JSONL_IO_LOCKS_GUARD = threading.Lock()
JSONL_IO_LOCKS: dict[str, threading.RLock] = {}
OPERATIONAL_SNAPSHOT_LOCK = threading.Lock()
OPERATIONAL_SNAPSHOT_SEQUENCE = 0


def _new_operational_snapshot(
    source_component: str,
    *,
    ttl_seconds: int = 15,
) -> dict[str, object]:
    """Create one identity for every state record assembled for the same screen."""
    global OPERATIONAL_SNAPSHOT_SEQUENCE
    now = datetime.now(ZoneInfo("Asia/Seoul"))
    with OPERATIONAL_SNAPSHOT_LOCK:
        OPERATIONAL_SNAPSHOT_SEQUENCE += 1
        sequence_number = OPERATIONAL_SNAPSHOT_SEQUENCE
    seed = (
        f"{source_component}|{now.isoformat(timespec='microseconds')}|"
        f"{os.getpid()}|{sequence_number}"
    )
    snapshot_id = "ops-" + hashlib.sha256(seed.encode("utf-8")).hexdigest()[:20]
    return {
        "recorded_at": now.isoformat(timespec="seconds"),
        "snapshot_id": snapshot_id,
        "source_component": str(source_component or "unknown"),
        "sequence_number": sequence_number,
        "expires_at": (
            now + timedelta(seconds=max(0, int(ttl_seconds or 0)))
        ).isoformat(timespec="seconds"),
    }


def _jsonl_io_lock(path: Path) -> threading.RLock:
    try:
        key = str(path.resolve())
    except OSError:
        key = str(path.absolute())
    with JSONL_IO_LOCKS_GUARD:
        return JSONL_IO_LOCKS.setdefault(key, threading.RLock())


def _runtime_file(name: str) -> Path:
    target = USER_DATA_ROOT / name
    legacy = LEGACY_DATA_ROOT / name
    if target != legacy and not target.exists() and legacy.is_file():
        try:
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(legacy, target)
        except OSError:
            return legacy
    return target


def _runtime_directory(*parts: str) -> Path:
    target = USER_DATA_ROOT.joinpath(*parts)
    legacy = LEGACY_DATA_ROOT.joinpath(*parts)
    if target.exists() or not legacy.exists() or target == legacy:
        target.mkdir(parents=True, exist_ok=True)
        return target
    return legacy


def _read_internal_developer_json(path: Path) -> dict[str, object]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _internal_developer_records(root: Path, group: str, limit: int = 50) -> list[dict[str, object]]:
    directory = root / group
    if not directory.is_dir():
        return []
    rows = [
        row
        for path in directory.glob("*.json")
        if (row := _read_internal_developer_json(path))
    ]
    rows.sort(
        key=lambda row: str(
            row.get("updated_at")
            or row.get("created_at")
            or row.get("received_at")
            or ""
        ),
        reverse=True,
    )
    return rows[: max(1, min(int(limit), 100))]


def _internal_developer_age_seconds(value: object, now: datetime) -> float | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return max(0.0, (now - parsed.astimezone(timezone.utc)).total_seconds())


def build_internal_developer_launcher_status(
    root: Path | None = None,
    *,
    now: datetime | None = None,
) -> dict[str, object]:
    """Build a small, read-only launcher status from the internal developer ledger."""
    store_root = (root or INTERNAL_DEVELOPER_ROOT).resolve()
    now_utc = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    heartbeat = _read_internal_developer_json(store_root / "service_heartbeat.json")
    incidents = _internal_developer_records(store_root, "incidents", limit=100)
    advice = _internal_developer_records(store_root, "advice", limit=50)
    reports = _internal_developer_records(store_root, "reports", limit=50)
    open_states = {
        "NEW",
        "DIAGNOSING",
        "AUTO_RECOVERING",
        "RECOVERY_FAILED",
        "NEEDS_EXTERNAL_ADVICE",
        "ADVICE_RECEIVED",
        "RETRYING",
        "NEEDS_CODE_FIX",
        "WAITING_FOR_RESTART",
    }
    open_incidents = [row for row in incidents if str(row.get("state") or "") in open_states]

    def is_drill(row: dict[str, object]) -> bool:
        diagnostic = row.get("diagnostic") if isinstance(row.get("diagnostic"), dict) else {}
        return diagnostic.get("drill") is True or diagnostic.get("actual_failure") is False

    drill_incidents = [row for row in open_incidents if is_drill(row)]
    real_incidents = [row for row in open_incidents if not is_drill(row)]
    recovered_incidents = [
        row
        for row in incidents
        if str(row.get("state") or "") == "RECOVERED_UNREVIEWED" and not is_drill(row)
    ]
    latest_recovery = recovered_incidents[0] if recovered_incidents else {}
    accepted_advice = next(
        (row for row in advice if str(row.get("status") or "") == "ACCEPTED_AS_GUIDANCE"),
        {},
    )
    latest_report = reports[0] if reports else {}
    paid_advisor = PaidAdvisorGate(store_root).status(limit=5)
    heartbeat_age = _internal_developer_age_seconds(heartbeat.get("updated_at"), now_utc)
    heartbeat_fresh = heartbeat_age is not None and heartbeat_age <= 180
    advice_age = _internal_developer_age_seconds(
        accepted_advice.get("updated_at") or accepted_advice.get("received_at"),
        now_utc,
    )
    recent_advice = bool(accepted_advice) and advice_age is not None and advice_age <= 86400
    heartbeat_status = str(heartbeat.get("status") or "").strip().lower()
    observing_statuses = {
        "app_unreachable_observing",
        "diagnostic_endpoint_observing",
    }

    if not heartbeat:
        tone = "offline"
        status = "OFFLINE"
        label = "감시자 연결 확인"
        message = "내부 개발자 생존 신호가 없습니다. 텔레그램 보고와 감시 작업을 확인해야 합니다."
    elif not heartbeat_fresh:
        tone = "warning"
        status = "STALE"
        label = "감시 응답 지연"
        message = "내부 개발자 생존 신호가 3분 이상 갱신되지 않았습니다."
    elif real_incidents:
        tone = "danger"
        status = "INCIDENT"
        label = f"기능 이상 {len(real_incidents)}건"
        message = str(real_incidents[0].get("summary") or "내부 개발자가 이상을 감지했습니다.")
    elif heartbeat_status in observing_statuses:
        tone = "warning"
        status = "OBSERVING"
        label = "일시 지연 재확인 중"
        message = "아직 장애 기준에는 못 미쳤으며 내부 개발자가 다음 주기에 같은 기능을 다시 확인합니다."
    elif latest_recovery:
        tone = "recovered"
        status = "RECOVERED"
        label = "기능 정상 · 복구 검증 완료"
        message = "내부 개발자가 연속 정상 주기를 확인해 실제 장애를 복구 상태로 전환했습니다."
    elif recent_advice:
        tone = "recovered"
        status = "RECOVERED"
        label = "GPT 자문 반영 확인"
        message = "자문이 안전정책을 통과했고 내부 개발자가 결과를 다시 검증했습니다."
    else:
        tone = "healthy"
        status = "HEALTHY"
        label = "전체 기능 정상"
        message = "내부 개발자가 정상 감시 중이며 현재 실제 장애는 없습니다."

    advice_payload = (
        accepted_advice.get("advice")
        if isinstance(accepted_advice.get("advice"), dict)
        else {}
    )
    current_row = real_incidents[0] if real_incidents else {}
    current_state = str(current_row.get("state") or "").upper()
    current_diagnostic = (
        current_row.get("diagnostic")
        if isinstance(current_row.get("diagnostic"), dict)
        else {}
    )
    current_evidence = (
        current_diagnostic.get("evidence")
        if isinstance(current_diagnostic.get("evidence"), dict)
        else {}
    )
    stage_by_state = {
        "NEW": (1, "이상 감지", "새 사건을 원장에 기록했습니다."),
        "DIAGNOSING": (2, "원인 진단 중", "증거와 영향 범위를 확인하고 있습니다."),
        "AUTO_RECOVERING": (3, "안전 복구 중", "허용된 저위험 복구만 실행하고 있습니다."),
        "RECOVERY_FAILED": (3, "자동복구 실패", "안전 경계를 넘지 않고 외부 자문을 준비합니다."),
        "NEEDS_EXTERNAL_ADVICE": (3, "외부 자문 대기", "보고서를 저장했고 GPT 또는 개발자 자문을 기다립니다."),
        "ADVICE_RECEIVED": (3, "자문 안전검사", "받은 자문에서 위험한 지시를 격리하고 있습니다."),
        "RETRYING": (4, "재검증 중", "조치 후 같은 기능을 다시 점검하고 있습니다."),
        "NEEDS_CODE_FIX": (3, "코드 수정 필요", "자동수리 범위를 넘어 개발자 검토가 필요합니다."),
        "WAITING_FOR_RESTART": (4, "재시작 반영 대기", "안전한 재시작 뒤 정상 여부를 다시 확인합니다."),
    }
    stage_number, stage_label, stage_detail = stage_by_state.get(
        current_state,
        (5, "정상 감시", "현재 실제 장애 없이 다음 주기를 감시하고 있습니다."),
    )
    if not current_row and heartbeat_status == "app_unreachable_observing":
        stage_number = 1
        stage_label = "본체 응답 재확인 중"
        stage_detail = "일시 미응답 1회를 관찰했습니다. 5회 연속일 때만 실제 장애로 올립니다."
    elif not current_row and heartbeat_status == "diagnostic_endpoint_observing":
        stage_number = 2
        stage_label = "진단 응답 재확인 중"
        stage_detail = "진단 지연 1회를 관찰했습니다. 3회 연속일 때만 실제 장애로 올립니다."
    if current_state == "NEEDS_EXTERNAL_ADVICE" and heartbeat.get("status") == "healthy":
        stage_number = 4
        stage_label = "정상 복귀 재검증 중"
        stage_detail = "사이드카는 다시 정상이며 사건 종료에 필요한 연속 정상 주기를 확인하고 있습니다."
    workflow_steps = [
        "이상 감지",
        "원인 진단",
        "안전 조치·자문",
        "재검증",
        "완료",
    ]
    workflow_active = bool(current_row) or heartbeat_status in observing_statuses
    workflow = {
        "active_step": stage_number,
        "total_steps": len(workflow_steps),
        "progress_percent": stage_number * 20 if workflow_active else 100,
        "label": stage_label,
        "detail": stage_detail,
        "last_activity_at": (
            heartbeat.get("updated_at")
            or current_row.get("updated_at")
            or current_row.get("created_at")
        ),
        "steps": [
            {
                "number": index,
                "label": step,
                "status": (
                    "completed"
                    if not workflow_active or index < stage_number
                    else "active"
                    if index == stage_number
                    else "pending"
                ),
            }
            for index, step in enumerate(workflow_steps, start=1)
        ],
    }
    history: list[dict[str, object]] = []
    for row in incidents[:4]:
        history.append(
            {
                "type": "incident",
                "id": row.get("incident_id"),
                "status": row.get("state"),
                "at": row.get("updated_at") or row.get("created_at"),
                "summary": row.get("summary"),
                "drill": is_drill(row),
            }
        )
    for row in advice[:3]:
        nested = row.get("advice") if isinstance(row.get("advice"), dict) else {}
        history.append(
            {
                "type": "advice",
                "id": row.get("advice_id"),
                "status": row.get("status"),
                "at": row.get("updated_at") or row.get("received_at"),
                "summary": nested.get("summary"),
                "drill": False,
            }
        )
    history.sort(key=lambda row: str(row.get("at") or ""), reverse=True)
    return {
        "ok": True,
        "schema": "codexstock.internal-developer-launcher-status.v1",
        "generated_at": now_utc.isoformat(timespec="seconds"),
        "status": status,
        "tone": tone,
        "label": label,
        "message": message,
        "heartbeat": {
            "fresh": heartbeat_fresh,
            "age_seconds": round(heartbeat_age, 1) if heartbeat_age is not None else None,
            "updated_at": heartbeat.get("updated_at"),
            "status": heartbeat.get("status"),
            "phase": heartbeat.get("phase"),
            "cycle_count": heartbeat.get("cycle_count"),
        },
        "counts": {
            "real_open_incidents": len(real_incidents),
            "drill_open_incidents": len(drill_incidents),
            "incidents": len(incidents),
            "advice": len(advice),
            "reports": len(reports),
        },
        "current_incident": {
            "id": real_incidents[0].get("incident_id"),
            "state": real_incidents[0].get("state"),
            "classification": real_incidents[0].get("classification"),
            "component": real_incidents[0].get("component"),
            "summary": real_incidents[0].get("summary"),
            "reason": (
                "상태 파일을 교체 저장하던 순간 Windows 파일 잠금이 겹쳤습니다."
                if str(current_evidence.get("error_type") or "") == "PermissionError"
                else current_evidence.get("error")
            ),
            "updated_at": real_incidents[0].get("updated_at")
            or real_incidents[0].get("created_at"),
        }
        if real_incidents
        else None,
        "latest_recovery": {
            "id": latest_recovery.get("incident_id"),
            "classification": latest_recovery.get("classification"),
            "summary": latest_recovery.get("summary"),
            "updated_at": latest_recovery.get("updated_at")
            or latest_recovery.get("created_at"),
        }
        if latest_recovery
        else None,
        "workflow": workflow,
        "latest_advice": {
            "id": accepted_advice.get("advice_id"),
            "incident_id": accepted_advice.get("incident_id"),
            "status": accepted_advice.get("status"),
            "advisor": advice_payload.get("advisor"),
            "summary": advice_payload.get("summary"),
            "updated_at": accepted_advice.get("updated_at") or accepted_advice.get("received_at"),
        }
        if accepted_advice
        else None,
        "latest_report": {
            "id": latest_report.get("report_id"),
            "incident_id": latest_report.get("incident_id"),
            "status": latest_report.get("review_status"),
            "updated_at": latest_report.get("updated_at") or latest_report.get("created_at"),
        }
        if latest_report
        else None,
        "history": history[:6],
        "paid_advisor": paid_advisor,
        "safety": "읽기 전용 표시입니다. 주문, 코드 수정, 보안 설정 변경을 실행하지 않습니다.",
    }


