def _knowledge_curator_source_paths(
    max_files: int = 200,
    *,
    include_archives: bool = False,
) -> list[Path]:
    """Return bounded, evidence-bearing sources without entering caches or secrets."""
    safe_limit = max(20, min(int(max_files), 2_000))
    cache_key = (bool(include_archives), safe_limit)
    cache_ttl = 300.0 if include_archives else 30.0
    with _KNOWLEDGE_CURATOR_SOURCE_CACHE_LOCK:
        cached = _KNOWLEDGE_CURATOR_SOURCE_CACHE.get(cache_key)
        if cached and time.monotonic() - cached[0] < cache_ttl:
            return list(cached[1])
    candidates = [USER_DATA_ROOT / name for name in KNOWLEDGE_CURATOR_CORE_FILES]
    if include_archives:
        candidates.extend(USER_DATA_ROOT / name for name in KNOWLEDGE_CURATOR_ARCHIVE_FILES)
        if OBSIDIAN_VAULT.is_dir():
            for directory_name in KNOWLEDGE_CURATOR_ARCHIVE_VAULT_DIRS:
                directory = OBSIDIAN_VAULT / directory_name
                if not directory.is_dir():
                    continue
                recent = sorted(
                    directory.rglob("*.md"),
                    key=lambda path: path.stat().st_mtime_ns,
                    reverse=True,
                )[:50]
                candidates.extend(recent)
    for knowledge_name in (
        "research", "meeting", "review", "replay", "learning",
        "strategy", "journal", "memory", "evidence",
    ):
        candidates.extend(USER_DATA_ROOT.glob(f"*{knowledge_name}*.sqlite"))
        candidates.extend(USER_DATA_ROOT.glob(f"*{knowledge_name}*.sqlite3"))
        candidates.extend(USER_DATA_ROOT.glob(f"*{knowledge_name}*.db"))
    excluded_parts = {"secrets", "cache", "caches", "tokens", "credentials"}
    maximum_size = 96 * 1024 * 1024 if include_archives else 64 * 1024 * 1024
    byte_budget = 384 * 1024 * 1024 if include_archives else 192 * 1024 * 1024
    filtered: list[Path] = []
    seen: set[str] = set()
    used_bytes = 0
    for path in candidates:
        normalized = str(path.resolve()) if path.exists() else str(path)
        if normalized in seen or not path.is_file():
            continue
        seen.add(normalized)
        size = int(path.stat().st_size)
        if any(part.lower() in excluded_parts for part in path.parts):
            continue
        if size > maximum_size or used_bytes + size > byte_budget:
            continue
        filtered.append(path)
        used_bytes += size
        if len(filtered) >= safe_limit:
            break
    with _KNOWLEDGE_CURATOR_SOURCE_CACHE_LOCK:
        _KNOWLEDGE_CURATOR_SOURCE_CACHE[cache_key] = (time.monotonic(), list(filtered))
    return filtered


def _compute_knowledge_curator_status() -> dict[str, object]:
    # Dashboard reads must not import specialist packages or contact Ollama.
    # The scheduler owns active dependency probes; this endpoint reads its cache.
    status = KNOWLEDGE_CURATOR.engine_status(refresh_runtime_probes=False)
    scheduler = globals().get("KNOWLEDGE_CURATOR_SCHEDULER")
    status["scheduler"] = scheduler.status() if scheduler is not None else {
        "running": False,
        "thread_alive": False,
        "state": "not_initialized",
    }
    status["discoverable_source_count"] = len(_knowledge_curator_source_paths())
    status["archive_source_count"] = len(_knowledge_curator_source_paths(include_archives=True))
    status["source_policy"] = {
        "core": "회의·복기·학습·후보판 원장은 60초 감시하며 JSONL 추가분만 읽습니다.",
        "archive": "과거 리그·대규모 연구·선별 문서는 상시 주기에서 제외하고 휴장일 명시적 배치로만 읽습니다.",
        "sqlite": "연구·복기 테이블만 읽기 전용으로 투영하고 계좌·토큰·주문 테이블은 제외합니다.",
    }
    status["source_policy"] = {
        "core": "회의·복기·학습·후보 원장을 60초마다 감시하며 JSONL의 추가분만 읽습니다.",
        "archive": "과거 리그·대규모 연구·훈련 문서는 상시 주기에서 제외하고 휴장일 명시적 배치에서만 읽습니다.",
        "sqlite": "연구·복기 지식 테이블만 읽기 전용으로 사용하며 계좌·인증·주문 테이블은 제외합니다.",
    }
    status["source_roots"] = [str(USER_DATA_ROOT), str(OBSIDIAN_VAULT)]
    status["safety"] = "Search projections are read-only; source ledgers and live-order paths are never modified."
    return status


def _refresh_knowledge_curator_status_cache() -> dict[str, object]:
    global _KNOWLEDGE_CURATOR_STATUS_CACHE
    global _KNOWLEDGE_CURATOR_STATUS_CACHE_AT
    global _KNOWLEDGE_CURATOR_STATUS_REFRESHING
    try:
        payload = _compute_knowledge_curator_status()
        payload["status_cache"] = {
            "cached": True,
            "refresh_in_progress": False,
            "age_seconds": 0.0,
        }
        with _KNOWLEDGE_CURATOR_STATUS_CACHE_LOCK:
            _KNOWLEDGE_CURATOR_STATUS_CACHE = copy.deepcopy(payload)
            _KNOWLEDGE_CURATOR_STATUS_CACHE_AT = time.monotonic()
        return payload
    finally:
        with _KNOWLEDGE_CURATOR_STATUS_CACHE_LOCK:
            _KNOWLEDGE_CURATOR_STATUS_REFRESHING = False


def _start_knowledge_curator_status_refresh() -> None:
    global _KNOWLEDGE_CURATOR_STATUS_REFRESHING
    with _KNOWLEDGE_CURATOR_STATUS_CACHE_LOCK:
        if _KNOWLEDGE_CURATOR_STATUS_REFRESHING:
            return
        _KNOWLEDGE_CURATOR_STATUS_REFRESHING = True
    timer = threading.Timer(0.01, _refresh_knowledge_curator_status_cache)
    timer.name = "knowledge-curator-status-refresh"
    timer.daemon = True
    timer.start()


def build_knowledge_curator_status() -> dict[str, object]:
    with _KNOWLEDGE_CURATOR_STATUS_CACHE_LOCK:
        cached = copy.deepcopy(_KNOWLEDGE_CURATOR_STATUS_CACHE)
        cached_at = float(_KNOWLEDGE_CURATOR_STATUS_CACHE_AT)
        refreshing = bool(_KNOWLEDGE_CURATOR_STATUS_REFRESHING)
    if not cached:
        return _refresh_knowledge_curator_status_cache()
    age_seconds = max(0.0, time.monotonic() - cached_at)
    scheduler = globals().get("KNOWLEDGE_CURATOR_SCHEDULER")
    if scheduler is not None:
        cached["scheduler"] = scheduler.status()
    cached["status_cache"] = {
        "cached": True,
        "refresh_in_progress": refreshing,
        "age_seconds": round(age_seconds, 3),
    }
    if age_seconds >= KNOWLEDGE_CURATOR_STATUS_CACHE_TTL_SECONDS and not refreshing:
        _start_knowledge_curator_status_refresh()
        cached["status_cache"]["refresh_in_progress"] = True
    return cached


KNOWLEDGE_CURATOR_SCHEDULER = KnowledgeCuratorScheduler(
    KNOWLEDGE_CURATOR,
    lambda: _knowledge_curator_source_paths(
        max_files=200,
        # Keep the always-on employee lightweight. Archive/replay corpora are
        # admitted only through the explicit holiday batch API, where they can be
        # observed and stopped independently instead of blocking a 60-second cycle.
        include_archives=False,
    ),
    lambda: bool(build_operating_focus().get("market_open")),
    lambda: bool(build_operating_focus().get("large_batch_jobs_allowed")),
)
# Seed an immediate status snapshot before the scheduler can start indexing.
_refresh_knowledge_curator_status_cache()

