def fetch_us_universe(timeout: float = 4.0) -> list[dict[str, str]]:
    urls = [
        "https://www.nasdaqtrader.com/dynamic/SymDir/nasdaqlisted.txt",
        "https://www.nasdaqtrader.com/dynamic/SymDir/otherlisted.txt",
    ]
    rows: list[dict[str, str]] = []
    for url in urls:
        request = Request(url, headers={"User-Agent": "QuantStudioHTS/1.0"})
        with urlopen(request, timeout=timeout) as response:
            text = response.read().decode("utf-8", errors="replace")
        lines = [line for line in text.splitlines() if "|" in line and not line.startswith("File Creation Time")]
        headers = lines[0].split("|")
        for line in lines[1:]:
            values = line.split("|")
            data = dict(zip(headers, values))
            symbol = (data.get("Symbol") or data.get("ACT Symbol") or "").strip()
            name = (data.get("Security Name") or data.get("Company Name") or symbol).strip()
            test_issue = (data.get("Test Issue") or "N").strip().upper()
            if not symbol or test_issue == "Y":
                continue
            rows.append({"symbol": symbol.replace("^", "."), "name": name, "market": "US", "choseong": symbol.upper()})
    return rows


def fetch_krx_work_date(timeout: float = 4.0) -> str:
    url = "http://data.krx.co.kr/comm/bldAttendant/executeForResourceBundle.cmd?baseName=krx.mdc.i18n.component&key=B128.bld"
    request = Request(
        url,
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
            "Referer": "https://data.krx.co.kr/contents/MDC/MDI/outerLoader/index.cmd",
        },
    )
    with urlopen(request, timeout=timeout) as response:
        data = json.loads(response.read().decode("utf-8", errors="replace"))
    raw = data["result"]["output"][0]["max_work_dt"]
    return f"{raw[:4]}-{raw[4:6]}-{raw[6:8]}"


def fetch_kr_universe(timeout: float = 8.0) -> list[dict[str, str]]:
    work_date = fetch_krx_work_date()
    url = f"https://raw.githubusercontent.com/FinanceData/fdr_krx_data_cache/refs/heads/master/data/listing/krx/{work_date}.csv"
    request = Request(url, headers={"User-Agent": "QuantStudioHTS/1.0"})
    with urlopen(request, timeout=timeout) as response:
        text = response.read().decode("utf-8-sig", errors="replace")
    rows: list[dict[str, str]] = []
    market_map = {"KOSPI": "KR-KOSPI", "KOSDAQ": "KR-KOSDAQ", "KONEX": "KR-KONEX"}
    for row in csv.DictReader(io.StringIO(text)):
        code = (row.get("Code") or "").strip().zfill(6)
        name = (row.get("Name") or "").strip()
        market = market_map.get((row.get("Market") or "").strip(), "KR")
        if not code or not name or code == "000000":
            continue
        rows.append(
            {
                "symbol": code,
                "name": name,
                "market": market,
                "choseong": name,
                "source": f"KRX-{work_date}",
            }
        )
    return rows


def _number(value: object) -> float:
    text = str(value or "").replace(",", "").replace("%", "").strip()
    if not text or text == "-":
        return 0.0
    try:
        return float(text)
    except ValueError:
        return 0.0


def _format_krw(value: object) -> str:
    return f"{_number(value):,.0f}원"


def _safe_pct(value: object, digits: int = 2) -> str:
    return f"{_number(value):+.{digits}f}%"


def build_delegated_live_authorization(
    policy: dict[str, object] | None = None,
    target_date: str | None = None,
) -> dict[str, object]:
    """Keep standing allocation settings separate from a trading-day order authorization."""
    try:
        policy = policy if isinstance(policy, dict) else OPS.autotrade_policy()
    except Exception:
        policy = {}
    return _build_delegated_authorization(
        policy,
        trading_date=str(target_date or today_kst()).strip(),
    )


def build_delegated_live_capital_policy(policy: dict[str, object] | None = None) -> dict[str, object]:
    """Summarize delegated live allocation settings without changing order permissions."""
    try:
        policy = policy if isinstance(policy, dict) else OPS.autotrade_policy()
    except Exception:
        policy = {}
    auto_pct = max(0.0, min(_number(policy.get("delegated_live_auto_submit_max_cash_pct", policy.get("live_pilot_max_cash_pct", 30.0))), 100.0))
    approval_pct = max(0.0, min(_number(policy.get("delegated_live_user_approval_above_cash_pct", 50.0)), 100.0))
    pilot_pct = max(0.0, min(_number(policy.get("live_pilot_max_cash_pct", 10.0)), 100.0))
    dynamic_pct = max(0.0, min(_number(policy.get("live_pilot_dynamic_max_cash_pct", policy.get("live_pilot_max_cash_pct", 50.0))), 100.0))
    target_symbol_count = max(1, int(_number(policy.get("delegated_live_min_buy_symbols_per_day", 1)) or 1))
    max_position_pct = max(
        0.0,
        min(_number(policy.get("delegated_live_max_position_cash_pct", pilot_pct)), 100.0),
    )
    max_configured_pct = max(auto_pct, approval_pct, pilot_pct, dynamic_pct)
    execution_mode = build_execution_mode_contract(policy)
    delegated_enabled = bool(execution_mode.get("delegated"))
    authorization = build_delegated_live_authorization(policy)
    live_pilot_enabled = bool(policy.get("live_pilot_enabled", False))
    live_execution_enabled = bool(policy.get("live_execution_enabled", False))
    require_approval = bool(execution_mode.get("requires_user_approval", True))
    if max_configured_pct >= 80.0:
        risk_level = "high"
        warning = "80% 이상 고위험 자금 설정입니다. 실전 전송 전 사용자 확인과 리스크 게이트가 필요합니다."
    elif max_configured_pct >= 50.0:
        risk_level = "elevated"
        warning = "50% 이상 적극 운용 설정입니다. 후보 검증, 승인, 중복주문 차단을 유지해야 합니다."
    elif max_configured_pct > 0.0:
        risk_level = "normal"
        warning = "설정된 자금 한도 안에서만 후보 수량을 계산합니다."
    else:
        risk_level = "off"
        warning = "자금 한도가 0%라 실전 후보 수량을 만들 수 없습니다."
    if not execution_mode.get("policy_consistent"):
        authority = "execution_mode_conflict"
        message = "실행 모드 정책 플래그가 충돌해 실전 전송을 차단합니다."
    elif not delegated_enabled:
        authority = "delegated_off"
        message = "위임 자동운용 OFF: 연구, Paper, 후보 감시는 가능하지만 AI가 스스로 실전 주문을 전송하지 않습니다."
    elif not authorization.get("valid_today"):
        authority = "daily_authorization_required"
        message = str(authorization.get("message", "오늘 실전 위임 최종 지시가 없어 실제 주문을 차단합니다."))
    elif not live_pilot_enabled or not live_execution_enabled:
        authority = "live_switch_off"
        message = "위임 자동운용 ON이어도 실전 파일럿/전송 스위치가 꺼져 있어 브로커 주문은 차단됩니다."
    elif require_approval:
        authority = "approval_gate"
        message = "위임 자동운용 ON: 자금 한도 안에서 후보를 만들되 승인/dry-submit/중복/시장시간 게이트를 통과해야 합니다."
    else:
        authority = "signed_executor_gate"
        message = "위임 자동운용 ON: 개별 승인을 기다리지 않고 서명 신호와 독립 실행기 안전 게이트를 적용합니다."
    return {
        "enabled": delegated_enabled,
        "authorization": authorization,
        "authority": authority,
        "risk_level": risk_level,
        "warning": warning,
        "message": message,
        "auto_submit_max_cash_pct": round(auto_pct, 2),
        "user_approval_above_cash_pct": round(approval_pct, 2),
        "live_pilot_max_cash_pct": round(pilot_pct, 2),
        "dynamic_max_cash_pct": round(dynamic_pct, 2),
        "target_symbol_count": target_symbol_count,
        "max_position_cash_pct": round(max_position_pct, 2),
        "distinct_symbols_required": target_symbol_count > 1,
        "max_configured_cash_pct": round(max_configured_pct, 2),
        "requires_user_approval": require_approval,
        "live_pilot_enabled": live_pilot_enabled,
        "live_execution_enabled": live_execution_enabled,
        "execution_mode_contract": execution_mode,
        "safety": "이 스냅샷은 상태 표시/수량 계산 정책입니다. 호출만으로 실제 주문을 실행하지 않습니다.",
    }


def _round_float(value: object, digits: int = 1) -> float:
    try:
        return round(float(value), digits)
    except (TypeError, ValueError):
        return 0.0


def _windows_memory_status() -> dict[str, float]:
    if sys.platform != "win32":
        return {}

    class MemoryStatusEx(ctypes.Structure):
        _fields_ = [
            ("dwLength", ctypes.c_ulong),
            ("dwMemoryLoad", ctypes.c_ulong),
            ("ullTotalPhys", ctypes.c_ulonglong),
            ("ullAvailPhys", ctypes.c_ulonglong),
            ("ullTotalPageFile", ctypes.c_ulonglong),
            ("ullAvailPageFile", ctypes.c_ulonglong),
            ("ullTotalVirtual", ctypes.c_ulonglong),
            ("ullAvailVirtual", ctypes.c_ulonglong),
            ("ullAvailExtendedVirtual", ctypes.c_ulonglong),
        ]

    status = MemoryStatusEx()
    status.dwLength = ctypes.sizeof(MemoryStatusEx)
    if not ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(status)):
        return {}
    total_gb = status.ullTotalPhys / (1024 ** 3)
    available_gb = status.ullAvailPhys / (1024 ** 3)
    payload = {
        "total_gb": _round_float(total_gb, 2),
        "available_gb": _round_float(available_gb, 2),
        "used_pct": _round_float(status.dwMemoryLoad, 1),
    }
    return payload


def _windows_process_memory() -> dict[str, float]:
    if sys.platform != "win32":
        return {}

    class ProcessMemoryCounters(ctypes.Structure):
        _fields_ = [
            ("cb", ctypes.c_ulong),
            ("PageFaultCount", ctypes.c_ulong),
            ("PeakWorkingSetSize", ctypes.c_size_t),
            ("WorkingSetSize", ctypes.c_size_t),
            ("QuotaPeakPagedPoolUsage", ctypes.c_size_t),
            ("QuotaPagedPoolUsage", ctypes.c_size_t),
            ("QuotaPeakNonPagedPoolUsage", ctypes.c_size_t),
            ("QuotaNonPagedPoolUsage", ctypes.c_size_t),
            ("PagefileUsage", ctypes.c_size_t),
            ("PeakPagefileUsage", ctypes.c_size_t),
            ("PrivateUsage", ctypes.c_size_t),
        ]

    counters = ProcessMemoryCounters()
    counters.cb = ctypes.sizeof(ProcessMemoryCounters)
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    psapi = ctypes.WinDLL("psapi", use_last_error=True)
    kernel32.GetCurrentProcess.restype = ctypes.c_void_p
    psapi.GetProcessMemoryInfo.argtypes = [ctypes.c_void_p, ctypes.POINTER(ProcessMemoryCounters), ctypes.c_ulong]
    psapi.GetProcessMemoryInfo.restype = ctypes.c_int
    handle = kernel32.GetCurrentProcess()
    ok = psapi.GetProcessMemoryInfo(handle, ctypes.byref(counters), counters.cb)
    if not ok:
        return {}
    return {
        "working_set_mb": _round_float(counters.WorkingSetSize / (1024 ** 2), 1),
        "private_mb": _round_float(counters.PrivateUsage / (1024 ** 2), 1),
        "peak_working_set_mb": _round_float(counters.PeakWorkingSetSize / (1024 ** 2), 1),
    }


def _process_cpu_percent() -> float:
    now_wall = time.perf_counter()
    now_process = time.process_time()
    with SYSTEM_RESOURCE_LOCK:
        last_wall = float(SYSTEM_RESOURCE_SAMPLE.get("wall", now_wall))
        last_process = float(SYSTEM_RESOURCE_SAMPLE.get("process", now_process))
        SYSTEM_RESOURCE_SAMPLE["wall"] = now_wall
        SYSTEM_RESOURCE_SAMPLE["process"] = now_process
    wall_delta = max(0.001, now_wall - last_wall)
    process_delta = max(0.0, now_process - last_process)
    cpu_count = max(1, os.cpu_count() or 1)
    return _round_float((process_delta / (wall_delta * cpu_count)) * 100, 1)


def build_system_resources() -> dict[str, object]:
    disk = shutil.disk_usage(REPO_ROOT)
    disk_total_gb = disk.total / (1024 ** 3)
    disk_free_gb = disk.free / (1024 ** 3)
    disk_used_pct = ((disk.total - disk.free) / disk.total) * 100 if disk.total else 0.0
    memory = _windows_memory_status()
    process_memory = _windows_process_memory()
    app_cpu_pct = _process_cpu_percent()
    memory_used_pct = float(memory.get("used_pct", 0) or 0)
    app_memory_mb = float(process_memory.get("working_set_mb", 0) or 0)

    level = "ok"
    label = "여유"
    reasons: list[str] = []
    if memory_used_pct >= 92 or disk_free_gb < 2:
        level = "danger"
        label = "부족"
    elif memory_used_pct >= 82 or disk_free_gb < 10 or app_memory_mb >= 3072 or app_cpu_pct >= 75:
        level = "warning"
        label = "주의"

    if memory:
        reasons.append(f"RAM {memory_used_pct:.0f}% 사용")
        if float(memory.get("available_gb", 0) or 0) < 4:
            reasons.append("AI 모델 실행 여유 RAM이 적음")
    else:
        reasons.append("RAM 상세 조회 대기")
    reasons.append(f"디스크 여유 {disk_free_gb:.1f}GB")
    if app_memory_mb:
        reasons.append(f"앱 메모리 {app_memory_mb:.0f}MB")

    return {
        "ok": level == "ok",
        "level": level,
        "label": label,
        "message": " · ".join(reasons),
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "app": {
            "pid": os.getpid(),
            "memory_mb": app_memory_mb,
            "private_memory_mb": process_memory.get("private_mb", 0),
            "peak_memory_mb": process_memory.get("peak_working_set_mb", 0),
            "cpu_pct": app_cpu_pct,
            "threads": threading.active_count(),
            "uptime_seconds": int(time.time() - SERVER_STARTED_AT),
        },
        "system": {
            "cpu_count": os.cpu_count() or 1,
            "memory_total_gb": memory.get("total_gb", 0),
            "memory_available_gb": memory.get("available_gb", 0),
            "memory_used_pct": memory_used_pct,
            "disk_total_gb": _round_float(disk_total_gb, 1),
            "disk_free_gb": _round_float(disk_free_gb, 1),
            "disk_used_pct": _round_float(disk_used_pct, 1),
        },
    }


def build_python_thread_activity(limit: int = 80) -> dict[str, object]:
    """Expose local worker names and code locations without frame variables."""
    frames = sys._current_frames()
    rows: list[dict[str, object]] = []
    for thread in threading.enumerate()[: max(1, min(int(limit or 80), 200))]:
        frame = frames.get(thread.ident) if thread.ident is not None else None
        stack: list[dict[str, object]] = []
        while frame is not None and len(stack) < 8:
            code = frame.f_code
            stack.append(
                {
                    "file": str(Path(code.co_filename).resolve()),
                    "function": code.co_name,
                    "line": int(frame.f_lineno),
                }
            )
            frame = frame.f_back
        rows.append(
            {
                "name": thread.name,
                "ident": thread.ident,
                "native_id": thread.native_id,
                "alive": thread.is_alive(),
                "daemon": thread.daemon,
                "stack": stack,
            }
        )
    return {
        "ok": True,
        "schema": "codexstock_python_thread_activity_v1",
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(
            timespec="seconds"
        ),
        "process_id": os.getpid(),
        "thread_count": len(rows),
        "threads": rows,
        "variables_exposed": False,
        "live_order_allowed": False,
    }


def _repo_relative(path: Path) -> str:
    try:
        return str(path.relative_to(REPO_ROOT)).replace("\\", "/")
    except ValueError:
        return str(path)


def _path_is_within(path: Path, root: Path) -> bool:
    """Check lexical containment without following a symlink out of the tree."""
    try:
        path_text = os.path.normcase(os.path.abspath(os.fspath(path)))
        root_text = os.path.normcase(os.path.abspath(os.fspath(root)))
        return os.path.commonpath((path_text, root_text)) == root_text
    except (OSError, TypeError, ValueError):
        return False


def _env_example_value(text: str, key: str) -> str:
    match = re.search(rf"(?mi)^\s*{re.escape(key)}\s*=\s*([^#\r\n]*)", text or "")
    return match.group(1).strip().strip('"').strip("'") if match else ""


def _release_private_file_row(path: Path, label: str, *, root: Path | None = None) -> dict[str, object]:
    display_path = _repo_relative(path) if root is None else str(path.relative_to(root)).replace("\\", "/")
    try:
        size_bytes = path.stat().st_size if path.is_file() else 0
    except OSError:
        size_bytes = 0
    return {"path": display_path, "label": label, "size_bytes": size_bytes}


def _audit_release_dist_private_files(dist_path: Path) -> list[dict[str, object]]:
    if not dist_path.is_dir():
        return []
    findings: list[dict[str, object]] = []
    for path in sorted((item for item in dist_path.rglob("*") if item.is_file()), key=lambda item: str(item).lower()):
        if path.name.lower() == ".env.example":
            continue
        relative_parts = path.relative_to(dist_path).parts
        if relative_parts and relative_parts[0].lower() == "runtime":
            findings.append(_release_private_file_row(path, "runtime 폴더 파일", root=dist_path))
            continue
        if (
            relative_parts
            and relative_parts[0].lower() in {"data", "reports"}
            and path.name.lower() != "readme.txt"
        ):
            findings.append(_release_private_file_row(path, "배포본 런타임 데이터", root=dist_path))
            continue
        lowered = path.name.lower()
        matched = next(
            (pattern for pattern in FRIEND_RELEASE_DIST_PRIVATE_PATTERNS if fnmatch.fnmatch(lowered, pattern.lower())),
            "",
        )
        if not matched:
            continue
        findings.append(
            _release_private_file_row(
                path,
                f"배포 제외 패턴 {matched}",
                root=dist_path,
            )
        )
    return findings


def _read_text_if_exists(path: Path) -> str:
    if not path.is_file():
        return ""
    try:
        return path.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return ""


def _release_check(
    check_id: str,
    label: str,
    status: str,
    detail: str,
    action: str = "",
    path: Path | None = None,
) -> dict[str, object]:
    return {
        "id": check_id,
        "label": label,
        "status": status,
        "detail": detail,
        "action": action,
        "path": _repo_relative(path) if path else "",
    }


def build_friend_release_readiness() -> dict[str, object]:
    env_example_path = REPO_ROOT / ".env.example"
    env_example_text = _read_text_if_exists(env_example_path)
    gitignore_text = _read_text_if_exists(REPO_ROOT / ".gitignore")
    checks: list[dict[str, object]] = []

    missing_files: list[dict[str, object]] = []
    for rel_path, label in FRIEND_RELEASE_REQUIRED_FILES:
        path = REPO_ROOT / rel_path
        exists = path.is_file()
        if not exists:
            missing_files.append({"path": rel_path, "label": label})
        checks.append(
            _release_check(
                f"file:{rel_path}",
                label,
                "pass" if exists else "blocker",
                f"{rel_path} {'준비됨' if exists else '없음'}",
                "" if exists else "배포 전에 이 파일을 만들어야 합니다.",
                path,
            )
        )

    env_rows = []
    missing_env_keys: list[str] = []
    for key, label in FRIEND_RELEASE_ENV_KEYS:
        present = f"{key}=" in env_example_text
        env_rows.append({"key": key, "label": label, "present_in_example": present})
        if not present:
            missing_env_keys.append(key)
    checks.append(
        _release_check(
            "env-example",
            "API 설정 예시",
            "pass" if not missing_env_keys else "blocker",
            f"{len(FRIEND_RELEASE_ENV_KEYS) - len(missing_env_keys)}/{len(FRIEND_RELEASE_ENV_KEYS)}개 항목 준비",
            "" if not missing_env_keys else f".env.example에 누락된 키를 추가하세요: {', '.join(missing_env_keys[:6])}",
            env_example_path,
        )
    )

    private_files: list[dict[str, object]] = []
    runtime_private_files: list[dict[str, object]] = []
    seen_private: set[str] = set()
    for path, label in FRIEND_RELEASE_PRIVATE_PATHS:
        if path.exists():
            rel = _repo_relative(path)
            seen_private.add(rel)
            destination = private_files if _path_is_within(path, REPO_ROOT) else runtime_private_files
            destination.append(_release_private_file_row(path, label))
    for root, pattern, label in FRIEND_RELEASE_PRIVATE_GLOBS:
        if not root.exists():
            continue
        for path in sorted(root.glob(pattern)):
            rel = _repo_relative(path)
            if rel in seen_private:
                continue
            private_files.append(_release_private_file_row(path, label))
            seen_private.add(rel)

    checks.append(
        _release_check(
            "private-files",
            "개인 파일 분리",
            "blocker" if private_files else "pass",
            f"프로젝트 코드 폴더에서 개인 파일 {len(private_files)}개 발견" if private_files else "프로젝트 코드 폴더에 알려진 개인 파일이 없습니다.",
            "친구에게 이 폴더를 그대로 보내지 말고 .\\prepare_friend_release.ps1로 dist\\CodexStock-Friend 배포본을 만드세요." if private_files else "",
        )
    )
    checks.append(
        _release_check(
            "runtime-private-files",
            "개인 런타임 데이터 분리",
            "pass",
            f"개인 기록 {len(runtime_private_files)}개가 프로젝트 밖 사용자 데이터 폴더에 분리되어 있습니다.",
            "",
        )
    )

    missing_ignore = [pattern for pattern in FRIEND_RELEASE_GITIGNORE_PATTERNS if pattern not in gitignore_text]
    checks.append(
        _release_check(
            "gitignore",
            "비밀 파일 Git 제외",
            "pass" if not missing_ignore else "warning",
            f"{len(FRIEND_RELEASE_GITIGNORE_PATTERNS) - len(missing_ignore)}/{len(FRIEND_RELEASE_GITIGNORE_PATTERNS)}개 보호 패턴 준비",
            "" if not missing_ignore else f".gitignore에 누락된 보호 패턴을 추가하세요: {', '.join(missing_ignore[:6])}",
            REPO_ROOT / ".gitignore",
        )
    )

    settings = INTEGRATIONS.settings()
    live_unlocked = bool(settings.live_trading and not settings.kis_readonly and not settings.kis_use_mock)
    example_live_trading = _env_example_value(env_example_text, "LIVE_TRADING").lower()
    example_kis_readonly = _env_example_value(env_example_text, "KIS_READONLY").lower()
    safe_defaults = example_live_trading in {"false", "0", "no", "off"} and example_kis_readonly in {"true", "1", "yes", "on"}
    checks.append(
        _release_check(
            "safety-defaults",
            "기본 주문 안전장치",
            "pass" if safe_defaults else "warning",
            (
                "현재 설정은 실전 주문 기본 잠금 상태입니다."
                if safe_defaults
                else f".env.example 기본값: LIVE_TRADING={example_live_trading or '누락'}, KIS_READONLY={example_kis_readonly or '누락'}"
            ),
            ".env.example을 LIVE_TRADING=false, KIS_READONLY=true로 고치세요." if not safe_defaults else "",
        )
    )
    if live_unlocked:
        checks.append(
            _release_check(
                "local-live-runtime-separated",
                "개인 실전 설정 배포 제외",
                "pass",
                "현재 개인 런타임의 실전 설정은 켜져 있지만 .env/.env.local은 배포 대상에서 제외됩니다.",
                "",
            )
        )

    dist_path = REPO_ROOT / "dist" / "CodexStock-Friend"
    dist_exists = dist_path.exists()
    dist_private_files = _audit_release_dist_private_files(dist_path)
    checks.append(
        _release_check(
            "dist-package",
            "친구용 배포 폴더",
            "pass" if dist_exists else "warning",
            "dist/CodexStock-Friend 생성됨" if dist_exists else "아직 친구용 배포 폴더가 없습니다.",
            ".\\prepare_friend_release.ps1 실행 후 dist\\CodexStock-Friend 폴더를 확인하세요." if not dist_exists else "",
            dist_path,
        )
    )
    checks.append(
        _release_check(
            "dist-private-files",
            "배포본 개인 파일 감사",
            "blocker" if dist_private_files else "pass",
            (
                f"배포본에서 제외 대상 파일 {len(dist_private_files)}개를 발견했습니다."
                if dist_private_files
                else "배포본에서 알려진 개인 설정·주문·텔레그램·서버 로그 파일을 찾지 못했습니다."
                if dist_exists
                else "배포본 생성 후 자동 검사합니다."
            ),
            ".\\prepare_friend_release.ps1로 배포본을 다시 만든 뒤 재점검하세요." if dist_private_files else "",
            dist_path,
        )
    )

    blocker_count = len([item for item in checks if item.get("status") == "blocker"])
    warning_count = len([item for item in checks if item.get("status") == "warning"])
    score = max(0, min(100, 100 - blocker_count * 22 - warning_count * 7))
    ready = blocker_count == 0 and warning_count <= 1 and not private_files and not dist_private_files
    if blocker_count:
        status = "개인 설정 분리 필요"
    elif warning_count:
        status = "거의 준비됨"
    else:
        status = "배포 준비 완료"

    return {
        "ok": True,
        "ready": ready,
        "score": score,
        "status": status,
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "summary": {
            "checks": len(checks),
            "blockers": blocker_count,
            "warnings": warning_count,
            "private_files": len(private_files),
            "repo_private_files": len(private_files),
            "runtime_private_files": len(runtime_private_files),
            "dist_private_files": len(dist_private_files),
            "runtime_separation_ok": not private_files,
            "dist_privacy_ok": dist_exists and not dist_private_files,
            "missing_required_files": len(missing_files),
            "missing_env_keys": len(missing_env_keys),
            "dist_exists": dist_exists,
        },
        "checks": checks,
        "private_files": private_files[:30],
        "runtime_private_files": runtime_private_files[:30],
        "dist_private_files": dist_private_files[:30],
        "env_keys": env_rows,
        "release_command": ".\\prepare_friend_release.ps1",
        "output_dir": "dist\\CodexStock-Friend",
        "safety": "비밀값은 표시하지 않고 파일 존재 여부와 설정 키 이름만 점검합니다. 친구는 반드시 본인 API와 본인 계좌로 설정해야 합니다.",
    }


def fetch_kr_market_rows(timeout: float = 8.0) -> tuple[str, list[dict[str, object]]]:
    work_date = fetch_krx_work_date()
    url = f"https://raw.githubusercontent.com/FinanceData/fdr_krx_data_cache/refs/heads/master/data/listing/krx/{work_date}.csv"
    request = Request(url, headers={"User-Agent": "QuantStudioHTS/1.0"})
    with urlopen(request, timeout=timeout) as response:
        text = response.read().decode("utf-8-sig", errors="replace")
    rows: list[dict[str, object]] = []
    for row in csv.DictReader(io.StringIO(text)):
        code = (row.get("Code") or "").strip().zfill(6)
        name = (row.get("Name") or "").strip()
        market = (row.get("Market") or "KR").strip()
        if not code or not name or code == "000000":
            continue
        rows.append(
            {
                "symbol": code,
                "name": name,
                "market": market,
                "close": _number(row.get("Close")),
                "change": _number(row.get("Changes")),
                "change_pct": _number(row.get("ChagesRatio")),
                "open": _number(row.get("Open")),
                "high": _number(row.get("High")),
                "low": _number(row.get("Low")),
                "volume": _number(row.get("Volume")),
                "amount": _number(row.get("Amount")),
                "marcap": _number(row.get("Marcap")),
                "dept": row.get("Dept") or "",
                "source": f"KRX-{work_date}",
            }
        )
    return work_date, rows


def analyze_kr_market() -> dict[str, object]:
    work_date, rows = fetch_kr_market_rows()
    if not rows:
        raise ValueError("KRX 시장 데이터를 찾을 수 없습니다")

    def summarize(target_rows: list[dict[str, object]]) -> dict[str, object]:
        tradable = [row for row in target_rows if float(row.get("close", 0)) > 0]
        up = [row for row in tradable if float(row.get("change_pct", 0)) > 0]
        down = [row for row in tradable if float(row.get("change_pct", 0)) < 0]
        flat = len(tradable) - len(up) - len(down)
        total_amount = sum(float(row.get("amount", 0)) for row in tradable)
        total_marcap = sum(float(row.get("marcap", 0)) for row in tradable)
        weighted = (
            sum(float(row.get("change_pct", 0)) * float(row.get("marcap", 0)) for row in tradable) / total_marcap
            if total_marcap
            else 0.0
        )
        avg = sum(float(row.get("change_pct", 0)) for row in tradable) / len(tradable) if tradable else 0.0
        return {
            "count": len(tradable),
            "up": len(up),
            "down": len(down),
            "flat": flat,
            "up_ratio_pct": round(len(up) / len(tradable) * 100, 2) if tradable else 0.0,
            "avg_change_pct": round(avg, 2),
            "marcap_weighted_change_pct": round(weighted, 2),
            "amount": round(total_amount, 0),
        }

    kospi_rows = [row for row in rows if row.get("market") == "KOSPI"]
    kosdaq_rows = [row for row in rows if row.get("market") == "KOSDAQ"]
    semiconductor_keywords = (
        "반도체",
        "GST",
        "한미반도체",
        "리노공업",
        "HPSP",
        "원익IPS",
        "주성엔지니어링",
        "이오테크닉스",
        "유진테크",
        "피에스케이",
        "DB하이텍",
        "하나마이크론",
        "심텍",
        "대덕전자",
        "테크윙",
        "ISC",
        "SFA반도체",
    )
    semis = [
        row
        for row in rows
        if any(keyword.upper() in f"{row.get('name', '')} {row.get('symbol', '')}".upper() for keyword in semiconductor_keywords)
    ]
    top_amount = sorted(rows, key=lambda row: float(row.get("amount", 0)), reverse=True)[:12]
    gainers = sorted([row for row in rows if float(row.get("amount", 0)) > 1_000_000_000], key=lambda row: float(row.get("change_pct", 0)), reverse=True)[:12]
    losers = sorted([row for row in rows if float(row.get("amount", 0)) > 1_000_000_000], key=lambda row: float(row.get("change_pct", 0)))[:12]
    semi_leaders = sorted(semis, key=lambda row: (float(row.get("change_pct", 0)), float(row.get("amount", 0))), reverse=True)[:12]
    semi_laggards = sorted(semis, key=lambda row: float(row.get("change_pct", 0)))[:8]
    overall = summarize(rows)
    kospi = summarize(kospi_rows)
    kosdaq = summarize(kosdaq_rows)
    stance = "중립"
    if overall["marcap_weighted_change_pct"] > 0.7 and overall["up_ratio_pct"] > 55:
        stance = "강세"
    elif overall["marcap_weighted_change_pct"] < -0.7 and overall["up_ratio_pct"] < 45:
        stance = "약세"
    elif overall["up_ratio_pct"] < 40:
        stance = "체감 약세"
    elif overall["up_ratio_pct"] > 60:
        stance = "체감 강세"
    headline = (
        f"{work_date} 한국장 판단: {stance}. "
        f"전체 상승 {overall['up']} / 하락 {overall['down']}, 시총가중 등락 {overall['marcap_weighted_change_pct']}%입니다."
    )
    return {
        "date": work_date,
        "is_today": work_date == datetime.now().date().isoformat(),
        "calendar_note": "오늘이 휴장일이면 최신 거래일 기준으로 분석합니다.",
        "source": f"KRX cache {work_date}",
        "headline": headline,
        "stance": stance,
        "overall": overall,
        "kospi": kospi,
        "kosdaq": kosdaq,
        "top_amount": top_amount,
        "gainers": gainers,
        "losers": losers,
        "semiconductor": {
            "summary": summarize(semis),
            "leaders": semi_leaders,
            "laggards": semi_laggards,
        },
        "ai_notes": [
            "거래대금 상위와 상승률 상위를 분리해서 봐야 실제 수급과 단순 급등을 구분할 수 있습니다.",
            "반도체/후공정/냉각 관련 후보는 시장 전체보다 상대강도와 거래대금 동반 여부를 우선 확인합니다.",
            "이 분석은 매매 명령이 아니라 24시간 AI 연구 데몬의 후보 발굴 입력값입니다.",
        ],
    }


def load_universe() -> dict[str, object]:
    sources = ["내장"]
    rows = list(BUILTIN_UNIVERSE)
    try:
        kr_rows = fetch_kr_universe()
        if kr_rows:
            sources.append("KRX전체")
            rows.extend(kr_rows)
    except Exception:
        pass
    try:
        us_rows = fetch_us_universe()
        if us_rows:
            sources.append("NasdaqTrader")
            rows.extend(us_rows)
    except Exception:
        pass
    source = "+".join(sources)
    if len(sources) > 1:
        try:
            UNIVERSE_CACHE.parent.mkdir(parents=True, exist_ok=True)
            UNIVERSE_CACHE.write_text(json.dumps({"source": source, "rows": rows}, ensure_ascii=False), encoding="utf-8")
        except Exception:
            pass
    if len(sources) == 1:
        if UNIVERSE_CACHE.exists():
            try:
                cached = json.loads(UNIVERSE_CACHE.read_text(encoding="utf-8"))
                rows = cached.get("rows", rows)
                source = f"{cached.get('source', '캐시')} 캐시"
            except Exception:
                source = "내장"
    seen: set[str] = set()
    unique = []
    for row in rows:
        symbol = str(row.get("symbol", "")).upper()
        if not symbol or symbol in seen:
            continue
        seen.add(symbol)
        row["symbol"] = symbol
        unique.append(row)
    return {"source": source, "count": len(unique), "rows": unique}


def _normalize_ai_brain_config(payload: dict[str, object], current: dict[str, object] | None = None) -> dict[str, object]:
    current = current or DEFAULT_AI_BRAIN
    provider = str(payload.get("provider", current.get("provider", "builtin")))
    provider_ids = {preset["id"] for preset in AI_BRAIN_PRESETS}
    if provider not in provider_ids:
        provider = "builtin"
    preset = next((item for item in AI_BRAIN_PRESETS if item["id"] == provider), AI_BRAIN_PRESETS[0])
    try:
        temperature = float(payload.get("temperature", current.get("temperature", 0.2)) or 0.2)
    except (TypeError, ValueError):
        temperature = 0.2
    return {
        "provider": provider,
        "model": str(payload.get("model") or preset["model"]),
        "endpoint": str(payload.get("endpoint") or preset["endpoint"]),
        "temperature": temperature,
    }


def _load_legacy_ai_brain() -> dict[str, object]:
    config = dict(DEFAULT_AI_BRAIN)
    if AI_BRAIN_FILE.exists():
        try:
            saved = json.loads(AI_BRAIN_FILE.read_text(encoding="utf-8"))
            if isinstance(saved, dict):
                config.update(saved)
        except Exception:
            pass
    provider_ids = {preset["id"] for preset in AI_BRAIN_PRESETS}
    if str(config.get("provider")) not in provider_ids:
        config["provider"] = DEFAULT_AI_BRAIN["provider"]
    return _normalize_ai_brain_config(config)


def load_ai_staff_brains() -> dict[str, dict[str, object]]:
    legacy = _load_legacy_ai_brain()
    configurable_roles = ("operator", "researcher", "research_market", "research_fundamental", "research_strategy")
    configs: dict[str, dict[str, object]] = {
        "operator": dict(legacy),
        "researcher": dict(DEFAULT_AI_BRAIN),
        "research_market": dict(DEFAULT_AI_BRAIN),
        "research_fundamental": dict(DEFAULT_AI_BRAIN),
        "research_strategy": dict(DEFAULT_AI_BRAIN),
        "risk_manager": {"provider": "builtin", "model": "규칙 엔진", "endpoint": "", "temperature": 0.0},
    }
    if AI_STAFF_BRAIN_FILE.exists():
        try:
            saved = json.loads(AI_STAFF_BRAIN_FILE.read_text(encoding="utf-8"))
            if isinstance(saved, dict):
                for role in configurable_roles:
                    row = saved.get(role)
                    if isinstance(row, dict):
                        configs[role].update(row)
        except Exception:
            pass
    for role in configurable_roles:
        configs[role] = _normalize_ai_brain_config(configs[role])
    return configs


def save_ai_staff_brain(role: str, payload: dict[str, object]) -> dict[str, object]:
    role = str(role or "operator").strip().lower()
    configurable_roles = {"operator", "researcher", "research_market", "research_fundamental", "research_strategy"}
    if role not in configurable_roles:
        role = "operator"
    configs = load_ai_staff_brains()
    configs[role] = _normalize_ai_brain_config(payload, configs.get(role, DEFAULT_AI_BRAIN))
    serializable = {key: value for key, value in configs.items() if key in configurable_roles}
    AI_STAFF_BRAIN_FILE.parent.mkdir(parents=True, exist_ok=True)
    AI_STAFF_BRAIN_FILE.write_text(json.dumps(serializable, ensure_ascii=False, indent=2), encoding="utf-8")
    if role == "operator":
        AI_BRAIN_FILE.write_text(json.dumps(configs[role], ensure_ascii=False, indent=2), encoding="utf-8")
    return configs[role]


def load_ai_brain() -> dict[str, object]:
    return dict(load_ai_staff_brains().get("operator", DEFAULT_AI_BRAIN))


def save_ai_brain(payload: dict[str, object]) -> dict[str, object]:
    return save_ai_staff_brain("operator", payload)


def ollama_available_models(endpoint: str = "") -> dict[str, object]:
    base = (endpoint or "http://127.0.0.1:11434").rstrip("/")
    try:
        request = Request(f"{base}/api/tags", method="GET")
        with urlopen(request, timeout=6) as response:
            data = json.loads(response.read().decode("utf-8"))
        models = []
        for item in data.get("models", []):
            if not isinstance(item, dict):
                continue
            name = str(item.get("name") or item.get("model") or "").strip()
            if name:
                models.append(name)
        return {"ok": True, "endpoint": base, "models": models}
    except Exception as exc:
        return {"ok": False, "endpoint": base, "models": [], "error": str(exc)}


_OLLAMA_START_LOCK = threading.Lock()
_OLLAMA_LAST_START_ATTEMPT = 0.0


def _local_ollama_executable() -> Path | None:
    configured = str(os.environ.get("OLLAMA_EXE", "")).strip()
    which_ollama = shutil.which("ollama")
    candidates = [
        Path(configured) if configured else None,
        Path(which_ollama) if which_ollama else None,
        Path(os.environ.get("LOCALAPPDATA", "")) / "Programs" / "Ollama" / "ollama.exe",
        Path(os.environ.get("ProgramFiles", "")) / "Ollama" / "ollama.exe",
    ]
    for candidate in candidates:
        if candidate and candidate.is_file():
            return candidate
    return None


def ensure_local_ollama_running(endpoint: str = "") -> dict[str, object]:
    """Start an installed local Ollama server once when the selected provider needs it."""
    global _OLLAMA_LAST_START_ATTEMPT
    base = (endpoint or "http://127.0.0.1:11434").rstrip("/")
    host = (urlparse(base).hostname or "").lower()
    current = ollama_available_models(base)
    if current.get("ok"):
        return {"ok": True, "started": False, "endpoint": base, "models": current.get("models", [])}
    if host not in {"127.0.0.1", "localhost", "::1"}:
        return {"ok": False, "started": False, "endpoint": base, "error": current.get("error", "remote_ollama_unavailable")}

    with _OLLAMA_START_LOCK:
        current = ollama_available_models(base)
        if current.get("ok"):
            return {"ok": True, "started": False, "endpoint": base, "models": current.get("models", [])}
        now = time.monotonic()
        if now - _OLLAMA_LAST_START_ATTEMPT < 60:
            return {"ok": False, "started": False, "endpoint": base, "error": current.get("error", "ollama_start_cooldown")}
        _OLLAMA_LAST_START_ATTEMPT = now
        executable = _local_ollama_executable()
        if executable is None:
            return {"ok": False, "started": False, "endpoint": base, "error": "ollama_executable_not_found"}
        try:
            creationflags = int(getattr(subprocess, "CREATE_NO_WINDOW", 0))
            child_env = os.environ.copy()
            child_env.setdefault("OLLAMA_LLM_LIBRARY", "cpu_avx2")
            subprocess.Popen(
                [str(executable), "serve"],
                stdin=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=creationflags,
                env=child_env,
            )
        except Exception as exc:
            return {"ok": False, "started": False, "endpoint": base, "error": str(exc)}

        deadline = time.monotonic() + 20
        while time.monotonic() < deadline:
            time.sleep(0.4)
            current = ollama_available_models(base)
            if current.get("ok"):
                JOURNAL.add(
                    "AI_BRAIN_OLLAMA_AUTO_STARTED",
                    str(executable),
                    {"endpoint": base, "models": current.get("models", [])},
                )
                return {"ok": True, "started": True, "endpoint": base, "models": current.get("models", [])}
        return {"ok": False, "started": True, "endpoint": base, "error": current.get("error", "ollama_start_timeout")}


def resolve_ollama_model(provider: str, configured_model: str, endpoint: str = "") -> dict[str, object]:
    configured_model = str(configured_model or "").strip()
    tags = ollama_available_models(endpoint)
    models = [str(item) for item in tags.get("models", [])]
    if configured_model and configured_model in models:
        return {"model": configured_model, "configured_model": configured_model, "changed": False, "tags": tags}
    preferred = {
        "ollama-local": ["qwen2.5:1.5b", "qwen2.5:3b", "llama3.2:1b", "gemma3:1b"],
        "ollama-gemma": ["gemma4:latest", "gemma4", "gemma3", "gemma"],
        "ollama-qwen": ["qwen2.5:3b", "qwen2.5:1.5b", "qwen2.5", "qwen"],
        "ollama-llama": ["llama3.2:3b", "llama3.2:1b", "llama3.2", "llama"],
        "ollama-deepseek": ["deepseek-r1:1.5b", "deepseek-r1", "deepseek"],
        "ollama-phi": ["phi3:mini", "phi3", "phi"],
    }.get(provider, [])
    for needle in preferred:
        for model in models:
            if model == needle or needle.lower() in model.lower():
                return {"model": model, "configured_model": configured_model, "changed": model != configured_model, "tags": tags}
    if models:
        return {"model": models[0], "configured_model": configured_model, "changed": models[0] != configured_model, "tags": tags}
    return {"model": configured_model, "configured_model": configured_model, "changed": False, "tags": tags}


def ai_brain_status() -> dict[str, object]:
    config = load_ai_brain()
    preset = next((item for item in AI_BRAIN_PRESETS if item["id"] == config.get("provider")), AI_BRAIN_PRESETS[0])
    resolved = None
    if str(config.get("provider")) in OLLAMA_PROVIDER_IDS:
        resolved = resolve_ollama_model(str(config.get("provider")), str(config.get("model", "")), str(config.get("endpoint", "")))
    return {
        "config": config,
        "preset": preset,
        "presets": AI_BRAIN_PRESETS,
        "resolved": resolved,
        "ready": config.get("provider") == "builtin" or bool((resolved or {}).get("model") or config.get("model")),
        "message": "선택된 AI 두뇌가 명령창 보조 응답에 사용됩니다.",
    }


def ai_staff_brain_status() -> dict[str, object]:
    configs = load_ai_staff_brains()
    roles: dict[str, dict[str, object]] = {}
    local_models: list[str] = []
    configurable_roles = {"operator", "researcher", "research_market", "research_fundamental", "research_strategy"}
    for role, config in configs.items():
        preset = next((item for item in AI_BRAIN_PRESETS if item["id"] == config.get("provider")), AI_BRAIN_PRESETS[0])
        resolved = None
        if role in configurable_roles and str(config.get("provider")) in OLLAMA_PROVIDER_IDS:
            resolved = resolve_ollama_model(str(config.get("provider")), str(config.get("model", "")), str(config.get("endpoint", "")))
            model_rows = (resolved.get("tags", {}) or {}).get("models", []) if isinstance(resolved, dict) else []
            for model in model_rows:
                if str(model) not in local_models:
                    local_models.append(str(model))
        roles[role] = {
            "config": config,
            "preset": preset,
            "resolved": resolved,
            "ready": role == "risk_manager" or config.get("provider") == "builtin" or bool((resolved or {}).get("model") or config.get("model")),
        }
    return {
        "ok": True,
        "roles": roles,
        "presets": AI_BRAIN_PRESETS,
        "local_models": local_models,
        "message": "설정 탭에서 운용/매매 직원과 연구 직원의 AI 모델을 따로 선택합니다.",
    }


def _builtin_agent_reply(prompt: str, context: str = "", failed_provider: str = "") -> str:
    text = prompt.strip()
    lowered = text.lower()
    greeting_words = ("\uc548\ub155", "\ud558\uc774", "\ubc18\uac00", "\ud5ec\ub85c", "\ud558\uc774\ub8e8", "\u314e\u3147", "hi", "hello", "hey")
    thanks_words = ("\uace0\ub9c8\uc6cc", "\uac10\uc0ac", "\uc88b\uc558\uc5b4", "\uc88b\uc544", "\uadf8\ub798", "thanks", "thank you")
    if any(word in lowered or word in text for word in greeting_words):
        suffix = f"\n\n참고: {failed_provider} 호출이 안 되어 내장 엔진으로 응답했습니다." if failed_provider else ""
        return (
            "\uc548\ub155\ud558\uc138\uc694. \uc800\ub294 \uc9c0\uae08 \ub0b4\uc7a5 \uc5d4\uc9c4\uc73c\ub85c \ub300\uae30 \uc911\uc785\ub2c8\ub2e4.\n"
            "\uacc4\uc88c \uc794\uace0, \uc2dc\uc7a5 \uad6d\uba74, \ud6c4\ubcf4 \ubc1c\uad74, \ubc31\ud14c\uc2a4\ud2b8, \uc624\ud1a0\ud30c\uc77c\ub7ff \uc0c1\ud0dc\ub294 \ub85c\uceec \ubaa8\ub378 \uc5c6\uc774\ub3c4 \ubc14\ub85c \ucc98\ub9ac\ud560 \uc218 \uc788\uc5b4\uc694."
            f"{suffix}"
        )
    if any(word in lowered or word in text for word in thanks_words):
        return "\uc88b\uc2b5\ub2c8\ub2e4. \uc774\uc81c \ub85c\uceec \ubaa8\ub378\uc774 \uaebc\uc838 \uc788\uc5b4\ub3c4 \uae30\ubcf8 \uba85\ub839\uacfc \ubcf4\uace0\ub294 \uacc4\uc18d \ub3cc\uc544\uac00\uac8c \ud558\uaca0\uc2b5\ub2c8\ub2e4."
    if failed_provider:
        return (
            f"{failed_provider} 호출이 실패해서 내장 엔진으로 전환했습니다.\n"
            "\uc0ac\uc6a9 \uac00\ub2a5\ud55c \uba85\ub839: \uacc4\uc88c \uc794\uace0, \uc2dc\uc7a5 \uad6d\uba74, \uc624\ud1a0\ud30c\uc77c\ub7ff \uc0c1\ud0dc, \ud6c4\ubcf4 \ubc1c\uad74, \ubc31\ud14c\uc2a4\ud2b8 AAPL, \ud55c\uad6d\uc7a5 \ubd84\uc11d."
        )
    return (
        "\ub0b4\uc7a5 \uc5d4\uc9c4\uc73c\ub85c \ucc98\ub9ac\ud588\uc2b5\ub2c8\ub2e4.\n"
        "\uc790\uc5f0\uc5b4 \ub300\ud654\ub97c \ub354 \uae38\uac8c \ud558\ub824\uba74 GPT/Ollama\ub97c \ucf24 \uc218 \uc788\uace0, \uae30\ubcf8 \uc8fc\uc2dd \uba85\ub839\uc740 \uc9c0\uae08\ub3c4 \ubc14\ub85c \uc791\ub3d9\ud569\ub2c8\ub2e4."
    )


def _fast_secretary_builtin_reply(prompt: str) -> str:
    text = str(prompt or "").strip()
    lowered = text.lower()
    greeting_words = ("안녕", "하이", "반가", "헬로", "ㅎㅇ", "hi", "hello", "hey")
    thanks_words = ("고마워", "감사", "수고", "잘했", "좋았어", "thanks", "thank you")
    speed_words = ("느려", "느리", "답답", "응답 속도", "대답 속도")
    acknowledgement_words = {"응", "어", "그래", "알았어", "알겠어", "좋아", "네", "예", "ㅇㅇ", "ok", "okay"}
    if any(word in lowered for word in speed_words):
        return "비서 속도 문제를 확인했습니다. 일반 대화는 경량 모델로 빠르게 처리하고, 심층 분석을 요청할 때만 Gemma4를 사용하겠습니다."
    if lowered in acknowledgement_words:
        return "네, 이어서 처리하겠습니다."
    if any(word in lowered for word in greeting_words):
        return "안녕하세요. 코덱스스톡 비서가 대기 중입니다. 무엇을 확인할까요?"
    if any(word in lowered for word in thanks_words):
        return "네, 필요한 작업을 계속 챙기겠습니다."
    return ""


def _resolve_secretary_ollama_model(
    configured_model: str,
    endpoint: str,
    prompt: str,
) -> dict[str, object]:
    resolved = resolve_ollama_model("ollama-local", configured_model, endpoint)
    tags = resolved.get("tags") if isinstance(resolved.get("tags"), dict) else {}
    models = [str(item) for item in tags.get("models", []) if str(item).strip()]
    deep_reasoning = any(word in str(prompt or "").lower() for word in SECRETARY_DEEP_REASONING_WORDS)
    if deep_reasoning or not str(configured_model).lower().startswith("gemma4"):
        return {
            "model": str(resolved.get("model") or configured_model),
            "configured_model": configured_model,
            "fast_secretary": False,
            "deep_reasoning": deep_reasoning,
            "tags": tags,
        }
    fast_model = next((candidate for candidate in SECRETARY_FAST_MODEL_CANDIDATES if candidate in models), "")
    return {
        "model": fast_model or str(resolved.get("model") or configured_model),
        "configured_model": configured_model,
        "fast_secretary": bool(fast_model),
        "deep_reasoning": False,
        "tags": tags,
    }


def _openai_api_key() -> str:
    env_file = REPO_ROOT / ".env"
    keys = ["OPENAI_API_KEY", "OPENAI_KEY"]
    for key in keys:
        value = ""
        if env_file.exists():
            for line in env_file.read_text(encoding="utf-8", errors="ignore").splitlines():
                if line.strip().startswith(f"{key}="):
                    value = line.split("=", 1)[1].strip().strip('"').strip("'")
                    break
        if value:
            return value
    return ""


def ask_selected_ai_brain(prompt: str, context: str = "") -> dict[str, object]:
    config = load_ai_brain()
    provider = str(config.get("provider", "builtin"))
    model = str(config.get("model", ""))
    endpoint = str(config.get("endpoint", ""))
    system = (
        "너는 한국어로 답하는 주식 AI 트레이더 보조 두뇌다. "
        "실전 주문은 승인 전까지 절대 실행하지 말고, 분석/백테스트/리스크 점검 중심으로 짧고 명확하게 답한다."
    )
    full_prompt = f"{system}\n\n현재 프로그램 컨텍스트:\n{context}\n\n사용자 명령:\n{prompt}"

    system = (
        "너는 코덱스스톡과 미니PC를 함께 관리하는 한 명의 한국어 AI 비서 '똑똑'이다. "
        "사용자와 이미 대화 중인 것처럼 앞선 문맥을 자연스럽게 이어서 답한다. "
        "전원 제어, 코덱스스톡 상태 확인, 주식 분석 기능은 서로 다른 직원이 아니라 모두 네 기능이다. "
        "이미 프로그램이 처리한 기능을 두고 권한이 없다고 말하거나, 코덱스스톡을 종목명으로 오해하지 않는다. "
        "모르는 상태는 지어내지 말고 확인이 필요하다고 말한다. "
        "실전 주문은 사용자 승인 전에는 실행하지 말고, 짧고 친근하며 자연스럽게 답한다."
    )
    full_prompt = f"{system}\n\n현재 프로그램 컨텍스트:\n{context}\n\n사용자 명령:\n{prompt}\n\n답변은 한국어 3문장 이내로 한다."

    if provider == "builtin":
        return {"ok": True, "provider": provider, "model": model, "reply": _builtin_agent_reply(prompt, context=context)}

    if provider == "__legacy_builtin_disabled__":
        return {
            "ok": True,
            "provider": provider,
            "model": model,
            "reply": "내장 규칙 엔진으로 처리했습니다. 더 복잡한 자연어 판단은 GPT, Gemma, Qwen 중 하나를 선택하면 연결됩니다.",
        }

    if provider == "openai":
        api_key = _openai_api_key()
        if not api_key:
            return {"ok": False, "provider": provider, "model": model, "reply": "OPENAI_API_KEY가 설정되어 있지 않습니다. .env에 키를 넣거나 로컬 모델을 선택해주세요."}
        payload = json.dumps(
            {
                "model": model or "gpt-4.1-mini",
                "temperature": float(config.get("temperature", 0.2)),
                "messages": [
                    {"role": "system", "content": system},
                    {"role": "user", "content": f"{context}\n\n{prompt}"},
                ],
            },
            ensure_ascii=False,
        ).encode("utf-8")
        request = Request(
            endpoint or "https://api.openai.com/v1/chat/completions",
            data=payload,
            headers={"Content-Type": "application/json", "Authorization": f"Bearer {api_key}"},
            method="POST",
        )
        try:
            with urlopen(request, timeout=20) as response:
                data = json.loads(response.read().decode("utf-8"))
            reply = data.get("choices", [{}])[0].get("message", {}).get("content", "").strip()
            return {"ok": True, "provider": provider, "model": model, "reply": reply or "GPT 응답이 비어 있습니다."}
        except Exception as exc:
            return {"ok": False, "provider": provider, "model": model, "reply": f"GPT 호출 실패: {exc}"}

    if provider in OLLAMA_PROVIDER_IDS:
        ensure_local_ollama_running(endpoint)
        url = (endpoint or "http://127.0.0.1:11434").rstrip("/") + "/api/generate"
        resolved = _resolve_secretary_ollama_model(model, endpoint, prompt)
        resolved_model = str(resolved.get("model") or model).strip()
        tags = resolved.get("tags") if isinstance(resolved.get("tags"), dict) else {}
        if not resolved_model:
            return {
                "ok": False,
                "provider": provider,
                "model": model,
                "reply": f"Ollama 모델을 찾지 못했습니다. 설치 모델: {', '.join(tags.get('models', [])) or '없음'}",
                "resolved": resolved,
            }
        if resolved.get("changed"):
            JOURNAL.add("AI_BRAIN_MODEL_RESOLVED", f"{model or '-'} -> {resolved_model}", {"provider": provider, "available": tags.get("models", [])})
        fast_secretary = bool(resolved.get("fast_secretary"))
        attempts = [
            {"num_predict": 96 if fast_secretary else 512, "timeout": 45 if fast_secretary else 240, "prompt": full_prompt},
            {
                "num_predict": 64 if fast_secretary else 256,
                "timeout": 45 if fast_secretary else 240,
                "prompt": f"{system}\n\n사용자 명령:\n{prompt}\n\n한국어로 3문장 이내로 답한다.",
            },
        ]
        last_error = ""
        for index, attempt in enumerate(attempts, start=1):
            payload = json.dumps(
                {
                    "model": resolved_model,
                    "prompt": attempt["prompt"],
                    "stream": False,
                    "think": False,
                    "keep_alive": "30m" if fast_secretary else "24h",
                    "options": {
                        "temperature": float(config.get("temperature", 0.2)),
                        "num_predict": int(attempt["num_predict"]),
                        "num_ctx": 2048 if fast_secretary else 4096,
                    },
                },
                ensure_ascii=False,
            ).encode("utf-8")
            request = Request(url, data=payload, headers={"Content-Type": "application/json"}, method="POST")
            try:
                with urlopen(request, timeout=int(attempt["timeout"])) as response:
                    data = json.loads(response.read().decode("utf-8"))
                if data.get("error"):
                    raise RuntimeError(str(data.get("error")))
                reply = str(data.get("response", "")).strip()
                if reply:
                    return {
                        "ok": True,
                        "provider": provider,
                        "model": resolved_model,
                        "configured_model": model,
                        "fast_secretary": fast_secretary,
                        "reply": reply,
                        "resolved": resolved,
                        "attempt": index,
                    }
                last_error = "로컬 모델 응답이 비어 있습니다."
            except Exception as exc:
                last_error = str(exc)
                JOURNAL.add("AI_BRAIN_OLLAMA_RETRY", last_error, {"provider": provider, "model": resolved_model, "attempt": index})
                time.sleep(0.4)
        return {
            "ok": False,
            "provider": provider,
            "model": resolved_model,
            "configured_model": model,
            "reply": f"로컬 모델 호출 실패: {last_error}. Ollama 실행 여부와 모델 설치를 확인해주세요.",
            "resolved": resolved,
        }

    if provider == "custom-local":
        payload = json.dumps({"model": model, "prompt": full_prompt, "temperature": float(config.get("temperature", 0.2))}, ensure_ascii=False).encode("utf-8")
        request = Request(endpoint, data=payload, headers={"Content-Type": "application/json"}, method="POST")
        try:
            with urlopen(request, timeout=35) as response:
                data = json.loads(response.read().decode("utf-8"))
            reply = data.get("reply") or data.get("response") or data.get("text") or ""
            return {"ok": True, "provider": provider, "model": model, "reply": str(reply).strip() or "사용자 로컬 API 응답이 비어 있습니다."}
        except Exception as exc:
            return {"ok": False, "provider": provider, "model": model, "reply": f"사용자 로컬 API 호출 실패: {exc}"}

    return {"ok": False, "provider": provider, "model": model, "reply": "지원하지 않는 AI 두뇌입니다."}


def warm_secretary_ai_brain() -> None:
    """Load the lightweight secretary model without blocking app startup."""
    try:
        config = load_ai_brain()
        provider = str(config.get("provider", "builtin"))
        if provider not in OLLAMA_PROVIDER_IDS:
            return
        endpoint = str(config.get("endpoint", ""))
        resolved = _resolve_secretary_ollama_model(
            str(config.get("model", "")),
            endpoint,
            "일반 비서 대화 준비",
        )
        if not resolved.get("fast_secretary"):
            return
        model = str(resolved.get("model") or "").strip()
        if not model:
            return
        payload = json.dumps(
            {
                "model": model,
                "prompt": "준비",
                "stream": False,
                "think": False,
                "keep_alive": "30m",
                "options": {"num_predict": 1, "num_ctx": 1024},
            },
            ensure_ascii=False,
        ).encode("utf-8")
        url = (endpoint or "http://127.0.0.1:11434").rstrip("/") + "/api/generate"
        request = Request(url, data=payload, headers={"Content-Type": "application/json"}, method="POST")
        with urlopen(request, timeout=45) as response:
            response.read()
        JOURNAL.add("SECRETARY_MODEL_PREWARMED", model, {"provider": provider})
    except Exception as exc:
        JOURNAL.add("SECRETARY_MODEL_PREWARM_FAILED", str(exc), {})


def _extract_symbols(text: str) -> list[str]:
    tokens = re.findall(r"\b[A-Za-z][A-Za-z0-9.]{0,7}\b|\b\d{6}\b", text.upper())
    blocked = {
        "AI",
        "MA",
        "RSI",
        "MDD",
        "ETF",
        "BUY",
        "SELL",
        "HELP",
        "PAPER",
        "LIVE",
        "CANDIDATE",
        "APPROVE",
        "DRY",
        "SUBMIT",
        "STATUS",
    }
    symbols = []
    for token in tokens:
        if token in blocked or re.match(r"^\d{4}$", token):
            continue
        if token not in symbols:
            symbols.append(token)
    return symbols


def _extract_approval_token(text: str) -> str:
    match = re.search(r"\bAPP-[A-Z0-9]{16}\b", text.upper())
    return match.group(0) if match else ""


def _approval_is_unexpired(row: dict[str, object] | None) -> bool:
    if not isinstance(row, dict):
        return False
    expires_at = str(row.get("expires_at", "")).strip()
    if not expires_at:
        return False
    try:
        expires = datetime.fromisoformat(expires_at)
    except ValueError:
        return False
    return expires >= datetime.now(expires.tzinfo) if expires.tzinfo else expires >= datetime.now()


def _confirm_single_live_order(source: str = "chat") -> dict[str, object]:
    """Resolve and submit exactly one current live-order ticket.

    A short confirmation is safe only when it identifies one immutable ticket.
    Ambiguous, expired, already-submitted, or failed dry-runs stop closed.
    """
    approvals = [row for row in OPS.approvals() if _approval_is_unexpired(row)]
    actionable = [
        row for row in approvals
        if str(row.get("status", "")).lower() in {"pending", "approved"}
    ]
    if not actionable:
        return {
            "ok": False,
            "status": "NO_ACTIONABLE_ORDER",
            "message": "승인할 유효 주문표가 없습니다.",
        }
    if len(actionable) != 1:
        return {
            "ok": False,
            "status": "AMBIGUOUS_ORDER_CONFIRMATION",
            "message": f"유효 주문표가 {len(actionable)}개라 한 단어 승인으로 특정할 수 없습니다.",
            "orders": [
                {
                    "token": row.get("token"),
                    "ticket": row.get("ticket", {}),
                }
                for row in actionable[:5]
            ],
        }

    approval = actionable[0]
    token = str(approval.get("token", ""))
    if str(approval.get("status", "")).lower() == "pending":
        approval = OPS.resolve_approval(
            token,
            approved=True,
            memo=f"{source} 단일 주문표 최종 승인",
        )

    dry_rows = [
        row for row in OPS.live_dry_submits(limit=100)
        if str((row.get("approval") or {}).get("token", "")) == token
        and str(row.get("status", "")) == "LIVE_READY_NOT_SUBMITTED"
    ]
    dry = dry_rows[-1] if dry_rows else OPS.live_dry_submit(token)
    if str(dry.get("status", "")) != "LIVE_READY_NOT_SUBMITTED":
        return {
            "ok": False,
            "status": "DRY_SUBMIT_BLOCKED",
            "message": "최종 재검증을 통과하지 못해 주문하지 않았습니다.",
            "approval": approval,
            "dry_submit": dry,
        }

    ticket = approval.get("ticket") if isinstance(approval.get("ticket"), dict) else {}
    quantity = float(ticket.get("quantity", 0) or 0)
    if quantity <= 0:
        return {
            "ok": False,
            "status": "INVALID_ORDER_QUANTITY",
            "message": "주문표 수량이 올바르지 않아 주문하지 않았습니다.",
        }
    result = submit_live_pilot_order(
        token=token,
        confirm_phrase=f"{quantity:g}주 파일럿 승인",
        order_type="limit",
        execution_actor="operator",
    )
    return {
        "ok": bool(result.get("ok")),
        "status": result.get("status", "LIVE_SUBMIT_FAILED"),
        "message": result.get("message", "최종 주문 처리 결과를 확인하세요."),
        "approval": approval,
        "dry_submit": dry,
        "submit": result,
    }


def _extract_dates(text: str) -> tuple[str, str]:
    dates = re.findall(r"\d{4}-\d{2}-\d{2}", text)
    if len(dates) >= 2:
        return dates[0], dates[1]
    if len(dates) == 1:
        return dates[0], today_kst()
    return "2020-01-01", today_kst()


def _extract_windows(text: str) -> tuple[int, int]:
    lower = text.lower()
    fast_match = re.search(r"(?:fast|단기|짧은선|ma)\s*[:=]?\s*(\d{1,3})", lower)
    slow_match = re.search(r"(?:slow|장기|긴선)\s*[:=]?\s*(\d{1,3})", lower)
    fast = int(fast_match.group(1)) if fast_match else 12
    slow = int(slow_match.group(1)) if slow_match else 32
    if slow <= fast:
        slow = max(fast + 5, 32)
    return fast, slow


def start_user_autotrade(source: str = "agent", memo: str = "사용자 명령 자동매매 시작") -> dict[str, object]:
    policy = OPS.save_autotrade_policy(
        {
            "paper_autopilot_enabled": True,
            "live_candidate_enabled": True,
            "live_pilot_enabled": True,
            "emergency_halt": False,
            "buy_blocked": False,
            "day_halted": False,
            "memo": memo,
        }
    )
    policy = OPS.set_emergency_halt(False, memo=memo)
    scheduler = AUTOPILOT_SCHEDULER.start()
    daemon = AI_DAEMON.start(initial_delay_seconds=_research_startup_initial_delay_seconds())
    ops_status = build_ops_status()
    return {
        "ok": True,
        "source": source,
        "policy": policy,
        "scheduler": scheduler,
        "daemon": daemon,
        "readiness": build_autotrade_readiness(ops_status),
        "ops_status": ops_status,
        "message": "자동매매 시작 완료: 자동 점검, AI 연구 데몬, Paper 운용, 실전 후보 발굴을 켰습니다.",
    }


def stop_user_autotrade(source: str = "agent", memo: str = "사용자 명령 자동매매 멈춤") -> dict[str, object]:
    policy = OPS.save_autotrade_policy(
        {
            "paper_autopilot_enabled": False,
            "live_candidate_enabled": False,
            "live_pilot_enabled": False,
            "live_execution_enabled": False,
            "memo": memo,
        }
    )
    policy = OPS.set_emergency_halt(True, memo=memo)
    scheduler = AUTOPILOT_SCHEDULER.stop()
    daemon = AI_DAEMON.stop()
    ops_status = build_ops_status()
    return {
        "ok": True,
        "source": source,
        "policy": policy,
        "scheduler": scheduler,
        "daemon": daemon,
        "readiness": build_autotrade_readiness(ops_status),
        "ops_status": ops_status,
        "message": "자동매매 멈춤 완료: 자동 점검과 AI 연구 데몬을 끄고 신규 주문 후보를 차단했습니다.",
    }


def build_autotrade_status_quick() -> dict[str, object]:
    global AUTOTRADE_STATUS_QUICK_CACHE
    started_at = time.perf_counter()
    now_monotonic = time.monotonic()
    if AUTOTRADE_STATUS_QUICK_CACHE:
        cached_at, cached_payload = AUTOTRADE_STATUS_QUICK_CACHE
        if now_monotonic - cached_at <= 30.0:
            payload = dict(cached_payload)
            payload["cached"] = True
            payload["cache_age_seconds"] = round(now_monotonic - cached_at, 3)
            return payload
    """텔레그램 상태 질의용 빠른 자동매매 상태. 계좌/시세 조회와 주문 전송을 하지 않는다."""
    policy = OPS.autotrade_policy()
    scheduler_thread = getattr(AUTOPILOT_SCHEDULER, "thread", None)
    daemon_thread = getattr(AI_DAEMON, "thread", None)
    scheduler = {
        "running": bool(getattr(AUTOPILOT_SCHEDULER, "running", False)),
        "thread_alive": bool(scheduler_thread and scheduler_thread.is_alive()),
    }
    daemon = {
        "running": bool(getattr(AI_DAEMON, "running", False)),
        "thread_alive": bool(daemon_thread and daemon_thread.is_alive()),
        "current_activity": copy.deepcopy(dict(getattr(AI_DAEMON, "current_activity", {}) or {})),
        "last_error": str(getattr(AI_DAEMON, "last_error", "") or ""),
    }

    # The launcher polls this endpoint frequently. Full ledger scans and account
    # reconciliation belong to the explicit detailed status endpoints.
    pending_approvals: list[dict[str, object]] = []
    approved_approvals: list[dict[str, object]] = []
    previous_payload = AUTOTRADE_STATUS_QUICK_CACHE[1] if AUTOTRADE_STATUS_QUICK_CACHE else {}
    previous_counts = previous_payload.get("today_counts") if isinstance(previous_payload, dict) else {}
    counts = dict(previous_counts) if isinstance(previous_counts, dict) else {}
    why = {
        "title": "빠른 운영 상태",
        "reason": "원장 전체 대사는 상세 상태 조회에서 수행합니다.",
        "next": "화면 폴링은 연구·백테스트와 분리되어 계속 응답합니다.",
        "diagnostics": [],
    }
    delegated_authorization = build_delegated_live_authorization(policy)
    diagnostics = why.get("diagnostics", []) if isinstance(why.get("diagnostics"), list) else []
    flags = {
        "delegated_live_autonomy_enabled": bool(policy.get("delegated_live_autonomy_enabled")),
        "delegated_live_authorized_today": bool(delegated_authorization.get("valid_today")),
        "paper_autopilot_enabled": bool(policy.get("paper_autopilot_enabled")),
        "live_candidate_enabled": bool(policy.get("live_candidate_enabled")),
        "live_pilot_enabled": bool(policy.get("live_pilot_enabled")),
        "live_execution_enabled": bool(policy.get("live_execution_enabled")),
        "require_approval": bool(policy.get("require_approval", True)),
        "emergency_halt": bool(policy.get("emergency_halt")),
        "day_halted": bool(policy.get("day_halted")),
        "buy_blocked": bool(policy.get("buy_blocked")),
        "scheduler_running": bool(scheduler.get("running")) and bool(scheduler.get("thread_alive")),
        "research_daemon_running": bool(daemon.get("running")),
    }
    capital_policy = build_delegated_live_capital_policy(policy)
    blockers: list[str] = []
    if flags["emergency_halt"]:
        blockers.append("긴급정지 ON")
    if flags["day_halted"]:
        blockers.append("당일정지 ON")
    if flags["buy_blocked"]:
        blockers.append("매수 차단 ON")
    if not flags["live_candidate_enabled"]:
        blockers.append("실전 후보 생성 OFF")
    if not flags["live_pilot_enabled"]:
        blockers.append("1주 파일럿 OFF")
    if not flags["live_execution_enabled"]:
        blockers.append("실전 주문 전송 OFF")
    if flags["delegated_live_autonomy_enabled"] and not flags["delegated_live_authorized_today"]:
        blockers.append("오늘 실전 위임 최종 지시 없음")
    if flags["require_approval"] and not pending_approvals and not approved_approvals:
        blockers.append("유효 승인 토큰 없음")

    mode = (
        "실전 위임 자동운용 ON"
        if flags["delegated_live_autonomy_enabled"]
        else "실전 후보 감시 ON"
        if flags["live_candidate_enabled"] or flags["live_pilot_enabled"]
        else "연구/Paper 중심"
    )
    if flags["emergency_halt"] or flags["day_halted"]:
        mode = "자동매매 정지/차단"
    payload = {
        "ok": True,
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "mode": mode,
        "flags": flags,
        "capital_policy": capital_policy,
        "delegated_authorization": delegated_authorization,
        "blockers": blockers,
        "pending_approvals": len(pending_approvals),
        "approved_approvals": len(approved_approvals),
        "today_counts": counts,
        "why": {
            "title": why.get("title", ""),
            "reason": why.get("reason", ""),
            "next": why.get("next", ""),
            "diagnostics": diagnostics[:3],
        },
        "scheduler": {
            "running": bool(scheduler.get("running")),
            "thread_alive": bool(scheduler.get("thread_alive")),
        },
        "daemon": {
            "running": bool(daemon.get("running")),
            "thread_alive": bool(daemon.get("thread_alive")),
            "current_activity": daemon.get("current_activity", {}),
            "last_error": daemon.get("last_error", ""),
        },
        "poll_health": {
            "status": "ok",
            "profile": "memory_and_policy_only",
            "total_step_ms": round((time.perf_counter() - started_at) * 1000.0, 2),
            "slow_step_count": 0,
            "slow_steps": [],
        },
        "server_runtime": {
            "started_at": datetime.fromtimestamp(SERVER_STARTED_AT).isoformat(timespec="seconds"),
            "uptime_seconds": round(max(0.0, time.time() - SERVER_STARTED_AT), 1),
            "process_id": os.getpid(),
            "runtime_marker": "ops_status_poll_cache_stabilized",
        },
        "detail_endpoint": "/api/ops/status",
        "quick": True,
        "cached": False,
        "safety": "빠른 상태 조회입니다. 계좌 조회, 시세 조회, 실제 주문 전송은 실행하지 않습니다.",
    }
    AUTOTRADE_STATUS_QUICK_CACHE = (time.monotonic(), dict(payload))
    return payload


def build_execution_sidecar_status_quick() -> dict[str, object]:
    """Read the isolated executor status without building the full ops report."""
    sidecar_dir = OPS.data_dir / "execution_sidecar"
    status_path = sidecar_dir / "status.json"
    proof_path = sidecar_dir / "validation_proof.json"
    candidate_scheduler_path = sidecar_dir / "shadow_candidate_scheduler.json"
    supervisor_path = sidecar_dir / "supervisor.json"
    pipeline_drill_path = sidecar_dir / "pipeline_drill" / "latest.json"

    def read_mapping(path: Path) -> dict[str, object]:
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return {}
        return value if isinstance(value, dict) else {}

    status = read_mapping(status_path)
    proof = read_mapping(proof_path)
    candidate_scheduler = read_mapping(candidate_scheduler_path)
    supervisor = read_mapping(supervisor_path)
    pipeline_drill = read_mapping(pipeline_drill_path)
    pipeline = status.get("candidate_pipeline")
    if not isinstance(pipeline, dict):
        pipeline = {}
    compact_proof = status.get("validation_proof")
    if not isinstance(compact_proof, dict):
        compact_proof = {}
    if proof:
        compact_proof = {
            "operational_ok": proof.get("operational_ok"),
            "proof_complete": proof.get("proof_complete"),
            "observation_hours": proof.get("observation_hours"),
            "required_observation_hours": proof.get("required_observation_hours"),
            "coverage_complete": proof.get("coverage_complete"),
            "qualifying_result_count": (proof.get("evidence") or {}).get("qualifying_result_count"),
            "required_result_count": proof.get("required_result_count"),
            "observed_symbol_count": (proof.get("evidence") or {}).get("observed_symbol_count"),
            "required_symbol_count": proof.get("required_symbol_count"),
            "generated_at": proof.get("generated_at"),
            "checks": proof.get("checks", {}),
        }
    process_id = int(status.get("process_id") or 0)
    process_alive = process_is_alive(process_id)
    try:
        status_at = datetime.fromisoformat(str(status.get("updated_at") or ""))
        if status_at.tzinfo is None:
            status_at = status_at.astimezone()
        status_age_seconds = max(0.0, (datetime.now().astimezone() - status_at).total_seconds())
    except (TypeError, ValueError):
        status_age_seconds = 999999.0
    status_fresh = status_age_seconds <= 10.0
    runtime_alive = process_alive and status_fresh
    proof_checks = compact_proof.get("checks")
    if not isinstance(proof_checks, dict):
        proof_checks = {}
    compact_proof["checks"] = {**proof_checks, "sidecar_process_alive": runtime_alive}
    compact_proof["operational_ok"] = bool(compact_proof.get("operational_ok")) and runtime_alive
    return {
        "ok": status.get("ok") is True and runtime_alive,
        "mode": status.get("mode", "unknown"),
        "updated_at": status.get("updated_at", ""),
        "cycles": int(status.get("cycles") or 0),
        "processed_total": int(status.get("processed_total") or 0),
        "inbox_pending": int(status.get("inbox_pending") or 0),
        "runtime_session_id": status.get("runtime_session_id", ""),
        "runtime_process": {
            "process_id": process_id,
            "process_alive": process_alive,
            "status_fresh": status_fresh,
            "status_age_seconds": round(status_age_seconds, 3),
            "process_started_at": status.get("process_started_at", ""),
        },
        "candidate_pipeline": pipeline,
        "pipeline_drill": pipeline_drill,
        "shadow_candidate_scheduler": candidate_scheduler,
        "supervisor": supervisor,
        "validation_proof": compact_proof,
        "real_order_supported": bool(status.get("real_order_supported")) and runtime_alive,
    }


def build_mcp_instant_overview() -> dict[str, object]:
    """Return in-memory operational facts without scanning trade or research ledgers."""
    try:
        policy = OPS.autotrade_policy()
        policy_error = ""
    except Exception as exc:
        policy = {}
        policy_error = str(exc)

    daemon = AI_DAEMON
    scheduler = AUTOPILOT_SCHEDULER
    daemon_thread = getattr(daemon, "thread", None)
    scheduler_thread = getattr(scheduler, "thread", None)
    daemon_running = bool(getattr(daemon, "running", False))
    scheduler_running = bool(getattr(scheduler, "running", False))
    activity = copy.deepcopy(dict(getattr(daemon, "current_activity", {}) or {}))
    staff_activity = copy.deepcopy(dict(getattr(daemon, "staff_activity", {}) or {}))
    role_meta = {
        str(row.get("id") or ""): row
        for row in AI_STAFF_ROLES
        if isinstance(row, dict) and row.get("id")
    }
    role_name_overrides = {"risk": "리스크 관리자", "telegram": "텔레그램 비서"}
    workers: list[dict[str, object]] = []
    stale_workers = 0
    for role_id, row in staff_activity.items():
        if not isinstance(row, dict):
            continue
        updated_at = str(row.get("updated_at") or "")
        age_seconds = _iso_age_seconds(updated_at) if updated_at else None
        stale = age_seconds is None or age_seconds > 1800
        stale_workers += int(stale)
        meta = role_meta.get(str(role_id), {})
        workers.append(
            {
                "id": role_id,
                "name": row.get("name") or meta.get("name") or role_name_overrides.get(str(role_id)) or role_id,
                "state": row.get("state") or ("상시근무" if daemon_running else "대기"),
                "task": row.get("task") or "대기",
                "target": row.get("target") or "-",
                "progress_pct": row.get("progress_pct"),
                "updated_at": updated_at,
                "age_seconds": round(float(age_seconds), 1) if age_seconds is not None else None,
                "stale": stale,
                "evidence": row.get("evidence") or "",
                "next_action": row.get("next_action") or "",
            }
        )

    emergency_halt = bool(policy.get("emergency_halt"))
    day_halted = bool(policy.get("day_halted"))
    delegated_enabled = bool(policy.get("delegated_live_autonomy_enabled"))
    live_execution_enabled = bool(policy.get("live_execution_enabled"))
    live_candidate_enabled = bool(policy.get("live_candidate_enabled"))
    delegated_authorization = build_delegated_live_authorization(policy)
    if emergency_halt or day_halted:
        mode = "운영 중지"
    elif delegated_enabled and live_execution_enabled:
        mode = "위임 실전 감시"
    elif live_candidate_enabled:
        mode = "실전 후보 감시"
    else:
        mode = "연구/Paper"

    return {
        "ok": not bool(policy_error),
        "schema": "codexstock.mcp-instant-overview.v1",
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "response_profile": "instant_memory_only",
        "mode": mode,
        "runtime": {
            "app": "running",
            "scheduler_running": scheduler_running,
            "scheduler_thread_alive": bool(scheduler_thread and scheduler_thread.is_alive()),
            "research_daemon_running": daemon_running,
            "research_daemon_thread_alive": bool(daemon_thread and daemon_thread.is_alive()),
            "last_error": str(getattr(daemon, "last_error", "") or ""),
        },
        "current_task": {
            "phase": activity.get("phase") or ("working" if daemon_running else "idle"),
            "title": activity.get("label") or ("연구 진행" if daemon_running else "대기"),
            "detail": activity.get("detail") or "",
            "target": activity.get("symbol_name") or activity.get("symbol") or "-",
            "progress_pct": activity.get("progress_pct"),
            "updated_at": activity.get("updated_at") or "",
        },
        "order_gates": {
            "emergency_halt": emergency_halt,
            "day_halted": day_halted,
            "buy_blocked": bool(policy.get("buy_blocked")),
            "live_candidate_enabled": live_candidate_enabled,
            "live_execution_enabled": live_execution_enabled,
            "delegated_live_autonomy_enabled": delegated_enabled,
            "delegated_authorized_today": bool(delegated_authorization.get("valid_today")),
            "require_approval": bool(policy.get("require_approval", True)),
        },
        "staff": {
            "count": len(workers),
            "stale_count": stale_workers,
            "workers": workers,
        },
        "details": {
            "quick_status_tool": "codexstock_status(detail='quick')",
            "full_status_tool": "codexstock_status(detail='full')",
            "quick_staff_tool": "codexstock_staff_status(detail='quick')",
            "full_staff_tool": "codexstock_staff_status(detail='full')",
            "meetings_tool": "codexstock_staff_meetings",
        },
        "policy_error": policy_error,
        "read_only": True,
        "live_order_allowed": False,
        "safety": "지피티용 즉시 상태 조회입니다. 원장 재스캔, 계좌 조회, 시세 조회, 실제 주문을 실행하지 않습니다.",
    }


