def _read_telegram_offset() -> int | None:
    try:
        data = json.loads(TELEGRAM_OFFSET_FILE.read_text(encoding="utf-8"))
        return int(data.get("offset"))
    except Exception:
        return None


def _write_telegram_offset(offset: int) -> None:
    TELEGRAM_OFFSET_FILE.parent.mkdir(parents=True, exist_ok=True)
    TELEGRAM_OFFSET_FILE.write_text(json.dumps({"offset": offset}, ensure_ascii=False), encoding="utf-8")


def telegram_receiver_readiness() -> dict[str, object]:
    try:
        status = INTEGRATIONS.status().get("telegram", {})
    except Exception as exc:
        status = {"enabled": False, "configured": False, "dry_run": True, "stub": True, "error": str(exc)}
    if not isinstance(status, dict):
        status = {}
    reasons = []
    if not status.get("enabled"):
        reasons.append("\ud154\ub808\uadf8\ub7a8 \uc218\uc2e0\uc774 \ube44\ud65c\uc131\ud654\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.")
    if not status.get("configured"):
        reasons.append("\ud154\ub808\uadf8\ub7a8 \ud1a0\ud070 \ub610\ub294 \ucc44\ud305 ID\uac00 \uc124\uc815\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.")
    if status.get("dry_run") or status.get("stub"):
        reasons.append("\ud154\ub808\uadf8\ub7a8\uc774 \ub4dc\ub77c\uc774\ub7f0/\uc2a4\ud141 \ubaa8\ub4dc\ub77c \uc2e4\uc81c \uba54\uc2dc\uc9c0\ub97c \ubc1b\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.")
    ready = not reasons
    return {
        "ready": ready,
        "status": status,
        "reason": " ".join(reasons) if reasons else "\ud154\ub808\uadf8\ub7a8 \uc790\ub3d9 \uba85\ub839 \uac10\uc2dc \uc900\ube44 \uc644\ub8cc",
    }


def _telegram_dispatch_had_success(result: dict[str, object]) -> bool:
    dispatches = result.get("dispatches", []) if isinstance(result.get("dispatches"), list) else []
    return any(bool(row.get("sent") or row.get("ok")) for row in dispatches if isinstance(row, dict))


def dispatch_telegram_command_reply_with_retry(source: str, retries: int = 1, delay_seconds: float = 1.2) -> dict[str, object]:
    first = dispatch_telegram_outbox(limit=1, source=source)
    attempts = [first]
    retry_used = False
    if first.get("processed") and not _telegram_dispatch_had_success(first):
        for retry_index in range(max(0, int(retries or 0))):
            retry_used = True
            time.sleep(max(0.1, min(float(delay_seconds or 0), 3.0)))
            retry = dispatch_telegram_outbox(limit=1, source=f"{source}-retry{retry_index + 1}")
            attempts.append(retry)
            if _telegram_dispatch_had_success(retry):
                break
    latest = attempts[-1] if attempts else first
    return {
        **latest,
        "retry_used": retry_used,
        "attempt_count": len(attempts),
        "attempts": attempts,
    }


def _telegram_command_diagnostic_from_handled(handled_item: dict[str, object]) -> dict[str, object]:
    latest_result = handled_item.get("result", {}) if isinstance(handled_item.get("result"), dict) else {}
    latest_sent = handled_item.get("sent", {}) if isinstance(handled_item.get("sent"), dict) else {}
    latest_reply = str(latest_result.get("reply") or "")
    latest_dispatches = latest_sent.get("dispatches", []) if isinstance(latest_sent.get("dispatches"), list) else []
    latest_dispatch_message = ""
    if latest_dispatches and isinstance(latest_dispatches[-1], dict):
        latest_dispatch_message = str(latest_dispatches[-1].get("message") or latest_dispatches[-1].get("status") or "")
    return {
        "created_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "has_command": bool(handled_item),
        "update_id": handled_item.get("update_id", ""),
        "command": handled_item.get("command", ""),
        "reply_preview": latest_reply[:240],
        "reply_ok": bool(latest_result.get("ok", False)) if latest_result else False,
        "sent_ok": bool(_telegram_dispatch_had_success(latest_sent)) if latest_sent else False,
        "retry_used": bool(latest_sent.get("retry_used", False)) if latest_sent else False,
        "attempt_count": int(latest_sent.get("attempt_count", 0) or 0) if latest_sent else 0,
        "dispatch_message": latest_dispatch_message,
    }


def remember_telegram_command_diagnostic(handled_item: dict[str, object]) -> dict[str, object]:
    diagnostic = _telegram_command_diagnostic_from_handled(handled_item)
    _append_jsonl(TELEGRAM_COMMAND_DIAGNOSTIC_FILE, diagnostic)
    _compact_jsonl(TELEGRAM_COMMAND_DIAGNOSTIC_FILE, max_rows=200)
    return diagnostic


def latest_telegram_command_diagnostic() -> dict[str, object]:
    rows = _read_jsonl(TELEGRAM_COMMAND_DIAGNOSTIC_FILE, limit=1)
    if rows:
        latest = dict(rows[-1])
        latest["from_persistent_log"] = True
        return latest
    return {
        "has_command": False,
        "update_id": "",
        "command": "",
        "reply_preview": "",
        "reply_ok": False,
        "sent_ok": False,
        "retry_used": False,
        "attempt_count": 0,
        "dispatch_message": "",
        "from_persistent_log": False,
    }


_POWER_CONTROL_COMMAND_PREFIXES = (
    "컴퓨터 상태",
    "pc 상태",
    "/pc_status",
    "컴퓨터 종료",
    "컴퓨터 꺼",
    "pc 종료",
    "/shutdown",
    "/pc_shutdown",
    "종료확인 ",
    "/confirm ",
    "종료취소",
    "/cancel",
)


def _is_power_control_command(text: str) -> bool:
    normalized = str(text or "").strip().lower()
    return any(normalized == prefix or normalized.startswith(prefix) for prefix in _POWER_CONTROL_COMMAND_PREFIXES)


_POWER_CONTROL_LOCK = threading.Lock()
_POWER_CONTROL_PENDING_CODE = ""
_POWER_CONTROL_PENDING_UNTIL = 0.0


def _handle_power_control_command(text: str) -> dict[str, object] | None:
    global _POWER_CONTROL_PENDING_CODE, _POWER_CONTROL_PENDING_UNTIL
    normalized = str(text or "").strip().lower()
    if not _is_power_control_command(normalized):
        return None

    with _POWER_CONTROL_LOCK:
        if normalized in {"컴퓨터 상태", "pc 상태", "/pc_status"}:
            reply = "미니PC가 켜져 있고 전원 제어 서비스가 정상입니다."
        elif normalized in {"컴퓨터 종료", "컴퓨터 꺼", "pc 종료", "/shutdown", "/pc_shutdown"}:
            _POWER_CONTROL_PENDING_CODE = f"{random.SystemRandom().randrange(1_000_000):06d}"
            _POWER_CONTROL_PENDING_UNTIL = time.time() + 120
            reply = (
                "정말 종료하려면 2분 안에 다음처럼 보내세요:\n"
                f"종료확인 {_POWER_CONTROL_PENDING_CODE}\n\n"
                "취소하려면 '종료취소'라고 보내세요."
            )
        elif normalized in {"종료취소", "/cancel"}:
            _POWER_CONTROL_PENDING_CODE = ""
            _POWER_CONTROL_PENDING_UNTIL = 0.0
            reply = "종료 요청을 취소했습니다."
        elif normalized.startswith("종료확인 ") or normalized.startswith("/confirm "):
            supplied = str(text).split(maxsplit=1)[1].strip() if " " in str(text) else ""
            if (
                _POWER_CONTROL_PENDING_CODE
                and time.time() <= _POWER_CONTROL_PENDING_UNTIL
                and hmac.compare_digest(supplied, _POWER_CONTROL_PENDING_CODE)
            ):
                _POWER_CONTROL_PENDING_CODE = ""
                _POWER_CONTROL_PENDING_UNTIL = 0.0
                return {
                    "ok": True,
                    "reply": "확인됐습니다. 미니PC를 10초 후 정상 종료합니다.",
                    "actions": [],
                    "power_shutdown": True,
                }
            reply = "확인번호가 틀렸거나 2분이 지났습니다. 다시 '컴퓨터 종료'라고 보내세요."
        else:
            return None
    return {"ok": True, "reply": reply, "actions": [], "power_shutdown": False}


def _handle_codexstock_status_command(text: str) -> dict[str, object] | None:
    normalized = re.sub(r"\s+", " ", str(text or "").strip().lower())
    exact = {
        "코덱스스톡은",
        "코덱스스톡 상태",
        "코덱스스톡 상태는",
        "코덱스스톡 켜졌어",
        "코덱스스톡 켜졌니",
        "코덱스스톡 살아있어",
        "/codexstock_status",
    }
    if normalized not in exact and not normalized.startswith("코덱스스톡 상태 "):
        return None

    status = build_autotrade_status_quick()
    scheduler = bool((status.get("scheduler") or {}).get("running"))
    daemon = bool((status.get("daemon") or {}).get("running"))
    blockers = [str(item) for item in status.get("blockers", []) if str(item).strip()]
    reply = (
        "코덱스스톡이 정상 실행 중입니다.\n"
        f"- 서버: {'정상' if status.get('ok') else '점검 필요'}\n"
        f"- 자동운영 스케줄러: {'실행 중' if scheduler else '중지'}\n"
        f"- AI 연구 엔진: {'실행 중' if daemon else '중지'}\n"
        f"- 운영 모드: {status.get('mode', '확인 불가')}"
    )
    if blockers:
        reply += "\n- 현재 제한: " + ", ".join(blockers)
    return {"ok": True, "reply": reply, "actions": []}


def _telegram_conversation_key(message: dict[str, object]) -> str:
    chat = message.get("chat") if isinstance(message.get("chat"), dict) else {}
    sender = message.get("from") if isinstance(message.get("from"), dict) else {}
    return str(chat.get("id") or sender.get("id") or "default")


def _telegram_conversation_context(key: str) -> str:
    with TELEGRAM_CONVERSATION_LOCK:
        rows = list(TELEGRAM_CONVERSATIONS.get(key, ()))
    return "\n".join(
        f"{'사용자' if row.get('role') == 'user' else '똑똑'}: {row.get('text', '')}"
        for row in rows[-8:]
    )


def _remember_telegram_exchange(key: str, user_text: str, reply_text: str) -> None:
    with TELEGRAM_CONVERSATION_LOCK:
        history = TELEGRAM_CONVERSATIONS.setdefault(key, deque(maxlen=12))
        history.append({"role": "user", "text": str(user_text)[:800]})
        history.append({"role": "assistant", "text": str(reply_text)[:1200]})


def poll_telegram_commands_once(timeout: int = 0, source: str = "telegram-poll", offset: int | None = None) -> dict[str, object]:
    readiness = telegram_receiver_readiness()
    if not readiness.get("ready"):
        return {
            "ok": False,
            "message": readiness.get("reason", ""),
            "handled": [],
            "raw_count": 0,
            "next_offset": _read_telegram_offset(),
            "status": readiness.get("status", {}),
            "can_receive": False,
        }

    try:
        safe_timeout = max(0, min(int(timeout or 0), 50))
    except (TypeError, ValueError):
        safe_timeout = 0

    with TELEGRAM_POLL_LOCK:
        next_offset = offset if offset is not None else _read_telegram_offset()
        updates = INTEGRATIONS.telegram_updates(offset=next_offset, timeout=safe_timeout)
        handled = []
        max_update_id = next_offset - 1 if next_offset else None
        for update in updates.get("updates", []):
            try:
                update_id = int(update.get("update_id", 0))
            except (TypeError, ValueError):
                update_id = 0
            if update_id:
                max_update_id = max(update_id, max_update_id or update_id)
            message = update.get("message") or update.get("edited_message") or {}
            text = str(message.get("text", "")).strip()
            if not text:
                continue
            conversation_key = _telegram_conversation_key(message)
            conversation_context = _telegram_conversation_context(conversation_key)
            result = _handle_codexstock_status_command(text)
            if result is None:
                result = _handle_power_control_command(text)
            if result is None:
                try:
                    result = execute_agent_command(
                        text,
                        source="telegram",
                        conversation_context=conversation_context,
                    )
                except Exception as exc:
                    result = {"ok": False, "reply": f"\uba85\ub839 \ucc98\ub9ac \uc2e4\ud328: {exc}", "actions": []}
            _remember_telegram_exchange(conversation_key, text, str(result.get("reply", "")))
            reply_source = f"{source}-{update_id}" if update_id else source
            record = OPS.queue_telegram(
                str(result.get("reply", "")),
                message_type="command_reply",
                source=reply_source,
                metadata={"command": text, "update_id": update_id, "poll_source": source},
            )
            sent = dispatch_telegram_command_reply_with_retry(source=f"{source}-reply")
            handled_item = {"update_id": update_id, "command": text, "result": result, "record": record, "sent": sent}
            handled_item["diagnostic"] = remember_telegram_command_diagnostic(handled_item)
            handled.append(handled_item)
            if result.get("power_shutdown") and _telegram_dispatch_had_success(sent):
                subprocess.Popen(
                    ["shutdown.exe", "/s", "/t", "10", "/d", "p:0:0", "/c", "Telegram authorized shutdown"],
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
        if max_update_id is not None:
            next_offset = max_update_id + 1
            _write_telegram_offset(next_offset)
        return {
            "ok": bool(updates.get("ok", False)),
            "message": updates.get("message"),
            "handled": handled,
            "raw_count": updates.get("raw_count", 0),
            "next_offset": next_offset,
            "status": updates.get("status", readiness.get("status", {})),
            "can_receive": True,
        }


def quick_agent_brief() -> dict[str, object]:
    market = MARKET.tick()
    movers = sorted(market.get("quotes", []), key=lambda row: row.get("change_pct", 0), reverse=True)
    top = movers[0] if movers else {"symbol": "-", "change_pct": 0}
    weak = movers[-1] if movers else {"symbol": "-", "change_pct": 0}
    quant = QUANTKING.full_report()
    regime = quant.get("economic", {}).get("regime", "-")
    hedge_rows = quant.get("hedge", {}).get("rows", [])
    hedge = hedge_rows[0] if hedge_rows else {"name": "-", "current_signal": "-"}
    return {
        "generated_at": market.get("time"),
        "headline": "AI 트레이더 빠른 운용 브리핑입니다.",
        "top": top,
        "weak": weak,
        "regime": regime,
        "hedge": hedge,
        "order_allowed": False,
    }


