def _public_market_row(row: dict[str, object]) -> dict[str, object]:
    return {
        "symbol": row.get("symbol", ""),
        "name": row.get("name", ""),
        "market": row.get("market", ""),
        "change_pct": row.get("change_pct", 0),
        "amount": row.get("amount", 0),
        "marcap": row.get("marcap", 0),
        "source": row.get("source", ""),
    }


def analyze_themes_from_rows(rows: list[dict[str, object]]) -> list[dict[str, object]]:
    themes = []
    for rule in THEME_RULES:
        matched = []
        for row in rows:
            haystack = f"{row.get('name', '')} {row.get('symbol', '')}".upper()
            if any(keyword.upper() in haystack for keyword in rule["keywords"]):
                matched.append(row)
        if not matched:
            continue
        amount = sum(float(row.get("amount", 0)) for row in matched)
        avg_change = sum(float(row.get("change_pct", 0)) for row in matched) / len(matched)
        leaders = sorted(matched, key=lambda item: (float(item.get("change_pct", 0)), float(item.get("amount", 0))), reverse=True)[:5]
        themes.append(
            {
                "id": rule["id"],
                "name": rule["name"],
                "count": len(matched),
                "avg_change_pct": round(avg_change, 2),
                "amount": round(amount, 0),
                "leaders": [_public_market_row(row) for row in leaders],
                "mission": "강한 테마는 공시/실적/백테스트 큐로 넘기고, 약한 테마는 리스크 관찰 목록에 둡니다.",
            }
        )
    return sorted(themes, key=lambda item: (float(item["avg_change_pct"]), float(item["amount"])), reverse=True)


def _intraday_theme_map_from_rows(rows: list[dict[str, object]]) -> dict[str, dict[str, object]]:
    """단타용 주도테마/대장주 맵.

    홍인기/불개미식 공개 원칙을 코드화한 필터입니다. 같은 테마에서 여러 종목이
    같이 움직이고, 그 안에서 거래대금이 몰리는 대장주만 단타 후보로 인정합니다.
    """
    symbol_map: dict[str, dict[str, object]] = {}
    for theme in analyze_themes_from_rows(rows):
        leaders = [row for row in theme.get("leaders", []) if isinstance(row, dict)]
        theme_amount = _number(theme.get("amount"))
        avg_change = _number(theme.get("avg_change_pct"))
        count = int(_number(theme.get("count")))
        theme_confirmed = count >= 3 and avg_change >= 1.0 and theme_amount >= 80_000_000_000
        for index, leader in enumerate(leaders, start=1):
            symbol = str(leader.get("symbol", "")).upper().strip()
            if not symbol:
                continue
            leader_amount = _number(leader.get("amount"))
            leader_change = _number(leader.get("change_pct"))
            confirmed = bool(theme_confirmed and index <= 3 and leader_amount >= 20_000_000_000 and leader_change >= 0.5)
            entry = {
                "id": theme.get("id", ""),
                "name": theme.get("name", ""),
                "confirmed": confirmed,
                "theme_confirmed": theme_confirmed,
                "leader_rank": index,
                "theme_count": count,
                "theme_avg_change_pct": round(avg_change, 2),
                "theme_amount": round(theme_amount, 0),
                "leader_amount": round(leader_amount, 0),
                "leader_change_pct": round(leader_change, 2),
                "rule": "같은 테마 3종목 이상 상승 + 테마 거래대금 800억 이상 + 대장주 후보 거래대금 200억 이상",
            }
            current = symbol_map.get(symbol)
            if not current:
                symbol_map[symbol] = entry
                continue
            current_key = (1 if current.get("confirmed") else 0, -int(_number(current.get("leader_rank"))), _number(current.get("theme_amount")))
            next_key = (1 if entry.get("confirmed") else 0, -index, theme_amount)
            if next_key > current_key:
                symbol_map[symbol] = entry
    return symbol_map


def _theme_rule_for_symbol_name(symbol: str, name: str = "") -> dict[str, object] | None:
    haystack = f"{symbol or ''} {name or ''}".upper()
    auto_keywords = ("로봇", "자율주행", "모비스", "현대차", "기아")
    if any(keyword.upper() in haystack for keyword in auto_keywords):
        return next((rule for rule in THEME_RULES if rule.get("id") == "auto"), None)
    for rule in THEME_RULES:
        if any(str(keyword).upper() in haystack for keyword in rule.get("keywords", [])):
            return rule
    return None


def _live_buy_theme_peer_gate(
    symbol: str,
    selection: dict[str, object] | None = None,
    *,
    max_notional: float = 0.0,
    quantity: float = 1.0,
) -> dict[str, object]:
    """AI 자동매수 후보가 같은 테마의 더 강한 후보보다 열위인지 점검한다."""
    normalized = str(symbol or "").upper().strip()
    selection = selection if isinstance(selection, dict) else {}
    if not (normalized.isdigit() and len(normalized) == 6):
        return {"ok": True, "state": "skip", "detail": "국내 6자리 종목이 아니라 테마 비교를 생략합니다."}
    try:
        work_date, rows = fetch_kr_market_rows()
    except Exception as exc:
        return {"ok": False, "state": "data_error", "detail": f"KRX 테마 비교 데이터 조회 실패: {exc}", "alternatives": []}
    current_row = next((row for row in rows if isinstance(row, dict) and str(row.get("symbol", "")).upper().zfill(6) == normalized), {})
    lookup_name = ""
    if not current_row:
        try:
            lookup = (_lookup_symbols([normalized]) or [{}])[0]
            lookup_name = str(lookup.get("name") or "")
        except Exception:
            lookup_name = ""
    current_name = str(current_row.get("name") or selection.get("name") or lookup_name or normalized)
    theme_rule = _theme_rule_for_symbol_name(normalized, current_name)
    if not theme_rule:
        return {"ok": True, "state": "no_theme", "detail": f"{current_name}은(는) 현재 등록 테마 비교 대상이 아닙니다."}

    max_ticket = max(0.0, float(max_notional or 0.0)) * max(1.0, float(quantity or 1.0))
    min_price = 2_000.0
    min_amount = 10_000_000_000.0
    min_marcap = 50_000_000_000.0
    peer_rows: list[dict[str, object]] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        row_symbol = str(row.get("symbol", "")).upper().zfill(6)
        row_name = str(row.get("name") or row_symbol)
        row_rule = _theme_rule_for_symbol_name(row_symbol, row_name)
        if not row_rule or row_rule.get("id") != theme_rule.get("id"):
            continue
        price = _number(row.get("close") or row.get("price"))
        amount = _number(row.get("amount"))
        marcap = _number(row.get("marcap") or row.get("market_cap"))
        change_pct = _number(row.get("change_pct"))
        if price <= 0:
            continue
        peer_rows.append(
            {
                "symbol": row_symbol,
                "name": row_name,
                "price": round(price, 2),
                "change_pct": round(change_pct, 2),
                "amount": round(amount, 0),
                "amount_eok": round(amount / 100_000_000, 1),
                "marcap": round(marcap, 0),
                "marcap_eok": round(marcap / 100_000_000, 1),
                "affordable": bool(not max_ticket or price <= max_ticket),
                "strong_enough": bool(price >= min_price and amount >= min_amount and (not marcap or marcap >= min_marcap) and change_pct >= 0.5),
            }
        )
    peer_rows.sort(key=lambda row: (_number(row.get("change_pct")), _number(row.get("amount"))), reverse=True)
    current = next((row for row in peer_rows if row.get("symbol") == normalized), None)
    if current is None:
        current = {
            "symbol": normalized,
            "name": current_name,
            "price": _number(current_row.get("close") if isinstance(current_row, dict) else 0),
            "change_pct": _number(current_row.get("change_pct") if isinstance(current_row, dict) else 0),
            "amount": _number(current_row.get("amount") if isinstance(current_row, dict) else 0),
            "amount_eok": round(_number(current_row.get("amount") if isinstance(current_row, dict) else 0) / 100_000_000, 1),
            "marcap": _number(current_row.get("marcap") if isinstance(current_row, dict) else 0),
            "marcap_eok": round(_number(current_row.get("marcap") if isinstance(current_row, dict) else 0) / 100_000_000, 1),
            "affordable": True,
            "strong_enough": False,
        }
    alternatives = [
        row for row in peer_rows
        if row.get("symbol") != normalized
        and row.get("affordable")
        and row.get("strong_enough")
    ][:5]
    stronger_alternatives = [
        row for row in alternatives
        if _number(row.get("change_pct")) >= _number(current.get("change_pct")) + 2.0
        and _number(row.get("amount")) >= max(min_amount, _number(current.get("amount")) * 2.0)
    ]
    block_reasons: list[str] = []
    current_price = _number(current.get("price"))
    current_amount = _number(current.get("amount"))
    current_marcap = _number(current.get("marcap"))
    current_change = _number(current.get("change_pct"))
    if current_price and current_price < min_price:
        block_reasons.append(f"초저가 후보: {_format_krw(current_price)} < {_format_krw(min_price)}")
    if current_amount < min_amount:
        block_reasons.append(f"거래대금 약함: {current_amount / 100_000_000:,.1f}억 < {min_amount / 100_000_000:,.0f}억")
    if current_marcap and current_marcap < min_marcap:
        block_reasons.append(f"시총 작음: {current_marcap / 100_000_000:,.1f}억 < {min_marcap / 100_000_000:,.0f}억")
    if current_change < 0.3:
        block_reasons.append(f"당일 주도성 약함: {current_change:+.2f}%")
    if stronger_alternatives:
        top = stronger_alternatives[0]
        block_reasons.append(
            f"같은 {theme_rule.get('name')} 테마에 더 강한 후보 {top.get('name')} "
            f"{_number(top.get('change_pct')):+.2f}%·{_number(top.get('amount_eok')):,.1f}억"
        )
    ok = not block_reasons
    top_peer = peer_rows[0] if peer_rows else {}
    if ok:
        detail = (
            f"{current.get('name')}은(는) {theme_rule.get('name')} 테마 내 비교 통과: "
            f"{current_change:+.2f}%, 거래대금 {current_amount / 100_000_000:,.1f}억"
        )
    else:
        detail = " / ".join(block_reasons[:4])
    return {
        "ok": ok,
        "state": "pass" if ok else "blocked",
        "work_date": work_date,
        "theme": {"id": theme_rule.get("id"), "name": theme_rule.get("name")},
        "current": current,
        "top_peer": top_peer,
        "alternatives": alternatives,
        "block_reasons": block_reasons[:5],
        "detail": detail,
        "criteria": {
            "min_price": min_price,
            "min_amount": min_amount,
            "min_marcap": min_marcap,
            "max_ticket": max_ticket,
        },
    }


def _agent_cache_load(path: Path, ttl_seconds: int) -> dict[str, object] | None:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        saved_at = float(data.get("saved_at", 0))
        if time.time() - saved_at <= ttl_seconds:
            return data
    except Exception:
        return None
    return None


def _agent_cache_save(
    path: Path,
    payload: dict[str, object],
    *,
    saved_at: float | None = None,
) -> None:
    temp_name = ""
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        data = {"saved_at": float(saved_at if saved_at is not None else time.time()), "payload": payload}
        with tempfile.NamedTemporaryFile(
            "w",
            encoding="utf-8",
            dir=path.parent,
            prefix=f".{path.name}.",
            suffix=".tmp",
            delete=False,
        ) as handle:
            temp_name = handle.name
            json.dump(data, handle, ensure_ascii=False, indent=2)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_name, path)
        temp_name = ""
    except Exception:
        pass
    finally:
        if temp_name:
            try:
                Path(temp_name).unlink(missing_ok=True)
            except OSError:
                pass


def _read_jsonl_unlocked(path: Path, limit: int | None = None) -> list[dict[str, object]]:
    if not path.exists():
        return []
    safe_limit = int(limit or 0)
    if safe_limit > 0:
        newest_rows: list[dict[str, object]] = []
        with path.open("rb") as handle:
            handle.seek(0, os.SEEK_END)
            position = handle.tell()
            pending = b""
            while position > 0 and len(newest_rows) < safe_limit:
                read_size = min(64 * 1024, position)
                position -= read_size
                handle.seek(position)
                pending = handle.read(read_size) + pending
                lines = pending.split(b"\n")
                pending = lines[0]
                for raw_line in reversed(lines[1:]):
                    clean = raw_line.decode("utf-8", errors="ignore").strip().lstrip("\ufeff")
                    if not clean:
                        continue
                    try:
                        item = json.loads(clean)
                    except json.JSONDecodeError:
                        continue
                    if isinstance(item, dict):
                        newest_rows.append(item)
                        if len(newest_rows) >= safe_limit:
                            break
            if position == 0 and pending and len(newest_rows) < safe_limit:
                clean = pending.decode("utf-8", errors="ignore").strip().lstrip("\ufeff")
                if clean:
                    try:
                        item = json.loads(clean)
                    except json.JSONDecodeError:
                        item = None
                    if isinstance(item, dict):
                        newest_rows.append(item)
        return list(reversed(newest_rows[:safe_limit]))
    rows: list[dict[str, object]] | deque[dict[str, object]]
    rows = []
    with path.open("r", encoding="utf-8", errors="ignore") as handle:
        lines = handle
        for line in lines:
            clean = line.strip().lstrip("\ufeff")
            if not clean:
                continue
            try:
                item = json.loads(clean)
            except json.JSONDecodeError:
                continue
            if isinstance(item, dict):
                rows.append(item)
    return list(rows)


def _read_jsonl(path: Path, limit: int | None = None) -> list[dict[str, object]]:
    """Keep Windows readers from racing atomic JSONL compaction/replacement."""
    with _jsonl_io_lock(path):
        return _read_jsonl_unlocked(path, limit=limit)


def _read_jsonl_latest_by_ids(
    path: Path,
    record_ids: list[str] | set[str],
    *,
    id_field: str = "id",
) -> tuple[list[dict[str, object]], dict[str, object]]:
    """Read only the newest requested records, stopping the reverse scan once found."""
    ordered_ids = list(
        dict.fromkeys(
            str(value or "").strip().upper()
            for value in record_ids
            if str(value or "").strip()
        )
    )
    wanted = set(ordered_ids)
    file_size = path.stat().st_size if path.is_file() else 0
    if not wanted or not file_size:
        return [], {
            "strategy": "reverse_targeted_jsonl_scan_v1",
            "requested_id_count": len(wanted),
            "found_id_count": 0,
            "missing_id_count": len(wanted),
            "file_size_bytes": file_size,
            "bytes_scanned": 0,
            "scan_pct": 0.0,
            "stopped_after_all_ids_found": not wanted,
        }
    found: dict[str, dict[str, object]] = {}
    bytes_scanned = 0
    with path.open("rb") as handle:
        handle.seek(0, os.SEEK_END)
        position = handle.tell()
        pending = b""
        while position > 0 and len(found) < len(wanted):
            read_size = min(64 * 1024, position)
            position -= read_size
            handle.seek(position)
            pending = handle.read(read_size) + pending
            bytes_scanned += read_size
            lines = pending.split(b"\n")
            pending = lines[0]
            for raw_line in reversed(lines[1:]):
                clean = raw_line.decode("utf-8", errors="ignore").strip().lstrip("\ufeff")
                if not clean:
                    continue
                try:
                    item = json.loads(clean)
                except json.JSONDecodeError:
                    continue
                if not isinstance(item, dict):
                    continue
                record_id = str(item.get(id_field) or "").strip().upper()
                if record_id in wanted and record_id not in found:
                    found[record_id] = item
                    if len(found) >= len(wanted):
                        break
        if position == 0 and pending and len(found) < len(wanted):
            clean = pending.decode("utf-8", errors="ignore").strip().lstrip("\ufeff")
            if clean:
                try:
                    item = json.loads(clean)
                except json.JSONDecodeError:
                    item = None
                if isinstance(item, dict):
                    record_id = str(item.get(id_field) or "").strip().upper()
                    if record_id in wanted and record_id not in found:
                        found[record_id] = item
    rows = [found[record_id] for record_id in ordered_ids if record_id in found]
    return rows, {
        "strategy": "reverse_targeted_jsonl_scan_v1",
        "requested_id_count": len(wanted),
        "found_id_count": len(found),
        "missing_id_count": len(wanted) - len(found),
        "file_size_bytes": file_size,
        "bytes_scanned": bytes_scanned,
        "scan_pct": round(bytes_scanned / file_size * 100.0, 4) if file_size else 0.0,
        "stopped_after_all_ids_found": len(found) == len(wanted),
    }


RUNTIME_EVENT_INDEX_CONNECTION: sqlite3.Connection | None = None
RUNTIME_EVENT_INDEX_MIGRATION: dict[str, object] = {
    "deduplicated_rows": 0,
    "unique_payload_index_ready": False,
}
HOT_LOG_STORAGE_CACHE: dict[str, object] = {"saved_at": 0.0, "payload": {}}


def _runtime_event_index_connection() -> sqlite3.Connection:
    global RUNTIME_EVENT_INDEX_CONNECTION
    if RUNTIME_EVENT_INDEX_CONNECTION is None:
        RUNTIME_EVENT_INDEX_DB.parent.mkdir(parents=True, exist_ok=True)
        RUNTIME_EVENT_INDEX_CONNECTION = sqlite3.connect(
            RUNTIME_EVENT_INDEX_DB,
            timeout=5.0,
            check_same_thread=False,
        )
        RUNTIME_EVENT_INDEX_CONNECTION.execute("PRAGMA journal_mode=WAL")
        RUNTIME_EVENT_INDEX_CONNECTION.execute("PRAGMA synchronous=NORMAL")
        RUNTIME_EVENT_INDEX_CONNECTION.execute("PRAGMA busy_timeout=5000")
        RUNTIME_EVENT_INDEX_CONNECTION.execute(
            """
            CREATE TABLE IF NOT EXISTS jsonl_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                source_path TEXT NOT NULL,
                source_name TEXT NOT NULL,
                event_date TEXT,
                created_at TEXT,
                symbol TEXT,
                kind TEXT,
                status TEXT,
                payload_json TEXT NOT NULL,
                inserted_at TEXT NOT NULL,
                payload_hash TEXT
            )
            """
        )
        RUNTIME_EVENT_INDEX_CONNECTION.execute(
            "CREATE INDEX IF NOT EXISTS idx_jsonl_events_source_id ON jsonl_events(source_name, id)"
        )
        RUNTIME_EVENT_INDEX_CONNECTION.execute(
            "CREATE INDEX IF NOT EXISTS idx_jsonl_events_payload_hash ON jsonl_events(source_name, payload_hash)"
        )
        RUNTIME_EVENT_INDEX_CONNECTION.execute(
            "CREATE INDEX IF NOT EXISTS idx_jsonl_events_source_date_id ON jsonl_events(source_name, event_date, id)"
        )
        RUNTIME_EVENT_INDEX_CONNECTION.execute(
            "CREATE INDEX IF NOT EXISTS idx_jsonl_events_source_symbol_id ON jsonl_events(source_name, symbol, id)"
        )
        RUNTIME_EVENT_INDEX_CONNECTION.execute(
            "CREATE INDEX IF NOT EXISTS idx_jsonl_events_source_status_id ON jsonl_events(source_name, status, id)"
        )
        RUNTIME_EVENT_INDEX_CONNECTION.execute(
            """
            CREATE TABLE IF NOT EXISTS jsonl_source_meta (
                source_name TEXT PRIMARY KEY,
                source_path TEXT NOT NULL,
                source_size_bytes INTEGER NOT NULL,
                source_mtime_ns INTEGER NOT NULL,
                source_row_count INTEGER NOT NULL,
                indexed_row_count INTEGER NOT NULL,
                coverage_mode TEXT NOT NULL,
                synchronized_at TEXT NOT NULL
            )
            """
        )
        try:
            RUNTIME_EVENT_INDEX_CONNECTION.execute(
                """
                CREATE UNIQUE INDEX IF NOT EXISTS uq_jsonl_events_source_payload_hash
                ON jsonl_events(source_name, payload_hash)
                WHERE payload_hash IS NOT NULL AND payload_hash <> ''
                """
            )
        except sqlite3.IntegrityError:
            cursor = RUNTIME_EVENT_INDEX_CONNECTION.execute(
                """
                DELETE FROM jsonl_events
                WHERE payload_hash IS NOT NULL
                  AND payload_hash <> ''
                  AND id NOT IN (
                      SELECT MIN(id)
                      FROM jsonl_events
                      WHERE payload_hash IS NOT NULL AND payload_hash <> ''
                      GROUP BY source_name, payload_hash
                  )
                """
            )
            RUNTIME_EVENT_INDEX_MIGRATION["deduplicated_rows"] = max(0, int(cursor.rowcount or 0))
            RUNTIME_EVENT_INDEX_CONNECTION.execute(
                """
                CREATE UNIQUE INDEX IF NOT EXISTS uq_jsonl_events_source_payload_hash
                ON jsonl_events(source_name, payload_hash)
                WHERE payload_hash IS NOT NULL AND payload_hash <> ''
                """
            )
        RUNTIME_EVENT_INDEX_MIGRATION["unique_payload_index_ready"] = True
        RUNTIME_EVENT_INDEX_CONNECTION.commit()
    return RUNTIME_EVENT_INDEX_CONNECTION


def _runtime_event_source_stat(path: Path) -> tuple[int, int]:
    try:
        stat = path.stat()
        return int(stat.st_size), int(stat.st_mtime_ns)
    except OSError:
        return 0, 0


def _runtime_event_index_source_allowed(path: Path) -> bool:
    """Only top-level authoritative runtime JSONL files may enter the shared index."""
    try:
        target = path.resolve()
        root = USER_DATA_ROOT.resolve()
        database_root = RUNTIME_EVENT_INDEX_DB.resolve().parent
    except OSError:
        return False
    return (
        target.suffix.lower() == ".jsonl"
        and target.parent == root
        and database_root == root
    )


def _runtime_event_index_source_meta_snapshot(
    path: Path,
) -> tuple[tuple[object, ...] | None, int, int]:
    """Recheck one source under the same lock order used by append and compaction."""
    with _jsonl_io_lock(path):
        with RUNTIME_EVENT_INDEX_LOCK:
            connection = _runtime_event_index_connection()
            meta = connection.execute(
                """
                SELECT source_size_bytes, source_mtime_ns, source_row_count,
                       indexed_row_count, coverage_mode, synchronized_at
                FROM jsonl_source_meta WHERE source_name=?
                """,
                (path.name,),
            ).fetchone()
            size_bytes, mtime_ns = _runtime_event_source_stat(path)
    return (tuple(meta) if meta else None), size_bytes, mtime_ns


def _runtime_event_index_update_meta_unlocked(
    connection: sqlite3.Connection,
    path: Path,
    *,
    source_row_count: int,
    indexed_row_count: int,
    coverage_mode: str,
) -> None:
    size_bytes, mtime_ns = _runtime_event_source_stat(path)
    connection.execute(
        """
        INSERT INTO jsonl_source_meta (
            source_name, source_path, source_size_bytes, source_mtime_ns,
            source_row_count, indexed_row_count, coverage_mode, synchronized_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(source_name) DO UPDATE SET
            source_path=excluded.source_path,
            source_size_bytes=excluded.source_size_bytes,
            source_mtime_ns=excluded.source_mtime_ns,
            source_row_count=excluded.source_row_count,
            indexed_row_count=excluded.indexed_row_count,
            coverage_mode=excluded.coverage_mode,
            synchronized_at=excluded.synchronized_at
        """,
        (
            path.name,
            str(path),
            size_bytes,
            mtime_ns,
            max(0, int(source_row_count)),
            max(0, int(indexed_row_count)),
            str(coverage_mode or "partial"),
            datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        ),
    )


def _runtime_event_index_replace_source_unlocked(
    connection: sqlite3.Connection,
    path: Path,
    rows: list[dict[str, object]],
) -> dict[str, int]:
    before = int(
        connection.execute(
            "SELECT COUNT(*) FROM jsonl_events WHERE source_name=?", (path.name,)
        ).fetchone()[0]
        or 0
    )
    connection.execute("DELETE FROM jsonl_events WHERE source_name=?", (path.name,))
    inserted = 0
    for payload in rows:
        if isinstance(payload, dict) and _runtime_event_index_insert_unlocked(connection, path, payload):
            inserted += 1
    _runtime_event_index_update_meta_unlocked(
        connection,
        path,
        source_row_count=len(rows),
        indexed_row_count=inserted,
        coverage_mode="full",
    )
    return {"before": before, "after": inserted, "stale_removed": max(0, before - inserted)}


def _runtime_event_index_replace_source_from_jsonl_unlocked(
    connection: sqlite3.Connection,
    path: Path,
) -> dict[str, int]:
    """Rebuild one source without materializing a potentially huge JSONL file."""
    before = int(
        connection.execute(
            "SELECT COUNT(*) FROM jsonl_events WHERE source_name=?", (path.name,)
        ).fetchone()[0]
        or 0
    )
    savepoint = "runtime_event_source_rebuild"
    connection.execute(f"SAVEPOINT {savepoint}")
    inserted = valid_rows = invalid_rows = blank_rows = 0
    try:
        connection.execute("DELETE FROM jsonl_events WHERE source_name=?", (path.name,))
        with path.open("r", encoding="utf-8", errors="ignore") as handle:
            for raw_line in handle:
                clean = raw_line.strip().lstrip("\ufeff")
                if not clean:
                    blank_rows += 1
                    continue
                try:
                    payload = json.loads(clean)
                except json.JSONDecodeError:
                    invalid_rows += 1
                    continue
                if not isinstance(payload, dict):
                    invalid_rows += 1
                    continue
                valid_rows += 1
                if _runtime_event_index_insert_unlocked(connection, path, payload):
                    inserted += 1
        _runtime_event_index_update_meta_unlocked(
            connection,
            path,
            source_row_count=valid_rows,
            indexed_row_count=inserted,
            coverage_mode="full",
        )
        connection.execute(f"RELEASE SAVEPOINT {savepoint}")
    except Exception:
        connection.execute(f"ROLLBACK TO SAVEPOINT {savepoint}")
        connection.execute(f"RELEASE SAVEPOINT {savepoint}")
        raise
    return {
        "before": before,
        "after": inserted,
        "source_row_count": valid_rows,
        "invalid_row_count": invalid_rows,
        "blank_row_count": blank_rows,
        "stale_removed": max(0, before - inserted),
    }


def _runtime_event_index_prune_untrusted_sources_unlocked(
    connection: sqlite3.Connection,
    valid_paths: list[Path],
) -> dict[str, object]:
    """Remove derived rows whose source path is missing or outside the runtime root."""
    valid_by_name = {path.name: path.resolve() for path in valid_paths}
    meta_rows = connection.execute(
        "SELECT source_name, source_path FROM jsonl_source_meta"
    ).fetchall()
    event_rows = connection.execute(
        "SELECT DISTINCT source_name, source_path FROM jsonl_events"
    ).fetchall()
    untrusted_names: set[str] = set()
    rebuild_names: set[str] = set()
    for source_name, source_path in [*meta_rows, *event_rows]:
        name = str(source_name or "")
        expected = valid_by_name.get(name)
        try:
            actual = Path(str(source_path or "")).resolve()
        except OSError:
            actual = Path(str(source_path or "")).absolute()
        if expected is None or os.path.normcase(str(actual)) != os.path.normcase(str(expected)):
            untrusted_names.add(name)
            if expected is not None:
                rebuild_names.add(name)
    removed_rows = 0
    for name in sorted(untrusted_names):
        cursor = connection.execute("DELETE FROM jsonl_events WHERE source_name=?", (name,))
        removed_rows += max(0, int(cursor.rowcount or 0))
        connection.execute("DELETE FROM jsonl_source_meta WHERE source_name=?", (name,))
    return {
        "removed_source_count": len(untrusted_names),
        "removed_event_row_count": removed_rows,
        "removed_source_names": sorted(untrusted_names),
        "rebuild_source_names": sorted(rebuild_names),
    }


def _runtime_event_index_note_append_unlocked(
    connection: sqlite3.Connection,
    path: Path,
    *,
    inserted: bool,
) -> None:
    meta = connection.execute(
        "SELECT source_row_count, indexed_row_count, coverage_mode FROM jsonl_source_meta WHERE source_name=?",
        (path.name,),
    ).fetchone()
    if meta and str(meta[2] or "") == "full":
        _runtime_event_index_update_meta_unlocked(
            connection,
            path,
            source_row_count=int(meta[0] or 0) + 1,
            indexed_row_count=int(meta[1] or 0) + (1 if inserted else 0),
            coverage_mode="full",
        )
        return
    indexed_count = int(
        connection.execute(
            "SELECT COUNT(*) FROM jsonl_events WHERE source_name=?", (path.name,)
        ).fetchone()[0]
        or 0
    )
    _runtime_event_index_update_meta_unlocked(
        connection,
        path,
        source_row_count=0,
        indexed_row_count=indexed_count,
        coverage_mode="partial",
    )


def _runtime_event_index_insert_unlocked(
    connection: sqlite3.Connection, path: Path, payload: dict[str, object]
) -> bool:
    payload_hash = jsonl_payload_hash(payload)
    compact_payload = runtime_event_index_payload(path, payload)
    created_at = jsonl_event_first_value(
        payload,
        "generated_at",
        "created_at",
        "submitted_at",
        "detected_at",
        "updated_at",
        "date",
    )
    kind = jsonl_event_first_value(payload, "type", "kind", "event", "mode") or path.stem
    cursor = connection.execute(
        """
        INSERT OR IGNORE INTO jsonl_events (
            source_path, source_name, event_date, created_at, symbol, kind, status,
            payload_json, inserted_at, payload_hash
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            str(path),
            path.name,
            jsonl_event_payload_date(payload),
            str(created_at or ""),
            jsonl_event_payload_symbol(payload),
            str(kind),
            jsonl_event_status_value(payload),
            json.dumps(compact_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
            datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
            payload_hash,
        ),
    )
    return cursor.rowcount > 0


def _mirror_runtime_event_to_sqlite(path: Path, payload: dict[str, object]) -> bool:
    if not _runtime_event_index_source_allowed(path):
        return False
    try:
        with RUNTIME_EVENT_INDEX_LOCK:
            connection = _runtime_event_index_connection()
            inserted = _runtime_event_index_insert_unlocked(connection, path, payload)
            _runtime_event_index_note_append_unlocked(connection, path, inserted=inserted)
            connection.commit()
            return inserted
    except (OSError, sqlite3.Error, TypeError, ValueError):
        return False


def _synchronize_runtime_event_index_after_rewrite(
    path: Path,
    rows: list[dict[str, object]],
) -> bool:
    """Keep the derived SQLite index aligned after an atomic JSONL rewrite."""
    if not _runtime_event_index_source_allowed(path):
        return False
    try:
        with RUNTIME_EVENT_INDEX_LOCK:
            connection = _runtime_event_index_connection()
            _runtime_event_index_replace_source_unlocked(connection, path, rows)
            connection.commit()
        return True
    except (OSError, sqlite3.Error, TypeError, ValueError):
        # Readers detect the stale file signature and safely fall back to JSONL.
        return False


def _append_jsonl(path: Path, payload: dict[str, object]) -> None:
    global HISTORICAL_REPLAY_SCORE_GATE_CACHE
    path.parent.mkdir(parents=True, exist_ok=True)
    line = json.dumps(payload, ensure_ascii=False, sort_keys=True) + "\n"
    with _jsonl_io_lock(path):
        with path.open("a", encoding="utf-8") as handle:
            handle.write(line)
            handle.flush()
        _mirror_runtime_event_to_sqlite(path, payload)
    target = path.resolve()
    milestone_path = HISTORICAL_REPLAY_EVIDENCE_MILESTONE_FILE.resolve()
    ledger_path = HISTORICAL_REPLAY_REGENERATION_FILE.resolve()
    replay_path = HISTORICAL_REPLAY_FILE.resolve()
    cached_index = (
        HISTORICAL_REPLAY_SCORE_GATE_CACHE[1]
        if HISTORICAL_REPLAY_SCORE_GATE_CACHE
        and isinstance(HISTORICAL_REPLAY_SCORE_GATE_CACHE[1], dict)
        else {}
    )
    replacements = (
        cached_index.get("replacements")
        if isinstance(cached_index.get("replacements"), dict)
        else {}
    )
    affects_certified_scope = target == milestone_path
    if target == ledger_path:
        source_id = str(payload.get("source_replay_id") or "").strip().upper()
        affects_certified_scope = source_id in replacements
    elif target == replay_path:
        replay_id = str(payload.get("id") or "").strip().upper()
        affects_certified_scope = any(
            str(row.get("new_replay_id") or "").strip().upper() == replay_id
            for row in replacements.values()
            if isinstance(row, dict)
        )
    if affects_certified_scope:
        with HISTORICAL_REPLAY_SCORE_GATE_LOCK:
            HISTORICAL_REPLAY_SCORE_GATE_CACHE = None
        with AI_TOURNAMENT_STANDINGS_CACHE_LOCK:
            AI_TOURNAMENT_STANDINGS_CACHE.clear()


def build_runtime_storage_status() -> dict[str, object]:
    jsonl_paths = sorted(USER_DATA_ROOT.glob("*.jsonl"), key=lambda path: path.name.lower())
    counts: dict[str, int] = {}
    meta_by_source: dict[str, tuple[object, ...]] = {}
    source_locations: list[tuple[object, object]] = []
    total_indexed = 0
    index_query_error = ""
    try:
        with RUNTIME_EVENT_INDEX_LOCK:
            connection = _runtime_event_index_connection()
            rows = connection.execute(
                "SELECT source_name, COUNT(*) FROM jsonl_events GROUP BY source_name"
            ).fetchall()
            meta_rows = connection.execute(
                """
                SELECT source_name, source_size_bytes, source_mtime_ns, source_row_count,
                       indexed_row_count, coverage_mode, synchronized_at
                FROM jsonl_source_meta
                """
            ).fetchall()
            source_locations = connection.execute(
                "SELECT source_name, source_path FROM jsonl_source_meta "
                "UNION SELECT DISTINCT source_name, source_path FROM jsonl_events"
            ).fetchall()
        counts = {str(name): int(count) for name, count in rows}
        meta_by_source = {str(row[0]): tuple(row[1:]) for row in meta_rows}
        total_indexed = sum(counts.values())
    except sqlite3.Error as exc:
        counts = {}
        index_query_error = str(exc)[:240]
    valid_by_name = {path.name: path.resolve() for path in jsonl_paths}
    untrusted_source_names: set[str] = set()
    for source_name, source_path in source_locations:
        name = str(source_name or "")
        expected = valid_by_name.get(name)
        try:
            actual = Path(str(source_path or "")).resolve()
        except OSError:
            actual = Path(str(source_path or "")).absolute()
        if expected is None or os.path.normcase(str(actual)) != os.path.normcase(str(expected)):
            untrusted_source_names.add(name)
    sources: list[dict[str, object]] = []
    for path in jsonl_paths:
        size_bytes, mtime_ns = _runtime_event_source_stat(path)
        meta = meta_by_source.get(path.name)
        trusted_source = path.name not in untrusted_source_names
        fresh = bool(
            trusted_source
            and meta
            and int(meta[0] or 0) == size_bytes
            and int(meta[1] or 0) == mtime_ns
        )
        full = bool(meta and str(meta[4] or "") == "full")
        if trusted_source and meta and full and not fresh:
            try:
                refreshed_meta, size_bytes, mtime_ns = _runtime_event_index_source_meta_snapshot(path)
            except (OSError, sqlite3.Error, TypeError, ValueError):
                refreshed_meta = None
            if refreshed_meta:
                meta = refreshed_meta
                full = str(meta[4] or "") == "full"
                fresh = bool(
                    int(meta[0] or 0) == size_bytes
                    and int(meta[1] or 0) == mtime_ns
                )
        sqlite_ready = fresh and full
        sources.append(
            {
                "source_name": path.name,
                "exists": True,
                "size_mb": round(size_bytes / (1024 * 1024), 2),
                "indexed_count": counts.get(path.name, 0),
                "source_row_count": int(meta[2] or 0) if meta else 0,
                "coverage_mode": str(meta[4] or "untracked") if meta else "untracked",
                "index_fresh": fresh,
                "synchronized_at": meta[5] if meta else "",
                "read_mode": "sqlite_compact_index" if sqlite_ready else "jsonl_tail",
            }
        )
    indexed_sources = sum(1 for row in sources if row.get("read_mode") == "sqlite_compact_index")
    existing_sources = len(sources)
    coverage = round(indexed_sources / existing_sources * 100.0, 1) if existing_sources else 100.0
    stale_or_partial = max(0, existing_sources - indexed_sources)
    untrusted_indexed_events = sum(counts.get(name, 0) for name in untrusted_source_names)
    ready = not index_query_error and not untrusted_source_names and stale_or_partial == 0
    transition_state = (
        "sqlite_primary_all_sources"
        if ready and existing_sources
        else "hybrid_sqlite_jsonl_fallback"
        if indexed_sources
        else "jsonl_only"
    )
    return {
        "ok": ready,
        "status": "ready" if ready else "reconciliation_required",
        "mode": "JSONL 원본 + SQLite 요약 인덱스",
        "transition_state": transition_state,
        "db_exists": RUNTIME_EVENT_INDEX_DB.exists(),
        "db_path": str(RUNTIME_EVENT_INDEX_DB),
        "total_indexed_events": total_indexed,
        "trusted_indexed_events": max(0, total_indexed - untrusted_indexed_events),
        "untrusted_indexed_event_count": untrusted_indexed_events,
        "indexed_sources": indexed_sources,
        "existing_jsonl_sources": existing_sources,
        "coverage_pct": coverage,
        "coverage_scope": "fresh_full_source_snapshot",
        "full_history_backfill_claimed": bool(ready and existing_sources),
        "stale_or_partial_source_count": stale_or_partial,
        "untrusted_index_source_count": len(untrusted_source_names),
        "untrusted_index_source_labels": [
            f"{name}:outside-runtime-root" for name in sorted(untrusted_source_names)
        ],
        "reconciliation_required": not ready,
        "index_query_error": index_query_error,
        "deduplicated_rows_on_startup": int(RUNTIME_EVENT_INDEX_MIGRATION.get("deduplicated_rows", 0) or 0),
        "unique_payload_index_ready": bool(RUNTIME_EVENT_INDEX_MIGRATION.get("unique_payload_index_ready")),
        "coverage_basis": "파일별 최근 기록을 요약 색인하며 원본 JSONL은 보존합니다.",
        "sources": sorted(sources, key=lambda row: (int(row["indexed_count"]), float(row["size_mb"])), reverse=True),
        "live_order_allowed": False,
    }


def backfill_runtime_event_index(max_rows: int = 120) -> dict[str, object]:
    started = time.perf_counter()
    safe_max_rows = max(1, min(int(max_rows or 120), 500))
    inserted = 0
    skipped = 0
    source_results: list[dict[str, object]] = []
    with RUNTIME_EVENT_INDEX_LOCK:
        connection = _runtime_event_index_connection()
        for path in sorted(USER_DATA_ROOT.glob("*.jsonl"), key=lambda item: item.name.lower()):
            try:
                size_bytes = path.stat().st_size
            except OSError:
                continue
            source_limit = min(safe_max_rows, 5 if size_bytes >= 100 * 1024 * 1024 else 20 if size_bytes >= 20 * 1024 * 1024 else safe_max_rows)
            rows = _read_jsonl(path, limit=source_limit)
            source_inserted = 0
            for payload in rows:
                if _runtime_event_index_insert_unlocked(connection, path, payload):
                    inserted += 1
                    source_inserted += 1
                else:
                    skipped += 1
            indexed_count = int(
                connection.execute(
                    "SELECT COUNT(*) FROM jsonl_events WHERE source_name=?", (path.name,)
                ).fetchone()[0]
                or 0
            )
            _runtime_event_index_update_meta_unlocked(
                connection,
                path,
                source_row_count=0,
                indexed_row_count=indexed_count,
                coverage_mode="partial",
            )
            source_results.append(
                {
                    "source_name": path.name,
                    "size_mb": round(size_bytes / (1024 * 1024), 2),
                    "scanned_rows": len(rows),
                    "inserted": source_inserted,
                }
            )
        connection.commit()
    return {
        "ok": True,
        "inserted": inserted,
        "skipped": skipped,
        "elapsed_ms": round((time.perf_counter() - started) * 1000.0, 1),
        "source_count": len(source_results),
        "sources": source_results,
        "status": build_runtime_storage_status(),
        "safety": "Bounded recent-row SQLite backfill only. JSONL files are not modified or deleted.",
    }


def query_runtime_event_index(
    path: Path,
    *,
    limit: int = 50,
    event_date: str = "",
    symbol: str = "",
    status: str = "",
    newest_first: bool = True,
) -> dict[str, object]:
    safe_limit = max(1, min(int(limit or 50), 1000))
    source_path = path.resolve()
    if path.suffix.lower() != ".jsonl" or not is_inside(source_path, USER_DATA_ROOT):
        return {"ok": False, "status": "invalid_source", "rows": [], "read_mode": "jsonl_required"}
    size_bytes, mtime_ns = _runtime_event_source_stat(path)
    try:
        with RUNTIME_EVENT_INDEX_LOCK:
            connection = _runtime_event_index_connection()
            meta = connection.execute(
                """
                SELECT source_size_bytes, source_mtime_ns, source_row_count,
                       indexed_row_count, coverage_mode, synchronized_at
                FROM jsonl_source_meta WHERE source_name=?
                """,
                (path.name,),
            ).fetchone()
            if not meta:
                return {"ok": False, "status": "index_not_synchronized", "rows": [], "read_mode": "jsonl_required"}
            fresh = int(meta[0] or 0) == size_bytes and int(meta[1] or 0) == mtime_ns
            full = str(meta[4] or "") == "full"
            if not fresh or not full:
                return {
                    "ok": False,
                    "status": "index_stale" if not fresh else "index_partial",
                    "rows": [],
                    "read_mode": "jsonl_required",
                    "fresh": fresh,
                    "coverage_mode": meta[4],
                }
            clauses = ["source_name=?"]
            params: list[object] = [path.name]
            if event_date:
                clauses.append("event_date=?")
                params.append(str(event_date)[:10])
            if symbol:
                clauses.append("symbol=?")
                params.append(str(symbol).upper().strip())
            if status:
                clauses.append("status=?")
                params.append(str(status).upper().strip())
            params.append(safe_limit)
            order = "DESC" if newest_first else "ASC"
            result_rows = connection.execute(
                f"SELECT payload_json FROM jsonl_events WHERE {' AND '.join(clauses)} ORDER BY id {order} LIMIT ?",
                params,
            ).fetchall()
        rows: list[dict[str, object]] = []
        for raw in result_rows:
            try:
                payload = json.loads(str(raw[0] or "{}"))
            except json.JSONDecodeError:
                continue
            if isinstance(payload, dict):
                rows.append(payload)
        return {
            "ok": True,
            "status": "ready",
            "rows": rows,
            "count": len(rows),
            "read_mode": "sqlite_compact_index",
            "fresh": True,
            "coverage_mode": "full",
            "source_row_count": int(meta[2] or 0),
            "indexed_row_count": int(meta[3] or 0),
            "synchronized_at": meta[5],
        }
    except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
        return {
            "ok": False,
            "status": "index_query_failed",
            "rows": [],
            "read_mode": "jsonl_required",
            "error": str(exc)[:300],
        }


def reconcile_runtime_event_index(
    *,
    source_names: list[str] | None = None,
    vacuum: bool = False,
) -> dict[str, object]:
    """Rebuild the derived SQLite index from the current authoritative JSONL files."""
    started = time.perf_counter()
    requested = {Path(str(name)).name for name in (source_names or []) if str(name).strip()}
    valid_paths = sorted(USER_DATA_ROOT.glob("*.jsonl"), key=lambda item: item.name.lower())
    valid_by_name = {path.name: path for path in valid_paths}
    paths = [
        path for path in valid_paths
        if not requested or path.name in requested
    ]
    cleanup: dict[str, object] = {
        "removed_source_count": 0,
        "removed_event_row_count": 0,
        "removed_source_names": [],
        "rebuild_source_names": [],
    }
    cleanup_error = ""
    try:
        with RUNTIME_EVENT_INDEX_LOCK:
            connection = _runtime_event_index_connection()
            cleanup = _runtime_event_index_prune_untrusted_sources_unlocked(connection, valid_paths)
            connection.commit()
    except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
        cleanup_error = str(exc)[:300]
    automatic_rebuild_names = {
        str(name) for name in cleanup.get("rebuild_source_names", []) if str(name) in valid_by_name
    }
    selected_names = {path.name for path in paths}
    paths.extend(
        valid_by_name[name]
        for name in sorted(automatic_rebuild_names - selected_names)
    )
    paths.sort(key=lambda item: item.name.lower())
    before_bytes = RUNTIME_EVENT_INDEX_DB.stat().st_size if RUNTIME_EVENT_INDEX_DB.exists() else 0
    source_results: list[dict[str, object]] = []
    total_before = 0
    total_after = 0
    stale_removed = 0
    for path in paths:
        source_started = time.perf_counter()
        with _jsonl_io_lock(path):
            try:
                with RUNTIME_EVENT_INDEX_LOCK:
                    connection = _runtime_event_index_connection()
                    result = _runtime_event_index_replace_source_from_jsonl_unlocked(connection, path)
                    connection.commit()
            except (OSError, sqlite3.Error, TypeError, ValueError) as exc:
                source_results.append(
                    {
                        "source_name": path.name,
                        "ok": False,
                        "row_count": 0,
                        "read_mode": "streaming_jsonl",
                        "error": str(exc)[:300],
                    }
                )
                continue
        total_before += int(result.get("before", 0))
        total_after += int(result.get("after", 0))
        stale_removed += int(result.get("stale_removed", 0))
        source_results.append(
                {
                    "source_name": path.name,
                    "ok": True,
                    "row_count": result.get("source_row_count", 0),
                    "indexed_count": result.get("after", 0),
                    "invalid_row_count": result.get("invalid_row_count", 0),
                    "blank_row_count": result.get("blank_row_count", 0),
                    "stale_removed": result.get("stale_removed", 0),
                    "read_mode": "streaming_jsonl",
                    "elapsed_ms": round((time.perf_counter() - source_started) * 1000.0, 1),
                }
        )
    vacuum_status = "not_requested"
    if vacuum and not any(not row.get("ok") for row in source_results):
        try:
            with RUNTIME_EVENT_INDEX_LOCK:
                connection = _runtime_event_index_connection()
                connection.commit()
                connection.execute("PRAGMA wal_checkpoint(TRUNCATE)")
                connection.execute("VACUUM")
                connection.commit()
            vacuum_status = "completed"
        except sqlite3.Error as exc:
            vacuum_status = f"failed:{str(exc)[:180]}"
    after_bytes = RUNTIME_EVENT_INDEX_DB.stat().st_size if RUNTIME_EVENT_INDEX_DB.exists() else 0
    HOT_LOG_STORAGE_CACHE.update({"saved_at": 0.0, "payload": {}})
    source_failed = any(not row.get("ok") for row in source_results)
    work_completed = bool(source_results) or bool(cleanup.get("removed_source_count"))
    ok = work_completed and not source_failed and not cleanup_error
    return {
        "ok": ok,
        "status": "reconciled" if ok else "partial_failure",
        "requested_source_count": len(requested),
        "automatic_rebuild_source_count": len(automatic_rebuild_names),
        "source_count": len(source_results),
        "total_indexed_before": total_before,
        "total_indexed_after": total_after,
        "stale_rows_removed": stale_removed,
        "database_size_before_mb": round(before_bytes / (1024 * 1024), 2),
        "database_size_after_mb": round(after_bytes / (1024 * 1024), 2),
        "vacuum_status": vacuum_status,
        "untrusted_source_cleanup": cleanup,
        "untrusted_source_cleanup_error": cleanup_error,
        "memory_mode": "bounded_streaming_one_row",
        "elapsed_ms": round((time.perf_counter() - started) * 1000.0, 1),
        "sources": source_results,
        "safety": "Rebuilds only the derived SQLite index. Authoritative JSONL records are read but never modified.",
        "live_order_allowed": False,
    }


def build_hot_log_storage(limit: int = 8, ttl_seconds: int = 60) -> dict[str, object]:
    now = time.time()
    cached = HOT_LOG_STORAGE_CACHE.get("payload")
    if isinstance(cached, dict) and cached and now - float(HOT_LOG_STORAGE_CACHE.get("saved_at") or 0.0) <= max(1, ttl_seconds):
        return {**cached, "cached": True}
    rows: list[dict[str, object]] = []
    for pattern in ("*.jsonl", "*.sqlite", "*.sqlite3", "*.db"):
        for path in USER_DATA_ROOT.glob(pattern):
            try:
                size_mb = path.stat().st_size / (1024 * 1024)
            except OSError:
                continue
            tone = "danger" if size_mb >= 500 else "warn" if size_mb >= 100 else "watch" if size_mb >= 20 else "ok"
            rows.append({"name": path.name, "path": str(path), "size_mb": round(size_mb, 2), "tone": tone})
    rows.sort(key=lambda row: float(row.get("size_mb") or 0), reverse=True)
    top_files = rows[: max(1, min(int(limit or 8), 30))]
    danger_count = sum(1 for row in rows if row.get("tone") == "danger")
    warn_count = sum(1 for row in rows if row.get("tone") == "warn")
    watch_count = sum(1 for row in rows if row.get("tone") == "watch")
    overall_tone = "danger" if danger_count else "warn" if warn_count else "watch" if watch_count else "ok"
    payload = {
        "ok": True,
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "tone": overall_tone,
        "total_size_mb": round(sum(float(row.get("size_mb") or 0) for row in rows), 2),
        "file_count": len(rows),
        "danger_count": danger_count,
        "warn_count": warn_count,
        "watch_count": watch_count,
        "top_files": top_files,
        "headline": f"저장 파일 {len(rows)}개 · 위험 {danger_count} · 경고 {warn_count} · 관찰 {watch_count}",
        "safety": "Metadata and bounded tail diagnostics only. No file is deleted or compacted.",
    }
    HOT_LOG_STORAGE_CACHE.update({"saved_at": now, "payload": payload})
    return {**payload, "cached": False}


def _compact_jsonl(path: Path, max_rows: int = 600) -> None:
    safe_max_rows = max(1, int(max_rows or 600))
    retained_rows: list[dict[str, object]] | None = None
    with _jsonl_io_lock(path):
        if not path.exists():
            return
        rows: deque[dict[str, object]] = deque(maxlen=safe_max_rows)
        valid_count = 0
        skipped_count = 0
        with path.open("r", encoding="utf-8", errors="ignore") as handle:
            for line in handle:
                clean = line.strip().lstrip("\ufeff")
                if not clean:
                    skipped_count += 1
                    continue
                try:
                    item = json.loads(clean)
                except json.JSONDecodeError:
                    skipped_count += 1
                    continue
                if not isinstance(item, dict):
                    skipped_count += 1
                    continue
                valid_count += 1
                rows.append(item)
        if valid_count <= safe_max_rows and skipped_count == 0:
            return
        temp_name = ""
        try:
            with tempfile.NamedTemporaryFile(
                "w",
                encoding="utf-8",
                dir=path.parent,
                prefix=f".{path.name}.",
                suffix=".tmp",
                delete=False,
            ) as handle:
                temp_name = handle.name
                for row in rows:
                    handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n")
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temp_name, path)
            temp_name = ""
            retained_rows = list(rows)
        finally:
            if temp_name:
                try:
                    Path(temp_name).unlink(missing_ok=True)
                except OSError:
                    pass
        if retained_rows is not None:
            _synchronize_runtime_event_index_after_rewrite(path, retained_rows)


def build_jsonl_compaction_dry_run(target_name: str, keep_rows: int = 600, data_dir: Path | None = None) -> dict[str, object]:
    data_dir = data_dir or USER_DATA_ROOT
    safe_name = Path(str(target_name or "")).name
    path = data_dir / safe_name
    safe_keep_rows = max(1, min(int(keep_rows or 600), 20_000))
    if not safe_name.endswith(".jsonl") or not path.exists() or path.parent.resolve() != data_dir.resolve():
        return {
            "ok": False,
            "status": "not_found",
            "applied": False,
            "dry_run_only": True,
            "mutation_allowed": False,
            "target": safe_name,
            "keep_rows": safe_keep_rows,
            "error": "target must be an existing data/*.jsonl file",
            "safety": "Read-only JSONL compaction dry-run. No file is modified.",
        }
    stat = path.stat()
    original_bytes = int(stat.st_size)
    tail_rows: deque[dict[str, object]] = deque(maxlen=safe_keep_rows)
    total_lines = 0
    blank_lines = 0
    invalid_lines = 0
    valid_rows = 0
    data_rows = 0
    prior_summarized_rows = 0
    with path.open("r", encoding="utf-8", errors="ignore") as handle:
        for line in handle:
            total_lines += 1
            clean = line.strip().lstrip("\ufeff")
            if not clean:
                blank_lines += 1
                continue
            try:
                item = json.loads(clean)
            except json.JSONDecodeError:
                invalid_lines += 1
                continue
            if not isinstance(item, dict):
                invalid_lines += 1
                continue
            valid_rows += 1
            if str(item.get("type") or "") == "jsonl_compaction_summary":
                prior_summarized_rows += max(0, int(_number(item.get("summarized_rows"))))
                continue
            data_rows += 1
            tail_rows.append(item)
    kept_rows = len(tail_rows)
    newly_summarized_rows = max(0, data_rows - kept_rows)
    summarized_rows = prior_summarized_rows + newly_summarized_rows
    summary_row = {
        "type": "jsonl_compaction_summary",
        "source_file": safe_name,
        "summarized_rows": summarized_rows,
        "valid_rows_before": valid_rows,
        "data_rows_before": data_rows,
        "prior_summarized_rows": prior_summarized_rows,
        "invalid_lines_before": invalid_lines,
        "blank_lines_before": blank_lines,
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "note": "dry-run estimate only; not written",
    }
    output_rows: list[dict[str, object]] = ([summary_row] if summarized_rows else []) + list(tail_rows)
    estimated_after_bytes = sum(
        len((json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n").encode("utf-8"))
        for row in output_rows
    )
    estimated_saved_bytes = max(0, original_bytes - estimated_after_bytes)
    return {
        "ok": True,
        "status": "dry_run",
        "applied": False,
        "dry_run_only": True,
        "mutation_allowed": False,
        "target": safe_name,
        "path": str(path),
        "keep_rows": safe_keep_rows,
        "total_lines": total_lines,
        "valid_rows": valid_rows,
        "data_rows": data_rows,
        "invalid_lines": invalid_lines,
        "blank_lines": blank_lines,
        "kept_rows": kept_rows,
        "summarized_rows": summarized_rows,
        "prior_summarized_rows": prior_summarized_rows,
        "newly_summarized_rows": newly_summarized_rows,
        "would_write_summary_row": summarized_rows > 0,
        "original_mb": round(original_bytes / (1024 * 1024), 2),
        "estimated_after_mb": round(estimated_after_bytes / (1024 * 1024), 2),
        "estimated_saved_mb": round(estimated_saved_bytes / (1024 * 1024), 2),
        "would_modify": estimated_saved_bytes > 0 or invalid_lines > 0 or blank_lines > 0,
        "backup_required": True,
        "requires_confirm_to_apply": True,
        "safety": "Read-only JSONL compaction dry-run. No file is modified.",
    }


def build_large_jsonl_compaction_estimate(
    target_name: str,
    keep_rows: int = 600,
    data_dir: Path | None = None,
    sample_bytes_per_region: int = 4 * 1024 * 1024,
) -> dict[str, object]:
    data_dir = data_dir or USER_DATA_ROOT
    safe_name = Path(str(target_name or "")).name
    path = data_dir / safe_name
    safe_keep_rows = max(1, min(int(keep_rows or 600), 20_000))
    safe_sample_bytes = max(64 * 1024, min(int(sample_bytes_per_region or 0), 8 * 1024 * 1024))
    if not safe_name.endswith(".jsonl") or not path.exists() or path.parent.resolve() != data_dir.resolve():
        return {
            "ok": False,
            "status": "not_found",
            "target": safe_name,
            "error": "target must be an existing data/*.jsonl file",
            "safety": "Read-only bounded JSONL estimate. No file is modified.",
        }
    original_bytes = int(path.stat().st_size)
    if original_bytes <= 0:
        return {
            "ok": True,
            "status": "bounded_estimate",
            "target": safe_name,
            "keep_rows": safe_keep_rows,
            "original_mb": 0.0,
            "estimated_after_mb": 0.0,
            "estimated_saved_mb": 0.0,
            "estimated_total_lines": 0,
            "estimated_kept_rows": 0,
            "confidence": "high",
            "sampled_bytes": 0,
            "sampled_newlines": 0,
            "safety": "Read-only bounded JSONL estimate. No file is modified.",
        }
    max_offset = max(0, original_bytes - safe_sample_bytes)
    offsets = sorted({0, max(0, (original_bytes // 2) - (safe_sample_bytes // 2)), max_offset})
    sampled_bytes = 0
    sampled_newlines = 0
    with path.open("rb") as handle:
        for offset in offsets:
            handle.seek(offset)
            chunk = handle.read(min(safe_sample_bytes, original_bytes - offset))
            sampled_bytes += len(chunk)
            sampled_newlines += chunk.count(b"\n")
    if sampled_bytes <= 0 or sampled_newlines <= 0:
        return {
            "ok": False,
            "status": "estimate_unavailable",
            "target": safe_name,
            "keep_rows": safe_keep_rows,
            "original_mb": round(original_bytes / (1024 * 1024), 2),
            "sampled_bytes": sampled_bytes,
            "sampled_newlines": sampled_newlines,
            "reason": "sample contained no JSONL line boundaries",
            "safety": "Read-only bounded JSONL estimate. No file is modified.",
        }
    estimated_avg_line_bytes = sampled_bytes / sampled_newlines
    estimated_total_lines = max(1, int(round(original_bytes / max(1.0, estimated_avg_line_bytes))))
    estimated_kept_rows = min(safe_keep_rows, estimated_total_lines)
    summary_row_allowance = 2048 if estimated_total_lines > estimated_kept_rows else 0
    estimated_after_bytes = min(
        original_bytes,
        int(round(estimated_kept_rows * estimated_avg_line_bytes)) + summary_row_allowance,
    )
    estimated_saved_bytes = max(0, original_bytes - estimated_after_bytes)
    confidence = "high" if sampled_newlines >= 100 else "medium" if sampled_newlines >= 20 else "low"
    return {
        "ok": True,
        "status": "bounded_estimate",
        "applied": False,
        "dry_run_only": True,
        "mutation_allowed": False,
        "target": safe_name,
        "path": str(path),
        "keep_rows": safe_keep_rows,
        "estimated_total_lines": estimated_total_lines,
        "estimated_kept_rows": estimated_kept_rows,
        "estimated_summarized_rows": max(0, estimated_total_lines - estimated_kept_rows),
        "estimated_avg_line_bytes": round(estimated_avg_line_bytes, 2),
        "original_mb": round(original_bytes / (1024 * 1024), 2),
        "estimated_after_mb": round(estimated_after_bytes / (1024 * 1024), 2),
        "estimated_saved_mb": round(estimated_saved_bytes / (1024 * 1024), 2),
        "estimated_saved_pct": round((estimated_saved_bytes / original_bytes) * 100.0, 2),
        "sampled_region_count": len(offsets),
        "sampled_bytes": sampled_bytes,
        "sampled_newlines": sampled_newlines,
        "confidence": confidence,
        "requires_full_dry_run_before_apply": True,
        "would_modify": estimated_saved_bytes > 0,
        "backup_required": True,
        "safety": "Read-only bounded JSONL estimate from fixed-size samples. No file is modified or deleted.",
    }


def _compact_jsonl_file_with_backup(path: Path, data_dir: Path, keep_rows: int) -> dict[str, object]:
    with _jsonl_io_lock(path):
        tail_rows: deque[dict[str, object]] = deque(maxlen=keep_rows)
        valid_rows = 0
        data_rows = 0
        invalid_lines = 0
        blank_lines = 0
        prior_summarized_rows = 0
        with path.open("r", encoding="utf-8", errors="ignore") as handle:
            for line in handle:
                clean = line.strip().lstrip("\ufeff")
                if not clean:
                    blank_lines += 1
                    continue
                try:
                    item = json.loads(clean)
                except json.JSONDecodeError:
                    invalid_lines += 1
                    continue
                if not isinstance(item, dict):
                    invalid_lines += 1
                    continue
                valid_rows += 1
                if str(item.get("type") or "") == "jsonl_compaction_summary":
                    prior_summarized_rows += max(0, int(_number(item.get("summarized_rows"))))
                    continue
                data_rows += 1
                tail_rows.append(item)
        timestamp = datetime.now(_zone("Asia/Seoul", 9)).strftime("%Y%m%d-%H%M%S")
        backup_dir = data_dir / "backups" / "jsonl_compaction"
        backup_dir.mkdir(parents=True, exist_ok=True)
        backup_path = backup_dir / f"{path.name}.{timestamp}.bak"
        shutil.copy2(path, backup_path)
        summarized_rows = prior_summarized_rows + max(0, data_rows - len(tail_rows))
        summary_row = {
            "type": "jsonl_compaction_summary",
            "source_file": path.name,
            "summarized_rows": summarized_rows,
            "valid_rows_before": valid_rows,
            "data_rows_before": data_rows,
            "prior_summarized_rows": prior_summarized_rows,
            "invalid_lines_before": invalid_lines,
            "blank_lines_before": blank_lines,
            "backup_path": str(backup_path),
            "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        }
        output_rows: list[dict[str, object]] = ([summary_row] if summarized_rows else []) + list(tail_rows)
        temp_path = path.with_name(f"{path.name}.tmp")
        with temp_path.open("w", encoding="utf-8", newline="\n") as handle:
            for row in output_rows:
                handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n")
            handle.flush()
            os.fsync(handle.fileno())
        temp_path.replace(path)
        return {
            "backup_path": str(backup_path),
            "original_bytes": backup_path.stat().st_size,
            "after_bytes": path.stat().st_size,
            "summarized_rows": summarized_rows,
            "valid_rows": valid_rows,
            "data_rows": data_rows,
            "prior_summarized_rows": prior_summarized_rows,
            "invalid_lines": invalid_lines,
            "blank_lines": blank_lines,
        }


def jsonl_compaction_backup_retention(
    target_name: str,
    *,
    apply: bool = False,
    confirm: str = "",
    data_dir: Path | None = None,
) -> dict[str, object]:
    data_dir = (data_dir or USER_DATA_ROOT).resolve()
    safe_name = Path(str(target_name or "")).name
    if not safe_name.endswith(".jsonl") or safe_name != str(target_name or ""):
        return {"ok": False, "status": "unsafe_target", "applied": False, "target": safe_name}
    backup_dir = (data_dir / "backups" / "jsonl_compaction").resolve()
    backup_dir.mkdir(parents=True, exist_ok=True)
    candidates = sorted(
        [
            path
            for path in backup_dir.glob(f"{safe_name}.*.bak")
            if path.is_file() and path.parent.resolve() == backup_dir and path.name.startswith(f"{safe_name}.")
        ],
        key=lambda path: (path.stat().st_mtime_ns, path.name),
    )
    preserve: set[Path] = set()
    if candidates:
        preserve.add(max(candidates, key=lambda path: (path.stat().st_size, path.stat().st_mtime_ns)))
        preserve.add(candidates[-1])
    contract_index_pins: set[Path] = set()
    if HISTORICAL_REPLAY_BACKUP_CONTRACT_INDEX_FILE.is_file():
        try:
            contract_index = json.loads(HISTORICAL_REPLAY_BACKUP_CONTRACT_INDEX_FILE.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            contract_index = {}
        entries = contract_index.get("entries") if isinstance(contract_index, dict) else {}
        for entry in entries.values() if isinstance(entries, dict) else []:
            if not isinstance(entry, dict):
                continue
            source_path = Path(str(entry.get("source_backup_path") or ""))
            try:
                resolved_source = source_path.resolve()
            except OSError:
                continue
            if resolved_source in candidates and resolved_source.parent == backup_dir:
                contract_index_pins.add(resolved_source)
    preserve.update(contract_index_pins)
    removable = [path for path in candidates if path not in preserve]
    plan = {
        "ok": True,
        "status": "dry_run",
        "applied": False,
        "target": safe_name,
        "backup_count": len(candidates),
        "preserved_count": len(preserve),
        "contract_index_pinned_count": len(contract_index_pins),
        "removable_count": len(removable),
        "preserved": [
            {
                "name": path.name,
                "size_mb": round(path.stat().st_size / (1024 * 1024), 2),
                "contract_index_pinned": path in contract_index_pins,
            }
            for path in sorted(preserve, key=lambda item: item.name)
        ],
        "removable": [
            {"name": path.name, "size_mb": round(path.stat().st_size / (1024 * 1024), 2)}
            for path in removable
        ],
        "estimated_reclaimed_mb": round(sum(path.stat().st_size for path in removable) / (1024 * 1024), 2),
        "rule": "Preserve the largest baseline, newest incremental, and every backup pinned by a replay contract index.",
        "required_confirm": "PRUNE",
    }
    if not apply:
        return plan
    if str(confirm or "").strip().upper() != "PRUNE":
        return {**plan, "ok": False, "status": "confirmation_required"}
    removed: list[str] = []
    for path in removable:
        if path.parent.resolve() != backup_dir or path.suffix.lower() != ".bak":
            continue
        path.unlink()
        removed.append(path.name)
    return {
        **plan,
        "status": "applied",
        "applied": True,
        "removed_count": len(removed),
        "removed": removed,
        "safety": "Largest baseline, newest incremental, and replay-contract source backups were preserved.",
    }


def apply_jsonl_compaction_with_summary(
    target_name: str,
    keep_rows: int = 600,
    confirm: str = "",
    data_dir: Path | None = None,
) -> dict[str, object]:
    data_dir = data_dir or USER_DATA_ROOT
    dry_run = build_jsonl_compaction_dry_run(target_name, keep_rows=keep_rows, data_dir=data_dir)
    if not dry_run.get("ok"):
        return dry_run
    if str(confirm or "").strip().upper() != "COMPACT":
        return {
            **dry_run,
            "ok": False,
            "status": "confirmation_required",
            "applied": False,
            "dry_run_only": True,
            "mutation_allowed": False,
            "required_confirm": "COMPACT",
            "message": "Pass confirm=COMPACT to apply after reviewing the dry-run.",
            "safety": "No file was modified.",
        }
    path = Path(str(dry_run.get("path") or ""))
    if not path.exists() or path.parent.resolve() != data_dir.resolve():
        return {
            **dry_run,
            "ok": False,
            "status": "unsafe_path",
            "applied": False,
            "dry_run_only": True,
            "mutation_allowed": False,
            "message": "Refusing to compact outside the configured data directory.",
            "safety": "No file was modified.",
        }
    if not dry_run.get("would_modify"):
        return {
            **dry_run,
            "status": "unchanged",
            "applied": False,
            "dry_run_only": True,
            "mutation_allowed": False,
            "message": "No compaction needed.",
            "safety": "No file was modified.",
        }
    safe_keep_rows = int(dry_run.get("keep_rows") or keep_rows or 600)
    compacted = _compact_jsonl_file_with_backup(path, data_dir, safe_keep_rows)
    original_bytes = int(compacted.get("original_bytes") or 0)
    after_bytes = int(compacted.get("after_bytes") or 0)
    return {
        **dry_run,
        "ok": True,
        "status": "applied",
        "applied": True,
        "dry_run_only": False,
        "mutation_allowed": True,
        "backup_path": compacted.get("backup_path", ""),
        "after_mb": round(after_bytes / (1024 * 1024), 2),
        "actual_saved_mb": round(max(0, original_bytes - after_bytes) / (1024 * 1024), 2),
        "summary_row_written": int(compacted.get("summarized_rows") or 0) > 0,
        "safety": "Compaction applied after explicit confirm=COMPACT and backup creation.",
    }


def _market_brief_row(row: dict[str, object]) -> dict[str, object]:
    amount = _number(row.get("amount"))
    return {
        "symbol": str(row.get("symbol", "")),
        "name": str(row.get("name", "") or row.get("symbol", "")),
        "market": str(row.get("market", "")),
        "close": round(_number(row.get("close")), 4),
        "change_pct": round(_number(row.get("change_pct")), 2),
        "volume": int(_number(row.get("volume"))),
        "amount": round(amount, 0),
        "amount_eok": round(amount / 100_000_000, 1),
        "marcap": round(_number(row.get("marcap")), 0),
        "source": row.get("source", ""),
    }


def _three_month_start_date(work_date: str) -> str:
    try:
        base = datetime.fromisoformat(str(work_date)[:10]).date()
    except Exception:
        base = datetime.now(ZoneInfo("Asia/Seoul")).date()
    return (base - timedelta(days=92)).isoformat()


def _symbol_three_month_return(symbol: str, start_date: str, end_date: str) -> dict[str, object]:
    normalized = _normalize_symbol_for_watchlist(symbol)
    try:
        series = _historical_close_rows(normalized, start_date, end_date, allow_simulated_fallback=False)
        rows = [row for row in series.get("rows", []) if isinstance(row, dict) and _number(row.get("close")) > 0]
        if len(rows) < 2:
            raise ValueError("3개월 가격 행 부족")
        start_price = _number(rows[0].get("close"))
        end_price = _number(rows[-1].get("close"))
        return_pct = ((end_price / start_price) - 1.0) * 100.0 if start_price else 0.0
        return {
            "ok": True,
            "symbol": normalized,
            "start_date": rows[0].get("date"),
            "end_date": rows[-1].get("date"),
            "start_price": round(start_price, 4),
            "end_price": round(end_price, 4),
            "return_pct": round(return_pct, 2),
            "provider": series.get("provider", series.get("source", "-")),
        }
    except Exception as exc:
        return {"ok": False, "symbol": normalized, "return_pct": 0.0, "error": str(exc)}


def _build_sector_three_month_returns(
    themes: list[dict[str, object]],
    rows_by_symbol: dict[str, dict[str, object]],
    work_date: str,
    max_themes: int = 8,
    symbols_per_theme: int = 3,
) -> list[dict[str, object]]:
    start_date = _three_month_start_date(work_date)
    results: list[dict[str, object]] = []
    for theme in themes[:max_themes]:
        if not isinstance(theme, dict):
            continue
        leaders = [row for row in theme.get("leaders", []) if isinstance(row, dict)]
        symbols: list[str] = []
        for leader in sorted(leaders, key=lambda item: _number(item.get("amount")), reverse=True):
            symbol = str(leader.get("symbol", "")).upper().strip()
            if symbol and symbol not in symbols:
                symbols.append(symbol)
            if len(symbols) >= symbols_per_theme:
                break
        symbol_returns = []
        for symbol in symbols:
            ret = _symbol_three_month_return(symbol, start_date, work_date)
            row = rows_by_symbol.get(symbol, {})
            ret["name"] = row.get("name") or next((leader.get("name") for leader in leaders if leader.get("symbol") == symbol), symbol)
            symbol_returns.append(ret)
        valid = [item for item in symbol_returns if item.get("ok")]
        avg_return = sum(_number(item.get("return_pct")) for item in valid) / len(valid) if valid else 0.0
        results.append(
            {
                "id": theme.get("id", ""),
                "name": theme.get("name", "-"),
                "period": f"{start_date}~{work_date}",
                "today_avg_change_pct": theme.get("avg_change_pct", 0),
                "today_amount_eok": round(_number(theme.get("amount")) / 100_000_000, 1),
                "three_month_return_pct": round(avg_return, 2),
                "symbols": symbol_returns,
                "leader": symbol_returns[0] if symbol_returns else {},
                "verdict": "3개월 주도" if avg_return >= 15 else "회복/관찰" if avg_return > 0 else "약세/회피",
            }
        )
    return sorted(results, key=lambda item: (_number(item.get("three_month_return_pct")), _number(item.get("today_amount_eok"))), reverse=True)


def _market_reflection_candidates(
    top_amount: list[dict[str, object]],
    gainers: list[dict[str, object]],
    losers: list[dict[str, object]],
    themes: list[dict[str, object]],
    candidates: list[dict[str, object]] | None = None,
) -> tuple[list[dict[str, object]], list[dict[str, object]], list[dict[str, object]]]:
    theme_leader_symbols: dict[str, str] = {}
    for theme in themes:
        if not isinstance(theme, dict):
            continue
        for leader in theme.get("leaders", []) if isinstance(theme.get("leaders"), list) else []:
            if isinstance(leader, dict) and leader.get("symbol"):
                theme_leader_symbols[str(leader.get("symbol")).upper()] = str(theme.get("name", "테마"))
    candidate_scores = {
        str(item.get("symbol", "")).upper(): item
        for item in candidates or []
        if isinstance(item, dict) and item.get("symbol")
    }
    should_enter: list[dict[str, object]] = []
    seen: set[str] = set()
    for row in [*gainers[:10], *top_amount[:10]]:
        symbol = str(row.get("symbol", "")).upper()
        if not symbol or symbol in seen:
            continue
        seen.add(symbol)
        amount = _number(row.get("amount"))
        change = _number(row.get("change_pct"))
        theme_name = theme_leader_symbols.get(symbol, "")
        score_row = candidate_scores.get(symbol, {})
        if amount >= 20_000_000_000 and change >= 2.0 and (theme_name or _number(score_row.get("score")) >= 60):
            should_enter.append(
                {
                    **_market_brief_row(row),
                    "theme": theme_name or "스크리너 상위",
                    "score": score_row.get("score"),
                    "review": "거래대금과 상승률이 같이 붙었습니다. 장초반 눌림/돌파 기준을 세워 paper 또는 소액 파일럿 후보로 복기합니다.",
                }
            )
    should_avoid: list[dict[str, object]] = []
    for row in [*losers[:8], *gainers[:8]]:
        symbol = str(row.get("symbol", "")).upper()
        change = _number(row.get("change_pct"))
        amount = _number(row.get("amount"))
        reason = ""
        if change <= -5 and amount >= 10_000_000_000:
            reason = "거래대금 동반 하락입니다. 물타기보다 손절/관망 기준을 먼저 복기합니다."
        elif change >= 18:
            reason = "급등 추격 구간입니다. 대장주 확인 없이 늦은 진입은 피해야 합니다."
        if reason:
            should_avoid.append({**_market_brief_row(row), "review": reason})
    missed_or_watch = []
    for row in top_amount[:8]:
        symbol = str(row.get("symbol", "")).upper()
        if symbol in {item.get("symbol") for item in should_enter}:
            continue
        missed_or_watch.append(
            {
                **_market_brief_row(row),
                "review": "대금은 컸지만 상승률/테마/후보점수 조합이 부족했습니다. 들어가지 않은 이유를 다음 사이클에서 확인합니다.",
            }
        )
    return should_enter[:8], should_avoid[:8], missed_or_watch[:8]


def _build_market_supply_audit(
    top_amount: list[dict[str, object]],
    top_volume: list[dict[str, object]],
    gainers: list[dict[str, object]],
    losers: list[dict[str, object]],
    work_date: str,
    max_symbols: int = 12,
) -> dict[str, object]:
    """Combine market leaders with explicit personal/foreign/institution flow evidence."""
    symbol_rows: dict[str, dict[str, object]] = {}
    for group in (top_amount[:5], top_volume[:3], gainers[:3], losers[:2]):
        for row in group:
            if not isinstance(row, dict):
                continue
            symbol = _normalize_symbol_for_watchlist(row.get("symbol"))
            if symbol and symbol not in symbol_rows and len(symbol_rows) < max_symbols:
                symbol_rows[symbol] = row

    flow_rows: list[dict[str, object]] = []
    unavailable: list[dict[str, str]] = []
    for symbol, market_row in symbol_rows.items():
        try:
            trend = INTEGRATIONS.kis_investor_trend(symbol)
        except Exception as exc:
            trend = {"ok": False, "message": str(exc), "latest": {}}
        latest = trend.get("latest") if isinstance(trend.get("latest"), dict) else {}
        if not trend.get("ok") or not latest:
            unavailable.append({"symbol": symbol, "reason": str(trend.get("message") or "수급 데이터 없음")})
            continue
        flow_rows.append(
            {
                **_market_brief_row(market_row),
                "flow_date": latest.get("date"),
                "personal_net_qty": int(_number(latest.get("personal_net_qty"))),
                "foreign_net_qty": int(_number(latest.get("foreign_net_qty"))),
                "institution_net_qty": int(_number(latest.get("institution_net_qty"))),
                "personal_net_amount": round(_number(latest.get("personal_net_amount")), 0),
                "foreign_net_amount": round(_number(latest.get("foreign_net_amount")), 0),
                "institution_net_amount": round(_number(latest.get("institution_net_amount")), 0),
                "personal_net_amount_eok": round(_number(latest.get("personal_net_amount")) / 100_000_000, 1),
                "foreign_net_amount_eok": round(_number(latest.get("foreign_net_amount")) / 100_000_000, 1),
                "institution_net_amount_eok": round(_number(latest.get("institution_net_amount")) / 100_000_000, 1),
                "flow_source": trend.get("source") or "kis_investor_trend",
            }
        )

    ranks: dict[str, object] = {}
    for investor in ("foreign", "institution"):
        try:
            rank = INTEGRATIONS.kis_foreign_institution_rank(investor=investor, market="all", direction="buy", limit=10)
        except Exception as exc:
            rank = {"ok": False, "items": [], "message": str(exc)}
        ranks[investor] = {
            "ok": bool(rank.get("ok")),
            "items": rank.get("items", []) if isinstance(rank.get("items"), list) else [],
            "message": rank.get("message", ""),
            "availability": rank.get("availability", ""),
        }

    def net_rank(key: str) -> list[dict[str, object]]:
        return sorted(flow_rows, key=lambda row: _number(row.get(key)), reverse=True)[:10]

    return {
        "ok": bool(flow_rows) or any(bool((ranks.get(key) or {}).get("ok")) for key in ("foreign", "institution")),
        "work_date": work_date,
        "scope": "거래대금·거래량·상승률·하락률 상위 기회군",
        "audited_symbol_count": len(symbol_rows),
        "flow_confirmed_count": len(flow_rows),
        "flow_unavailable_count": len(unavailable),
        "items": flow_rows,
        "personal_net_buy_top_in_opportunity_pool": net_rank("personal_net_amount"),
        "foreign_net_buy_top_in_opportunity_pool": net_rank("foreign_net_amount"),
        "institution_net_buy_top_in_opportunity_pool": net_rank("institution_net_amount"),
        "foreign_market_rank": ranks["foreign"],
        "institution_market_rank": ranks["institution"],
        "unavailable": unavailable,
        "contract": "개인 순매수 상위는 기회군 내부 순위이며, 외국인·기관 시장 순위는 KIS 장중 잠정 집계입니다. 당일 종목별 확정 수급은 장 종료 후 조회합니다.",
        "safety": "읽기전용 시장 수급 대사입니다. 주문을 실행하지 않습니다.",
    }


def build_market_reflection_journal(
    raw_rows: list[dict[str, object]] | None = None,
    kr_market: dict[str, object] | None = None,
    themes: list[dict[str, object]] | None = None,
    candidates: list[dict[str, object]] | None = None,
    ops_action: dict[str, object] | None = None,
    replay_training: dict[str, object] | None = None,
    source: str = "manual",
    force: bool = False,
) -> dict[str, object]:
    latest = _read_jsonl(MARKET_REFLECTION_FILE, limit=1)
    if latest and not force:
        latest_row = latest[-1]
        if latest_row.get("work_date") == fetch_krx_work_date() and _iso_age_seconds(latest_row.get("generated_at")) is not None and _iso_age_seconds(latest_row.get("generated_at")) < 1800:
            latest_row["cached"] = True
            return latest_row
    if raw_rows is None:
        work_date, raw_rows = fetch_kr_market_rows()
    else:
        work_date = str((kr_market or {}).get("date") or (raw_rows[0].get("source", "") if raw_rows else "")).replace("KRX-", "")[:10] or fetch_krx_work_date()
    if kr_market is None:
        kr_market = analyze_kr_market()
    if themes is None:
        themes = analyze_themes_from_rows(raw_rows)
    rows_by_symbol = {str(row.get("symbol", "")).upper(): row for row in raw_rows if isinstance(row, dict)}
    top_amount = sorted(raw_rows, key=lambda row: _number(row.get("amount")), reverse=True)[:20]
    top_volume = sorted(raw_rows, key=lambda row: _number(row.get("volume")), reverse=True)[:20]
    gainers = sorted([row for row in raw_rows if _number(row.get("amount")) >= 1_000_000_000], key=lambda row: _number(row.get("change_pct")), reverse=True)[:20]
    losers = sorted([row for row in raw_rows if _number(row.get("amount")) >= 1_000_000_000], key=lambda row: _number(row.get("change_pct")))[:20]
    supply_audit = _build_market_supply_audit(top_amount, top_volume, gainers, losers, work_date)
    sector_returns = _build_sector_three_month_returns(themes or [], rows_by_symbol, work_date)
    should_enter, should_avoid, missed_or_watch = _market_reflection_candidates(top_amount, gainers, losers, themes or [], candidates)
    holding_reviews: list[dict[str, object]] = []
    try:
        account = INTEGRATIONS.kis_account()
        positions = account.get("positions", []) if isinstance(account.get("positions"), list) else []
    except Exception:
        positions = []
    for position in positions[:12]:
        if not isinstance(position, dict):
            continue
        symbol = str(position.get("symbol", "")).upper().strip()
        row = rows_by_symbol.get(symbol, {})
        change = _number(row.get("change_pct"))
        pnl_pct = _number(position.get("profit_loss_rate"))
        if pnl_pct >= 2.2 or change >= 2.2:
            action = "수익보호/트레일링 기준 확인"
        elif pnl_pct <= -1.2 or change <= -2.0:
            action = "손절/비중축소 기준 확인"
        else:
            action = "보유 근거 유지 여부 확인"
        holding_reviews.append(
            {
                "symbol": symbol,
                "name": position.get("name") or row.get("name") or symbol,
                "quantity": position.get("quantity"),
                "avg_price": position.get("avg_price") or position.get("average_price"),
                "current_price": position.get("current_price") or row.get("close"),
                "pnl_pct": round(pnl_pct, 2),
                "today_change_pct": round(change, 2),
                "action": action,
            }
        )
    top_sector = sector_returns[0] if sector_returns else {}
    top_theme = themes[0] if themes else {}
    summary = (
        f"{work_date} 시장복기: 당일 주도테마 {top_theme.get('name', '-')} "
        f"({top_theme.get('avg_change_pct', 0)}%, 대금 {round(_number(top_theme.get('amount')) / 100_000_000, 1)}억), "
        f"3개월 주도섹터 {top_sector.get('name', '-')} ({top_sector.get('three_month_return_pct', 0)}%). "
        f"진입복기 {len(should_enter)}개, 회피복기 {len(should_avoid)}개."
    )
    report = {
        "id": f"MREF-{int(time.time() * 1000)}",
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "source": source,
        "cached": False,
        "work_date": work_date,
        "summary": summary,
        "kr_market_headline": (kr_market or {}).get("headline", "-"),
        "market_stance": (kr_market or {}).get("stance", "-"),
        "top_amount": [_market_brief_row(row) for row in top_amount[:12]],
        "top_volume": [_market_brief_row(row) for row in top_volume[:12]],
        "gainers": [_market_brief_row(row) for row in gainers[:12]],
        "losers": [_market_brief_row(row) for row in losers[:12]],
        "supply_audit": supply_audit,
        "themes_today": themes[:10] if isinstance(themes, list) else [],
        "sector_three_month_returns": sector_returns[:10],
        "should_have_entered": should_enter,
        "should_have_avoided": should_avoid,
        "missed_or_watch": missed_or_watch,
        "holding_reviews": holding_reviews,
        "research_ai_role": "거래대금/거래량/섹터 수익률/뉴스·공시를 묶어 다음 후보와 검증 과제를 만든다.",
        "operator_ai_role": "진입했어야 할 자리, 팔았어야 할 자리, 피했어야 할 자리와 주문 게이트를 복기한다.",
        "ops_action": ops_action or {},
        "replay_training": replay_training or {},
        "next_tasks": [
            "상위 거래대금 종목의 장초반 눌림/돌파 조건을 paper 리허설로 비교",
            "거래대금 동반 하락 종목은 손절/회피 사례로 저장",
            "3개월 주도 섹터와 당일 주도 테마가 겹치는 종목을 우선 후보로 재검증",
            "실전 보유종목은 매수 이유, 청산 기준, 당일 수급 변화를 매일 복기",
            "외국인·기관·개인 순매수와 거래대금·거래량·등락률 상위가 겹친 종목의 탐색 누락 원인을 대사",
        ],
        "safety": "시장복기 일지는 AI 학습/검증 기록이며 수익 보장이나 확정 매매 지시가 아닙니다.",
    }
    memory = MEMORY.append_market_reflection_memory(report)
    report["memory"] = {
        "ok": bool(memory.get("ok")),
        "note_path": memory.get("path"),
        "latest_path": memory.get("latest_path"),
    }
    _append_jsonl(MARKET_REFLECTION_FILE, report)
    _compact_jsonl(MARKET_REFLECTION_FILE, max_rows=800)
    JOURNAL.add("MARKET_REFLECTION_JOURNAL", summary, {"id": report["id"], "note_path": report["memory"].get("note_path")})
    return report


def latest_market_reflection_journal() -> dict[str, object]:
    rows = _read_jsonl(MARKET_REFLECTION_FILE, limit=1)
    return rows[-1] if rows else {}


def _promotion_candidate_index() -> dict[str, dict[str, object]]:
    rows = _read_jsonl(STRATEGY_PROMOTION_CANDIDATE_FILE)
    indexed: dict[str, dict[str, object]] = {}
    for row in rows:
        candidate_id = str(row.get("id", "")).strip()
        if candidate_id:
            indexed[candidate_id] = row
    return indexed


def _promotion_candidate_validation_evidence_hash(evidence: dict[str, object]) -> str:
    material = dict(evidence)
    material.pop("evidence_hash", None)
    canonical = json.dumps(material, ensure_ascii=True, sort_keys=True, separators=(",", ":"), default=str)
    return "sha256:" + hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _promotion_candidate_validation_evidence_status(candidate: dict[str, object]) -> dict[str, object]:
    """Verify that a Paper candidate came from provider OHLCV, not demo/synthetic prices."""
    evidence = candidate.get("validation_evidence") if isinstance(candidate.get("validation_evidence"), dict) else {}
    promotion = candidate.get("promotion") if isinstance(candidate.get("promotion"), dict) else {}
    validation = evidence.get("validation") if isinstance(evidence.get("validation"), dict) else {}
    lifecycle = evidence.get("lifecycle") if isinstance(evidence.get("lifecycle"), dict) else {}
    quality = evidence.get("data_quality") if isinstance(evidence.get("data_quality"), dict) else {}
    execution = evidence.get("execution_model") if isinstance(evidence.get("execution_model"), dict) else {}
    evidence_blockers: list[str] = []

    if str(evidence.get("schema") or "") != "codexstock_promotion_candidate_validation_v2":
        evidence_blockers.append("candidate_validation_evidence_missing_or_legacy")
    stored_hash = str(evidence.get("evidence_hash") or "")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", stored_hash):
        evidence_blockers.append("candidate_validation_evidence_hash_missing")
    elif stored_hash != _promotion_candidate_validation_evidence_hash(evidence):
        evidence_blockers.append("candidate_validation_evidence_hash_mismatch")
    candidate_id = str(candidate.get("id") or "").strip()
    symbol = str(candidate.get("symbol") or "").upper().strip()
    if not candidate_id or str(evidence.get("candidate_id") or "").strip() != candidate_id:
        evidence_blockers.append("candidate_validation_candidate_id_mismatch")
    if not symbol or str(evidence.get("symbol") or "").upper().strip() != symbol:
        evidence_blockers.append("candidate_validation_symbol_mismatch")
    created_date: date | None = None
    data_end_date: date | None = None
    first_paper_session_date: date | None = None
    try:
        created_date = datetime.fromisoformat(
            str(evidence.get("created_at") or "").replace("Z", "+00:00")
        ).date()
    except (TypeError, ValueError):
        evidence_blockers.append("candidate_created_at_invalid")
    try:
        data_end_date = date.fromisoformat(str(evidence.get("data_end_date") or "")[:10])
    except (TypeError, ValueError):
        evidence_blockers.append("candidate_data_end_date_invalid")
    try:
        first_paper_session_date = date.fromisoformat(
            str(evidence.get("first_paper_session_date") or "")[:10]
        )
    except (TypeError, ValueError):
        evidence_blockers.append("candidate_first_paper_session_invalid")
    if str(candidate.get("first_paper_session_date") or "") != str(
        evidence.get("first_paper_session_date") or ""
    ):
        evidence_blockers.append("candidate_first_paper_session_link_mismatch")
    if created_date is not None and data_end_date is not None and data_end_date > created_date:
        evidence_blockers.append("candidate_data_end_after_nomination")
    if created_date is not None and first_paper_session_date is not None:
        expected_first_session = _ai_staff_learning_roll_to_krx_session(
            created_date + timedelta(days=1),
            forward=True,
        )
        if first_paper_session_date != expected_first_session:
            evidence_blockers.append("candidate_next_session_cooling_contract_mismatch")
    if str(evidence.get("source_engine") or "") != "research_forge":
        evidence_blockers.append("candidate_source_not_research_forge")
    experiment_id = str(evidence.get("experiment_id") or "")
    if not re.fullmatch(r"exp_[A-Za-z0-9_]+", experiment_id):
        evidence_blockers.append("research_forge_experiment_id_missing")
    if str(evidence.get("experiment_status") or "") != "PAPER_CANDIDATE":
        evidence_blockers.append("research_forge_manual_paper_nomination_missing")
    adapter = str(evidence.get("adapter") or "")
    if adapter not in {
        "codexstock-local-ohlcv-v1",
        "codexstock-analytical-multitimeframe-v1",
    }:
        evidence_blockers.append("candidate_adapter_not_historical_provider")
    if "synthetic" in adapter.lower() or "mock" in adapter.lower():
        evidence_blockers.append("synthetic_or_mock_backtest_forbidden")
    if str(evidence.get("data_mode") or "") != "historical_provider":
        evidence_blockers.append("historical_provider_data_missing")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", str(evidence.get("dataset_hash") or "")):
        evidence_blockers.append("candidate_dataset_hash_missing_or_invalid")
    if int(_number(evidence.get("row_count"))) < 252:
        evidence_blockers.append("candidate_historical_rows_below_252")
    if quality.get("strict_temporal_order") is not True:
        evidence_blockers.append("candidate_temporal_order_not_strict")
    if int(_number(quality.get("duplicate_dates"))) != 0:
        evidence_blockers.append("candidate_duplicate_dates_present")
    if int(_number(quality.get("invalid_ohlc_rows"))) != 0:
        evidence_blockers.append("candidate_invalid_ohlc_present")
    if evidence.get("point_in_time_universe_passed") is not True:
        evidence_blockers.append("candidate_point_in_time_universe_missing")
    if evidence.get("adjusted_prices") is not True:
        evidence_blockers.append("candidate_corporate_action_adjustment_missing")
    if (str(evidence.get("signal_timing") or ""), str(evidence.get("fill_timing") or "")) not in {
        ("close_t", "open_t_plus_1"),
        ("close_t", "open_t_plus_delay"),
        ("completed_bar_t", "open_t_plus_delay"),
    }:
        evidence_blockers.append("candidate_next_bar_execution_missing")
    if str(execution.get("execution_mode") or "") not in {"REALISTIC", "CONSERVATIVE", "CUSTOM"}:
        evidence_blockers.append("candidate_execution_mode_optimistic_or_missing")
    if execution.get("costs_declared") is not True:
        evidence_blockers.append("candidate_transaction_costs_missing")
    if execution.get("liquidity_model_declared") is not True:
        evidence_blockers.append("candidate_liquidity_model_missing")
    if int(_number(execution.get("order_delay_bars"))) < 1:
        evidence_blockers.append("candidate_order_delay_missing")
    required_validation = {
        "passed": "candidate_validation_not_passed",
        "strict_walk_forward_passed": "candidate_strict_walk_forward_not_passed",
        "no_walk_forward_leakage": "candidate_walk_forward_leakage_detected",
        "label_horizon_purge_covered": "candidate_label_horizon_purge_missing",
        "parameter_robustness_passed": "candidate_parameter_robustness_not_passed",
    }
    for field, blocker in required_validation.items():
        if validation.get(field) is not True:
            evidence_blockers.append(blocker)
    if lifecycle.get("eligible_for_manual_paper_nomination") is not True:
        evidence_blockers.append("candidate_lifecycle_not_ready")
    if lifecycle.get("automatic_promotion") is not False:
        evidence_blockers.append("candidate_automatic_promotion_guard_missing")
    if lifecycle.get("report_bundle_verified") is not True:
        evidence_blockers.append("candidate_report_bundle_not_verified")
    if evidence.get("paper_only") is not True or evidence.get("live_order_allowed") is not False:
        evidence_blockers.append("candidate_paper_only_guard_missing")

    promotion_blockers: list[str] = []
    if str(promotion.get("stage") or "") != "PAPER_READY":
        promotion_blockers.append("promotion_candidate_stage_not_paper_ready")
    upstream_blockers = promotion.get("blockers") if isinstance(promotion.get("blockers"), list) else []
    if any(str(item).strip() for item in upstream_blockers):
        promotion_blockers.append("promotion_candidate_upstream_blockers_present")
    blockers = list(dict.fromkeys([*evidence_blockers, *promotion_blockers]))
    return {
        "verified": not blockers,
        "evidence_verified": not evidence_blockers,
        "status": "verified" if not blockers else "quarantined",
        "blockers": blockers,
        "evidence_blockers": list(dict.fromkeys(evidence_blockers)),
        "promotion_blockers": promotion_blockers,
        "experiment_id": experiment_id,
        "dataset_hash": evidence.get("dataset_hash"),
        "paper_only": True,
        "live_order_allowed": False,
    }


def _promotion_candidate_evidence_audit(
    rows: list[dict[str, object]] | None = None,
) -> dict[str, object]:
    source_rows = rows if rows is not None else _read_jsonl(STRATEGY_PROMOTION_CANDIDATE_FILE, limit=2000)
    verified_rows: list[dict[str, object]] = []
    quarantined_rows: list[dict[str, object]] = []
    blocker_counts: dict[str, int] = {}
    seen_experiments: set[str] = set()
    for original in source_rows:
        candidate = dict(original)
        status = _promotion_candidate_validation_evidence_status(candidate)
        experiment_id = str(status.get("experiment_id") or "")
        blockers = [str(item) for item in status.get("blockers", []) if str(item)]
        if status.get("verified") and experiment_id in seen_experiments:
            blockers.append("duplicate_research_forge_experiment_candidate")
        if not blockers:
            seen_experiments.add(experiment_id)
            candidate["validation_evidence_status"] = {**status, "blockers": []}
            verified_rows.append(candidate)
            continue
        for blocker in dict.fromkeys(blockers):
            blocker_counts[blocker] = blocker_counts.get(blocker, 0) + 1
        candidate["validation_evidence_status"] = {
            **status,
            "verified": False,
            "status": "quarantined",
            "blockers": list(dict.fromkeys(blockers)),
        }
        quarantined_rows.append(candidate)
    return {
        "ok": not quarantined_rows,
        "schema": "codexstock_promotion_candidate_evidence_audit_v1",
        "raw_count": len(source_rows),
        "verified_count": len(verified_rows),
        "quarantined_count": len(quarantined_rows),
        "unique_research_forge_experiment_count": len(seen_experiments),
        "blocker_counts": blocker_counts,
        "verified_rows": verified_rows,
        "quarantined_rows": quarantined_rows,
        "rule": (
            "Only manually nominated Research Forge experiments backed by provider OHLCV, a valid dataset hash, "
            "point-in-time universe, adjusted prices, next-bar execution, costs, liquidity, strict walk-forward, "
            "robustness, a verified report, and a next-KRX-session cooling boundary may create Paper rehearsal tickets."
        ),
        "paper_only": True,
        "live_order_allowed": False,
    }


def _promotion_rehearsal_entry_evidence_hash(evidence: dict[str, object]) -> str:
    material = dict(evidence)
    material.pop("evidence_hash", None)
    canonical = json.dumps(material, ensure_ascii=True, sort_keys=True, separators=(",", ":"), default=str)
    return "sha256:" + hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _promotion_rehearsal_entry_evidence_status(row: dict[str, object]) -> dict[str, object]:
    evidence = row.get("entry_quote_evidence") if isinstance(row.get("entry_quote_evidence"), dict) else {}
    blockers: list[str] = []
    entry_price = _number(row.get("price"))
    evidence_price = _number(evidence.get("price"))
    currency = str(evidence.get("currency") or "").strip().upper()
    expected_unit = f"{currency}_per_share" if currency else ""
    created_at = str(row.get("created_at") or "").strip()
    observed_at = str(evidence.get("observed_at") or "").strip()
    created_time: datetime | None = None
    observed_time: datetime | None = None
    try:
        created_time = datetime.fromisoformat(created_at.replace("Z", "+00:00"))
        if created_time.tzinfo is None:
            created_time = created_time.replace(tzinfo=_zone("Asia/Seoul", 9))
        created_time = created_time.astimezone(_zone("Asia/Seoul", 9))
    except (TypeError, ValueError):
        blockers.append("created_at_invalid")
    try:
        observed_time = datetime.fromisoformat(observed_at.replace("Z", "+00:00"))
        if observed_time.tzinfo is None:
            observed_time = observed_time.replace(tzinfo=_zone("Asia/Seoul", 9))
        observed_time = observed_time.astimezone(_zone("Asia/Seoul", 9))
    except (TypeError, ValueError):
        blockers.append("entry_quote_observed_at_invalid")
    if created_time is not None:
        created_date_text = created_time.date().isoformat()
        if created_time.weekday() >= 5 or created_date_text in KRX_CONFIRMED_CLOSED_DATES:
            blockers.append("rehearsal_not_krx_session_day")
        if created_time.hour * 60 + created_time.minute < 15 * 60 + 35:
            blockers.append("rehearsal_not_post_market_window")
    if created_time is not None and observed_time is not None:
        if created_time.date() != observed_time.date():
            blockers.append("entry_quote_rehearsal_date_mismatch")
        if abs((created_time - observed_time).total_seconds()) > 10 * 60:
            blockers.append("entry_quote_rehearsal_time_gap_above_10m")
    if str(row.get("ticket_status") or "") != "PAPER_FILLED":
        blockers.append("paper_ticket_not_filled")
    if not str(row.get("ticket_id") or "").strip():
        blockers.append("paper_ticket_id_missing")
    if not str(row.get("candidate_id") or "").strip():
        blockers.append("candidate_id_missing")
    if str(evidence.get("schema") or "") != "codexstock_promotion_rehearsal_entry_quote_v1":
        blockers.append("entry_quote_evidence_missing_or_legacy")
    stored_evidence_hash = str(evidence.get("evidence_hash") or "")
    if not stored_evidence_hash.startswith("sha256:"):
        blockers.append("entry_quote_evidence_hash_missing")
    elif stored_evidence_hash != _promotion_rehearsal_entry_evidence_hash(evidence):
        blockers.append("entry_quote_evidence_hash_mismatch")
    if evidence.get("official_mark_eligible") is not True:
        blockers.append("entry_quote_not_official_mark")
    if str(evidence.get("unit_status") or "") != "ok":
        blockers.append("entry_quote_unit_not_ok")
    if str(evidence.get("temporal_status") or "ok") != "ok":
        blockers.append("entry_quote_temporal_status_not_ok")
    if not str(evidence.get("snapshot_hash") or "").strip():
        blockers.append("entry_quote_snapshot_hash_missing")
    quote_row = evidence.get("quote_row") if isinstance(evidence.get("quote_row"), dict) else {}
    quote_row_hash = str(evidence.get("quote_row_hash") or "")
    if not quote_row:
        blockers.append("entry_quote_row_missing")
    else:
        recomputed_quote_row_hash = _common_quote_snapshot_hash([quote_row])
        if not quote_row_hash:
            blockers.append("entry_quote_row_hash_missing")
        elif quote_row_hash != recomputed_quote_row_hash:
            blockers.append("entry_quote_row_hash_mismatch")
        if str(evidence.get("snapshot_hash") or "") != recomputed_quote_row_hash:
            blockers.append("entry_quote_snapshot_row_hash_mismatch")
        if str(quote_row.get("symbol") or "").upper().strip() != str(row.get("symbol") or "").upper().strip():
            blockers.append("entry_quote_row_symbol_mismatch")
        if str(quote_row.get("currency") or "").upper().strip() != currency:
            blockers.append("entry_quote_row_currency_mismatch")
        if quote_row.get("official_mark_eligible") is not True:
            blockers.append("entry_quote_row_not_official_mark")
        quote_row_price = _number(quote_row.get("price"))
        if quote_row_price <= 0 or abs(quote_row_price - evidence_price) > max(0.01, evidence_price * 0.000001):
            blockers.append("entry_quote_row_price_mismatch")
    if not currency:
        blockers.append("entry_quote_currency_missing")
    if str(evidence.get("quote_unit") or "") != expected_unit:
        blockers.append("entry_quote_unit_contract_mismatch")
    if entry_price <= 0 or evidence_price <= 0:
        blockers.append("entry_quote_price_invalid")
    elif abs(entry_price - evidence_price) > max(0.01, evidence_price * 0.000001):
        blockers.append("entry_quote_price_record_mismatch")
    if row.get("paper_only") is not True or row.get("live_order_allowed") is not False:
        blockers.append("paper_only_guard_missing")
    if str(row.get("real_execution") or "") != "BLOCKED":
        blockers.append("real_execution_guard_missing")
    return {
        "verified": not blockers,
        "status": "verified" if not blockers else "quarantined",
        "blockers": list(dict.fromkeys(blockers)),
        "candidate_day_key": (
            f"{str(row.get('candidate_id') or '').strip()}|{created_at[:10]}"
            if str(row.get("candidate_id") or "").strip() and len(created_at) >= 10
            else ""
        ),
    }


def _promotion_rehearsal_artifact_blockers(
    row: dict[str, object],
    *,
    ticket_index: dict[str, dict[str, object]],
    candidate_index: dict[str, dict[str, object]],
) -> list[str]:
    blockers: list[str] = []
    ticket_id = str(row.get("ticket_id") or "").strip()
    candidate_id = str(row.get("candidate_id") or "").strip()
    symbol = str(row.get("symbol") or "").upper().strip()
    entry_evidence = row.get("entry_quote_evidence") if isinstance(row.get("entry_quote_evidence"), dict) else {}
    ticket = ticket_index.get(ticket_id, {})
    candidate = candidate_index.get(candidate_id, {})
    if not ticket:
        blockers.append("paper_ticket_artifact_missing")
    else:
        if str(ticket.get("status") or "") != "PAPER_FILLED":
            blockers.append("paper_ticket_artifact_not_filled")
        if str(ticket.get("mode") or "") != "paper" or str(ticket.get("side") or "").upper() != "BUY":
            blockers.append("paper_ticket_artifact_contract_mismatch")
        if str(ticket.get("symbol") or "").upper().strip() != symbol:
            blockers.append("paper_ticket_symbol_mismatch")
        if abs(_number(ticket.get("quantity")) - _number(row.get("quantity"))) > 0.000001:
            blockers.append("paper_ticket_quantity_mismatch")
        row_price = _number(row.get("price"))
        if abs(_number(ticket.get("price")) - row_price) > max(0.01, row_price * 0.000001):
            blockers.append("paper_ticket_price_mismatch")
        if str(ticket.get("real_execution") or "") != "BLOCKED" or str(ticket.get("guard") or "") != "paper_only_no_broker_order":
            blockers.append("paper_ticket_live_guard_mismatch")
        if str(ticket.get("risk_status") or "") != "PASSED":
            blockers.append("paper_ticket_risk_gate_not_passed")
        metadata = ticket.get("metadata") if isinstance(ticket.get("metadata"), dict) else {}
        if str(metadata.get("candidate_id") or "").strip() != candidate_id:
            blockers.append("paper_ticket_candidate_link_mismatch")
        ticket_evidence = metadata.get("entry_quote_evidence") if isinstance(metadata.get("entry_quote_evidence"), dict) else {}
        if str(ticket_evidence.get("evidence_hash") or "") != str(entry_evidence.get("evidence_hash") or ""):
            blockers.append("paper_ticket_quote_evidence_link_mismatch")
        if metadata.get("paper_only") is not True or metadata.get("live_order_allowed") is not False:
            blockers.append("paper_ticket_metadata_guard_missing")
    if not candidate:
        blockers.append("promotion_candidate_artifact_missing")
    else:
        if str(candidate.get("symbol") or "").upper().strip() != symbol:
            blockers.append("promotion_candidate_symbol_mismatch")
        candidate_status = _promotion_candidate_validation_evidence_status(candidate)
        blockers.extend(
            str(item)
            for item in candidate_status.get("blockers", [])
            if str(item)
        )
    return list(dict.fromkeys(blockers))


def _promotion_rehearsal_evidence_audit(
    rows: list[dict[str, object]],
    *,
    ticket_rows: list[dict[str, object]] | None = None,
    candidate_rows: list[dict[str, object]] | None = None,
) -> dict[str, object]:
    verified_rows: list[dict[str, object]] = []
    quarantined_rows: list[dict[str, object]] = []
    seen_candidate_days: set[str] = set()
    seen_experiment_days: set[str] = set()
    seen_ticket_ids: set[str] = set()
    verified_candidate_ids: set[str] = set()
    verified_experiment_ids: set[str] = set()
    blocker_counts: dict[str, int] = {}
    duplicate_count = 0
    source_tickets = ticket_rows if ticket_rows is not None else _read_jsonl(OPS.ticket_file, limit=5000)
    source_candidates = candidate_rows if candidate_rows is not None else _read_jsonl(STRATEGY_PROMOTION_CANDIDATE_FILE, limit=2000)
    ticket_index = {
        str(item.get("id") or "").strip(): item
        for item in source_tickets
        if isinstance(item, dict) and str(item.get("id") or "").strip()
    }
    candidate_index = {
        str(item.get("id") or "").strip(): item
        for item in source_candidates
        if isinstance(item, dict) and str(item.get("id") or "").strip()
    }
    for original in rows:
        row = dict(original)
        status = _promotion_rehearsal_entry_evidence_status(row)
        candidate_day_key = str(status.get("candidate_day_key") or "")
        blockers = [str(item) for item in status.get("blockers", []) if str(item)]
        ticket_id = str(row.get("ticket_id") or "").strip()
        candidate_id = str(row.get("candidate_id") or "").strip()
        candidate = candidate_index.get(candidate_id, {})
        candidate_status = (
            _promotion_candidate_validation_evidence_status(candidate)
            if candidate
            else {}
        )
        experiment_id = str(candidate_status.get("experiment_id") or "").strip()
        session_date = str(row.get("created_at") or "")[:10]
        experiment_day_key = (
            f"{experiment_id}|{session_date}"
            if experiment_id and len(session_date) == 10
            else ""
        )
        blockers.extend(
            _promotion_rehearsal_artifact_blockers(
                row,
                ticket_index=ticket_index,
                candidate_index=candidate_index,
            )
        )
        if status.get("verified") and candidate_day_key in seen_candidate_days:
            blockers.append("duplicate_candidate_day")
            duplicate_count += 1
        if status.get("verified") and experiment_day_key in seen_experiment_days:
            blockers.append("duplicate_research_forge_experiment_day")
        if ticket_id and ticket_id in seen_ticket_ids:
            blockers.append("duplicate_paper_ticket")
        if not blockers and candidate_day_key not in seen_candidate_days:
            seen_candidate_days.add(candidate_day_key)
            seen_experiment_days.add(experiment_day_key)
            seen_ticket_ids.add(ticket_id)
            verified_candidate_ids.add(candidate_id)
            verified_experiment_ids.add(experiment_id)
            row["entry_evidence_status"] = {**status, "blockers": []}
            row["candidate_evidence_identity"] = {
                "candidate_id": candidate_id,
                "research_forge_experiment_id": experiment_id,
                "dataset_hash": candidate_status.get("dataset_hash"),
            }
            verified_rows.append(row)
            continue
        for blocker in dict.fromkeys(blockers):
            blocker_counts[blocker] = blocker_counts.get(blocker, 0) + 1
        row["entry_evidence_status"] = {
            **status,
            "verified": False,
            "status": "quarantined",
            "blockers": list(dict.fromkeys(blockers)),
        }
        quarantined_rows.append(row)
    verified_dates = {
        str(row.get("created_at") or "")[:10]
        for row in verified_rows
        if len(str(row.get("created_at") or "")) >= 10
    }
    verified_symbols = {
        str(row.get("symbol") or "").upper().strip()
        for row in verified_rows
        if str(row.get("symbol") or "").strip()
    }
    return {
        "ok": not quarantined_rows,
        "schema": "codexstock_promotion_rehearsal_evidence_audit_v2",
        "raw_count": len(rows),
        "verified_count": len(verified_rows),
        "artifact_verified_count": len(verified_rows),
        "quarantined_count": len(quarantined_rows),
        "duplicate_candidate_day_count": duplicate_count,
        "verified_candidate_day_count": len(seen_candidate_days),
        "verified_research_experiment_day_count": len(seen_experiment_days),
        "unique_session_day_count": len(verified_dates),
        "unique_symbol_count": len(verified_symbols),
        "unique_candidate_count": len(verified_candidate_ids),
        "unique_research_forge_experiment_count": len(verified_experiment_ids),
        "verified_candidate_ids": sorted(verified_candidate_ids),
        "verified_research_forge_experiment_ids": sorted(verified_experiment_ids),
        "ticket_artifact_count": len(ticket_index),
        "candidate_artifact_count": len(candidate_index),
        "blocker_counts": blocker_counts,
        "verified_rows": verified_rows,
        "quarantined_rows": quarantined_rows,
        "rule": (
            "Count only one post-market KRX-session PAPER_FILLED rehearsal per candidate/date and "
            "Research Forge experiment/date whose self-hashed official quote evidence, Paper ticket ledger, "
            "and promotion-candidate ledger all reconcile."
        ),
        "live_order_allowed": False,
    }


def _promotion_rehearsal_readiness(audit: dict[str, object]) -> dict[str, object]:
    verified_count = int(_number(audit.get("verified_count")))
    unique_days = int(_number(audit.get("unique_session_day_count")))
    unique_symbols = int(_number(audit.get("unique_symbol_count")))
    unique_candidates = int(_number(audit.get("unique_candidate_count")))
    unique_experiments = int(_number(audit.get("unique_research_forge_experiment_count")))
    required_count = 20
    required_days = 5
    required_symbols = 3
    required_candidates = 3
    required_experiments = 3
    checks = [
        {"id": "verified_lifecycle_count", "ok": verified_count >= required_count, "value": verified_count, "required": required_count},
        {"id": "independent_session_days", "ok": unique_days >= required_days, "value": unique_days, "required": required_days},
        {"id": "symbol_diversity", "ok": unique_symbols >= required_symbols, "value": unique_symbols, "required": required_symbols},
        {"id": "candidate_diversity", "ok": unique_candidates >= required_candidates, "value": unique_candidates, "required": required_candidates},
        {"id": "research_experiment_diversity", "ok": unique_experiments >= required_experiments, "value": unique_experiments, "required": required_experiments},
    ]
    partial_score = round(
        min(verified_count / required_count, 1.0) * 6.0
        + min(unique_days / required_days, 1.0) * 1.5
        + min(unique_symbols / required_symbols, 1.0) * 1.0
        + min(unique_candidates / required_candidates, 1.0) * 0.75
        + min(unique_experiments / required_experiments, 1.0) * 0.75,
        2,
    )
    blockers = [str(item["id"]) for item in checks if not item["ok"]]
    return {
        "schema": "codexstock_promotion_rehearsal_readiness_v1",
        "ready": not blockers,
        "status": "verified_diverse_paper_rehearsal" if not blockers else "accruing_verified_paper_rehearsal",
        "verified_count": verified_count,
        "unique_session_day_count": unique_days,
        "unique_symbol_count": unique_symbols,
        "unique_candidate_count": unique_candidates,
        "unique_research_forge_experiment_count": unique_experiments,
        "required_verified_count": required_count,
        "required_unique_session_days": required_days,
        "required_unique_symbols": required_symbols,
        "required_unique_candidates": required_candidates,
        "required_unique_research_forge_experiments": required_experiments,
        "remaining_verified_count": max(0, required_count - verified_count),
        "minimum_additional_session_days_at_three_per_day": math.ceil(
            max(0, required_count - verified_count) / 3
        ),
        "partial_score": partial_score,
        "checks": checks,
        "blockers": blockers,
        "paper_only": True,
        "live_order_allowed": False,
    }


def _promotion_forward_observation_hash(row: dict[str, object]) -> str:
    material = dict(row)
    material.pop("observation_hash", None)
    canonical = json.dumps(material, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    return "sha256:" + hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _promotion_forward_candidate_digest_hash(digest: object) -> str:
    normalized = digest if isinstance(digest, list) else []
    canonical = json.dumps(normalized, ensure_ascii=True, sort_keys=True)
    return "sha256:" + hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _promotion_forward_session_dates(start: date, end: date) -> list[date]:
    if end < start:
        return []
    sessions: list[date] = []
    current = start
    while current <= end:
        if current.weekday() < 5 and current.isoformat() not in KRX_CONFIRMED_CLOSED_DATES:
            sessions.append(current)
        current += timedelta(days=1)
    return sessions


def _record_promotion_forward_observation(
    result: dict[str, object],
    *,
    current_time: datetime,
    operating_focus: dict[str, object],
    source: str,
) -> dict[str, object]:
    """Append one immutable post-market Paper observation per verified KRX session."""
    observed_at = current_time.astimezone(_zone("Asia/Seoul", 9))
    observed_date = observed_at.date().isoformat()
    with PROMOTION_FORWARD_OBSERVATION_LOCK:
        existing_rows = _read_jsonl(PROMOTION_FORWARD_OBSERVATION_FILE, limit=800)
        existing = next(
            (
                row
                for row in reversed(existing_rows)
                if isinstance(row, dict) and str(row.get("observed_date") or "") == observed_date
            ),
            {},
        )
        if existing:
            return {
                "ok": True,
                "status": "already_recorded_for_session",
                "recorded": False,
                "record": existing,
                "path": str(PROMOTION_FORWARD_OBSERVATION_FILE),
                "paper_only": True,
                "live_order_allowed": False,
            }
        result_rows = [row for row in result.get("results", []) if isinstance(row, dict)]
        candidate_digest = [
            {
                "candidate_id": row.get("candidate_id")
                or (row.get("rehearsal", {}) if isinstance(row.get("rehearsal"), dict) else {}).get("candidate_id"),
                "symbol": row.get("symbol")
                or (row.get("rehearsal", {}) if isinstance(row.get("rehearsal"), dict) else {}).get("symbol"),
                "status": row.get("status"),
                "ok": bool(row.get("ok")),
                "ticket_status": (
                    row.get("ticket", {}).get("status")
                    if isinstance(row.get("ticket"), dict)
                    else None
                ),
                "entry_snapshot_hash": (
                    row.get("entry_quote_evidence", {}).get("snapshot_hash")
                    if isinstance(row.get("entry_quote_evidence"), dict)
                    else None
                ),
            }
            for row in result_rows
        ]
        digest_hash = _promotion_forward_candidate_digest_hash(candidate_digest)
        previous_hash = str(existing_rows[-1].get("observation_hash") or "") if existing_rows else ""
        record: dict[str, object] = {
            "schema": "codexstock_promotion_forward_observation_v1",
            "id": f"PFO-{int(observed_at.timestamp() * 1000)}",
            "observed_date": observed_date,
            "observed_at": observed_at.isoformat(timespec="seconds"),
            "source": source,
            "result_status": str(result.get("status") or "unknown"),
            "market_session_verified": bool(
                observed_at.weekday() < 5
                and observed_date not in KRX_CONFIRMED_CLOSED_DATES
                and operating_focus.get("market_closed_day") is not True
            ),
            "post_market_window_verified": observed_at.hour * 60 + observed_at.minute >= 15 * 60 + 35,
            "operating_focus_mode": operating_focus.get("mode"),
            "eligible_candidate_count": int(_number(result.get("eligible_candidate_count"))),
            "created_rehearsal_count": int(_number(result.get("created_count"))),
            "filled_rehearsal_count": int(_number(result.get("filled_count"))),
            "candidate_result_count": len(candidate_digest),
            "candidate_result_digest": candidate_digest,
            "candidate_result_hash": digest_hash,
            "previous_observation_hash": previous_hash,
            "paper_only": True,
            "live_order_allowed": False,
            "real_execution": "BLOCKED",
        }
        record["observation_hash"] = _promotion_forward_observation_hash(record)
        _append_jsonl(PROMOTION_FORWARD_OBSERVATION_FILE, record)
        _compact_jsonl(PROMOTION_FORWARD_OBSERVATION_FILE, max_rows=600)
    return {
        "ok": True,
        "status": "recorded",
        "recorded": True,
        "record": record,
        "path": str(PROMOTION_FORWARD_OBSERVATION_FILE),
        "paper_only": True,
        "live_order_allowed": False,
    }


def build_promotion_forward_observation_audit(
    rows: list[dict[str, object]] | None = None,
    *,
    now: datetime | None = None,
) -> dict[str, object]:
    """Prove continuous forward operation instead of using two distant timestamps."""
    current = now or datetime.now(_zone("Asia/Seoul", 9))
    if current.tzinfo is None:
        current = current.replace(tzinfo=_zone("Asia/Seoul", 9))
    else:
        current = current.astimezone(_zone("Asia/Seoul", 9))
    source_rows = rows if rows is not None else _read_jsonl(PROMOTION_FORWARD_OBSERVATION_FILE, limit=800)
    verified_rows: list[dict[str, object]] = []
    quarantined_rows: list[dict[str, object]] = []
    seen_dates: set[str] = set()
    previous_stored_hash = ""
    previous_date: date | None = None
    blocker_counts: dict[str, int] = {}
    allowed_statuses = {"no_due_candidate", "completed", "completed_with_blockers"}
    for index, original in enumerate(source_rows):
        if not isinstance(original, dict):
            continue
        row = dict(original)
        blockers: list[str] = []
        observed_date_text = str(row.get("observed_date") or "")
        observed_at_text = str(row.get("observed_at") or "")
        try:
            observed_date = datetime.fromisoformat(observed_date_text).date()
        except (TypeError, ValueError):
            observed_date = date.min
            blockers.append("observed_date_invalid")
        try:
            observed_at = datetime.fromisoformat(observed_at_text.replace("Z", "+00:00"))
            if observed_at.tzinfo is None:
                observed_at = observed_at.replace(tzinfo=_zone("Asia/Seoul", 9))
            observed_at = observed_at.astimezone(_zone("Asia/Seoul", 9))
        except (TypeError, ValueError):
            observed_at = None
            blockers.append("observed_at_invalid")
        if str(row.get("schema") or "") != "codexstock_promotion_forward_observation_v1":
            blockers.append("schema_invalid")
        if observed_at is not None and observed_at.date() != observed_date:
            blockers.append("observed_date_timestamp_mismatch")
        if (
            observed_at is not None
            and observed_at > current
        ) or observed_date > current.date():
            blockers.append("observation_after_audit_cutoff")
        if observed_at is not None and observed_at.hour * 60 + observed_at.minute < 15 * 60 + 35:
            blockers.append("post_market_window_not_proven")
        if observed_date.weekday() >= 5 or observed_date_text in KRX_CONFIRMED_CLOSED_DATES:
            blockers.append("krx_session_day_not_valid")
        if row.get("market_session_verified") is not True:
            blockers.append("market_session_not_verified")
        if row.get("post_market_window_verified") is not True:
            blockers.append("post_market_flag_missing")
        if str(row.get("result_status") or "") not in allowed_statuses:
            blockers.append("result_status_not_observation_eligible")
        candidate_result_digest = row.get("candidate_result_digest")
        candidate_result_hash = str(row.get("candidate_result_hash") or "")
        if not candidate_result_hash.startswith("sha256:"):
            blockers.append("candidate_result_hash_missing")
        elif candidate_result_hash != _promotion_forward_candidate_digest_hash(candidate_result_digest):
            blockers.append("candidate_result_hash_mismatch")
        if row.get("paper_only") is not True or row.get("live_order_allowed") is not False:
            blockers.append("paper_only_guard_missing")
        if str(row.get("real_execution") or "") != "BLOCKED":
            blockers.append("real_execution_guard_missing")
        stored_hash = str(row.get("observation_hash") or "")
        if stored_hash != _promotion_forward_observation_hash(row):
            blockers.append("observation_hash_mismatch")
        if index > 0 and str(row.get("previous_observation_hash") or "") != previous_stored_hash:
            blockers.append("observation_hash_chain_mismatch")
        if observed_date_text in seen_dates:
            blockers.append("duplicate_observation_date")
        if previous_date is not None and observed_date < previous_date:
            blockers.append("observation_date_out_of_order")
        previous_stored_hash = stored_hash
        previous_date = observed_date if observed_date != date.min else previous_date
        if blockers:
            for blocker in dict.fromkeys(blockers):
                blocker_counts[blocker] = blocker_counts.get(blocker, 0) + 1
            row["audit_blockers"] = list(dict.fromkeys(blockers))
            quarantined_rows.append(row)
            continue
        seen_dates.add(observed_date_text)
        verified_rows.append(row)

    coverage_end = current.date()
    if current.hour * 60 + current.minute < 15 * 60 + 35:
        coverage_end -= timedelta(days=1)
    while coverage_end.weekday() >= 5 or coverage_end.isoformat() in KRX_CONFIRMED_CLOSED_DATES:
        coverage_end -= timedelta(days=1)
    valid_dates = sorted(datetime.fromisoformat(str(row["observed_date"])).date() for row in verified_rows)
    first_date = valid_dates[0] if valid_dates else None
    last_date = valid_dates[-1] if valid_dates else None
    expected_sessions = _promotion_forward_session_dates(first_date, coverage_end) if first_date else []
    valid_date_set = set(valid_dates)
    missing_sessions = [session for session in expected_sessions if session not in valid_date_set]
    coverage_pct = round(
        len(valid_date_set.intersection(expected_sessions)) / len(expected_sessions) * 100.0,
        2,
    ) if expected_sessions else 0.0
    max_missing_streak = 0
    current_missing_streak = 0
    for session in expected_sessions:
        if session in valid_date_set:
            current_missing_streak = 0
        else:
            current_missing_streak += 1
            max_missing_streak = max(max_missing_streak, current_missing_streak)
    latest_session_observed = bool(expected_sessions and expected_sessions[-1] in valid_date_set)
    calendar_span_days = (last_date - first_date).days if first_date and last_date else 0
    observation_window_calendar_days = calendar_span_days + 1 if first_date and last_date else 0
    verified_status_counts: dict[str, int] = {}
    verified_candidate_ids: set[str] = set()
    verified_symbols: set[str] = set()
    for row in verified_rows:
        status_text = str(row.get("result_status") or "unknown")
        verified_status_counts[status_text] = verified_status_counts.get(status_text, 0) + 1
        digest_rows = (
            row.get("candidate_result_digest")
            if isinstance(row.get("candidate_result_digest"), list)
            else []
        )
        for digest in digest_rows:
            if not isinstance(digest, dict):
                continue
            candidate_id = str(digest.get("candidate_id") or "").strip()
            symbol = str(digest.get("symbol") or "").strip().upper()
            if candidate_id:
                verified_candidate_ids.add(candidate_id)
            if symbol:
                verified_symbols.add(symbol)
    last_observation_hash = (
        str(verified_rows[-1].get("observation_hash") or "")
        if verified_rows
        else ""
    )
    hash_chain_complete = bool(
        verified_rows
        and not quarantined_rows
        and all(str(row.get("observation_hash") or "").startswith("sha256:") for row in verified_rows)
    )
    coverage_quality_passed = bool(
        verified_rows
        and not quarantined_rows
        and coverage_pct >= 95.0
        and max_missing_streak <= 2
        and latest_session_observed
    )
    verified_forward_days = observation_window_calendar_days if coverage_quality_passed else 0
    blockers: list[str] = []
    if not verified_rows:
        blockers.append("no_verified_forward_observation_days")
    if quarantined_rows:
        blockers.append("forward_observation_integrity_failure")
    if coverage_pct < 95.0:
        blockers.append("forward_observation_coverage_below_95_pct")
    if max_missing_streak > 2:
        blockers.append("forward_observation_gap_above_two_sessions")
    if expected_sessions and not latest_session_observed:
        blockers.append("latest_required_session_observation_missing")
    if observation_window_calendar_days < 90:
        blockers.append("forward_calendar_span_below_90_days")
    if len(verified_rows) < 50:
        blockers.append("forward_observation_day_count_below_50")
    next_required = missing_sessions[0] if missing_sessions else coverage_end + timedelta(days=1)
    while next_required.weekday() >= 5 or next_required.isoformat() in KRX_CONFIRMED_CLOSED_DATES:
        next_required += timedelta(days=1)
    ready = not blockers
    return {
        "ok": True,
        "schema": "codexstock_promotion_forward_observation_audit_v1",
        "status": "verified_90_day_forward_operation" if ready else "accruing_forward_evidence",
        "ready": ready,
        "required_calendar_days": 90,
        "minimum_observation_day_count": 50,
        "minimum_session_coverage_pct": 95.0,
        "maximum_missing_session_streak": 2,
        "raw_row_count": len(source_rows),
        "verified_observation_day_count": len(verified_rows),
        "quarantined_row_count": len(quarantined_rows),
        "first_observation_date": first_date.isoformat() if first_date else "",
        "last_observation_date": last_date.isoformat() if last_date else "",
        "coverage_end_date": coverage_end.isoformat(),
        "audit_cutoff_at": current.isoformat(timespec="seconds"),
        "future_observation_row_count": int(
            blocker_counts.get("observation_after_audit_cutoff", 0)
        ),
        "calendar_span_days": calendar_span_days,
        "observation_window_calendar_days": observation_window_calendar_days,
        "calendar_day_count_policy": "inclusive_first_and_last_observation_dates",
        "verified_forward_days": verified_forward_days,
        "days_remaining": max(0, 90 - verified_forward_days),
        "expected_session_count": len(expected_sessions),
        "session_coverage_pct": coverage_pct,
        "missing_session_count": len(missing_sessions),
        "missing_session_dates": [item.isoformat() for item in missing_sessions[:30]],
        "max_consecutive_missing_sessions": max_missing_streak,
        "latest_required_session_observed": latest_session_observed,
        "next_required_observation_date": next_required.isoformat(),
        "coverage_quality_passed": coverage_quality_passed,
        "evidence_integrity": {
            "schema": "codexstock_forward_observation_integrity_v1",
            "hash_chain_complete": hash_chain_complete,
            "last_observation_hash": last_observation_hash,
            "verified_result_status_counts": verified_status_counts,
            "unique_candidate_count": len(verified_candidate_ids),
            "unique_symbol_count": len(verified_symbols),
            "candidate_result_hash_policy": "sha256_digest_must_match_candidate_result_digest",
            "observation_hash_policy": "append_only_hash_chain_previous_observation_hash",
            "future_rows_quarantined": int(
                blocker_counts.get("observation_after_audit_cutoff", 0)
            ),
            "paper_only": True,
            "live_order_allowed": False,
        },
        "blockers": list(dict.fromkeys(blockers)),
        "blocker_counts": blocker_counts,
        "verified_rows": verified_rows,
        "quarantined_rows": quarantined_rows,
        "automatic_observer": build_promotion_forward_observer_status(now=current),
        "paper_only": True,
        "live_order_allowed": False,
        "operator_message": (
            "90일 순방향 관찰 증거가 검증되었습니다."
            if ready
            else f"순방향 관찰 {verified_forward_days}/90일, 유효 관찰일 {len(verified_rows)}개, "
            f"다음 필수 기록일 {next_required.isoformat()}입니다."
        ),
    }


def _promotion_rehearsal_mark(row: dict[str, object], quote_cache: dict[str, dict[str, object]]) -> dict[str, object]:
    symbol = str(row.get("symbol", "")).upper().strip()
    entry_price = _number(row.get("price"))
    quantity = _number(row.get("quantity"))
    if symbol and symbol not in quote_cache:
        try:
            quote_cache[symbol] = ops_quote(symbol)
        except Exception as exc:
            quote_cache[symbol] = {"symbol": symbol, "price": 0, "source": f"시세 실패: {exc}"}
    quote = quote_cache.get(symbol, {"symbol": symbol, "price": 0, "source": "시세 없음"})
    current_price = _number(quote.get("price"))
    price_ratio = current_price / entry_price if entry_price > 0 and current_price > 0 else 0.0
    unit_issues: list[str] = []
    if symbol.isdigit() and len(symbol) == 6 and entry_price > 0 and current_price >= 1_000 and entry_price < 1_000:
        unit_issues.append("krw_entry_price_below_plausible_unit")
    if price_ratio and (price_ratio < 0.05 or price_ratio > 20.0):
        unit_issues.append("entry_current_price_ratio_outlier")
    entry_evidence_status = _promotion_rehearsal_entry_evidence_status(row)
    if not entry_evidence_status.get("verified"):
        unit_issues.extend(str(item) for item in entry_evidence_status.get("blockers", []) if str(item))
    unit_issues = list(dict.fromkeys(unit_issues))
    performance_eligible = bool(
        entry_price > 0
        and current_price > 0
        and not unit_issues
        and entry_evidence_status.get("verified")
    )
    entry_value = entry_price * quantity
    market_value = current_price * quantity
    pnl = market_value - entry_value if performance_eligible else 0.0
    pnl_pct = ((current_price / entry_price) - 1) * 100 if performance_eligible else 0.0
    if current_price <= 0:
        verdict = "시세 대기"
    elif unit_issues:
        verdict = "가격·통화 단위 불일치 격리"
    elif pnl_pct >= 3:
        verdict = "강세 리허설"
    elif pnl_pct <= -3:
        verdict = "위험 리허설"
    elif pnl_pct >= 0:
        verdict = "양호 관찰"
    else:
        verdict = "약보합 관찰"
    return {
        "symbol": symbol,
        "entry_price": round(entry_price, 4),
        "current_price": round(current_price, 4),
        "quantity": quantity,
        "entry_value": round(entry_value, 2),
        "market_value": round(market_value, 2),
        "pnl": round(pnl, 2),
        "pnl_pct": round(pnl_pct, 2),
        "price_ratio": round(price_ratio, 6),
        "performance_eligible": performance_eligible,
        "learning_eligible": performance_eligible,
        "unit_issues": unit_issues,
        "entry_evidence_status": entry_evidence_status,
        "quote_source": quote.get("source", ""),
        "verdict": verdict,
        "updated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
    }


def _promotion_rehearsal_review(mark: dict[str, object], candidate: dict[str, object]) -> dict[str, object]:
    pnl_pct = _number(mark.get("pnl_pct"))
    current_price = _number(mark.get("current_price"))
    max_drawdown = abs(_number(candidate.get("max_drawdown_pct"))) if candidate else 0.0
    promotion = candidate.get("promotion") if isinstance(candidate.get("promotion"), dict) else {}
    readiness = _number(promotion.get("readiness_score")) if promotion else 0.0
    checks: list[str] = []
    if not bool(mark.get("performance_eligible", True)):
        status = "QUARANTINED_UNIT_MISMATCH"
        label = "단위 불일치 격리"
        severity = "warning"
        action = "진입가의 통화·단위를 복구하기 전까지 공식 Paper 성과와 학습에서 제외합니다."
        checks.append("가격·통화·단위가 현재 시세와 맞지 않아 성과 승격을 차단했습니다.")
    elif max_drawdown >= 25:
        checks.append("백테스트 MDD가 큰 편이라 paper 구간 손실 확대를 더 민감하게 봅니다.")
    if readiness < 70:
        checks.append("승급 준비도가 충분히 높지 않아 관찰 기간을 더 둡니다.")
    if not bool(mark.get("performance_eligible", True)):
        pass
    elif current_price <= 0:
        status = "WAIT_QUOTE"
        label = "시세 대기"
        severity = "wait"
        action = "시세가 들어올 때까지 판단을 보류하고 데이터 연결 상태를 확인합니다."
    elif pnl_pct <= -5:
        status = "RISK_REVIEW"
        label = "위험 복기"
        severity = "danger"
        action = "손실 원인을 복기하고 같은 조건의 추가 paper 진입은 보류합니다."
        checks.append("진입가 대비 -5% 이하입니다. 손절/전략 훼손 조건을 점검합니다.")
    elif pnl_pct <= -3:
        status = "RISK_WATCH"
        label = "손실 경계"
        severity = "warning"
        action = "가격 회복 여부와 거래량 변화를 다음 점검에서 우선 확인합니다."
        checks.append("진입가 대비 -3% 이하입니다. 후보 승급은 보류합니다.")
    elif pnl_pct >= 5:
        status = "PROFIT_LOCK_REVIEW"
        label = "수익보호 검토"
        severity = "success"
        action = "paper 수익을 보호하는 추적손절/부분청산 규칙을 가정해 복기합니다."
        checks.append("진입가 대비 +5% 이상입니다. 수익 보호 규칙 검증 대상으로 올립니다.")
    elif pnl_pct >= 2:
        status = "WINNER_WATCH"
        label = "강세 관찰"
        severity = "success"
        action = "추세 지속 여부를 관찰하고 다음 백테스트/워크포워드 검증 후보로 유지합니다."
    elif pnl_pct >= 0:
        status = "CONTINUE_OBSERVE"
        label = "계속 관찰"
        severity = "ok"
        action = "큰 훼손이 없으므로 다음 점검까지 paper 상태를 유지합니다."
    else:
        status = "WEAK_OBSERVE"
        label = "약보합 관찰"
        severity = "warning"
        action = "손실 폭은 작지만 진입 근거가 유지되는지 다음 점검에서 확인합니다."
    if not checks:
        checks.append("실거래 신호가 아니라 paper 리허설 복기용 판단입니다.")
    return {
        "status": status,
        "label": label,
        "severity": severity,
        "action": action,
        "checks": checks,
        "guardrail": "이 복기 판정은 모의운용 점검용이며 실거래 주문 지시가 아닙니다.",
    }


def _hydrate_promotion_rehearsal(row: dict[str, object], candidate_lookup: dict[str, dict[str, object]], quote_cache: dict[str, dict[str, object]]) -> dict[str, object]:
    rehearsal = dict(row)
    candidate_id = str(rehearsal.get("candidate_id", "")).strip()
    candidate = candidate_lookup.get(candidate_id, {})
    if candidate:
        promotion = candidate.get("promotion") if isinstance(candidate.get("promotion"), dict) else {}
        summaries = candidate.get("summaries") if isinstance(candidate.get("summaries"), dict) else {}
        relative = summaries.get("relative") if isinstance(summaries.get("relative"), dict) else {}
        rehearsal["candidate"] = {
            "id": candidate.get("id"),
            "symbol": candidate.get("symbol"),
            "fast": candidate.get("fast"),
            "slow": candidate.get("slow"),
            "test_return_pct": candidate.get("test_return_pct"),
            "max_drawdown_pct": candidate.get("max_drawdown_pct"),
            "relative_score": relative.get("relative_score"),
            "promotion": {
                "stage": promotion.get("stage"),
                "label": promotion.get("label"),
                "readiness_score": promotion.get("readiness_score"),
            },
        }
    mark = _promotion_rehearsal_mark(rehearsal, quote_cache)
    rehearsal["mark"] = mark
    rehearsal["entry_evidence_status"] = mark.get("entry_evidence_status", {})
    rehearsal["review"] = _promotion_rehearsal_review(mark, rehearsal.get("candidate", {}) if isinstance(rehearsal.get("candidate"), dict) else {})
    return rehearsal


def _promotion_rehearsals(limit: int = 50) -> list[dict[str, object]]:
    rows = _read_jsonl(STRATEGY_PROMOTION_REHEARSAL_FILE, limit=limit)
    candidate_lookup = _promotion_candidate_index()
    quote_cache: dict[str, dict[str, object]] = {}
    return list(reversed([_hydrate_promotion_rehearsal(row, candidate_lookup, quote_cache) for row in rows]))


def _find_promotion_rehearsal(rehearsal_id: str = "", candidate_id: str = "") -> dict[str, object] | None:
    rows = _promotion_rehearsals(limit=200)
    if not rows:
        return None
    rehearsal_id = rehearsal_id.strip()
    candidate_id = candidate_id.strip()
    if not rehearsal_id and not candidate_id:
        return rows[0]
    for row in rows:
        if rehearsal_id and str(row.get("id", "")) == rehearsal_id:
            return row
        if candidate_id and str(row.get("candidate_id", "")) == candidate_id:
            return row
    return None


def _promotion_rehearsal_report_text(rehearsal: dict[str, object]) -> str:
    mark = rehearsal.get("mark") if isinstance(rehearsal.get("mark"), dict) else {}
    review = rehearsal.get("review") if isinstance(rehearsal.get("review"), dict) else {}
    candidate = rehearsal.get("candidate") if isinstance(rehearsal.get("candidate"), dict) else {}
    promotion = candidate.get("promotion") if isinstance(candidate.get("promotion"), dict) else {}
    checks = review.get("checks") if isinstance(review.get("checks"), list) else []
    lines = [
        "[Paper 리허설 복기 보고]",
        f"생성: {datetime.now(ZoneInfo('Asia/Seoul')).isoformat(timespec='seconds')}",
        "실전 주문: BLOCKED",
        "",
        f"종목: {rehearsal.get('symbol', '-')}",
        f"티켓: {rehearsal.get('ticket_id', '-')} / {rehearsal.get('ticket_status', '-')}",
        f"전략: MA {candidate.get('fast', '-')}/{candidate.get('slow', '-')} / {promotion.get('label', '전략 후보')}",
        f"진입가: {_number(mark.get('entry_price')):,.2f}",
        f"현재가: {_number(mark.get('current_price')):,.2f}",
        f"평가손익: {_number(mark.get('pnl')):,.2f} ({_number(mark.get('pnl_pct')):+.2f}%)",
        f"복기 판정: {review.get('label', mark.get('verdict', '-'))}",
        f"다음 행동: {review.get('action', '다음 점검까지 paper 상태를 유지합니다.')}",
    ]
    if checks:
        lines.append("")
        lines.append("점검 메모:")
        for item in checks[:4]:
            lines.append(f"- {item}")
    lines.append("")
    lines.append("주의: 이 보고서는 모의운용 복기용이며 실거래 주문 지시가 아닙니다.")
    return "\n".join(lines)


def build_simple_trade_telegram_text(
    trade: dict[str, object],
    *,
    report_mode: str,
    reason: str = "",
    exit_plan: str = "",
) -> str:
    """Build a short, unmistakable Paper/live trade message for Telegram."""
    normalized_mode = str(report_mode or "paper").strip().lower()
    labels = {
        "paper": "[모의매매]",
        "live_plan": "[실제매매 예정]",
        "live_execution": "[실제매매 주문]",
    }
    label = labels.get(normalized_mode, "[모의매매]")
    side = str(trade.get("side") or "BUY").upper().strip()
    action = "매수" if side == "BUY" else "매도"
    symbol = str(trade.get("symbol") or "-").upper().strip()
    name = resolve_symbol_display_name(symbol, trade.get("name"), trade.get("symbol_name")) if symbol != "-" else "-"
    quantity = _number(trade.get("quantity"))
    price = _number(trade.get("price"))
    happened_at = str(trade.get("created_at") or trade.get("submitted_at") or datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"))
    clean_reason = " ".join(str(reason or trade.get("reason") or trade.get("memo") or "판단 근거 기록 없음").split())[:220]
    if not exit_plan:
        if side == "SELL":
            exit_plan = "매도 완료. 다음 후보를 다시 검토합니다."
        elif normalized_mode == "paper":
            exit_plan = "손절·익절·재료 약화 기준이 오면 모의매도합니다."
        else:
            exit_plan = "손절·익절·재료 약화·장중 흐름 훼손 기준이 오면 매도합니다."
    status_line = {
        "paper": f"무엇: {name}({symbol}) {quantity:g}주 모의{action}",
        "live_plan": f"할 일: {name}({symbol}) {quantity:g}주 실제{action} 예정",
        "live_execution": f"한 일: {name}({symbol}) {quantity:g}주 실제{action} 주문 제출",
    }.get(normalized_mode, f"무엇: {name}({symbol}) {quantity:g}주 모의{action}")
    lines = [label, status_line]
    if price > 0:
        lines.append(f"가격: {price:,.0f}원")
    lines.extend(
        [
            f"시간: {happened_at}",
            f"이유: {clean_reason}",
            f"언제 팔지: {'해당 없음' if side == 'SELL' else exit_plan}",
        ]
    )
    if normalized_mode == "paper":
        lines.append("주의: 실제 계좌 주문이 아닙니다.")
    return "\n".join(lines)


def queue_simple_trade_telegram(
    trade: dict[str, object],
    *,
    report_mode: str,
    reason: str = "",
    exit_plan: str = "",
    source: str = "trade-reporter",
) -> dict[str, object]:
    text = build_simple_trade_telegram_text(
        trade,
        report_mode=report_mode,
        reason=reason,
        exit_plan=exit_plan,
    )
    return OPS.queue_telegram(
        text=text,
        message_type=f"simple_trade_{report_mode}",
        source=source,
        metadata={
            "report_mode": report_mode,
            "symbol": trade.get("symbol"),
            "side": trade.get("side"),
            "ticket_id": trade.get("id") or trade.get("ticket_id"),
        },
    )


def _promotion_rehearsal_digest(limit: int = 20) -> dict[str, object]:
    rows = _promotion_rehearsals(limit=limit)
    evidence_audit = _promotion_rehearsal_evidence_audit(rows)
    readiness = _promotion_rehearsal_readiness(evidence_audit)
    verified_entry_rows = [
        row for row in evidence_audit.get("verified_rows", []) if isinstance(row, dict)
    ]
    eligible_rows = [
        row
        for row in verified_entry_rows
        if isinstance(row.get("mark"), dict) and bool((row.get("mark") or {}).get("performance_eligible", True))
    ]
    quarantined_rows = [
        row for row in evidence_audit.get("quarantined_rows", []) if isinstance(row, dict)
    ]
    mark_unavailable_rows = [row for row in verified_entry_rows if row not in eligible_rows]
    total_pnl = sum(_number((row.get("mark") or {}).get("pnl")) for row in eligible_rows)
    avg_pnl_pct = (
        sum(_number((row.get("mark") or {}).get("pnl_pct")) for row in eligible_rows) / len(eligible_rows)
        if eligible_rows
        else 0.0
    )
    by_status: dict[str, int] = {}
    by_severity: dict[str, int] = {}
    for row in rows:
        review = row.get("review") if isinstance(row.get("review"), dict) else {}
        status = str(review.get("status", "UNKNOWN"))
        severity = str(review.get("severity", "ok"))
        by_status[status] = by_status.get(status, 0) + 1
        by_severity[severity] = by_severity.get(severity, 0) + 1
    sorted_rows = sorted(eligible_rows, key=lambda item: _number((item.get("mark") or {}).get("pnl_pct")) if isinstance(item.get("mark"), dict) else 0.0, reverse=True)
    return {
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "count": len(rows),
        "verified_entry_count": len(verified_entry_rows),
        "performance_eligible_count": len(eligible_rows),
        "quarantined_count": len(quarantined_rows),
        "quarantined_rows": quarantined_rows[:8],
        "mark_unavailable_count": len(mark_unavailable_rows),
        "entry_evidence_audit": {
            key: value
            for key, value in evidence_audit.items()
            if key not in {"verified_rows", "quarantined_rows"}
        },
        "readiness": readiness,
        "total_pnl": round(total_pnl, 2),
        "avg_pnl_pct": round(avg_pnl_pct, 2),
        "by_status": by_status,
        "by_severity": by_severity,
        "winners": sorted_rows[:3],
        "risks": list(reversed(sorted_rows[-3:])),
        "rows": rows,
        "real_execution": "BLOCKED",
        "safety": "모의운용 복기 요약이며 실거래 주문 지시가 아닙니다.",
    }


def _promotion_rehearsal_digest_text(digest: dict[str, object]) -> str:
    rows = digest.get("rows") if isinstance(digest.get("rows"), list) else []
    winners = digest.get("winners") if isinstance(digest.get("winners"), list) else []
    risks = digest.get("risks") if isinstance(digest.get("risks"), list) else []
    by_status = digest.get("by_status") if isinstance(digest.get("by_status"), dict) else {}
    lines = [
        "[Paper 리허설 종합 요약]",
        f"생성: {digest.get('generated_at', '-')}",
        "실전 주문: BLOCKED",
        "",
        f"관찰 리허설: {digest.get('count', 0)}건",
        (
            f"검증 준비도: {((digest.get('readiness') or {}).get('verified_count', 0))}/20건 · "
            f"거래일 {((digest.get('readiness') or {}).get('unique_session_day_count', 0))}/5일 · "
            f"종목 {((digest.get('readiness') or {}).get('unique_symbol_count', 0))}/3개"
        ),
        f"총 평가손익: {_number(digest.get('total_pnl')):,.2f}",
        f"평균 손익률: {_number(digest.get('avg_pnl_pct')):+.2f}%",
        f"판정 분포: {', '.join(f'{key} {value}건' for key, value in by_status.items()) if by_status else '-'}",
    ]
    if winners:
        lines.append("")
        lines.append("상위 관찰 후보:")
        for row in winners[:3]:
            mark = row.get("mark") if isinstance(row.get("mark"), dict) else {}
            review = row.get("review") if isinstance(row.get("review"), dict) else {}
            lines.append(f"- {row.get('symbol', '-')} { _number(mark.get('pnl_pct')):+.2f}% / {review.get('label', '-')}")
    if risks:
        lines.append("")
        lines.append("위험/약세 후보:")
        for row in risks[:3]:
            mark = row.get("mark") if isinstance(row.get("mark"), dict) else {}
            review = row.get("review") if isinstance(row.get("review"), dict) else {}
            lines.append(f"- {row.get('symbol', '-')} { _number(mark.get('pnl_pct')):+.2f}% / {review.get('label', '-')}")
    if rows:
        lines.append("")
        lines.append("다음 행동:")
        first_review = rows[0].get("review") if isinstance(rows[0], dict) and isinstance(rows[0].get("review"), dict) else {}
        lines.append(f"- 최신 후보: {rows[0].get('symbol', '-')} / {first_review.get('action', '다음 점검까지 paper 상태를 유지합니다.')}")
        if any(str((row.get("review") or {}).get("severity")) in {"warning", "danger"} for row in rows if isinstance(row.get("review"), dict)):
            lines.append("- 경고 후보는 다음 백테스트/뉴스/DART 점검에서 우선 복기합니다.")
        else:
            lines.append("- 큰 위험 신호가 없으므로 다음 자동 점검까지 관찰을 유지합니다.")
    lines.append("")
    lines.append("주의: 이 보고서는 모의운용 복기용이며 실거래 주문 지시가 아닙니다.")
    return "\n".join(lines)


def _promotion_rehearsal_snapshot_signature(digest: dict[str, object]) -> str:
    rows = digest.get("rows") if isinstance(digest.get("rows"), list) else []
    compact_rows = []
    for row in rows[:8]:
        if not isinstance(row, dict):
            continue
        mark = row.get("mark") if isinstance(row.get("mark"), dict) else {}
        review = row.get("review") if isinstance(row.get("review"), dict) else {}
        compact_rows.append(
            {
                "symbol": row.get("symbol"),
                "ticket_status": row.get("ticket_status"),
                "pnl_pct": _number(mark.get("pnl_pct")),
                "review_status": review.get("status"),
            }
        )
    payload = {
        "count": digest.get("count", 0),
        "total_pnl": digest.get("total_pnl", 0),
        "avg_pnl_pct": digest.get("avg_pnl_pct", 0),
        "by_status": digest.get("by_status", {}),
        "by_severity": digest.get("by_severity", {}),
        "rows": compact_rows,
    }
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:20]


def _promotion_rehearsal_snapshots(limit: int = 50) -> list[dict[str, object]]:
    return list(reversed(_read_jsonl(STRATEGY_PROMOTION_REHEARSAL_SNAPSHOT_FILE, limit=limit)))


def _record_promotion_rehearsal_snapshot(digest: dict[str, object], source: str = "autopilot", force: bool = False) -> dict[str, object]:
    count = int(digest.get("count", 0) or 0)
    signature = _promotion_rehearsal_snapshot_signature(digest)
    latest = _promotion_rehearsal_snapshots(limit=1)
    if latest and latest[0].get("signature") == signature and not force:
        return {"recorded": False, "reason": "unchanged", "record": latest[0]}
    by_severity = digest.get("by_severity") if isinstance(digest.get("by_severity"), dict) else {}
    warning_count = int(by_severity.get("warning", 0) or 0) + int(by_severity.get("danger", 0) or 0)
    rows = digest.get("rows") if isinstance(digest.get("rows"), list) else []
    compact_rows = []
    for row in rows[:8]:
        if not isinstance(row, dict):
            continue
        mark = row.get("mark") if isinstance(row.get("mark"), dict) else {}
        review = row.get("review") if isinstance(row.get("review"), dict) else {}
        candidate = row.get("candidate") if isinstance(row.get("candidate"), dict) else {}
        compact_rows.append(
            {
                "symbol": row.get("symbol"),
                "ticket_id": row.get("ticket_id"),
                "candidate_id": row.get("candidate_id"),
                "fast": candidate.get("fast"),
                "slow": candidate.get("slow"),
                "entry_price": mark.get("entry_price"),
                "current_price": mark.get("current_price"),
                "pnl": mark.get("pnl"),
                "pnl_pct": mark.get("pnl_pct"),
                "review_status": review.get("status"),
                "review_label": review.get("label"),
                "review_action": review.get("action"),
            }
        )
    state = "warning" if warning_count else "observing" if count else "empty"
    record = {
        "id": f"PRS-{int(time.time() * 1000)}",
        "created_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "source": source,
        "signature": signature,
        "state": state,
        "count": count,
        "total_pnl": digest.get("total_pnl", 0),
        "avg_pnl_pct": digest.get("avg_pnl_pct", 0),
        "warning_count": warning_count,
        "by_status": digest.get("by_status", {}),
        "by_severity": digest.get("by_severity", {}),
        "rows": compact_rows,
        "real_execution": "BLOCKED",
        "safety": "Paper 리허설 변화 기록입니다. 실거래 주문 지시가 아닙니다.",
    }
    _append_jsonl(STRATEGY_PROMOTION_REHEARSAL_SNAPSHOT_FILE, record)
    return {"recorded": True, "reason": "recorded", "record": record}


def _promotion_rehearsal_snapshot_trend(limit: int = 20) -> dict[str, object]:
    snapshots = _promotion_rehearsal_snapshots(limit=limit)
    latest = snapshots[0] if snapshots else None
    previous = snapshots[1] if len(snapshots) > 1 else None
    if not latest:
        return {
            "state": "empty",
            "label": "스냅샷 대기",
            "message": "아직 비교할 Paper 리허설 스냅샷이 없습니다.",
            "delta": {},
            "changes": [],
            "snapshot_count": 0,
        }
    latest_avg = _number(latest.get("avg_pnl_pct"))
    latest_total = _number(latest.get("total_pnl"))
    latest_warning = int(latest.get("warning_count", 0) or 0)
    if not previous:
        return {
            "state": "baseline",
            "label": "기준 스냅샷",
            "message": f"첫 기준 스냅샷입니다. 평균 손익률 {latest_avg:+.2f}%, 경고 {latest_warning}건입니다.",
            "latest": latest,
            "previous": None,
            "delta": {"avg_pnl_pct": 0, "total_pnl": 0, "warning_count": 0, "count": int(latest.get("count", 0) or 0)},
            "changes": [],
            "snapshot_count": len(snapshots),
        }
    avg_delta = latest_avg - _number(previous.get("avg_pnl_pct"))
    total_delta = latest_total - _number(previous.get("total_pnl"))
    warning_delta = latest_warning - int(previous.get("warning_count", 0) or 0)
    count_delta = int(latest.get("count", 0) or 0) - int(previous.get("count", 0) or 0)
    latest_rows = {str(row.get("symbol", "")): row for row in latest.get("rows", []) if isinstance(row, dict)}
    previous_rows = {str(row.get("symbol", "")): row for row in previous.get("rows", []) if isinstance(row, dict)}
    changes = []
    for symbol in sorted(set(latest_rows) | set(previous_rows)):
        now_row = latest_rows.get(symbol, {})
        prev_row = previous_rows.get(symbol, {})
        pnl_delta = _number(now_row.get("pnl_pct")) - _number(prev_row.get("pnl_pct"))
        review_changed = str(now_row.get("review_status", "")) != str(prev_row.get("review_status", ""))
        if abs(pnl_delta) >= 0.1 or review_changed or symbol not in previous_rows or symbol not in latest_rows:
            changes.append(
                {
                    "symbol": symbol,
                    "pnl_pct": now_row.get("pnl_pct"),
                    "previous_pnl_pct": prev_row.get("pnl_pct"),
                    "pnl_delta_pct": round(pnl_delta, 2),
                    "review_status": now_row.get("review_status"),
                    "previous_review_status": prev_row.get("review_status"),
                    "review_changed": review_changed,
                    "state": "new" if symbol not in previous_rows else "removed" if symbol not in latest_rows else "changed",
                }
            )
    if warning_delta > 0 or avg_delta <= -2:
        state = "worse"
        label = "악화 감시"
        message = f"평균 손익률 {avg_delta:+.2f}%p, 경고 {warning_delta:+d}건 변화입니다. 위험 후보 우선 복기가 필요합니다."
    elif avg_delta >= 2 and warning_delta <= 0:
        state = "better"
        label = "개선 관찰"
        message = f"평균 손익률 {avg_delta:+.2f}%p 개선, 경고 {warning_delta:+d}건 변화입니다. 성과 재현성을 점검합니다."
    else:
        state = "stable"
        label = "안정 관찰"
        message = f"평균 손익률 {avg_delta:+.2f}%p, 경고 {warning_delta:+d}건 변화로 큰 흔들림은 없습니다."
    return {
        "state": state,
        "label": label,
        "message": message,
        "latest": latest,
        "previous": previous,
        "delta": {
            "avg_pnl_pct": round(avg_delta, 2),
            "total_pnl": round(total_delta, 2),
            "warning_count": warning_delta,
            "count": count_delta,
        },
        "changes": changes[:10],
        "snapshot_count": len(snapshots),
        "safety": "스냅샷 변화 분석은 paper 복기용입니다. 실거래 주문 지시가 아닙니다.",
    }


def _promotion_rehearsal_trend_report_text(trend: dict[str, object]) -> str:
    delta = trend.get("delta") if isinstance(trend.get("delta"), dict) else {}
    latest = trend.get("latest") if isinstance(trend.get("latest"), dict) else {}
    previous = trend.get("previous") if isinstance(trend.get("previous"), dict) else {}
    changes = trend.get("changes") if isinstance(trend.get("changes"), list) else []
    lines = [
        "[Paper 리허설 변화 보고]",
        f"생성: {datetime.now(ZoneInfo('Asia/Seoul')).isoformat(timespec='seconds')}",
        "실전 주문: BLOCKED",
        "",
        f"상태: {trend.get('label', '-')}",
        f"요약: {trend.get('message', '-')}",
        f"스냅샷: 최신 {latest.get('id', '-')} / 이전 {previous.get('id', '-') if previous else '-'}",
        f"평균 손익률 변화: {_number(delta.get('avg_pnl_pct')):+.2f}%p",
        f"총 평가손익 변화: {_number(delta.get('total_pnl')):+,.2f}",
        f"경고 수 변화: {int(delta.get('warning_count', 0) or 0):+d}건",
        f"리허설 수 변화: {int(delta.get('count', 0) or 0):+d}건",
    ]
    if changes:
        lines.append("")
        lines.append("종목별 변화:")
        for item in changes[:6]:
            if not isinstance(item, dict):
                continue
            lines.append(
                f"- {item.get('symbol', '-')} { _number(item.get('previous_pnl_pct')):+.2f}% -> { _number(item.get('pnl_pct')):+.2f}% "
                f"({ _number(item.get('pnl_delta_pct')):+.2f}%p), 판정 {item.get('previous_review_status', '-')} -> {item.get('review_status', '-')}"
            )
    lines.append("")
    lines.append("주의: 이 보고서는 모의운용 변화 복기용이며 실거래 주문 지시가 아닙니다.")
    return "\n".join(lines)


def _md_cell(value: object) -> str:
    text = str(value if value is not None and value != "" else "-")
    return text.replace("|", "\\|").replace("\r", " ").replace("\n", " ").strip() or "-"


def _promotion_rehearsal_memory_note(
    digest: dict[str, object],
    trend: dict[str, object],
    snapshots: list[dict[str, object]],
    source: str = "ui-rehearsal-memory",
) -> dict[str, object]:
    created_at = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
    note_id = f"PRM-{int(time.time() * 1000)}"
    safe_stamp = created_at.replace(":", "").replace("-", "")[:15]
    folder = OBSIDIAN_VAULT / "PaperRehearsals"
    folder.mkdir(parents=True, exist_ok=True)

    latest = trend.get("latest") if isinstance(trend.get("latest"), dict) else (snapshots[0] if snapshots else {})
    previous = trend.get("previous") if isinstance(trend.get("previous"), dict) else (snapshots[1] if len(snapshots) > 1 else {})
    delta = trend.get("delta") if isinstance(trend.get("delta"), dict) else {}
    changes = trend.get("changes") if isinstance(trend.get("changes"), list) else []
    rows = latest.get("rows") if isinstance(latest.get("rows"), list) else []
    by_status = latest.get("by_status") if isinstance(latest.get("by_status"), dict) else {}
    by_severity = latest.get("by_severity") if isinstance(latest.get("by_severity"), dict) else {}

    state = str(trend.get("state", "baseline") or "baseline")
    label = str(trend.get("label", "기준 스냅샷") or "기준 스냅샷")
    message = str(trend.get("message", "Paper 리허설 장기기억을 저장했습니다.") or "-")
    next_action = "다음 자동 점검까지 paper 상태를 관찰합니다."
    if state == "worse":
        next_action = "경고 후보를 우선 복기하고, 동일 전략의 추가 paper 진입을 보류합니다."
    elif state == "better":
        next_action = "개선 후보의 조건을 검증하고, 과최적화 여부를 다음 백테스트에서 확인합니다."

    lines = [
        "---",
        "type: paper-rehearsal-memory",
        f"id: {note_id}",
        f"created: {created_at}",
        f"source: {source}",
        f"state: {state}",
        f"latest_snapshot: {latest.get('id', '-') if latest else '-'}",
        "real_execution: BLOCKED",
        "---",
        "",
        f"# Paper 리허설 장기기억 {created_at[:10]}",
        "",
        "## 핵심 결론",
        f"- 상태: {label}",
        f"- 요약: {message}",
        f"- 다음 행동: {next_action}",
        "- 안전: 이 기록은 paper 리허설 복기용이며 실거래 주문 지시가 아닙니다.",
        "",
        "## 누적 지표",
        "| 항목 | 값 |",
        "| --- | ---: |",
        f"| 리허설 수 | {int(latest.get('count', digest.get('count', 0)) or 0)} |",
        f"| 총 평가손익 | {_number(latest.get('total_pnl', digest.get('total_pnl', 0))):,.2f} |",
        f"| 평균 손익률 | {_number(latest.get('avg_pnl_pct', digest.get('avg_pnl_pct', 0))):+.2f}% |",
        f"| 경고 수 | {int(latest.get('warning_count', 0) or 0)} |",
        f"| 평균 손익률 변화 | {_number(delta.get('avg_pnl_pct')):+.2f}%p |",
        f"| 경고 변화 | {int(delta.get('warning_count', 0) or 0):+d} |",
        "",
        "## 판정 분포",
        "| 구분 | 건수 |",
        "| --- | ---: |",
    ]
    if by_status:
        for key, value in by_status.items():
            lines.append(f"| {_md_cell(key)} | {value} |")
    else:
        lines.append("| - | 0 |")
    lines += ["", "## 위험도 분포", "| 구분 | 건수 |", "| --- | ---: |"]
    if by_severity:
        for key, value in by_severity.items():
            lines.append(f"| {_md_cell(key)} | {value} |")
    else:
        lines.append("| - | 0 |")

    lines += ["", "## 최근 리허설 후보", "| 종목 | 판정 | 진입가 | 현재가 | 손익률 | 다음 행동 |", "| --- | --- | ---: | ---: | ---: | --- |"]
    if rows:
        for row in rows[:12]:
            if not isinstance(row, dict):
                continue
            symbol = _md_cell(row.get("symbol"))
            lines.append(
                f"| [[{symbol}]] | {_md_cell(row.get('review_label') or row.get('review_status'))} | "
                f"{_number(row.get('entry_price')):,.2f} | {_number(row.get('current_price')):,.2f} | "
                f"{_number(row.get('pnl_pct')):+.2f}% | {_md_cell(row.get('review_action'))} |"
            )
    else:
        lines.append("| - | - | 0.00 | 0.00 | +0.00% | 기록 없음 |")

    lines += ["", "## 변화 감지"]
    if changes:
        for item in changes[:10]:
            if not isinstance(item, dict):
                continue
            lines.append(
                f"- [[{_md_cell(item.get('symbol'))}]]: "
                f"{_number(item.get('previous_pnl_pct')):+.2f}% -> {_number(item.get('pnl_pct')):+.2f}% "
                f"({_number(item.get('pnl_delta_pct')):+.2f}%p), "
                f"판정 {_md_cell(item.get('previous_review_status'))} -> {_md_cell(item.get('review_status'))}"
            )
    else:
        lines.append("- 아직 의미 있는 종목별 변화가 감지되지 않았습니다.")

    lines += ["", "## 최근 스냅샷"]
    for row in snapshots[:8]:
        lines.append(
            f"- {row.get('id', '-')}: {row.get('created_at', '-')} / "
            f"평균 {_number(row.get('avg_pnl_pct')):+.2f}% / 총손익 {_number(row.get('total_pnl')):,.2f} / "
            f"경고 {int(row.get('warning_count', 0) or 0)}건 / source={row.get('source', '-')}"
        )
    if previous:
        lines += ["", "## 이전 기준", f"- 이전 스냅샷: {previous.get('id', '-')} / {previous.get('created_at', '-')}"]

    note_text = "\n".join(lines) + "\n"
    note_path = folder / f"rehearsal-memory-{safe_stamp}.md"
    latest_path = folder / "latest.md"
    note_path.write_text(note_text, encoding="utf-8")
    latest_path.write_text(note_text, encoding="utf-8")

    memory_record = {
        "id": note_id,
        "created_at": created_at,
        "source": source,
        "note_path": str(note_path),
        "latest_path": str(latest_path),
        "state": state,
        "label": label,
        "message": message,
        "latest_snapshot_id": latest.get("id") if latest else None,
        "previous_snapshot_id": previous.get("id") if previous else None,
        "count": int(latest.get("count", digest.get("count", 0)) or 0),
        "avg_pnl_pct": round(_number(latest.get("avg_pnl_pct", digest.get("avg_pnl_pct", 0))), 2),
        "total_pnl": round(_number(latest.get("total_pnl", digest.get("total_pnl", 0))), 2),
        "warning_count": int(latest.get("warning_count", 0) or 0),
        "symbols": [str(row.get("symbol", "")) for row in rows[:12] if isinstance(row, dict) and row.get("symbol")],
        "real_execution": "BLOCKED",
    }
    memory_data = MEMORY.load()
    records = list(memory_data.get("paper_rehearsal_memories", []))
    records.append(memory_record)
    memory_data["paper_rehearsal_memories"] = records[-240:]
    lessons = list(memory_data.get("lessons", []))
    lessons.append(f"Paper 리허설 {label}: {message}")
    memory_data["lessons"] = [lesson for lesson in lessons if lesson][-240:]
    MEMORY.save(memory_data)
    return {
        "ok": True,
        "id": note_id,
        "created_at": created_at,
        "path": str(note_path),
        "latest_path": str(latest_path),
        "vault": str(OBSIDIAN_VAULT),
        "folder": str(folder),
        "memory_record": memory_record,
        "safety": "옵시디언 기억 저장은 paper 복기 기록입니다. 실거래 주문 지시가 아닙니다.",
    }


def _promotion_rehearsal_index() -> dict[str, list[dict[str, object]]]:
    rows = _read_jsonl(STRATEGY_PROMOTION_REHEARSAL_FILE)
    indexed: dict[str, list[dict[str, object]]] = {}
    for row in rows:
        candidate_id = str(row.get("candidate_id", "")).strip()
        if not candidate_id:
            continue
        indexed.setdefault(candidate_id, []).append(row)
    return indexed


def _promotion_candidates(limit: int = 20) -> list[dict[str, object]]:
    rows = _read_jsonl(STRATEGY_PROMOTION_CANDIDATE_FILE, limit=limit)
    rehearsal_index = _promotion_rehearsal_index()
    candidate_lookup = _promotion_candidate_index()
    quote_cache: dict[str, dict[str, object]] = {}
    hydrated: list[dict[str, object]] = []
    for row in rows:
        candidate = dict(row)
        evidence_status = _promotion_candidate_validation_evidence_status(candidate)
        candidate["validation_evidence_status"] = evidence_status
        if not evidence_status.get("verified"):
            promotion = candidate.get("promotion") if isinstance(candidate.get("promotion"), dict) else {}
            promotion_existing_blockers = (
                [str(item) for item in promotion.get("blockers", []) if str(item)]
                if isinstance(promotion.get("blockers"), list)
                else []
            )
            candidate["promotion"] = {
                **promotion,
                "original_stage": promotion.get("stage"),
                "stage": "QUARANTINED",
                "recommended_mode": "research_only",
                "blockers": list(
                    dict.fromkeys(
                        [
                            *promotion_existing_blockers,
                            *[str(item) for item in evidence_status.get("blockers", []) if str(item)],
                        ]
                    )
                ),
            }
        candidate_id = str(candidate.get("id", "")).strip()
        rehearsals = rehearsal_index.get(candidate_id, [])
        if rehearsals:
            latest = _hydrate_promotion_rehearsal(rehearsals[-1], candidate_lookup, quote_cache)
            latest["count"] = len(rehearsals)
            candidate["paper_rehearsal"] = latest
        hydrated.append(candidate)
    return list(reversed(hydrated))


def _promotion_candidate_by_id(candidate_id: str) -> dict[str, object] | None:
    rows = _read_jsonl(STRATEGY_PROMOTION_CANDIDATE_FILE)
    if not rows:
        return None
    if not candidate_id:
        return rows[-1]
    return next((row for row in reversed(rows) if str(row.get("id", "")) == candidate_id), None)


def _attach_optimization_risk_gates(result: dict[str, object]) -> dict[str, object]:
    for row in result.get("top_results", []):
        if isinstance(row, dict):
            attach_backtest_risk_gate(row)
    if isinstance(result.get("best"), dict):
        best = attach_backtest_risk_gate(result["best"])  # type: ignore[arg-type]
        decision = result.get("decision")
        gate = best.get("risk_gate") if isinstance(best, dict) else None
        if isinstance(decision, dict) and isinstance(gate, dict):
            decision["risk_gate_status"] = gate.get("status")
            decision["risk_gate_message"] = gate.get("message")
            if gate.get("status") == "BLOCKED" and decision.get("status") == "PASS":
                decision["status"] = "REVIEW"
                decision["label"] = "보호장치 재검토"
                decision["summary"] = "전략 점수는 좋지만 보호장치 기준에서 막힌 항목이 있어 모의 운용 전 추가 검토가 필요합니다."
    return result


def _promotion_candidate_record(result: dict[str, object], scenario: str, fast_values: list[int], slow_values: list[int], source: str) -> dict[str, object]:
    best = result.get("best") if isinstance(result.get("best"), dict) else {}
    promotion = result.get("promotion_review") if isinstance(result.get("promotion_review"), dict) else {}
    decision = result.get("decision") if isinstance(result.get("decision"), dict) else {}
    relative = result.get("relative_performance") if isinstance(result.get("relative_performance"), dict) else {}
    walk_forward = result.get("walk_forward") if isinstance(result.get("walk_forward"), dict) else {}
    stress = result.get("stress_test") if isinstance(result.get("stress_test"), dict) else {}
    parameter = result.get("parameter_robustness") if isinstance(result.get("parameter_robustness"), dict) else {}
    candidate_id = f"SPC-{int(time.time() * 1000)}"
    upstream_stage = promotion.get("stage")
    upstream_blockers = promotion.get("blockers", []) if isinstance(promotion.get("blockers"), list) else []
    record = {
        "id": candidate_id,
        "created_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "source": source,
        "symbol": str(result.get("symbol", "")).upper(),
        "start_date": result.get("start_date"),
        "end_date": result.get("end_date"),
        "scenario": scenario,
        "fast_values": fast_values,
        "slow_values": slow_values,
        "fast": best.get("fast"),
        "slow": best.get("slow"),
        "score": best.get("score"),
        "test_return_pct": best.get("test_return_pct"),
        "max_drawdown_pct": best.get("test_drawdown_pct"),
        "profit_factor": best.get("profit_factor"),
        "trade_count": best.get("trade_count"),
        "decision": {
            "status": decision.get("status"),
            "label": decision.get("label"),
            "risk_gate_status": decision.get("risk_gate_status"),
        },
        "promotion": {
            "stage": "BLOCKED",
            "upstream_stage": upstream_stage,
            "label": "SYNTHETIC_RESEARCH_ONLY",
            "readiness_score": promotion.get("readiness_score"),
            "recommended_mode": "research_only",
            "blockers": list(
                dict.fromkeys(
                    [
                        *[str(item) for item in upstream_blockers if str(item)],
                        "synthetic_backtest_not_eligible_for_paper",
                        "research_forge_provider_evidence_required",
                    ]
                )
            ),
            "review_items": promotion.get("review_items", []),
            "automatic_promotion": False,
        },
        "summaries": {
            "walk_forward": (walk_forward.get("summary") if isinstance(walk_forward, dict) else {}),
            "stress": (stress.get("summary") if isinstance(stress, dict) else {}),
            "parameter": (parameter.get("summary") if isinstance(parameter, dict) else {}),
            "relative": (relative.get("summary") if isinstance(relative, dict) else {}),
        },
        "guardrail": "실거래 주문은 OFF입니다. 이 큐는 모의투자 후보 추적용입니다.",
    }
    candidate_created_date = datetime.fromisoformat(str(record["created_at"])).date()
    first_paper_session_date = _ai_staff_learning_roll_to_krx_session(
        candidate_created_date + timedelta(days=1),
        forward=True,
    ).isoformat()
    record["first_paper_session_date"] = first_paper_session_date
    evidence = {
        "schema": "codexstock_promotion_candidate_validation_v2",
        "candidate_id": candidate_id,
        "symbol": record["symbol"],
        "created_at": record["created_at"],
        "data_end_date": record.get("end_date"),
        "first_paper_session_date": first_paper_session_date,
        "source_engine": "codexstock_native",
        "experiment_id": "",
        "experiment_status": "SYNTHETIC_RESEARCH",
        "adapter": "codexstock-native-synthetic",
        "data_mode": "synthetic",
        "dataset_id": "",
        "dataset_hash": "",
        "row_count": 0,
        "data_quality": {
            "strict_temporal_order": False,
            "duplicate_dates": 0,
            "invalid_ohlc_rows": 0,
        },
        "point_in_time_universe_passed": False,
        "adjusted_prices": False,
        "signal_timing": "synthetic_close",
        "fill_timing": "synthetic_close",
        "execution_model": {
            "execution_mode": "OPTIMISTIC",
            "costs_declared": False,
            "liquidity_model_declared": False,
            "order_delay_bars": 0,
        },
        "validation": {
            "passed": False,
            "strict_walk_forward_passed": False,
            "no_walk_forward_leakage": False,
            "label_horizon_purge_covered": False,
            "parameter_robustness_passed": False,
        },
        "lifecycle": {
            "eligible_for_manual_paper_nomination": False,
            "automatic_promotion": False,
            "report_bundle_verified": False,
        },
        "paper_only": True,
        "live_order_allowed": False,
    }
    evidence["evidence_hash"] = _promotion_candidate_validation_evidence_hash(evidence)
    record["validation_evidence"] = evidence
    record["validation_evidence_status"] = _promotion_candidate_validation_evidence_status(record)
    return record


def _research_forge_promotion_candidate_record(
    experiment_id: str,
    *,
    source: str = "research-forge-promotion-import",
) -> dict[str, object]:
    """Convert a manually nominated Research Forge experiment into a Paper-only candidate."""
    experiment_id = str(experiment_id or "").strip()
    if not re.fullmatch(r"exp_[A-Za-z0-9_]+", experiment_id):
        raise ValueError("A valid Research Forge experiment id is required")
    experiment = RESEARCH_FORGE.registry.get(experiment_id)
    payload = experiment.to_dict()
    readiness = RESEARCH_FORGE.lifecycle_readiness(experiment_id)
    strategy = payload.get("strategy") if isinstance(payload.get("strategy"), dict) else {}
    rules = strategy.get("rules") if isinstance(strategy.get("rules"), dict) else {}
    snapshot = payload.get("data_snapshot") if isinstance(payload.get("data_snapshot"), dict) else {}
    result = payload.get("result") if isinstance(payload.get("result"), dict) else {}
    validation = payload.get("validation") if isinstance(payload.get("validation"), dict) else {}
    strict = validation.get("strict_walk_forward") if isinstance(validation.get("strict_walk_forward"), dict) else {}
    strict_summary = strict.get("summary") if isinstance(strict.get("summary"), dict) else {}
    robustness = validation.get("parameter_robustness") if isinstance(validation.get("parameter_robustness"), dict) else {}
    robustness_summary = robustness.get("summary") if isinstance(robustness.get("summary"), dict) else {}
    quality = result.get("data_quality") if isinstance(result.get("data_quality"), dict) else {}
    universe = validation.get("universe_evidence") if isinstance(validation.get("universe_evidence"), dict) else {}
    validation_rows = [item for item in validation.get("checks", []) if isinstance(item, dict)]
    validation_checks = {
        str(item.get("id") or ""): item.get("ok") is True
        for item in validation_rows
        if str(item.get("id") or "")
    }
    validation_details = {
        str(item.get("id") or ""): item.get("detail")
        for item in validation_rows
        if str(item.get("id") or "")
    }
    lifecycle_checks = {
        str(item.get("id") or ""): item.get("ok") is True
        for item in readiness.get("checks", [])
        if isinstance(item, dict) and str(item.get("id") or "")
    }
    experiment_status = str(payload.get("status") or "")
    lifecycle_ready = readiness.get("eligible_for_manual_paper_nomination") is True
    manually_nominated = experiment_status == "PAPER_CANDIDATE"
    candidate_id = f"SPC-RF-{int(time.time() * 1000)}"
    symbol = str(result.get("symbol") or rules.get("symbol") or snapshot.get("symbol") or "").upper().strip()
    if not symbol:
        raise ValueError("Research Forge experiment has no symbol")
    lifecycle_blockers = [str(item) for item in readiness.get("blockers", []) if str(item)]
    promotion_blockers = list(lifecycle_blockers)
    if not manually_nominated:
        promotion_blockers.append("research_forge_manual_paper_nomination_missing")
    candidate_created_at = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
    candidate_created_date = datetime.fromisoformat(candidate_created_at).date()
    first_paper_session_date = _ai_staff_learning_roll_to_krx_session(
        candidate_created_date + timedelta(days=1),
        forward=True,
    ).isoformat()
    data_end_date = str(result.get("end_date") or snapshot.get("end_date") or "")[:10]
    evidence = {
        "schema": "codexstock_promotion_candidate_validation_v2",
        "candidate_id": candidate_id,
        "symbol": symbol,
        "created_at": candidate_created_at,
        "data_end_date": data_end_date,
        "first_paper_session_date": first_paper_session_date,
        "source_engine": "research_forge",
        "experiment_id": experiment_id,
        "experiment_status": experiment_status,
        "adapter": payload.get("backtest_adapter"),
        "data_mode": result.get("data_mode") or snapshot.get("data_mode"),
        "dataset_id": result.get("dataset_id") or snapshot.get("dataset_id"),
        "dataset_hash": result.get("dataset_hash"),
        "row_count": int(_number(result.get("row_count"))),
        "data_quality": {
            "strict_temporal_order": quality.get("strict_temporal_order") is True,
            "duplicate_dates": int(_number(quality.get("duplicate_dates"))),
            "invalid_ohlc_rows": int(_number(quality.get("invalid_ohlc_rows"))),
        },
        "point_in_time_universe_passed": universe.get("passed") is True,
        "point_in_time_universe_dataset_id": universe.get("dataset_id") or snapshot.get("universe_dataset_id"),
        "adjusted_prices": snapshot.get("adjusted_prices") is True,
        "signal_timing": result.get("signal_timing"),
        "fill_timing": result.get("fill_timing"),
        "execution_model": {
            "execution_mode": readiness.get("execution_mode"),
            "costs_declared": validation_checks.get("costs_declared") is True,
            "liquidity_model_declared": validation_checks.get("liquidity_model_declared") is True,
            "order_delay_bars": int(_number(validation_details.get("order_delay_declared"))),
        },
        "validation": {
            "passed": validation.get("passed") is True,
            "strict_walk_forward_passed": strict_summary.get("passed") is True,
            "no_walk_forward_leakage": (
                strict_summary.get("temporal_leakage_detected") is not True
                and strict.get("parameter_selection_uses_oos") is False
            ),
            "label_horizon_purge_covered": lifecycle_checks.get("label_horizon_purge_covered") is True,
            "parameter_robustness_passed": robustness_summary.get("robust") is True,
        },
        "lifecycle": {
            "eligible_for_manual_paper_nomination": lifecycle_ready,
            "automatic_promotion": readiness.get("automatic_promotion") is True,
            "report_bundle_verified": lifecycle_checks.get("report_bundle_verified") is True,
            "blockers": lifecycle_blockers,
        },
        "paper_only": True,
        "live_order_allowed": False,
    }
    evidence["evidence_hash"] = _promotion_candidate_validation_evidence_hash(evidence)
    lifecycle_check_count = len(lifecycle_checks)
    readiness_score = (
        round(100.0 * sum(1 for ok in lifecycle_checks.values() if ok) / lifecycle_check_count, 2)
        if lifecycle_check_count
        else 0.0
    )
    record: dict[str, object] = {
        "id": candidate_id,
        "created_at": evidence["created_at"],
        "source": source,
        "source_engine": "research_forge",
        "research_forge_experiment_id": experiment_id,
        "symbol": symbol,
        "first_paper_session_date": first_paper_session_date,
        "start_date": result.get("start_date") or snapshot.get("start_date"),
        "end_date": result.get("end_date") or snapshot.get("end_date"),
        "scenario": "research_forge_verified_historical",
        "fast": rules.get("fast"),
        "slow": rules.get("slow"),
        "score": result.get("score"),
        "test_return_pct": result.get("total_return_pct"),
        "max_drawdown_pct": result.get("max_drawdown_pct"),
        "profit_factor": result.get("profit_factor"),
        "trade_count": result.get("trade_count"),
        "decision": {
            "status": "PASS" if lifecycle_ready and manually_nominated else "REVIEW",
            "label": "VERIFIED_HISTORICAL_PROVIDER" if lifecycle_ready and manually_nominated else "RESEARCH_ONLY",
            "risk_gate_status": "PASSED" if lifecycle_ready and manually_nominated else "BLOCKED",
        },
        "promotion": {
            "stage": "PAPER_READY" if lifecycle_ready and manually_nominated else "BLOCKED",
            "label": "RESEARCH_FORGE_PAPER_READY" if lifecycle_ready and manually_nominated else "RESEARCH_FORGE_BLOCKED",
            "readiness_score": readiness_score,
            "recommended_mode": "paper" if lifecycle_ready and manually_nominated else "research_only",
            "blockers": list(dict.fromkeys(promotion_blockers)),
            "review_items": lifecycle_blockers,
            "automatic_promotion": False,
        },
        "validation_evidence": evidence,
        "guardrail": "Research Forge evidence may create Paper tickets only; live orders remain blocked.",
        "paper_only": True,
        "live_order_allowed": False,
    }
    evidence_status = _promotion_candidate_validation_evidence_status(record)
    if not evidence_status.get("evidence_verified"):
        promotion_record = record.get("promotion") if isinstance(record.get("promotion"), dict) else {}
        promotion_record["stage"] = "BLOCKED"
        promotion_record["recommended_mode"] = "research_only"
        promotion_record["blockers"] = list(
            dict.fromkeys([*promotion_blockers, *evidence_status.get("evidence_blockers", [])])
        )
        record["promotion"] = promotion_record
        evidence_status = _promotion_candidate_validation_evidence_status(record)
    record["validation_evidence_status"] = evidence_status
    return record


def _discover_research_forge_promotion_candidates(
    *,
    source: str = "autopilot-research-forge-candidate-discovery",
    max_imports: int = 1,
    scan_limit: int = 200,
) -> dict[str, object]:
    """Auto-nominate strictly verified experiments and import Paper-only candidates."""
    import_limit = max(0, min(int(max_imports or 0), 3))
    bounded_scan_limit = max(1, min(int(scan_limit or 200), 500))
    experiments = list(RESEARCH_FORGE.registry.list())[-bounded_scan_limit:]
    status_counts: dict[str, int] = {}
    for experiment in experiments:
        status = getattr(experiment.status, "value", str(experiment.status))
        status_counts[status] = status_counts.get(status, 0) + 1
    manually_nominated = [
        experiment
        for experiment in reversed(experiments)
        if getattr(experiment.status, "value", str(experiment.status)) == "PAPER_CANDIDATE"
    ]
    auto_nominated: list[object] = []
    auto_nomination_blocked: list[dict[str, object]] = []
    for experiment in reversed(experiments):
        experiment_status = getattr(experiment.status, "value", str(experiment.status))
        if experiment_status != "VALIDATION" or len(auto_nominated) >= import_limit:
            continue
        experiment_id = str(experiment.id)
        try:
            readiness = RESEARCH_FORGE.lifecycle_readiness(experiment_id)
        except Exception as exc:
            auto_nomination_blocked.append(
                {
                    "experiment_id": experiment_id,
                    "status": "readiness_error",
                    "blockers": [str(exc)[:300]],
                }
            )
            continue
        readiness_blockers = [str(item) for item in readiness.get("blockers", []) if str(item)]
        if readiness.get("eligible_for_manual_paper_nomination") is not True:
            auto_nomination_blocked.append(
                {
                    "experiment_id": experiment_id,
                    "status": "strict_evidence_not_ready",
                    "blockers": readiness_blockers,
                }
            )
            continue
        try:
            RESEARCH_FORGE.auto_nominate_verified_paper(
                experiment_id,
                scheduler_id="codexstock-verified-paper-scheduler",
                rationale=(
                    "All Research Forge lifecycle evidence gates passed. "
                    "Nominate for forward Paper rehearsal only; live promotion remains blocked."
                ),
            )
            auto_nominated.append(RESEARCH_FORGE.registry.get(experiment_id))
        except Exception as exc:
            auto_nomination_blocked.append(
                {
                    "experiment_id": experiment_id,
                    "status": "auto_nomination_error",
                    "blockers": [str(exc)[:300]],
                }
            )
    nominated = [*auto_nominated, *manually_nominated]
    imported: list[dict[str, object]] = []
    blocked: list[dict[str, object]] = []
    already_imported: list[str] = []
    with PROMOTION_CANDIDATE_LOCK:
        existing_rows = _read_jsonl(STRATEGY_PROMOTION_CANDIDATE_FILE, limit=5000)
        existing_experiment_ids = {
            str(row.get("research_forge_experiment_id") or "")
            for row in existing_rows
            if isinstance(row, dict) and str(row.get("research_forge_experiment_id") or "")
        }
        for experiment in nominated:
            experiment_id = str(experiment.id)
            if experiment_id in existing_experiment_ids:
                already_imported.append(experiment_id)
                continue
            if len(imported) >= import_limit:
                break
            try:
                candidate = _research_forge_promotion_candidate_record(
                    experiment_id,
                    source=source,
                )
            except Exception as exc:
                blocked.append(
                    {
                        "experiment_id": experiment_id,
                        "status": "conversion_error",
                        "blockers": [str(exc)[:300]],
                    }
                )
                continue
            evidence_status = _promotion_candidate_validation_evidence_status(candidate)
            candidate["validation_evidence_status"] = evidence_status
            if not evidence_status.get("verified"):
                blocked.append(
                    {
                        "experiment_id": experiment_id,
                        "status": "evidence_blocked",
                        "blockers": [
                            str(item)
                            for item in evidence_status.get("blockers", [])
                            if str(item)
                        ],
                    }
                )
                continue
            _append_jsonl(STRATEGY_PROMOTION_CANDIDATE_FILE, candidate)
            existing_experiment_ids.add(experiment_id)
            imported.append(
                {
                    "candidate_id": candidate.get("id"),
                    "experiment_id": experiment_id,
                    "symbol": candidate.get("symbol"),
                    "dataset_hash": evidence_status.get("dataset_hash"),
                    "stage": (candidate.get("promotion") or {}).get("stage")
                    if isinstance(candidate.get("promotion"), dict)
                    else None,
                }
            )
    status = "imported" if imported else "already_imported" if already_imported and nominated else "no_eligible_candidate"
    if blocked and not imported:
        status = "eligible_candidate_blocked"
    payload = {
        "ok": not blocked,
        "schema": "codexstock_research_forge_candidate_discovery_v1",
        "status": status,
        "scanned_experiment_count": len(experiments),
        "experiment_status_counts": status_counts,
        "manually_nominated_experiment_count": len(manually_nominated),
        "automatically_nominated_experiment_count": len(auto_nominated),
        "automatic_nomination_blocked_count": len(auto_nomination_blocked),
        "automatic_nomination_blocked": auto_nomination_blocked,
        "import_limit": import_limit,
        "imported_count": len(imported),
        "already_imported_count": len(already_imported),
        "blocked_count": len(blocked),
        "imported": imported,
        "already_imported_experiment_ids": already_imported,
        "blocked": blocked,
        "automatic_research_execution": False,
        "automatic_verified_paper_nomination": True,
        "automatic_promotion": False,
        "paper_only": True,
        "live_order_allowed": False,
    }
    if imported:
        JOURNAL.add(
            "RESEARCH_FORGE_PROMOTION_CANDIDATE_DISCOVERY",
            f"Imported {len(imported)} verified Research Forge Paper candidate(s)",
            payload,
        )
    return payload


def _research_forge_candidate_discovery_audit(
    *,
    scan_limit: int = 200,
) -> dict[str, object]:
    """Read-only proof that discovery is bounded and only verified candidates become runnable."""
    bounded_scan_limit = max(1, min(int(scan_limit or 200), 500))
    experiments = list(RESEARCH_FORGE.registry.list())[-bounded_scan_limit:]
    experiment_status_counts: dict[str, int] = {}
    nominated_ids: set[str] = set()
    for experiment in experiments:
        status = getattr(experiment.status, "value", str(experiment.status))
        experiment_status_counts[status] = experiment_status_counts.get(status, 0) + 1
        if status == "PAPER_CANDIDATE":
            nominated_ids.add(str(experiment.id))
    candidate_rows = _read_jsonl(STRATEGY_PROMOTION_CANDIDATE_FILE, limit=5000)
    candidate_audit = _promotion_candidate_evidence_audit(candidate_rows)
    verified_rows = [
        row for row in candidate_audit.get("verified_rows", []) if isinstance(row, dict)
    ]
    verified_experiment_ids = {
        str(row.get("research_forge_experiment_id") or "")
        for row in verified_rows
        if str(row.get("research_forge_experiment_id") or "")
    }
    imported_experiment_ids = {
        str(row.get("research_forge_experiment_id") or "")
        for row in candidate_rows
        if isinstance(row, dict) and str(row.get("research_forge_experiment_id") or "")
    }
    pending_nominated_ids = sorted(nominated_ids - imported_experiment_ids)
    scheduler_eligible_rows = [
        row
        for row in verified_rows
        if isinstance(row.get("promotion"), dict)
        and (row.get("promotion") or {}).get("stage") == "PAPER_READY"
        and not (row.get("promotion") or {}).get("blockers")
    ]
    contract_ready = bool(
        candidate_audit.get("schema") == "codexstock_promotion_candidate_evidence_audit_v1"
        and candidate_audit.get("paper_only") is True
        and candidate_audit.get("live_order_allowed") is False
    )
    return {
        "ok": contract_ready,
        "schema": "codexstock_research_forge_candidate_discovery_audit_v1",
        "contract_ready": contract_ready,
        "bounded_scan_limit": bounded_scan_limit,
        "max_auto_imports_per_tick": 3,
        "scanned_experiment_count": len(experiments),
        "experiment_status_counts": experiment_status_counts,
        "manually_nominated_experiment_count": len(nominated_ids),
        "imported_experiment_count": len(imported_experiment_ids),
        "verified_imported_experiment_count": len(verified_experiment_ids),
        "pending_nominated_experiment_count": len(pending_nominated_ids),
        "pending_nominated_experiment_ids": pending_nominated_ids,
        "scheduler_eligible_candidate_count": len(scheduler_eligible_rows),
        "quarantined_candidate_count": int(_number(candidate_audit.get("quarantined_count"))),
        "candidate_evidence_schema": candidate_audit.get("schema"),
        "requires_manual_research_forge_nomination": False,
        "supports_automatic_verified_paper_nomination": True,
        "automatic_nomination_requires_all_lifecycle_gates": True,
        "requires_verified_historical_provider_evidence": True,
        "requires_next_krx_session_cooling": True,
        "scheduler_hook": "run_due_promotion_paper_rehearsal",
        "automatic_research_execution": False,
        "automatic_promotion": False,
        "paper_only": True,
        "live_order_allowed": False,
    }


def _compact_money(value: object) -> str:
    number = float(value or 0)
    if abs(number) >= 1_0000_0000_0000:
        return f"{number / 1_0000_0000_0000:.1f}조"
    if abs(number) >= 1_0000_0000:
        return f"{number / 1_0000_0000:.1f}억"
    return f"{number:,.0f}"


def _lookup_symbols(symbols: list[str]) -> list[dict[str, object]]:
    global SYMBOL_LOOKUP_CACHE_MTIME
    try:
        cache_mtime = UNIVERSE_CACHE.stat().st_mtime
    except OSError:
        cache_mtime = 0.0
    with SYMBOL_LOOKUP_CACHE_LOCK:
        if not SYMBOL_LOOKUP_CACHE or SYMBOL_LOOKUP_CACHE_MTIME != cache_mtime:
            cached_rows: list[object] = []
            if cache_mtime > 0:
                try:
                    cached_payload = json.loads(UNIVERSE_CACHE.read_text(encoding="utf-8"))
                    if isinstance(cached_payload, dict) and isinstance(cached_payload.get("rows"), list):
                        cached_rows = cached_payload["rows"]
                except Exception:
                    cached_rows = []
            lookup: dict[str, dict[str, object]] = {}
            for source_row in [*BUILTIN_UNIVERSE, *cached_rows]:
                if not isinstance(source_row, dict):
                    continue
                symbol = str(source_row.get("symbol") or "").upper().strip()
                if symbol:
                    lookup[symbol] = dict(source_row, symbol=symbol)
            SYMBOL_LOOKUP_CACHE.clear()
            SYMBOL_LOOKUP_CACHE.update(lookup)
            SYMBOL_LOOKUP_CACHE_MTIME = cache_mtime
        lookup = dict(SYMBOL_LOOKUP_CACHE)
    rows = []
    for symbol in symbols:
        normalized = str(symbol or "").upper().strip()
        if not normalized:
            continue
        row = dict(lookup.get(normalized, {"symbol": normalized, "name": normalized, "market": "KR" if normalized.isdigit() else "US"}))
        row["symbol"] = normalized
        rows.append(row)
    return rows


def _normalize_symbol_for_watchlist(symbol: object) -> str:
    value = str(symbol or "").strip().upper()
    if re.fullmatch(r"\d{1,6}", value):
        return value.zfill(6)
    return value[:16]


def _useful_symbol_name(value: object, symbol: object = "") -> str:
    normalized = _normalize_symbol_for_watchlist(symbol)
    text = str(value or "").strip()
    if not text:
        return ""
    if normalized and text.upper() == normalized.upper():
        return ""
    if re.fullmatch(r"\d{1,6}", text.strip()):
        return ""
    return text


def _quick_cached_symbol_name(symbol: object) -> str:
    """빠른 진단 카드 전용: 네트워크 갱신 없이 로컬 종목 캐시에서만 이름을 찾는다."""
    global QUICK_SYMBOL_NAME_CACHE_MTIME
    normalized = _normalize_symbol_for_watchlist(symbol)
    if not normalized:
        return ""
    try:
        mtime = UNIVERSE_CACHE.stat().st_mtime
    except OSError:
        return ""
    if not QUICK_SYMBOL_NAME_CACHE or QUICK_SYMBOL_NAME_CACHE_MTIME != mtime:
        try:
            cached = json.loads(UNIVERSE_CACHE.read_text(encoding="utf-8"))
            rows = cached.get("rows", []) if isinstance(cached, dict) else []
            names: dict[str, str] = {}
            for row in rows:
                if not isinstance(row, dict):
                    continue
                row_symbol = _normalize_symbol_for_watchlist(row.get("symbol"))
                row_name = _useful_symbol_name(row.get("name"), row_symbol)
                if row_symbol and row_name and row_symbol not in names:
                    names[row_symbol] = row_name
            QUICK_SYMBOL_NAME_CACHE.clear()
            QUICK_SYMBOL_NAME_CACHE.update(names)
            QUICK_SYMBOL_NAME_CACHE_MTIME = mtime
        except Exception:
            return ""
    return _useful_symbol_name(QUICK_SYMBOL_NAME_CACHE.get(normalized), normalized)


def resolve_symbol_display_name(symbol: object, *candidates: object) -> str:
    normalized = _normalize_symbol_for_watchlist(symbol)
    for candidate in candidates:
        name = _useful_symbol_name(candidate, normalized)
        if name:
            return name
    quick_name = _quick_cached_symbol_name(normalized)
    if quick_name:
        return quick_name
    try:
        looked_up = _lookup_symbols([normalized])
        if looked_up:
            name = _useful_symbol_name(looked_up[0].get("name"), normalized)
            if name:
                return name
    except Exception:
        pass
    try:
        for row in reversed(_read_jsonl(LIVE_ORDER_SUBMIT_FILE, limit=500)):
            if str(row.get("symbol") or "").upper().strip() != normalized:
                continue
            plan = row.get("plan", {}) if isinstance(row.get("plan"), dict) else {}
            selection = plan.get("selection", {}) if isinstance(plan.get("selection"), dict) else {}
            for candidate in (
                row.get("name"),
                row.get("symbol_name"),
                plan.get("name"),
                plan.get("symbol_name"),
                selection.get("name"),
            ):
                name = _useful_symbol_name(candidate, normalized)
                if name:
                    return name
    except Exception:
        pass
    return normalized or str(symbol or "").strip()


def enrich_quote_display_name(payload: dict[str, object], symbol: object = "") -> dict[str, object]:
    result = dict(payload)
    normalized = _normalize_symbol_for_watchlist(symbol or result.get("symbol") or result.get("pdno") or result.get("code"))
    if normalized:
        result["symbol"] = normalized
    result["name"] = resolve_symbol_display_name(
        normalized or result.get("symbol"),
        result.get("name"),
        result.get("prdt_name"),
        result.get("hts_kor_isnm"),
        result.get("stck_shrn_iscd"),
    )
    return result


