def _symbol_news_aliases(symbol: str, name: str) -> list[str]:
    aliases = [str(symbol or "").strip(), str(name or "").strip()]
    aliases.extend(NEWS_SYMBOL_ALIASES.get(str(symbol or "").upper(), ()))
    deduped: list[str] = []
    for alias in aliases:
        text = str(alias or "").strip()
        if len(text) < 2:
            continue
        if text not in deduped:
            deduped.append(text)
    return deduped


def _mark_symbol_matched_news_items(items: list[dict[str, object]], symbol: str, name: str) -> list[dict[str, object]]:
    aliases = _symbol_news_aliases(symbol, name)
    marked: list[dict[str, object]] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        haystack = " ".join(
            str(item.get(key) or "")
            for key in ("title", "summary", "description", "source")
        ).lower()
        matched_aliases = [alias for alias in aliases if alias.lower() in haystack]
        marked.append(
            {
                **item,
                "verified": bool(matched_aliases),
                "score_allowed": bool(matched_aliases),
                "symbol_match_aliases": matched_aliases,
                "symbol_match_policy": "title_summary_source_must_contain_symbol_name_code_or_allowed_alias",
            }
        )
    return marked


def build_news_radar(symbol_rows: list[dict[str, object]]) -> list[dict[str, object]]:
    targets = list(symbol_rows[:8])
    if len(targets) > 1:
        with ThreadPoolExecutor(
            max_workers=min(4, len(targets)),
            thread_name_prefix="news-radar",
        ) as executor:
            batches = list(executor.map(lambda row: build_news_radar([row]), targets))
        return [batch[0] for batch in batches if batch]
    rows = []
    for row in targets:
        symbol = str(row.get("symbol", "")).upper()
        name = str(row.get("name") or symbol)
        market = str(row.get("market") or "")
        query = f"{name} {symbol} 주식 실적 리포트" if symbol.isdigit() else f"{symbol} {name} stock earnings analyst report"
        try:
            items = _mark_symbol_matched_news_items(fetch_news_rss(query=query, limit=5), symbol, name)
            status = score_news_items(items)
            source_status = "ready"
            message = "정상"
        except Exception as exc:
            items = []
            status = {"score": 0, "stance": "조회 대기", "positive_count": 0, "risk_count": 0}
            source_status = "error"
            message = str(exc)
        rows.append(
            {
                "symbol": symbol,
                "name": name,
                "market": market,
                "query": query,
                "score": status["score"],
                "raw_score": status.get("raw_score", 0),
                "stance": status["stance"],
                "positive_count": status["positive_count"],
                "risk_count": status["risk_count"],
                "raw_positive_count": status.get("raw_positive_count", 0),
                "raw_risk_count": status.get("raw_risk_count", 0),
                "verified_item_count": status.get("verified_item_count", 0),
                "unverified_item_count": status.get("unverified_item_count", len(items)),
                "score_policy": status.get("score_policy", "verified_and_score_allowed_only"),
                "items": items,
                "source_status": source_status,
                "message": message,
            }
        )
    return rows


