def _action_lookahead_timing_audit(
    action: dict[str, object],
    *,
    required: bool = False,
    expected_calendar_root: object = "",
) -> dict[str, object]:
    evidence_keys = (
        "decision_data_as_of",
        "execution_at",
        "signal_lag_bars",
        "decision_market_price",
        "execution_price_basis",
    )
    calendar_evidence_keys = (
        "symbol_calendar_contract",
        "symbol_calendar_root",
        "symbol_calendar_pair_count",
        "symbol_calendar_adjacency_index",
        "decision_symbol_bar_index",
        "execution_symbol_bar_index",
        "decision_symbol_bar_date",
        "execution_symbol_bar_date",
        "symbol_calendar_adjacency_proof",
    )

    def missing(value: object) -> bool:
        return value is None or value == ""

    has_evidence = any(not missing(action.get(key)) for key in (*evidence_keys, *calendar_evidence_keys))
    if not required and not has_evidence:
        return {"ok": True, "status": "legacy_not_checked", "blockers": [], "required": False}

    blockers: list[str] = []
    required_keys = (*evidence_keys, *calendar_evidence_keys) if required else evidence_keys
    missing_keys = [key for key in required_keys if missing(action.get(key))]
    if missing_keys:
        blockers.append("lookahead_timing_evidence_missing:" + ",".join(missing_keys))

    def parse(value: object) -> datetime | None:
        try:
            parsed = datetime.fromisoformat(str(value or "").strip().replace("Z", "+00:00"))
        except (TypeError, ValueError):
            return None
        if parsed.tzinfo is not None:
            parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
        return parsed

    decision_at = parse(action.get("decision_data_as_of"))
    execution_at = parse(action.get("execution_at"))
    action_at = parse(action.get("date"))
    if decision_at is None or execution_at is None:
        blockers.append("lookahead_timing_date_invalid")
    elif decision_at >= execution_at:
        blockers.append("lookahead_detected:decision_data_not_before_execution")
    if action_at is None or execution_at is None or action_at.date() != execution_at.date():
        blockers.append("execution_date_mismatch")

    lag = _number(action.get("signal_lag_bars"))
    if lag < 1 or abs(lag - round(lag)) > 1e-9:
        blockers.append("signal_lag_bars_invalid")
    if _number(action.get("decision_market_price")) <= 0:
        blockers.append("decision_market_price_invalid")
    basis = str(action.get("execution_price_basis") or "").strip().lower()
    if basis not in {"next_available_open", "next_available_close", "next_available_bar"}:
        blockers.append("execution_price_basis_invalid")
    calendar_proof_required = required or any(not missing(action.get(key)) for key in calendar_evidence_keys)
    calendar_proof_ok = False
    if calendar_proof_required:
        calendar_proof_ok = verify_calendar_adjacency_proof(
            action,
            expected_symbol=action.get("symbol"),
            expected_root=expected_calendar_root,
        )
        if not calendar_proof_ok:
            blockers.append("lookahead_calendar_adjacency_proof_invalid")
        decision_bar_date = str(action.get("decision_symbol_bar_date") or "").strip()[:10]
        execution_bar_date = str(action.get("execution_symbol_bar_date") or "").strip()[:10]
        if decision_at is None or decision_bar_date != decision_at.date().isoformat():
            blockers.append("decision_calendar_date_mismatch")
        if execution_at is None or execution_bar_date != execution_at.date().isoformat():
            blockers.append("execution_calendar_date_mismatch")
        if abs(lag - 1.0) > 1e-9:
            blockers.append("signal_lag_calendar_adjacency_mismatch")
    unique = list(dict.fromkeys(blockers))
    return {
        "ok": not unique,
        "status": "lookahead_safe" if not unique else "lookahead_blocked",
        "required": bool(required),
        "decision_data_as_of": action.get("decision_data_as_of"),
        "execution_at": action.get("execution_at"),
        "signal_lag_bars": action.get("signal_lag_bars"),
        "decision_market_price": action.get("decision_market_price"),
        "execution_price_basis": action.get("execution_price_basis"),
        "calendar_proof_checked": calendar_proof_required,
        "calendar_proof_ok": calendar_proof_ok if calendar_proof_required else None,
        "symbol_calendar_root": action.get("symbol_calendar_root"),
        "expected_symbol_calendar_root": str(expected_calendar_root or ""),
        "blockers": unique,
    }


def _closed_trade_journal_from_actions(
    trades: list[dict[str, object]],
    *,
    require_lookahead_evidence: bool = False,
    symbol_calendar_roots: dict[str, object] | None = None,
) -> list[dict[str, object]]:
    journal: list[dict[str, object]] = []
    open_stack: dict[str, list[dict[str, object]]] = {}
    for trade in trades:
        if not isinstance(trade, dict):
            continue
        symbol = str(trade.get("symbol", ""))
        if not symbol:
            continue
        side = str(trade.get("side", "")).upper()
        if side == "BUY":
            open_stack.setdefault(symbol, []).append(trade)
            continue
        if side != "SELL":
            continue
        entries = open_stack.get(symbol, [])
        entry_trade = entries.pop(0) if entries else {}
        roots = symbol_calendar_roots if isinstance(symbol_calendar_roots, dict) else {}
        expected_calendar_root = roots.get(symbol) or roots.get(symbol.upper()) or ""
        entry_timing = _action_lookahead_timing_audit(
            entry_trade,
            required=require_lookahead_evidence,
            expected_calendar_root=expected_calendar_root,
        )
        exit_timing = _action_lookahead_timing_audit(
            trade,
            required=require_lookahead_evidence,
            expected_calendar_root=expected_calendar_root,
        )
        entry_date = str(trade.get("entry_date") or entry_trade.get("date") or "")
        entry_price = _number(trade.get("entry_price") or entry_trade.get("price"))
        exit_price = _number(trade.get("price"))
        recorded_pnl_present = trade.get("pnl_pct") not in {None, ""}
        if recorded_pnl_present:
            pnl_pct = _number(trade.get("pnl_pct"))
            pnl_pct_source = "recorded"
        elif entry_price > 0 and exit_price > 0:
            pnl_pct = ((exit_price / entry_price) - 1.0) * 100.0
            pnl_pct_source = "computed_from_entry_exit"
        else:
            pnl_pct = 0.0
            pnl_pct_source = "missing"
        row = {
            "symbol": symbol,
            "name": trade.get("name") or entry_trade.get("name") or symbol,
            "strategy": trade.get("strategy") or entry_trade.get("strategy") or "",
            "entry_date": entry_date,
            "entry_price": round(entry_price, 4),
            "entry_reason": trade.get("entry_reason") or entry_trade.get("reason") or "",
            "entry_score": trade.get("entry_score") or entry_trade.get("score") or 0,
            "exit_date": trade.get("date"),
            "exit_price": round(exit_price, 4),
            "exit_reason": trade.get("reason", ""),
            "peak_market_price": trade.get("peak_market_price"),
            "exit_trigger_market_price": trade.get("exit_trigger_market_price"),
            "peak_drawdown_pct": trade.get("peak_drawdown_pct"),
            "trailing_trigger_pct": trade.get("trailing_trigger_pct"),
            "decision_return_pct": trade.get("decision_return_pct"),
            "quantity": _number(trade.get("quantity")),
            "holding_days": trade.get("holding_days", ""),
            "notional": trade.get("notional", 0),
            "pnl_pct": round(pnl_pct, 2),
            "pnl_pct_source": pnl_pct_source,
            "entry_timing": entry_timing,
            "exit_timing": exit_timing,
            "result": "승리" if pnl_pct > 0 else "손실",
        }
        reconciliation = _trade_price_return_audit(
            row["entry_price"],
            row["exit_price"],
            row["pnl_pct"],
            row["exit_reason"],
            entry_date=row["entry_date"],
            exit_date=row["exit_date"],
            enforce_time_sequence=True,
            reason_evidence={
                "peak_market_price": row.get("peak_market_price"),
                "exit_trigger_market_price": row.get("exit_trigger_market_price"),
                "peak_drawdown_pct": row.get("peak_drawdown_pct"),
                "trailing_trigger_pct": row.get("trailing_trigger_pct"),
                "decision_return_pct": row.get("decision_return_pct"),
            },
        )
        timing_blockers = [
            *entry_timing.get("blockers", []),
            *exit_timing.get("blockers", []),
        ]
        if timing_blockers:
            reconciliation["ok"] = False
            reconciliation["status"] = "LOOKAHEAD_EVIDENCE_BLOCKED"
            reconciliation["severity"] = "blocker"
            reconciliation["official_return_blocker"] = True
            reconciliation["review_action"] = "Regenerate with prior-bar decision evidence and next-bar execution."
            reconciliation["blockers"] = list(
                dict.fromkeys([*reconciliation.get("blockers", []), *timing_blockers])
            )
        reconciliation["lookahead_timing_status"] = (
            "safe" if entry_timing.get("ok") and exit_timing.get("ok") else "blocked"
        )
        reconciliation["entry_timing"] = entry_timing
        reconciliation["exit_timing"] = exit_timing
        row["return_reconciliation"] = reconciliation
        row["reconciliation_status"] = reconciliation.get("status")
        row["review"] = (
            f"{row['entry_date']} {row['name']} 진입: {row['entry_reason'] or '-'} / "
            f"{row['exit_date']} 청산: {row['exit_reason'] or '-'} / 수익률 {pnl_pct:+.2f}%"
        )
        journal.append(row)
    return journal


def _extract_reason_threshold_pct(reason: object) -> float | None:
    text = str(reason or "")
    if not text:
        return None
    trigger_match = re.search(r"(?:트리거|trigger)\s*([+-]?\d+(?:\.\d+)?)\s*%", text, flags=re.IGNORECASE)
    if trigger_match:
        return _number(trigger_match.group(1))
    matches = re.findall(r"([+-]?\d+(?:\.\d+)?)\s*%", text)
    if not matches:
        return None
    return _number(matches[-1])


def _extract_reason_fill_return_pct(reason: object) -> float | None:
    text = str(reason or "")
    if not text:
        return None
    match = re.search(
        r"(?:실제\s*청산|actual(?:\s+fill)?)\s*([+-]?\d+(?:\.\d+)?)\s*%",
        text,
        flags=re.IGNORECASE,
    )
    return _number(match.group(1)) if match else None


def _reason_threshold_basis(reason: object) -> str:
    text = str(reason or "").lower()
    if re.search(r"trailing|trail|트레일|고점\s*대비|peak\s*drawdown", text, flags=re.IGNORECASE):
        return "peak_drawdown"
    return "entry_return"


def _trade_price_return_audit(
    entry_price: object,
    exit_price: object,
    recorded_return_pct: object,
    exit_reason: object,
    entry_date: object = None,
    exit_date: object = None,
    enforce_time_sequence: bool = False,
    reason_evidence: dict[str, object] | None = None,
) -> dict[str, object]:
    entry = _number(entry_price)
    exit_value = _number(exit_price)
    recorded = round(_number(recorded_return_pct), 4)
    warnings: list[str] = []
    blockers: list[str] = []
    computed: float | None = None
    return_diff: float | None = None
    status = "OK"
    severity = "ok"
    official_return_blocker = False
    review_action = ""
    if entry <= 0 or exit_value <= 0:
        status = "MISSING_PRICE"
        severity = "blocker"
        official_return_blocker = True
        review_action = "Regenerate the trade journal with entry/exit prices before using this return as official."
        blockers.append("진입가 또는 청산가가 없어 수익률을 재계산할 수 없습니다.")
    else:
        computed = round(((exit_value / entry) - 1.0) * 100.0, 4)
        return_diff = round(computed - recorded, 4)
        if abs(return_diff) > 0.15:
            status = "PRICE_RETURN_MISMATCH"
            severity = "blocker"
            official_return_blocker = True
            review_action = "Regenerate the return from the same entry/exit fill engine before publishing the result."
            blockers.append("기록 수익률과 진입가/청산가 재계산 수익률이 다릅니다.")

    exit_reason_present = bool(str(exit_reason or "").strip())
    if not exit_reason_present:
        if status == "OK":
            status = "MISSING_EXIT_REASON"
            severity = "blocker"
            review_action = "Regenerate the trade journal with the actual exit trigger before publishing the return."
        official_return_blocker = True
        blockers.append("Exit reason is missing, so the liquidation decision cannot be audited.")

    time_sequence_status = "not_checked"
    holding_seconds: float | None = None
    if enforce_time_sequence:
        try:
            entry_time = datetime.fromisoformat(str(entry_date or "").strip().replace("Z", "+00:00"))
            exit_time = datetime.fromisoformat(str(exit_date or "").strip().replace("Z", "+00:00"))
            if entry_time.tzinfo is not None:
                entry_time = entry_time.astimezone(timezone.utc).replace(tzinfo=None)
            if exit_time.tzinfo is not None:
                exit_time = exit_time.astimezone(timezone.utc).replace(tzinfo=None)
            holding_seconds = (exit_time - entry_time).total_seconds()
            time_sequence_status = "valid" if holding_seconds >= 0 else "reversed"
        except (TypeError, ValueError):
            time_sequence_status = "missing_or_invalid"
        if time_sequence_status != "valid":
            if status == "OK":
                status = "INVALID_TRADE_TIME_SEQUENCE"
                severity = "blocker"
                review_action = "Regenerate the journal with valid entry and exit timestamps before publishing the return."
            official_return_blocker = True
            blockers.append(f"Trade time sequence is {time_sequence_status}; exit must be at or after entry.")

    reason_fill_return = _extract_reason_fill_return_pct(exit_reason)
    reason_fill_diff: float | None = None
    if reason_fill_return is not None and computed is not None:
        reason_fill_diff = round(computed - reason_fill_return, 4)
        if abs(reason_fill_diff) > 0.15 and status == "OK":
            status = "REASON_FILL_RETURN_MISMATCH"
            severity = "blocker"
            official_return_blocker = True
            review_action = "Regenerate exit_reason from the same fill return used by the trade journal."
            blockers.append("Exit reason actual-fill return does not match entry/exit price return.")

    evidence = reason_evidence if isinstance(reason_evidence, dict) else {}
    decision_return_present = evidence.get("decision_return_pct") not in {None, ""}
    decision_return_pct = _number(evidence.get("decision_return_pct")) if decision_return_present else computed
    threshold = _extract_reason_threshold_pct(exit_reason)
    threshold_basis = _reason_threshold_basis(exit_reason)
    threshold_diff: float | None = None
    threshold_met: bool | None = None
    reason_direction_matched: bool | None = None
    peak_market_price: float | None = None
    exit_trigger_market_price: float | None = None
    computed_peak_drawdown_pct: float | None = None
    recorded_peak_drawdown_pct: float | None = None
    peak_drawdown_diff_pct: float | None = None
    trailing_trigger_pct: float | None = None
    trailing_evidence_status = "not_required"
    if threshold is not None and computed is not None and threshold_basis == "peak_drawdown":
        peak_present = evidence.get("peak_market_price") not in {None, ""}
        trigger_present = evidence.get("exit_trigger_market_price") not in {None, ""}
        recorded_drawdown_present = evidence.get("peak_drawdown_pct") not in {None, ""}
        trailing_trigger_present = evidence.get("trailing_trigger_pct") not in {None, ""}
        if peak_present:
            peak_market_price = _number(evidence.get("peak_market_price"))
        if trigger_present:
            exit_trigger_market_price = _number(evidence.get("exit_trigger_market_price"))
        if recorded_drawdown_present:
            recorded_peak_drawdown_pct = _number(evidence.get("peak_drawdown_pct"))
        if trailing_trigger_present:
            trailing_trigger_pct = _number(evidence.get("trailing_trigger_pct"))
        if peak_market_price and peak_market_price > 0 and exit_trigger_market_price and exit_trigger_market_price > 0:
            computed_peak_drawdown_pct = round(
                ((exit_trigger_market_price / peak_market_price) - 1.0) * 100.0,
                4,
            )
            effective_threshold = trailing_trigger_pct if trailing_trigger_pct is not None else threshold
            threshold = effective_threshold
            threshold_diff = round(computed_peak_drawdown_pct - effective_threshold, 4)
            threshold_tolerance = max(0.25, abs(effective_threshold) * 0.05)
            threshold_met = computed_peak_drawdown_pct <= effective_threshold + threshold_tolerance
            reason_direction_matched = computed_peak_drawdown_pct <= threshold_tolerance
            trailing_evidence_status = "verified"
            if recorded_peak_drawdown_pct is not None:
                peak_drawdown_diff_pct = round(computed_peak_drawdown_pct - recorded_peak_drawdown_pct, 4)
                if abs(peak_drawdown_diff_pct) > 0.15:
                    trailing_evidence_status = "inconsistent"
                    if status == "OK":
                        status = "TRAILING_EVIDENCE_MISMATCH"
                        severity = "blocker"
                        official_return_blocker = True
                        review_action = "Regenerate peak drawdown evidence from the same market-price series."
                    blockers.append("기록된 고점 대비 하락률과 최고가/신호가 재계산 값이 다릅니다.")
            if peak_market_price + 1e-9 < exit_trigger_market_price:
                trailing_evidence_status = "invalid_peak"
                if status == "OK":
                    status = "TRAILING_PEAK_INVALID"
                    severity = "blocker"
                    official_return_blocker = True
                    review_action = "Regenerate the observed peak; peak price cannot be below the trigger price."
                blockers.append("관측 최고가가 청산 신호가보다 낮아 trailing 증거가 유효하지 않습니다.")
            elif not threshold_met and status == "OK":
                status = "REASON_TRAILING_THRESHOLD_NOT_MET"
                severity = "blocker"
                official_return_blocker = True
                review_action = "Review the trailing trigger and peak-price evidence before publishing the return."
                blockers.append("고점 대비 하락률이 기록된 trailing 발동 기준에 도달하지 않았습니다.")
        else:
            threshold_diff = round(computed - threshold, 4)
            threshold_tolerance = max(0.25, abs(threshold) * 0.05)
            trailing_evidence_status = "missing"
            if status == "OK":
                status = "REASON_TRAILING_PEAK_UNVERIFIED"
                severity = "warning"
                review_action = "Attach peak-price evidence to verify the trailing drawdown trigger."
            warnings.append("Trailing threshold uses peak drawdown and cannot be verified from entry/exit prices alone.")
    if threshold is not None and decision_return_pct is not None and threshold_basis != "peak_drawdown":
        threshold_diff = round(decision_return_pct - threshold, 4)
        threshold_tolerance = max(0.25, abs(threshold) * 0.05)
        # Exit reasons and published returns use 0.01 percentage-point precision.
        # Compare at that same precision so an invisible fourth-decimal fill
        # artifact cannot turn an exact displayed tolerance boundary into a block.
        comparison_computed = round(decision_return_pct, 2)
        comparison_threshold = round(threshold, 2)
        if threshold > 0:
            threshold_met = comparison_computed >= comparison_threshold - threshold_tolerance
            reason_direction_matched = comparison_computed >= -threshold_tolerance
        elif threshold < 0:
            threshold_met = comparison_computed <= comparison_threshold + threshold_tolerance
            reason_direction_matched = comparison_computed <= threshold_tolerance
        else:
            threshold_met = abs(comparison_computed) <= threshold_tolerance
            reason_direction_matched = True
        if not threshold_met:
            if status == "OK":
                status = "REASON_DIRECTION_MISMATCH" if not reason_direction_matched else "REASON_THRESHOLD_NOT_MET"
                severity = "blocker" if not reason_direction_matched else "warning"
                official_return_blocker = True
                review_action = "Review trigger direction and fill evidence before publishing this return."
            warnings.append("청산 사유의 기준 수익률과 실제 청산 수익률 차이가 큽니다.")

    return {
        "ok": status == "OK",
        "status": status,
        "severity": severity,
        "official_return_blocker": official_return_blocker,
        "review_action": review_action,
        "computed_return_pct": round(computed, 2) if computed is not None else None,
        "recorded_return_pct": round(recorded, 2),
        "return_diff_pct": round(return_diff, 2) if return_diff is not None else None,
        "reason_threshold_pct": round(threshold, 2) if threshold is not None else None,
        "reason_threshold_diff_pct": round(threshold_diff, 2) if threshold_diff is not None else None,
        "reason_threshold_tolerance_pct": round(threshold_tolerance, 2) if threshold is not None and computed is not None else None,
        "reason_threshold_basis": threshold_basis,
        "reason_threshold_verifiable": threshold_basis == "entry_return" or trailing_evidence_status == "verified",
        "reason_threshold_met": threshold_met,
        "reason_direction_matched": reason_direction_matched,
        "peak_market_price": round(peak_market_price, 4) if peak_market_price is not None else None,
        "exit_trigger_market_price": round(exit_trigger_market_price, 4) if exit_trigger_market_price is not None else None,
        "computed_peak_drawdown_pct": round(computed_peak_drawdown_pct, 2) if computed_peak_drawdown_pct is not None else None,
        "recorded_peak_drawdown_pct": round(recorded_peak_drawdown_pct, 2) if recorded_peak_drawdown_pct is not None else None,
        "peak_drawdown_diff_pct": round(peak_drawdown_diff_pct, 2) if peak_drawdown_diff_pct is not None else None,
        "trailing_trigger_pct": round(trailing_trigger_pct, 2) if trailing_trigger_pct is not None else None,
        "trailing_evidence_status": trailing_evidence_status,
        "reason_fill_return_pct": round(reason_fill_return, 2) if reason_fill_return is not None else None,
        "reason_fill_diff_pct": round(reason_fill_diff, 2) if reason_fill_diff is not None else None,
        "decision_return_pct": round(decision_return_pct, 2) if decision_return_pct is not None else None,
        "exit_reason_present": exit_reason_present,
        "time_sequence_status": time_sequence_status,
        "holding_seconds": round(holding_seconds, 3) if holding_seconds is not None else None,
        "warnings": warnings,
        "blockers": blockers,
    }


def _closed_trade_reconciliation_summary(closed_journal: list[dict[str, object]], limit: int = 8) -> dict[str, object]:
    checked = 0
    ok_count = 0
    warning_count = 0
    blocker_count = 0
    official_return_blocker_count = 0
    samples: list[dict[str, object]] = []
    for row in closed_journal:
        if not isinstance(row, dict):
            continue
        audit = row.get("return_reconciliation") if isinstance(row.get("return_reconciliation"), dict) else {}
        if not audit:
            continue
        checked += 1
        warnings = audit.get("warnings") if isinstance(audit.get("warnings"), list) else []
        blockers = audit.get("blockers") if isinstance(audit.get("blockers"), list) else []
        if audit.get("ok"):
            ok_count += 1
        if warnings:
            warning_count += 1
        if blockers:
            blocker_count += 1
        if audit.get("official_return_blocker"):
            official_return_blocker_count += 1
        if (warnings or blockers) and len(samples) < max(1, int(limit or 8)):
            samples.append(
                {
                    "symbol": row.get("symbol"),
                    "name": row.get("name"),
                    "entry_date": row.get("entry_date"),
                    "exit_date": row.get("exit_date"),
                    "entry_price": row.get("entry_price"),
                    "exit_price": row.get("exit_price"),
                    "pnl_pct": row.get("pnl_pct"),
                    "exit_reason": row.get("exit_reason"),
                    "status": audit.get("status"),
                    "severity": audit.get("severity"),
                    "official_return_blocker": audit.get("official_return_blocker"),
                    "review_action": audit.get("review_action"),
                    "computed_return_pct": audit.get("computed_return_pct"),
                    "reason_threshold_pct": audit.get("reason_threshold_pct"),
                    "reason_threshold_diff_pct": audit.get("reason_threshold_diff_pct"),
                    "reason_threshold_tolerance_pct": audit.get("reason_threshold_tolerance_pct"),
                    "reason_threshold_basis": audit.get("reason_threshold_basis"),
                    "reason_threshold_verifiable": audit.get("reason_threshold_verifiable"),
                    "peak_market_price": audit.get("peak_market_price"),
                    "exit_trigger_market_price": audit.get("exit_trigger_market_price"),
                    "computed_peak_drawdown_pct": audit.get("computed_peak_drawdown_pct"),
                    "recorded_peak_drawdown_pct": audit.get("recorded_peak_drawdown_pct"),
                    "peak_drawdown_diff_pct": audit.get("peak_drawdown_diff_pct"),
                    "trailing_trigger_pct": audit.get("trailing_trigger_pct"),
                    "trailing_evidence_status": audit.get("trailing_evidence_status"),
                    "exit_reason_present": audit.get("exit_reason_present"),
                    "time_sequence_status": audit.get("time_sequence_status"),
                    "lookahead_timing_status": audit.get("lookahead_timing_status"),
                    "entry_timing": audit.get("entry_timing"),
                    "exit_timing": audit.get("exit_timing"),
                    "holding_seconds": audit.get("holding_seconds"),
                    "warnings": warnings,
                    "blockers": blockers,
                }
            )
    return {
        "reconciliation_engine_version": "trade-price-return-audit.v7",
        "checked_count": checked,
        "ok_count": ok_count,
        "warning_count": warning_count,
        "blocker_count": blocker_count,
        "official_return_blocker_count": official_return_blocker_count,
        "needs_review": warning_count + blocker_count,
        "samples": samples,
        "summary": f"청산 매매 {checked:,}건 대사: 정상 {ok_count:,}건, 주의 {warning_count:,}건, 차단급 {blocker_count:,}건",
    }


def _backtest_primary_symbol(result: dict[str, object]) -> str:
    symbol = str(result.get("symbol") or "").strip().upper()
    if symbol:
        return symbol
    symbols = result.get("symbols") if isinstance(result.get("symbols"), list) else []
    for item in symbols:
        symbol = str(item or "").strip().upper()
        if symbol:
            return symbol
    return ""


def _backtest_day_to_date(result: dict[str, object], day_value: object) -> str:
    dates = result.get("dates") if isinstance(result.get("dates"), list) else []
    try:
        day = int(float(str(day_value or "0").strip()))
    except (TypeError, ValueError):
        day = 0
    if dates and 1 <= day <= len(dates):
        return str(dates[day - 1])
    return str(day_value or "").strip()


def _backtest_trade_actions_for_reconciliation(result: dict[str, object]) -> list[dict[str, object]]:
    actions = result.get("trade_actions_sample") if isinstance(result.get("trade_actions_sample"), list) else []
    if not actions:
        actions = result.get("trades") if isinstance(result.get("trades"), list) else []
    symbol = _backtest_primary_symbol(result)
    name = str(result.get("name") or result.get("display_name") or symbol).strip()
    normalized: list[dict[str, object]] = []
    for trade in actions:
        if not isinstance(trade, dict):
            continue
        row = dict(trade)
        if symbol and not row.get("symbol"):
            row["symbol"] = symbol
        if name and not row.get("name"):
            row["name"] = name
        if not row.get("date"):
            row["date"] = _backtest_day_to_date(result, row.get("day") or row.get("bar") or row.get("index"))
        normalized.append(row)
    return normalized


def _open_position_return_reconciliation(
    result: dict[str, object],
    actions: list[dict[str, object]],
) -> dict[str, object] | None:
    """Prove a return made entirely of still-open Paper positions."""
    if not actions or any(str(row.get("side") or "").strip().upper() != "BUY" for row in actions):
        return None
    positions = result.get("open_positions") if isinstance(result.get("open_positions"), list) else []
    if not positions:
        return None

    blockers: list[str] = []
    timing_model = result.get("execution_timing_model") if isinstance(result.get("execution_timing_model"), dict) else {}
    timing_required = bool(timing_model.get("lookahead_safe_required"))
    bundle_evidence = result.get("replay_data_bundle_evidence") if isinstance(result.get("replay_data_bundle_evidence"), dict) else {}
    calendar_roots = bundle_evidence.get("symbol_calendar_adjacency_roots") if isinstance(bundle_evidence.get("symbol_calendar_adjacency_roots"), dict) else {}
    if timing_required:
        for action in actions:
            symbol = str(action.get("symbol") or "").strip().upper()
            timing = _action_lookahead_timing_audit(
                action,
                required=True,
                expected_calendar_root=calendar_roots.get(symbol, ""),
            )
            blockers.extend(str(item) for item in timing.get("blockers", []))
    buys: dict[str, dict[str, float]] = {}
    for action in actions:
        symbol = str(action.get("symbol") or "").strip().upper()
        quantity = _number(action.get("quantity"))
        cash_cost = _number(action.get("cash_cost"))
        if not symbol or quantity <= 0 or cash_cost <= 0:
            blockers.append("open_position_buy_evidence_invalid")
            continue
        bucket = buys.setdefault(symbol, {"quantity": 0.0, "cash_cost": 0.0})
        bucket["quantity"] += quantity
        bucket["cash_cost"] += cash_cost

    position_rows: dict[str, dict[str, object]] = {}
    for position in positions:
        if not isinstance(position, dict):
            blockers.append("open_position_record_invalid")
            continue
        symbol = str(position.get("symbol") or "").strip().upper()
        if not symbol or symbol in position_rows:
            blockers.append("open_position_symbol_invalid_or_duplicate")
            continue
        position_rows[symbol] = position
    if set(buys) != set(position_rows):
        blockers.append("open_position_symbol_coverage_mismatch")

    cost_model = result.get("cost_model") if isinstance(result.get("cost_model"), dict) else {}
    commission_rate = _number(cost_model.get("commission_bps_each_side")) / 10_000.0
    slippage_rate = _number(cost_model.get("slippage_bps_each_side")) / 10_000.0
    kr_sell_tax_rate = _number(cost_model.get("kr_sell_tax_bps")) / 10_000.0
    fx_spread_rate = _number(cost_model.get("fx_conversion_spread_bps_each_side")) / 10_000.0
    if commission_rate <= 0 or slippage_rate <= 0 or kr_sell_tax_rate <= 0:
        blockers.append("open_position_cost_model_incomplete")

    audit = result.get("price_currency_unit_audit") if isinstance(result.get("price_currency_unit_audit"), dict) else {}
    contracts = audit.get("contracts") if isinstance(audit.get("contracts"), dict) else {}
    net_liquidation_value = 0.0
    for symbol, buy in buys.items():
        position = position_rows.get(symbol, {})
        quantity = _number(position.get("quantity"))
        avg_cost = _number(position.get("avg_cost"))
        last_price = _number(position.get("last_price"))
        expected_avg_cost = buy["cash_cost"] / buy["quantity"] if buy["quantity"] > 0 else 0.0
        if abs(quantity - buy["quantity"]) > 0.000001:
            blockers.append(f"open_position_quantity_mismatch:{symbol}")
        if avg_cost <= 0 or abs(avg_cost - expected_avg_cost) > max(0.01, expected_avg_cost * 0.0000001):
            blockers.append(f"open_position_avg_cost_mismatch:{symbol}")
        if last_price <= 0:
            blockers.append(f"open_position_last_price_invalid:{symbol}")
            continue
        contract = contracts.get(symbol) if isinstance(contracts.get(symbol), dict) else {}
        if contract.get("passed") is not True:
            blockers.append(f"open_position_price_contract_invalid:{symbol}")
        gross = max(0.0, quantity * last_price * (1.0 - slippage_rate))
        market = str(contract.get("market") or position.get("market") or "").upper()
        sell_tax = gross * kr_sell_tax_rate if market == "KR" else 0.0
        usdkrw_rate = _number(position.get("last_usdkrw_rate"))
        regulatory = (
            _paper_us_regulatory_fee_contract(
                str(position.get("valuation_date") or result.get("actual_end_date") or ""),
                quantity=quantity,
                gross_krw=gross,
                usdkrw_rate=usdkrw_rate,
            )
            if market == "US"
            else {}
        )
        fx_conversion_cost = gross * fx_spread_rate if market == "US" else 0.0
        if market == "US" and (fx_spread_rate <= 0 or usdkrw_rate <= 0):
            blockers.append(f"open_position_us_cost_evidence_incomplete:{symbol}")
        net_liquidation_value += max(
            0.0,
            gross
            - (gross * commission_rate)
            - sell_tax
            - _number(regulatory.get("sec_fee_krw"))
            - _number(regulatory.get("finra_taf_krw"))
            - fx_conversion_cost,
        )

    initial_cash = _number(result.get("initial_cash"))
    expected_cash = initial_cash - sum(bucket["cash_cost"] for bucket in buys.values())
    experience = result.get("experience_log") if isinstance(result.get("experience_log"), list) else []
    final_experience = experience[-1] if experience and isinstance(experience[-1], dict) else {}
    recorded_cash = _number(final_experience.get("cash"))
    final_equity = _number(result.get("final_equity"))
    recorded_return = _number(result.get("total_return_pct"))
    expected_equity = expected_cash + net_liquidation_value
    computed_return = ((final_equity / initial_cash) - 1.0) * 100.0 if initial_cash > 0 else 0.0
    money_tolerance = max(0.05, (len(actions) + len(positions)) * 0.02)
    if initial_cash <= 0 or expected_cash < -money_tolerance:
        blockers.append("open_position_cash_ledger_invalid")
    if abs(recorded_cash - expected_cash) > money_tolerance:
        blockers.append("open_position_final_cash_mismatch")
    if int(_number(final_experience.get("positions"))) != len(position_rows):
        blockers.append("open_position_experience_count_mismatch")
    if abs(_number(final_experience.get("equity")) - final_equity) > money_tolerance:
        blockers.append("open_position_experience_equity_mismatch")
    if abs(expected_equity - final_equity) > money_tolerance:
        blockers.append("open_position_net_liquidation_equity_mismatch")
    if abs(round(computed_return, 2) - recorded_return) > 0.000001:
        blockers.append("open_position_total_return_mismatch")

    unique_blockers = list(dict.fromkeys(blockers))
    passed = not unique_blockers
    return {
        "status": "open_positions_mark_to_market_passed" if passed else "open_positions_mark_to_market_blocked",
        "valuation_scope": "open_positions_net_liquidation",
        "valuation_checked_count": len(position_rows),
        "normalized_action_count": len(actions),
        "checked_count": 0,
        "ok_count": 0,
        "warning_count": 0,
        "blocker_count": len(unique_blockers),
        "official_return_blocker_count": len(unique_blockers),
        "needs_review": 0 if passed else 1,
        "official_return_claim_allowed": passed,
        "expected_final_cash": round(expected_cash, 2),
        "recorded_final_cash": round(recorded_cash, 2),
        "expected_final_equity": round(expected_equity, 2),
        "recorded_final_equity": round(final_equity, 2),
        "computed_return_pct": round(computed_return, 2),
        "recorded_return_pct": round(recorded_return, 2),
        "summary": (
            f"Open-position valuation passed for {len(position_rows)} positions."
            if passed
            else f"Open-position valuation blocked: {', '.join(unique_blockers)}"
        ),
        "samples": [{"status": "BLOCKED", "reason": reason} for reason in unique_blockers[:8]],
        "closed_trade_sample": [],
    }


def build_backtest_return_reconciliation(result: dict[str, object]) -> dict[str, object]:
    actions = _backtest_trade_actions_for_reconciliation(result)
    if not actions:
        return {
            "status": "no_trade_actions",
            "sample_scope": "none",
            "checked_count": 0,
            "ok_count": 0,
            "warning_count": 0,
            "blocker_count": 0,
            "official_return_blocker_count": 0,
            "needs_review": 1,
            "official_return_claim_allowed": False,
            "summary": "No trade actions were available for entry/exit/return reconciliation.",
            "samples": [],
            "closed_trade_sample": [],
        }
    timing_model = result.get("execution_timing_model") if isinstance(result.get("execution_timing_model"), dict) else {}
    bundle_evidence = result.get("replay_data_bundle_evidence") if isinstance(result.get("replay_data_bundle_evidence"), dict) else {}
    calendar_roots = bundle_evidence.get("symbol_calendar_adjacency_roots") if isinstance(bundle_evidence.get("symbol_calendar_adjacency_roots"), dict) else {}
    closed_journal = _closed_trade_journal_from_actions(
        actions,
        require_lookahead_evidence=bool(timing_model.get("lookahead_safe_required")),
        symbol_calendar_roots=calendar_roots,
    )
    summary = _closed_trade_reconciliation_summary(closed_journal)
    checked_count = int(_number(summary.get("checked_count")))
    blocker_count = int(_number(summary.get("blocker_count")))
    warning_count = int(_number(summary.get("warning_count")))
    official_blockers = int(_number(summary.get("official_return_blocker_count")))
    if checked_count <= 0:
        open_position_reconciliation = _open_position_return_reconciliation(result, actions)
        if open_position_reconciliation is not None:
            return open_position_reconciliation
        status = "no_closed_trades"
    elif blocker_count or official_blockers:
        status = "blocked"
    elif warning_count:
        status = "warning"
    else:
        status = "passed"
    return {
        "status": status,
        "sample_scope": "trade_actions_sample" if isinstance(result.get("trade_actions_sample"), list) else "trades",
        "normalized_action_count": len(actions),
        "checked_count": checked_count,
        "ok_count": int(_number(summary.get("ok_count"))),
        "warning_count": warning_count,
        "blocker_count": blocker_count,
        "official_return_blocker_count": official_blockers,
        "needs_review": int(_number(summary.get("needs_review"))) if checked_count else 1,
        "official_return_claim_allowed": (
            checked_count > 0
            and warning_count == 0
            and blocker_count == 0
            and official_blockers == 0
        ),
        "summary": summary.get("summary"),
        "samples": summary.get("samples", []),
        "closed_trade_sample": closed_journal[-8:],
    }


def _historical_replay_official_verdict(
    replay: dict[str, object],
    reconciliation: dict[str, object],
) -> dict[str, object]:
    """Require both trade reconciliation and the replay data contract for official returns."""
    reasons: list[str] = []
    if reconciliation.get("official_return_claim_allowed") is not True:
        reasons.append("trade_reconciliation_not_passed")
    if str(replay.get("data_mode") or "") != "real":
        reasons.append("non_real_market_data")
    timing_model = replay.get("execution_timing_model") if isinstance(replay.get("execution_timing_model"), dict) else {}
    if (
        timing_model.get("lookahead_safe_required") is not True
        or timing_model.get("same_bar_signal_execution_allowed") is not False
        or int(_number(timing_model.get("minimum_signal_lag_bars"))) < 1
        or str(timing_model.get("calendar_adjacency_proof_contract") or "")
        != CALENDAR_ADJACENCY_PROOF_CONTRACT
    ):
        reasons.append("lookahead_safe_execution_timing_model_missing_or_invalid")
    data_errors = replay.get("data_errors")
    if isinstance(data_errors, list) and data_errors:
        reasons.append("market_data_errors_present")
    elif data_errors not in (None, []):
        reasons.append("market_data_errors_invalid")

    audit = replay.get("price_currency_unit_audit")
    if not isinstance(audit, dict):
        reasons.append("price_currency_unit_audit_missing")
        audit = {}
    elif audit.get("passed") is not True or audit.get("blockers"):
        reasons.append("price_currency_unit_audit_not_passed")
    contracts = audit.get("contracts") if isinstance(audit.get("contracts"), dict) else {}
    expected_symbols = {
        str(symbol or "").strip().upper()
        for symbol in (replay.get("symbols") if isinstance(replay.get("symbols"), list) else [])
        if str(symbol or "").strip()
    }
    contract_symbols = {str(symbol or "").strip().upper() for symbol in contracts}
    if not contracts or (expected_symbols and contract_symbols != expected_symbols):
        reasons.append("price_contract_coverage_incomplete")
    if any(
        not isinstance(contract, dict)
        or contract.get("passed") is not True
        or bool(contract.get("blockers"))
        for contract in contracts.values()
    ):
        reasons.append("price_contract_blocker_present")
    bundle_evidence = (
        replay.get("replay_data_bundle_evidence")
        if isinstance(replay.get("replay_data_bundle_evidence"), dict)
        else {}
    )
    bundle_hash = str(bundle_evidence.get("bundle_content_hash") or "")
    slice_hash = str(bundle_evidence.get("slice_content_hash") or "")
    requested_period = (
        bundle_evidence.get("requested_period")
        if isinstance(bundle_evidence.get("requested_period"), dict)
        else {}
    )
    row_counts = (
        bundle_evidence.get("symbol_row_counts")
        if isinstance(bundle_evidence.get("symbol_row_counts"), dict)
        else {}
    )
    row_bounds = (
        bundle_evidence.get("symbol_row_bounds")
        if isinstance(bundle_evidence.get("symbol_row_bounds"), dict)
        else {}
    )
    calendar_roots = (
        bundle_evidence.get("symbol_calendar_adjacency_roots")
        if isinstance(bundle_evidence.get("symbol_calendar_adjacency_roots"), dict)
        else {}
    )
    calendar_pair_counts = (
        bundle_evidence.get("symbol_calendar_pair_counts")
        if isinstance(bundle_evidence.get("symbol_calendar_pair_counts"), dict)
        else {}
    )
    if (
        bundle_evidence.get("schema")
        != HISTORICAL_REPLAY_DATA_BUNDLE_SLICE_EVIDENCE_SCHEMA
        or bundle_evidence.get("used") is not True
        or bundle_evidence.get("passed") is not True
        or bundle_evidence.get("source_fetch_reused") is not True
        or bundle_evidence.get("future_rows_excluded_before_strategy") is not True
        or bundle_evidence.get("no_rows_outside_requested_period") is not True
        or bundle_evidence.get("live_order_allowed") is not False
    ):
        reasons.append("immutable_replay_data_bundle_not_verified")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", bundle_hash) or not re.fullmatch(
        r"sha256:[0-9a-f]{64}", slice_hash
    ):
        reasons.append("replay_data_bundle_hash_missing_or_invalid")
    if requested_period != {
        "start_date": str(replay.get("start_date") or ""),
        "end_date": str(replay.get("end_date") or ""),
    }:
        reasons.append("replay_data_bundle_period_mismatch")
    if (
        set(row_counts) != expected_symbols
        or set(row_bounds) != expected_symbols
        or set(calendar_roots) != expected_symbols
        or set(calendar_pair_counts) != expected_symbols
        or any(int(_number(row_counts.get(symbol))) <= 0 for symbol in expected_symbols)
        or any(
            not re.fullmatch(r"[0-9a-f]{64}", str(calendar_roots.get(symbol) or ""))
            or int(_number(calendar_pair_counts.get(symbol)))
            != max(0, int(_number(row_counts.get(symbol))) - 1)
            for symbol in expected_symbols
        )
    ):
        reasons.append("replay_data_bundle_symbol_coverage_incomplete")
    expected_manifest_hash = _replay_data_bundle_slice_manifest_hash(bundle_evidence)
    if not hmac.compare_digest(
        str(bundle_evidence.get("slice_manifest_hash") or ""),
        expected_manifest_hash,
    ):
        reasons.append("replay_data_bundle_manifest_hash_mismatch")
    return {
        "schema": "codexstock_replay_official_verdict_v1",
        "official_return_claim_allowed": not reasons,
        "block_reasons": list(dict.fromkeys(reasons)),
        "trade_reconciliation_passed": reconciliation.get("official_return_claim_allowed") is True,
        "price_currency_unit_audit_passed": audit.get("passed") is True and not audit.get("blockers"),
        "replay_data_bundle_verified": not any(
            reason.startswith("replay_data_bundle")
            or reason.startswith("immutable_replay_data_bundle")
            for reason in reasons
        ),
        "replay_data_bundle_hash": bundle_hash,
        "replay_data_slice_hash": slice_hash,
        "data_mode": replay.get("data_mode"),
        "data_error_count": len(data_errors) if isinstance(data_errors, list) else int(data_errors not in (None, [])),
    }


def _write_replay_trade_journal_files(record: dict[str, object], actions: list[dict[str, object]], closed_journal: list[dict[str, object]]) -> dict[str, object]:
    replay_id = str(record.get("id") or f"HREPLAY-{int(time.time() * 1000)}")
    TRADE_JOURNAL_DIR.mkdir(parents=True, exist_ok=True)
    json_path = TRADE_JOURNAL_DIR / f"{replay_id}.json"
    top10 = sorted(closed_journal, key=lambda row: _number(row.get("pnl_pct")), reverse=True)[:10]
    bottom10 = sorted(closed_journal, key=lambda row: _number(row.get("pnl_pct")))[:10]
    reconciliation_summary = _closed_trade_reconciliation_summary(closed_journal)
    payload = {
        "id": replay_id,
        "generated_at": record.get("generated_at"),
        "source": record.get("source"),
        "period": f"{record.get('start_date')}~{record.get('end_date')}",
        "strategy": record.get("strategy_label"),
        "symbols": record.get("symbols", []),
        "summary": record.get("summary"),
        "action_count": len(actions),
        "closed_count": len(closed_journal),
        "reconciliation_summary": reconciliation_summary,
        "top10": top10,
        "bottom10": bottom10,
        "closed_trades": closed_journal,
        "actions": actions,
    }
    json_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True), encoding="utf-8")

    md_folder = OBSIDIAN_VAULT / "TradingJournal"
    md_folder.mkdir(parents=True, exist_ok=True)
    md_path = md_folder / f"{replay_id}.md"
    lines = [
        "---",
        "type: historical-replay-trade-journal",
        f"created: {record.get('generated_at')}",
        f"replay_id: {replay_id}",
        "---",
        "",
        f"# 과거장 훈련 매매일지 {replay_id}",
        "",
        f"- 기간: {record.get('start_date')}~{record.get('end_date')}",
        f"- 전략: {record.get('strategy_label')}",
        f"- 전체 매매 이벤트: {len(actions):,}건",
        f"- 청산 완료 매매: {len(closed_journal):,}건",
        f"- 수익률 대사: {reconciliation_summary.get('summary')}",
        f"- 전체 원장 JSON: {json_path}",
        "",
        "## 수익률 대사",
        f"- {reconciliation_summary.get('summary')}",
        f"- 검토 필요: {reconciliation_summary.get('needs_review', 0)}건",
    ]
    for item in reconciliation_summary.get("samples", [])[:5] if isinstance(reconciliation_summary.get("samples"), list) else []:
        lines.append(
            f"- {item.get('name')}({item.get('symbol')}) {item.get('entry_date')}→{item.get('exit_date')} "
            f"기록 {item.get('pnl_pct')}% / 가격재계산 {item.get('computed_return_pct')}% / "
            f"사유기준 {item.get('reason_threshold_pct')}% / 상태 {item.get('status')}"
        )
    lines += [
        "",
        "## 수익률 TOP 10",
    ]
    if top10:
        for index, row in enumerate(top10, start=1):
            lines.append(
                f"{index}. {row.get('name')}({row.get('symbol')}) {row.get('pnl_pct')}% "
                f"/ {row.get('entry_date')} 매수: {row.get('entry_reason')} "
                f"/ {row.get('exit_date')} 매도: {row.get('exit_reason')}"
            )
    else:
        lines.append("- 청산 완료 매매가 아직 없습니다.")
    lines += ["", "## 손실률 하위 10"]
    if bottom10:
        for index, row in enumerate(bottom10, start=1):
            lines.append(
                f"{index}. {row.get('name')}({row.get('symbol')}) {row.get('pnl_pct')}% "
                f"/ {row.get('entry_date')} 매수: {row.get('entry_reason')} "
                f"/ {row.get('exit_date')} 매도: {row.get('exit_reason')}"
            )
    else:
        lines.append("- 청산 완료 매매가 아직 없습니다.")
    lines += ["", "## 전체 청산 매매일지"]
    for index, row in enumerate(closed_journal, start=1):
        lines.append(
            f"{index}. {row.get('entry_date')}→{row.get('exit_date')} "
            f"{row.get('name')}({row.get('symbol')}) {row.get('pnl_pct')}% / "
            f"매수 이유: {row.get('entry_reason')} / 매도 이유: {row.get('exit_reason')}"
        )
    md_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return {
        "json_path": str(json_path),
        "markdown_path": str(md_path),
        "top10": top10,
        "bottom10": bottom10,
        "sample": closed_journal[-80:],
        "closed_count": len(closed_journal),
        "action_count": len(actions),
        "reconciliation_summary": reconciliation_summary,
    }


def _evenly_spaced_indices(length: int, max_points: int) -> list[int]:
    if length <= 0:
        return []
    if length <= max_points:
        return list(range(length))
    last = length - 1
    return sorted({round(index * last / (max_points - 1)) for index in range(max_points)})


def _compact_historical_replay_storage_record(record: dict[str, object]) -> dict[str, object]:
    """Keep replay history useful in the UI without duplicating full journals in every JSONL row."""
    stored = dict(record)
    dates = record.get("dates") if isinstance(record.get("dates"), list) else []
    equity = record.get("equity_curve") if isinstance(record.get("equity_curve"), list) else []
    aligned_count = min(len(dates), len(equity))
    sample_indices = _evenly_spaced_indices(aligned_count, 120)
    stored["dates"] = [dates[index] for index in sample_indices]
    stored["equity_curve"] = [equity[index] for index in sample_indices]

    period_returns = record.get("period_returns") if isinstance(record.get("period_returns"), dict) else {}
    period_limits = {"daily": 10, "weekly": 16, "monthly": 24}
    stored["period_returns"] = {
        period: list(values[-period_limits[period] :])
        for period, values in period_returns.items()
        if period in period_limits and isinstance(values, list)
    }
    list_limits = {
        "experience_log": 10,
        "trades": 20,
        "trade_actions_sample": 10,
        "trade_journal_sample": 10,
        "trade_journal_top10": 3,
        "trade_journal_bottom10": 3,
    }
    for key, limit in list_limits.items():
        values = record.get(key)
        stored[key] = list(values[-limit:]) if isinstance(values, list) else []
    stored["storage_compaction"] = {
        "schema": "historical_replay_compact_v1",
        "full_detail_preserved": bool(record.get("trade_journal_path")),
        "full_detail_path": record.get("trade_journal_path") or "",
        "chart_points_before": aligned_count,
        "chart_points_stored": len(sample_indices),
        "experience_rows_stored": len(stored["experience_log"]),
        "trade_rows_stored": len(stored["trades"]),
        "journal_rows_stored": len(stored["trade_journal_sample"]),
    }
    return stored


def _historical_replay_artifact_anchors(
    record: dict[str, object],
    *,
    stored_replay: dict[str, object] | None = None,
) -> dict[str, str]:
    """Bind one persisted replay row and its exact journal bytes to the ledger."""
    replay_id = str(record.get("id") or "").strip().upper()
    if not re.fullmatch(r"HREPLAY-[0-9]+", replay_id):
        raise ValueError("invalid regenerated replay id for artifact anchoring")
    expected_journal_path = (TRADE_JOURNAL_DIR / f"{replay_id}.json").resolve()
    reported_path = Path(str(record.get("trade_journal_path") or "")).resolve()
    if (
        reported_path != expected_journal_path
        or not expected_journal_path.is_file()
        or not is_inside(expected_journal_path, USER_DATA_ROOT)
    ):
        raise FileNotFoundError("regenerated replay journal is not safely persisted")
    journal_bytes = expected_journal_path.read_bytes()
    journal_payload = json.loads(journal_bytes.decode("utf-8"))
    if not isinstance(journal_payload, dict) or not isinstance(
        journal_payload.get("actions"), list
    ):
        raise ValueError("regenerated replay journal actions are invalid")
    persisted_replay = (
        dict(stored_replay)
        if isinstance(stored_replay, dict)
        else _compact_historical_replay_storage_record(record)
    )
    return {
        "artifact_hash_contract": REPLAY_ARTIFACT_HASH_CONTRACT,
        "replay_artifact_sha256": canonical_replay_artifact_sha256(
            persisted_replay
        ),
        "journal_artifact_sha256": journal_artifact_sha256(journal_bytes),
    }


def _historical_replay_contract_from_payload(
    payload: dict[str, object],
    normalized_id: str,
    *,
    detail_path: Path,
    detail_source: str,
) -> dict[str, object]:
    if str(payload.get("id") or "").strip().upper() != normalized_id:
        return {
            "ok": False,
            "status": "detail_identity_mismatch",
            "replay_id": normalized_id,
            "detail_path": str(detail_path),
            "detail_source": detail_source,
            "operator_message": "historical replay data backfill deferred: market-priority mode is active.",
            "paper_only": True,
            "live_order_allowed": False,
        }
    strategy_config = payload.get("strategy_config") if isinstance(payload.get("strategy_config"), dict) else {}
    symbols = list(dict.fromkeys(
        str(symbol or "").strip().upper()
        for symbol in payload.get("symbols", [])
        if str(symbol or "").strip()
    )) if isinstance(payload.get("symbols"), list) else []
    required = {
        "symbols": bool(symbols),
        "start_date": bool(str(payload.get("start_date") or "").strip()),
        "end_date": bool(str(payload.get("end_date") or "").strip()),
        "strategy_mode": bool(str(payload.get("strategy_mode") or "").strip()),
        "fast": _number(strategy_config.get("fast", payload.get("fast"))) >= 2,
        "slow": _number(strategy_config.get("slow", payload.get("slow"))) > _number(strategy_config.get("fast", payload.get("fast"))),
        "initial_cash": _number(payload.get("initial_cash")) > 0,
        "allocation_pct": _number(strategy_config.get("allocation_pct")) > 0,
        "max_positions": _number(strategy_config.get("max_positions")) > 0,
    }
    missing_fields = [key for key, present in required.items() if not present]
    archived_costs = {
        key: payload.get(key)
        for key in (
            "commission_bps",
            "slippage_bps",
            "kr_sell_tax_bps",
            "fx_conversion_spread_bps",
        )
        if payload.get(key) is not None
    }
    cost_policy_changed = len(archived_costs) != 4
    run_arguments = {
        "symbols": symbols,
        "start_date": str(payload.get("start_date") or ""),
        "end_date": str(payload.get("end_date") or ""),
        "fast": int(_number(strategy_config.get("fast", payload.get("fast"))) or 12),
        "slow": int(_number(strategy_config.get("slow", payload.get("slow"))) or 32),
        "initial_cash": _number(payload.get("initial_cash")),
        "allocation_pct": _number(strategy_config.get("allocation_pct")),
        "max_positions": int(_number(strategy_config.get("max_positions"))),
        "strategy_mode": str(payload.get("strategy_mode") or ""),
        "stop_loss_pct": _number(strategy_config.get("stop_loss_pct")),
        "take_profit_pct": _number(strategy_config.get("take_profit_pct")),
        "holding_limit_days": int(_number(strategy_config.get("holding_limit_days"))),
        "cycles_per_day": int(_number(strategy_config.get("cycles_per_day", payload.get("cycles_per_day"))) or 24),
        "allow_simulated_fallback": False,
        "persist_detail": True,
        "commission_bps": _number(archived_costs.get("commission_bps")) or DEFAULT_PAPER_COMMISSION_BPS,
        "slippage_bps": _number(archived_costs.get("slippage_bps")) or DEFAULT_PAPER_SLIPPAGE_BPS,
        "kr_sell_tax_bps": _number(archived_costs.get("kr_sell_tax_bps")) or DEFAULT_PAPER_KR_SELL_TAX_BPS,
        "fx_conversion_spread_bps": (
            _number(archived_costs.get("fx_conversion_spread_bps"))
            or DEFAULT_PAPER_FX_SPREAD_BPS
        ),
    }
    ready = not missing_fields
    return {
        "ok": ready,
        "status": "ready_with_cost_policy_change" if ready and cost_policy_changed else "ready" if ready else "contract_incomplete",
        "replay_id": normalized_id,
        "detail_path": str(detail_path),
        "detail_source": detail_source,
        "source_generated_at": payload.get("generated_at"),
        "source_trade_count": int(_number(payload.get("closed_trade_count"))),
        "source_total_return_pct": _number(payload.get("total_return_pct")),
        "source_data_mode": payload.get("data_mode"),
        "missing_fields": missing_fields,
        "strategy_config": strategy_config,
        "run_arguments": run_arguments if ready else {},
        "cost_policy": {
            "archived": archived_costs,
            "current": {
                "commission_bps": run_arguments["commission_bps"],
                "slippage_bps": run_arguments["slippage_bps"],
                "kr_sell_tax_bps": run_arguments["kr_sell_tax_bps"],
                "fx_conversion_spread_bps": run_arguments["fx_conversion_spread_bps"],
                "policy_version": PAPER_COST_POLICY_VERSION,
                "us_regulatory_fee_policy_version": PAPER_US_REGULATORY_POLICY_VERSION,
                "us_sec_fee_schedule": [dict(row) for row in PAPER_US_SEC_FEE_SCHEDULE],
                "us_finra_taf_schedule": [dict(row) for row in PAPER_US_FINRA_TAF_SCHEDULE],
            },
            "changed_from_archive": cost_policy_changed,
            "comparison_rule": "Do not attribute return differences solely to strategy when the legacy archive omitted mandatory costs.",
        },
        "paper_only": True,
        "live_order_allowed": False,
        "safety": "This contract can only feed run_historical_paper_replay and never submits a broker order.",
    }


def _indexed_historical_replay_contract_payload(
    normalized_id: str,
    index_path: Path | None = None,
) -> tuple[dict[str, object] | None, Path]:
    return _load_indexed_contract_payload(
        normalized_id,
        index_path or HISTORICAL_REPLAY_BACKUP_CONTRACT_INDEX_FILE,
    )


def build_historical_replay_backup_contract_index(
    replay_ids: list[str],
    *,
    backup_root: Path | None = None,
    index_path: Path | None = None,
) -> dict[str, object]:
    """Extract only immutable replay inputs from preserved JSONL backups."""
    result = _build_backup_contract_index(
        replay_ids,
        backup_root=backup_root or (USER_DATA_ROOT / "backups" / "jsonl_compaction"),
        index_path=index_path or HISTORICAL_REPLAY_BACKUP_CONTRACT_INDEX_FILE,
        now=lambda: datetime.now(ZoneInfo("Asia/Seoul")),
    )
    return {
        **result,
        "paper_only": True,
        "live_order_allowed": False,
    }


def _embedded_tournament_replay_contract_payload(
    normalized_id: str,
    *,
    tournament_path: Path | None = None,
) -> dict[str, object] | None:
    """Recover immutable replay inputs embedded in a preserved tournament row."""
    source_path = tournament_path or AI_TOURNAMENT_FILE
    records = _read_jsonl(source_path, limit=1000)
    for record in reversed(records):
        rankings = record.get("rankings") if isinstance(record, dict) else []
        if not isinstance(rankings, list):
            continue
        for row in rankings:
            if not isinstance(row, dict):
                continue
            if str(row.get("replay_id") or "").strip().upper() != normalized_id:
                continue
            challenge = (
                row.get("selected_challenge_config")
                if isinstance(row.get("selected_challenge_config"), dict)
                else {}
            )
            cost_model = row.get("cost_model") if isinstance(row.get("cost_model"), dict) else {}
            return {
                "id": normalized_id,
                "generated_at": record.get("generated_at"),
                "symbols": row.get("selected_symbols", []),
                "start_date": record.get("start_date"),
                "end_date": record.get("end_date"),
                "strategy_mode": row.get("strategy_mode") or challenge.get("strategy_mode"),
                "fast": row.get("fast_window"),
                "slow": row.get("slow_window"),
                "initial_cash": row.get("initial_cash"),
                "strategy_config": {
                    "fast": row.get("fast_window"),
                    "slow": row.get("slow_window"),
                    "allocation_pct": challenge.get("allocation_pct"),
                    "max_positions": challenge.get("max_positions"),
                    "stop_loss_pct": challenge.get("stop_loss_pct"),
                    "take_profit_pct": challenge.get("take_profit_pct"),
                    "holding_limit_days": challenge.get("holding_limit_days"),
                    "cycles_per_day": challenge.get("cycles_per_day", 24),
                },
                "commission_bps": cost_model.get("commission_bps_each_side"),
                "slippage_bps": cost_model.get("slippage_bps_each_side"),
                "kr_sell_tax_bps": cost_model.get("kr_sell_tax_bps"),
                "fx_conversion_spread_bps": cost_model.get("fx_conversion_spread_bps_each_side"),
                "closed_trade_count": row.get("closed_trade_count"),
                "total_return_pct": row.get("total_return_pct"),
                "data_mode": row.get("data_mode"),
            }
    return None


def historical_replay_regeneration_contract(
    replay_id: str,
    *,
    detail_root: Path | None = None,
) -> dict[str, object]:
    """Recover a replay's immutable Paper inputs without trusting tournament summaries."""
    normalized_id = str(replay_id or "").strip().upper()
    if not re.fullmatch(r"HREPLAY-[0-9]+", normalized_id):
        return {
            "ok": False,
            "status": "invalid_replay_id",
            "replay_id": normalized_id,
            "paper_only": True,
            "live_order_allowed": False,
        }
    root = (detail_root or HISTORICAL_REPLAY_DETAIL_DIR).resolve()
    archive_path = (root / f"{normalized_id}.json.zip").resolve()
    if archive_path.parent != root or not archive_path.is_file():
        indexed_payload, index_path = _indexed_historical_replay_contract_payload(normalized_id)
        if indexed_payload is not None:
            return _historical_replay_contract_from_payload(
                indexed_payload,
                normalized_id,
                detail_path=index_path,
                detail_source="backup_contract_index",
            )
        embedded_payload = _embedded_tournament_replay_contract_payload(normalized_id)
        if embedded_payload is not None:
            return _historical_replay_contract_from_payload(
                embedded_payload,
                normalized_id,
                detail_path=AI_TOURNAMENT_FILE,
                detail_source="tournament_embedded_contract",
            )
        return {
            "ok": False,
            "status": "detail_archive_missing",
            "replay_id": normalized_id,
            "detail_path": str(archive_path),
            "backup_index_path": str(index_path),
            "paper_only": True,
            "live_order_allowed": False,
        }
    max_uncompressed_bytes = 50 * 1024 * 1024
    try:
        with zipfile.ZipFile(archive_path) as archive:
            members = [
                item
                for item in archive.infolist()
                if not item.is_dir() and Path(item.filename).name == f"{normalized_id}.json"
            ]
            if len(members) != 1:
                raise ValueError("matching_detail_member_count")
            member = members[0]
            if member.file_size <= 0 or member.file_size > max_uncompressed_bytes:
                raise ValueError("detail_member_size_blocked")
            payload = json.loads(archive.read(member).decode("utf-8"))
    except (OSError, ValueError, UnicodeDecodeError, json.JSONDecodeError, zipfile.BadZipFile) as exc:
        return {
            "ok": False,
            "status": "detail_archive_invalid",
            "replay_id": normalized_id,
            "detail_path": str(archive_path),
            "error": str(exc),
            "paper_only": True,
            "live_order_allowed": False,
        }
    if not isinstance(payload, dict):
        return {
            "ok": False,
            "status": "detail_archive_invalid",
            "replay_id": normalized_id,
            "detail_path": str(archive_path),
            "paper_only": True,
            "live_order_allowed": False,
        }
    return _historical_replay_contract_from_payload(
        payload,
        normalized_id,
        detail_path=archive_path,
        detail_source="detail_archive",
    )


def compact_historical_replay_storage_history(
    *,
    apply: bool = False,
    confirm: str = "",
    data_dir: Path | None = None,
) -> dict[str, object]:
    data_dir = (data_dir or USER_DATA_ROOT).resolve()
    path = (data_dir / "historical_paper_replays.jsonl").resolve()
    if not path.exists() or path.parent != data_dir:
        return {"ok": False, "status": "not_found", "applied": False, "path": str(path)}
    temp_path = path.with_name(f"{path.name}.compact.tmp")
    original_bytes = path.stat().st_size
    output_bytes = 0
    valid_rows = 0
    compacted_rows = 0
    summary_rows = 0
    invalid_lines = 0
    full_detail_paths = 0
    should_apply = apply and str(confirm or "").strip().upper() == "COMPACT_REPLAYS"
    with _jsonl_io_lock(path):
        output_handle = temp_path.open("w", encoding="utf-8", newline="\n") if should_apply else None
        try:
            with path.open("r", encoding="utf-8", errors="ignore") as source:
                for line in source:
                    clean = line.strip().lstrip("\ufeff")
                    if not clean:
                        continue
                    try:
                        row = json.loads(clean)
                    except json.JSONDecodeError:
                        invalid_lines += 1
                        continue
                    if not isinstance(row, dict):
                        invalid_lines += 1
                        continue
                    valid_rows += 1
                    if str(row.get("type") or "") == "jsonl_compaction_summary":
                        stored = row
                        summary_rows += 1
                    else:
                        stored = _compact_historical_replay_storage_record(row)
                        compacted_rows += 1
                        full_detail_paths += int(bool(stored.get("trade_journal_path")))
                    output_line = json.dumps(stored, ensure_ascii=False, sort_keys=True) + "\n"
                    output_bytes += len(output_line.encode("utf-8"))
                    if output_handle is not None:
                        output_handle.write(output_line)
            if output_handle is not None:
                output_handle.flush()
                os.fsync(output_handle.fileno())
        finally:
            if output_handle is not None:
                output_handle.close()
        plan = {
            "ok": invalid_lines == 0,
            "status": "dry_run" if not should_apply else "prepared",
            "applied": False,
            "path": str(path),
            "valid_rows": valid_rows,
            "compacted_rows": compacted_rows,
            "summary_rows": summary_rows,
            "invalid_lines": invalid_lines,
            "full_detail_paths_preserved": full_detail_paths,
            "original_mb": round(original_bytes / (1024 * 1024), 2),
            "estimated_after_mb": round(output_bytes / (1024 * 1024), 2),
            "estimated_saved_mb": round(max(0, original_bytes - output_bytes) / (1024 * 1024), 2),
            "required_confirm": "COMPACT_REPLAYS",
            "safety": "Full trade journals remain at their recorded paths; this rewrites only the replay history index.",
        }
        if not apply:
            return plan
        if not should_apply:
            return {**plan, "ok": False, "status": "confirmation_required"}
        if invalid_lines:
            temp_path.unlink(missing_ok=True)
            return {**plan, "ok": False, "status": "invalid_rows_blocked"}
        timestamp = datetime.now(_zone("Asia/Seoul", 9)).strftime("%Y%m%d-%H%M%S")
        backup_dir = data_dir / "backups" / "jsonl_compaction"
        backup_dir.mkdir(parents=True, exist_ok=True)
        backup_path = backup_dir / f"{path.name}.{timestamp}.bak"
        shutil.copy2(path, backup_path)
        temp_path.replace(path)
        return {
            **plan,
            "status": "applied",
            "applied": True,
            "backup_path": str(backup_path),
            "after_mb": round(path.stat().st_size / (1024 * 1024), 2),
        }


def _historical_replay_data_coverage(
    data: dict[str, dict[str, object]],
    dates: list[str],
    requested_start_date: str,
    requested_end_date: str,
) -> dict[str, object]:
    """Describe the real portfolio horizon instead of trusting requested dates."""
    requested_start = datetime.fromisoformat(requested_start_date).date()
    requested_end = datetime.fromisoformat(requested_end_date).date()
    actual_start_date = dates[0] if dates else ""
    actual_end_date = dates[-1] if dates else ""
    actual_start = datetime.fromisoformat(actual_start_date).date() if actual_start_date else None
    actual_end = datetime.fromisoformat(actual_end_date).date() if actual_end_date else None
    requested_days = max(1, (requested_end - requested_start).days)
    actual_days = max(0, (actual_end - actual_start).days) if actual_start and actual_end else 0
    boundary_tolerance_days = 7

    symbols: dict[str, dict[str, object]] = {}
    full_boundary_symbol_count = 0
    for symbol, series in data.items():
        rows = series.get("rows") if isinstance(series.get("rows"), list) else []
        row_dates = sorted(
            str(row.get("date") or "")
            for row in rows
            if isinstance(row, dict) and str(row.get("date") or "")
        )
        first_date = row_dates[0] if row_dates else ""
        last_date = row_dates[-1] if row_dates else ""
        first_day = datetime.fromisoformat(first_date).date() if first_date else None
        last_day = datetime.fromisoformat(last_date).date() if last_date else None
        starts_near_boundary = bool(
            first_day and first_day <= requested_start + timedelta(days=boundary_tolerance_days)
        )
        ends_near_boundary = bool(
            last_day and last_day >= requested_end - timedelta(days=boundary_tolerance_days)
        )
        full_boundary = starts_near_boundary and ends_near_boundary
        if full_boundary:
            full_boundary_symbol_count += 1
        symbols[symbol] = {
            "first_date": first_date or None,
            "last_date": last_date or None,
            "row_count": len(row_dates),
            "starts_near_requested_boundary": starts_near_boundary,
            "ends_near_requested_boundary": ends_near_boundary,
            "full_requested_boundary_coverage": full_boundary,
            "provider": series.get("provider"),
            "source": series.get("source"),
        }

    portfolio_boundary_coverage = bool(
        actual_start
        and actual_end
        and actual_start <= requested_start + timedelta(days=boundary_tolerance_days)
        and actual_end >= requested_end - timedelta(days=boundary_tolerance_days)
    )
    return {
        "schema": "codexstock_replay_data_coverage_v1",
        "requested_start_date": requested_start_date,
        "requested_end_date": requested_end_date,
        "actual_start_date": actual_start_date or None,
        "actual_end_date": actual_end_date or None,
        "requested_horizon_years": round(requested_days / 365.25, 6),
        "actual_horizon_years": round(actual_days / 365.25, 6),
        "calendar_coverage_pct": round(min(100.0, actual_days / requested_days * 100.0), 4),
        "boundary_tolerance_calendar_days": boundary_tolerance_days,
        "portfolio_boundary_coverage_passed": portfolio_boundary_coverage,
        "symbol_count": len(symbols),
        "full_boundary_symbol_count": full_boundary_symbol_count,
        "symbols": symbols,
        "policy": "CAGR uses actual portfolio boundary dates; requested dates are labels only.",
    }


def _paper_us_regulatory_fee_contract(
    date_key: str,
    *,
    quantity: float = 0.0,
    gross_krw: float = 0.0,
    usdkrw_rate: float = 0.0,
) -> dict[str, object]:
    """Return independently reproducible US sell-side regulatory costs."""
    normalized_date = str(date_key or "")[:10]
    sec_row = PAPER_US_SEC_FEE_SCHEDULE[0]
    for row in PAPER_US_SEC_FEE_SCHEDULE:
        if str(row.get("effective_from") or "") <= normalized_date:
            sec_row = row
        else:
            break
    taf_row = PAPER_US_FINRA_TAF_SCHEDULE[0]
    for row in PAPER_US_FINRA_TAF_SCHEDULE:
        if str(row.get("effective_from") or "") <= normalized_date:
            taf_row = row
        else:
            break
    sec_fee_bps = _number(sec_row.get("fee_bps"))
    taf_per_share_usd = _number(taf_row.get("per_share_usd"))
    taf_max_usd = _number(taf_row.get("max_per_trade_usd"))
    sec_fee_krw = max(0.0, gross_krw) * sec_fee_bps / 10_000.0
    taf_usd = min(
        max(0.0, quantity) * taf_per_share_usd,
        taf_max_usd,
    )
    taf_krw = taf_usd * max(0.0, usdkrw_rate)
    return {
        "policy_version": PAPER_US_REGULATORY_POLICY_VERSION,
        "trade_date": normalized_date,
        "sec_fee_bps": sec_fee_bps,
        "sec_fee_krw": sec_fee_krw,
        "sec_evidence": sec_row.get("evidence"),
        "finra_taf_per_share_usd": taf_per_share_usd,
        "finra_taf_max_usd": taf_max_usd,
        "finra_taf_usd": taf_usd,
        "finra_taf_krw": taf_krw,
        "finra_evidence": taf_row.get("evidence"),
        "official_schedule_coverage": bool(
            sec_row.get("evidence") != "historical_fallback_proxy"
            and taf_row.get("evidence") != "pre_2024_fallback_proxy"
        ),
    }


def _replay_transaction_cost_audit(
    actions: list[dict[str, object]],
    cost_model: dict[str, object],
    recorded_totals: dict[str, object],
    *,
    estimated_open_liquidation_cost: float = 0.0,
) -> dict[str, object]:
    """Reconcile every action cost before a net return can become official."""
    commission_rate = _number(cost_model.get("commission_bps_each_side")) / 10_000.0
    slippage_rate = _number(cost_model.get("slippage_bps_each_side")) / 10_000.0
    kr_sell_tax_rate = _number(cost_model.get("kr_sell_tax_bps")) / 10_000.0
    fx_spread_rate = _number(cost_model.get("fx_conversion_spread_bps_each_side")) / 10_000.0
    has_us_actions = any(
        str(action.get("market") or ("KR" if str(action.get("symbol") or "").isdigit() else "US")).upper()
        == "US"
        for action in actions
        if isinstance(action, dict)
    )
    blockers: list[str] = []
    if cost_model.get("enabled") is not True:
        blockers.append("cost_model_not_enabled")
    if commission_rate <= 0:
        blockers.append("commission_rate_missing")
    if slippage_rate <= 0:
        blockers.append("slippage_rate_missing")
    if kr_sell_tax_rate <= 0:
        blockers.append("kr_sell_tax_rate_missing")
    if has_us_actions and fx_spread_rate <= 0:
        blockers.append("us_fx_conversion_spread_missing")
    if has_us_actions and cost_model.get("us_regulatory_fee_policy_version") != PAPER_US_REGULATORY_POLICY_VERSION:
        blockers.append("us_regulatory_fee_policy_missing_or_stale")
    if not actions:
        blockers.append("no_trade_actions_for_cost_audit")

    ledger_commission = 0.0
    ledger_slippage = 0.0
    ledger_sell_tax = 0.0
    ledger_us_sec_fee = 0.0
    ledger_us_finra_taf = 0.0
    ledger_fx_conversion_cost = 0.0
    action_blockers: list[dict[str, object]] = []
    hash_rows: list[dict[str, object]] = []
    for index, action in enumerate(actions, start=1):
        side = str(action.get("side") or "").strip().upper()
        symbol = str(action.get("symbol") or "").strip().upper()
        quantity = _number(action.get("quantity"))
        notional = _number(action.get("notional"))
        market_price = _number(action.get("market_price"))
        execution_price = _number(action.get("execution_price"))
        commission = _number(action.get("commission"))
        slippage_cost = _number(action.get("slippage_cost"))
        sell_tax = _number(action.get("sell_tax"))
        market = str(action.get("market") or ("KR" if symbol.isdigit() else "US")).strip().upper()
        usdkrw_rate = _number(action.get("usdkrw_rate"))
        us_sec_fee = _number(action.get("us_sec_fee"))
        us_finra_taf = _number(action.get("us_finra_taf"))
        fx_conversion_cost = _number(action.get("fx_conversion_cost"))
        row_blockers: list[str] = []
        if side not in {"BUY", "SELL"}:
            row_blockers.append("invalid_side")
        if not symbol or quantity <= 0 or notional <= 0 or market_price <= 0 or execution_price <= 0:
            row_blockers.append("invalid_action_notional_or_price")
        expected_commission = notional * commission_rate
        expected_slippage = quantity * abs(execution_price - market_price)
        expected_tax = notional * kr_sell_tax_rate if side == "SELL" and market == "KR" else 0.0
        expected_fx_conversion = notional * fx_spread_rate if market == "US" else 0.0
        regulatory = (
            _paper_us_regulatory_fee_contract(
                str(action.get("date") or ""),
                quantity=quantity,
                gross_krw=notional,
                usdkrw_rate=usdkrw_rate,
            )
            if side == "SELL" and market == "US"
            else {}
        )
        expected_us_sec_fee = _number(regulatory.get("sec_fee_krw"))
        expected_us_finra_taf = _number(regulatory.get("finra_taf_krw"))
        money_tolerance = max(0.05, notional * 0.000001)
        slippage_tolerance = max(0.05, expected_slippage * 0.001, quantity * 0.00011)
        if abs(commission - expected_commission) > money_tolerance:
            row_blockers.append("commission_mismatch")
        if abs(slippage_cost - expected_slippage) > slippage_tolerance:
            row_blockers.append("slippage_mismatch")
        if abs(sell_tax - expected_tax) > money_tolerance:
            row_blockers.append("sell_tax_mismatch")
        if market == "US" and usdkrw_rate <= 0:
            row_blockers.append("usdkrw_rate_missing_for_us_costs")
        if abs(fx_conversion_cost - expected_fx_conversion) > money_tolerance:
            row_blockers.append("fx_conversion_cost_mismatch")
        if abs(us_sec_fee - expected_us_sec_fee) > money_tolerance:
            row_blockers.append("us_sec_fee_mismatch")
        if abs(us_finra_taf - expected_us_finra_taf) > money_tolerance:
            row_blockers.append("us_finra_taf_mismatch")
        if side == "BUY":
            expected_cash_cost = notional + commission + expected_fx_conversion
            if abs(_number(action.get("cash_cost")) - expected_cash_cost) > money_tolerance:
                row_blockers.append("buy_cash_cost_mismatch")
        elif side == "SELL":
            expected_net_proceeds = (
                notional
                - commission
                - sell_tax
                - expected_us_sec_fee
                - expected_us_finra_taf
                - expected_fx_conversion
            )
            if abs(_number(action.get("net_proceeds")) - expected_net_proceeds) > money_tolerance:
                row_blockers.append("sell_net_proceeds_mismatch")
        ledger_commission += commission
        ledger_slippage += slippage_cost
        ledger_sell_tax += sell_tax
        ledger_us_sec_fee += us_sec_fee
        ledger_us_finra_taf += us_finra_taf
        ledger_fx_conversion_cost += fx_conversion_cost
        hash_rows.append(
            {
                "side": side,
                "symbol": symbol,
                "date": action.get("date"),
                "quantity": action.get("quantity"),
                "notional": action.get("notional"),
                "commission": action.get("commission"),
                "slippage_cost": action.get("slippage_cost"),
                "sell_tax": action.get("sell_tax"),
                "market": market,
                "usdkrw_rate": action.get("usdkrw_rate"),
                "us_sec_fee": action.get("us_sec_fee"),
                "us_finra_taf": action.get("us_finra_taf"),
                "fx_conversion_cost": action.get("fx_conversion_cost"),
            }
        )
        if row_blockers:
            action_blockers.append({"index": index, "symbol": symbol, "side": side, "blockers": row_blockers})

    recorded_commission = _number(recorded_totals.get("total_commission"))
    recorded_slippage = _number(recorded_totals.get("total_slippage_cost"))
    recorded_sell_tax = _number(recorded_totals.get("total_sell_tax"))
    recorded_us_sec_fee = _number(recorded_totals.get("total_us_sec_fee"))
    recorded_us_finra_taf = _number(recorded_totals.get("total_us_finra_taf"))
    recorded_fx_conversion_cost = _number(recorded_totals.get("total_fx_conversion_cost"))
    recorded_total = _number(recorded_totals.get("total_transaction_cost"))
    aggregate_tolerance = max(0.05, len(actions) * 0.011, recorded_total * 0.000001)
    if abs(recorded_commission - ledger_commission) > aggregate_tolerance:
        blockers.append("aggregate_commission_mismatch")
    if abs(recorded_slippage - ledger_slippage) > aggregate_tolerance:
        blockers.append("aggregate_slippage_mismatch")
    if abs(recorded_sell_tax - ledger_sell_tax) > aggregate_tolerance:
        blockers.append("aggregate_sell_tax_mismatch")
    if abs(recorded_us_sec_fee - ledger_us_sec_fee) > aggregate_tolerance:
        blockers.append("aggregate_us_sec_fee_mismatch")
    if abs(recorded_us_finra_taf - ledger_us_finra_taf) > aggregate_tolerance:
        blockers.append("aggregate_us_finra_taf_mismatch")
    if abs(recorded_fx_conversion_cost - ledger_fx_conversion_cost) > aggregate_tolerance:
        blockers.append("aggregate_fx_conversion_cost_mismatch")
    ledger_total = (
        ledger_commission
        + ledger_slippage
        + ledger_sell_tax
        + ledger_us_sec_fee
        + ledger_us_finra_taf
        + ledger_fx_conversion_cost
    )
    if abs(recorded_total - ledger_total) > aggregate_tolerance:
        blockers.append("aggregate_transaction_cost_mismatch")
    if action_blockers:
        blockers.append("action_cost_ledger_mismatch")
    unique_blockers = list(dict.fromkeys(blockers))
    passed = not unique_blockers
    return {
        "schema": "codexstock_replay_transaction_cost_audit_v1",
        "model_version": PAPER_COST_POLICY_VERSION,
        "passed": passed,
        "status": "passed" if passed else "blocked",
        "applied_action_count": len(actions),
        "ledger_commission": round(ledger_commission, 2),
        "ledger_slippage_cost": round(ledger_slippage, 2),
        "ledger_sell_tax": round(ledger_sell_tax, 2),
        "ledger_us_sec_fee": round(ledger_us_sec_fee, 2),
        "ledger_us_finra_taf": round(ledger_us_finra_taf, 2),
        "ledger_fx_conversion_cost": round(ledger_fx_conversion_cost, 2),
        "ledger_total_transaction_cost": round(ledger_total, 2),
        "recorded_total_transaction_cost": round(recorded_total, 2),
        "estimated_open_liquidation_cost": round(max(0.0, estimated_open_liquidation_cost), 2),
        "net_liquidation_cost_basis": True,
        "cost_model": dict(cost_model),
        "ledger_hash": hashlib.sha256(
            json.dumps(hash_rows, ensure_ascii=True, sort_keys=True).encode("utf-8")
        ).hexdigest(),
        "blockers": unique_blockers,
        "action_blockers": action_blockers[:20],
        "policy": "Every action cost and aggregate must reconcile before net performance is official.",
    }


def _official_usdkrw_daily_rows(start_date: str, end_date: str) -> tuple[list[dict[str, object]], dict[str, object]]:
    """Fetch official daily USD/KRW in yearly chunks without crossing the requested end date."""
    try:
        start = datetime.fromisoformat(start_date).date()
        end = datetime.fromisoformat(end_date).date()
    except ValueError:
        return [], {"ok": False, "error": "invalid_date", "future_value_used": False}
    rows_by_date: dict[str, dict[str, object]] = {}
    errors: list[dict[str, object]] = []
    requests = 0
    configured = False
    for year in range(start.year, end.year + 1):
        chunk_start = max(start, date(year, 1, 1))
        chunk_end = min(end, date(year, 12, 31))
        requests += 1
        try:
            result = INTEGRATIONS.ecos_series(
                stat_code="731Y001",
                cycle="D",
                start=chunk_start.strftime("%Y%m%d"),
                end=chunk_end.strftime("%Y%m%d"),
                item_code1="0000001",
                limit=1000,
            )
        except Exception as exc:
            errors.append({"year": year, "error": f"{type(exc).__name__}: {exc}"[:300]})
            continue
        configured = configured or bool(result.get("configured"))
        if result.get("ok") is not True:
            errors.append({"year": year, "error": str(result.get("message") or "ECOS unavailable")[:300]})
            continue
        for item in result.get("rows", []):
            if not isinstance(item, dict):
                continue
            raw_date = str(item.get("time") or "")
            value = _number(item.get("value"))
            try:
                observed = datetime.strptime(raw_date, "%Y%m%d").date()
            except ValueError:
                continue
            if observed < start or observed > end or value <= 0:
                continue
            date_key = observed.isoformat()
            rows_by_date[date_key] = {
                "date": date_key,
                "close": value,
                "adjusted_close": value,
                "fx_source": "BOK ECOS 731Y001/0000001",
                "official": True,
                "future_value_used": False,
            }
    rows = [rows_by_date[key] for key in sorted(rows_by_date)]
    return rows, {
        "ok": bool(rows),
        "configured": configured,
        "source": "BOK ECOS 731Y001/0000001",
        "start_date": start_date,
        "end_date": end_date,
        "request_count": requests,
        "row_count": len(rows),
        "errors": errors,
        "future_value_used": False,
    }


def _replay_usdkrw_rows(start_date: str, end_date: str, *, min_rows: int) -> dict[str, object]:
    """Combine Yahoo FX with official ECOS only where the requested boundary is missing."""
    errors: list[dict[str, object]] = []
    yahoo_rows: list[dict[str, object]] = []
    try:
        yahoo = _fetch_yahoo_chart_range("KRW=X", start_date, end_date, timeout=7.0, min_rows=min_rows)
        yahoo_rows = [
            {
                **row,
                "fx_source": "Yahoo chart:KRW=X",
                "official": False,
                "future_value_used": False,
            }
            for row in yahoo.get("rows", [])
            if isinstance(row, dict) and _number(row.get("adjusted_close") or row.get("close")) > 0
        ]
    except Exception as exc:
        errors.append({"source": "Yahoo chart:KRW=X", "error": f"{type(exc).__name__}: {exc}"[:300]})
    yahoo_rows.sort(key=lambda row: str(row.get("date") or ""))
    requested_start = datetime.fromisoformat(start_date).date()
    requested_end = datetime.fromisoformat(end_date).date()
    gaps: list[tuple[date, date]] = []
    if not yahoo_rows:
        gaps.append((requested_start - timedelta(days=14), requested_end))
    else:
        first = datetime.fromisoformat(str(yahoo_rows[0].get("date") or "")[:10]).date()
        last = datetime.fromisoformat(str(yahoo_rows[-1].get("date") or "")[:10]).date()
        if first > requested_start + timedelta(days=7):
            gaps.append((requested_start - timedelta(days=14), min(requested_end, first - timedelta(days=1))))
        if last < requested_end - timedelta(days=7):
            gaps.append((max(requested_start, last + timedelta(days=1)), requested_end))
    official_rows: list[dict[str, object]] = []
    official_evidence: list[dict[str, object]] = []
    for gap_start, gap_end in gaps:
        if gap_start > gap_end:
            continue
        rows, evidence = _official_usdkrw_daily_rows(gap_start.isoformat(), gap_end.isoformat())
        official_rows.extend(rows)
        official_evidence.append(evidence)
        errors.extend(
            {"source": evidence.get("source"), **row}
            for row in evidence.get("errors", [])
            if isinstance(row, dict)
        )
    merged: dict[str, dict[str, object]] = {
        str(row.get("date") or "")[:10]: dict(row)
        for row in official_rows
        if str(row.get("date") or "")[:10]
    }
    for row in yahoo_rows:
        date_key = str(row.get("date") or "")[:10]
        if date_key:
            merged[date_key] = dict(row)
    rows = [merged[key] for key in sorted(merged)]
    return {
        "rows": rows,
        "evidence": {
            "schema": "codexstock_replay_fx_source_evidence_v1",
            "requested_start_date": start_date,
            "requested_end_date": end_date,
            "yahoo_row_count": len(yahoo_rows),
            "official_row_count": len(official_rows),
            "merged_row_count": len(rows),
            "official_gap_count": len(gaps),
            "official_evidence": official_evidence,
            "sources": sorted({str(row.get("fx_source") or "") for row in rows if row.get("fx_source")}),
            "errors": errors,
            "future_value_used": False,
            "fill_policy": "latest_rate_at_or_before_price_date_only",
        },
    }


def _historical_replay_data_bundle_digest(
    series_by_symbol: dict[str, object],
    fx_rows: list[dict[str, object]],
) -> str:
    digest = hashlib.sha256(HISTORICAL_REPLAY_DATA_BUNDLE_SCHEMA.encode("ascii"))
    for symbol in sorted(series_by_symbol):
        payload = series_by_symbol.get(symbol)
        series = payload if isinstance(payload, dict) else {}
        digest.update(f"\n{symbol}|{series.get('source', '')}|{series.get('provider', '')}".encode("utf-8"))
        rows = series.get("rows") if isinstance(series.get("rows"), list) else []
        for row in sorted(
            (item for item in rows if isinstance(item, dict)),
            key=lambda item: str(item.get("date") or ""),
        ):
            digest.update(
                (
                    f"\n{str(row.get('date') or '')[:10]}|{row.get('close', '')}|"
                    f"{row.get('adjclose', '')}|{row.get('volume', '')}"
                ).encode("utf-8")
            )
    digest.update(b"\nFX")
    for row in sorted(fx_rows, key=lambda item: str(item.get("date") or "")):
        digest.update(
            f"\n{str(row.get('date') or '')[:10]}|{row.get('close', '')}|{row.get('adjclose', '')}".encode("utf-8")
        )
    return f"sha256:{digest.hexdigest()}"


def _replay_data_bundle_slice_manifest_hash(evidence: dict[str, object]) -> str:
    fields = (
        "schema",
        "bundle_content_hash",
        "slice_content_hash",
        "bundle_period",
        "requested_period",
        "symbols",
        "symbol_count",
        "symbol_row_counts",
        "symbol_row_bounds",
        "symbol_calendar_adjacency_roots",
        "symbol_calendar_pair_counts",
        "fx_row_count",
        "excluded_before_row_count",
        "excluded_future_row_count",
        "future_rows_excluded_before_strategy",
        "no_rows_outside_requested_period",
        "source_fetch_reused",
        "live_order_allowed",
    )
    payload = {field: evidence.get(field) for field in fields}
    encoded = json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return f"sha256:{hashlib.sha256(encoded).hexdigest()}"


def _build_historical_replay_data_bundle(
    symbols: list[str],
    start_date: str,
    end_date: str,
    *,
    allow_simulated_fallback: bool = False,
    min_bars: int = 40,
) -> dict[str, object]:
    """Load one immutable market-data envelope for a multi-replay execution."""
    start_date = _parse_replay_date(start_date, "2018-01-01").date().isoformat()
    end_date = _parse_replay_date(end_date, today_kst()).date().isoformat()
    if start_date > end_date:
        raise ValueError("replay data bundle start_date must not exceed end_date")
    cleaned: list[str] = []
    for symbol in symbols:
        normalized = str(symbol or "").strip().upper()
        if normalized.isdigit():
            normalized = normalized.zfill(6)
        if normalized and normalized not in cleaned:
            cleaned.append(normalized)
    cleaned = cleaned[:80]
    if not cleaned:
        raise ValueError("replay data bundle requires at least one symbol")
    min_bars = max(5, min(int(min_bars or 40), 40))
    errors: list[dict[str, object]] = []
    fx_rows: list[dict[str, object]] = []
    fx_evidence: dict[str, object] = {}
    if any(not symbol.isdigit() for symbol in cleaned):
        fx_payload = _replay_usdkrw_rows(start_date, end_date, min_rows=min_bars)
        fx_rows = [dict(row) for row in fx_payload.get("rows", []) if isinstance(row, dict)]
        fx_evidence = fx_payload.get("evidence") if isinstance(fx_payload.get("evidence"), dict) else {}
        if not fx_rows:
            errors.append({"symbol": "USD/KRW", "error": "verified FX rows are unavailable"})
    series_by_symbol: dict[str, object] = {}
    for symbol in cleaned:
        try:
            series = _historical_close_rows(
                symbol,
                start_date,
                end_date,
                allow_simulated_fallback=allow_simulated_fallback,
                min_rows=min_bars,
            )
        except Exception as exc:
            errors.append({"symbol": symbol, "error": str(exc)[:500]})
            continue
        rows = [
            dict(row)
            for row in series.get("rows", [])
            if isinstance(row, dict)
            and float(row.get("close", 0) or 0) > 0
            and start_date <= str(row.get("date") or "")[:10] <= end_date
        ]
        rows.sort(key=lambda row: str(row.get("date") or ""))
        if not rows:
            errors.append({"symbol": symbol, "error": "market data rows are empty"})
            continue
        series_by_symbol[symbol] = {
            **series,
            "rows": rows,
            "errors": list(series.get("errors", [])) if isinstance(series.get("errors"), list) else [],
        }
    missing_symbols = [symbol for symbol in cleaned if symbol not in series_by_symbol]
    if missing_symbols:
        raise ValueError(
            "replay data bundle is incomplete: "
            + ", ".join(missing_symbols)
            + (f" / errors={errors[-5:]}" if errors else "")
        )
    content_hash = _historical_replay_data_bundle_digest(series_by_symbol, fx_rows)
    return {
        "schema": HISTORICAL_REPLAY_DATA_BUNDLE_SCHEMA,
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "start_date": start_date,
        "end_date": end_date,
        "symbols": cleaned,
        "allow_simulated_fallback": bool(allow_simulated_fallback),
        "min_bars": min_bars,
        "series_by_symbol": series_by_symbol,
        "fx_rows": fx_rows,
        "fx_evidence": fx_evidence,
        "data_errors": errors,
        "content_hash": content_hash,
        "complete": True,
        "live_order_allowed": False,
        "persistence_policy": "execution_scoped_memory_only",
        "slice_policy": "slice_to_requested_dates_before_price_normalization_and_strategy_execution",
    }


def _slice_historical_replay_data_bundle(
    bundle: dict[str, object],
    symbols: list[str],
    start_date: str,
    end_date: str,
    *,
    allow_simulated_fallback: bool,
) -> tuple[dict[str, dict[str, object]], list[dict[str, object]], list[dict[str, object]], dict[str, object]]:
    if bundle.get("schema") != HISTORICAL_REPLAY_DATA_BUNDLE_SCHEMA:
        raise ValueError("invalid replay data bundle schema")
    bundle_start = str(bundle.get("start_date") or "")
    bundle_end = str(bundle.get("end_date") or "")
    if not bundle_start or not bundle_end or bundle_start > start_date or bundle_end < end_date:
        raise ValueError("replay data bundle does not cover requested period")
    if bool(bundle.get("allow_simulated_fallback")) != bool(allow_simulated_fallback):
        raise ValueError("replay data bundle simulation policy mismatch")
    content_hash = str(bundle.get("content_hash") or "")
    if not content_hash.startswith("sha256:"):
        raise ValueError("replay data bundle content hash is missing")
    source_map = bundle.get("series_by_symbol") if isinstance(bundle.get("series_by_symbol"), dict) else {}
    fx_source = bundle.get("fx_rows") if isinstance(bundle.get("fx_rows"), list) else []
    if bundle.get("_integrity_verified_hash") != content_hash:
        actual_hash = _historical_replay_data_bundle_digest(source_map, fx_source)
        if actual_hash != content_hash:
            raise ValueError("replay data bundle content hash mismatch")
        bundle["_integrity_verified_hash"] = content_hash
    missing = [symbol for symbol in symbols if symbol not in source_map]
    if missing:
        raise ValueError("replay data bundle symbols missing: " + ", ".join(missing))
    sliced: dict[str, dict[str, object]] = {}
    excluded_before = 0
    excluded_after = 0
    row_counts: dict[str, int] = {}
    row_bounds: dict[str, dict[str, object]] = {}
    calendar_roots: dict[str, str] = {}
    calendar_pair_counts: dict[str, int] = {}
    for symbol in symbols:
        source = source_map.get(symbol)
        series = source if isinstance(source, dict) else {}
        source_rows = series.get("rows") if isinstance(series.get("rows"), list) else []
        rows: list[dict[str, object]] = []
        for source_row in source_rows:
            if not isinstance(source_row, dict):
                continue
            date_key = str(source_row.get("date") or "")[:10]
            if date_key < start_date:
                excluded_before += 1
                continue
            if date_key > end_date:
                excluded_after += 1
                continue
            if float(source_row.get("close", 0) or 0) > 0:
                rows.append(dict(source_row))
        rows.sort(key=lambda row: str(row.get("date") or ""))
        if not rows:
            raise ValueError(f"replay data bundle has no rows for {symbol} in requested period")
        sliced[symbol] = {**series, "rows": rows}
        row_counts[symbol] = len(rows)
        row_bounds[symbol] = {
            "first_date": str(rows[0].get("date") or "")[:10],
            "last_date": str(rows[-1].get("date") or "")[:10],
            "row_count": len(rows),
        }
        trading_dates = [str(row.get("date") or "")[:10] for row in rows]
        calendar_roots[symbol] = calendar_adjacency_root(symbol, trading_dates)
        calendar_pair_counts[symbol] = max(0, len(trading_dates) - 1)
    fx_rows = [
        dict(row)
        for row in fx_source
        if isinstance(row, dict) and start_date <= str(row.get("date") or "")[:10] <= end_date
    ]
    prior_fx_rows = [
        row for row in fx_source
        if isinstance(row, dict) and str(row.get("date") or "")[:10] < start_date
    ]
    if prior_fx_rows:
        fx_rows.insert(0, dict(max(prior_fx_rows, key=lambda row: str(row.get("date") or ""))))
    errors = [dict(row) for row in bundle.get("data_errors", []) if isinstance(row, dict)]
    slice_content_hash = _historical_replay_data_bundle_digest(sliced, fx_rows)
    evidence = {
        "schema": HISTORICAL_REPLAY_DATA_BUNDLE_SLICE_EVIDENCE_SCHEMA,
        "used": True,
        "passed": True,
        "content_hash": content_hash,
        "bundle_content_hash": content_hash,
        "slice_content_hash": slice_content_hash,
        "bundle_period": {"start_date": bundle_start, "end_date": bundle_end},
        "requested_period": {"start_date": start_date, "end_date": end_date},
        "symbols": list(symbols),
        "symbol_count": len(symbols),
        "symbol_row_counts": row_counts,
        "symbol_row_bounds": row_bounds,
        "symbol_calendar_adjacency_roots": calendar_roots,
        "symbol_calendar_pair_counts": calendar_pair_counts,
        "fx_row_count": len(fx_rows),
        "fx_source_evidence": dict(bundle.get("fx_evidence") or {}) if isinstance(bundle.get("fx_evidence"), dict) else {},
        "excluded_before_row_count": excluded_before,
        "excluded_future_row_count": excluded_after,
        "future_rows_excluded_before_strategy": True,
        "no_rows_outside_requested_period": all(
            start_date <= str(row.get("date") or "")[:10] <= end_date
            for series in sliced.values()
            for row in series.get("rows", [])
            if isinstance(row, dict)
        ),
        "source_fetch_reused": True,
        "live_order_allowed": False,
    }
    evidence["slice_manifest_hash"] = _replay_data_bundle_slice_manifest_hash(evidence)
    return sliced, fx_rows, errors, evidence


def run_historical_paper_replay(
    symbols: list[str],
    start_date: str,
    end_date: str,
    fast: int = 12,
    slow: int = 32,
    initial_cash: float = 100_000_000.0,
    allocation_pct: float = 25.0,
    max_positions: int = 4,
    source: str = "manual",
    strategy_mode: str = "ma_cross",
    stop_loss_pct: float | None = None,
    take_profit_pct: float | None = None,
    holding_limit_days: int | None = None,
    cycles_per_day: int = 24,
    allow_simulated_fallback: bool = False,
    min_bars: int = 40,
    persist_detail: bool = True,
    commission_bps: float = DEFAULT_PAPER_COMMISSION_BPS,
    slippage_bps: float = DEFAULT_PAPER_SLIPPAGE_BPS,
    kr_sell_tax_bps: float = DEFAULT_PAPER_KR_SELL_TAX_BPS,
    fx_conversion_spread_bps: float = DEFAULT_PAPER_FX_SPREAD_BPS,
    replay_data_bundle: dict[str, object] | None = None,
) -> dict[str, object]:
    if fast < 2 or slow <= fast:
        raise ValueError(MSG_RANGE)
    cleaned: list[str] = []
    for symbol in symbols:
        normalized = str(symbol or "").strip().upper()
        if not normalized:
            continue
        if normalized.isdigit():
            normalized = normalized.zfill(6)
        if normalized not in cleaned:
            cleaned.append(normalized)
    if not cleaned:
        cleaned = ["083450", "005930", "NVDA"]
    cleaned = cleaned[:80]
    start_date = _parse_replay_date(start_date, "2018-01-01").date().isoformat()
    end_date = _parse_replay_date(end_date, today_kst()).date().isoformat()
    cash = max(1_000_000.0, float(initial_cash or 100_000_000.0))
    allocation_pct = _clamp(float(allocation_pct or 25.0), 1.0, 100.0)
    max_positions = max(1, min(int(max_positions or 4), 20))
    strategy_profile = _replay_strategy_profile(strategy_mode)
    strategy_mode = str(strategy_profile.get("id", "ma_cross"))
    strategy_label = str(strategy_profile.get("label", strategy_mode))
    strategy_horizon = _replay_strategy_horizon(strategy_mode)
    minimum_history_bars = max(slow, int(strategy_profile.get("minimum_history_bars", slow) or slow))
    if stop_loss_pct is None:
        stop_loss_pct = float(strategy_profile.get("stop_loss_pct", 8.0) or 8.0)
    if take_profit_pct is None:
        take_profit_pct = float(strategy_profile.get("take_profit_pct", 0.0) or 0.0)
    if holding_limit_days is None:
        holding_limit_days = int(strategy_profile.get("holding_limit_days", 0) or 0)
    stop_loss_pct = _clamp(float(stop_loss_pct or 8.0), 1.0, 40.0)
    take_profit_pct = _clamp(float(take_profit_pct or 0.0), 0.0, 1000.0)
    holding_limit_days = max(0, min(int(holding_limit_days or 0), 3650))
    cycles_per_day = max(1, min(int(cycles_per_day or 24), 1440))
    min_bars = max(5, min(int(min_bars or 40), 40))
    commission_bps = _clamp(float(commission_bps or DEFAULT_PAPER_COMMISSION_BPS), DEFAULT_PAPER_COMMISSION_BPS, 1000.0)
    slippage_bps = _clamp(float(slippage_bps or DEFAULT_PAPER_SLIPPAGE_BPS), DEFAULT_PAPER_SLIPPAGE_BPS, 1000.0)
    kr_sell_tax_bps = _clamp(float(kr_sell_tax_bps or DEFAULT_PAPER_KR_SELL_TAX_BPS), DEFAULT_PAPER_KR_SELL_TAX_BPS, 1000.0)
    fx_conversion_spread_bps = _clamp(
        float(fx_conversion_spread_bps or DEFAULT_PAPER_FX_SPREAD_BPS),
        DEFAULT_PAPER_FX_SPREAD_BPS,
        1000.0,
    )
    commission_rate = commission_bps / 10_000.0
    slippage_rate = slippage_bps / 10_000.0
    kr_sell_tax_rate = kr_sell_tax_bps / 10_000.0
    fx_conversion_spread_rate = fx_conversion_spread_bps / 10_000.0

    if replay_data_bundle is None:
        replay_data_bundle = _build_historical_replay_data_bundle(
            cleaned,
            start_date,
            end_date,
            allow_simulated_fallback=allow_simulated_fallback,
            min_bars=min_bars,
        )

    symbol_meta = {
        symbol: {
            "symbol": symbol,
            "name": _quick_cached_symbol_name(symbol) or symbol,
            "market": "KR" if symbol.isdigit() else "US",
        }
        for symbol in cleaned
    }
    data: dict[str, dict[str, object]] = {}
    all_dates: set[str] = set()
    data_errors: list[dict[str, object]] = []
    fx_rows: list[dict[str, object]] = []
    bundled_series: dict[str, dict[str, object]] = {}
    replay_data_bundle_evidence: dict[str, object] = {
        "schema": HISTORICAL_REPLAY_DATA_BUNDLE_SLICE_EVIDENCE_SCHEMA,
        "used": False,
        "passed": False,
        "source_fetch_reused": False,
    }
    if isinstance(replay_data_bundle, dict):
        bundled_series, fx_rows, bundle_errors, replay_data_bundle_evidence = _slice_historical_replay_data_bundle(
            replay_data_bundle,
            cleaned,
            start_date,
            end_date,
            allow_simulated_fallback=allow_simulated_fallback,
        )
        data_errors.extend(bundle_errors)
    elif any(not symbol.isdigit() for symbol in cleaned):
        fx_payload = _replay_usdkrw_rows(start_date, end_date, min_rows=min_bars)
        fx_rows = [dict(row) for row in fx_payload.get("rows", []) if isinstance(row, dict)]
        if not fx_rows:
            evidence = fx_payload.get("evidence") if isinstance(fx_payload.get("evidence"), dict) else {}
            data_errors.append({"symbol": "USD/KRW", "error": f"verified FX rows unavailable: {evidence.get('errors', [])}"[:500]})
    market_data_snapshot_hash = str(
        replay_data_bundle_evidence.get("slice_content_hash") or ""
    )
    for symbol in cleaned:
        try:
            series = bundled_series.get(symbol)
            if series is None:
                series = _historical_close_rows(
                    symbol,
                    start_date,
                    end_date,
                    allow_simulated_fallback=allow_simulated_fallback,
                    min_rows=min_bars,
                )
        except Exception as exc:
            data_errors.append({"symbol": symbol, "error": str(exc)})
            continue
        source_rows = [
            row
            for row in series.get("rows", [])
            if isinstance(row, dict)
            and float(row.get("close", 0) or 0) > 0
            and start_date <= str(row.get("date") or "")[:10] <= end_date
        ]
        rows, price_contract = _normalize_replay_price_rows(
            symbol,
            source_rows,
            provider=str(series.get("provider") or "-"),
            fx_rows=fx_rows,
            listing_evidence=(
                series.get("listing_evidence")
                if isinstance(series.get("listing_evidence"), dict)
                else {}
            ),
        )
        if not rows:
            data_errors.append({"symbol": symbol, "error": "실데이터 일봉 행이 비어 있습니다."})
            continue
        data[symbol] = {
            "source": series.get("source", "-"),
            "provider": series.get("provider", "-"),
            "yahoo_symbol": series.get("yahoo_symbol", ""),
            "errors": series.get("errors", []),
            "price_contract": price_contract,
            "rows": rows,
            "by_date": {str(row["date"]): float(row["close"]) for row in rows},
            "fx_by_date": {
                str(row["date"]): _number(row.get("usdkrw_rate"))
                for row in rows
                if _number(row.get("usdkrw_rate")) > 0
            },
        }
        all_dates.update(str(row["date"]) for row in rows)
    if not data:
        raise ValueError("과거장 훈련에 사용할 실데이터 종목이 없습니다. " + " / ".join(str(item.get("error", "")) for item in data_errors[-5:]))
    dates = sorted(date_key for date_key in all_dates if start_date <= date_key <= end_date)
    if len(dates) < slow + 5:
        raise ValueError("훈련 구간의 거래일 데이터가 부족합니다.")

    symbol_trading_dates = {
        symbol: [str(row.get("date") or "")[:10] for row in series.get("rows", [])]
        for symbol, series in data.items()
    }
    symbol_date_indexes = {
        symbol: {date_value: index for index, date_value in enumerate(trading_dates)}
        for symbol, trading_dates in symbol_trading_dates.items()
    }
    histories: dict[str, list[float]] = {symbol: [] for symbol in data}
    history_dates: dict[str, list[str]] = {symbol: [] for symbol in data}
    last_prices: dict[str, float] = {}
    positions: dict[str, dict[str, object]] = {}
    trades: list[dict[str, object]] = []
    journal: list[dict[str, object]] = []
    equity_curve: list[float] = []
    peak = cash
    max_drawdown = 0.0
    total_commission = 0.0
    total_slippage_cost = 0.0
    total_sell_tax = 0.0
    total_us_sec_fee = 0.0
    total_us_finra_taf = 0.0
    total_fx_conversion_cost = 0.0
    total_turnover = 0.0
    last_fx_rates: dict[str, float] = {}
    last_price_dates: dict[str, str] = {}

    def estimated_exit_net(
        symbol: str,
        market_price: float,
        quantity: float,
        *,
        valuation_date: str = "",
        usdkrw_rate: float = 0.0,
    ) -> float:
        execution_price = market_price * (1.0 - slippage_rate)
        gross = max(0.0, execution_price * quantity)
        commission = gross * commission_rate
        market = symbol_meta.get(symbol, {}).get("market")
        sell_tax = gross * kr_sell_tax_rate if market == "KR" else 0.0
        regulatory = (
            _paper_us_regulatory_fee_contract(
                valuation_date,
                quantity=quantity,
                gross_krw=gross,
                usdkrw_rate=usdkrw_rate,
            )
            if market == "US"
            else {}
        )
        fx_conversion_cost = gross * fx_conversion_spread_rate if market == "US" else 0.0
        return max(
            0.0,
            gross
            - commission
            - sell_tax
            - _number(regulatory.get("sec_fee_krw"))
            - _number(regulatory.get("finra_taf_krw"))
            - fx_conversion_cost,
        )

    def current_equity() -> float:
        value = cash
        for symbol, position in positions.items():
            price = last_prices.get(symbol, float(position.get("avg_cost", 0) or 0))
            value += estimated_exit_net(
                symbol,
                price,
                float(position.get("quantity", 0) or 0),
                valuation_date=last_price_dates.get(symbol, ""),
                usdkrw_rate=last_fx_rates.get(symbol, 0.0),
            )
        return value

    for index, date_key in enumerate(dates):
        day_actions: list[dict[str, object]] = []
        today_prices: dict[str, float] = {}
        today_fx_rates: dict[str, float] = {}
        for symbol, series in data.items():
            price = (series.get("by_date") or {}).get(date_key) if isinstance(series.get("by_date"), dict) else None
            if isinstance(price, (int, float)) and price > 0:
                current_price = float(price)
                today_prices[symbol] = current_price
                last_prices[symbol] = current_price
                last_price_dates[symbol] = date_key
                fx_value = _number((series.get("fx_by_date") or {}).get(date_key)) if isinstance(series.get("fx_by_date"), dict) else 0.0
                if fx_value > 0:
                    today_fx_rates[symbol] = fx_value
                    last_fx_rates[symbol] = fx_value
                histories[symbol].append(current_price)
                history_dates[symbol].append(date_key)

        # Decisions use the completed prior bar; today's close is execution-only evidence.
        for symbol in list(positions.keys()):
            history = histories.get(symbol, [])
            price = today_prices.get(symbol, 0.0)
            if len(history) < slow + 1 or price <= 0 or index <= 0:
                continue
            decision_history = history[:-1]
            decision_price = float(decision_history[-1])
            decision_date = history_dates[symbol][-2]
            fast_ma = _series_sma(decision_history, fast)
            slow_ma = _series_sma(decision_history, slow)
            position = positions[symbol]
            avg_cost = float(position.get("avg_cost", price) or price)
            decision_return_pct = ((decision_price / avg_cost) - 1.0) * 100.0 if avg_cost else 0.0
            pnl_pct = decision_return_pct
            peak_price = max(float(position.get("peak_price", avg_cost) or avg_cost), decision_price)
            position["peak_price"] = peak_price
            pullback_pct = ((decision_price / peak_price) - 1.0) * 100.0 if peak_price else 0.0
            holding_days = index - int(position.get("entry_index", index) or index)
            rsi14 = _series_rsi(decision_history, 14)
            momentum5 = _series_pct_change(decision_history, min(5, len(decision_history) - 1))
            momentum20 = _series_pct_change(decision_history, min(20, len(decision_history) - 1))
            momentum60 = _series_pct_change(decision_history, min(60, len(decision_history) - 1))
            momentum120 = _series_pct_change(decision_history, min(120, len(decision_history) - 1))
            ma50 = _series_sma(decision_history, 50)
            ma90 = _series_sma(decision_history, 90)
            ma180 = _series_sma(decision_history, 180)
            ma200 = _series_sma(decision_history, 200)
            prior = decision_history[:-1]
            prior_low20 = min(prior[-20:]) if len(prior) >= 20 else min(prior) if prior else decision_price
            sell_reason = ""
            trailing_trigger_pct: float | None = None
            if strategy_mode == "protected_ma":
                trailing_stop = max(3.0, stop_loss_pct * 0.65)
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"보호형 손절 -{stop_loss_pct:.1f}% 도달"
                elif take_profit_pct > 0 and pnl_pct >= take_profit_pct:
                    sell_reason = f"보호형 익절 +{take_profit_pct:.1f}% 도달"
                elif pnl_pct > 0 and pullback_pct <= -trailing_stop:
                    sell_reason = f"수익 보호 trailing {pullback_pct:.1f}%"
                    trailing_trigger_pct = -trailing_stop
                elif fast_ma < slow_ma:
                    sell_reason = "보호형 MA 추세 훼손"
            elif strategy_mode == "short_swing":
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"단기 스윙 손절 -{stop_loss_pct:.1f}%"
                elif take_profit_pct > 0 and pnl_pct >= take_profit_pct:
                    sell_reason = f"단기 스윙 익절 +{take_profit_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"보유 {holding_limit_days}일 제한"
                elif fast_ma < slow_ma:
                    sell_reason = "단기 스윙 추세 이탈"
            elif strategy_mode == "breakout":
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"돌파 실패 손절 -{stop_loss_pct:.1f}%"
                elif take_profit_pct > 0 and pnl_pct >= take_profit_pct:
                    sell_reason = f"돌파 전략 익절 +{take_profit_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"돌파 포지션 보유 {holding_limit_days}일 초과"
                elif decision_price < fast_ma:
                    sell_reason = "돌파 후 단기 추세선 이탈"
            elif strategy_mode == "intraday_theme_leader":
                soft_stop = min(1.2, stop_loss_pct * 0.75)
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"대장주 단타 하드 손절 -{stop_loss_pct:.1f}%"
                elif pnl_pct <= -soft_stop and (momentum5 < 0 or fast_ma < slow_ma):
                    sell_reason = f"대장주 단타 소프트 손절 확인 {pnl_pct:.1f}% / 수급 약화"
                elif take_profit_pct > 0 and pnl_pct >= take_profit_pct:
                    sell_reason = f"대장주 단타 익절 +{take_profit_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"단타 보유 {holding_limit_days}일 제한"
                elif fast_ma < slow_ma:
                    sell_reason = "대장주 단타 추세 훼손"
                elif rsi14 >= 82 and pullback_pct <= -1.0:
                    sell_reason = "과열 후 밀림 확인"
            elif strategy_mode == "intraday_momentum_breakout":
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"단타 고점 돌파 실패 손절 -{stop_loss_pct:.1f}%"
                elif take_profit_pct > 0 and pnl_pct >= take_profit_pct:
                    sell_reason = f"단타 고점 돌파 익절 +{take_profit_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"단타 고점 돌파 보유 {holding_limit_days}일 제한"
                elif decision_price < fast_ma or momentum5 < -1.0:
                    sell_reason = "단타 고점 돌파 모멘텀 이탈"
            elif strategy_mode == "intraday_pullback_reclaim":
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"단타 눌림목 회복 실패 손절 -{stop_loss_pct:.1f}%"
                elif take_profit_pct > 0 and pnl_pct >= take_profit_pct:
                    sell_reason = f"단타 눌림목 회복 익절 +{take_profit_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"단타 눌림목 보유 {holding_limit_days}일 제한"
                elif fast_ma < slow_ma or momentum5 < -2.0:
                    sell_reason = "단타 눌림목 추세 회복 실패"
            elif strategy_mode == "intraday_mean_reversion":
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"단타 과매도 반전 실패 손절 -{stop_loss_pct:.1f}%"
                elif take_profit_pct > 0 and pnl_pct >= take_profit_pct:
                    sell_reason = f"단타 과매도 반전 익절 +{take_profit_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"단타 과매도 반전 보유 {holding_limit_days}일 제한"
                elif rsi14 >= 65 or decision_price >= fast_ma * 1.03:
                    sell_reason = "단타 과매도 반전 목표 구간 도달"
            elif strategy_mode == "buffett_quality_proxy":
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"버핏형 장기 프록시 손실 제한 -{stop_loss_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"버핏형 장기 프록시 {holding_limit_days}일 재검증"
                elif decision_price < ma200 and momentum120 < 0:
                    sell_reason = "200일 장기 추세와 120일 모멘텀 동시 훼손"
            elif strategy_mode == "graham_defensive_proxy":
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"그레이엄형 방어 프록시 손실 제한 -{stop_loss_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"그레이엄형 방어 프록시 {holding_limit_days}일 재검증"
                elif decision_price < ma180 * 0.95 and momentum120 < -10:
                    sell_reason = "장기 가치회귀 프록시의 방어 추세 훼손"
            elif strategy_mode == "lynch_growth_proxy":
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"린치형 성장 프록시 손실 제한 -{stop_loss_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"린치형 성장 프록시 {holding_limit_days}일 재검증"
                elif decision_price < ma90 and momentum60 < 0:
                    sell_reason = "90일 성장 추세와 60일 모멘텀 동시 훼손"
            elif strategy_mode == "turtle_55":
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"터틀 55일 추세 손실 제한 -{stop_loss_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"터틀 55일 추세 {holding_limit_days}일 재검증"
                elif decision_price <= prior_low20:
                    sell_reason = "터틀 20일 청산 채널 이탈"
            elif strategy_mode == "minervini_proxy":
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"미너비니형 모멘텀 손실 제한 -{stop_loss_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"미너비니형 모멘텀 {holding_limit_days}일 재검증"
                elif decision_price < ma50 and momentum60 < 0:
                    sell_reason = "50일 추세와 60일 모멘텀 동시 훼손"
            elif strategy_mode == "canslim_proxy":
                if pnl_pct <= -stop_loss_pct:
                    sell_reason = f"CANSLIM형 프록시 손실 제한 -{stop_loss_pct:.1f}%"
                elif holding_limit_days and holding_days >= holding_limit_days:
                    sell_reason = f"CANSLIM형 프록시 {holding_limit_days}일 재검증"
                elif decision_price < ma50 and momentum20 < -8:
                    sell_reason = "50일 성장주 추세와 단기 모멘텀 동시 훼손"
            else:
                if fast_ma < slow_ma:
                    sell_reason = "단기 추세가 장기 추세 아래로 내려옴"
                elif pnl_pct <= -stop_loss_pct:
                    sell_reason = f"손실 -{stop_loss_pct:.1f}% 방어 규칙"
            if not sell_reason:
                continue
            quantity = float(position.get("quantity", 0) or 0)
            execution_price = price * (1.0 - slippage_rate)
            gross_proceeds = quantity * execution_price
            commission = gross_proceeds * commission_rate
            market = str(symbol_meta.get(symbol, {}).get("market") or "KR")
            usdkrw_rate = today_fx_rates.get(symbol, last_fx_rates.get(symbol, 0.0))
            sell_tax = gross_proceeds * kr_sell_tax_rate if market == "KR" else 0.0
            us_regulatory = (
                _paper_us_regulatory_fee_contract(
                    date_key,
                    quantity=quantity,
                    gross_krw=gross_proceeds,
                    usdkrw_rate=usdkrw_rate,
                )
                if market == "US"
                else {}
            )
            us_sec_fee = _number(us_regulatory.get("sec_fee_krw"))
            us_finra_taf = _number(us_regulatory.get("finra_taf_krw"))
            fx_conversion_cost = (
                gross_proceeds * fx_conversion_spread_rate if market == "US" else 0.0
            )
            proceeds = max(
                0.0,
                gross_proceeds
                - commission
                - sell_tax
                - us_sec_fee
                - us_finra_taf
                - fx_conversion_cost,
            )
            effective_exit_price = proceeds / quantity if quantity > 0 else 0.0
            pnl_pct = ((effective_exit_price / avg_cost) - 1.0) * 100.0 if avg_cost else 0.0
            cash += proceeds
            total_commission += commission
            total_sell_tax += sell_tax
            total_us_sec_fee += us_sec_fee
            total_us_finra_taf += us_finra_taf
            total_fx_conversion_cost += fx_conversion_cost
            slippage_cost = max(0.0, quantity * (price - execution_price))
            total_slippage_cost += slippage_cost
            total_turnover += gross_proceeds
            calendar_proof = build_calendar_adjacency_proof(
                symbol,
                symbol_trading_dates[symbol],
                symbol_date_indexes[symbol][date_key],
            )
            trade = {
                "date": date_key,
                "decision_data_as_of": decision_date,
                "execution_at": date_key,
                "signal_lag_bars": 1,
                "decision_market_price": round(decision_price, 4),
                "decision_return_pct": round(decision_return_pct, 4),
                "execution_price_basis": "next_available_close",
                "market_data_snapshot_hash": market_data_snapshot_hash,
                **calendar_proof,
                "symbol": symbol,
                "name": symbol_meta.get(symbol, {}).get("name", symbol),
                "market": market,
                "side": "SELL",
                "entry_date": position.get("entry_date"),
                "entry_price": round(float(position.get("avg_cost", price) or price), 4),
                "entry_reason": position.get("entry_reason", ""),
                "entry_score": position.get("entry_score", 0),
                "price": round(effective_exit_price, 4),
                "market_price": round(price, 4),
                "execution_price": round(execution_price, 4),
                "quantity": round(quantity, 6),
                "notional": round(gross_proceeds, 2),
                "net_proceeds": round(proceeds, 2),
                "commission": round(commission, 2),
                "slippage_cost": round(slippage_cost, 2),
                "sell_tax": round(sell_tax, 2),
                "usdkrw_rate": round(usdkrw_rate, 8) if market == "US" and usdkrw_rate > 0 else None,
                "fx_conversion_cost": round(fx_conversion_cost, 2),
                "us_sec_fee": round(us_sec_fee, 2),
                "us_finra_taf": round(us_finra_taf, 2),
                "us_sec_fee_bps": us_regulatory.get("sec_fee_bps") if market == "US" else 0.0,
                "us_regulatory_fee_source": (
                    {
                        "sec": us_regulatory.get("sec_evidence"),
                        "finra": us_regulatory.get("finra_evidence"),
                    }
                    if market == "US"
                    else None
                ),
                "pnl_pct": round(pnl_pct, 2),
                "holding_days": holding_days,
                "strategy": strategy_label,
                "reason": sell_reason,
                "peak_market_price": round(peak_price, 4),
                "exit_trigger_market_price": round(decision_price, 4),
                "peak_drawdown_pct": round(pullback_pct, 4),
                "trailing_trigger_pct": round(trailing_trigger_pct, 4) if trailing_trigger_pct is not None else None,
            }
            trades.append(trade)
            day_actions.append(trade)
            del positions[symbol]

        equity = current_equity()
        market_breadth = 1.0
        if strategy_mode in {
            "intraday_theme_leader",
            "intraday_momentum_breakout",
            "intraday_pullback_reclaim",
            "intraday_mean_reversion",
        }:
            breadth_total = 0
            breadth_positive = 0
            for breadth_symbol, breadth_history in histories.items():
                if len(breadth_history) < slow + 1 or breadth_symbol not in today_prices:
                    continue
                breadth_decision_history = breadth_history[:-1]
                breadth_price = float(breadth_decision_history[-1])
                if breadth_price <= 0:
                    continue
                breadth_total += 1
                breadth_fast = _series_sma(breadth_decision_history, fast)
                breadth_slow = _series_sma(breadth_decision_history, slow)
                breadth_momentum20 = _series_pct_change(
                    breadth_decision_history,
                    min(20, len(breadth_decision_history) - 1),
                )
                if breadth_fast > breadth_slow and breadth_momentum20 > 0:
                    breadth_positive += 1
            market_breadth = breadth_positive / breadth_total if breadth_total else 1.0
        candidates: list[dict[str, object]] = []
        for symbol, history in histories.items():
            if symbol in positions or len(history) < minimum_history_bars + 1 or symbol not in today_prices or index <= 0:
                continue
            decision_history = history[:-1]
            decision_price = float(decision_history[-1])
            decision_date = history_dates[symbol][-2]
            fast_ma = _series_sma(decision_history, fast)
            slow_ma = _series_sma(decision_history, slow)
            rsi14 = _series_rsi(decision_history, 14)
            momentum5 = _series_pct_change(decision_history, min(5, len(decision_history) - 1))
            momentum20 = _series_pct_change(decision_history, min(20, len(decision_history) - 1))
            momentum60 = _series_pct_change(decision_history, min(60, len(decision_history) - 1))
            momentum120 = _series_pct_change(decision_history, min(120, len(decision_history) - 1))
            momentum240 = _series_pct_change(decision_history, min(240, len(decision_history) - 1))
            ma20 = _series_sma(decision_history, 20)
            ma50 = _series_sma(decision_history, 50)
            ma90 = _series_sma(decision_history, 90)
            ma150 = _series_sma(decision_history, 150)
            ma180 = _series_sma(decision_history, 180)
            ma200 = _series_sma(decision_history, 200)
            prior = decision_history[:-1]
            prior_high10 = max(prior[-10:]) if len(prior) >= 10 else max(prior) if prior else decision_price
            prior_high20 = max(prior[-20:]) if len(prior) >= 20 else max(prior) if prior else decision_price
            prior_high55 = max(prior[-55:]) if len(prior) >= 55 else max(prior) if prior else decision_price
            prior_high120 = max(prior[-120:]) if len(prior) >= 120 else max(prior) if prior else decision_price
            prior_high240 = max(prior[-240:]) if len(prior) >= 240 else max(prior) if prior else decision_price
            signal = False
            reason = ""
            if strategy_mode == "short_swing":
                signal = fast_ma > slow_ma and momentum5 > 0.8 and momentum20 > -8 and 35 <= rsi14 <= 72
                reason = f"단기 스윙: 5일 모멘텀 {momentum5:.1f}%, RSI {rsi14:.1f}"
                score = momentum5 * 0.8 + momentum20 * 0.2 + max(0.0, 68.0 - rsi14) * 0.08 + (fast_ma / slow_ma - 1.0) * 100.0
            elif strategy_mode == "breakout":
                signal = decision_price >= prior_high20 * 1.005 and momentum20 > 2.0 and rsi14 < 80
                reason = f"신고가 돌파: 20일 상단 {prior_high20:.2f} 돌파, RSI {rsi14:.1f}"
                score = ((decision_price / max(1e-9, prior_high20)) - 1.0) * 100.0 + momentum20 * 0.35 + max(0.0, 76.0 - rsi14) * 0.05
            elif strategy_mode == "protected_ma":
                signal = fast_ma > slow_ma and momentum20 > -4 and rsi14 < 72
                reason = f"보호형 MA: 추세 우위, RSI {rsi14:.1f}, 손절 {stop_loss_pct:.1f}%"
                score = (fast_ma / slow_ma - 1.0) * 100.0 + momentum20 * 0.22 + max(0.0, 64.0 - rsi14) * 0.09
            elif strategy_mode == "intraday_theme_leader":
                near_high = decision_price >= prior_high20 * 0.985
                breadth_ok = market_breadth >= 0.38
                signal = breadth_ok and fast_ma > slow_ma and momentum5 > 0.8 and momentum20 > 1.5 and 42 <= rsi14 <= 78 and near_high
                reason = f"주도테마 대장주 단타 근사: 5일 {momentum5:.1f}%, 20일 {momentum20:.1f}%, RSI {rsi14:.1f}, 고점권 {near_high}, 시장폭 {market_breadth * 100:.0f}%"
                score = momentum5 * 1.2 + momentum20 * 0.35 + (fast_ma / slow_ma - 1.0) * 100.0 + max(0.0, 74.0 - rsi14) * 0.08
            elif strategy_mode == "intraday_momentum_breakout":
                breadth_ok = market_breadth >= 0.35
                signal = breadth_ok and decision_price >= prior_high10 * 1.002 and momentum5 > 1.2 and momentum20 > 2.0 and 50 <= rsi14 <= 80
                reason = f"단타 고점 돌파 근사: 10일 상단 {prior_high10:.2f}, 5일 {momentum5:.1f}%, RSI {rsi14:.1f}, 시장폭 {market_breadth * 100:.0f}%"
                score = momentum5 * 1.4 + momentum20 * 0.3 + (decision_price / max(1e-9, prior_high10) - 1.0) * 100.0
            elif strategy_mode == "intraday_pullback_reclaim":
                breadth_ok = market_breadth >= 0.32
                pullback_zone = -2.5 <= momentum5 <= 1.5
                signal = breadth_ok and fast_ma > slow_ma and momentum20 > 3.0 and pullback_zone and 38 <= rsi14 <= 62 and decision_price >= fast_ma * 0.99
                reason = f"단타 눌림목 회복 근사: 5일 {momentum5:.1f}%, 20일 {momentum20:.1f}%, RSI {rsi14:.1f}, 시장폭 {market_breadth * 100:.0f}%"
                score = momentum20 * 0.45 - abs(momentum5) * 0.2 + max(0.0, 58.0 - rsi14) * 0.12 + (fast_ma / slow_ma - 1.0) * 100.0
            elif strategy_mode == "intraday_mean_reversion":
                breadth_ok = market_breadth >= 0.25
                trend_survives = decision_price >= slow_ma * 0.94
                signal = breadth_ok and trend_survives and momentum5 <= -2.0 and momentum20 > -12.0 and 24 <= rsi14 <= 43
                reason = f"단타 과매도 반전 근사: 5일 {momentum5:.1f}%, 20일 {momentum20:.1f}%, RSI {rsi14:.1f}, 장기추세 생존 {trend_survives}"
                score = max(0.0, 45.0 - rsi14) * 0.5 + abs(min(0.0, momentum5)) * 0.7 + momentum20 * 0.1
            elif strategy_mode == "buffett_quality_proxy":
                signal = decision_price > ma200 and ma50 > ma200 and momentum240 > 0 and 40 <= rsi14 <= 75
                reason = f"버핏형 품질·장기 프록시: 50/200일 추세, 240일 {momentum240:.1f}%, RSI {rsi14:.1f}"
                score = (ma50 / ma200 - 1.0) * 100.0 + momentum120 * 0.25 + momentum240 * 0.35 + max(0.0, 70.0 - rsi14) * 0.05
            elif strategy_mode == "graham_defensive_proxy":
                signal = decision_price >= ma180 * 0.95 and momentum120 > -5 and 35 <= rsi14 <= 62
                reason = f"그레이엄형 방어·장기 프록시: 180일선 방어, 120일 {momentum120:.1f}%, RSI {rsi14:.1f}"
                score = momentum120 * 0.2 - abs(rsi14 - 48.0) * 0.08 + (decision_price / ma180 - 1.0) * 40.0
            elif strategy_mode == "lynch_growth_proxy":
                signal = fast_ma > slow_ma and momentum60 > 5 and momentum120 > 8 and 42 <= rsi14 <= 75
                reason = f"린치형 성장가치 프록시: {fast}/{slow}일 추세, 60일 {momentum60:.1f}%, 120일 {momentum120:.1f}%"
                score = (fast_ma / slow_ma - 1.0) * 100.0 + momentum60 * 0.35 + momentum120 * 0.4
            elif strategy_mode == "turtle_55":
                signal = decision_price >= prior_high55 * 1.001 and momentum60 > 10 and decision_price > ma50
                reason = f"터틀 55일 추세 프록시: 55일 상단 {prior_high55:.2f} 돌파, 60일 {momentum60:.1f}%"
                score = (decision_price / max(1e-9, prior_high55) - 1.0) * 100.0 + momentum60 * 0.8 + momentum120 * 0.25
            elif strategy_mode == "minervini_proxy":
                trend_stack = decision_price > ma50 > ma150 > ma200
                near_high = decision_price >= prior_high240 * 0.75
                signal = trend_stack and near_high and momentum120 > 20 and momentum240 > 20 and rsi14 >= 48
                reason = f"미너비니형 프록시: 50/150/200일 정렬 {trend_stack}, 120일 {momentum120:.1f}%, 240일 {momentum240:.1f}%"
                score = momentum60 * 0.45 + momentum120 * 0.55 + momentum240 * 0.25 + (decision_price / max(1e-9, prior_high240)) * 10.0
            elif strategy_mode == "canslim_proxy":
                near_high = decision_price >= prior_high120 * 0.92
                signal = decision_price > ma50 and near_high and momentum60 > 20 and momentum120 > 30 and 50 <= rsi14 <= 82
                reason = f"오닐 CANSLIM형 프록시: 120일 고점 근접 {near_high}, 60일 {momentum60:.1f}%, 120일 {momentum120:.1f}%"
                score = momentum20 * 0.5 + momentum60 * 0.7 + momentum120 * 0.35 + (decision_price / max(1e-9, prior_high120)) * 8.0
            else:
                signal = fast_ma > slow_ma and rsi14 < 74
                reason = f"MA {fast}/{slow} 상승 전환, RSI {rsi14:.1f}"
                score = (fast_ma / slow_ma - 1.0) * 100.0 + momentum20 * 0.25 + max(0.0, 65.0 - rsi14) * 0.08
            if signal:
                candidates.append(
                    {
                        "symbol": symbol,
                        "score": score,
                        "fast_ma": fast_ma,
                        "slow_ma": slow_ma,
                        "rsi": rsi14,
                        "momentum5": momentum5,
                        "momentum20": momentum20,
                        "reason": reason,
                        "decision_data_as_of": decision_date,
                        "decision_market_price": decision_price,
                    }
                )
        candidates.sort(key=lambda item: float(item["score"]), reverse=True)

        slots = max_positions - len(positions)
        for candidate in candidates[: max(0, slots)]:
            symbol = str(candidate["symbol"])
            price = today_prices.get(symbol, 0.0)
            if price <= 0 or cash <= 0:
                continue
            target_notional = min(cash, equity * allocation_pct / 100.0)
            execution_price = price * (1.0 + slippage_rate)
            market = str(symbol_meta.get(symbol, {}).get("market") or "KR")
            usdkrw_rate = today_fx_rates.get(symbol, last_fx_rates.get(symbol, 0.0))
            unit_fx_rate = fx_conversion_spread_rate if market == "US" else 0.0
            unit_cash_cost = execution_price * (1.0 + commission_rate + unit_fx_rate)
            quantity = math.floor(target_notional / max(unit_cash_cost, 1e-12))
            if quantity <= 0:
                continue
            notional = quantity * execution_price
            commission = notional * commission_rate
            fx_conversion_cost = notional * unit_fx_rate
            cash_cost = notional + commission + fx_conversion_cost
            effective_entry_price = cash_cost / quantity
            cash -= cash_cost
            total_commission += commission
            total_fx_conversion_cost += fx_conversion_cost
            slippage_cost = max(0.0, quantity * (execution_price - price))
            total_slippage_cost += slippage_cost
            total_turnover += notional
            calendar_proof = build_calendar_adjacency_proof(
                symbol,
                symbol_trading_dates[symbol],
                symbol_date_indexes[symbol][date_key],
            )
            positions[symbol] = {
                "quantity": quantity,
                "avg_cost": effective_entry_price,
                "entry_date": date_key,
                "entry_index": index,
                "entry_reason": str(candidate.get("reason") or f"MA {fast}/{slow} 상승 전환"),
                "entry_score": round(float(candidate["score"]), 2),
                "peak_price": price,
                "strategy": strategy_mode,
            }
            trade = {
                "date": date_key,
                "decision_data_as_of": candidate.get("decision_data_as_of"),
                "execution_at": date_key,
                "signal_lag_bars": 1,
                "decision_market_price": round(float(candidate.get("decision_market_price", 0) or 0), 4),
                "execution_price_basis": "next_available_close",
                "market_data_snapshot_hash": market_data_snapshot_hash,
                **calendar_proof,
                "symbol": symbol,
                "name": symbol_meta.get(symbol, {}).get("name", symbol),
                "market": market,
                "side": "BUY",
                "price": round(effective_entry_price, 4),
                "market_price": round(price, 4),
                "execution_price": round(execution_price, 4),
                "quantity": round(quantity, 6),
                "notional": round(notional, 2),
                "cash_cost": round(cash_cost, 2),
                "commission": round(commission, 2),
                "slippage_cost": round(slippage_cost, 2),
                "sell_tax": 0.0,
                "usdkrw_rate": round(usdkrw_rate, 8) if market == "US" and usdkrw_rate > 0 else None,
                "fx_conversion_cost": round(fx_conversion_cost, 2),
                "us_sec_fee": 0.0,
                "us_finra_taf": 0.0,
                "us_sec_fee_bps": 0.0,
                "us_regulatory_fee_source": None,
                "score": round(float(candidate["score"]), 2),
                "strategy": strategy_label,
                "reason": str(candidate.get("reason") or f"MA {fast}/{slow} 상승 전환"),
            }
            trades.append(trade)
            day_actions.append(trade)

        equity = current_equity()
        peak = max(peak, equity)
        drawdown = (equity / peak - 1.0) * 100.0 if peak else 0.0
        max_drawdown = min(max_drawdown, drawdown)
        equity_curve.append(round(equity, 2))
        if day_actions or index in {0, len(dates) - 1} or index % max(1, len(dates) // 12) == 0:
            buys = [item for item in day_actions if item.get("side") == "BUY"]
            sells = [item for item in day_actions if item.get("side") == "SELL"]
            if buys:
                lesson = "강한 추세 후보를 분산 진입하며 경험치를 쌓았습니다."
            elif sells:
                lesson = "추세 훼손 또는 손실 방어 신호를 익혔습니다."
            else:
                lesson = "매매하지 않는 날도 포지션과 리스크를 점검했습니다."
            journal.append(
                {
                    "date": date_key,
                    "equity": round(equity, 2),
                    "cash": round(cash, 2),
                    "positions": len(positions),
                    "actions": day_actions,
                    "lesson": lesson,
                    "drawdown_pct": round(drawdown, 2),
                }
            )

    final_equity = equity_curve[-1] if equity_curve else cash
    closed = [trade for trade in trades if trade.get("side") == "SELL"]
    wins = [float(trade.get("pnl_pct", 0) or 0) for trade in closed if float(trade.get("pnl_pct", 0) or 0) > 0]
    losses = [float(trade.get("pnl_pct", 0) or 0) for trade in closed if float(trade.get("pnl_pct", 0) or 0) <= 0]
    closed_trade_journal = _closed_trade_journal_from_actions(
        trades,
        require_lookahead_evidence=True,
    )
    monthly: dict[str, float] = {}
    for date_key, equity_value in zip(dates, equity_curve):
        monthly[date_key[:7]] = float(equity_value)
    bucket_returns = {
        "daily": _bucket_return_rows(dates, equity_curve, "daily"),
        "weekly": _bucket_return_rows(dates, equity_curve, "weekly"),
        "monthly": _bucket_return_rows(dates, equity_curve, "monthly"),
    }
    latest_bucket_returns = _latest_replay_bucket_returns(bucket_returns)
    initial_cash_value = max(1_000_000.0, float(initial_cash or 100_000_000.0))
    total_return_pct = round((final_equity / max(1.0, initial_cash_value) - 1.0) * 100.0, 2)
    data_coverage = _historical_replay_data_coverage(data, dates, start_date, end_date)
    estimated_open_liquidation_cost = sum(
        max(
            0.0,
            float(position.get("quantity", 0) or 0) * last_prices.get(symbol, 0.0)
            - estimated_exit_net(
                symbol,
                last_prices.get(symbol, 0.0),
                float(position.get("quantity", 0) or 0),
                valuation_date=last_price_dates.get(symbol, ""),
                usdkrw_rate=last_fx_rates.get(symbol, 0.0),
            ),
        )
        for symbol, position in positions.items()
    )
    cost_model = {
        "enabled": True,
        "mandatory": True,
        "policy_version": PAPER_COST_POLICY_VERSION,
        "commission_bps_each_side": round(commission_bps, 4),
        "slippage_bps_each_side": round(slippage_bps, 4),
        "kr_sell_tax_bps": round(kr_sell_tax_bps, 4),
        "us_sell_tax_bps": 0.0,
        "us_regulatory_fee_policy_version": PAPER_US_REGULATORY_POLICY_VERSION,
        "us_sec_fee_schedule": [dict(row) for row in PAPER_US_SEC_FEE_SCHEDULE],
        "us_finra_taf_schedule": [dict(row) for row in PAPER_US_FINRA_TAF_SCHEDULE],
        "us_finra_taf_pass_through_assumed": True,
        "fx_conversion_spread_bps_each_side": round(fx_conversion_spread_bps, 4),
        "fx_conversion_mode": "per_trade_krw_cash_conversion_proxy",
        "market_costs": {
            "KR": {
                "commission_bps_each_side": round(commission_bps, 4),
                "slippage_bps_each_side": round(slippage_bps, 4),
                "sell_tax_bps": round(kr_sell_tax_bps, 4),
                "fx_conversion_spread_bps_each_side": 0.0,
            },
            "US": {
                "commission_bps_each_side": round(commission_bps, 4),
                "slippage_bps_each_side": round(slippage_bps, 4),
                "sell_tax_bps": 0.0,
                "sec_section31_date_aware": True,
                "finra_taf_date_aware": True,
                "fx_conversion_spread_bps_each_side": round(fx_conversion_spread_bps, 4),
            },
        },
        "base_currency_assumption": "KRW base; US adjusted prices are converted by daily USD/KRW when coverage is sufficient",
        "base_currency": "KRW",
        "fx_return_mode": "USD prices converted by daily USD/KRW" if any(not symbol.isdigit() for symbol in cleaned) else "not_required",
    }
    total_transaction_cost = (
        total_commission
        + total_slippage_cost
        + total_sell_tax
        + total_us_sec_fee
        + total_us_finra_taf
        + total_fx_conversion_cost
    )
    transaction_cost_audit = _replay_transaction_cost_audit(
        trades,
        cost_model,
        {
            "total_commission": total_commission,
            "total_slippage_cost": total_slippage_cost,
            "total_sell_tax": total_sell_tax,
            "total_us_sec_fee": total_us_sec_fee,
            "total_us_finra_taf": total_us_finra_taf,
            "total_fx_conversion_cost": total_fx_conversion_cost,
            "total_transaction_cost": total_transaction_cost,
        },
        estimated_open_liquidation_cost=estimated_open_liquidation_cost,
    )
    sources = {
        symbol: {
            "name": symbol_meta.get(symbol, {}).get("name", symbol),
            "market": symbol_meta.get(symbol, {}).get("market", "KR" if symbol.isdigit() else "US"),
            "source": data.get(symbol, {}).get("source", "-"),
            "provider": data.get(symbol, {}).get("provider", "-"),
            "yahoo_symbol": data.get(symbol, {}).get("yahoo_symbol", ""),
            "price_contract": data.get(symbol, {}).get("price_contract", {}),
        }
        for symbol in cleaned
        if symbol in data
    }
    simulated_sources = [
        symbol
        for symbol, row in data.items()
        if "simulated" in str(row.get("source", "")).lower()
    ]
    price_contracts = {
        symbol: row.get("price_contract", {})
        for symbol, row in data.items()
        if isinstance(row, dict)
    }
    price_contract_blockers = [
        {"symbol": symbol, "blockers": contract.get("blockers", [])}
        for symbol, contract in price_contracts.items()
        if isinstance(contract, dict) and not contract.get("passed")
    ]
    price_currency_unit_audit = {
        "ok": True,
        "schema": "codexstock_price_currency_unit_audit_v1",
        "passed": bool(price_contracts) and not price_contract_blockers,
        "base_currency": "KRW",
        "symbol_count": len(price_contracts),
        "passed_symbol_count": sum(1 for contract in price_contracts.values() if isinstance(contract, dict) and contract.get("passed")),
        "contracts": price_contracts,
        "blockers": price_contract_blockers,
        "policy": "Official replay returns require split/dividend-adjusted prices and KRW-normalized US prices with at least 95% FX coverage.",
    }
    record = {
        "id": f"HREPLAY-{int(time.time() * 1000)}",
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "source": source,
        "data_mode": "simulated" if len(simulated_sources) == len(data) else "mixed" if simulated_sources else "real",
        "data_policy": "실데이터 필수" if not allow_simulated_fallback else "실데이터 우선, 실패 시 샘플 허용",
        "data_errors": data_errors,
        "replay_data_bundle_evidence": replay_data_bundle_evidence,
        "price_currency_unit_audit": price_currency_unit_audit,
        "symbols": list(sources.keys()),
        "start_date": start_date,
        "end_date": end_date,
        "actual_start_date": data_coverage.get("actual_start_date"),
        "actual_end_date": data_coverage.get("actual_end_date"),
        "actual_horizon_years": data_coverage.get("actual_horizon_years"),
        "data_coverage": data_coverage,
        "strategy_mode": strategy_mode,
        "strategy_label": strategy_label,
        "strategy_owner": strategy_profile.get("owner", "코덱스 AI"),
        "strategy_description": strategy_profile.get("description", ""),
        "strategy_horizon": strategy_horizon,
        "master_strategy_proxy": bool(strategy_profile.get("master_proxy")),
        "stage2_requirements": list(strategy_profile.get("stage2_requirements") or []),
        "strategy_config": {
            "fast": fast,
            "slow": slow,
            "stop_loss_pct": round(float(stop_loss_pct), 2),
            "take_profit_pct": round(float(take_profit_pct), 2),
            "holding_limit_days": int(holding_limit_days),
            "allocation_pct": round(float(allocation_pct), 2),
            "max_positions": max_positions,
            "cycles_per_day": cycles_per_day,
            "minimum_history_bars": minimum_history_bars,
            "horizon": strategy_horizon,
        },
        "execution_timing_model": {
            "version": HISTORICAL_REPLAY_EXECUTION_TIMING_MODEL_VERSION,
            "decision_basis": "completed_prior_daily_bar",
            "execution_basis": "next_available_close",
            "minimum_signal_lag_bars": 1,
            "same_bar_signal_execution_allowed": False,
            "lookahead_safe_required": True,
            "execution_bar_excluded_from_decision": True,
            "symbol_calendar_alignment_required": True,
            "missing_execution_bar_policy": "skip_until_next_available_symbol_bar",
            "calendar_adjacency_proof_contract": CALENDAR_ADJACENCY_PROOF_CONTRACT,
        },
        "cost_model": cost_model,
        "commission_bps": round(commission_bps, 4),
        "slippage_bps": round(slippage_bps, 4),
        "kr_sell_tax_bps": round(kr_sell_tax_bps, 4),
        "fx_conversion_spread_bps": round(fx_conversion_spread_bps, 4),
        "transaction_cost_audit": transaction_cost_audit,
        "fast": fast,
        "slow": slow,
        "initial_cash": round(initial_cash_value, 2),
        "final_equity": round(final_equity, 2),
        "total_return_pct": total_return_pct,
        "max_drawdown_pct": round(max_drawdown, 2),
        "trade_count": len(trades),
        "total_turnover": round(total_turnover, 2),
        "total_commission": round(total_commission, 2),
        "total_slippage_cost": round(total_slippage_cost, 2),
        "total_sell_tax": round(total_sell_tax, 2),
        "total_us_sec_fee": round(total_us_sec_fee, 2),
        "total_us_finra_taf": round(total_us_finra_taf, 2),
        "total_us_regulatory_fees": round(total_us_sec_fee + total_us_finra_taf, 2),
        "total_fx_conversion_cost": round(total_fx_conversion_cost, 2),
        "total_transaction_cost": round(total_transaction_cost, 2),
        "estimated_open_liquidation_cost": round(estimated_open_liquidation_cost, 2),
        "transaction_cost_pct_of_initial_cash": round(
            (total_transaction_cost / max(initial_cash_value, 1.0)) * 100.0,
            4,
        ),
        "closed_trade_count": len(closed),
        "win_rate_pct": round((len(wins) / len(closed)) * 100.0, 2) if closed else 0.0,
        "average_win_pct": rounded_financial_mean_pct(wins),
        "average_loss_pct": rounded_financial_mean_pct(losses),
        "replay_days": len(dates),
        "cycles_per_day": cycles_per_day,
        "compressed_training_hours": len(dates) * cycles_per_day,
        "open_positions": [
            {
                "symbol": symbol,
                "name": symbol_meta.get(symbol, {}).get("name", symbol),
                "market": symbol_meta.get(symbol, {}).get("market", "KR" if symbol.isdigit() else "US"),
                "quantity": position.get("quantity", 0),
                "avg_cost": position.get("avg_cost", 0),
                "last_price": round(last_prices.get(symbol, 0), 4),
                "valuation_date": last_price_dates.get(symbol),
                "last_usdkrw_rate": (
                    round(last_fx_rates.get(symbol, 0.0), 8)
                    if symbol_meta.get(symbol, {}).get("market") == "US"
                    and last_fx_rates.get(symbol, 0.0) > 0
                    else None
                ),
                "unrealized_pct": round(((last_prices.get(symbol, 0) / float(position.get("avg_cost", 1) or 1)) - 1.0) * 100.0, 2),
                "strategy": strategy_label,
            }
            for symbol, position in positions.items()
        ],
        "sources": sources,
        "dates": dates,
        "equity_curve": equity_curve,
        "monthly_equity": [{"month": month, "equity": round(value, 2)} for month, value in monthly.items()],
        "period_returns": bucket_returns,
        "latest_period_returns": latest_bucket_returns,
        "trades": trades[-120:],
        "trade_actions_sample": trades[-120:],
        "trade_journal_count": len(closed_trade_journal),
        "trade_journal_sample": closed_trade_journal[-80:],
        "trade_journal_top10": sorted(closed_trade_journal, key=lambda row: _number(row.get("pnl_pct")), reverse=True)[:10],
        "trade_journal_bottom10": sorted(closed_trade_journal, key=lambda row: _number(row.get("pnl_pct")))[:10],
        "experience_log": journal[-120:],
        "summary": (
            f"{strategy_label} 전략으로 {len(dates)}거래일을 {len(dates) * cycles_per_day:,}시간 압축훈련했고, "
            f"매매 {len(trades)}회 / 수익률 {total_return_pct}% / "
            f"MDD {round(max_drawdown, 2)}%를 기록했습니다."
        ),
        "safety": "과거장 모의훈련은 경험 축적과 전략 검증용입니다. 실전 주문을 전송하지 않습니다.",
    }
    if persist_detail:
        trade_journal_files = _write_replay_trade_journal_files(record, trades, closed_trade_journal)
        record["trade_journal_path"] = trade_journal_files.get("json_path")
        record["trade_journal_markdown_path"] = trade_journal_files.get("markdown_path")
        record["trade_journal_top10"] = trade_journal_files.get("top10", [])
        record["trade_journal_bottom10"] = trade_journal_files.get("bottom10", [])
        record["trade_journal_sample"] = trade_journal_files.get("sample", [])
        record["trade_journal_count"] = trade_journal_files.get("closed_count", len(closed_trade_journal))
        record["trade_action_count"] = trade_journal_files.get("action_count", len(trades))
        record["trade_journal_reconciliation_summary"] = trade_journal_files.get("reconciliation_summary", {})
    else:
        record["trade_journal_path"] = ""
        record["trade_journal_markdown_path"] = ""
        record["trade_journal_reconciliation_summary"] = _closed_trade_reconciliation_summary(closed_trade_journal)
        record["detail_persisted"] = False
    record["staff_meeting"] = _ai_staff_meeting_from_replay(record)
    if persist_detail:
        _append_jsonl(HISTORICAL_REPLAY_FILE, _compact_historical_replay_storage_record(record))
    JOURNAL.add("HISTORICAL_PAPER_REPLAY", str(record["summary"]), {"id": record["id"], "symbols": record["symbols"]})
    return record


def _regenerate_historical_paper_replay_locked(replay_id: str, *, force: bool = False) -> dict[str, object]:
    """Run one append-only Paper regeneration from an archived immutable contract."""
    contract = historical_replay_regeneration_contract(replay_id)
    if not contract.get("ok"):
        return {**contract, "regeneration_started": False}
    normalized_id = str(contract.get("replay_id") or "")
    previous = [
        row
        for row in _read_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, limit=1000)
        if str(row.get("source_replay_id") or "") == normalized_id
        and str(row.get("status") or "") in {"verified_replacement_candidate", "quarantined_new_result"}
    ]
    current_previous = [
        row for row in previous
        if _historical_replay_evidence_contract_is_current(row)
    ]
    if current_previous and not force:
        latest = current_previous[-1]
        return {
            "ok": True,
            "status": "already_regenerated",
            "regeneration_started": False,
            "source_replay_id": normalized_id,
            "existing_new_replay_id": latest.get("new_replay_id"),
            "existing_result": latest,
            "paper_only": True,
            "live_order_allowed": False,
        }
    run_arguments = dict(contract.get("run_arguments") or {})
    if "min_bars" not in run_arguments:
        run_arguments["min_bars"] = max(
            5,
            min(40, int(_number(run_arguments.get("slow")) or 32) + 5),
        )
    contract_hash = hashlib.sha256(
        json.dumps(run_arguments, ensure_ascii=False, sort_keys=True).encode("utf-8")
    ).hexdigest()
    started_at = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
    try:
        result = run_historical_paper_replay(
            **run_arguments,
            source=f"tournament-regeneration:{normalized_id}",
        )
        artifact_anchors = _historical_replay_artifact_anchors(result)
        reconciliation = result.get("trade_journal_reconciliation_summary")
        if not isinstance(reconciliation, dict) or "official_return_claim_allowed" not in reconciliation:
            journal_path = Path(str(result.get("trade_journal_path") or ""))
            journal_payload: dict[str, object] = {}
            if journal_path.is_file() and is_inside(journal_path, USER_DATA_ROOT):
                loaded_journal = json.loads(journal_path.read_text(encoding="utf-8"))
                if isinstance(loaded_journal, dict):
                    journal_payload = loaded_journal
            reconciliation_input = dict(result)
            reconciliation_input["trades"] = journal_payload.get("actions", result.get("trades", []))
            reconciliation_input["trade_actions_sample"] = reconciliation_input["trades"]
            reconciliation = build_backtest_return_reconciliation(reconciliation_input)
        official_verdict = _historical_replay_official_verdict(result, reconciliation)
        official_allowed = bool(official_verdict.get("official_return_claim_allowed"))
        status = "verified_replacement_candidate" if official_allowed else "quarantined_new_result"
        ledger = {
            "id": f"HREGEN-{int(time.time() * 1000)}",
            "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
            "started_at": started_at,
            "status": status,
            "evidence_schema_version": HISTORICAL_REPLAY_EVIDENCE_SCHEMA_VERSION,
            "execution_timing_model_version": HISTORICAL_REPLAY_EXECUTION_TIMING_MODEL_VERSION,
            "replay_data_bundle_evidence_schema": (
                result.get("replay_data_bundle_evidence", {}).get("schema")
                if isinstance(result.get("replay_data_bundle_evidence"), dict)
                else ""
            ),
            "replay_data_bundle_hash": official_verdict.get("replay_data_bundle_hash", ""),
            "replay_data_slice_hash": official_verdict.get("replay_data_slice_hash", ""),
            **artifact_anchors,
            "source_replay_id": normalized_id,
            "new_replay_id": result.get("id"),
            "contract_hash": contract_hash,
            "source_trade_count": contract.get("source_trade_count"),
            "new_trade_count": result.get("closed_trade_count"),
            "source_total_return_pct": contract.get("source_total_return_pct"),
            "new_total_return_pct": result.get("total_return_pct"),
            "return_difference_pct": round(
                _number(result.get("total_return_pct")) - _number(contract.get("source_total_return_pct")),
                4,
            ),
            "cost_policy": contract.get("cost_policy"),
            "reconciliation": reconciliation,
            "official_verdict": official_verdict,
            "official_return_block_reasons": official_verdict.get("block_reasons", []),
            "official_return_claim_allowed": official_allowed,
            "old_record_rewritten": False,
            "automatic_promotion": False,
            "paper_only": True,
            "live_order_allowed": False,
            "review_rule": "Promote only after the new full journal passes reconciliation and the cost-policy difference is reviewed.",
        }
        ledger["source_comparison"] = classify_replay_source_comparison(ledger)
    except Exception as exc:
        retryable = not isinstance(exc, (ValueError, FileNotFoundError))
        ledger = {
            "id": f"HREGEN-{int(time.time() * 1000)}",
            "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
            "started_at": started_at,
            "status": "regeneration_failed",
            "source_replay_id": normalized_id,
            "contract_hash": contract_hash,
            "error": str(exc),
            "failure_kind": "transient_runtime_error" if retryable else "input_or_market_data_unavailable",
            "retryable": retryable,
            "old_record_rewritten": False,
            "automatic_promotion": False,
            "paper_only": True,
            "live_order_allowed": False,
        }
    _append_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, ledger)
    data_gap_queue: dict[str, object] = {}
    if ledger.get("status") == "regeneration_failed" and ledger.get("retryable") is False:
        try:
            data_gap_queue = historical_replay_data_gap_queue(record=True)
        except Exception as exc:
            data_gap_queue = {"ok": False, "status": "manifest_error", "error": str(exc)[:220]}
    return {
        "ok": ledger["status"] == "verified_replacement_candidate",
        "status": ledger["status"],
        "regeneration_started": True,
        "source_replay_id": normalized_id,
        "new_replay_id": ledger.get("new_replay_id"),
        "ledger": ledger,
        "error": ledger.get("error", ""),
        "retryable": ledger.get("retryable"),
        "data_gap_queue": data_gap_queue,
        "ledger_path": str(HISTORICAL_REPLAY_REGENERATION_FILE),
        "paper_only": True,
        "live_order_allowed": False,
    }


def regenerate_historical_paper_replay(replay_id: str, *, force: bool = False) -> dict[str, object]:
    """Serialize expensive replay recovery so manual/API/worker calls cannot race."""
    if not HISTORICAL_REPLAY_REGENERATION_LOCK.acquire(blocking=False):
        return {
            "ok": False,
            "status": "regeneration_busy",
            "regeneration_started": False,
            "source_replay_id": str(replay_id or "").strip().upper(),
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
        }
    try:
        return _regenerate_historical_paper_replay_locked(replay_id, force=force)
    finally:
        HISTORICAL_REPLAY_REGENERATION_LOCK.release()


def regenerate_historical_paper_replay_isolated(
    replay_id: str,
    *,
    force: bool = False,
) -> dict[str, object]:
    """Keep the automatic Paper queue from blocking the web/UI process."""
    normalized_id = str(replay_id or "").strip().upper()
    if not HISTORICAL_REPLAY_REGENERATION_LOCK.acquire(blocking=False):
        return {
            "ok": False,
            "status": "regeneration_busy",
            "regeneration_started": False,
            "source_replay_id": normalized_id,
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
        }
    try:
        return run_replay_subprocess(
            normalized_id,
            python_executable=sys.executable,
            repo_root=REPO_ROOT,
            result_dir=HISTORICAL_REPLAY_REGENERATION_SUBPROCESS_DIR,
            force=force,
        )
    finally:
        HISTORICAL_REPLAY_REGENERATION_LOCK.release()


def classify_historical_replay_regeneration_failure(
    replay_id: str,
    *,
    failure_kind: str,
    retryable: bool,
) -> dict[str, object]:
    """Append a failure classification correction without rewriting prior evidence."""
    normalized_id = str(replay_id or "").strip().upper()
    rows = [
        row
        for row in _read_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, limit=10000)
        if str(row.get("source_replay_id") or "").strip().upper() == normalized_id
    ]
    latest = rows[-1] if rows else {}
    if not re.fullmatch(r"HREPLAY-[0-9]+", normalized_id):
        return {"ok": False, "status": "invalid_replay_id", "live_order_allowed": False}
    if str(latest.get("status") or "") != "regeneration_failed":
        return {"ok": False, "status": "latest_verdict_not_failed", "live_order_allowed": False}
    corrected = {
        **latest,
        "id": f"HREGEN-{int(time.time() * 1000)}",
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "failure_kind": str(failure_kind or "classified_failure"),
        "retryable": bool(retryable),
        "failure_classified": True,
        "supersedes_ledger_id": latest.get("id"),
        "old_record_rewritten": False,
        "automatic_promotion": False,
        "paper_only": True,
        "live_order_allowed": False,
    }
    _append_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, corrected)
    data_gap_queue = historical_replay_data_gap_queue(record=True)
    return {
        "ok": True,
        "status": "failure_classified",
        "ledger": corrected,
        "data_gap_queue": data_gap_queue,
        "paper_only": True,
        "live_order_allowed": False,
    }


def reassess_historical_replay_regeneration(source_replay_id: str, new_replay_id: str) -> dict[str, object]:
    """Append a corrected verdict for an existing regenerated Paper journal."""
    source_id = str(source_replay_id or "").strip().upper()
    new_id = str(new_replay_id or "").strip().upper()
    if not re.fullmatch(r"HREPLAY-[0-9]+", source_id) or not re.fullmatch(r"HREPLAY-[0-9]+", new_id):
        return {"ok": False, "status": "invalid_replay_id", "live_order_allowed": False}
    previous = [
        row
        for row in _read_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, limit=1000)
        if str(row.get("source_replay_id") or "") == source_id
        and str(row.get("new_replay_id") or "") == new_id
    ]
    if not previous:
        return {"ok": False, "status": "regeneration_ledger_missing", "live_order_allowed": False}
    journal_path = (TRADE_JOURNAL_DIR / f"{new_id}.json").resolve()
    if not journal_path.is_file() or not is_inside(journal_path, USER_DATA_ROOT):
        return {"ok": False, "status": "new_trade_journal_missing", "live_order_allowed": False}
    try:
        journal_bytes = journal_path.read_bytes()
        journal = json.loads(journal_bytes.decode("utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return {"ok": False, "status": "new_trade_journal_invalid", "error": str(exc), "live_order_allowed": False}
    reconciliation = build_backtest_return_reconciliation(
        {"trades": journal.get("actions", []) if isinstance(journal, dict) else []}
    )
    replay_rows = _read_jsonl(HISTORICAL_REPLAY_FILE, limit=10000)
    replay = next(
        (
            row
            for row in reversed(replay_rows)
            if str(row.get("id") or "").strip().upper() == new_id
        ),
        {},
    )
    official_verdict = _historical_replay_official_verdict(replay, reconciliation)
    official_allowed = bool(official_verdict.get("official_return_claim_allowed"))
    latest = previous[-1]
    if _historical_replay_evidence_contract_is_current(latest):
        current_replay_hash = canonical_replay_artifact_sha256(replay)
        current_journal_hash = journal_artifact_sha256(journal_bytes)
        if (
            str(latest.get("artifact_hash_contract") or "")
            != REPLAY_ARTIFACT_HASH_CONTRACT
            or str(latest.get("replay_artifact_sha256") or "").lower()
            != current_replay_hash
            or str(latest.get("journal_artifact_sha256") or "").lower()
            != current_journal_hash
        ):
            return {
                "ok": False,
                "status": "artifact_integrity_mismatch",
                "source_replay_id": source_id,
                "new_replay_id": new_id,
                "paper_only": True,
                "live_order_allowed": False,
            }
    corrected = {
        **latest,
        "id": f"HREGEN-{int(time.time() * 1000)}",
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "status": "verified_replacement_candidate" if official_allowed else "quarantined_new_result",
        "reconciliation": reconciliation,
        "official_verdict": official_verdict,
        "official_return_block_reasons": official_verdict.get("block_reasons", []),
        "official_return_claim_allowed": official_allowed,
        "supersedes_ledger_id": latest.get("id"),
        "verdict_reassessed": True,
        "old_record_rewritten": False,
        "automatic_promotion": False,
        "paper_only": True,
        "live_order_allowed": False,
    }
    _append_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, corrected)
    return {
        "ok": official_allowed,
        "status": corrected["status"],
        "ledger": corrected,
        "paper_only": True,
        "live_order_allowed": False,
    }


def _historical_replay_regeneration_campaign(audit: dict[str, object]) -> dict[str, object]:
    """Freeze one recovery scope so newly created tournaments cannot move its finish line."""
    queue_rows = audit.get("regeneration_queue") if isinstance(audit.get("regeneration_queue"), list) else []
    current_ids = list(dict.fromkeys(
        str(row.get("replay_id") or "").strip().upper()
        for row in queue_rows
        if isinstance(row, dict) and str(row.get("replay_id") or "").strip()
    ))
    if not current_ids:
        batch_rows = audit.get("regeneration_batches") if isinstance(audit.get("regeneration_batches"), list) else []
        current_ids = list(dict.fromkeys(
            str(row.get("replay_id") or "").strip().upper()
            for row in batch_rows
            if isinstance(row, dict) and str(row.get("replay_id") or "").strip()
        ))
    try:
        stored = json.loads(HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        stored = {}
    stored_ids = stored.get("source_replay_ids") if isinstance(stored.get("source_replay_ids"), list) else []
    campaign_ids = list(dict.fromkeys(
        str(replay_id or "").strip().upper()
        for replay_id in stored_ids
        if str(replay_id or "").strip()
    ))
    if stored.get("schema") != "codexstock_replay_regeneration_campaign_v1" or not campaign_ids:
        campaign_ids = current_ids
        stored = {
            "schema": "codexstock_replay_regeneration_campaign_v1",
            "campaign_id": f"HRCAMPAIGN-{int(time.time() * 1000)}",
            "created_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
            "source_signature": list(_historical_replay_status_file_signature(AI_TOURNAMENT_FILE)),
            "source_replay_ids": campaign_ids,
            "target_count": int(_number(audit.get("regeneration_candidate_count"))) or len(campaign_ids),
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
        }
        try:
            target = HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE
            target.parent.mkdir(parents=True, exist_ok=True)
            temp = target.with_name(f"{target.name}.{os.getpid()}.tmp")
            temp.write_text(json.dumps(stored, ensure_ascii=False, indent=2), encoding="utf-8")
            os.replace(temp, target)
        except OSError:
            pass
    campaign_set = set(campaign_ids)
    current_set = set(current_ids)
    reported_current_count = int(_number(audit.get("regeneration_candidate_count"))) or len(current_ids)
    identity_scope_complete = reported_current_count == len(current_ids)
    return {
        **stored,
        "source_replay_ids": campaign_ids,
        "target_count": int(_number(stored.get("target_count"))) or len(campaign_ids),
        "current_candidate_count": reported_current_count,
        "current_candidate_id_preview_count": len(current_ids),
        "candidate_identity_comparison_status": "complete" if identity_scope_complete else "preview_only",
        "candidate_identity_comparison_claim_allowed": identity_scope_complete,
        "deferred_new_candidate_count": len(current_set - campaign_set) if identity_scope_complete else None,
        "missing_original_candidate_count": len(campaign_set - current_set) if identity_scope_complete else None,
        "manifest_path": str(HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE),
    }


def _historical_replay_campaign_manifest_scope() -> tuple[int, set[str]]:
    """Read the frozen campaign denominator without rebuilding the expensive audit."""
    try:
        payload = json.loads(
            HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE.read_text(encoding="utf-8")
        )
    except (OSError, json.JSONDecodeError):
        return 0, set()
    if not isinstance(payload, dict) or payload.get("schema") != "codexstock_replay_regeneration_campaign_v1":
        return 0, set()
    source_ids = payload.get("source_replay_ids") if isinstance(payload.get("source_replay_ids"), list) else []
    normalized_ids = {
        str(replay_id or "").strip().upper()
        for replay_id in source_ids
        if str(replay_id or "").strip()
    }
    target_count = int(_number(payload.get("target_count"))) or len(normalized_ids)
    return target_count, normalized_ids


def _historical_replay_regeneration_ledger_progress(
    total_candidates: int,
    source_replay_ids: set[str] | None = None,
    *,
    include_verified_source_ids: bool = False,
) -> dict[str, object]:
    """Summarize the append-only ledger without rescanning replay archives."""
    ledger_rows = _read_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, limit=5000)
    latest_by_source: dict[str, dict[str, object]] = {}
    latest_scoped_row: dict[str, object] = {}
    for row in ledger_rows:
        source_id = str(row.get("source_replay_id") or "").strip().upper()
        if source_id and (source_replay_ids is None or source_id in source_replay_ids):
            latest_by_source[source_id] = row
            latest_scoped_row = row
    counts = {
        "verified": 0,
        "quarantined": 0,
        "failed": 0,
    }
    legacy_resolved_count = 0
    failure_kind_counts: dict[str, int] = {}
    retryable_failure_count = 0
    blocked_failure_count = 0
    for row in latest_by_source.values():
        status = str(row.get("status") or "")
        current_evidence = _historical_replay_evidence_contract_is_current(row)
        if status in {"verified_replacement_candidate", "quarantined_new_result"} and not current_evidence:
            legacy_resolved_count += 1
            continue
        if status == "verified_replacement_candidate":
            counts["verified"] += 1
        elif status == "quarantined_new_result":
            counts["quarantined"] += 1
        elif status == "regeneration_failed":
            counts["failed"] += 1
            failure_kind = str(row.get("failure_kind") or "unclassified").strip().lower()
            failure_kind_counts[failure_kind] = failure_kind_counts.get(failure_kind, 0) + 1
            if row.get("retryable") is False:
                blocked_failure_count += 1
            else:
                retryable_failure_count += 1
    resolved_count = counts["verified"] + counts["quarantined"]
    attempted_count = resolved_count + counts["failed"]
    unattempted_count = max(0, total_candidates - attempted_count)
    remaining_count = max(0, total_candidates - resolved_count)
    progress_pct = round((resolved_count / total_candidates) * 100.0, 2) if total_candidates else 100.0
    latest_row = latest_scoped_row
    result: dict[str, object] = {
        "verified_count": counts["verified"],
        "quarantined_count": counts["quarantined"],
        "failed_count": counts["failed"],
        "resolved_count": resolved_count,
        "attempted_count": attempted_count,
        "unattempted_count": unattempted_count,
        "retryable_failure_count": retryable_failure_count,
        "blocked_failure_count": blocked_failure_count,
        "legacy_resolved_count": legacy_resolved_count,
        "required_evidence_schema_version": HISTORICAL_REPLAY_EVIDENCE_SCHEMA_VERSION,
        "required_execution_timing_model_version": HISTORICAL_REPLAY_EXECUTION_TIMING_MODEL_VERSION,
        "required_replay_data_bundle_evidence_schema": HISTORICAL_REPLAY_DATA_BUNDLE_SLICE_EVIDENCE_SCHEMA,
        "failure_kind_counts": failure_kind_counts,
        "total_candidate_count": total_candidates,
        "remaining_candidate_count": remaining_count,
        "progress_pct": progress_pct,
        "label": f"{resolved_count}/{total_candidates} ({progress_pct:.2f}%)",
        "latest_verdict_counts": counts,
        "unique_source_replay_count": len(latest_by_source),
        "latest_activity": {
            "generated_at": latest_row.get("generated_at", ""),
            "source_replay_id": latest_row.get("source_replay_id", ""),
            "status": latest_row.get("status", ""),
            "failure_kind": latest_row.get("failure_kind", ""),
        },
        "accounting": {
            "equation": "resolved + failed + unattempted = total",
            "accounted_count": resolved_count + counts["failed"] + unattempted_count,
            "invariant_ok": resolved_count + counts["failed"] + unattempted_count == total_candidates,
        },
    }
    if include_verified_source_ids:
        result["_verified_source_ids"] = sorted(
            source_id
            for source_id, row in latest_by_source.items()
            if (
                str(row.get("status") or "") == "verified_replacement_candidate"
                and _historical_replay_evidence_contract_is_current(row)
            )
        )
    return result


def _historical_replay_base_audit() -> dict[str, object]:
    """Cache the expensive immutable-source audit separately from the live verdict ledger."""
    global HISTORICAL_REPLAY_BASE_AUDIT_CACHE
    signature = _historical_replay_status_file_signature(AI_TOURNAMENT_FILE)
    with HISTORICAL_REPLAY_BASE_AUDIT_CACHE_LOCK:
        cached = HISTORICAL_REPLAY_BASE_AUDIT_CACHE
        if isinstance(cached, tuple) and len(cached) == 2 and cached[0] == signature:
            payload = dict(cached[1])
            payload["base_audit_cache_hit"] = True
            payload["base_audit_cache_source"] = "memory"
            return payload
        if cached is _HISTORICAL_REPLAY_BASE_AUDIT_UNINITIALIZED:
            try:
                persisted = json.loads(
                    HISTORICAL_REPLAY_BASE_AUDIT_CACHE_FILE.read_text(encoding="utf-8")
                )
                persisted_payload = (
                    persisted.get("payload")
                    if isinstance(persisted.get("payload"), dict)
                    else {}
                )
                if (
                    persisted.get("schema") == "codexstock_historical_replay_base_audit_cache_v1"
                    and persisted.get("source_signature") == list(signature)
                    and isinstance(persisted_payload.get("regeneration_queue"), list)
                    and int(_number(persisted_payload.get("regeneration_candidate_count"))) > 0
                ):
                    HISTORICAL_REPLAY_BASE_AUDIT_CACHE = (
                        signature,
                        dict(persisted_payload),
                    )
                    payload = dict(persisted_payload)
                    payload["base_audit_cache_hit"] = True
                    payload["base_audit_cache_source"] = "disk"
                    return payload
            except (OSError, json.JSONDecodeError, TypeError, ValueError):
                pass
        payload = dict(ai_tournament_reconciliation_audit(limit=300, queue_limit=1000, batch_limit=200))
        preview_batches = payload.get("regeneration_batches") if isinstance(payload.get("regeneration_batches"), list) else []
        preview_limit = 20
        all_preview_ids = list(dict.fromkeys(
            str(row.get("replay_id") or "").strip().upper()
            for row in preview_batches
            if isinstance(row, dict) and str(row.get("replay_id") or "").strip()
        ))
        preview_ids = all_preview_ids[:preview_limit]
        preview_contracts = [historical_replay_regeneration_contract(replay_id) for replay_id in preview_ids]
        recoverable_preview = sum(bool(row.get("ok")) for row in preview_contracts)
        missing_preview = sum(row.get("status") == "detail_archive_missing" for row in preview_contracts)
        payload["_source_preview"] = {
            "checked_unique_replay_count": len(preview_ids),
            "recoverable_count": recoverable_preview,
            "detail_archive_missing_count": missing_preview,
            "invalid_archive_count": max(0, len(preview_ids) - recoverable_preview - missing_preview),
            "preview_limit": preview_limit,
            "sample_limited": bool(
                payload.get("regeneration_batch_sample_limited")
                or len(all_preview_ids) > len(preview_ids)
            ),
        }
        HISTORICAL_REPLAY_BASE_AUDIT_CACHE = (signature, dict(payload))
        try:
            cache_record = {
                "schema": "codexstock_historical_replay_base_audit_cache_v1",
                "source_signature": list(signature),
                "saved_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
                "payload": payload,
            }
            target = HISTORICAL_REPLAY_BASE_AUDIT_CACHE_FILE
            target.parent.mkdir(parents=True, exist_ok=True)
            temp = target.with_name(f"{target.name}.{os.getpid()}.tmp")
            temp.write_text(
                json.dumps(cache_record, ensure_ascii=False, separators=(",", ":")),
                encoding="utf-8",
            )
            os.replace(temp, target)
        except OSError:
            pass
        payload["base_audit_cache_hit"] = False
        payload["base_audit_cache_source"] = "computed"
        return payload


def _historical_replay_completion_estimate(
    remaining_count: int,
    worker_status: dict[str, object],
) -> dict[str, object]:
    interval_seconds = max(0, int(_number(worker_status.get("interval_seconds"))))
    closed_day_interval_seconds = max(
        1,
        int(
            _number(worker_status.get("closed_day_success_cooldown_seconds"))
            or interval_seconds
            or 1
        ),
    )
    last_wait_seconds = max(0, int(_number(worker_status.get("last_wait_seconds"))))
    last_result = worker_status.get("last_result") if isinstance(worker_status.get("last_result"), dict) else {}
    last_selection = last_result.get("selection") if isinstance(last_result.get("selection"), dict) else {}
    cadence_seconds = max(0, int(_number(last_selection.get("cadence_seconds"))))
    schedule_mode = str(last_selection.get("schedule_mode") or "standard")
    if cadence_seconds:
        effective_cooldown_seconds = max(interval_seconds, cadence_seconds)
    elif schedule_mode in {"manual_paper_focus_batch", "market_closed_day_full_batch"}:
        effective_cooldown_seconds = last_wait_seconds
    else:
        effective_cooldown_seconds = max(interval_seconds, last_wait_seconds)
    elapsed_seconds = max(0.0, _number(last_result.get("elapsed_seconds")))
    recent_elapsed = sorted(
        value
        for value in (
            max(0.0, _number(item))
            for item in worker_status.get("recent_success_elapsed_seconds", [])
        )
        if value > 0.0
    )
    duration_sample_count = len(recent_elapsed)
    median_elapsed_seconds = (
        recent_elapsed[duration_sample_count // 2]
        if duration_sample_count % 2
        else sum(recent_elapsed[duration_sample_count // 2 - 1 : duration_sample_count // 2 + 1]) / 2.0
    ) if duration_sample_count else elapsed_seconds
    p90_index = max(0, min(duration_sample_count - 1, int((duration_sample_count * 0.9) - 0.000001)))
    p90_elapsed_seconds = recent_elapsed[p90_index] if duration_sample_count else elapsed_seconds
    estimated_seconds_remaining = int(
        round(remaining_count * (effective_cooldown_seconds + median_elapsed_seconds))
    ) if effective_cooldown_seconds or median_elapsed_seconds else None
    conservative_seconds_remaining = int(
        round(remaining_count * (effective_cooldown_seconds + p90_elapsed_seconds))
    ) if effective_cooldown_seconds or p90_elapsed_seconds else None
    full_batch_seconds_remaining = int(
        round(remaining_count * (closed_day_interval_seconds + median_elapsed_seconds))
    ) if closed_day_interval_seconds or median_elapsed_seconds else None
    median_cycle_seconds = effective_cooldown_seconds + median_elapsed_seconds
    conservative_cycle_seconds = effective_cooldown_seconds + p90_elapsed_seconds
    throughput_per_hour = 3600.0 / median_cycle_seconds if median_cycle_seconds > 0 else None
    estimated_duty_cycle_pct = (
        (median_elapsed_seconds / median_cycle_seconds) * 100.0
        if median_cycle_seconds > 0
        else None
    )
    conservative_duty_cycle_pct = (
        (p90_elapsed_seconds / conservative_cycle_seconds) * 100.0
        if conservative_cycle_seconds > 0
        else None
    )
    return {
        "estimated_seconds_remaining": estimated_seconds_remaining,
        "estimated_hours_remaining": round(estimated_seconds_remaining / 3600.0, 2)
        if estimated_seconds_remaining is not None
        else None,
        "conservative_hours_remaining": round(conservative_seconds_remaining / 3600.0, 2)
        if conservative_seconds_remaining is not None
        else None,
        "full_batch_seconds_remaining": full_batch_seconds_remaining,
        "full_batch_hours_remaining": round(full_batch_seconds_remaining / 3600.0, 2)
        if full_batch_seconds_remaining is not None
        else None,
        "last_job_elapsed_seconds": elapsed_seconds or None,
        "median_job_elapsed_seconds": round(median_elapsed_seconds, 2) if median_elapsed_seconds else None,
        "p90_job_elapsed_seconds": round(p90_elapsed_seconds, 2) if p90_elapsed_seconds else None,
        "duration_sample_count": duration_sample_count,
        "estimated_throughput_per_hour": round(throughput_per_hour, 2)
        if throughput_per_hour is not None
        else None,
        "estimated_worker_duty_cycle_pct": round(estimated_duty_cycle_pct, 2)
        if estimated_duty_cycle_pct is not None
        else None,
        "conservative_worker_duty_cycle_pct": round(conservative_duty_cycle_pct, 2)
        if conservative_duty_cycle_pct is not None
        else None,
        "base_interval_seconds": interval_seconds,
        "closed_day_interval_seconds": closed_day_interval_seconds,
        "cadence_seconds": cadence_seconds,
        "cooldown_seconds": effective_cooldown_seconds,
        "schedule_mode": schedule_mode,
        "next_due_at": worker_status.get("next_due_at", ""),
        "next_eligible_at": last_selection.get("next_eligible_at", ""),
        "basis": "remaining * (median_recent_success_elapsed_seconds + cooldown_seconds)",
        "full_batch_basis": "remaining * (median_recent_success_elapsed_seconds + closed_day_interval_seconds)",
        "schedule_disclosure": (
            "Current-lane estimate uses the active weekday throttle. Full-batch estimate assumes continuous "
            "weekend/holiday processing and is not a calendar completion promise."
        ),
        "load_disclosure": (
            "Duty cycle is replay execution time divided by execution plus cooldown; it estimates this worker only, "
            "not total system CPU usage."
        ),
        "estimate_only": True,
    }


def _historical_replay_worker_public_status(
    worker_status: dict[str, object],
    progress: dict[str, object] | None = None,
) -> dict[str, object]:
    """Expose actual worker liveness instead of trusting a persisted running flag."""
    requested_running = bool(worker_status.get("running"))
    thread_alive = (
        bool(worker_status.get("thread_alive"))
        if "thread_alive" in worker_status
        else requested_running
    )
    running = requested_running and thread_alive
    current_replay_id = str(worker_status.get("current_replay_id") or "")
    busy = bool(current_replay_id)
    last_error = str(worker_status.get("last_error") or worker_status.get("last_job_error") or "")
    if requested_running and not thread_alive:
        health_state, health_label = "BROKEN", "스레드 중단"
    elif not requested_running:
        health_state, health_label = "STOPPED", "중지"
    elif busy:
        health_state, health_label = "WORKING", "검증 중"
    elif last_error:
        health_state, health_label = "DEGRADED", "최근 오류"
    else:
        health_state, health_label = "HEALTHY", "정상 대기"

    last_result = worker_status.get("last_result") if isinstance(worker_status.get("last_result"), dict) else {}
    selection = last_result.get("selection") if isinstance(last_result.get("selection"), dict) else {}
    last_success_at = str(worker_status.get("last_success_at") or "")
    progress_payload = progress if isinstance(progress, dict) else {}
    latest_activity = (
        progress_payload.get("latest_activity")
        if isinstance(progress_payload.get("latest_activity"), dict)
        else {}
    )
    if not last_success_at and str(latest_activity.get("status") or "") == "verified_replacement_candidate":
        last_success_at = str(latest_activity.get("generated_at") or "")

    return {
        "running": running,
        "configured_running": requested_running,
        "thread_alive": thread_alive,
        "health_state": health_state,
        "health_label": health_label,
        "busy": busy,
        "current_replay_id": current_replay_id,
        "interval_seconds": max(0, int(_number(worker_status.get("interval_seconds")))),
        "cycle_count": int(_number(worker_status.get("cycle_count"))),
        "restored_from_state": bool(worker_status.get("restored_from_state")),
        "next_due_at": worker_status.get("next_due_at", ""),
        "last_check_at": worker_status.get("last_check_at", ""),
        "last_success_at": last_success_at,
        "last_wait_reason": worker_status.get("last_wait_reason", ""),
        "last_wait_seconds": max(0, int(_number(worker_status.get("last_wait_seconds")))),
        "schedule_mode": str(selection.get("schedule_mode") or "standard"),
        "cadence_seconds": max(0, int(_number(selection.get("cadence_seconds")))),
        "next_eligible_at": selection.get("next_eligible_at", ""),
        "paper_only": True,
        "live_order_allowed": False,
    }


def historical_replay_regeneration_status() -> dict[str, object]:
    """Expose honest recovery progress from latest append-only verdicts."""
    audit = _historical_replay_base_audit()
    campaign = _historical_replay_regeneration_campaign(audit)
    campaign_ids = set(campaign.get("source_replay_ids", []))
    total_candidates = int(_number(campaign.get("target_count")))
    ledger_progress = _historical_replay_regeneration_ledger_progress(total_candidates, campaign_ids)
    source_preview = audit.get("_source_preview") if isinstance(audit.get("_source_preview"), dict) else {}
    completed = int(ledger_progress["resolved_count"])
    worker = globals().get("HISTORICAL_REPLAY_REGENERATION_WORKER")
    worker_status = worker.status() if worker is not None else {}
    remaining_count = int(ledger_progress["remaining_candidate_count"])
    completion_estimate = _historical_replay_completion_estimate(remaining_count, worker_status)
    incremental_plan = {
        "schema": "codexstock_historical_replay_incremental_plan_v1",
        "current_evidence_skipped_count": int(ledger_progress.get("resolved_count") or 0),
        "pending_evidence_upgrade_count": int(ledger_progress.get("legacy_resolved_count") or 0),
        "genuinely_unattempted_count": max(
            0,
            int(ledger_progress.get("unattempted_count") or 0)
            - int(ledger_progress.get("legacy_resolved_count") or 0),
        ),
        "retryable_failure_count": int(ledger_progress.get("retryable_failure_count") or 0),
        "blocked_failure_count": int(ledger_progress.get("blocked_failure_count") or 0),
        "remaining_count": remaining_count,
        "selection_rule": "skip_current_evidence_then_upgrade_legacy_or_unattempted_only",
        "append_only_checkpoint": True,
        "checkpoint_path": str(HISTORICAL_REPLAY_REGENERATION_FILE),
        "old_record_rewritten": False,
        "paper_only": True,
        "automatic_promotion": False,
        "live_order_allowed": False,
    }
    return {
        "ok": True,
        "status": "complete" if total_candidates and completed >= total_candidates else "in_progress",
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "progress": {
            key: value
            for key, value in ledger_progress.items()
            if key not in {"latest_verdict_counts", "unique_source_replay_count"}
        },
        "latest_verdict_counts": ledger_progress["latest_verdict_counts"],
        "unique_source_replay_count": ledger_progress["unique_source_replay_count"],
        "worker": _historical_replay_worker_public_status(worker_status, ledger_progress),
        "completion_estimate": completion_estimate,
        "incremental_plan": incremental_plan,
        "focus_mode": historical_replay_focus_mode_status(),
        "source_preview": dict(source_preview),
        "audit": {
            "status": audit.get("status") or (audit.get("summary") or {}).get("status"),
            "candidate_count": total_candidates,
            "official_return_claim_allowed": audit.get("official_return_claim_allowed"),
            "base_audit_cache_hit": bool(audit.get("base_audit_cache_hit")),
            "source_signature": list(_historical_replay_status_file_signature(AI_TOURNAMENT_FILE)),
        },
        "campaign": {
            key: value
            for key, value in campaign.items()
            if key != "source_replay_ids"
        },
        "ledger_path": str(HISTORICAL_REPLAY_REGENERATION_FILE),
        "automatic_promotion": False,
        "paper_only": True,
        "live_order_allowed": False,
    }


def _historical_replay_status_file_signature(path: Path) -> tuple[int, int]:
    try:
        stat = path.stat()
        return stat.st_mtime_ns, stat.st_size
    except OSError:
        return 0, 0


def _overlay_live_replay_worker_status(payload: dict[str, object]) -> dict[str, object]:
    """Keep expensive ledger status cached while exposing current worker liveness."""
    worker = globals().get("HISTORICAL_REPLAY_REGENERATION_WORKER")
    worker_status = worker.status() if worker is not None else {}
    updated = dict(payload)
    progress = updated.get("progress") if isinstance(updated.get("progress"), dict) else {}
    remaining_count = int(_number(progress.get("remaining_candidate_count")))
    updated["worker"] = _historical_replay_worker_public_status(worker_status, progress)
    updated["completion_estimate"] = _historical_replay_completion_estimate(
        remaining_count,
        worker_status,
    )
    return updated


def cached_historical_replay_regeneration_status() -> dict[str, object]:
    """Avoid repeating the full 756-record audit until its source files change."""
    global HISTORICAL_REPLAY_REGENERATION_STATUS_CACHE
    cache_schema_version = "historical-replay-regeneration-status-cache.v4"
    signature = (
        _historical_replay_status_file_signature(AI_TOURNAMENT_FILE),
        _historical_replay_status_file_signature(HISTORICAL_REPLAY_REGENERATION_FILE),
        _historical_replay_status_file_signature(HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE),
    )
    with HISTORICAL_REPLAY_REGENERATION_STATUS_CACHE_LOCK:
        cached = HISTORICAL_REPLAY_REGENERATION_STATUS_CACHE
        if cached and cached[0] == signature:
            payload = dict(cached[1])
            payload["cache_hit"] = True
            payload["cache_source"] = "memory"
            return _overlay_live_replay_worker_status(payload)
        try:
            persisted = json.loads(
                HISTORICAL_REPLAY_REGENERATION_STATUS_CACHE_FILE.read_text(encoding="utf-8")
            )
            persisted_signature = persisted.get("source_signature") if isinstance(persisted, dict) else None
            persisted_payload = persisted.get("payload") if isinstance(persisted, dict) else None
            if (
                persisted.get("schema_version") == cache_schema_version
                and persisted_signature == [list(item) for item in signature]
                and isinstance(persisted_payload, dict)
            ):
                HISTORICAL_REPLAY_REGENERATION_STATUS_CACHE = (signature, dict(persisted_payload))
                payload = dict(persisted_payload)
                payload["cache_hit"] = True
                payload["cache_source"] = "disk"
                return _overlay_live_replay_worker_status(payload)
        except (OSError, json.JSONDecodeError):
            pass
        payload = historical_replay_regeneration_status()
        HISTORICAL_REPLAY_REGENERATION_STATUS_CACHE = (signature, dict(payload))
        cache_record = {
            "schema_version": cache_schema_version,
            "source_signature": [list(item) for item in signature],
            "saved_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
            "payload": payload,
        }
        try:
            target_path = HISTORICAL_REPLAY_REGENERATION_STATUS_CACHE_FILE
            target_path.parent.mkdir(parents=True, exist_ok=True)
            temp_path = target_path.with_name(f"{target_path.name}.{os.getpid()}.tmp")
            temp_path.write_text(
                json.dumps(cache_record, ensure_ascii=False, indent=2),
                encoding="utf-8",
            )
            os.replace(temp_path, target_path)
        except OSError:
            pass
        payload = dict(payload)
        payload["cache_hit"] = False
        payload["cache_source"] = "computed"
        return _overlay_live_replay_worker_status(payload)


def run_historical_replay_regeneration_manual_batch(max_cycles: int = 1) -> dict[str, object]:
    """Run a bounded manual Paper reconciliation batch while respecting worker cooldowns."""
    requested_cycles = max(1, min(int(_number(max_cycles) or 1), 5))
    before = cached_historical_replay_regeneration_status()
    before_progress = before.get("progress") if isinstance(before.get("progress"), dict) else {}
    focus = build_operating_focus()
    if focus.get("market_priority_active") or focus.get("market_open"):
        return {
            "ok": True,
            "status": "deferred_to_market_closed_window",
            "stop_reason": "market_priority_active",
            "requested_cycles": requested_cycles,
            "executed_cycles": 0,
            "verified_delta": 0,
            "before_label": before_progress.get("label"),
            "after_label": before_progress.get("label"),
            "before_progress": before_progress,
            "after_progress": before_progress,
            "current_focus_mode": focus.get("mode", ""),
            "current_market_phase": focus.get("market_phase", ""),
            "current_market_priority_active": bool(focus.get("market_priority_active")),
            "current_market_open": bool(focus.get("market_open")),
            "operator_message": "과거장 수동 대사 보류: 장전/장중 매매 우선 모드에서는 실행하지 않습니다.",
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
            "unverified_result_affects_score": False,
            "unverified_result_affects_live_candidate": False,
        }
    worker = globals().get("HISTORICAL_REPLAY_REGENERATION_WORKER")
    if worker is None:
        return {
            "ok": False,
            "status": "worker_missing",
            "requested_cycles": requested_cycles,
            "executed_cycles": 0,
            "verified_delta": 0,
            "before_progress": before_progress,
            "after_progress": before_progress,
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
        }
    results: list[dict[str, object]] = []
    stop_reason = "max_cycles_reached"
    for _ in range(requested_cycles):
        result = worker.run_once()
        results.append(
            {
                "ok": bool(result.get("ok")),
                "status": result.get("status"),
                "replay_id": result.get("replay_id"),
                "elapsed_seconds": result.get("elapsed_seconds"),
                "selection_status": (
                    result.get("selection", {}).get("status")
                    if isinstance(result.get("selection"), dict)
                    else None
                ),
                "paper_only": True,
                "live_order_allowed": False,
            }
        )
        status = str(result.get("status") or "")
        if status not in {"verified_replacement_candidate", "quarantined_new_result"}:
            stop_reason = status or "no_result_status"
            break
        cooldown_seconds = 0
        if hasattr(worker, "_cooldown_for_result"):
            try:
                cooldown_seconds = int(worker._cooldown_for_result(result)[0])
            except Exception:
                cooldown_seconds = 0
        if cooldown_seconds > int(_number(worker.status().get("interval_seconds")) or 0):
            stop_reason = "cooldown_required"
            break
    # Force a fresh status build so the caller sees the ledger row just appended.
    global HISTORICAL_REPLAY_REGENERATION_STATUS_CACHE
    with HISTORICAL_REPLAY_REGENERATION_STATUS_CACHE_LOCK:
        HISTORICAL_REPLAY_REGENERATION_STATUS_CACHE = None
    after = cached_historical_replay_regeneration_status()
    after_progress = after.get("progress") if isinstance(after.get("progress"), dict) else {}
    verified_delta = int(_number(after_progress.get("resolved_count"))) - int(_number(before_progress.get("resolved_count")))
    return {
        "ok": bool(results),
        "status": "completed" if stop_reason == "max_cycles_reached" else "stopped",
        "stop_reason": stop_reason,
        "requested_cycles": requested_cycles,
        "executed_cycles": len(results),
        "verified_delta": verified_delta,
        "before_label": before_progress.get("label"),
        "after_label": after_progress.get("label"),
        "before_progress": before_progress,
        "after_progress": after_progress,
        "worker": after.get("worker", {}),
        "results": results,
        "paper_only": True,
        "automatic_promotion": False,
        "live_order_allowed": False,
        "unverified_result_affects_score": False,
        "unverified_result_affects_live_candidate": False,
    }


def _build_responsive_historical_replay_regeneration_status() -> dict[str, object]:
    """Build the accurate progress snapshot outside request latency."""
    payload = dict(cached_historical_replay_regeneration_status())
    payload.pop("cache_hit", None)
    payload.pop("cache_source", None)
    payload["responsive_source_signature"] = [
        list(_historical_replay_status_file_signature(AI_TOURNAMENT_FILE)),
        list(_historical_replay_status_file_signature(HISTORICAL_REPLAY_REGENERATION_FILE)),
        list(_historical_replay_status_file_signature(HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE)),
    ]
    return payload


def _historical_replay_responsive_cache_is_current(payload: dict[str, object]) -> bool:
    expected = [
        list(_historical_replay_status_file_signature(AI_TOURNAMENT_FILE)),
        list(_historical_replay_status_file_signature(HISTORICAL_REPLAY_REGENERATION_FILE)),
        list(_historical_replay_status_file_signature(HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE)),
    ]
    return payload.get("responsive_source_signature") == expected


def _live_historical_replay_progress_overlay(
    payload: dict[str, object],
    cached_progress: dict[str, object],
) -> tuple[dict[str, object], bool]:
    """Refresh cheap append-only counters while the full audit cache rebuilds."""
    source_signature = payload.get("responsive_source_signature")
    if not isinstance(source_signature, list) or len(source_signature) != 3:
        return dict(cached_progress), False
    campaign_total, campaign_ids = _historical_replay_campaign_manifest_scope()
    if campaign_total <= 0:
        return dict(cached_progress), False
    return (
        _historical_replay_regeneration_ledger_progress(
            campaign_total,
            campaign_ids or None,
        ),
        True,
    )


HISTORICAL_REPLAY_RESPONSIVE_STATUS_CACHE = StaleWhileRefreshStatusCache(
    builder=_build_responsive_historical_replay_regeneration_status,
    cache_path=HISTORICAL_REPLAY_RESPONSIVE_STATUS_CACHE_FILE,
    schema_version="historical-replay-responsive-status.v2",
    ttl_seconds=2,
    durable_validator=_historical_replay_responsive_cache_is_current,
)


def responsive_historical_replay_regeneration_status() -> dict[str, object]:
    """Return progress immediately while a changed ledger refreshes in background."""
    payload = HISTORICAL_REPLAY_RESPONSIVE_STATUS_CACHE.get()
    cache_expired = bool(payload.get("stale"))
    source_signature_current = _historical_replay_responsive_cache_is_current(payload)
    source_snapshot_stale = not source_signature_current
    progress = dict(payload.get("progress") or {})
    live_ledger_overlay = False
    # Never rescan the append-only replay ledger on an HTTP request. The
    # stale-while-refresh cache rebuilds changed evidence off-thread; until
    # then the previous signed snapshot stays visible and explicitly stale.
    progress["snapshot_stale"] = source_snapshot_stale and not live_ledger_overlay
    progress["detail_snapshot_stale"] = source_snapshot_stale
    progress["live_ledger_overlay"] = live_ledger_overlay
    progress["cache_expired"] = cache_expired
    progress["source_signature_current"] = source_signature_current
    progress["refreshing"] = bool(payload.get("refreshing"))
    progress["confirmed"] = source_signature_current or live_ledger_overlay
    if live_ledger_overlay and str(progress.get("label") or ""):
        progress["display_label"] = f"{progress['label']} (원장 확정·상세 갱신 중)"
    elif progress.get("snapshot_stale") and str(progress.get("label") or ""):
        progress["display_label"] = f"{progress['label']} (갱신 중·미확정)"
    else:
        progress["display_label"] = str(progress.get("label") or "")
    return _overlay_live_replay_worker_status(
        {
            **payload,
            "stale": source_snapshot_stale,
            "cache_expired": cache_expired,
            "source_signature_current": source_signature_current,
            "source_state": (
                "CONFIRMED_CACHED"
                if source_signature_current
                else "LIVE_LEDGER_OVERLAY_REFRESHING"
                if live_ledger_overlay
                else "SOURCE_CHANGED_REFRESHING"
            ),
            "progress": progress,
        }
    )


def historical_replay_worker_startup_gate(
    status: dict[str, object] | None = None,
) -> dict[str, object]:
    """Keep a completed replay campaign asleep until its source files change."""
    replay_status = (
        dict(status)
        if isinstance(status, dict)
        else responsive_historical_replay_regeneration_status()
    )
    progress = (
        replay_status.get("progress")
        if isinstance(replay_status.get("progress"), dict)
        else {}
    )
    remaining_count = max(
        0,
        int(_number(progress.get("remaining_candidate_count"))),
    )
    source_confirmed = bool(
        progress.get("confirmed") is True
        or replay_status.get("source_signature_current") is True
    )
    completion_confirmed = bool(
        str(replay_status.get("status") or "").strip().lower() == "complete"
        and remaining_count == 0
        and source_confirmed
    )
    return {
        "ok": True,
        "schema": "codexstock_replay_worker_startup_gate_v1",
        "worker_start_required": not completion_confirmed,
        "completion_confirmed": completion_confirmed,
        "remaining_candidate_count": remaining_count,
        "source_confirmed": source_confirmed,
        "reason": (
            "completed_campaign_auto_sleep"
            if completion_confirmed
            else "replay_work_or_source_confirmation_pending"
        ),
        "paper_only": True,
        "automatic_promotion": False,
        "live_order_allowed": False,
    }


def historical_replay_data_gap_worker_startup_gate(
    replay_gate: dict[str, object] | None = None,
) -> dict[str, object]:
    """Do not wake the Stage 2 backfill worker after a confirmed completion."""
    gate = (
        dict(replay_gate)
        if isinstance(replay_gate, dict)
        else historical_replay_worker_startup_gate()
    )
    completion_confirmed = bool(gate.get("completion_confirmed"))
    return {
        "ok": True,
        "schema": "codexstock_replay_data_gap_worker_startup_gate_v1",
        "worker_start_required": not completion_confirmed,
        "completion_confirmed": completion_confirmed,
        "reason": (
            "completed_campaign_has_no_pending_stage2_work"
            if completion_confirmed
            else "replay_completion_or_stage2_work_pending"
        ),
        "paper_only": True,
        "automatic_promotion": False,
        "live_order_allowed": False,
    }


def _historical_replay_verified_certificate_cache_signature() -> tuple[tuple[str, int, int], ...]:
    paths = (
        AI_TOURNAMENT_FILE,
        HISTORICAL_REPLAY_REGENERATION_FILE,
        HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE,
        HISTORICAL_REPLAY_EVIDENCE_MILESTONE_FILE,
        HISTORICAL_REPLAY_COMPLETION_CERTIFICATE_FILE,
    )
    return tuple(
        (str(path.resolve()), *_historical_replay_status_file_signature(path))
        for path in paths
    )


def _cached_verified_historical_replay_completion_certificate() -> dict[str, object]:
    global HISTORICAL_REPLAY_VERIFIED_CERTIFICATE_CACHE
    signature = _historical_replay_verified_certificate_cache_signature()
    with HISTORICAL_REPLAY_VERIFIED_CERTIFICATE_CACHE_LOCK:
        cached = HISTORICAL_REPLAY_VERIFIED_CERTIFICATE_CACHE
        if cached and cached[0] == signature:
            return {
                **copy.deepcopy(cached[1]),
                "certificate_fast_cache_hit": True,
                "certificate_fast_cache_source": "memory",
            }
        try:
            record = json.loads(
                HISTORICAL_REPLAY_VERIFIED_CERTIFICATE_CACHE_FILE.read_text(encoding="utf-8")
            )
            persisted_signature = record.get("source_signature") if isinstance(record, dict) else None
            persisted_payload = record.get("payload") if isinstance(record, dict) else None
            persisted_hash = str(record.get("payload_sha256") or "") if isinstance(record, dict) else ""
            computed_hash = (
                hashlib.sha256(
                    json.dumps(
                        persisted_payload,
                        ensure_ascii=False,
                        sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest()
                if isinstance(persisted_payload, dict)
                else ""
            )
            if (
                record.get("schema_version") == "verified-certificate-fast-cache.v1"
                and persisted_signature == [list(item) for item in signature]
                and isinstance(persisted_payload, dict)
                and persisted_payload.get("ok") is True
                and hmac.compare_digest(persisted_hash, computed_hash)
            ):
                HISTORICAL_REPLAY_VERIFIED_CERTIFICATE_CACHE = (
                    signature,
                    copy.deepcopy(persisted_payload),
                )
                return {
                    **copy.deepcopy(persisted_payload),
                    "certificate_fast_cache_hit": True,
                    "certificate_fast_cache_source": "disk",
                }
        except (OSError, json.JSONDecodeError, TypeError, ValueError):
            pass
        certificate = load_historical_replay_completion_certificate()
        if certificate.get("ok") is True:
            HISTORICAL_REPLAY_VERIFIED_CERTIFICATE_CACHE = (
                signature,
                copy.deepcopy(certificate),
            )
            durable_payload = copy.deepcopy(certificate)
            payload_hash = hashlib.sha256(
                json.dumps(
                    durable_payload,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            record = {
                "schema_version": "verified-certificate-fast-cache.v1",
                "source_signature": [list(item) for item in signature],
                "saved_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
                "payload_sha256": payload_hash,
                "payload": durable_payload,
            }
            try:
                target_path = HISTORICAL_REPLAY_VERIFIED_CERTIFICATE_CACHE_FILE
                target_path.parent.mkdir(parents=True, exist_ok=True)
                temp_path = target_path.with_name(f"{target_path.name}.{os.getpid()}.tmp")
                temp_path.write_text(
                    json.dumps(record, ensure_ascii=False),
                    encoding="utf-8",
                )
                os.replace(temp_path, target_path)
            except OSError:
                pass
        else:
            HISTORICAL_REPLAY_VERIFIED_CERTIFICATE_CACHE = None
        return {
            **certificate,
            "certificate_fast_cache_hit": False,
            "certificate_fast_cache_source": "validated",
        }


def historical_replay_completion_audit(
    *,
    include_stored_certificate_summary: bool = False,
) -> dict[str, object]:
    status = cached_historical_replay_regeneration_status()
    progress = status.get("progress") if isinstance(status.get("progress"), dict) else {}
    campaign = status.get("campaign") if isinstance(status.get("campaign"), dict) else {}
    target_count = int(_number(campaign.get("target_count")))
    resolved_count = int(_number(progress.get("resolved_count")))
    remaining_count = int(_number(progress.get("remaining_candidate_count")))
    worker_status = HISTORICAL_REPLAY_REGENERATION_WORKER.status()
    if target_count > 0 and resolved_count == target_count and remaining_count == 0:
        certificate = _cached_verified_historical_replay_completion_certificate()
        if (
            certificate.get("ok") is True
            and certificate.get("completion_verified") is True
            and int(_number(certificate.get("resolved_count"))) == target_count
            and int(_number(certificate.get("expected_total"))) == target_count
        ):
            operating_focus = build_operating_focus()
            completion_estimate = _historical_replay_completion_estimate(0, worker_status)
            fast_result = {
                **certificate,
                "schema": "codexstock_historical_replay_completion_audit_v3",
                "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
                "certificate_path": str(HISTORICAL_REPLAY_COMPLETION_CERTIFICATE_FILE),
                "ledger_path": str(HISTORICAL_REPLAY_REGENERATION_FILE),
                "data_gap_queue_path": str(HISTORICAL_REPLAY_DATA_GAP_QUEUE_FILE),
                "completion_estimate": completion_estimate,
                "incremental_plan": status.get("incremental_plan", certificate.get("incremental_plan", {})),
                "focus_mode": historical_replay_focus_mode_status(),
                "next_action": "completion_certificate_available",
                "current_run_allowed": False,
                "current_market_priority_active": bool(operating_focus.get("market_priority_active")),
                "current_market_open": bool(operating_focus.get("market_open")),
                "current_market_phase": operating_focus.get("market_phase", ""),
                "current_focus_mode": operating_focus.get("mode", ""),
                "operator_message": (
                    f"Historical replay {resolved_count}/{target_count} is already certified; "
                    "unchanged evidence was reused instead of rescanning all artifacts."
                ),
                "completion_audit_cache_hit": True,
                "completion_audit_cache_source": "verified_completion_certificate",
                "deep_rescan_skipped": True,
                "paper_only": True,
                "automatic_promotion": False,
                "live_order_allowed": False,
            }
            if include_stored_certificate_summary:
                fast_result["_stored_certificate_summary"] = {
                    key: certificate.get(key)
                    for key in (
                        "ok",
                        "status",
                        "certificate_id",
                        "issued_at",
                        "campaign_id",
                        "certificate_sha256",
                        "hash_valid",
                        "source_signature_current",
                        "path",
                    )
                    if certificate.get(key) not in (None, "")
                }
            return fast_result
    data_gap_status = historical_replay_data_gap_queue(record=False)
    evidence_audit = historical_replay_evidence_audit(
        deep=remaining_count == 0,
    )
    _, campaign_ids = _historical_replay_campaign_manifest_scope()
    result = audit_replay_completion(
        progress=progress,
        unique_source_replay_count=int(_number(status.get("unique_source_replay_count"))),
        worker_status=worker_status,
        data_gap_status=data_gap_status,
        evidence_audit=evidence_audit,
        expected_total=int(_number(campaign.get("target_count"))),
        campaign_id_count=len(campaign_ids),
    )
    milestone_status = historical_replay_evidence_milestone_status()
    completion_estimate = _historical_replay_completion_estimate(
        int(_number(result.get("remaining_count"))),
        worker_status,
    )
    operating_focus = build_operating_focus()
    if result.get("completion_verified"):
        next_action = "completion_certificate_available"
        current_run_allowed = False
    elif str(completion_estimate.get("schedule_mode") or "") in {
        "market_priority_deferred",
        "premarket_priority_deferred",
    }:
        next_action = "defer_to_market_closed_window"
        current_run_allowed = False
    elif operating_focus.get("market_priority_active") or operating_focus.get("market_open"):
        next_action = "defer_to_market_closed_window"
        current_run_allowed = False
    else:
        next_action = "continue_bounded_paper_replay_reconciliation"
        current_run_allowed = True
    return {
        **result,
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "certificate_path": str(HISTORICAL_REPLAY_COMPLETION_CERTIFICATE_FILE),
        "ledger_path": str(HISTORICAL_REPLAY_REGENERATION_FILE),
        "data_gap_queue_path": str(HISTORICAL_REPLAY_DATA_GAP_QUEUE_FILE),
        "completion_estimate": completion_estimate,
        "incremental_plan": status.get("incremental_plan", {}),
        "focus_mode": historical_replay_focus_mode_status(),
        "next_action": next_action,
        "current_run_allowed": current_run_allowed,
        "current_market_priority_active": bool(operating_focus.get("market_priority_active")),
        "current_market_open": bool(operating_focus.get("market_open")),
        "current_market_phase": operating_focus.get("market_phase", ""),
        "current_focus_mode": operating_focus.get("mode", ""),
        "operator_message": (
            f"과거장 대사 {result.get('progress_label') or '-'} / 남은 {int(_number(result.get('remaining_count')))}건 / "
            f"다음 조치 {next_action}"
        ),
        "evidence_audit": evidence_audit,
        "deep_evidence_gate": milestone_status.get("deep_verification", {}),
        "completion_audit_cache_hit": False,
        "completion_audit_cache_source": "deep_recomputed",
        "deep_rescan_skipped": False,
    }


HISTORICAL_REPLAY_JOURNAL_SIGNATURE_CACHE: tuple[float, dict[str, object]] | None = None
HISTORICAL_REPLAY_JOURNAL_SIGNATURE_LOCK = threading.Lock()


def _historical_replay_journal_source_signature(force: bool = False) -> dict[str, object]:
    global HISTORICAL_REPLAY_JOURNAL_SIGNATURE_CACHE
    try:
        ttl_seconds = max(5, min(int(os.getenv("CODEXSTOCK_REPLAY_JOURNAL_SIGNATURE_TTL_SECONDS", "60") or 60), 600))
    except ValueError:
        ttl_seconds = 60
    now_mono = time.monotonic()
    with HISTORICAL_REPLAY_JOURNAL_SIGNATURE_LOCK:
        cached = HISTORICAL_REPLAY_JOURNAL_SIGNATURE_CACHE
        if not force and cached and now_mono - cached[0] <= ttl_seconds:
            return dict(cached[1])

        digest = hashlib.sha256()
        file_count = 0
        total_bytes = 0
        latest_mtime_ns = 0
        try:
            journal_paths = sorted(TRADE_JOURNAL_DIR.glob("HREPLAY-*.json"))
        except OSError:
            journal_paths = []
        for path in journal_paths:
            try:
                stat = path.stat()
            except OSError:
                continue
            file_count += 1
            total_bytes += int(stat.st_size)
            latest_mtime_ns = max(latest_mtime_ns, int(stat.st_mtime_ns))
            digest.update(
                f"{path.name}|{stat.st_size}|{stat.st_mtime_ns}\n".encode("utf-8")
            )
        result = {
            "schema": "codexstock_replay_journal_source_signature_v1",
            "file_count": file_count,
            "total_bytes": total_bytes,
            "latest_mtime_ns": latest_mtime_ns,
            "metadata_sha256": digest.hexdigest(),
            "cache_ttl_seconds": ttl_seconds,
        }
        HISTORICAL_REPLAY_JOURNAL_SIGNATURE_CACHE = (time.monotonic(), result)
        return dict(result)


def _historical_replay_completion_source_signature() -> dict[str, object]:
    """Anchor a certificate to the frozen campaign, not growing training logs."""
    milestone_status = historical_replay_evidence_milestone_status()
    deep = (
        milestone_status.get("deep_verification")
        if isinstance(milestone_status.get("deep_verification"), dict)
        else {}
    )
    target_count = int(_number(milestone_status.get("target_count")))
    passed_milestones = {
        int(_number(value))
        for value in milestone_status.get("passed_milestones", [])
        if int(_number(value)) > 0
    }
    return {
        "schema": "codexstock_historical_replay_completion_source_signature_v3",
        "campaign_id": str(milestone_status.get("campaign_id") or ""),
        "target_count": target_count,
        "campaign_scope_hash": str(milestone_status.get("campaign_scope_hash") or ""),
        "required_evidence_schema_version": str(
            milestone_status.get("required_evidence_schema_version") or ""
        ),
        "required_execution_timing_model_version": str(
            milestone_status.get("required_execution_timing_model_version") or ""
        ),
        "required_replay_data_bundle_evidence_schema": str(
            milestone_status.get("required_replay_data_bundle_evidence_schema") or ""
        ),
        "resolved_count": int(_number(milestone_status.get("resolved_count"))),
        "verified_through_count": int(_number(deep.get("verified_through_count"))),
        "last_verified_at": str(deep.get("last_verified_at") or ""),
        "ledger_evidence_hash": str(deep.get("ledger_evidence_hash") or ""),
        "journal_evidence_hash": str(deep.get("journal_evidence_hash") or ""),
        "replay_evidence_hash": str(deep.get("replay_evidence_hash") or ""),
        "evidence_bundle_hash": str(deep.get("evidence_bundle_hash") or ""),
        "audited_scope_hash": str(deep.get("audited_scope_hash") or ""),
        "evidence_bundle_hash_contract": str(
            deep.get("evidence_bundle_hash_contract") or ""
        ),
        "artifact_hash_contract": str(deep.get("artifact_hash_contract") or ""),
        "artifact_anchor_required_count": int(
            _number(deep.get("artifact_anchor_required_count"))
        ),
        "artifact_anchor_verified_count": int(
            _number(deep.get("artifact_anchor_verified_count"))
        ),
        "artifact_anchor_mismatch_count": int(
            _number(deep.get("artifact_anchor_mismatch_count"))
        ),
        "artifact_anchor_deep_verified": deep.get("artifact_anchor_deep_verified") is True,
        "final_milestone_passed": target_count > 0 and target_count in passed_milestones,
    }


def _historical_replay_certificate_hash(payload: dict[str, object]) -> str:
    canonical = dict(payload)
    canonical.pop("certificate_sha256", None)
    return hashlib.sha256(
        json.dumps(
            canonical,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def load_historical_replay_completion_certificate() -> dict[str, object]:
    try:
        payload = json.loads(
            HISTORICAL_REPLAY_COMPLETION_CERTIFICATE_FILE.read_text(encoding="utf-8")
        )
    except (FileNotFoundError, OSError, json.JSONDecodeError):
        return {
            "ok": False,
            "status": "certificate_missing",
            "path": str(HISTORICAL_REPLAY_COMPLETION_CERTIFICATE_FILE),
            "paper_only": True,
            "live_order_allowed": False,
        }
    if not isinstance(payload, dict):
        payload = {}
    stored_hash = str(payload.get("certificate_sha256") or "")
    hash_valid = bool(stored_hash) and hmac.compare_digest(
        stored_hash,
        _historical_replay_certificate_hash(payload),
    )
    source_signature_current = payload.get("source_signature") == (
        _historical_replay_completion_source_signature()
    )
    contract_valid = bool(
        payload.get("schema") == "codexstock_historical_replay_completion_certificate_v3"
        and payload.get("source_signature_version") == 3
        and payload.get("certificate_allowed") is True
        and payload.get("completion_verified") is True
        and payload.get("paper_only") is True
        and payload.get("automatic_promotion") is False
        and payload.get("live_order_allowed") is False
    )
    ok = contract_valid and hash_valid and source_signature_current
    return {
        **payload,
        "ok": ok,
        "status": (
            "certificate_verified"
            if ok
            else "certificate_stale"
            if contract_valid and hash_valid and not source_signature_current
            else "certificate_invalid"
        ),
        "hash_valid": hash_valid,
        "source_signature_current": source_signature_current,
        "path": str(HISTORICAL_REPLAY_COMPLETION_CERTIFICATE_FILE),
        "paper_only": True,
        "live_order_allowed": False,
    }


def persist_historical_replay_completion_certificate(
    audit_result: dict[str, object] | None = None,
) -> dict[str, object]:
    audit = dict(audit_result) if isinstance(audit_result, dict) else historical_replay_completion_audit()
    if not bool(audit.get("ok")) or not bool(audit.get("certificate_allowed")):
        return {
            **audit,
            "certificate_persisted": False,
            "certificate_path": str(HISTORICAL_REPLAY_COMPLETION_CERTIFICATE_FILE),
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
        }
    evidence = audit.get("evidence_audit") if isinstance(audit.get("evidence_audit"), dict) else {}
    required_evidence_hashes = {
        key: str(evidence.get(key) or "")
        for key in (
            "ledger_evidence_hash",
            "journal_evidence_hash",
            "replay_evidence_hash",
            "evidence_bundle_hash",
        )
    }
    invalid_evidence_hashes = sorted(
        key
        for key, value in required_evidence_hashes.items()
        if not re.fullmatch(r"[0-9a-f]{64}", value)
    )
    if invalid_evidence_hashes:
        return {
            **audit,
            "ok": False,
            "status": "certificate_evidence_hashes_invalid",
            "certificate_persisted": False,
            "invalid_evidence_hashes": invalid_evidence_hashes,
            "certificate_path": str(HISTORICAL_REPLAY_COMPLETION_CERTIFICATE_FILE),
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
        }
    source_signature = _historical_replay_completion_source_signature()
    signature_hashes_match = all(
        str(source_signature.get(key) or "") == value
        for key, value in required_evidence_hashes.items()
    )
    target_count = int(_number(source_signature.get("target_count")))
    source_signature_valid = bool(
        source_signature.get("schema")
        == "codexstock_historical_replay_completion_source_signature_v3"
        and source_signature.get("final_milestone_passed") is True
        and target_count > 0
        and int(_number(source_signature.get("resolved_count"))) == target_count
        and int(_number(source_signature.get("verified_through_count"))) == target_count
        and int(_number(source_signature.get("artifact_anchor_required_count"))) == target_count
        and int(_number(source_signature.get("artifact_anchor_verified_count"))) == target_count
        and int(_number(source_signature.get("artifact_anchor_mismatch_count"))) == 0
        and source_signature.get("artifact_anchor_deep_verified") is True
        and signature_hashes_match
    )
    if not source_signature_valid:
        return {
            **audit,
            "ok": False,
            "status": "certificate_source_signature_invalid",
            "certificate_persisted": False,
            "source_signature": source_signature,
            "signature_hashes_match": signature_hashes_match,
            "certificate_path": str(HISTORICAL_REPLAY_COMPLETION_CERTIFICATE_FILE),
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
        }
    issued_at = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
    certificate = {
        **audit,
        "schema": "codexstock_historical_replay_completion_certificate_v3",
        "source_signature_version": 3,
        "certificate_id": f"HRCERT-{int(time.time() * 1000)}",
        "issued_at": issued_at,
        "campaign_id": evidence.get("campaign_id", ""),
        "source_signature": source_signature,
        "ledger_evidence_hash": evidence.get("ledger_evidence_hash"),
        "journal_evidence_hash": evidence.get("journal_evidence_hash"),
        "replay_evidence_hash": evidence.get("replay_evidence_hash"),
        "evidence_bundle_hash": evidence.get("evidence_bundle_hash"),
        "certificate_persisted": True,
        "certificate_path": str(HISTORICAL_REPLAY_COMPLETION_CERTIFICATE_FILE),
        "paper_only": True,
        "automatic_promotion": False,
        "live_order_allowed": False,
    }
    certificate["certificate_sha256"] = _historical_replay_certificate_hash(certificate)
    target = HISTORICAL_REPLAY_COMPLETION_CERTIFICATE_FILE
    try:
        target.parent.mkdir(parents=True, exist_ok=True)
        temp_path = target.with_name(f"{target.name}.{os.getpid()}.tmp")
        temp_path.write_text(
            json.dumps(certificate, ensure_ascii=False, indent=2, sort_keys=True),
            encoding="utf-8",
        )
        os.replace(temp_path, target)
    except OSError as exc:
        return {
            **certificate,
            "ok": False,
            "status": "certificate_write_failed",
            "certificate_persisted": False,
            "error": f"{type(exc).__name__}: {exc}"[:300],
        }
    return load_historical_replay_completion_certificate()


def refresh_historical_replay_completion_certificate() -> dict[str, object]:
    """Reissue a Paper certificate from one in-process, fail-closed audit snapshot."""
    audit = historical_replay_completion_audit()
    milestone_sync = _sync_historical_replay_completion_milestone(audit)
    result = persist_historical_replay_completion_certificate(audit)
    return {
        **result,
        "refresh_requested_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(
            timespec="seconds"
        ),
        "audit_snapshot_reused": True,
        "completion_milestone_sync": milestone_sync,
        "paper_only": True,
        "automatic_promotion": False,
        "live_order_allowed": False,
    }


def _sync_historical_replay_completion_milestone(
    audit: dict[str, object],
) -> dict[str, object]:
    """Bind one completed full-scope audit to the final milestone without rescanning."""
    evidence = (
        audit.get("evidence_audit")
        if isinstance(audit.get("evidence_audit"), dict)
        else {}
    )
    if not (
        audit.get("ok") is True
        and audit.get("completion_verified") is True
        and audit.get("certificate_allowed") is True
        and evidence.get("ok") is True
        and evidence.get("deep") is True
    ):
        return {
            "ok": False,
            "status": "completion_audit_not_eligible_for_final_milestone",
            "final_milestone_persisted": False,
            "paper_only": True,
            "live_order_allowed": False,
        }
    try:
        campaign = json.loads(
            HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE.read_text(encoding="utf-8")
        )
    except (OSError, json.JSONDecodeError):
        campaign = {}
    campaign_ids = [
        str(value or "").strip().upper()
        for value in campaign.get("source_replay_ids", [])
        if str(value or "").strip()
    ]
    target_count = int(_number(campaign.get("target_count"))) or len(campaign_ids)
    status = historical_replay_evidence_milestone_status()
    if target_count <= 0 or len(campaign_ids) != target_count:
        return {
            "ok": False,
            "status": "completion_campaign_scope_invalid",
            "final_milestone_persisted": False,
            "target_count": target_count,
            "campaign_id_count": len(campaign_ids),
            "paper_only": True,
            "live_order_allowed": False,
        }
    if target_count in {
        int(_number(value))
        for value in status.get("passed_milestones", [])
        if int(_number(value)) > 0
    }:
        return {
            "ok": True,
            "status": "final_milestone_already_verified",
            "final_milestone_persisted": False,
            "final_milestone_reused": True,
            "milestone": target_count,
            "paper_only": True,
            "live_order_allowed": False,
        }
    record = _build_historical_replay_evidence_milestone_record(
        status=status,
        evidence=evidence,
        milestone=target_count,
        milestone_scope=campaign_ids,
    )
    if record.get("status") != "passed":
        return {
            "ok": False,
            "status": "full_scope_evidence_not_eligible_for_final_milestone",
            "final_milestone_persisted": False,
            "milestone": target_count,
            "record": record,
            "paper_only": True,
            "live_order_allowed": False,
        }
    _append_jsonl(HISTORICAL_REPLAY_EVIDENCE_MILESTONE_FILE, record)
    refreshed = historical_replay_evidence_milestone_status()
    final_verified = target_count in {
        int(_number(value))
        for value in refreshed.get("passed_milestones", [])
        if int(_number(value)) > 0
    }
    return {
        "ok": final_verified,
        "status": (
            "final_milestone_verified_from_completion_audit"
            if final_verified
            else "final_milestone_persisted_but_not_verified"
        ),
        "final_milestone_persisted": True,
        "final_milestone_reused": False,
        "milestone": target_count,
        "record": record,
        "paper_only": True,
        "live_order_allowed": False,
    }


def historical_replay_evidence_audit(
    *,
    deep: bool = True,
    scope_ids: list[str] | None = None,
) -> dict[str, object]:
    audit = _historical_replay_base_audit()
    campaign = _historical_replay_regeneration_campaign(audit)
    audit_scope = scope_ids if scope_ids is not None else campaign.get("source_replay_ids", [])
    normalized_scope = {
        str(value or "").strip().upper()
        for value in audit_scope
        if str(value or "").strip()
    }
    ledger_rows = _read_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, limit=10000)
    latest_by_source: dict[str, dict[str, object]] = {}
    for row in ledger_rows:
        source_id = str(row.get("source_replay_id") or "").strip().upper()
        if source_id in normalized_scope:
            latest_by_source[source_id] = row
    required_replay_ids = {
        str(row.get("new_replay_id") or "").strip().upper()
        for row in latest_by_source.values()
        if str(row.get("status") or "")
        in {"verified_replacement_candidate", "quarantined_new_result"}
        and _historical_replay_evidence_contract_is_current(row)
        and str(row.get("new_replay_id") or "").strip()
    }
    replay_rows: list[dict[str, object]] | None = None
    replay_summary_lookup = {
        "strategy": "not_required_for_shallow_audit",
        "requested_id_count": 0,
        "found_id_count": 0,
        "missing_id_count": 0,
        "bytes_scanned": 0,
    }
    if deep:
        replay_rows, replay_summary_lookup = _read_jsonl_latest_by_ids(
            HISTORICAL_REPLAY_FILE,
            required_replay_ids,
        )
    result = audit_regeneration_evidence(
        ledger_rows=ledger_rows,
        campaign_ids=audit_scope,
        journal_root=TRADE_JOURNAL_DIR,
        replay_rows=replay_rows,
        deep=deep,
        required_evidence_schema_version=HISTORICAL_REPLAY_EVIDENCE_SCHEMA_VERSION,
        required_execution_timing_model_version=HISTORICAL_REPLAY_EXECUTION_TIMING_MODEL_VERSION,
        required_replay_data_bundle_evidence_schema=HISTORICAL_REPLAY_DATA_BUNDLE_SLICE_EVIDENCE_SCHEMA,
    )
    return {
        **result,
        "campaign_id": campaign.get("campaign_id", ""),
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "journal_root": str(TRADE_JOURNAL_DIR),
        "replay_summary_lookup": replay_summary_lookup,
    }


def _historical_replay_evidence_milestone_status_source_signature(
) -> tuple[tuple[str, int, int], ...]:
    return tuple(
        (str(path.resolve()), *_historical_replay_status_file_signature(path))
        for path in (
            HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE,
            HISTORICAL_REPLAY_REGENERATION_FILE,
            HISTORICAL_REPLAY_EVIDENCE_MILESTONE_FILE,
        )
    )


def _build_historical_replay_evidence_milestone_status() -> dict[str, object]:
    try:
        campaign = json.loads(
            HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE.read_text(encoding="utf-8")
        )
    except (OSError, json.JSONDecodeError):
        campaign = {}
    campaign_id_list = [
        str(value or "").strip().upper()
        for value in campaign.get("source_replay_ids", [])
        if str(value or "").strip()
    ]
    campaign_ids = set(campaign_id_list)
    campaign_scope_hash = evidence_scope_hash(campaign_ids)
    target_count = int(_number(campaign.get("target_count"))) or len(campaign_ids)
    progress = _historical_replay_regeneration_ledger_progress(
        target_count,
        campaign_ids,
        include_verified_source_ids=True,
    )
    verified_source_id_set = {
        str(value or "").strip().upper()
        for value in progress.pop("_verified_source_ids", [])
        if str(value or "").strip()
    }
    verified_ids = [source_id for source_id in campaign_id_list if source_id in verified_source_id_set]
    rows = _read_jsonl(HISTORICAL_REPLAY_EVIDENCE_MILESTONE_FILE, limit=1000)
    latest_by_milestone: dict[int, dict[str, object]] = {}
    for row in rows:
        if str(row.get("campaign_id") or "") != str(campaign.get("campaign_id") or ""):
            continue
        milestone = int(_number(row.get("milestone")))
        if milestone:
            latest_by_milestone[milestone] = row
    record_validity = {
        milestone: valid_evidence_milestone_record(
            row,
            required_evidence_schema_version=HISTORICAL_REPLAY_EVIDENCE_SCHEMA_VERSION,
            required_execution_timing_model_version=HISTORICAL_REPLAY_EXECUTION_TIMING_MODEL_VERSION,
            required_replay_data_bundle_evidence_schema=HISTORICAL_REPLAY_DATA_BUNDLE_SLICE_EVIDENCE_SCHEMA,
            required_artifact_hash_contract=REPLAY_ARTIFACT_HASH_CONTRACT,
            required_campaign_scope_hash=campaign_scope_hash,
            currently_verified_source_ids=verified_source_id_set,
            required_target_count=target_count,
        )
        for milestone, row in latest_by_milestone.items()
    }
    active_review_required = sorted(
        milestone
        for milestone, row in latest_by_milestone.items()
        if str(row.get("status") or "") == "review_required"
        and str(row.get("schema") or "") == "codexstock_replay_evidence_milestone_v8"
        and int(_number(row.get("target_count"))) == target_count
        and str(row.get("campaign_scope_hash") or "") == campaign_scope_hash
        and str(row.get("evidence_schema_version") or "")
        == HISTORICAL_REPLAY_EVIDENCE_SCHEMA_VERSION
        and str(row.get("execution_timing_model_version") or "")
        == HISTORICAL_REPLAY_EXECUTION_TIMING_MODEL_VERSION
        and str(row.get("replay_data_bundle_evidence_schema") or "")
        == HISTORICAL_REPLAY_DATA_BUNDLE_SLICE_EVIDENCE_SCHEMA
    )
    passed = sorted(
        milestone
        for milestone, valid in record_validity.items()
        if valid
    )
    invalidated = sorted(set(latest_by_milestone) - set(passed))
    configured = evidence_milestones(target_count)
    due = due_evidence_milestones(
        resolved_count=int(_number(progress.get("resolved_count"))),
        target_count=target_count,
        passed_milestones=passed,
    )
    next_milestone = next(
        (milestone for milestone in configured if milestone not in passed),
        None,
    )
    deep_verified_through = max(passed, default=0)
    deep_verified_record = latest_by_milestone.get(deep_verified_through, {})
    deep_verified_pct = round(
        (deep_verified_through / target_count) * 100.0,
        2,
    ) if target_count else 100.0
    deep_verification = {
        "status": "passed_to_milestone" if deep_verified_through else "pending_initial_milestone",
        "verified_through_count": deep_verified_through,
        "target_count": target_count,
        "coverage_pct": deep_verified_pct,
        "progress_label": f"{deep_verified_through}/{target_count} ({deep_verified_pct:.2f}%)",
        "next_milestone": next_milestone,
        "last_verified_at": deep_verified_record.get("generated_at", ""),
        "evidence_schema_version": HISTORICAL_REPLAY_EVIDENCE_SCHEMA_VERSION,
        "execution_timing_model_version": HISTORICAL_REPLAY_EXECUTION_TIMING_MODEL_VERSION,
        "replay_data_bundle_evidence_schema": HISTORICAL_REPLAY_DATA_BUNDLE_SLICE_EVIDENCE_SCHEMA,
        "ledger_evidence_hash": deep_verified_record.get("ledger_evidence_hash"),
        "journal_evidence_hash": deep_verified_record.get("journal_evidence_hash"),
        "replay_evidence_hash": deep_verified_record.get("replay_evidence_hash"),
        "evidence_bundle_hash": deep_verified_record.get("evidence_bundle_hash"),
        "audited_scope_hash": deep_verified_record.get("audited_scope_hash"),
        "evidence_bundle_hash_contract": deep_verified_record.get("evidence_bundle_hash_contract"),
        "artifact_hash_contract": deep_verified_record.get("artifact_hash_contract"),
        "artifact_anchor_required_count": deep_verified_record.get("artifact_anchor_required_count", 0),
        "artifact_anchor_verified_count": deep_verified_record.get("artifact_anchor_verified_count", 0),
        "artifact_anchor_mismatch_count": deep_verified_record.get("artifact_anchor_mismatch_count", 0),
        "artifact_anchor_deep_verified": deep_verified_record.get("artifact_anchor_deep_verified") is True,
        "lookahead_rule": "decision_data_as_of_before_execution_at_with_minimum_one_bar_lag",
        "paper_only": True,
        "live_order_allowed": False,
    }
    return {
        "ok": not active_review_required,
        "schema": "codexstock_replay_evidence_milestone_status_v8",
        "campaign_id": campaign.get("campaign_id", ""),
        "target_count": target_count,
        "campaign_scope_hash": campaign_scope_hash,
        "required_evidence_schema_version": HISTORICAL_REPLAY_EVIDENCE_SCHEMA_VERSION,
        "required_execution_timing_model_version": HISTORICAL_REPLAY_EXECUTION_TIMING_MODEL_VERSION,
        "required_replay_data_bundle_evidence_schema": HISTORICAL_REPLAY_DATA_BUNDLE_SLICE_EVIDENCE_SCHEMA,
        "resolved_count": int(_number(progress.get("resolved_count"))),
        "configured_milestones": configured,
        "passed_milestones": passed,
        "invalidated_milestones": invalidated,
        "active_review_required_milestones": active_review_required,
        "due_milestones": due,
        "next_milestone": next_milestone,
        "deep_verification": deep_verification,
        "latest_records": [
            {
                **latest_by_milestone[key],
                "current_contract_valid": bool(record_validity.get(key)),
                "effective_status": (
                    "passed"
                    if record_validity.get(key)
                    else "review_required"
                    if key in active_review_required
                    else "invalidated"
                ),
            }
            for key in sorted(latest_by_milestone)
        ],
        "ledger_path": str(HISTORICAL_REPLAY_EVIDENCE_MILESTONE_FILE),
        "paper_only": True,
        "live_order_allowed": False,
    }


def historical_replay_evidence_milestone_status() -> dict[str, object]:
    """Return milestone evidence without reparsing an unchanged JSONL ledger."""
    global HISTORICAL_REPLAY_EVIDENCE_MILESTONE_STATUS_CACHE
    schema_version = "historical-replay-evidence-milestone-status-cache.v1"
    signature = _historical_replay_evidence_milestone_status_source_signature()
    cache_path = HISTORICAL_REPLAY_EVIDENCE_MILESTONE_STATUS_CACHE_FILE
    disk_cache_allowed = all(
        Path(item[0]).parent == cache_path.resolve().parent
        for item in signature
    )
    with HISTORICAL_REPLAY_EVIDENCE_MILESTONE_STATUS_CACHE_LOCK:
        cached = HISTORICAL_REPLAY_EVIDENCE_MILESTONE_STATUS_CACHE
        if cached and cached[0] == signature:
            payload = copy.deepcopy(cached[1])
            payload["cache_hit"] = True
            payload["cache_source"] = "memory"
            return payload
        try:
            persisted = (
                json.loads(cache_path.read_text(encoding="utf-8"))
                if disk_cache_allowed
                else {}
            )
            persisted_payload = (
                persisted.get("payload")
                if isinstance(persisted.get("payload"), dict)
                else {}
            )
            if (
                persisted.get("schema_version") == schema_version
                and persisted.get("source_signature")
                == [list(item) for item in signature]
                and persisted_payload
            ):
                HISTORICAL_REPLAY_EVIDENCE_MILESTONE_STATUS_CACHE = (
                    signature,
                    copy.deepcopy(persisted_payload),
                )
                payload = copy.deepcopy(persisted_payload)
                payload["cache_hit"] = True
                payload["cache_source"] = "disk"
                return payload
        except (FileNotFoundError, OSError, json.JSONDecodeError, TypeError):
            pass

        payload = _build_historical_replay_evidence_milestone_status()
        HISTORICAL_REPLAY_EVIDENCE_MILESTONE_STATUS_CACHE = (
            signature,
            copy.deepcopy(payload),
        )
        cache_record = {
            "schema_version": schema_version,
            "source_signature": [list(item) for item in signature],
            "saved_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(
                timespec="seconds"
            ),
            "payload": payload,
        }
        try:
            if not disk_cache_allowed:
                raise OSError("milestone cache source paths are outside runtime data")
            target_path = cache_path
            target_path.parent.mkdir(parents=True, exist_ok=True)
            temp_path = target_path.with_name(
                f"{target_path.name}.{os.getpid()}.tmp"
            )
            temp_path.write_text(
                json.dumps(cache_record, ensure_ascii=False, indent=2),
                encoding="utf-8",
            )
            os.replace(temp_path, target_path)
        except OSError:
            pass
        result = copy.deepcopy(payload)
        result["cache_hit"] = False
        result["cache_source"] = "computed"
        return result


def _build_historical_replay_evidence_milestone_record(
    *,
    status: dict[str, object],
    evidence: dict[str, object],
    milestone: int,
    milestone_scope: list[str],
) -> dict[str, object]:
    passed = bool(
        evidence.get("ok")
        and len(milestone_scope) == int(milestone)
        and int(_number(evidence.get("verified_count"))) == int(milestone)
        and str(evidence.get("artifact_hash_contract") or "")
        == REPLAY_ARTIFACT_HASH_CONTRACT
        and int(_number(evidence.get("artifact_anchor_required_count")))
        == int(milestone)
        and int(_number(evidence.get("artifact_anchor_verified_count")))
        == int(milestone)
        and int(_number(evidence.get("artifact_anchor_mismatch_count"))) == 0
        and evidence.get("artifact_anchor_deep_verified") is True
        and str(evidence.get("audited_scope_hash") or "")
        == evidence_scope_hash(milestone_scope)
        and {
            str(value or "").strip().upper()
            for value in evidence.get("audited_source_ids", [])
            if str(value or "").strip()
        }
        == set(milestone_scope)
        and str(evidence.get("evidence_bundle_hash_contract") or "")
        == EVIDENCE_BUNDLE_HASH_CONTRACT
    )
    return {
        "schema": "codexstock_replay_evidence_milestone_v8",
        "campaign_id": status.get("campaign_id", ""),
        "target_count": status.get("target_count"),
        "campaign_scope_hash": status.get("campaign_scope_hash"),
        "evidence_schema_version": HISTORICAL_REPLAY_EVIDENCE_SCHEMA_VERSION,
        "execution_timing_model_version": HISTORICAL_REPLAY_EXECUTION_TIMING_MODEL_VERSION,
        "replay_data_bundle_evidence_schema": HISTORICAL_REPLAY_DATA_BUNDLE_SLICE_EVIDENCE_SCHEMA,
        "milestone": int(milestone),
        "status": "passed" if passed else "review_required",
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(
            timespec="seconds"
        ),
        "resolved_count": evidence.get("resolved_count"),
        "verified_count": evidence.get("verified_count"),
        "quarantined_count": evidence.get("quarantined_count"),
        "failed_count": evidence.get("failed_count"),
        "audited_journal_count": evidence.get("audited_journal_count"),
        "audited_closed_trade_count": evidence.get("audited_closed_trade_count"),
        "issue_count": evidence.get("issue_count"),
        "issue_code_counts": evidence.get("issue_code_counts", {}),
        "missing_trade_field_counts": evidence.get("missing_trade_field_counts", {}),
        "comparison_status_counts": evidence.get("comparison_status_counts", {}),
        "comparison_review_required_count": evidence.get(
            "comparison_review_required_count"
        ),
        "source_equivalence_claim_allowed_count": evidence.get(
            "source_equivalence_claim_allowed_count"
        ),
        "ledger_evidence_hash": evidence.get("ledger_evidence_hash"),
        "journal_evidence_hash": evidence.get("journal_evidence_hash"),
        "replay_evidence_hash": evidence.get("replay_evidence_hash"),
        "evidence_bundle_hash": evidence.get("evidence_bundle_hash"),
        "audited_source_ids": evidence.get("audited_source_ids", []),
        "audited_scope_hash": evidence.get("audited_scope_hash"),
        "evidence_bundle_hash_contract": evidence.get(
            "evidence_bundle_hash_contract"
        ),
        "artifact_hash_contract": evidence.get("artifact_hash_contract"),
        "artifact_anchor_required_count": evidence.get(
            "artifact_anchor_required_count"
        ),
        "artifact_anchor_verified_count": evidence.get(
            "artifact_anchor_verified_count"
        ),
        "artifact_anchor_mismatch_count": evidence.get(
            "artifact_anchor_mismatch_count"
        ),
        "artifact_anchor_deep_verified": evidence.get(
            "artifact_anchor_deep_verified"
        )
        is True,
        "paper_only": True,
        "live_order_allowed": False,
    }


def run_due_historical_replay_evidence_milestones() -> dict[str, object]:
    status = historical_replay_evidence_milestone_status()
    due = status.get("due_milestones") if isinstance(status.get("due_milestones"), list) else []
    if not due:
        return {**status, "executed_milestones": []}
    try:
        campaign = json.loads(
            HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE.read_text(encoding="utf-8")
        )
    except (OSError, json.JSONDecodeError):
        campaign = {}
    campaign_ids = [
        str(value or "").strip().upper()
        for value in campaign.get("source_replay_ids", [])
        if str(value or "").strip()
    ]
    campaign_id_set = set(campaign_ids)
    latest_by_source: dict[str, dict[str, object]] = {}
    for row in _read_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, limit=10000):
        source_id = str(row.get("source_replay_id") or "").strip().upper()
        if source_id in campaign_id_set:
            latest_by_source[source_id] = row
    verified_ids = [
        source_id
        for source_id in campaign_ids
        if (
            str((latest_by_source.get(source_id) or {}).get("status") or "")
            == "verified_replacement_candidate"
            and _historical_replay_evidence_contract_is_current(latest_by_source.get(source_id) or {})
        )
    ]
    executed: list[dict[str, object]] = []
    for milestone in due:
        milestone_scope = verified_ids[: int(milestone)]
        evidence = historical_replay_evidence_audit(
            deep=True,
            scope_ids=milestone_scope,
        )
        record = _build_historical_replay_evidence_milestone_record(
            status=status,
            evidence=evidence,
            milestone=int(milestone),
            milestone_scope=milestone_scope,
        )
        _append_jsonl(HISTORICAL_REPLAY_EVIDENCE_MILESTONE_FILE, record)
        executed.append(record)
    return {
        **historical_replay_evidence_milestone_status(),
        "executed_milestones": executed,
    }


def regenerate_historical_paper_replay_isolated_with_milestones(
    replay_id: str,
) -> dict[str, object]:
    if not HEAVY_RESEARCH_JOB_LOCK.acquire(blocking=False):
        return {
            "ok": True,
            "status": "deferred_heavy_research_busy",
            "replay_id": replay_id,
            "retry_after_seconds": 60,
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
        }
    try:
        result = regenerate_historical_paper_replay_isolated(replay_id)
        if str(result.get("status") or "") in {
            "verified_replacement_candidate",
            "quarantined_new_result",
        }:
            try:
                result["evidence_milestones"] = run_due_historical_replay_evidence_milestones()
            except Exception as exc:
                result["evidence_milestones"] = {
                    "ok": False,
                    "status": "milestone_audit_error",
                    "error": f"{type(exc).__name__}: {exc}"[:300],
                    "paper_only": True,
                    "live_order_allowed": False,
                }
        return result
    finally:
        HEAVY_RESEARCH_JOB_LOCK.release()


def next_historical_replay_regeneration_candidate(
    *,
    max_failed_attempts: int = 3,
    max_source_trade_count: int | None = None,
) -> dict[str, object]:
    """Select the next recoverable full-scope replay without repeating resolved work."""
    if HISTORICAL_REPLAY_DATA_BACKFILL_LOCK.locked():
        return {
            "ok": True,
            "status": "waiting_for_data_backfill",
            "paper_only": True,
            "live_order_allowed": False,
        }
    audit = _historical_replay_base_audit()
    queue_rows = audit.get("regeneration_queue") if isinstance(audit.get("regeneration_queue"), list) else []
    campaign = _historical_replay_regeneration_campaign(audit)
    campaign_ids = set(campaign.get("source_replay_ids", []))
    campaign_target_count = int(_number(campaign.get("target_count"))) or len(campaign_ids)
    queue_rows = [
        row for row in queue_rows
        if str(row.get("replay_id") or "").strip().upper() in campaign_ids
    ]
    ledger_rows = _read_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, limit=10000)
    latest_by_source: dict[str, dict[str, object]] = {}
    failure_counts: dict[str, int] = {}
    for row in ledger_rows:
        replay_id = str(row.get("source_replay_id") or "").strip().upper()
        if not replay_id:
            continue
        latest_by_source[replay_id] = row
        if str(row.get("status") or "") == "regeneration_failed":
            failure_counts[replay_id] = failure_counts.get(replay_id, 0) + 1
    queued_ids = {
        str(row.get("replay_id") or "").strip().upper()
        for row in queue_rows
        if isinstance(row, dict) and str(row.get("replay_id") or "").strip()
    }
    # A corrected audit rule can make a frozen source disappear from the live
    # queue. Keep the campaign finishable by replaying its preserved contract
    # rather than silently shrinking the immutable target.
    for replay_id in sorted(campaign_ids - queued_ids):
        latest_row = latest_by_source.get(replay_id) or {}
        latest_status = str(latest_row.get("status") or "")
        current_evidence = _historical_replay_evidence_contract_is_current(latest_row)
        if current_evidence and latest_status in {"verified_replacement_candidate", "quarantined_new_result"}:
            continue
        queue_rows.append(
            {
                "replay_id": replay_id,
                "expected_trade_count": 0,
                "candidate_scope": "frozen_campaign_contract",
                "issue_status": "CAMPAIGN_SOURCE_REEVALUATED",
            }
        )
    blocked_contracts: list[dict[str, object]] = []
    candidate_pool: list[dict[str, object]] = []
    deferred_large_candidate_count = 0
    for queue_position, row in enumerate(queue_rows, start=1):
        replay_id = str(row.get("replay_id") or "").strip().upper()
        if not replay_id:
            continue
        latest_status = str((latest_by_source.get(replay_id) or {}).get("status") or "")
        latest_row = latest_by_source.get(replay_id) or {}
        current_evidence = _historical_replay_evidence_contract_is_current(latest_row)
        if current_evidence and latest_status in {"verified_replacement_candidate", "quarantined_new_result"}:
            continue
        if latest_status == "regeneration_failed" and latest_row.get("retryable") is False:
            continue
        failed_attempts = failure_counts.get(replay_id, 0)
        if failed_attempts >= max(1, int(max_failed_attempts)):
            continue
        expected_trade_count = int(_number(row.get("expected_trade_count")))
        if (
            max_source_trade_count is not None
            and expected_trade_count > max(0, int(max_source_trade_count))
        ):
            deferred_large_candidate_count += 1
            continue
        candidate_pool.append(
            {
                "replay_id": replay_id,
                "queue_position": queue_position,
                "failed_attempts": failed_attempts,
                "expected_trade_count": expected_trade_count,
                "evidence_upgrade_required": bool(
                    latest_status in {"verified_replacement_candidate", "quarantined_new_result"}
                    and not current_evidence
                ),
            }
        )

    # The audit already carries each replay's archived trade count. Rank on that
    # lightweight index first so we do not reopen hundreds of detail archives
    # merely to select the next replay.
    candidate_pool.sort(
        key=lambda item: (
            -int(_number(item.get("expected_trade_count"))),
            int(_number(item.get("queue_position"))),
        )
    )
    for candidate in candidate_pool:
        replay_id = str(candidate.get("replay_id") or "")
        contract = historical_replay_regeneration_contract(replay_id)
        if not contract.get("ok"):
            blocked_contracts.append(
                {
                    "replay_id": replay_id,
                    "status": contract.get("status", "contract_invalid"),
                }
            )
            continue
        source_trade_count = int(
            _number(contract.get("source_trade_count"))
            or _number(candidate.get("expected_trade_count"))
        )
        if (
            max_source_trade_count is not None
            and source_trade_count > max(0, int(max_source_trade_count))
        ):
            deferred_large_candidate_count += 1
            continue
        run_arguments = contract.get("run_arguments") if isinstance(contract.get("run_arguments"), dict) else {}
        return {
            "ok": True,
            "status": "ready",
            "replay_id": replay_id,
            "queue_position": int(_number(candidate.get("queue_position"))),
            "queue_count": len(queue_rows),
            "total_candidate_count": campaign_target_count,
            "candidate_pool_count": len(candidate_pool),
            "contracts_checked_count": len(blocked_contracts) + 1,
            "failed_attempts": int(_number(candidate.get("failed_attempts"))),
            "contract_status": contract.get("status"),
            "source_trade_count": source_trade_count,
            "source_total_return_pct": contract.get("source_total_return_pct"),
            "start_date": run_arguments.get("start_date"),
            "end_date": run_arguments.get("end_date"),
            "evidence_upgrade_required": bool(candidate.get("evidence_upgrade_required")),
            "required_evidence_schema_version": HISTORICAL_REPLAY_EVIDENCE_SCHEMA_VERSION,
            "required_execution_timing_model_version": HISTORICAL_REPLAY_EXECUTION_TIMING_MODEL_VERSION,
            "max_source_trade_count": max_source_trade_count,
            "deferred_large_candidate_count": deferred_large_candidate_count,
            "selection_policy": "largest_source_trade_count_then_audit_priority",
            "paper_only": True,
            "live_order_allowed": False,
        }
    unresolved_count = max(
        0,
        campaign_target_count
        - sum(
            1
            for row in latest_by_source.values()
            if (
                str(row.get("status") or "")
                in {"verified_replacement_candidate", "quarantined_new_result"}
                and _historical_replay_evidence_contract_is_current(row)
            )
        ),
    )
    return {
        "ok": unresolved_count == 0,
        "status": "queue_complete" if unresolved_count == 0 else "no_recoverable_contract_in_queue",
        "queue_count": len(queue_rows),
        "total_candidate_count": campaign_target_count,
        "unresolved_count": unresolved_count,
        "blocked_contract_count": len(blocked_contracts),
        "deferred_large_candidate_count": deferred_large_candidate_count,
        "max_source_trade_count": max_source_trade_count,
        "blocked_contracts": blocked_contracts[:20],
        "paper_only": True,
        "live_order_allowed": False,
    }


def historical_replay_data_gap_queue(*, record: bool = True) -> dict[str, object]:
    """Expose Stage 2 OHLCV backfill requests for nonretryable replay failures."""
    if (
        not record
        and HISTORICAL_REPLAY_DATA_GAP_QUEUE_FILE.is_file()
        and HISTORICAL_REPLAY_REGENERATION_FILE.is_file()
    ):
        try:
            same_runtime_directory = (
                HISTORICAL_REPLAY_DATA_GAP_QUEUE_FILE.parent.resolve()
                == HISTORICAL_REPLAY_REGENERATION_FILE.parent.resolve()
            )
            manifest_is_current = (
                HISTORICAL_REPLAY_DATA_GAP_QUEUE_FILE.stat().st_mtime_ns
                >= HISTORICAL_REPLAY_REGENERATION_FILE.stat().st_mtime_ns
            )
            if same_runtime_directory and manifest_is_current:
                payload = json.loads(
                    HISTORICAL_REPLAY_DATA_GAP_QUEUE_FILE.read_text(encoding="utf-8")
                )
                if isinstance(payload, dict):
                    return {
                        **payload,
                        "cached": True,
                        "cache_validation": "manifest_newer_than_regeneration_ledger",
                    }
        except (OSError, json.JSONDecodeError):
            pass
    rows = _read_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, limit=10000)
    if record:
        return _build_replay_data_gap_manifest(
            rows,
            contract_loader=historical_replay_regeneration_contract,
            output_path=HISTORICAL_REPLAY_DATA_GAP_QUEUE_FILE,
            now=lambda: datetime.now(ZoneInfo("Asia/Seoul")),
        )
    if HISTORICAL_REPLAY_DATA_GAP_QUEUE_FILE.is_file():
        try:
            payload = json.loads(HISTORICAL_REPLAY_DATA_GAP_QUEUE_FILE.read_text(encoding="utf-8"))
            if isinstance(payload, dict):
                latest_by_source: dict[str, dict[str, object]] = {}
                for row in rows:
                    replay_id = str(row.get("source_replay_id") or "").strip().upper()
                    if replay_id:
                        latest_by_source[replay_id] = row
                expected_ids = sorted(
                    replay_id
                    for replay_id, row in latest_by_source.items()
                    if _replay_ledger_requires_data_backfill(row)
                )
                requests = payload.get("requests") if isinstance(payload.get("requests"), list) else []
                recorded_ids = sorted(
                    str(request.get("contract", {}).get("replay_id") or "").strip().upper()
                    for request in requests
                    if isinstance(request, dict) and isinstance(request.get("contract"), dict)
                )
                if recorded_ids == expected_ids:
                    return payload
        except (OSError, json.JSONDecodeError):
            pass
    return _build_replay_data_gap_manifest(
        rows,
        contract_loader=historical_replay_regeneration_contract,
        output_path=HISTORICAL_REPLAY_DATA_GAP_QUEUE_FILE,
        now=lambda: datetime.now(ZoneInfo("Asia/Seoul")),
    )


HISTORICAL_REPLAY_DATA_BACKFILL_SERVICE = ReplayDataBackfillService(
    queue_loader=lambda: historical_replay_data_gap_queue(record=False),
    engine_run=OPENBB_RUNTIME.run_historical_backfill,
    replay_regenerate=regenerate_historical_paper_replay,
    queue_refresh=lambda: historical_replay_data_gap_queue(record=False),
    append_ledger=_append_jsonl,
    result_dir=HISTORICAL_REPLAY_DATA_GAP_RESULT_DIR,
    index_path=HISTORICAL_REPLAY_DATA_GAP_INDEX_FILE,
    ledger_path=HISTORICAL_REPLAY_DATA_GAP_RESULT_LEDGER_FILE,
)


def run_historical_replay_data_gap_backfill(request_id: str) -> dict[str, object]:
    request_key = str(request_id or "").strip()
    focus = build_operating_focus()
    if focus.get("market_priority_active") or focus.get("market_open"):
        return {
            "ok": True,
            "status": "deferred_to_market_closed_window",
            "request_id": request_key,
            "current_focus_mode": focus.get("mode", ""),
            "current_market_phase": focus.get("market_phase", ""),
            "current_market_priority_active": bool(focus.get("market_priority_active")),
            "current_market_open": bool(focus.get("market_open")),
            "operator_message": "과거장 데이터 백필 보류: 장전/장중 매매 우선 모드에서는 실행하지 않습니다.",
            "paper_only": True,
            "score_allowed": False,
            "promotion_allowed": False,
            "live_order_allowed": False,
            "unverified_result_affects_score": False,
            "unverified_result_affects_live_candidate": False,
        }
    if not HISTORICAL_REPLAY_DATA_BACKFILL_LOCK.acquire(blocking=False):
        return {
            "ok": False,
            "status": "data_backfill_busy",
            "request_id": request_key,
            "paper_only": True,
            "score_allowed": False,
            "promotion_allowed": False,
            "live_order_allowed": False,
        }
    try:
        return HISTORICAL_REPLAY_DATA_BACKFILL_SERVICE.run(request_id)
    finally:
        HISTORICAL_REPLAY_DATA_BACKFILL_LOCK.release()


def _weekday_after_hours_replay_load_policy(
    recent_elapsed_seconds: list[float] | None = None,
) -> dict[str, object]:
    """Pace serial Paper recovery from measured job cost, never from queue size."""
    if recent_elapsed_seconds is None:
        worker = globals().get("HISTORICAL_REPLAY_REGENERATION_WORKER")
        status = worker.status() if worker is not None else {}
        raw_durations = status.get("recent_success_elapsed_seconds", [])
    else:
        raw_durations = recent_elapsed_seconds
    durations: list[float] = []
    if isinstance(raw_durations, list):
        for value in raw_durations[-20:]:
            duration = _number(value)
            if 0.0 < duration < 1_800.0:
                durations.append(float(duration))
    observed_p75 = 0.0
    if durations:
        ordered = sorted(durations)
        p75_index = max(0, math.ceil(len(ordered) * 0.75) - 1)
        observed_p75 = ordered[p75_index]
        target_cycle_seconds = observed_p75 / (
            WEEKDAY_AFTER_HOURS_REPLAY_TARGET_COMPUTE_SHARE_PCT / 100.0
        )
        cooldown_seconds = math.ceil(max(0.0, target_cycle_seconds - observed_p75))
    else:
        cooldown_seconds = WEEKDAY_AFTER_HOURS_REPLAY_DEFAULT_COOLDOWN_SECONDS
    cooldown_seconds = max(
        WEEKDAY_AFTER_HOURS_REPLAY_MIN_COOLDOWN_SECONDS,
        min(WEEKDAY_AFTER_HOURS_REPLAY_MAX_COOLDOWN_SECONDS, int(cooldown_seconds)),
    )
    return {
        "cadence_seconds": cooldown_seconds,
        "observed_job_count": len(durations),
        "observed_p75_seconds": round(observed_p75, 2),
        "target_compute_share_pct": WEEKDAY_AFTER_HOURS_REPLAY_TARGET_COMPUTE_SHARE_PCT,
        "minimum_cooldown_seconds": WEEKDAY_AFTER_HOURS_REPLAY_MIN_COOLDOWN_SECONDS,
        "maximum_cooldown_seconds": WEEKDAY_AFTER_HOURS_REPLAY_MAX_COOLDOWN_SECONDS,
        "serial_worker": True,
        "paper_only": True,
        "live_order_allowed": False,
    }


def _weekday_after_hours_replay_runtime_profile(
    rows: list[dict[str, object]],
    *,
    minimum_source_trade_count: int,
    maximum_source_trade_count: int,
    campaign_ids: set[str] | None = None,
) -> dict[str, object]:
    """Measure a trade-count lane before allowing it during a weekday night."""
    elapsed_seconds: list[float] = []
    scoped_ids = campaign_ids or set()
    for row in rows:
        if not isinstance(row, dict) or not _historical_replay_evidence_contract_is_current(row):
            continue
        if str(row.get("status") or "") not in {
            "verified_replacement_candidate",
            "quarantined_new_result",
        }:
            continue
        source_replay_id = str(row.get("source_replay_id") or "").strip().upper()
        if scoped_ids and source_replay_id not in scoped_ids:
            continue
        source_trade_count = int(_number(row.get("source_trade_count")))
        if not minimum_source_trade_count <= source_trade_count <= maximum_source_trade_count:
            continue
        try:
            started_at = datetime.fromisoformat(str(row.get("started_at") or ""))
            generated_at = datetime.fromisoformat(str(row.get("generated_at") or ""))
        except (TypeError, ValueError):
            continue
        elapsed = (generated_at - started_at).total_seconds()
        if 0.0 < elapsed <= 1_800.0:
            elapsed_seconds.append(float(elapsed))
    ordered = sorted(elapsed_seconds[-20:])
    p90_seconds = 0.0
    if ordered:
        p90_seconds = ordered[min(len(ordered) - 1, max(0, int(len(ordered) * 0.9)))]
    max_seconds = max(ordered) if ordered else 0.0
    observed_safe = bool(
        ordered
        and p90_seconds <= WEEKDAY_AFTER_HOURS_REPLAY_SAFE_P90_SECONDS
        and max_seconds <= WEEKDAY_AFTER_HOURS_REPLAY_SAFE_MAX_SECONDS
    )
    return {
        "minimum_source_trade_count": minimum_source_trade_count,
        "maximum_source_trade_count": maximum_source_trade_count,
        "sample_count": len(ordered),
        "p90_elapsed_seconds": round(p90_seconds, 2),
        "max_elapsed_seconds": round(max_seconds, 2),
        "observed_safe": observed_safe,
        "probe_allowed": not ordered,
        "safe_p90_limit_seconds": WEEKDAY_AFTER_HOURS_REPLAY_SAFE_P90_SECONDS,
        "safe_max_limit_seconds": WEEKDAY_AFTER_HOURS_REPLAY_SAFE_MAX_SECONDS,
        "paper_only": True,
        "live_order_allowed": False,
    }


def _select_weekday_after_hours_replay_candidate(
    *,
    ledger_rows: list[dict[str, object]],
    campaign_ids: set[str],
) -> dict[str, object]:
    """Expand only one measured lane at a time; never turn a weekday into a full batch."""
    current_limit = WEEKDAY_AFTER_HOURS_REPLAY_MAX_SOURCE_TRADES
    selected = next_historical_replay_regeneration_candidate(
        max_source_trade_count=current_limit,
    )
    profiles: list[dict[str, object]] = []
    if selected.get("replay_id"):
        return {
            **selected,
            "max_source_trade_count": current_limit,
            "adaptive_lane": False,
            "weekday_runtime_profiles": profiles,
        }

    while current_limit < WEEKDAY_AFTER_HOURS_REPLAY_ADAPTIVE_MAX_SOURCE_TRADES:
        next_limit = min(
            WEEKDAY_AFTER_HOURS_REPLAY_ADAPTIVE_MAX_SOURCE_TRADES,
            current_limit + WEEKDAY_AFTER_HOURS_REPLAY_ADAPTIVE_STEP_TRADES,
        )
        profile = _weekday_after_hours_replay_runtime_profile(
            ledger_rows,
            minimum_source_trade_count=current_limit + 1,
            maximum_source_trade_count=next_limit,
            campaign_ids=campaign_ids,
        )
        profiles.append(profile)
        if not profile.get("observed_safe") and not profile.get("probe_allowed"):
            return {
                **selected,
                "status": "weekday_after_hours_runtime_guard",
                "max_source_trade_count": current_limit,
                "blocked_lane": {
                    "minimum_source_trade_count": current_limit + 1,
                    "maximum_source_trade_count": next_limit,
                },
                "adaptive_lane": False,
                "weekday_runtime_profiles": profiles,
                "paper_only": True,
                "live_order_allowed": False,
            }
        candidate = next_historical_replay_regeneration_candidate(
            max_source_trade_count=next_limit,
        )
        if candidate.get("replay_id"):
            return {
                **candidate,
                "max_source_trade_count": next_limit,
                "adaptive_lane": True,
                "adaptive_probe": bool(profile.get("probe_allowed")),
                "weekday_runtime_profiles": profiles,
                "paper_only": True,
                "live_order_allowed": False,
            }
        selected = candidate
        current_limit = next_limit
    return {
        **selected,
        "max_source_trade_count": current_limit,
        "adaptive_lane": current_limit > WEEKDAY_AFTER_HOURS_REPLAY_MAX_SOURCE_TRADES,
        "weekday_runtime_profiles": profiles,
        "paper_only": True,
        "live_order_allowed": False,
    }


def _finalize_historical_replay_queue_selection(
    selected: dict[str, object],
    *,
    schedule_mode: str,
) -> dict[str, object]:
    if str(selected.get("status") or "") != "queue_complete":
        return {**selected, "schedule_mode": schedule_mode}
    certificate = load_historical_replay_completion_certificate()
    if not certificate.get("ok"):
        certificate = persist_historical_replay_completion_certificate()
    certificate_summary = {
        key: certificate.get(key)
        for key in (
            "ok",
            "status",
            "certificate_id",
            "issued_at",
            "campaign_id",
            "certificate_sha256",
            "hash_valid",
            "source_signature_current",
            "certificate_path",
            "path",
        )
        if certificate.get(key) not in (None, "")
    }
    verified = bool(certificate.get("ok"))
    return {
        **selected,
        "ok": verified,
        "status": "queue_complete" if verified else "completion_certificate_review_required",
        "schedule_mode": "completion_verified" if verified else "completion_fail_closed",
        "completion_verified": verified,
        "completion_certificate": certificate_summary,
        "retry_after_seconds": 5 * 60,
        "score_allowed": verified,
        "promotion_allowed": False,
        "paper_only": True,
        "automatic_promotion": False,
        "live_order_allowed": False,
    }


def historical_replay_focus_mode_status(
    *,
    now: datetime | None = None,
) -> dict[str, object]:
    """Read the expiring operator-requested Paper-only fast lane."""
    current_time = now or datetime.now(ZoneInfo("Asia/Seoul"))
    try:
        payload = json.loads(HISTORICAL_REPLAY_FOCUS_MODE_FILE.read_text(encoding="utf-8"))
    except (FileNotFoundError, OSError, json.JSONDecodeError):
        payload = {}
    if not isinstance(payload, dict):
        payload = {}
    try:
        expires_at = datetime.fromisoformat(str(payload.get("expires_at") or ""))
    except (TypeError, ValueError):
        expires_at = None
    if expires_at is not None and expires_at.tzinfo is None:
        expires_at = expires_at.replace(tzinfo=ZoneInfo("Asia/Seoul"))
    contract_safe = bool(
        payload.get("schema") == "codexstock_historical_replay_focus_mode_v1"
        and payload.get("paper_only") is True
        and payload.get("live_order_allowed") is False
        and payload.get("automatic_promotion") is False
    )
    requested_enabled = bool(payload.get("enabled"))
    expired = bool(expires_at is not None and current_time >= expires_at)
    active = bool(requested_enabled and contract_safe and expires_at is not None and not expired)
    return {
        "ok": contract_safe if payload else True,
        "status": "active" if active else "expired" if expired and requested_enabled else "disabled",
        "active": active,
        "requested_enabled": requested_enabled,
        "started_at": payload.get("started_at", ""),
        "expires_at": payload.get("expires_at", ""),
        "reason": payload.get("reason", ""),
        "mode": "manual_paper_focus_batch" if active else "standard_schedule",
        "serial_worker": True,
        "subprocess_priority": "below_normal",
        "success_cooldown_seconds": 0,
        "state_path": str(HISTORICAL_REPLAY_FOCUS_MODE_FILE),
        "paper_only": True,
        "automatic_promotion": False,
        "live_order_allowed": False,
    }


def set_historical_replay_focus_mode(
    enabled: bool,
    *,
    duration_hours: float = 18.0,
    reason: str = "operator_requested_holiday_focus",
) -> dict[str, object]:
    """Enable a bounded serial fast lane only while market-priority work is inactive."""
    current_time = datetime.now(ZoneInfo("Asia/Seoul"))
    focus = build_operating_focus()
    if enabled and (focus.get("market_priority_active") or focus.get("market_open")):
        return {
            "ok": False,
            "status": "deferred_to_market_closed_window",
            "active": False,
            "current_focus_mode": focus.get("mode", ""),
            "current_market_phase": focus.get("market_phase", ""),
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
        }
    safe_duration = max(0.25, min(float(_number(duration_hours) or 18.0), 48.0))
    record = {
        "schema": "codexstock_historical_replay_focus_mode_v1",
        "enabled": bool(enabled),
        "started_at": current_time.isoformat(timespec="seconds"),
        "expires_at": (current_time + timedelta(hours=safe_duration)).isoformat(timespec="seconds"),
        "reason": str(reason or "operator_requested_holiday_focus")[:160],
        "duration_hours": round(safe_duration, 2),
        "serial_worker": True,
        "subprocess_priority": "below_normal",
        "paper_only": True,
        "automatic_promotion": False,
        "live_order_allowed": False,
    }
    target = HISTORICAL_REPLAY_FOCUS_MODE_FILE
    target.parent.mkdir(parents=True, exist_ok=True)
    temp = target.with_name(f"{target.name}.{os.getpid()}.tmp")
    temp.write_text(json.dumps(record, ensure_ascii=False, indent=2), encoding="utf-8")
    os.replace(temp, target)
    worker = globals().get("HISTORICAL_REPLAY_REGENERATION_WORKER")
    if worker is not None:
        worker_status = (
            worker.start(interval_seconds=15, initial_delay_seconds=0)
            if enabled
            else worker.stop()
        )
    else:
        worker_status = {"status": "worker_missing", "running": False}
    return {
        **historical_replay_focus_mode_status(now=current_time),
        "worker": _historical_replay_worker_public_status(worker_status),
        "operator_message": (
            f"과거장 Paper 집중모드 가동: {safe_duration:.2f}시간, 단일 저우선순위 작업자, 실전 주문 차단"
            if enabled
            else "과거장 Paper 집중모드 중지"
        ),
    }


def next_scheduled_historical_replay_regeneration_candidate(
    *,
    now: datetime | None = None,
) -> dict[str, object]:
    current_time = now or datetime.now(ZoneInfo("Asia/Seoul"))
    focus = build_operating_focus()
    if focus.get("market_priority_active") or focus.get("market_open"):
        schedule_mode = "market_open_deferred" if focus.get("market_open") else "market_priority_deferred"
        return {
            "ok": True,
            "status": "scheduled_for_market_closed_day",
            "schedule": focus.get("large_batch_schedule"),
            "schedule_mode": schedule_mode,
            "market_priority_active": bool(focus.get("market_priority_active")),
            "market_phase": focus.get("market_phase", ""),
            "paper_only": True,
            "live_order_allowed": False,
        }
    milestone_status = historical_replay_evidence_milestone_status()
    active_review_required = milestone_status.get("active_review_required_milestones")
    if isinstance(active_review_required, list) and active_review_required:
        return {
            "ok": False,
            "status": "evidence_milestone_review_required",
            "schedule_mode": "evidence_fail_closed",
            "active_review_required_milestones": list(active_review_required),
            "retry_after_seconds": 5 * 60,
            "manual_recheck_endpoint": "/api/ai-tournament/regeneration-evidence-milestones/run",
            "score_allowed": False,
            "promotion_allowed": False,
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
        }
    focus_mode = historical_replay_focus_mode_status(now=current_time)
    if focus_mode.get("active"):
        selected = next_historical_replay_regeneration_candidate()
        finalized = _finalize_historical_replay_queue_selection(
            selected,
            schedule_mode="manual_paper_focus_batch",
        )
        return {
            **finalized,
            "focus_mode": focus_mode,
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
        }
    if focus.get("large_batch_jobs_allowed"):
        selected = next_historical_replay_regeneration_candidate()
        return _finalize_historical_replay_queue_selection(
            selected,
            schedule_mode="market_closed_day_full_batch",
        )
    load_policy = _weekday_after_hours_replay_load_policy()
    cooldown_seconds = int(load_policy["cadence_seconds"])
    latest_current_generated_at: datetime | None = None
    _, campaign_ids = _historical_replay_campaign_manifest_scope()
    ledger_rows = _read_jsonl(HISTORICAL_REPLAY_REGENERATION_FILE, limit=10000)
    for row in reversed(ledger_rows):
        source_replay_id = str(row.get("source_replay_id") or "").strip().upper()
        if campaign_ids and source_replay_id not in campaign_ids:
            continue
        if not _historical_replay_evidence_contract_is_current(row):
            continue
        try:
            latest_current_generated_at = datetime.fromisoformat(
                str(row.get("generated_at") or "")
            )
        except (TypeError, ValueError):
            latest_current_generated_at = None
        break
    if latest_current_generated_at is not None:
        if latest_current_generated_at.tzinfo is None:
            latest_current_generated_at = latest_current_generated_at.replace(
                tzinfo=ZoneInfo("Asia/Seoul")
            )
        elapsed = max(0, int((current_time - latest_current_generated_at).total_seconds()))
        remaining = max(0, cooldown_seconds - elapsed)
        if remaining:
            return {
                "ok": True,
                "status": "weekday_after_hours_cooldown",
                "schedule_mode": "weekday_after_hours_bounded",
                "retry_after_seconds": remaining,
                "cadence_seconds": cooldown_seconds,
                "next_eligible_at": (
                    current_time + timedelta(seconds=remaining)
                ).isoformat(timespec="seconds"),
                "max_source_trade_count": WEEKDAY_AFTER_HOURS_REPLAY_MAX_SOURCE_TRADES,
                "load_policy": load_policy,
                "paper_only": True,
                "live_order_allowed": False,
            }
    selected = _select_weekday_after_hours_replay_candidate(
        ledger_rows=ledger_rows,
        campaign_ids=campaign_ids,
    )
    if str(selected.get("status") or "") == "queue_complete":
        return _finalize_historical_replay_queue_selection(
            selected,
            schedule_mode="weekday_after_hours_complete",
        )
    if not selected.get("replay_id"):
        return {
            **selected,
            "ok": True,
            "status": "scheduled_for_market_closed_day",
            "schedule": focus.get("large_batch_schedule"),
            "schedule_mode": "weekday_after_hours_no_small_candidate",
            "retry_after_seconds": cooldown_seconds,
            "cadence_seconds": cooldown_seconds,
            "next_schedule_check_at": (
                current_time + timedelta(seconds=cooldown_seconds)
            ).isoformat(timespec="seconds"),
            "load_policy": load_policy,
        }
    return {
        **selected,
        "schedule_mode": "weekday_after_hours_bounded",
        "retry_after_seconds": cooldown_seconds,
        "cadence_seconds": cooldown_seconds,
        "next_eligible_at": (
            current_time + timedelta(seconds=cooldown_seconds)
        ).isoformat(timespec="seconds"),
        "load_policy": load_policy,
    }


