def _autonomous_replay_window() -> tuple[str, str]:
    windows = [
        ("2018-01-01", "2018-12-31"),
        ("2019-01-01", "2019-12-31"),
        ("2020-01-01", "2020-12-31"),
        ("2021-01-01", "2021-12-31"),
        ("2022-01-01", "2022-12-31"),
        ("2023-01-01", "2023-12-31"),
        ("2024-01-01", "2024-12-31"),
        ("2025-01-01", "2025-12-31"),
    ]
    today = today_kst()
    available = [(start, end if end <= today else today) for start, end in windows if start <= today]
    index = len(_read_jsonl(HISTORICAL_REPLAY_FILE, limit=500)) % max(1, len(available))
    return available[index]


def run_autonomous_replay_training(candidates: list[dict[str, object]] | None = None, source: str = "ai-daemon") -> dict[str, object]:
    symbols: list[str] = []
    for item in candidates or []:
        if not isinstance(item, dict):
            continue
        symbol = str(item.get("symbol", "")).upper().strip()
        if symbol and symbol not in symbols:
            symbols.append(symbol)
    for symbol in load_user_watchlist().get("symbols", []):
        normalized = str(symbol).upper().strip()
        if normalized and normalized not in symbols:
            symbols.append(normalized)
    if not symbols:
        symbols = ["083450", "005930", "NVDA", "AAPL"]
    strategy_ids = list(REPLAY_STRATEGY_PROFILES.keys())
    today = today_kst()
    replay_windows = [
        (f"{year}-01-01", min(f"{year}-12-31", today))
        for year in range(2018, datetime.fromisoformat(today).year + 1)
        if f"{year}-01-01" <= today
    ]
    existing_records = [
        row for row in MEMORY.load().get("historical_replay_memories", []) if isinstance(row, dict)
    ]
    seen_contexts: set[str] = set()
    for row in existing_records:
        row_symbols = sorted(str(symbol).upper().strip() for symbol in row.get("symbols", []) if str(symbol).strip())
        seen_contexts.add(
            "|".join(
                [
                    str(row.get("strategy_id") or ""),
                    str(row.get("start_date") or ""),
                    str(row.get("end_date") or ""),
                    ",".join(row_symbols),
                ]
            )
        )
    selected_contract: tuple[str, str, str, list[str]] | None = None
    for start_candidate, end_candidate in replay_windows:
        for strategy_candidate in strategy_ids:
            candidate_profile = _replay_strategy_profile(strategy_candidate)
            strategy_id = (
                f"{strategy_candidate}_MA_{int(candidate_profile.get('fast', 12) or 12)}_"
                f"{int(candidate_profile.get('slow', 32) or 32)}"
            )
            for offset in range(max(1, min(len(symbols), 4))):
                rotated = symbols[offset:] + symbols[:offset]
                candidate_symbols = rotated[:3]
                material = "|".join(
                    [strategy_id, start_candidate, end_candidate, ",".join(sorted(candidate_symbols))]
                )
                if material not in seen_contexts:
                    selected_contract = (start_candidate, end_candidate, strategy_candidate, candidate_symbols)
                    break
            if selected_contract:
                break
        if selected_contract:
            break
    if selected_contract:
        start_date, end_date, strategy_mode, training_symbols = selected_contract
        novelty_status = "new_context"
    else:
        start_date, end_date = _autonomous_replay_window()
        replay_count = len(_read_jsonl(HISTORICAL_REPLAY_FILE, limit=500))
        strategy_mode = strategy_ids[replay_count % max(1, len(strategy_ids))]
        offset = replay_count % max(1, len(symbols))
        training_symbols = (symbols[offset:] + symbols[:offset])[:3]
        novelty_status = "context_space_exhausted_repeat"
    profile = _replay_strategy_profile(strategy_mode)
    fast = int(profile.get("fast", 12) or 12)
    slow = int(profile.get("slow", 32) or 32)
    replay = run_historical_paper_replay(
        symbols=training_symbols,
        start_date=start_date,
        end_date=end_date,
        fast=fast,
        slow=slow,
        initial_cash=50_000_000.0,
        allocation_pct=25.0,
        max_positions=3,
        source=source,
        strategy_mode=strategy_mode,
        stop_loss_pct=float(profile.get("stop_loss_pct", 8.0) or 8.0),
        take_profit_pct=float(profile.get("take_profit_pct", 0.0) or 0.0),
        holding_limit_days=int(profile.get("holding_limit_days", 0) or 0),
        cycles_per_day=24,
    )
    memory = MEMORY.append_historical_replay_memory(replay, source=source)
    return {
        "ok": True,
        "status": "TRAINED",
        "source": source,
        "replay_id": replay.get("id"),
        "memory_id": (memory.get("memory") or {}).get("id") if isinstance(memory.get("memory"), dict) else None,
        "symbols": replay.get("symbols", []),
        "period": f"{replay.get('start_date')}~{replay.get('end_date')}",
        "strategy_mode": replay.get("strategy_mode"),
        "strategy_label": replay.get("strategy_label"),
        "novelty_status": novelty_status,
        "prior_context_count": len(seen_contexts),
        "return_pct": replay.get("total_return_pct"),
        "max_drawdown_pct": replay.get("max_drawdown_pct"),
        "trade_count": replay.get("trade_count"),
        "compressed_training_hours": replay.get("compressed_training_hours"),
        "latest_period_returns": replay.get("latest_period_returns"),
        "staff_meeting": replay.get("staff_meeting", []),
        "summary": replay.get("summary"),
        "note_path": memory.get("path"),
        "graph_path": memory.get("graph_path"),
        "replay": {
            "id": replay.get("id"),
            "summary": replay.get("summary"),
            "strategy_label": replay.get("strategy_label"),
            "sources": replay.get("sources"),
            "open_positions": replay.get("open_positions"),
        },
    }


