def _clean_staff_persona_text(value: object, fallback: str = "", limit: int = 80) -> str:
    text = re.sub(r"\s+", " ", str(value or fallback or "")).strip()
    return text[:limit]


def load_ai_staff_personas() -> dict[str, dict[str, str]]:
    personas = _default_ai_staff_personas()
    if AI_STAFF_PERSONA_FILE.exists():
        try:
            saved = json.loads(AI_STAFF_PERSONA_FILE.read_text(encoding="utf-8"))
            if isinstance(saved, dict):
                rows = saved.get("personas", saved)
                if isinstance(rows, dict):
                    for role, row in rows.items():
                        if role in personas and isinstance(row, dict):
                            personas[role].update({
                                "persona_name": _clean_staff_persona_text(row.get("persona_name"), personas[role]["persona_name"], 24),
                                "call_sign": _clean_staff_persona_text(row.get("call_sign"), personas[role]["call_sign"], 16),
                                "profile": _clean_staff_persona_text(row.get("profile"), personas[role]["profile"], 120),
                            })
        except Exception:
            pass
    return personas


def save_ai_staff_personas(payload: dict[str, object]) -> dict[str, object]:
    personas = load_ai_staff_personas()
    rows = payload.get("personas", [])
    if isinstance(rows, dict):
        iterable = [{"id": role, **(row if isinstance(row, dict) else {})} for role, row in rows.items()]
    elif isinstance(rows, list):
        iterable = [row for row in rows if isinstance(row, dict)]
    else:
        iterable = []
    for row in iterable:
        role = str(row.get("id") or row.get("role") or "").strip()
        if role not in personas:
            continue
        defaults = _default_ai_staff_personas()[role]
        personas[role] = {
            "persona_name": _clean_staff_persona_text(row.get("persona_name"), defaults["persona_name"], 24),
            "call_sign": _clean_staff_persona_text(row.get("call_sign"), defaults["call_sign"], 16),
            "profile": _clean_staff_persona_text(row.get("profile"), defaults["profile"], 120),
        }
    AI_STAFF_PERSONA_FILE.parent.mkdir(parents=True, exist_ok=True)
    AI_STAFF_PERSONA_FILE.write_text(json.dumps({"personas": personas}, ensure_ascii=False, indent=2), encoding="utf-8")
    JOURNAL.add("AI_STAFF_PERSONA_SAVE", "AI 직원 이름 설정 저장", {"roles": list(personas.keys())})
    return {"ok": True, "personas": personas, "contestants": ai_tournament_contestants(), "path": str(AI_STAFF_PERSONA_FILE)}


