def _ai_tournament_score(replay: dict[str, object], risk_limit_pct: float) -> dict[str, object]:
    return_pct = _number(replay.get("total_return_pct"))
    mdd_abs = abs(_number(replay.get("max_drawdown_pct")))
    win_rate = _number(replay.get("win_rate_pct"))
    trade_count = int(_number(replay.get("trade_count")))
    avg_win = _number(replay.get("average_win_pct"))
    avg_loss_abs = abs(_number(replay.get("average_loss_pct")))
    profit_factor_proxy = round(avg_win / avg_loss_abs, 2) if avg_loss_abs else (round(avg_win, 2) if avg_win else 0.0)
    risk_violation = max(0.0, mdd_abs - max(0.0, float(risk_limit_pct or 0.0)))
    inactivity_penalty = 5.0 if trade_count <= 0 else 0.0
    score = (
        return_pct
        - mdd_abs * 0.65
        + win_rate * 0.08
        + min(trade_count, 80) * 0.03
        + min(profit_factor_proxy, 5.0) * 2.0
        - risk_violation * 1.6
        - inactivity_penalty
    )
    return {
        "score": round(score, 2),
        "return_pct": round(return_pct, 2),
        "mdd_abs_pct": round(mdd_abs, 2),
        "win_rate_pct": round(win_rate, 2),
        "trade_count": trade_count,
        "profit_factor_proxy": profit_factor_proxy,
        "risk_violation_pct": round(risk_violation, 2),
        "score_formula": "수익률 - MDD*0.65 + 승률*0.08 + 거래경험 + 손익비가점 - 리스크위반",
    }


def _ai_tournament_default_symbols(limit: int = 6) -> list[str]:
    selected: list[str] = []
    for symbol in load_user_watchlist().get("symbols", []):
        normalized = str(symbol or "").strip().upper()
        if normalized and normalized not in selected:
            selected.append(normalized.zfill(6) if normalized.isdigit() else normalized)
    for symbol in ["083450", "005930", "000660", "005380", "042700", "058470", "NVDA", "AAPL"]:
        if symbol not in selected:
            selected.append(symbol)
    return selected[: max(3, min(int(limit or 6), 12))]


def _normalize_tournament_symbols(symbols: list[object] | tuple[object, ...] | None) -> list[str]:
    selected: list[str] = []
    for symbol in symbols or []:
        normalized = str(symbol or "").strip().upper()
        if normalized.isdigit():
            normalized = normalized.zfill(6)
        if normalized and normalized not in selected:
            selected.append(normalized)
    return selected


def _ai_tournament_period_symbols(start_date: str, end_date: str) -> list[str]:
    selected: list[str] = []
    try:
        start = _parse_replay_date(start_date, "2000-01-01").date()
        end = _parse_replay_date(end_date, today_kst()).date()
    except Exception:
        start = datetime.fromisoformat("2000-01-01").date()
        end = datetime.now(_zone("Asia/Seoul", 9)).date()
    for scenario in _capital_challenge_scenarios(start_year=max(2000, int(str(start.year)[:4]))):
        try:
            scenario_start = _parse_replay_date(str(scenario.get("start")), "2000-01-01").date()
            scenario_end = _parse_replay_date(str(scenario.get("end")), today_kst()).date()
        except Exception:
            continue
        if scenario_start <= end and scenario_end >= start:
            selected.extend(_normalize_tournament_symbols(list(scenario.get("symbols", []))))
    return _normalize_tournament_symbols(selected)


def _krx_full_universe_rows_for_tournament(limit: int = 400) -> tuple[str, list[dict[str, object]]]:
    try:
        work_date, rows = fetch_kr_market_rows(timeout=8.0)
    except Exception:
        return "", []
    tradable = [
        row for row in rows
        if isinstance(row, dict)
        and str(row.get("symbol") or "").isdigit()
        and str(row.get("market") or "").upper() in {"KOSPI", "KOSDAQ", "KR"}
        and _number(row.get("close")) > 0
        and _number(row.get("amount")) > 0
    ]
    tradable.sort(key=lambda row: _number(row.get("amount")), reverse=True)
    return work_date, tradable[: max(50, min(int(limit or 400), 1800))]


AI_STAFF_SYMBOL_SELECTION_LENSES: tuple[str, ...] = (
    "momentum_liquidity",
    "theme_breakout",
    "balanced_regime",
    "quality_survival",
)


def _ai_staff_symbol_selection_lens(agent_id: str, season_index: int = 0) -> dict[str, object]:
    seed_text = f"{agent_id}|{max(0, int(season_index or 0))}|open-symbol-lens"
    seed_hash = hashlib.sha256(seed_text.encode("utf-8")).hexdigest()
    lens_id = AI_STAFF_SYMBOL_SELECTION_LENSES[int(seed_hash[:12], 16) % len(AI_STAFF_SYMBOL_SELECTION_LENSES)]
    return {
        "id": lens_id,
        "selection_seed_hash": f"sha256:{seed_hash}",
        "agent_id": agent_id,
        "season_index": max(0, int(season_index or 0)),
        "all_lenses_open_to_all_staff": True,
        "role_restriction": False,
    }


def _ai_tournament_full_krx_symbols(
    contestant: dict[str, object],
    *,
    limit: int = 12,
    season_index: int = 0,
) -> tuple[list[str], str]:
    work_date, rows = _krx_full_universe_rows_for_tournament(limit=1800)
    if not rows:
        return [], "KRX 전체 종목 스캔 실패로 시대별 후보군 사용"
    agent_id = str(contestant.get("id") or "")
    lens = _ai_staff_symbol_selection_lens(agent_id, season_index)
    lens_id = str(lens.get("id") or "balanced_regime")
    theme_map = _intraday_theme_map_from_rows(rows)

    def row_score(row: dict[str, object]) -> float:
        symbol = str(row.get("symbol") or "").zfill(6)
        name = str(row.get("name") or "")
        change = _number(row.get("change_pct"))
        amount = _number(row.get("amount"))
        marcap = _number(row.get("marcap"))
        close = _number(row.get("close"))
        theme = theme_map.get(symbol, {})
        theme_bonus = 10.0 if theme.get("confirmed") else 0.0
        amount_eok = amount / 100_000_000
        marcap_eok = marcap / 100_000_000
        if lens_id == "momentum_liquidity":
            score = max(change, 0) * 5.0 + min(amount_eok, 3_000) / 15.0 + theme_bonus * 1.5
        elif lens_id == "theme_breakout":
            score = max(change, 0) * 4.0 + min(amount_eok, 2_000) / 25.0 + theme_bonus * 2.0
            if any(word in name.upper() for word in ("AI", "로봇", "반도체", "전력", "바이오", "조선", "방산")):
                score += 12
        elif lens_id == "quality_survival":
            score = min(marcap_eok, 500_000) / 12_000.0 + min(amount_eok, 1_500) / 30.0 - abs(change) * 1.2
            if close < 2_000:
                score -= 30
        else:
            score = min(marcap_eok, 300_000) / 15_000.0 + min(amount_eok, 2_000) / 30.0 + max(change, 0) * 2.0 + theme_bonus
        if close < 1_000:
            score -= 50
        if amount < 3_000_000_000:
            score -= 20
        return round(score, 4)

    ranked = sorted(rows, key=row_score, reverse=True)
    selected = _normalize_tournament_symbols([row.get("symbol") for row in ranked])
    if selected and season_index:
        offset = abs(int(season_index or 0)) % len(selected)
        selected = selected[offset:] + selected[:offset]
    clipped = selected[: max(3, min(int(limit or 12), 18))]
    return clipped, (
        f"KRX 전체 종목 자율 {lens_id} 관점 "
        f"({work_date}, 스캔 {len(rows)}개, 역할 제한 없음)"
    )


def _ai_tournament_symbols_for_contestant(
    contestant: dict[str, object],
    *,
    start_date: str,
    end_date: str,
    base_symbols: list[str],
    limit: int = 8,
    season_index: int = 0,
) -> tuple[list[str], str]:
    agent_id = str(contestant.get("id") or "")
    full_symbols, full_reason = _ai_tournament_full_krx_symbols(
        contestant,
        limit=max(3, min(int(limit or 8), 18)),
        season_index=season_index,
    )
    if full_symbols:
        return full_symbols, full_reason
    period_symbols = _ai_tournament_period_symbols(start_date, end_date)
    aggressive_pool = [
        "083450", "042700", "058470", "089030", "403870", "247540",
        "277810", "035720", "035420", "068270", "207940", "000660",
    ]
    quality_pool = [
        "005930", "000660", "005380", "000270", "012330", "051910",
        "006400", "035420", "068270", "207940", "105560", "015760",
    ]
    lens = _ai_staff_symbol_selection_lens(agent_id, season_index)
    lens_id = str(lens.get("id") or "balanced_regime")
    if lens_id in {"momentum_liquidity", "theme_breakout"}:
        raw = period_symbols + aggressive_pool + list(base_symbols) + quality_pool
    elif lens_id == "quality_survival":
        raw = quality_pool + period_symbols + list(base_symbols) + aggressive_pool
    else:
        raw = period_symbols + list(base_symbols) + quality_pool + aggressive_pool
    reason = f"자율 {lens_id} 종목 관점, 전 직원 전체 관점 사용 가능, 역할 제한 없음"
    selected = _normalize_tournament_symbols(raw)
    if not selected:
        selected = _ai_tournament_default_symbols(limit=limit)
    if selected:
        offset = abs(int(season_index or 0)) % len(selected)
        selected = selected[offset:] + selected[:offset]
    return selected[: max(3, min(int(limit or 8), 12))], reason


def _ai_tournament_windows_for_period(start_date: str, end_date: str, fast: int, slow: int) -> tuple[int, int, bool]:
    try:
        period_days = len(_business_dates(start_date, end_date, min_days=5))
    except Exception:
        period_days = 260
    fast = max(2, int(fast or 12))
    slow = max(fast + 1, int(slow or 32))
    max_slow = max(8, period_days - 6)
    if period_days < 60:
        max_slow = max(8, min(max_slow, int(period_days * 0.7)))
    if slow <= max_slow:
        return fast, slow, False
    adjusted_slow = max(fast + 1, min(slow, max_slow))
    adjusted_fast = min(fast, max(2, adjusted_slow // 2))
    if adjusted_fast >= adjusted_slow:
        adjusted_fast = max(2, adjusted_slow - 3)
    return adjusted_fast, adjusted_slow, True


def _ai_tournament_challenge_symbol_groups(
    contestant: dict[str, object],
    *,
    start_date: str,
    end_date: str,
    base_symbols: list[str],
    contestant_symbols: list[str],
    season_index: int = 0,
) -> list[dict[str, object]]:
    agent_id = str(contestant.get("id") or "")
    period_symbols = _ai_tournament_period_symbols(start_date, end_date)
    aggressive_pool = [
        "042700", "058470", "089030", "403870", "247540", "277810",
        "083450", "064350", "086520", "196170", "267260", "010120",
        "003230", "257720", "454910", "214150", "241710", "000660",
    ]
    quality_pool = [
        "005930", "000660", "005380", "000270", "012330", "051910",
        "006400", "035420", "068270", "207940", "105560", "015760",
    ]
    lens = _ai_staff_symbol_selection_lens(agent_id, season_index)
    lens_id = str(lens.get("id") or "balanced_regime")
    agent_pool = aggressive_pool + quality_pool
    pool_seed = int(
        hashlib.sha256(f"{agent_id}|{season_index}|symbol-pool".encode("utf-8")).hexdigest()[:12],
        16,
    )
    if agent_pool:
        pool_offset = pool_seed % len(agent_pool)
        agent_pool = agent_pool[pool_offset:] + agent_pool[:pool_offset]

    groups: list[dict[str, object]] = []
    seen: set[tuple[str, ...]] = set()

    def add(label: str, symbols: list[object] | tuple[object, ...], limit: int = 12) -> None:
        normalized = _normalize_tournament_symbols(list(symbols))
        if normalized and season_index:
            offset = abs(int(season_index or 0)) % len(normalized)
            normalized = normalized[offset:] + normalized[:offset]
        clipped = normalized[: max(3, min(int(limit or 12), 18))]
        key = tuple(clipped)
        if len(clipped) >= 3 and key not in seen:
            seen.add(key)
            groups.append({"label": label, "symbols": clipped})

    add("직원 기본 후보", contestant_symbols, limit=12)
    add(f"자율 {lens_id} 시기 후보", period_symbols + agent_pool + base_symbols, limit=12)
    add("독립 혼합 관점 후보", agent_pool + period_symbols + base_symbols, limit=12)
    full_symbols, full_reason = _ai_tournament_full_krx_symbols(
        contestant,
        limit=18,
        season_index=season_index,
    )
    if full_symbols:
        add(full_reason, full_symbols + agent_pool, limit=12)
    try:
        work_date, raw_rows = fetch_kr_market_rows(timeout=6.0)
        market_symbols = _daily_replay_drill_symbols(raw_rows, limit=12)
        add(f"KRX 거래대금/상승률 후보({work_date})", market_symbols + agent_pool, limit=12)
    except Exception:
        pass
    add("기본 백업 후보", aggressive_pool + quality_pool + base_symbols, limit=12)
    return groups[:5]


def _ai_staff_verified_strategy_memory_configs(
    contestant_id: str,
    *,
    before_date: str,
    limit: int = 6,
    records: list[dict[str, object]] | None = None,
) -> list[dict[str, object]]:
    """Return only point-in-time, evidence-gated strategies learned before a replay period."""
    try:
        current_start = datetime.fromisoformat(str(before_date)).date()
    except (TypeError, ValueError):
        return []
    source_records = records if records is not None else _read_jsonl(AI_TOURNAMENT_FILE, limit=600)
    candidates: list[dict[str, object]] = []
    for record in source_records:
        if not isinstance(record, dict):
            continue
        try:
            source_end = datetime.fromisoformat(str(record.get("end_date") or "")).date()
        except (TypeError, ValueError):
            continue
        if source_end >= current_start:
            continue
        rankings = record.get("rankings") if isinstance(record.get("rankings"), list) else []
        for row in rankings:
            if not isinstance(row, dict) or str(row.get("contestant_id") or "") != contestant_id:
                continue
            if _ai_staff_learning_claim_state(row).get("eligible") is not True:
                continue
            params = _ai_staff_strategy_parameters(row)
            if params.get("strategy") not in REPLAY_STRATEGY_PROFILES:
                continue
            candidates.append(
                {
                    "label": f"verified memory / {row.get('strategy_name') or params.get('strategy')}",
                    **params,
                    "candidate_origin": "verified_strategy_memory",
                    "strategy_memory_source_record_id": record.get("id"),
                    "strategy_memory_source_end_date": source_end.isoformat(),
                    "strategy_memory_score": _ai_tournament_challenge_ranking_score(row),
                }
            )
    candidates.sort(
        key=lambda row: (
            _number(row.get("strategy_memory_score")),
            str(row.get("strategy_memory_source_end_date") or ""),
        ),
        reverse=True,
    )
    deduped: list[dict[str, object]] = []
    seen: set[tuple[object, ...]] = set()
    for config in candidates:
        key = (
            config.get("strategy"),
            int(_number(config.get("fast"))),
            int(_number(config.get("slow"))),
            round(_number(config.get("stop")), 2),
            round(_number(config.get("take")), 2),
            int(_number(config.get("hold"))),
        )
        if key in seen:
            continue
        seen.add(key)
        config.setdefault("strategy_horizon", _replay_strategy_horizon(str(config.get("strategy") or "ma_cross")))
        profile = _replay_strategy_profile(str(config.get("strategy") or "ma_cross"))
        config.setdefault("master_strategy_proxy", bool(profile.get("master_proxy")))
        config.setdefault("stage2_requirements", list(profile.get("stage2_requirements") or []))
        deduped.append(config)
    return deduped[: max(0, min(int(limit or 6), 12))]


def _ai_staff_role_generated_strategy_configs(
    contestant: dict[str, object],
    *,
    season_index: int = 0,
) -> list[dict[str, object]]:
    role_id = str(contestant.get("id") or "")
    modes = AI_STAFF_ROLE_STRATEGY_MODES.get(role_id, (str(contestant.get("strategy_mode") or "ma_cross"),))
    allocation = float(contestant.get("allocation_pct", 25) or 25)
    max_positions = int(contestant.get("max_positions", 3) or 3)
    season = max(0, int(season_index or 0))
    indicator_names = list(RESEARCH_FORGE_INDICATORS.keys())
    generated: list[dict[str, object]] = []
    for mode in modes:
        profile = _replay_strategy_profile(mode)
        base_fast = int(profile.get("fast", contestant.get("fast", 12)) or 12)
        base_slow = int(profile.get("slow", contestant.get("slow", 32)) or 32)
        for variant_name, fast_factor, slow_factor, risk_factor in (
            ("fast", 0.75, 0.8, 1.0),
            ("balanced", 1.0, 1.0, 0.9),
            ("defensive", 1.2, 1.25, 0.72),
            ("experimental", 0.9, 1.1, 0.82),
            ("patient", 1.35, 1.5, 0.78),
            ("concentrated", 0.9, 1.05, 1.08),
        ):
            seed_text = f"{role_id}|{season}|{mode}|{variant_name}"
            seed_hash = hashlib.sha256(seed_text.encode("utf-8")).hexdigest()
            seed = int(seed_hash[:12], 16)
            fast_jitter = ((seed % 17) - 8) / 100.0
            slow_jitter = (((seed // 17) % 21) - 10) / 100.0
            risk_jitter = (((seed // 357) % 15) - 7) / 100.0
            fast = max(2, int(round(base_fast * max(0.55, fast_factor + fast_jitter))))
            slow = max(fast + 3, int(round(base_slow * max(0.7, slow_factor + slow_jitter))))
            effective_risk = max(0.55, risk_factor + risk_jitter)
            hypothesis_start = seed % len(indicator_names)
            hypothesis = [
                indicator_names[hypothesis_start],
                indicator_names[(hypothesis_start + 1 + (seed % 5)) % len(indicator_names)],
            ]
            generation_id = f"{role_id}-S{season:05d}-{mode}-{variant_name}-{seed_hash[:10]}"
            generated.append(
                {
                    "strategy": mode,
                    "label": f"{role_id} generated S{season} {mode} {variant_name}",
                    "fast": fast,
                    "slow": slow,
                    "stop": round(max(1.0, _number(profile.get("stop_loss_pct")) * effective_risk), 2),
                    "take": round(max(0.0, _number(profile.get("take_profit_pct")) * (2.0 - effective_risk)), 2),
                    "hold": max(0, int(_number(profile.get("holding_limit_days"))) + ((seed // 5355) % 3) - 1),
                    "allocation": round(max(10.0, min(80.0, allocation * effective_risk)), 2),
                    "max_positions": max(
                        1,
                        max_positions
                        + (1 if variant_name == "defensive" else 0)
                        - (1 if variant_name == "concentrated" else 0),
                    ),
                    "candidate_origin": "role_generated",
                    "generated_variant": variant_name,
                    "strategy_generation_id": generation_id,
                    "strategy_generation_season": season,
                    "open_ended_generation": True,
                    "indicator_recipe": list(AI_STAFF_NATIVE_INDICATOR_RECIPES.get(mode, ("SMA", "RSI"))),
                    "research_indicator_hypothesis": hypothesis,
                    "research_stage_required": any(name not in {"SMA", "RSI", "ROC"} for name in hypothesis),
                    "capital_growth_goal": {
                        "start_capital_krw": 10_000_000,
                        "target_capital_krw": 10_000_000_000,
                        "target_multiple": 1000,
                    },
                }
            )
    return generated


def _ai_tournament_challenge_configs(
    contestant: dict[str, object],
    trial_budget: int = 6,
    *,
    before_date: str | None = None,
    end_date: str | None = None,
    season_index: int = 0,
) -> list[dict[str, object]]:
    base = {
        "label": str(contestant.get("strategy_name") or contestant.get("strategy_mode") or "직원 기본 전술"),
        "strategy": str(contestant.get("strategy_mode") or "ma_cross"),
        "fast": int(contestant.get("fast", 12) or 12),
        "slow": int(contestant.get("slow", 32) or 32),
        "allocation": float(contestant.get("allocation_pct", 25) or 25),
        "max_positions": int(contestant.get("max_positions", 3) or 3),
        "stop": float(contestant.get("stop_loss_pct", 8) or 8),
        "take": float(contestant.get("take_profit_pct", 0) or 0),
        "hold": int(contestant.get("holding_limit_days", 0) or 0),
        "candidate_origin": "role_baseline",
    }
    role_id = str(contestant.get("id") or "")
    aggressive = [
        {"strategy": "intraday_theme_leader", "label": "챔피언 추격 단타 2/8", "fast": 2, "slow": 8, "stop": 1.2, "take": 3.0, "hold": 1, "allocation": 80, "max_positions": 1},
        {"strategy": "intraday_theme_leader", "label": "주도테마 압축 3/10", "fast": 3, "slow": 10, "stop": 1.8, "take": 4.5, "hold": 2, "allocation": 70, "max_positions": 2},
        {"strategy": "breakout", "label": "거래대금 돌파 3/12", "fast": 3, "slow": 12, "stop": 2.5, "take": 8.0, "hold": 3, "allocation": 65, "max_positions": 2},
        {"strategy": "short_swing", "label": "급등 눌림 스윙 4/14", "fast": 4, "slow": 14, "stop": 3.0, "take": 10.0, "hold": 4, "allocation": 60, "max_positions": 2},
        {"strategy": "breakout", "label": "고변동 신고가 추격 5/18", "fast": 5, "slow": 18, "stop": 4.0, "take": 15.0, "hold": 6, "allocation": 55, "max_positions": 2},
        {"strategy": "protected_ma", "label": "수익 보존 추세 5/16", "fast": 5, "slow": 16, "stop": 2.8, "take": 7.0, "hold": 5, "allocation": 45, "max_positions": 3},
    ]
    learned = _ai_staff_verified_strategy_memory_configs(
        role_id,
        before_date=str(before_date),
        limit=6,
    ) if before_date else []
    for config in aggressive:
        config.setdefault("candidate_origin", "role_seed")
    generated = _ai_staff_role_generated_strategy_configs(contestant, season_index=season_index)
    configs = [base] + learned + aggressive + generated
    rejected_generated = _ai_staff_counterfactual_rejected_strategy_ids(role_id)
    if rejected_generated:
        configs = [
            config for config in configs
            if str(config.get("strategy_generation_id") or "") not in rejected_generated
        ]
    deduped: list[dict[str, object]] = []
    seen: set[tuple[object, ...]] = set()
    for config in configs:
        key = (
            config.get("strategy"),
            int(config.get("fast", 0) or 0),
            int(config.get("slow", 0) or 0),
            float(config.get("allocation", 0) or 0),
            int(config.get("max_positions", 0) or 0),
        )
        if key in seen:
            continue
        seen.add(key)
        config.setdefault("strategy_horizon", _replay_strategy_horizon(str(config.get("strategy") or "ma_cross")))
        profile = _replay_strategy_profile(str(config.get("strategy") or "ma_cross"))
        config.setdefault("master_strategy_proxy", bool(profile.get("master_proxy")))
        config.setdefault("stage2_requirements", list(profile.get("stage2_requirements") or []))
        config.setdefault("minimum_history_bars", int(_number(profile.get("minimum_history_bars"))))
        deduped.append(config)
    arena = _ai_staff_training_arena(before_date, end_date, season_index)
    allowed_horizons = set(str(item) for item in arena.get("allowed_horizons", []))
    available_bars = int(_number(arena.get("estimated_business_bars")))
    eligible = [
        item for item in deduped
        if str(item.get("strategy_horizon")) in allowed_horizons
        and (not arena.get("master_only") or item.get("master_strategy_proxy") is True)
        and (
            int(_number(item.get("minimum_history_bars"))) <= 0
            or int(_number(item.get("minimum_history_bars"))) <= available_bars
        )
    ]
    if not eligible:
        eligible = list(deduped)
    available_count = len(eligible)
    budget = max(1, min(int(trial_budget or 6), 12))
    def rotate(rows: list[dict[str, object]], salt: str) -> list[dict[str, object]]:
        if not rows:
            return []
        digest = hashlib.sha256(
            f"{role_id}|{arena.get('selection_seed_hash')}|{salt}".encode("utf-8")
        ).hexdigest()
        offset = int(digest[:12], 16) % len(rows)
        return rows[offset:] + rows[:offset]

    memory_candidates = rotate(
        [item for item in eligible if item.get("candidate_origin") == "verified_strategy_memory"],
        "exploit-memory",
    )
    generated_candidates = rotate(
        [item for item in eligible if item.get("candidate_origin") == "role_generated"],
        "explore-generated",
    )
    other_candidates = rotate(
        [
            item for item in eligible
            if item.get("candidate_origin") not in {"verified_strategy_memory", "role_generated"}
        ],
        "seed-and-baseline",
    )
    autonomous_draft: list[dict[str, object]] = []
    if memory_candidates:
        memory_candidates[0]["autonomous_choice_basis"] = "verified prior winner exploitation"
        autonomous_draft.append(memory_candidates[0])
    if generated_candidates:
        generated_candidates[0]["autonomous_choice_basis"] = "new strategy exploration"
        autonomous_draft.append(generated_candidates[0])
    autonomous_draft.extend(rotate(generated_candidates + memory_candidates + other_candidates, "free-draft"))
    distinct_modes: list[dict[str, object]] = []
    repeated_modes: list[dict[str, object]] = []
    drafted_modes: set[str] = set()
    for item in autonomous_draft:
        mode = str(item.get("strategy") or "ma_cross")
        if mode in drafted_modes:
            repeated_modes.append(item)
            continue
        drafted_modes.add(mode)
        distinct_modes.append(item)
    autonomous_draft = distinct_modes + repeated_modes
    selected: list[dict[str, object]] = []
    selected_keys: set[tuple[object, ...]] = set()
    for item in autonomous_draft:
        item_key = (
            item.get("strategy"),
            int(_number(item.get("fast"))),
            int(_number(item.get("slow"))),
            float(_number(item.get("allocation"))),
            int(_number(item.get("max_positions"))),
        )
        if item_key in selected_keys:
            continue
        item.setdefault("autonomous_choice_basis", "independent arena draft")
        if rejected_generated:
            item["counterfactual_rejection_filter"] = {
                "active": True,
                "blocked_strategy_count": len(rejected_generated),
                "blocked_strategy_ids": sorted(rejected_generated)[:12],
                "live_candidate_allowed": False,
                "score_promotion_allowed": False,
                "policy": "directionally_regressed_generated_strategies_are_excluded",
            }
        selected.append(item)
        selected_keys.add(item_key)
        if len(selected) >= budget:
            break
    origins = sorted({str(item.get("candidate_origin") or "unknown") for item in eligible})
    horizon_mix = {
        horizon: sum(1 for item in selected if item.get("strategy_horizon") == horizon)
        for horizon in ("daytrade", "swing", "mid_term", "long_term")
    }
    for config in selected:
        config["strategy_library_candidate_count"] = available_count
        config["strategy_library_total_candidate_count"] = len(deduped)
        config["strategy_library_tested_count"] = len(selected)
        config["strategy_library_origins"] = origins
        config["strategy_library_season_index"] = max(0, int(season_index or 0))
        config["strategy_library_open_ended"] = True
        config["strategy_lifetime_limit"] = None
        config["strategy_horizon_mix"] = horizon_mix
        config["training_arena"] = dict(arena)
        config["agent_strategy_autonomy"] = True
        config["role_strategy_restriction"] = False
        config.setdefault(
            "indicator_recipe",
            list(AI_STAFF_NATIVE_INDICATOR_RECIPES.get(str(config.get("strategy") or "ma_cross"), ("SMA", "RSI"))),
        )
    return selected


def _ai_staff_strategy_parameters(row: dict[str, object]) -> dict[str, object]:
    config = row.get("selected_challenge_config") if isinstance(row.get("selected_challenge_config"), dict) else {}
    return {
        "strategy": str(row.get("strategy_mode") or row.get("strategy") or config.get("strategy_mode") or config.get("strategy") or "ma_cross"),
        "fast": int(_number(row.get("fast_window") or row.get("fast") or config.get("fast_window") or config.get("fast")) or 0),
        "slow": int(_number(row.get("slow_window") or row.get("slow") or config.get("slow_window") or config.get("slow")) or 0),
        "stop": round(_number(config.get("stop_loss_pct") or row.get("stop_loss_pct") or row.get("stop")), 4),
        "take": round(_number(config.get("take_profit_pct") or row.get("take_profit_pct") or row.get("take")), 4),
        "hold": int(_number(config.get("holding_limit_days") or row.get("holding_limit_days") or row.get("hold")) or 0),
        "allocation": round(_number(config.get("allocation_pct") or row.get("allocation_pct") or row.get("allocation")), 4),
        "max_positions": int(_number(config.get("max_positions") or row.get("max_positions")) or 0),
    }


def _ai_staff_strategy_signature(row: dict[str, object]) -> str:
    return hashlib.sha256(
        json.dumps(_ai_staff_strategy_parameters(row), ensure_ascii=True, sort_keys=True).encode("utf-8")
    ).hexdigest()


def _ai_staff_learning_source_hash(record: dict[str, object], row: dict[str, object]) -> str:
    payload = {
        "record_id": record.get("id"),
        "contestant_id": row.get("contestant_id"),
        "start_date": record.get("start_date"),
        "end_date": record.get("end_date"),
        "actual_start_date": row.get("actual_start_date"),
        "actual_end_date": row.get("actual_end_date"),
        "strategy": _ai_staff_strategy_parameters(row),
        "total_return_pct": row.get("total_return_pct"),
        "max_drawdown_pct": row.get("max_drawdown_pct"),
        "win_rate_pct": row.get("win_rate_pct"),
        "trade_count": row.get("trade_count"),
        "cost_model": row.get("cost_model"),
        "return_reconciliation_summary": row.get("return_reconciliation_summary"),
        "monte_carlo_stress": row.get("monte_carlo_stress"),
    }
    return hashlib.sha256(
        json.dumps(payload, ensure_ascii=True, sort_keys=True).encode("utf-8")
    ).hexdigest()


def _ai_staff_period_performance(record: dict[str, object], row: dict[str, object]) -> dict[str, object]:
    try:
        start = datetime.fromisoformat(str(row.get("actual_start_date") or record.get("start_date") or "")).date()
        end = datetime.fromisoformat(str(row.get("actual_end_date") or record.get("end_date") or "")).date()
        days = (end - start).days
    except (TypeError, ValueError):
        days = 0
    total_return = _number(row.get("total_return_pct"))
    horizon_years = max(0.0, days / 365.25)
    multiple = 1.0 + total_return / 100.0
    annualized: float | None = None
    if days >= 60 and multiple > 0:
        annualized = (multiple ** (365.25 / days) - 1.0) * 100.0
        annualized = _clamp(annualized, -100.0, 500.0)
    mdd = abs(_number(row.get("max_drawdown_pct")))
    risk_adjusted = annualized - mdd * 0.5 if annualized is not None else None
    return {
        "valid": annualized is not None,
        "period_days": days,
        "horizon_years": round(horizon_years, 4),
        "total_return_pct": round(total_return, 4),
        "annualized_return_pct": round(annualized, 4) if annualized is not None else None,
        "max_drawdown_pct": round(mdd, 4),
        "risk_adjusted_score": round(risk_adjusted, 4) if risk_adjusted is not None else None,
        "trade_count": int(_number(row.get("trade_count"))),
    }


def _ai_staff_replay_journal_diagnosis(
    record: dict[str, object],
    row: dict[str, object],
) -> dict[str, object]:
    performance = _ai_staff_period_performance(record, row)
    horizon_years = max(0.0, _number(performance.get("horizon_years")))
    period_days = max(0, int(_number(performance.get("period_days"))))
    action_count = int(_number(row.get("trade_count")))
    closed_count = int(_number(row.get("closed_trade_count")))
    avg_win_pct = _number(row.get("average_win_pct"))
    avg_loss_abs_pct = abs(_number(row.get("average_loss_pct")))
    total_return_pct = _number(row.get("total_return_pct"))
    cost_pct = max(0.0, _number(row.get("transaction_cost_pct_of_initial_cash")))
    bottom_trades = row.get("bottom_trades") if isinstance(row.get("bottom_trades"), list) else []
    if not bottom_trades:
        bottom_trades = row.get("trade_journal_bottom10") if isinstance(row.get("trade_journal_bottom10"), list) else []
    sampled_exit_reasons = [
        str(item.get("exit_reason") or item.get("reason") or "").strip().lower()
        for item in bottom_trades
        if isinstance(item, dict)
    ]
    stop_loss_sample_count = sum(
        1
        for reason in sampled_exit_reasons
        if any(token in reason for token in ("stop", "loss", "손절", "방어"))
    )
    reason_codes: list[str] = []
    lessons: list[str] = []
    if closed_count <= 0:
        reason_codes.append("no_closed_trades")
        lessons.append("No closed trades: entry conditions were too restrictive or the exit lifecycle never completed.")
    minimum_closed_trade_count = (
        max(3, int(math.ceil(horizon_years * 1.5)))
        if period_days >= 60
        else 1
    )
    if 0 < closed_count < minimum_closed_trade_count:
        reason_codes.append("too_few_closed_trades")
        lessons.append("Too few closed trades for the tested horizon: increase signal opportunity without removing risk gates.")
    if closed_count >= 3 and avg_loss_abs_pct > max(1.0, avg_win_pct * 1.2):
        reason_codes.append("unfavorable_payoff_ratio")
        lessons.append("Average loss materially exceeded average win: tighten losses and require a larger reward target.")
    if action_count >= 20 and cost_pct >= 1.0 and cost_pct > max(0.5, abs(total_return_pct) * 0.2):
        reason_codes.append("transaction_cost_drag")
        lessons.append("Transaction costs consumed too much of the result: reduce turnover and extend the signal horizon.")
    if len(sampled_exit_reasons) >= 3 and stop_loss_sample_count / len(sampled_exit_reasons) >= 0.6:
        reason_codes.append("stop_loss_concentration")
        lessons.append("Most sampled losses exited through defensive stops: require stronger entries before changing the stop budget.")
    return {
        "schema": "codexstock_ai_staff_replay_journal_diagnosis_v1",
        "reason_codes": list(dict.fromkeys(reason_codes)),
        "lessons": lessons,
        "metrics": {
            "horizon_years": round(horizon_years, 4),
            "period_days": period_days,
            "minimum_closed_trade_count": minimum_closed_trade_count,
            "action_count": action_count,
            "closed_trade_count": closed_count,
            "average_win_pct": round(avg_win_pct, 4),
            "average_loss_abs_pct": round(avg_loss_abs_pct, 4),
            "total_return_pct": round(total_return_pct, 4),
            "transaction_cost_pct_of_initial_cash": round(cost_pct, 4),
            "sampled_loss_exit_count": len(sampled_exit_reasons),
            "sampled_stop_loss_count": stop_loss_sample_count,
        },
        "source": "reconciled_replay_trade_journal_and_summary",
        "live_order_allowed": False,
    }


def _ai_staff_learning_counterfactual_hash(
    control: dict[str, object],
    target_row: dict[str, object],
) -> str:
    safe_control = {key: value for key, value in control.items() if key != "evidence_hash"}
    target_payload = {
        "contestant_id": target_row.get("contestant_id"),
        "actual_start_date": target_row.get("actual_start_date"),
        "actual_end_date": target_row.get("actual_end_date"),
        "selected_symbols": target_row.get("selected_symbols"),
        "strategy": _ai_staff_strategy_parameters(target_row),
        "total_return_pct": target_row.get("total_return_pct"),
        "max_drawdown_pct": target_row.get("max_drawdown_pct"),
        "win_rate_pct": target_row.get("win_rate_pct"),
        "trade_count": target_row.get("trade_count"),
        "cost_model": target_row.get("cost_model"),
        "transaction_cost_audit": target_row.get("transaction_cost_audit"),
        "execution_timing_model": target_row.get("execution_timing_model"),
        "data_coverage": target_row.get("data_coverage"),
        "price_currency_unit_audit": target_row.get("price_currency_unit_audit"),
        "return_reconciliation_summary": target_row.get("return_reconciliation_summary"),
    }
    return hashlib.sha256(
        json.dumps(
            {"control": safe_control, "target": target_payload},
            ensure_ascii=True,
            sort_keys=True,
        ).encode("utf-8")
    ).hexdigest()


AI_STAFF_LEARNING_TRANSITION_SCHEMA = "codexstock_ai_staff_causal_learning_transition_v1"


def _ai_staff_learning_transition_hash(transition: dict[str, object]) -> str:
    material = dict(transition)
    material.pop("transition_hash", None)
    return hashlib.sha256(
        json.dumps(material, ensure_ascii=True, sort_keys=True).encode("utf-8")
    ).hexdigest()


def _ai_staff_learning_transition_status(
    transition: dict[str, object] | None,
) -> dict[str, object]:
    """Validate that an adapted strategy is causally tied to prior official evidence."""
    row = transition if isinstance(transition, dict) else {}
    blockers: list[str] = []
    if row.get("schema") != AI_STAFF_LEARNING_TRANSITION_SCHEMA:
        blockers.append("learning_transition_schema_mismatch")
    source_record_id = str(row.get("source_record_id") or "").strip()
    source_evidence_hash = str(row.get("source_evidence_hash") or "").strip().lower()
    if not source_record_id:
        blockers.append("learning_transition_source_record_missing")
    if not re.fullmatch(r"[0-9a-f]{64}", source_evidence_hash):
        blockers.append("learning_transition_source_evidence_hash_invalid")
    reason_codes = [
        str(item).strip()
        for item in row.get("reason_codes", [])
        if str(item).strip()
    ] if isinstance(row.get("reason_codes"), list) else []
    if not reason_codes:
        blockers.append("learning_transition_reason_codes_missing")
    baseline = row.get("baseline_strategy") if isinstance(row.get("baseline_strategy"), dict) else {}
    adapted = row.get("adapted_strategy") if isinstance(row.get("adapted_strategy"), dict) else {}
    changes = row.get("adaptation_changes") if isinstance(row.get("adaptation_changes"), dict) else {}
    if not baseline or not adapted:
        blockers.append("learning_transition_strategy_pair_missing")
    elif baseline == adapted or not changes:
        blockers.append("learning_transition_no_parameter_change")
    source_period = row.get("source_period") if isinstance(row.get("source_period"), dict) else {}
    source_end_text = str(source_period.get("end_date") or "")
    target_start_text = str(row.get("target_start_date") or "")
    try:
        source_end = datetime.fromisoformat(source_end_text).date()
        target_start = datetime.fromisoformat(target_start_text).date()
        if source_end >= target_start:
            blockers.append("learning_transition_source_target_overlap")
    except (TypeError, ValueError):
        blockers.append("learning_transition_period_invalid")
    if row.get("paper_only") is not True:
        blockers.append("learning_transition_not_paper_only")
    if row.get("live_order_allowed") is not False:
        blockers.append("learning_transition_live_order_not_blocked")
    if row.get("unverified_result_affects_score") is not False:
        blockers.append("learning_transition_unverified_score_effect_not_blocked")
    if row.get("unverified_result_affects_live_candidate") is not False:
        blockers.append("learning_transition_unverified_live_effect_not_blocked")
    stored_hash = str(row.get("transition_hash") or "")
    calculated_hash = _ai_staff_learning_transition_hash(row) if row else ""
    hash_valid = bool(stored_hash and stored_hash == calculated_hash)
    if not hash_valid:
        blockers.append("learning_transition_hash_mismatch")
    return {
        "valid": not blockers,
        "blockers": list(dict.fromkeys(blockers)),
        "stored_hash": stored_hash,
        "calculated_hash": calculated_hash,
        "hash_valid": hash_valid,
        "source_record_id": source_record_id,
        "source_evidence_hash": source_evidence_hash,
        "paper_only": True,
        "live_order_allowed": False,
    }


def _build_ai_staff_causal_learning_transition(
    context: dict[str, object],
    baseline_config: dict[str, object],
    adapted_config: dict[str, object],
    *,
    target_start_date: str,
) -> dict[str, object]:
    baseline = _ai_staff_strategy_parameters(baseline_config)
    adapted = _ai_staff_strategy_parameters(adapted_config)
    changes = {
        key: {"before": baseline.get(key), "after": adapted.get(key)}
        for key in baseline
        if baseline.get(key) != adapted.get(key)
    }
    provenance = (
        adapted_config.get("_learning_provenance")
        if isinstance(adapted_config.get("_learning_provenance"), dict)
        else {}
    )
    transition: dict[str, object] = {
        "schema": AI_STAFF_LEARNING_TRANSITION_SCHEMA,
        "source_record_id": str(context.get("source_record_id") or ""),
        "source_evidence_hash": str(context.get("source_evidence_hash") or ""),
        "source_contestant_id": str(context.get("source_contestant_id") or ""),
        "source_period": {
            "start_date": context.get("source_start_date"),
            "end_date": context.get("source_end_date"),
        },
        "target_start_date": str(target_start_date),
        "reason_codes": [
            str(item)
            for item in context.get("reason_codes", [])
            if str(item)
        ] if isinstance(context.get("reason_codes"), list) else [],
        "baseline_strategy": baseline,
        "adapted_strategy": adapted,
        "adaptation_changes": changes,
        "adaptation_algorithm": str(
            provenance.get("adaptation_algorithm")
            or "open_library_arena_constrained_evidence_draft_v2"
        ),
        "actionable_reason_codes": provenance.get("actionable_reason_codes", []),
        "non_actionable_reason_codes": provenance.get("non_actionable_reason_codes", []),
        "adaptation_blockers": provenance.get("adaptation_blockers", []),
        "risk_budget_scale_up_gate": provenance.get("risk_budget_scale_up_gate", {}),
        "source_metrics": context.get("source_metrics", {}),
        "source_raw_metrics": context.get("source_raw_metrics", {}),
        "journal_diagnosis": context.get("journal_diagnosis", {}),
        "paper_only": True,
        "live_order_allowed": False,
        "unverified_result_affects_score": False,
        "unverified_result_affects_live_candidate": False,
    }
    transition["transition_hash"] = _ai_staff_learning_transition_hash(transition)
    return transition


AI_STAFF_LEARNING_MIN_VALIDATED_PAIRS = 3
AI_STAFF_LEARNING_MIN_IMPROVED_PAIRS = 2
AI_STAFF_COUNTERFACTUAL_EXECUTION_CONTRACT_SCHEMA = (
    "codexstock_ai_staff_counterfactual_execution_contract_v1"
)


def _ai_staff_counterfactual_execution_contract_hash(
    contract: dict[str, object],
) -> str:
    material = dict(contract)
    material.pop("contract_hash", None)
    return "sha256:" + hashlib.sha256(
        json.dumps(
            material,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _ai_staff_counterfactual_execution_contract_status(
    row: dict[str, object],
) -> dict[str, object]:
    contract = (
        row.get("execution_comparison_contract")
        if isinstance(row.get("execution_comparison_contract"), dict)
        else {}
    )
    blockers: list[str] = []
    if contract.get("schema") != AI_STAFF_COUNTERFACTUAL_EXECUTION_CONTRACT_SCHEMA:
        blockers.append("execution_contract_missing_or_invalid")
    calculated_hash = _ai_staff_counterfactual_execution_contract_hash(contract) if contract else ""
    stored_hash = str(contract.get("contract_hash") or "")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", stored_hash):
        blockers.append("execution_contract_hash_missing")
    elif not hmac.compare_digest(stored_hash, calculated_hash):
        blockers.append("execution_contract_hash_mismatch")
    if str(row.get("execution_comparison_contract_hash") or "") != stored_hash:
        blockers.append("ledger_execution_contract_hash_mismatch")
    expected_symbols = [
        str(symbol)
        for symbol in row.get("symbols", [])
        if str(symbol)
    ] if isinstance(row.get("symbols"), list) else []
    if [str(symbol) for symbol in contract.get("symbols", []) if str(symbol)] != expected_symbols:
        blockers.append("execution_contract_symbols_mismatch")
    if str(contract.get("start_date") or "") != str(row.get("start_date") or ""):
        blockers.append("execution_contract_start_date_mismatch")
    if str(contract.get("end_date") or "") != str(row.get("end_date") or ""):
        blockers.append("execution_contract_end_date_mismatch")
    initial_cash = _number(contract.get("initial_cash"))
    if initial_cash <= 0 or abs(initial_cash - _number(row.get("initial_cash"))) > 0.000001:
        blockers.append("execution_contract_initial_cash_mismatch")
    cycles_per_day = int(_number(contract.get("cycles_per_day")))
    if cycles_per_day != 24 or cycles_per_day != int(_number(row.get("cycles_per_day"))):
        blockers.append("execution_contract_cycle_count_mismatch")
    minimum_bars = int(_number(contract.get("minimum_bars")))
    if minimum_bars < 8 or minimum_bars != int(_number(row.get("shared_replay_min_bars"))):
        blockers.append("execution_contract_minimum_bars_mismatch")
    if contract.get("shared_replay_data_bundle_required") is not True:
        blockers.append("execution_contract_shared_bundle_not_required")
    if contract.get("allow_simulated_fallback") is not False or row.get("allow_simulated_fallback") is not False:
        blockers.append("execution_contract_simulated_fallback_not_blocked")
    if contract.get("paper_only") is not True or contract.get("live_order_allowed") is not False:
        blockers.append("execution_contract_paper_guard_missing")
    return {
        "valid": not blockers,
        "blockers": list(dict.fromkeys(blockers)),
        "contract_hash": stored_hash,
        "paper_only": True,
        "live_order_allowed": False,
    }


def _ai_staff_counterfactual_replay_bundle_status(
    row: dict[str, object],
) -> dict[str, object]:
    evidence = (
        row.get("replay_data_bundle_evidence")
        if isinstance(row.get("replay_data_bundle_evidence"), dict)
        else {}
    )
    blockers: list[str] = []
    expected_symbols = [
        str(symbol)
        for symbol in row.get("symbols", [])
        if str(symbol)
    ] if isinstance(row.get("symbols"), list) else []
    requested_period = {
        "start_date": str(row.get("start_date") or ""),
        "end_date": str(row.get("end_date") or ""),
    }
    if (
        evidence.get("schema") != HISTORICAL_REPLAY_DATA_BUNDLE_SLICE_EVIDENCE_SCHEMA
        or evidence.get("used") is not True
        or evidence.get("passed") is not True
        or evidence.get("source_fetch_reused") is not True
        or evidence.get("future_rows_excluded_before_strategy") is not True
        or evidence.get("no_rows_outside_requested_period") is not True
        or evidence.get("live_order_allowed") is not False
    ):
        blockers.append("immutable_replay_data_bundle_not_verified")
    bundle_hash = str(evidence.get("bundle_content_hash") or "")
    slice_hash = str(evidence.get("slice_content_hash") or "")
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", bundle_hash) or not re.fullmatch(
        r"sha256:[0-9a-f]{64}", slice_hash
    ):
        blockers.append("replay_data_bundle_hash_missing_or_invalid")
    if evidence.get("requested_period") != requested_period:
        blockers.append("replay_data_bundle_period_mismatch")
    if [str(symbol) for symbol in evidence.get("symbols", []) if str(symbol)] != expected_symbols:
        blockers.append("replay_data_bundle_symbols_mismatch")
    row_counts = evidence.get("symbol_row_counts") if isinstance(evidence.get("symbol_row_counts"), dict) else {}
    row_bounds = evidence.get("symbol_row_bounds") if isinstance(evidence.get("symbol_row_bounds"), dict) else {}
    calendar_roots = (
        evidence.get("symbol_calendar_adjacency_roots")
        if isinstance(evidence.get("symbol_calendar_adjacency_roots"), dict)
        else {}
    )
    calendar_pair_counts = (
        evidence.get("symbol_calendar_pair_counts")
        if isinstance(evidence.get("symbol_calendar_pair_counts"), dict)
        else {}
    )
    if (
        set(row_counts) != set(expected_symbols)
        or set(row_bounds) != set(expected_symbols)
        or set(calendar_roots) != set(expected_symbols)
        or set(calendar_pair_counts) != set(expected_symbols)
        or any(int(_number(row_counts.get(symbol))) <= 0 for symbol in expected_symbols)
        or any(
            not re.fullmatch(r"[0-9a-f]{64}", str(calendar_roots.get(symbol) or ""))
            or int(_number(calendar_pair_counts.get(symbol)))
            != max(0, int(_number(row_counts.get(symbol))) - 1)
            for symbol in expected_symbols
        )
    ):
        blockers.append("replay_data_bundle_symbol_coverage_incomplete")
    expected_manifest_hash = _replay_data_bundle_slice_manifest_hash(evidence) if evidence else ""
    if not hmac.compare_digest(
        str(evidence.get("slice_manifest_hash") or ""),
        expected_manifest_hash,
    ):
        blockers.append("replay_data_bundle_manifest_hash_mismatch")
    return {
        "valid": not blockers,
        "blockers": list(dict.fromkeys(blockers)),
        "bundle_content_hash": bundle_hash,
        "slice_content_hash": slice_hash,
        "slice_manifest_hash": evidence.get("slice_manifest_hash"),
        "paper_only": True,
        "live_order_allowed": False,
    }


def _ai_staff_learning_confidence_blockers(statistics: dict[str, object]) -> list[str]:
    blockers: list[str] = []
    sample_count = int(_number(statistics.get("sample_count")))
    improved_count = int(_number(statistics.get("improved_pair_count")))
    confidence_low_raw = statistics.get("confidence_interval_low")
    confidence_low = _number(confidence_low_raw) if confidence_low_raw is not None else None
    mean_raw = statistics.get("mean_risk_adjusted_improvement")
    mean = _number(mean_raw) if mean_raw is not None else None
    if sample_count < AI_STAFF_LEARNING_MIN_VALIDATED_PAIRS:
        blockers.append("validated_pair_count_below_minimum")
    if improved_count < AI_STAFF_LEARNING_MIN_IMPROVED_PAIRS:
        blockers.append("improved_pair_count_below_minimum")
    if confidence_low is None:
        blockers.append("confidence_interval_not_available")
    elif confidence_low <= 0.0:
        blockers.append("confidence_interval_low_not_positive")
    if mean is not None and mean <= 0.0:
        blockers.append("mean_risk_adjusted_improvement_not_positive")
    return list(dict.fromkeys(blockers))


def _ai_staff_learning_effect_statistics(improvements: list[float]) -> dict[str, object]:
    """Measure a paired learning effect without treating one lucky replay as growth."""
    values = [float(value) for value in improvements if math.isfinite(float(value))]
    sample_count = len(values)
    if not values:
        empty_statistics = {
            "sample_count": 0,
            "mean_risk_adjusted_improvement": None,
            "median_risk_adjusted_improvement": None,
            "sample_stddev": None,
            "confidence_level_pct": 95.0,
            "confidence_interval_low": None,
            "confidence_interval_high": None,
            "improved_pair_count": 0,
            "confidence_gate_passed": False,
        }
        empty_statistics["confidence_gate_blockers"] = _ai_staff_learning_confidence_blockers(empty_statistics)
        empty_statistics["additional_validated_pair_count_needed"] = AI_STAFF_LEARNING_MIN_VALIDATED_PAIRS
        empty_statistics["additional_improved_pair_count_needed"] = AI_STAFF_LEARNING_MIN_IMPROVED_PAIRS
        return empty_statistics

    ordered = sorted(values)
    midpoint = sample_count // 2
    median = ordered[midpoint] if sample_count % 2 else (ordered[midpoint - 1] + ordered[midpoint]) / 2.0
    mean = sum(values) / sample_count
    stddev: float | None = None
    confidence_low: float | None = None
    confidence_high: float | None = None
    if sample_count >= 2:
        variance = sum((value - mean) ** 2 for value in values) / (sample_count - 1)
        stddev = math.sqrt(max(0.0, variance))
        t_critical_95 = {
            1: 12.706, 2: 4.303, 3: 3.182, 4: 2.776, 5: 2.571,
            6: 2.447, 7: 2.365, 8: 2.306, 9: 2.262, 10: 2.228,
            11: 2.201, 12: 2.179, 13: 2.160, 14: 2.145, 15: 2.131,
            16: 2.120, 17: 2.110, 18: 2.101, 19: 2.093, 20: 2.086,
            21: 2.080, 22: 2.074, 23: 2.069, 24: 2.064, 25: 2.060,
            26: 2.056, 27: 2.052, 28: 2.048, 29: 2.045, 30: 2.042,
        }.get(sample_count - 1, 1.96)
        margin = t_critical_95 * stddev / math.sqrt(sample_count)
        confidence_low = mean - margin
        confidence_high = mean + margin
    improved_count = sum(1 for value in values if value >= 1.0)
    confidence_gate_passed = bool(
        sample_count >= AI_STAFF_LEARNING_MIN_VALIDATED_PAIRS
        and improved_count >= AI_STAFF_LEARNING_MIN_IMPROVED_PAIRS
        and confidence_low is not None
        and confidence_low > 0.0
    )
    statistics = {
        "sample_count": sample_count,
        "mean_risk_adjusted_improvement": round(mean, 4),
        "median_risk_adjusted_improvement": round(median, 4),
        "sample_stddev": round(stddev, 4) if stddev is not None else None,
        "confidence_level_pct": 95.0,
        "confidence_interval_low": round(confidence_low, 4) if confidence_low is not None else None,
        "confidence_interval_high": round(confidence_high, 4) if confidence_high is not None else None,
        "improved_pair_count": improved_count,
        "confidence_gate_passed": confidence_gate_passed,
    }
    statistics["confidence_gate_blockers"] = _ai_staff_learning_confidence_blockers(statistics)
    statistics["additional_validated_pair_count_needed"] = max(0, AI_STAFF_LEARNING_MIN_VALIDATED_PAIRS - sample_count)
    statistics["additional_improved_pair_count_needed"] = max(0, AI_STAFF_LEARNING_MIN_IMPROVED_PAIRS - improved_count)
    return statistics


def _ai_staff_counterfactual_triplet_causal_status(
    by_type: dict[str, dict[str, object]],
    *,
    target_start_date: object,
) -> dict[str, object]:
    """Verify that a triplet measures a prior lesson's effect, not a random variant."""
    required = ("prior_official_source", "same_period_baseline", "same_period_adapted")
    blockers: list[str] = []
    transition_hashes: set[str] = set()
    transitions: list[dict[str, object]] = []
    preregistered_flags: list[bool] = []
    preregistration_hashes: set[str] = set()
    preregistration_ids: set[str] = set()
    for run_type in required:
        row = by_type.get(run_type, {})
        if row.get("causal_learning_evidence_eligible") is not True:
            blockers.append(f"{run_type}:causal_learning_evidence_flag_missing")
        if row.get("paper_only") is not True:
            blockers.append(f"{run_type}:paper_only_not_proven")
        if row.get("live_order_allowed") is not False:
            blockers.append(f"{run_type}:live_order_not_blocked")
        if row.get("unverified_result_affects_score") is not False:
            blockers.append(f"{run_type}:unverified_score_effect_not_blocked")
        if row.get("unverified_result_affects_live_candidate") is not False:
            blockers.append(f"{run_type}:unverified_live_effect_not_blocked")
        preregistered = row.get("preregistered_forward_test") is True
        preregistered_flags.append(preregistered)
        if preregistered:
            if row.get("preregistered_forward_evidence_eligible") is not True:
                blockers.append(
                    f"{run_type}:forward_preregistration_execution_not_eligible"
                )
            preregistration_hash = str(
                row.get("learning_preregistration_hash") or ""
            )
            preregistration_id = str(
                row.get("learning_preregistration_id") or ""
            )
            if not preregistration_hash:
                blockers.append(f"{run_type}:forward_preregistration_hash_missing")
            else:
                preregistration_hashes.add(preregistration_hash)
            if not preregistration_id:
                blockers.append(f"{run_type}:forward_preregistration_id_missing")
            else:
                preregistration_ids.add(preregistration_id)

        stored_ledger_hash = str(row.get("ledger_hash") or "")
        ledger_material = dict(row)
        ledger_material.pop("ledger_hash", None)
        calculated_ledger_hash = hashlib.sha256(
            json.dumps(ledger_material, ensure_ascii=True, sort_keys=True).encode("utf-8")
        ).hexdigest()
        if not stored_ledger_hash or stored_ledger_hash != calculated_ledger_hash:
            blockers.append(f"{run_type}:ledger_hash_mismatch")

        transition = row.get("learning_transition") if isinstance(row.get("learning_transition"), dict) else {}
        transition_status = _ai_staff_learning_transition_status(transition)
        if not transition_status.get("valid"):
            blockers.extend(
                f"{run_type}:{blocker}"
                for blocker in transition_status.get("blockers", [])
                if str(blocker)
            )
        transition_hash = str(transition.get("transition_hash") or "")
        if str(row.get("learning_transition_hash") or "") != transition_hash:
            blockers.append(f"{run_type}:ledger_transition_hash_mismatch")
        if transition_hash:
            transition_hashes.add(transition_hash)
        transitions.append(transition)

        expected_strategy = (
            transition.get("adapted_strategy")
            if run_type == "same_period_adapted"
            else transition.get("baseline_strategy")
        )
        expected_parameters = (
            _ai_staff_strategy_parameters(expected_strategy)
            if isinstance(expected_strategy, dict)
            else {}
        )
        executed_strategy = row.get("executed_strategy")
        executed_parameters = (
            _ai_staff_strategy_parameters(executed_strategy)
            if isinstance(executed_strategy, dict)
            else {}
        )
        if not executed_parameters or executed_parameters != expected_parameters:
            blockers.append(f"{run_type}:executed_strategy_transition_mismatch")

    if len(transition_hashes) != 1:
        blockers.append("triplet_learning_transition_hash_not_identical")
    if any(preregistered_flags):
        if not all(preregistered_flags):
            blockers.append("triplet_forward_preregistration_flag_not_identical")
        if len(preregistration_hashes) != 1:
            blockers.append("triplet_forward_preregistration_hash_not_identical")
        if len(preregistration_ids) != 1:
            blockers.append("triplet_forward_preregistration_id_not_identical")
    first_transition = transitions[0] if transitions else {}
    if str(first_transition.get("target_start_date") or "") != str(target_start_date or ""):
        blockers.append("triplet_target_start_date_transition_mismatch")
    contestant_ids = {
        str(row.get("contestant_id") or "")
        for row in by_type.values()
        if isinstance(row, dict)
    }
    if len(contestant_ids) != 1 or str(first_transition.get("source_contestant_id") or "") not in contestant_ids:
        blockers.append("triplet_contestant_transition_mismatch")

    source_row = by_type.get("prior_official_source", {})
    if source_row.get("evidence_role") != "verified_prior_official_source_observation":
        blockers.append("prior_official_source:evidence_role_invalid")
    if str(source_row.get("source_record_id") or "") != str(first_transition.get("source_record_id") or ""):
        blockers.append("prior_official_source:source_record_id_mismatch")
    if str(source_row.get("source_evidence_hash") or "") != str(first_transition.get("source_evidence_hash") or ""):
        blockers.append("prior_official_source:source_evidence_hash_mismatch")

    baseline = by_type.get("same_period_baseline", {})
    adapted = by_type.get("same_period_adapted", {})
    baseline_period = (
        str(baseline.get("actual_start_date") or ""),
        str(baseline.get("actual_end_date") or ""),
    )
    adapted_period = (
        str(adapted.get("actual_start_date") or ""),
        str(adapted.get("actual_end_date") or ""),
    )
    if not all(baseline_period) or baseline_period != adapted_period:
        blockers.append("same_period_baseline_adapted_period_mismatch")

    baseline_cost = baseline.get("cost_model") if isinstance(baseline.get("cost_model"), dict) else {}
    adapted_cost = adapted.get("cost_model") if isinstance(adapted.get("cost_model"), dict) else {}
    if not baseline_cost or baseline_cost != adapted_cost:
        blockers.append("same_period_baseline_adapted_cost_model_mismatch")

    baseline_execution_contract = _ai_staff_counterfactual_execution_contract_status(baseline)
    adapted_execution_contract = _ai_staff_counterfactual_execution_contract_status(adapted)
    blockers.extend(
        f"same_period_baseline:{blocker}"
        for blocker in baseline_execution_contract.get("blockers", [])
        if str(blocker)
    )
    blockers.extend(
        f"same_period_adapted:{blocker}"
        for blocker in adapted_execution_contract.get("blockers", [])
        if str(blocker)
    )
    if (
        not baseline_execution_contract.get("contract_hash")
        or baseline_execution_contract.get("contract_hash")
        != adapted_execution_contract.get("contract_hash")
    ):
        blockers.append("same_period_execution_contract_hash_mismatch")

    baseline_bundle = (
        baseline.get("replay_data_bundle_evidence")
        if isinstance(baseline.get("replay_data_bundle_evidence"), dict)
        else {}
    )
    adapted_bundle = (
        adapted.get("replay_data_bundle_evidence")
        if isinstance(adapted.get("replay_data_bundle_evidence"), dict)
        else {}
    )
    baseline_slice_hash = str(baseline_bundle.get("slice_content_hash") or "")
    adapted_slice_hash = str(adapted_bundle.get("slice_content_hash") or "")
    baseline_bundle_status = _ai_staff_counterfactual_replay_bundle_status(baseline)
    adapted_bundle_status = _ai_staff_counterfactual_replay_bundle_status(adapted)
    blockers.extend(
        f"same_period_baseline:{blocker}"
        for blocker in baseline_bundle_status.get("blockers", [])
        if str(blocker)
    )
    blockers.extend(
        f"same_period_adapted:{blocker}"
        for blocker in adapted_bundle_status.get("blockers", [])
        if str(blocker)
    )
    if not baseline_bundle_status.get("valid") or not adapted_bundle_status.get("valid"):
        blockers.append("same_period_replay_data_bundle_evidence_missing")
    if baseline_slice_hash != adapted_slice_hash:
        blockers.append("same_period_replay_data_bundle_hash_mismatch")
    if (
        str(baseline_bundle.get("bundle_content_hash") or "")
        != str(adapted_bundle.get("bundle_content_hash") or "")
        or str(baseline_bundle.get("slice_manifest_hash") or "")
        != str(adapted_bundle.get("slice_manifest_hash") or "")
    ):
        blockers.append("same_period_replay_data_bundle_manifest_mismatch")

    for run_type, row in (("same_period_baseline", baseline), ("same_period_adapted", adapted)):
        cost_audit = row.get("transaction_cost_audit") if isinstance(row.get("transaction_cost_audit"), dict) else {}
        timing = row.get("execution_timing_model") if isinstance(row.get("execution_timing_model"), dict) else {}
        coverage = row.get("data_coverage") if isinstance(row.get("data_coverage"), dict) else {}
        if cost_audit.get("passed") is not True:
            blockers.append(f"{run_type}:transaction_cost_audit_not_passed")
        if (
            timing.get("lookahead_safe_required") is not True
            or timing.get("same_bar_signal_execution_allowed") is not False
            or int(_number(timing.get("minimum_signal_lag_bars"))) < 1
        ):
            blockers.append(f"{run_type}:lookahead_safe_timing_not_proven")
        if coverage.get("portfolio_boundary_coverage_passed") is not True:
            blockers.append(f"{run_type}:period_boundary_coverage_not_proven")

    unique_blockers = list(dict.fromkeys(blockers))
    return {
        "eligible": not unique_blockers,
        "blockers": unique_blockers,
        "learning_transition_hash": next(iter(transition_hashes)) if len(transition_hashes) == 1 else "",
        "preregistered_forward_test": bool(preregistered_flags and all(preregistered_flags)),
        "preregistered_forward_evidence_eligible": bool(
            not unique_blockers
            and preregistered_flags
            and all(preregistered_flags)
            and len(preregistration_hashes) == 1
            and len(preregistration_ids) == 1
        ),
        "learning_preregistration_hash": (
            next(iter(preregistration_hashes))
            if len(preregistration_hashes) == 1
            else ""
        ),
        "learning_preregistration_id": (
            next(iter(preregistration_ids))
            if len(preregistration_ids) == 1
            else ""
        ),
        "paper_only": True,
        "live_order_allowed": False,
    }


def _ai_staff_counterfactual_ledger_summary(
    limit: int = 5000,
    *,
    include_completed_triplets: bool = False,
) -> dict[str, object]:
    rows = _read_jsonl(AI_STAFF_LEARNING_COUNTERFACTUAL_LEDGER_FILE, limit=limit)
    valid_rows = [
        row for row in rows
        if isinstance(row, dict)
        and row.get("schema") == "codexstock_ai_staff_learning_counterfactual_ledger_v1"
    ]
    grouped: dict[tuple[object, ...], dict[str, dict[str, object]]] = {}
    for row in valid_rows:
        key = (
            row.get("contestant_id"),
            row.get("strategy_generation_id"),
            row.get("start_date"),
            row.get("end_date"),
            tuple(str(symbol) for symbol in row.get("symbols", []) if str(symbol))
            if isinstance(row.get("symbols"), list)
            else (),
        )
        grouped.setdefault(key, {})[str(row.get("run_type") or "")] = row
    required = {"prior_official_source", "same_period_baseline", "same_period_adapted"}
    diagnostic_completed_triplets: list[dict[str, object]] = []
    causal_completed_triplets: list[dict[str, object]] = []
    strategy_verdicts: list[dict[str, object]] = []
    rejected_strategy_records: dict[str, dict[str, object]] = {}
    improved_triplets = 0
    regressed_triplets = 0
    inconclusive_triplets = 0
    directionally_improved_triplets = 0
    directionally_regressed_triplets = 0
    watch_candidate_count = 0
    reject_candidate_count = 0
    diagnostic_directionally_improved_triplets = 0
    diagnostic_directionally_regressed_triplets = 0
    preregistered_forward_triplet_count = 0
    preregistered_forward_improved_triplet_count = 0
    risk_adjusted_improvements: list[float] = []
    for key, by_type in grouped.items():
        if not required.issubset(by_type):
            continue
        if any(by_type[run_type].get("status") != "COMPLETED" for run_type in required):
            continue
        baseline = by_type["same_period_baseline"]
        adapted = by_type["same_period_adapted"]
        baseline_score = _number(baseline.get("total_return_pct")) - 0.5 * abs(_number(baseline.get("max_drawdown_pct")))
        adapted_score = _number(adapted.get("total_return_pct")) - 0.5 * abs(_number(adapted.get("max_drawdown_pct")))
        improvement = round(adapted_score - baseline_score, 4)
        if improvement > 0:
            diagnostic_directionally_improved_triplets += 1
        elif improvement < 0:
            diagnostic_directionally_regressed_triplets += 1
        causal_status = _ai_staff_counterfactual_triplet_causal_status(
            by_type,
            target_start_date=key[2],
        )
        transition = (
            adapted.get("learning_transition")
            if isinstance(adapted.get("learning_transition"), dict)
            else {}
        )
        source_period = transition.get("source_period") if isinstance(transition.get("source_period"), dict) else {}
        replay_bundle = (
            baseline.get("replay_data_bundle_evidence")
            if isinstance(baseline.get("replay_data_bundle_evidence"), dict)
            else {}
        )
        if improvement >= 1.0:
            status = "improved"
        elif improvement <= -1.0:
            status = "regressed"
        else:
            status = "inconclusive"
        triplet_row = {
            "contestant_id": key[0],
            "strategy_generation_id": key[1],
            "start_date": key[2],
            "end_date": key[3],
            "symbols": list(key[4]) if isinstance(key[4], tuple) else [],
            "baseline_risk_adjusted_score": round(baseline_score, 4),
            "adapted_risk_adjusted_score": round(adapted_score, 4),
            "risk_adjusted_improvement": improvement,
            "status": status,
            "causal_learning_evidence_eligible": bool(causal_status.get("eligible")),
            "causal_learning_evidence_blockers": causal_status.get("blockers", []),
            "learning_transition_hash": causal_status.get("learning_transition_hash", ""),
            "preregistered_forward_test": bool(
                causal_status.get("preregistered_forward_test")
            ),
            "preregistered_forward_evidence_eligible": bool(
                causal_status.get("preregistered_forward_evidence_eligible")
            ),
            "learning_preregistration_id": causal_status.get(
                "learning_preregistration_id", ""
            ),
            "learning_preregistration_hash": causal_status.get(
                "learning_preregistration_hash", ""
            ),
            "source_record_id": transition.get("source_record_id"),
            "source_period": {
                "start_date": source_period.get("start_date"),
                "end_date": source_period.get("end_date"),
            },
            "adaptation_changes": transition.get("adaptation_changes", {}),
            "replay_data_slice_hash": replay_bundle.get("slice_content_hash"),
            "paper_only": True,
            "official_learning_evidence": False,
            "live_order_allowed": False,
        }
        diagnostic_completed_triplets.append(triplet_row)
        if causal_status.get("eligible"):
            causal_completed_triplets.append(triplet_row)
            risk_adjusted_improvements.append(improvement)
            if causal_status.get("preregistered_forward_evidence_eligible"):
                preregistered_forward_triplet_count += 1
                if status == "improved":
                    preregistered_forward_improved_triplet_count += 1
            if improvement > 0:
                directionally_improved_triplets += 1
            elif improvement < 0:
                directionally_regressed_triplets += 1
            if status == "improved":
                improved_triplets += 1
            elif status == "regressed":
                regressed_triplets += 1
            else:
                inconclusive_triplets += 1
        if improvement <= -0.1:
            verdict = "reject_from_live_candidate"
            reject_candidate_count += 1
        elif improvement > 0:
            verdict = "watch_more_paper_evidence"
            watch_candidate_count += 1
        else:
            verdict = "needs_more_evidence"
        strategy_verdicts.append(
            {
                "contestant_id": key[0],
                "strategy_generation_id": key[1],
                "risk_adjusted_improvement": improvement,
                "causal_learning_evidence_eligible": bool(causal_status.get("eligible")),
                "causal_learning_evidence_blockers": causal_status.get("blockers", []),
                "official_learning_evidence": False,
                "live_candidate_allowed": False,
                "score_promotion_allowed": False,
                "verdict": verdict,
                "reason": (
                    "directionally_regressed_in_same_period_counterfactual"
                    if verdict == "reject_from_live_candidate"
                    else "directionally_improved_but_below_official_threshold"
                    if verdict == "watch_more_paper_evidence"
                    else "counterfactual_effect_inconclusive"
                ),
            }
        )
        if verdict == "reject_from_live_candidate" and str(key[1] or "").strip():
            rejected_strategy_records[str(key[1])] = {
                "strategy_generation_id": str(key[1]),
                "contestant_id": key[0],
                "reason": "directionally_regressed_in_same_period_counterfactual",
                "risk_adjusted_improvement": improvement,
                "causal_learning_evidence_eligible": bool(causal_status.get("eligible")),
                "live_candidate_allowed": False,
                "score_promotion_allowed": False,
                "official_learning_evidence": False,
            }
    required_improved_triplets = 3
    additional_improved_needed = max(0, required_improved_triplets - improved_triplets)
    confidence_statistics = _ai_staff_learning_effect_statistics(risk_adjusted_improvements)
    confidence_gate_passed = bool(confidence_statistics.get("confidence_gate_passed"))
    confidence_gate_blockers = (
        confidence_statistics.get("confidence_gate_blockers")
        if isinstance(confidence_statistics.get("confidence_gate_blockers"), list)
        else []
    )
    if not causal_completed_triplets:
        next_verification_action = "collect_causal_learning_transition_triplets"
    elif additional_improved_needed:
        next_verification_action = "run_more_paper_counterfactual_triplets"
    elif not confidence_gate_passed:
        next_verification_action = "run_independent_period_confidence_check"
    else:
        next_verification_action = "review_for_manual_learning_evidence_promotion"
    if confidence_gate_passed:
        operator_message = "직원 학습 효과 검증 통과: 수동 승격 검토 가능"
    elif additional_improved_needed:
        operator_message = f"직원 학습 효과 보류: 개선 트리플릿 {additional_improved_needed}개 추가 필요"
    elif "confidence_interval_low_not_positive" in confidence_gate_blockers:
        operator_message = "직원 학습 효과 보류: 평균 개선은 보일 수 있으나 95% 신뢰구간 하단이 아직 0 이하입니다."
    else:
        operator_message = "직원 학습 효과 보류: Paper 반사실험 증거가 아직 공식 승격 기준을 통과하지 못했습니다."
    if not causal_completed_triplets and diagnostic_completed_triplets:
        operator_message = (
            f"직원 학습 효과 보류: 기존 {len(diagnostic_completed_triplets)}개 묶음은 "
            "이전 복기에서 전략이 바뀌었다는 인과 근거가 없어 성장 증거에서 제외했습니다."
        )
    elif not causal_completed_triplets:
        operator_message = "직원 학습 효과 보류: 검증된 이전 복기에서 파생된 다음 전략 비교가 아직 없습니다."
    return {
        "schema": "codexstock_ai_staff_counterfactual_ledger_summary_v2",
        "ledger_path": str(AI_STAFF_LEARNING_COUNTERFACTUAL_LEDGER_FILE),
        "ledger_row_count": len(valid_rows),
        "completed_triplet_count": len(causal_completed_triplets),
        "causal_completed_triplet_count": len(causal_completed_triplets),
        "diagnostic_completed_triplet_count": len(diagnostic_completed_triplets),
        "excluded_noncausal_triplet_count": len(diagnostic_completed_triplets) - len(causal_completed_triplets),
        "required_improved_triplet_count_for_official_evidence": required_improved_triplets,
        "additional_improved_triplet_count_needed": additional_improved_needed,
        "counterfactual_effect_statistics": confidence_statistics,
        "counterfactual_confidence_gate_passed": confidence_gate_passed,
        "counterfactual_confidence_gate_blockers": confidence_gate_blockers,
        "official_counterfactual_promotion_ready": confidence_gate_passed,
        "next_verification_action": next_verification_action,
        "operator_message": operator_message,
        "improved_triplet_count": improved_triplets,
        "regressed_triplet_count": regressed_triplets,
        "inconclusive_triplet_count": inconclusive_triplets,
        "directionally_improved_triplet_count": directionally_improved_triplets,
        "directionally_regressed_triplet_count": directionally_regressed_triplets,
        "diagnostic_directionally_improved_triplet_count": diagnostic_directionally_improved_triplets,
        "diagnostic_directionally_regressed_triplet_count": diagnostic_directionally_regressed_triplets,
        "preregistered_forward_triplet_count": preregistered_forward_triplet_count,
        "preregistered_forward_improved_triplet_count": preregistered_forward_improved_triplet_count,
        "preregistered_forward_partial_evidence_present": bool(
            preregistered_forward_triplet_count > 0
        ),
        "preregistered_forward_growth_evidence_present": bool(
            preregistered_forward_triplet_count > 0
        ),
        "watch_more_paper_evidence_count": watch_candidate_count,
        "reject_from_live_candidate_count": reject_candidate_count,
        "rejected_strategy_ids": sorted(rejected_strategy_records),
        "rejected_strategy_records": [
            rejected_strategy_records[strategy_id]
            for strategy_id in sorted(rejected_strategy_records)
        ],
        "completed_triplet_keys": [
            {
                "contestant_id": row.get("contestant_id"),
                "strategy_generation_id": row.get("strategy_generation_id"),
                "start_date": row.get("start_date"),
                "end_date": row.get("end_date"),
                "symbols": row.get("symbols", []),
            }
            for row in diagnostic_completed_triplets
        ],
        "causal_completed_triplet_keys": [
            {
                "contestant_id": row.get("contestant_id"),
                "strategy_generation_id": row.get("strategy_generation_id"),
                "start_date": row.get("start_date"),
                "end_date": row.get("end_date"),
                "symbols": row.get("symbols", []),
                "preregistered_forward_test": bool(row.get("preregistered_forward_test")),
                "preregistered_forward_evidence_eligible": bool(
                    row.get("preregistered_forward_evidence_eligible")
                ),
                "learning_preregistration_id": row.get("learning_preregistration_id"),
                "learning_preregistration_hash": row.get("learning_preregistration_hash"),
            }
            for row in causal_completed_triplets
        ],
        "strategy_verdicts": strategy_verdicts[-20:],
        "triplet_preview": causal_completed_triplets[-5:],
        "diagnostic_triplet_preview": diagnostic_completed_triplets[-5:],
        "causal_completed_triplets": causal_completed_triplets if include_completed_triplets else [],
        "paper_only": True,
        "official_learning_evidence": False,
        "live_order_allowed": False,
        "unverified_result_affects_score": False,
        "unverified_result_affects_live_candidate": False,
    }


def _merge_ai_staff_counterfactual_learning_pairs(
    staff: dict[str, dict[str, object]],
    triplets: list[dict[str, object]],
) -> dict[str, int]:
    """Merge only independent, causal Paper triplets into per-staff learning evidence."""
    merged_count = 0
    excluded_count = 0
    for raw_triplet in triplets:
        if not isinstance(raw_triplet, dict):
            excluded_count += 1
            continue
        contestant_id = str(raw_triplet.get("contestant_id") or "").strip()
        entry = staff.get(contestant_id)
        if not isinstance(entry, dict):
            excluded_count += 1
            continue

        strategy_generation_id = str(raw_triplet.get("strategy_generation_id") or "").strip()
        start_date = str(raw_triplet.get("start_date") or "").strip()
        end_date = str(raw_triplet.get("end_date") or "").strip()
        symbols = sorted({str(symbol).strip() for symbol in raw_triplet.get("symbols", []) if str(symbol).strip()})
        transition_hash = str(raw_triplet.get("learning_transition_hash") or "").strip().lower()
        source_record_id = str(raw_triplet.get("source_record_id") or "").strip()
        source_period = raw_triplet.get("source_period") if isinstance(raw_triplet.get("source_period"), dict) else {}
        blockers: list[str] = []
        if raw_triplet.get("causal_learning_evidence_eligible") is not True:
            blockers.append("counterfactual_triplet_not_causal")
        if raw_triplet.get("paper_only") is not True:
            blockers.append("counterfactual_triplet_not_paper_only")
        if raw_triplet.get("live_order_allowed") is not False:
            blockers.append("counterfactual_triplet_live_order_not_blocked")
        if not strategy_generation_id or not symbols:
            blockers.append("counterfactual_triplet_identity_incomplete")
        if not re.fullmatch(r"[0-9a-f]{64}", transition_hash):
            blockers.append("counterfactual_transition_hash_invalid")

        pair_key = "|".join(
            [
                "counterfactual",
                contestant_id,
                strategy_generation_id,
                start_date,
                end_date,
                ",".join(symbols),
            ]
        )
        validated_pair_keys = entry.get("_validated_pair_keys")
        if isinstance(validated_pair_keys, set) and pair_key in validated_pair_keys:
            blockers.append("duplicate_learning_pair")

        target_interval: tuple[date, date] | None = None
        try:
            target_interval = (
                datetime.fromisoformat(start_date).date(),
                datetime.fromisoformat(end_date).date(),
            )
            if target_interval[1] < target_interval[0]:
                blockers.append("target_period_reverse")
            validated_periods = entry.get("_validated_target_periods")
            if isinstance(validated_periods, list) and any(
                target_interval[0] <= prior_end and prior_start <= target_interval[1]
                for prior_start, prior_end in validated_periods
            ):
                blockers.append("target_period_overlaps_prior_learning_pair")
        except (TypeError, ValueError):
            blockers.append("target_period_invalid")

        source_start = str(source_period.get("start_date") or "").strip()
        source_end = str(source_period.get("end_date") or "").strip()
        try:
            if datetime.fromisoformat(source_end).date() >= datetime.fromisoformat(start_date).date():
                blockers.append("source_target_periods_overlap_or_reverse")
        except (TypeError, ValueError):
            blockers.append("source_period_invalid")

        improvement = _number(raw_triplet.get("risk_adjusted_improvement"))
        if not math.isfinite(improvement):
            blockers.append("counterfactual_improvement_invalid")
        expected_status = "improved" if improvement >= 1.0 else "regressed" if improvement <= -1.0 else "inconclusive"
        if str(raw_triplet.get("status") or "") != expected_status:
            blockers.append("counterfactual_status_mismatch")

        pair: dict[str, object] = {
            "evidence_source": "causal_counterfactual_ledger",
            "strategy_generation_id": strategy_generation_id or None,
            "source_record_id": source_record_id or None,
            "source_period": {
                "start_date": source_start or None,
                "end_date": source_end or None,
            },
            "target_period": {"start_date": start_date or None, "end_date": end_date or None},
            "symbols": symbols,
            "learning_transition_hash": transition_hash or None,
            "preregistered_forward_test": bool(
                raw_triplet.get("preregistered_forward_test")
            ),
            "preregistered_forward_evidence_eligible": bool(
                raw_triplet.get("preregistered_forward_evidence_eligible")
            ),
            "learning_preregistration_id": raw_triplet.get(
                "learning_preregistration_id"
            ),
            "learning_preregistration_hash": raw_triplet.get(
                "learning_preregistration_hash"
            ),
            "replay_data_slice_hash": raw_triplet.get("replay_data_slice_hash"),
            "adaptation_changes": raw_triplet.get("adaptation_changes", {}),
            "risk_adjusted_improvement": round(improvement, 4),
            "blockers": list(dict.fromkeys(blockers)),
            "paper_only": True,
            "official_learning_evidence": False,
            "score_promotion_allowed": False,
            "live_candidate_allowed": False,
            "live_order_allowed": False,
        }
        pairs = entry.get("learning_pairs")
        if blockers:
            excluded_count += 1
            entry["counterfactual_learning_pair_excluded_count"] = int(
                entry.get("counterfactual_learning_pair_excluded_count") or 0
            ) + 1
            pair["status"] = "excluded_counterfactual"
            if isinstance(pairs, list):
                pairs.append(pair)
            continue

        merged_count += 1
        entry["counterfactual_learning_pair_count"] = int(entry.get("counterfactual_learning_pair_count") or 0) + 1
        entry["causal_learning_link_count"] = int(entry.get("causal_learning_link_count") or 0) + 1
        entry["validated_learning_pair_count"] = int(entry.get("validated_learning_pair_count") or 0) + 1
        if raw_triplet.get("preregistered_forward_evidence_eligible") is True:
            entry["preregistered_forward_learning_pair_count"] = int(
                entry.get("preregistered_forward_learning_pair_count") or 0
            ) + 1
        if isinstance(validated_pair_keys, set):
            validated_pair_keys.add(pair_key)
        validated_periods = entry.get("_validated_target_periods")
        if isinstance(validated_periods, list) and target_interval is not None:
            validated_periods.append(target_interval)
        improvements = entry.get("risk_adjusted_improvements")
        if isinstance(improvements, list):
            improvements.append(improvement)
        transition_hashes = entry.get("_counterfactual_transition_hashes")
        if isinstance(transition_hashes, set):
            transition_hashes.add(transition_hash)
        verified_ids = entry.get("verified_source_record_ids")
        if isinstance(verified_ids, list) and source_record_id and source_record_id not in verified_ids:
            verified_ids.append(source_record_id)
        pair["status"] = expected_status
        if expected_status == "improved":
            entry["improved_learning_pair_count"] = int(entry.get("improved_learning_pair_count") or 0) + 1
        elif expected_status == "regressed":
            entry["regressed_learning_pair_count"] = int(entry.get("regressed_learning_pair_count") or 0) + 1
        else:
            entry["inconclusive_learning_pair_count"] = int(entry.get("inconclusive_learning_pair_count") or 0) + 1
        if isinstance(pairs, list):
            pairs.append(pair)
    return {"merged_count": merged_count, "excluded_count": excluded_count}


def _ai_staff_counterfactual_rejected_strategy_ids(
    contestant_id: str | None = None,
    *,
    summary: dict[str, object] | None = None,
) -> dict[str, dict[str, object]]:
    """Return generated strategies that failed same-period Paper counterfactuals."""
    source = summary if isinstance(summary, dict) else _ai_staff_counterfactual_ledger_summary()
    rejected: dict[str, dict[str, object]] = {}
    record_rows = source.get("rejected_strategy_records")
    if isinstance(record_rows, list):
        for row in record_rows:
            if not isinstance(row, dict):
                continue
            if contestant_id and str(row.get("contestant_id") or "") != str(contestant_id):
                continue
            strategy_id = str(row.get("strategy_generation_id") or "").strip()
            if not strategy_id:
                continue
            rejected[strategy_id] = {
                "strategy_generation_id": strategy_id,
                "contestant_id": row.get("contestant_id"),
                "reason": row.get("reason") or "counterfactual_rejected",
                "risk_adjusted_improvement": row.get("risk_adjusted_improvement"),
                "live_candidate_allowed": False,
                "score_promotion_allowed": False,
                "official_learning_evidence": False,
            }
        if rejected:
            return rejected
    for row in source.get("strategy_verdicts", []) if isinstance(source.get("strategy_verdicts"), list) else []:
        if not isinstance(row, dict):
            continue
        if row.get("verdict") != "reject_from_live_candidate":
            continue
        if contestant_id and str(row.get("contestant_id") or "") != str(contestant_id):
            continue
        strategy_id = str(row.get("strategy_generation_id") or "").strip()
        if not strategy_id:
            continue
        rejected[strategy_id] = {
            "strategy_generation_id": strategy_id,
            "contestant_id": row.get("contestant_id"),
            "reason": row.get("reason") or "counterfactual_rejected",
            "risk_adjusted_improvement": row.get("risk_adjusted_improvement"),
            "live_candidate_allowed": False,
            "score_promotion_allowed": False,
            "official_learning_evidence": False,
        }
    return rejected


def _ai_staff_adaptation_changes_signature(changes: dict[str, object]) -> str:
    """Identify the parameter change itself so a new strategy id cannot hide a repeated failure."""
    normalized: dict[str, dict[str, object]] = {}
    for key in sorted(str(item) for item in changes):
        value = changes.get(key)
        if not isinstance(value, dict) or "before" not in value or "after" not in value:
            continue
        normalized[key] = {
            "before": value.get("before"),
            "after": value.get("after"),
        }
    if not normalized:
        return ""
    canonical = json.dumps(
        normalized,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    )
    return "sha256:" + hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _ai_staff_counterfactual_adaptation_history(
    contestant_id: str,
    *,
    before_date: str,
    summary: dict[str, object] | None = None,
) -> dict[str, object]:
    """Aggregate only prior causal Paper outcomes for exact parameter-change signatures."""
    try:
        current_start = datetime.fromisoformat(str(before_date)).date()
    except (TypeError, ValueError):
        return {
            "ok": False,
            "schema": "codexstock_ai_staff_counterfactual_adaptation_history_v1",
            "contestant_id": contestant_id,
            "before_date": str(before_date or ""),
            "history_count": 0,
            "items": [],
            "blockers": ["counterfactual_feedback_before_date_invalid"],
            "paper_only": True,
            "live_order_allowed": False,
        }
    source = (
        summary
        if isinstance(summary, dict)
        else _ai_staff_counterfactual_ledger_summary(include_completed_triplets=True)
    )
    completed = source.get("causal_completed_triplets")
    grouped: dict[str, dict[str, object]] = {}
    excluded_future_or_same_period = 0
    for row in completed if isinstance(completed, list) else []:
        if not isinstance(row, dict) or str(row.get("contestant_id") or "") != str(contestant_id):
            continue
        try:
            period_end = datetime.fromisoformat(str(row.get("end_date") or "")).date()
        except (TypeError, ValueError):
            continue
        if period_end >= current_start:
            excluded_future_or_same_period += 1
            continue
        changes = row.get("adaptation_changes") if isinstance(row.get("adaptation_changes"), dict) else {}
        signature = _ai_staff_adaptation_changes_signature(changes)
        if not signature:
            continue
        bucket = grouped.setdefault(
            signature,
            {
                "change_signature": signature,
                "adaptation_changes": changes,
                "effects": [],
                "periods": [],
                "strategy_generation_ids": [],
            },
        )
        effects = bucket.get("effects")
        if isinstance(effects, list):
            effects.append(float(_number(row.get("risk_adjusted_improvement"))))
        periods = bucket.get("periods")
        if isinstance(periods, list):
            periods.append(
                {
                    "start_date": row.get("start_date"),
                    "end_date": row.get("end_date"),
                    "risk_adjusted_improvement": row.get("risk_adjusted_improvement"),
                    "status": row.get("status"),
                }
            )
        generation_ids = bucket.get("strategy_generation_ids")
        strategy_id = str(row.get("strategy_generation_id") or "").strip()
        if isinstance(generation_ids, list) and strategy_id and strategy_id not in generation_ids:
            generation_ids.append(strategy_id)

    items: list[dict[str, object]] = []
    for bucket in grouped.values():
        effects = [float(value) for value in bucket.pop("effects", [])]
        statistics = _ai_staff_learning_effect_statistics(effects)
        mean_effect = _number(statistics.get("mean_risk_adjusted_improvement"))
        improved_count = sum(1 for value in effects if value >= 1.0)
        regressed_count = sum(1 for value in effects if value <= -1.0)
        if statistics.get("confidence_gate_passed") is True:
            decision = "repeat_supported_in_paper"
        elif mean_effect <= -0.1:
            decision = "reject_repeat_and_pivot"
        else:
            decision = "watch_more_paper_evidence"
        items.append(
            {
                **bucket,
                "sample_count": len(effects),
                "improved_count": improved_count,
                "regressed_count": regressed_count,
                "mean_risk_adjusted_improvement": round(mean_effect, 4),
                "effect_statistics": statistics,
                "decision": decision,
                "paper_only": True,
                "live_order_allowed": False,
                "automatic_promotion": False,
            }
        )
    items.sort(
        key=lambda row: (
            str(row.get("decision") or "") == "repeat_supported_in_paper",
            _number(row.get("mean_risk_adjusted_improvement")),
            int(_number(row.get("sample_count"))),
        ),
        reverse=True,
    )
    return {
        "ok": True,
        "schema": "codexstock_ai_staff_counterfactual_adaptation_history_v1",
        "contestant_id": contestant_id,
        "before_date": current_start.isoformat(),
        "history_count": len(items),
        "prior_triplet_count": sum(int(_number(item.get("sample_count"))) for item in items),
        "rejected_signature_count": sum(
            1 for item in items if item.get("decision") == "reject_repeat_and_pivot"
        ),
        "supported_signature_count": sum(
            1 for item in items if item.get("decision") == "repeat_supported_in_paper"
        ),
        "excluded_future_or_same_period_count": excluded_future_or_same_period,
        "items": items,
        "blockers": [],
        "point_in_time_cutoff_enforced": True,
        "paper_only": True,
        "live_order_allowed": False,
        "automatic_promotion": False,
    }


def _build_ai_staff_learning_counterfactual_control(
    *,
    source_record_id: str,
    baseline_row: dict[str, object],
    target_row: dict[str, object],
) -> dict[str, object]:
    baseline_symbols = sorted(str(item) for item in baseline_row.get("selected_symbols", []) if str(item))
    target_symbols = sorted(str(item) for item in target_row.get("selected_symbols", []) if str(item))
    baseline_period = {
        "start_date": baseline_row.get("actual_start_date"),
        "end_date": baseline_row.get("actual_end_date"),
    }
    target_period = {
        "start_date": target_row.get("actual_start_date"),
        "end_date": target_row.get("actual_end_date"),
    }
    control: dict[str, object] = {
        "schema": "codexstock_ai_staff_learning_counterfactual_v1",
        "source_record_id": source_record_id,
        "contestant_id": target_row.get("contestant_id"),
        "target_period": target_period,
        "symbols": target_symbols,
        "baseline_strategy": _ai_staff_strategy_parameters(baseline_row),
        "adapted_strategy": _ai_staff_strategy_parameters(target_row),
        "baseline_result": baseline_row,
        "same_target_period": baseline_period == target_period,
        "same_symbols": bool(target_symbols) and baseline_symbols == target_symbols,
        "same_cost_model": baseline_row.get("cost_model") == target_row.get("cost_model"),
        "live_order_allowed": False,
        "policy": (
            "The prior strategy and adapted strategy must be replayed on the same target period, symbols, "
            "cost policy, lookahead-safe timing, and official evidence boundary."
        ),
    }
    control["evidence_hash"] = _ai_staff_learning_counterfactual_hash(control, target_row)
    return control


def _ai_staff_certified_learning_observation(
    record: dict[str, object],
    row: dict[str, object],
    *,
    certified_index: dict[str, object] | None = None,
    bias_cache: dict[tuple[str, str, tuple[str, ...]], dict[str, object]] | None = None,
    universe_store: UniverseStore | None = None,
) -> dict[str, object]:
    """Project a certified replacement as a new Paper learning observation.

    The projection never rewrites the legacy result or claims source equivalence.
    It only reuses the preserved staff identity while all performance and audit
    fields come from the separately certified replacement replay.
    """
    source_row = dict(row)
    score_gate = _historical_replay_score_gate(
        source_row,
        certified_index=certified_index,
    )
    replay = (
        score_gate.get("_claim_replay")
        if isinstance(score_gate.get("_claim_replay"), dict)
        else {}
    )
    source_replay_id = str(score_gate.get("source_replay_id") or "").strip().upper()
    certified_replay_id = str(score_gate.get("certified_replay_id") or "").strip().upper()
    index = certified_index if isinstance(certified_index, dict) else _historical_replay_certified_score_index()
    replacements = index.get("replacements") if isinstance(index.get("replacements"), dict) else {}
    replacement = replacements.get(source_replay_id) if source_replay_id else None
    ledger = replacement.get("ledger") if isinstance(replacement, dict) and isinstance(replacement.get("ledger"), dict) else {}
    comparison = ledger.get("source_comparison") if isinstance(ledger.get("source_comparison"), dict) else {}
    blockers: list[str] = []
    if score_gate.get("score_allowed") is not True or not replay:
        if isinstance(score_gate.get("blockers"), list):
            blockers.extend(
                str(value)
                for value in score_gate.get("blockers", [])
                if str(value).strip()
            )
        else:
            blockers.append("certified_replacement_score_gate_not_passed")
    if not isinstance(replacement, dict) or not ledger:
        blockers.append("certified_replacement_ledger_missing")
    if ledger:
        if ledger.get("paper_only") is not True:
            blockers.append("certified_replacement_not_paper_only")
        if ledger.get("live_order_allowed") is not False:
            blockers.append("certified_replacement_live_order_not_blocked")
        if ledger.get("automatic_promotion") is not False:
            blockers.append("certified_replacement_automatic_promotion_not_blocked")
        if ledger.get("official_return_claim_allowed") is not True:
            blockers.append("certified_replacement_official_return_not_allowed")
    if replay:
        if str(replay.get("id") or "").strip().upper() != certified_replay_id:
            blockers.append("certified_replacement_identity_mismatch")
        if str(replay.get("source") or "") != f"tournament-regeneration:{source_replay_id}":
            blockers.append("certified_replacement_source_lineage_mismatch")
    if comparison:
        if comparison.get("schema") != "codexstock_replay_source_comparison_v1":
            blockers.append("certified_replacement_source_comparison_schema_invalid")
        if comparison.get("new_result_return_claim_is_separate") is not True:
            blockers.append("certified_replacement_separate_result_boundary_missing")
    else:
        blockers.append("certified_replacement_source_comparison_missing")

    source_mode = str(
        source_row.get("strategy_mode")
        or source_row.get("strategy")
        or (
            source_row.get("selected_challenge_config", {}).get("strategy_mode")
            if isinstance(source_row.get("selected_challenge_config"), dict)
            else ""
        )
        or ""
    ).strip()
    replay_mode = str(replay.get("strategy_mode") or "").strip()
    strategy_config = replay.get("strategy_config") if isinstance(replay.get("strategy_config"), dict) else {}
    if not source_mode or not replay_mode or source_mode != replay_mode:
        blockers.append("certified_replacement_strategy_mode_mismatch")
    if not strategy_config:
        blockers.append("certified_replacement_strategy_contract_missing")

    replay_symbols = _normalize_tournament_symbols(
        replay.get("symbols") if isinstance(replay.get("symbols"), list) else []
    )
    record_symbols = _normalize_tournament_symbols(
        record.get("symbols") if isinstance(record.get("symbols"), list) else []
    )
    row_symbols = _normalize_tournament_symbols(
        source_row.get("selected_symbols")
        if isinstance(source_row.get("selected_symbols"), list)
        else []
    )
    if not replay_symbols:
        blockers.append("certified_replacement_symbol_contract_missing")
    if record_symbols and replay_symbols != record_symbols:
        blockers.append("certified_replacement_record_universe_mismatch")
    if row_symbols and replay_symbols != row_symbols:
        blockers.append("certified_replacement_staff_universe_mismatch")

    start_date = str(replay.get("start_date") or record.get("start_date") or "")
    end_date = str(replay.get("end_date") or record.get("end_date") or "")
    bias_audit: dict[str, object] = {}
    if replay_symbols and start_date and end_date and not blockers:
        cache_key = (start_date, end_date, tuple(replay_symbols))
        if isinstance(bias_cache, dict) and cache_key in bias_cache:
            bias_audit = bias_cache[cache_key]
        else:
            bias_audit = _ai_tournament_bias_audit(
                symbols=replay_symbols,
                start_date=start_date,
                end_date=end_date,
                symbol_selection_mode="common",
                universe_dataset_id=None,
                store=universe_store,
            )
            if isinstance(bias_cache, dict):
                bias_cache[cache_key] = bias_audit
        if bias_audit.get("passed") is not True:
            blockers.append("certified_replacement_point_in_time_universe_not_validated")

    unique_blockers = list(dict.fromkeys(blockers))
    if unique_blockers:
        return {
            "eligible": False,
            "status": "verification_pending",
            "row": source_row,
            "source_replay_id": source_replay_id or None,
            "certified_replay_id": certified_replay_id or None,
            "blockers": unique_blockers,
            "paper_only": True,
            "promotion_allowed": False,
            "live_order_allowed": False,
        }

    projected = dict(source_row)
    projected.update(
        {
            "replay_id": source_replay_id,
            "certified_replay_id": certified_replay_id,
            "strategy_mode": replay_mode,
            "fast_window": strategy_config.get("fast", replay.get("fast")),
            "slow_window": strategy_config.get("slow", replay.get("slow")),
            "selected_challenge_config": {
                "strategy_mode": replay_mode,
                "allocation_pct": strategy_config.get("allocation_pct"),
                "max_positions": strategy_config.get("max_positions"),
                "stop_loss_pct": strategy_config.get("stop_loss_pct"),
                "take_profit_pct": strategy_config.get("take_profit_pct"),
                "holding_limit_days": strategy_config.get("holding_limit_days"),
                "cycles_per_day": strategy_config.get("cycles_per_day"),
            },
            "selected_symbols": replay_symbols,
            "actual_start_date": replay.get("actual_start_date"),
            "actual_end_date": replay.get("actual_end_date"),
            "total_return_pct": replay.get("total_return_pct"),
            "max_drawdown_pct": replay.get("max_drawdown_pct"),
            "win_rate_pct": replay.get("win_rate_pct"),
            "trade_count": replay.get("trade_count"),
            "closed_trade_count": replay.get("closed_trade_count"),
            "average_win_pct": replay.get("average_win_pct"),
            "average_loss_pct": replay.get("average_loss_pct"),
            "transaction_cost_pct_of_initial_cash": replay.get("transaction_cost_pct_of_initial_cash"),
            "top_trades": replay.get("top_trades", []),
            "bottom_trades": replay.get("bottom_trades", []),
            "trade_journal_top10": replay.get("trade_journal_top10", []),
            "trade_journal_bottom10": replay.get("trade_journal_bottom10", []),
            "cost_model": replay.get("cost_model", {}),
            "transaction_cost_audit": replay.get("transaction_cost_audit", {}),
            "execution_timing_model": replay.get("execution_timing_model", {}),
            "data_coverage": replay.get("data_coverage", {}),
            "price_currency_unit_audit": replay.get("price_currency_unit_audit", {}),
            "return_reconciliation_summary": replacement.get("reconciliation", {}),
            "bias_audit": bias_audit,
            "monte_carlo_stress": _ai_tournament_monte_carlo_stress(
                replay,
                iterations=300,
                seed=f"certified-learning-{certified_replay_id}",
            ),
            "data_mode": replay.get("data_mode"),
            "paper_only": True,
            "promotion_allowed": False,
            "live_order_allowed": False,
        }
    )
    projected["learning_observation_provenance"] = {
        "schema": "codexstock_ai_staff_certified_learning_observation_v1",
        "source_record_id": record.get("id"),
        "contestant_id": source_row.get("contestant_id"),
        "source_replay_id": source_replay_id,
        "certified_replay_id": certified_replay_id,
        "certified_milestone": score_gate.get("certified_milestone"),
        "evidence_bundle_hash": score_gate.get("evidence_bundle_hash"),
        "contract_hash": ledger.get("contract_hash"),
        "source_comparison_status": comparison.get("status"),
        "legacy_result_equivalence_claim_allowed": False,
        "new_result_return_claim_is_separate": True,
        "performance_source": "certified_replacement_only",
        "paper_only": True,
        "promotion_allowed": False,
        "live_order_allowed": False,
    }
    return {
        "eligible": True,
        "status": "certified_replacement_observation",
        "row": projected,
        "source_replay_id": source_replay_id,
        "certified_replay_id": certified_replay_id,
        "blockers": [],
        "paper_only": True,
        "promotion_allowed": False,
        "live_order_allowed": False,
    }


def _ai_staff_learning_claim_state(
    row: dict[str, object],
    *,
    certified_index: dict[str, object] | None = None,
) -> dict[str, object]:
    """Apply a stricter evidence gate than the public tournament claim."""
    official = _ai_tournament_official_claim_state(
        row,
        certified_index=certified_index,
    )
    reasons = [str(item) for item in official.get("reasons", []) if str(item)]
    cost_audit = row.get("transaction_cost_audit") if isinstance(row.get("transaction_cost_audit"), dict) else {}
    applied_action_count = int(_number(cost_audit.get("applied_action_count")))
    recorded_trade_count = int(_number(row.get("trade_count")))
    cost_ledger_valid = bool(
        cost_audit.get("schema") == "codexstock_replay_transaction_cost_audit_v1"
        and cost_audit.get("passed") is True
        and applied_action_count > 0
        and (recorded_trade_count <= 0 or applied_action_count == recorded_trade_count)
    )
    if not cost_ledger_valid:
        reasons.append("transaction_cost_ledger_not_validated")

    timing = row.get("execution_timing_model") if isinstance(row.get("execution_timing_model"), dict) else {}
    lookahead_safe = bool(
        timing.get("lookahead_safe_required") is True
        and timing.get("same_bar_signal_execution_allowed") is False
        and int(_number(timing.get("minimum_signal_lag_bars"))) >= 1
    )
    if not lookahead_safe:
        reasons.append("lookahead_safe_timing_not_validated")

    coverage = row.get("data_coverage") if isinstance(row.get("data_coverage"), dict) else {}
    period_coverage_valid = bool(
        row.get("actual_start_date")
        and row.get("actual_end_date")
        and coverage.get("portfolio_boundary_coverage_passed") is True
    )
    if not period_coverage_valid:
        reasons.append("actual_period_coverage_not_validated")

    unique_reasons = list(dict.fromkeys(reasons))
    return {
        "eligible": not unique_reasons,
        "status": "official_learning_evidence" if not unique_reasons else "reference_only",
        "reasons": unique_reasons,
        "tournament_claim": official,
        "transaction_cost_ledger_validated": cost_ledger_valid,
        "lookahead_safe_timing_validated": lookahead_safe,
        "actual_period_coverage_validated": period_coverage_valid,
        "policy": (
            "Learning evidence requires an official tournament claim, a reconciled action-level cost ledger, "
            "prior-bar/next-bar timing, and actual period boundary coverage."
        ),
    }


def _ai_staff_verified_learning_contexts(
    current_start_date: str,
    *,
    records: list[dict[str, object]] | None = None,
    counterfactual_summary: dict[str, object] | None = None,
) -> dict[str, dict[str, object]]:
    """Return the latest prior official weakness that can be adapted causally."""
    try:
        current_start = datetime.fromisoformat(current_start_date).date()
    except (TypeError, ValueError):
        return {}
    source_records = records if records is not None else _read_jsonl(AI_TOURNAMENT_FILE, limit=300)
    certified_index = _historical_replay_certified_score_index()
    bias_cache: dict[tuple[str, str, tuple[str, ...]], dict[str, object]] = {}
    universe_store = UniverseStore(POINT_IN_TIME_UNIVERSE_ROOT)
    contexts: dict[str, dict[str, object]] = {}
    for record in source_records:
        if not isinstance(record, dict):
            continue
        try:
            source_end = datetime.fromisoformat(str(record.get("end_date") or "")).date()
        except (TypeError, ValueError):
            continue
        if source_end >= current_start:
            continue
        for raw_row in record.get("rankings", []) if isinstance(record.get("rankings"), list) else []:
            if not isinstance(raw_row, dict):
                continue
            projection = _ai_staff_certified_learning_observation(
                record,
                raw_row,
                certified_index=certified_index,
                bias_cache=bias_cache,
                universe_store=universe_store,
            )
            row = (
                projection.get("row")
                if projection.get("eligible") is True and isinstance(projection.get("row"), dict)
                else raw_row
            )
            contestant_id = str(row.get("contestant_id") or "").strip()
            if not contestant_id or not _ai_staff_learning_claim_state(
                row,
                certified_index=certified_index,
            ).get("eligible"):
                continue
            performance = _ai_staff_period_performance(record, row)
            if not performance.get("valid"):
                continue
            risk_limit = _number(row.get("risk_limit_pct")) or 15.0
            reason_codes: list[str] = []
            if _number(row.get("total_return_pct")) <= 0:
                reason_codes.append("non_positive_net_return")
            if abs(_number(row.get("max_drawdown_pct"))) > risk_limit:
                reason_codes.append("drawdown_above_role_limit")
            if int(_number(row.get("trade_count"))) >= 10 and _number(row.get("win_rate_pct")) < 35.0:
                reason_codes.append("low_win_rate")
            journal_diagnosis = _ai_staff_replay_journal_diagnosis(record, row)
            reason_codes.extend(
                str(item)
                for item in journal_diagnosis.get("reason_codes", [])
                if str(item)
            )
            stress = row.get("monte_carlo_stress") if isinstance(row.get("monte_carlo_stress"), dict) else {}
            stress_reason_codes = _ai_tournament_monte_carlo_failure_reasons(stress)
            reason_codes.extend(
                code
                for code in stress_reason_codes
                if code not in {
                    "monte_carlo_evidence_missing",
                    "monte_carlo_actual_sample_insufficient",
                    "monte_carlo_reconciliation_not_validated",
                }
            )
            mdd_abs = abs(_number(row.get("max_drawdown_pct")))
            risk_budget_utilization_pct = (
                mdd_abs / risk_limit * 100.0
                if risk_limit > 0
                else 0.0
            )
            if (
                not reason_codes
                and _number(row.get("total_return_pct")) > 0
                and int(_number(row.get("trade_count"))) >= 3
                and mdd_abs > 0
                and risk_budget_utilization_pct <= 40.0
            ):
                reason_codes.append("risk_budget_underutilized")
            reason_codes = list(dict.fromkeys(reason_codes))
            if not reason_codes:
                continue
            context = {
                "source_record_id": record.get("id"),
                "source_start_date": row.get("actual_start_date") or record.get("start_date"),
                "source_end_date": row.get("actual_end_date") or record.get("end_date"),
                "source_contestant_id": contestant_id,
                "source_strategy": _ai_staff_strategy_parameters(row),
                "source_metrics": performance,
                "source_raw_metrics": {
                    "total_return_pct": row.get("total_return_pct"),
                    "max_drawdown_pct": row.get("max_drawdown_pct"),
                    "win_rate_pct": row.get("win_rate_pct"),
                    "trade_count": row.get("trade_count"),
                    "risk_limit_pct": risk_limit,
                    "risk_budget_utilization_pct": round(risk_budget_utilization_pct, 4),
                    "monte_carlo_stress": stress,
                },
                "reason_codes": reason_codes,
                "monte_carlo_stress": stress,
                "monte_carlo_reason_codes": stress_reason_codes,
                "stress_retraining_plan": _ai_tournament_stress_retraining_plan(
                    _ai_staff_strategy_parameters(row),
                    stress,
                ),
                "risk_budget_scale_up_gate": {},
                "journal_diagnosis": journal_diagnosis,
                "journal_lessons": journal_diagnosis.get("lessons", []),
                "source_evidence_hash": _ai_staff_learning_source_hash(record, row),
            }
            prior = contexts.get(contestant_id)
            if not prior or str(context.get("source_end_date") or "") > str(prior.get("source_end_date") or ""):
                contexts[contestant_id] = context
    counterfactual_summary = (
        counterfactual_summary
        if isinstance(counterfactual_summary, dict)
        else _ai_staff_counterfactual_ledger_summary(include_completed_triplets=True)
        if contexts
        else {}
    )
    for contestant_id, context in contexts.items():
        context["counterfactual_adaptation_history"] = (
            _ai_staff_counterfactual_adaptation_history(
                contestant_id,
                before_date=current_start_date,
                summary=counterfactual_summary,
            )
        )
        if "risk_budget_underutilized" not in context.get("reason_codes", []):
            continue
        context["risk_budget_scale_up_gate"] = _ai_staff_risk_budget_scale_up_gate(
            contestant_id,
            current_start_date=current_start_date,
            monte_carlo_stress=(
                context.get("monte_carlo_stress")
                if isinstance(context.get("monte_carlo_stress"), dict)
                else {}
            ),
            counterfactual_summary=counterfactual_summary,
        )
    return contexts


def _ai_staff_risk_budget_scale_up_gate(
    contestant_id: str,
    *,
    current_start_date: str,
    monte_carlo_stress: dict[str, object] | None = None,
    counterfactual_summary: dict[str, object] | None = None,
) -> dict[str, object]:
    """Allow a Paper risk increase only after independent causal proof and real stress evidence."""
    try:
        current_start = datetime.fromisoformat(current_start_date).date()
    except (TypeError, ValueError):
        current_start = date.max
    summary = (
        counterfactual_summary
        if isinstance(counterfactual_summary, dict)
        else _ai_staff_counterfactual_ledger_summary(include_completed_triplets=True)
    )
    completed = summary.get("causal_completed_triplets")
    grouped_periods: dict[tuple[date, date], list[float]] = {}
    for row in completed if isinstance(completed, list) else []:
        if not isinstance(row, dict) or str(row.get("contestant_id") or "") != contestant_id:
            continue
        try:
            start = datetime.fromisoformat(str(row.get("start_date") or "")).date()
            end = datetime.fromisoformat(str(row.get("end_date") or "")).date()
        except ValueError:
            continue
        if end >= current_start or end < start:
            continue
        grouped_periods.setdefault((start, end), []).append(
            float(_number(row.get("risk_adjusted_improvement")))
        )
    period_effects = sorted(
        (
            start,
            end,
            sum(values) / len(values),
        )
        for (start, end), values in grouped_periods.items()
        if values
    )
    independent_effects: list[float] = []
    independent_periods: list[dict[str, object]] = []
    last_end: date | None = None
    for start, end, effect in period_effects:
        if last_end is not None and start <= last_end:
            continue
        independent_effects.append(effect)
        independent_periods.append(
            {
                "start_date": start.isoformat(),
                "end_date": end.isoformat(),
                "risk_adjusted_improvement": round(effect, 4),
            }
        )
        last_end = end
    statistics = _ai_staff_learning_effect_statistics(independent_effects)
    stress = monte_carlo_stress if isinstance(monte_carlo_stress, dict) else {}
    stress_passed = bool(
        stress.get("passed") is True
        and stress.get("official_evidence") is True
        and stress.get("actual_sample_sufficient") is True
        and stress.get("reconciliation_validated") is True
    )
    blockers: list[str] = []
    if len(independent_effects) < AI_STAFF_LEARNING_MIN_VALIDATED_PAIRS:
        blockers.append("risk_scale_independent_period_count_below_minimum")
    blockers.extend(
        f"risk_scale_{item}"
        for item in statistics.get("confidence_gate_blockers", [])
        if str(item)
    )
    if not stress_passed:
        blockers.append("risk_scale_official_monte_carlo_not_passed")
    return {
        "schema": "codexstock_ai_staff_risk_budget_scale_up_gate_v1",
        "passed": not blockers,
        "contestant_id": contestant_id,
        "current_start_date": current_start_date,
        "independent_period_count": len(independent_effects),
        "independent_periods": independent_periods,
        "effect_statistics": statistics,
        "official_monte_carlo_passed": stress_passed,
        "blockers": list(dict.fromkeys(blockers)),
        "paper_only": True,
        "live_order_allowed": False,
    }


def _apply_ai_staff_verified_learning(
    config: dict[str, object],
    context: dict[str, object] | None,
    *,
    current_start_date: str,
) -> dict[str, object]:
    result = dict(config)
    monte_carlo_retraining_contract = (
        result.pop("_monte_carlo_retraining_contract")
        if isinstance(result.get("_monte_carlo_retraining_contract"), dict)
        else {}
    )
    retraining_source_config = (
        monte_carlo_retraining_contract.get("source_config")
        if isinstance(monte_carlo_retraining_contract.get("source_config"), dict)
        else {}
    )
    preconfigured_monte_carlo_candidate = bool(
        monte_carlo_retraining_contract.get("paper_only") is True
        and monte_carlo_retraining_contract.get("live_order_allowed") is False
        and monte_carlo_retraining_contract.get("automatic_promotion") is False
        and retraining_source_config
        and monte_carlo_retraining_contract.get("candidate_config_hash")
    )
    if not context:
        result["_learning_provenance"] = {
            "schema": "codexstock_ai_staff_learning_provenance_v1",
            "adaptive": False,
            "verified_source_record_ids": [],
            "reason": "no_prior_official_weakness_before_current_period",
            "applied_before_replay": False,
            "live_order_allowed": False,
        }
        return result

    before = _ai_staff_strategy_parameters(
        retraining_source_config if preconfigured_monte_carlo_candidate else result
    )
    reasons = [str(item) for item in context.get("reason_codes", []) if str(item)]
    evidence_expansion_reasons = {
        "no_closed_trades",
        "too_few_closed_trades",
    }
    actionable_reasons = [item for item in reasons if item not in evidence_expansion_reasons]
    monte_carlo_retraining_consumed_reason_codes: list[str] = []
    if preconfigured_monte_carlo_candidate:
        # The generated candidate itself is the hypothesis. Do not mutate it again
        # before its same-period Paper comparison.
        monte_carlo_retraining_consumed_reason_codes = list(actionable_reasons)
        actionable_reasons = []
    adaptation_blockers: list[str] = []
    if evidence_expansion_reasons.intersection(reasons):
        adaptation_blockers.append("sparse_trade_evidence_requires_universe_or_period_expansion")
    risk_scale_gate = (
        context.get("risk_budget_scale_up_gate")
        if isinstance(context.get("risk_budget_scale_up_gate"), dict)
        else {}
    )
    if "risk_budget_underutilized" in actionable_reasons and risk_scale_gate.get("passed") is not True:
        actionable_reasons = [item for item in actionable_reasons if item != "risk_budget_underutilized"]
        adaptation_blockers.extend(
            str(item)
            for item in risk_scale_gate.get(
                "blockers",
                ["risk_scale_confidence_and_stress_gate_not_passed"],
            )
            if str(item)
        )
    if "drawdown_above_role_limit" in actionable_reasons:
        result["allocation"] = round(max(10.0, _number(result.get("allocation")) * 0.8), 2)
        result["max_positions"] = max(1, int(_number(result.get("max_positions"))) - 1)
        result["stop"] = round(max(1.0, min(_number(result.get("stop")) or 8.0, 4.0)), 2)
    stress_tail_reasons = {
        "monte_carlo_low_positive_path_rate",
        "monte_carlo_negative_tail_return",
        "monte_carlo_ruin_risk",
        "monte_carlo_tail_drawdown",
    }
    if stress_tail_reasons.intersection(actionable_reasons):
        reduction = 0.65 if "monte_carlo_ruin_risk" in actionable_reasons else 0.78
        result["allocation"] = round(
            max(5.0, (_number(result.get("allocation")) or 25.0) * reduction),
            2,
        )
        result["max_positions"] = max(1, int(_number(result.get("max_positions")) or 1) - 1)
        current_stop = _number(result.get("stop")) or 8.0
        result["stop"] = round(max(0.8, min(current_stop * 0.8, 4.0)), 2)
        result["slow"] = max(
            int(_number(result.get("fast")) or 2) + 3,
            int(_number(result.get("slow")) or 5) + 2,
        )
    if "non_positive_net_return" in actionable_reasons:
        current_mode = str(result.get("strategy") or "")
        arena = result.get("training_arena") if isinstance(result.get("training_arena"), dict) else {}
        allowed_horizons = set(
            str(item)
            for item in arena.get("allowed_horizons", ["daytrade", "swing", "mid_term", "long_term"])
        )
        eligible_modes = [
            mode
            for mode in AI_STAFF_OPEN_STRATEGY_MODES
            if _replay_strategy_horizon(mode) in allowed_horizons
            and (not arena.get("master_only") or _replay_strategy_profile(mode).get("master_proxy") is True)
        ]
        if not eligible_modes:
            eligible_modes = list(AI_STAFF_OPEN_STRATEGY_MODES)
        seed_text = "|".join(
            [
                str(context.get("source_record_id") or ""),
                str(context.get("source_contestant_id") or ""),
                current_mode,
                ",".join(sorted(reasons)),
                str(arena.get("id") or "free_play"),
            ]
        )
        offset = int(hashlib.sha256(seed_text.encode("utf-8")).hexdigest()[:12], 16)
        if current_mode in eligible_modes and len(eligible_modes) > 1:
            step = 1 + offset % (len(eligible_modes) - 1)
            result["strategy"] = eligible_modes[(eligible_modes.index(current_mode) + step) % len(eligible_modes)]
        else:
            result["strategy"] = eligible_modes[offset % len(eligible_modes)]
        result["fast"] = max(2, int(_number(result.get("fast"))) - 1)
        result["slow"] = max(int(_number(result.get("fast"))) + 3, int(_number(result.get("slow"))) + 2)
    if "low_win_rate" in actionable_reasons:
        take = _number(result.get("take"))
        if take > 0:
            result["take"] = round(max(2.0, take * 0.85), 2)
        result["hold"] = max(1, int(_number(result.get("hold"))) or 1)
    journal_diagnosis = context.get("journal_diagnosis") if isinstance(context.get("journal_diagnosis"), dict) else {}
    journal_metrics = journal_diagnosis.get("metrics") if isinstance(journal_diagnosis.get("metrics"), dict) else {}
    if "unfavorable_payoff_ratio" in actionable_reasons:
        loss_abs_pct = max(1.0, _number(journal_metrics.get("average_loss_abs_pct")))
        result["stop"] = round(max(1.0, (_number(result.get("stop")) or loss_abs_pct) * 0.8), 2)
        current_take = _number(result.get("take"))
        result["take"] = round(max(current_take * 1.15, loss_abs_pct * 1.8), 2)
    if "transaction_cost_drag" in actionable_reasons:
        result["fast"] = max(2, int(_number(result.get("fast"))) + 2)
        result["slow"] = max(int(_number(result.get("fast"))) + 3, int(_number(result.get("slow"))) + 4)
        result["hold"] = max(3, int(_number(result.get("hold"))) + 2)
        result["allocation"] = round(max(10.0, _number(result.get("allocation")) * 0.9), 2)
    if "stop_loss_concentration" in actionable_reasons:
        result["fast"] = max(2, int(_number(result.get("fast"))) + 1)
        result["slow"] = max(int(_number(result.get("fast"))) + 3, int(_number(result.get("slow"))) + 3)
    if "risk_budget_underutilized" in actionable_reasons:
        result["allocation"] = round(
            min(50.0, max(10.0, (_number(result.get("allocation")) or 25.0) * 1.05)),
            2,
        )
    proposed_after = _ai_staff_strategy_parameters(result)
    proposed_changes = {
        key: {"before": before.get(key), "after": proposed_after.get(key)}
        for key in before
        if before.get(key) != proposed_after.get(key)
    }
    proposed_change_signature = _ai_staff_adaptation_changes_signature(proposed_changes)
    history = (
        context.get("counterfactual_adaptation_history")
        if isinstance(context.get("counterfactual_adaptation_history"), dict)
        else {}
    )
    if preconfigured_monte_carlo_candidate:
        history = {}
    history_items = history.get("items") if isinstance(history.get("items"), list) else []
    matched_feedback = next(
        (
            item
            for item in history_items
            if isinstance(item, dict)
            and str(item.get("change_signature") or "") == proposed_change_signature
        ),
        {},
    )
    feedback_decision = str(matched_feedback.get("decision") or "")
    counterfactual_feedback: dict[str, object] = {
        "schema": "codexstock_ai_staff_next_decision_feedback_v1",
        "decision": feedback_decision or (
            "new_paper_hypothesis"
            if history_items
            else "no_prior_counterfactual_evidence"
        ),
        "original_proposed_change_signature": proposed_change_signature,
        "matched_prior_evidence": bool(matched_feedback),
        "prior_sample_count": int(_number(matched_feedback.get("sample_count"))),
        "prior_mean_risk_adjusted_improvement": matched_feedback.get(
            "mean_risk_adjusted_improvement"
        ),
        "prior_effect_statistics": matched_feedback.get("effect_statistics", {}),
        "known_regressed_repeat_blocked": False,
        "pivot_applied": False,
        "point_in_time_cutoff_enforced": bool(
            history.get("point_in_time_cutoff_enforced", True)
        ),
        "paper_only": True,
        "live_order_allowed": False,
        "automatic_promotion": False,
    }
    if feedback_decision == "reject_repeat_and_pivot":
        rejected_signatures = {
            str(item.get("change_signature") or "")
            for item in history_items
            if isinstance(item, dict)
            and item.get("decision") == "reject_repeat_and_pivot"
        }
        base_fast = max(2, int(_number(before.get("fast")) or 2))
        base_slow = max(base_fast + 3, int(_number(before.get("slow")) or base_fast + 3))
        base_allocation = _number(before.get("allocation")) or 25.0
        pivot_signature = ""
        pivot_result = dict(config)
        for step in range(1, 9):
            candidate = dict(config)
            candidate["slow"] = max(base_fast + 3, base_slow + step)
            candidate["allocation"] = round(
                max(5.0, base_allocation * max(0.55, 1.0 - 0.07 * step)),
                2,
            )
            candidate_after = _ai_staff_strategy_parameters(candidate)
            candidate_changes = {
                key: {"before": before.get(key), "after": candidate_after.get(key)}
                for key in before
                if before.get(key) != candidate_after.get(key)
            }
            candidate_signature = _ai_staff_adaptation_changes_signature(candidate_changes)
            if candidate_signature and candidate_signature not in rejected_signatures:
                pivot_result = candidate
                pivot_signature = candidate_signature
                break
        result = pivot_result
        adaptation_blockers.append("prior_same_parameter_change_regressed")
        counterfactual_feedback.update(
            {
                "decision": "reject_repeat_and_pivot",
                "known_regressed_repeat_blocked": True,
                "pivot_applied": True,
                "pivot_change_signature": pivot_signature,
                "next_action": "test_distinct_conservative_paper_hypothesis",
            }
        )
    elif feedback_decision == "repeat_supported_in_paper":
        counterfactual_feedback["next_action"] = "repeat_supported_change_on_new_paper_period"
    elif feedback_decision == "watch_more_paper_evidence":
        counterfactual_feedback["next_action"] = "collect_one_more_independent_paper_period"
    else:
        counterfactual_feedback["next_action"] = "test_new_paper_hypothesis"
    selected_profile = _replay_strategy_profile(str(result.get("strategy") or "ma_cross"))
    result["strategy_horizon"] = _replay_strategy_horizon(str(result.get("strategy") or "ma_cross"))
    result["master_strategy_proxy"] = bool(selected_profile.get("master_proxy"))
    result["stage2_requirements"] = list(selected_profile.get("stage2_requirements") or [])
    result["indicator_recipe"] = list(
        AI_STAFF_NATIVE_INDICATOR_RECIPES.get(str(result.get("strategy") or "ma_cross"), ("SMA", "RSI"))
    )
    after = _ai_staff_strategy_parameters(result)
    changes = {
        key: {"before": before.get(key), "after": after.get(key)}
        for key in before
        if before.get(key) != after.get(key)
    }
    counterfactual_feedback["final_change_signature"] = (
        _ai_staff_adaptation_changes_signature(changes)
    )
    adaptive = bool(changes)
    source_id = str(context.get("source_record_id") or "")
    result["label"] = f"{result.get('label') or result.get('strategy') or 'strategy'} / verified learning" if adaptive else result.get("label")
    executed_retraining_config_hash = (
        _ai_tournament_stress_retraining_config_hash(result)
        if preconfigured_monte_carlo_candidate
        else ""
    )
    monte_carlo_retraining_application = {
        "schema": "codexstock_monte_carlo_retraining_application_v1",
        "applied": preconfigured_monte_carlo_candidate,
        "plan_id": str(monte_carlo_retraining_contract.get("plan_id") or ""),
        "plan_hash": str(monte_carlo_retraining_contract.get("plan_hash") or ""),
        "candidate_id": str(monte_carlo_retraining_contract.get("candidate_id") or ""),
        "candidate_config_hash": str(
            monte_carlo_retraining_contract.get("candidate_config_hash") or ""
        ),
        "executed_config_hash": executed_retraining_config_hash,
        "exact_candidate_tested": bool(
            preconfigured_monte_carlo_candidate
            and executed_retraining_config_hash
            == str(monte_carlo_retraining_contract.get("candidate_config_hash") or "")
        ),
        "source_config": before if preconfigured_monte_carlo_candidate else {},
        "consumed_reason_codes": monte_carlo_retraining_consumed_reason_codes,
        "paper_only": True,
        "live_order_allowed": False,
        "automatic_promotion": False,
    }
    result["_learning_provenance"] = {
        "schema": "codexstock_ai_staff_learning_provenance_v1",
        "adaptive": adaptive,
        "verified_source_record_ids": [source_id] if adaptive and source_id else [],
        "source_evidence_hashes": {source_id: context.get("source_evidence_hash")} if adaptive and source_id else {},
        "source_contestant_id": context.get("source_contestant_id"),
        "source_period": {
            "start_date": context.get("source_start_date"),
            "end_date": context.get("source_end_date"),
        },
        "current_start_date": current_start_date,
        "reason_codes": reasons,
        "actionable_reason_codes": actionable_reasons,
        "non_actionable_reason_codes": [
            item for item in reasons if item not in actionable_reasons
        ],
        "adaptation_blockers": list(dict.fromkeys(adaptation_blockers)),
        "next_learning_action": (
            "expand_universe_or_target_period"
            if evidence_expansion_reasons.intersection(reasons) and not actionable_reasons
            else "collect_independent_confidence_and_official_stress_evidence"
            if "risk_budget_underutilized" in reasons and "risk_budget_underutilized" not in actionable_reasons
            else "run_same_period_paper_counterfactual"
        ),
        "adaptation_changes": changes,
        "source_metrics": context.get("source_metrics"),
        "journal_diagnosis": journal_diagnosis,
        "journal_lessons_applied": context.get("journal_lessons", []),
        "monte_carlo_reason_codes": context.get("monte_carlo_reason_codes", []),
        "stress_retraining_plan": context.get("stress_retraining_plan", {}),
        "monte_carlo_retraining": monte_carlo_retraining_application,
        "risk_budget_scale_up_gate": risk_scale_gate,
        "counterfactual_next_decision_feedback": counterfactual_feedback,
        "adaptation_algorithm": "role_aware_evidence_gated_adaptation_v6",
        "applied_before_replay": adaptive,
        "live_order_allowed": False,
        "policy": "Only prior official non-overlapping evidence may alter the next Paper strategy.",
    }
    return result


def build_ai_staff_learning_decision_reflection_audit(
    *,
    as_of_date: str = "",
) -> dict[str, object]:
    """Prove that causal Paper outcomes alter the next strategy decision without claiming profit."""
    cutoff = str(as_of_date or datetime.now(_zone("Asia/Seoul", 9)).date().isoformat())
    summary = _ai_staff_counterfactual_ledger_summary(include_completed_triplets=True)
    contexts = _ai_staff_verified_learning_contexts(
        cutoff,
        counterfactual_summary=summary,
    )
    contestants = {
        str(row.get("id") or ""): row
        for row in ai_tournament_contestants()
        if isinstance(row, dict)
    }
    rows: list[dict[str, object]] = []
    unsafe_repeat_count = 0
    prior_history_staff_count = 0
    for contestant_id, context in sorted(contexts.items()):
        source = (
            context.get("source_strategy")
            if isinstance(context.get("source_strategy"), dict)
            else {}
        )
        contestant = contestants.get(contestant_id, {})
        base = {
            "strategy": str(source.get("strategy") or contestant.get("strategy_mode") or "ma_cross"),
            "label": str(contestant.get("strategy_name") or source.get("strategy") or "verified baseline"),
            "fast": int(_number(source.get("fast")) or contestant.get("fast") or 12),
            "slow": int(_number(source.get("slow")) or contestant.get("slow") or 32),
            "stop": float(_number(source.get("stop")) or contestant.get("stop_loss_pct") or 8.0),
            "take": float(_number(source.get("take")) or contestant.get("take_profit_pct") or 0.0),
            "hold": int(_number(source.get("hold")) or contestant.get("holding_limit_days") or 0),
            "allocation": float(_number(source.get("allocation")) or contestant.get("allocation_pct") or 25.0),
            "max_positions": int(_number(source.get("max_positions")) or contestant.get("max_positions") or 3),
            "candidate_origin": "verified_prior_learning_baseline",
        }
        next_strategy = _apply_ai_staff_verified_learning(
            base,
            context,
            current_start_date=cutoff,
        )
        provenance = (
            next_strategy.get("_learning_provenance")
            if isinstance(next_strategy.get("_learning_provenance"), dict)
            else {}
        )
        feedback = (
            provenance.get("counterfactual_next_decision_feedback")
            if isinstance(provenance.get("counterfactual_next_decision_feedback"), dict)
            else {}
        )
        history = (
            context.get("counterfactual_adaptation_history")
            if isinstance(context.get("counterfactual_adaptation_history"), dict)
            else {}
        )
        history_count = int(_number(history.get("history_count")))
        if history_count > 0:
            prior_history_staff_count += 1
        original_signature = str(feedback.get("original_proposed_change_signature") or "")
        final_signature = str(feedback.get("final_change_signature") or "")
        known_rejected = str(feedback.get("decision") or "") == "reject_repeat_and_pivot"
        repeat_blocked = bool(
            not known_rejected
            or (
                feedback.get("known_regressed_repeat_blocked") is True
                and feedback.get("pivot_applied") is True
                and final_signature
                and final_signature != original_signature
            )
        )
        if not repeat_blocked:
            unsafe_repeat_count += 1
        rows.append(
            {
                "contestant_id": contestant_id,
                "display_name": contestant.get("display_name") or contestant_id,
                "source_record_id": context.get("source_record_id"),
                "source_end_date": context.get("source_end_date"),
                "as_of_date": cutoff,
                "prior_change_signature_count": history_count,
                "prior_triplet_count": int(_number(history.get("prior_triplet_count"))),
                "rejected_signature_count": int(_number(history.get("rejected_signature_count"))),
                "supported_signature_count": int(_number(history.get("supported_signature_count"))),
                "feedback_decision": feedback.get("decision"),
                "matched_prior_evidence": bool(feedback.get("matched_prior_evidence")),
                "prior_sample_count": int(_number(feedback.get("prior_sample_count"))),
                "prior_mean_risk_adjusted_improvement": feedback.get(
                    "prior_mean_risk_adjusted_improvement"
                ),
                "known_regressed_repeat_detected": known_rejected,
                "known_regressed_repeat_blocked": bool(
                    known_rejected and repeat_blocked
                ),
                "no_unsafe_known_regressed_repeat": repeat_blocked,
                "original_proposed_change_signature": original_signature,
                "final_change_signature": final_signature,
                "final_strategy": _ai_staff_strategy_parameters(next_strategy),
                "adaptation_changes": provenance.get("adaptation_changes", {}),
                "point_in_time_cutoff_enforced": bool(
                    feedback.get("point_in_time_cutoff_enforced")
                ),
                "paper_only": True,
                "live_order_allowed": False,
                "automatic_promotion": False,
            }
        )

    completed_triplets = summary.get("causal_completed_triplets")
    historical_repeat_checks: list[dict[str, object]] = []
    for triplet in completed_triplets if isinstance(completed_triplets, list) else []:
        if not isinstance(triplet, dict):
            continue
        contestant_id = str(triplet.get("contestant_id") or "")
        target_start = str(triplet.get("start_date") or "")
        changes = (
            triplet.get("adaptation_changes")
            if isinstance(triplet.get("adaptation_changes"), dict)
            else {}
        )
        signature = _ai_staff_adaptation_changes_signature(changes)
        if not contestant_id or not target_start or not signature:
            continue
        prior_history = _ai_staff_counterfactual_adaptation_history(
            contestant_id,
            before_date=target_start,
            summary=summary,
        )
        prior_match = next(
            (
                item
                for item in prior_history.get("items", [])
                if isinstance(item, dict)
                and str(item.get("change_signature") or "") == signature
            ),
            {},
        )
        if prior_match.get("decision") != "reject_repeat_and_pivot":
            continue
        historical_repeat_checks.append(
            {
                "contestant_id": contestant_id,
                "strategy_generation_id": triplet.get("strategy_generation_id"),
                "target_start_date": target_start,
                "target_end_date": triplet.get("end_date"),
                "change_signature": signature,
                "prior_sample_count": int(_number(prior_match.get("sample_count"))),
                "prior_mean_risk_adjusted_improvement": prior_match.get(
                    "mean_risk_adjusted_improvement"
                ),
                "guard_decision": "reject_repeat_and_pivot",
                "would_block_repeated_failure_now": True,
                "point_in_time_cutoff_enforced": bool(
                    prior_history.get("point_in_time_cutoff_enforced")
                ),
                "paper_only": True,
                "live_order_allowed": False,
            }
        )
    historical_guard_verified = bool(
        historical_repeat_checks
        and all(
            row.get("would_block_repeated_failure_now") is True
            and row.get("point_in_time_cutoff_enforced") is True
            for row in historical_repeat_checks
        )
    )
    reflection_verified = bool(
        rows
        and prior_history_staff_count == len(rows)
        and unsafe_repeat_count == 0
        and all(row.get("point_in_time_cutoff_enforced") for row in rows)
        and historical_guard_verified
    )
    performance_improvement_proven = bool(
        summary.get("counterfactual_confidence_gate_passed") is True
    )
    if reflection_verified and performance_improvement_proven:
        status = "decision_and_performance_verified"
    elif reflection_verified:
        status = "decision_reflection_verified_performance_pending"
    else:
        status = "decision_reflection_gap"
    return {
        "ok": True,
        "schema": "codexstock_ai_staff_learning_decision_reflection_audit_v1",
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "as_of_date": cutoff,
        "status": status,
        "staff_count": len(rows),
        "prior_history_staff_count": prior_history_staff_count,
        "unsafe_known_regressed_repeat_count": unsafe_repeat_count,
        "historical_regressed_repeat_opportunity_count": len(
            historical_repeat_checks
        ),
        "historical_repeat_guard_verified": historical_guard_verified,
        "historical_repeat_checks": historical_repeat_checks[:20],
        "next_decision_reflection_verified": reflection_verified,
        "performance_improvement_proven": performance_improvement_proven,
        "causal_completed_triplet_count": int(
            _number(summary.get("causal_completed_triplet_count"))
        ),
        "improved_triplet_count": int(_number(summary.get("improved_triplet_count"))),
        "regressed_triplet_count": int(_number(summary.get("regressed_triplet_count"))),
        "inconclusive_triplet_count": int(_number(summary.get("inconclusive_triplet_count"))),
        "effect_statistics": summary.get("counterfactual_effect_statistics", {}),
        "staff": rows,
        "next_action": (
            "continue_new_independent_paper_periods_until_confidence_lower_bound_is_positive"
            if reflection_verified and not performance_improvement_proven
            else "repair_next_decision_feedback_path"
            if not reflection_verified
            else "retain_verified_policy_and_monitor_forward_performance"
        ),
        "paper_only": True,
        "live_order_allowed": False,
        "automatic_promotion": False,
        "official_performance_claim_allowed": performance_improvement_proven,
    }


def _ai_tournament_challenge_ranking_score(replay: dict[str, object]) -> float:
    return_pct = _number(replay.get("total_return_pct"))
    mdd_abs = abs(_number(replay.get("max_drawdown_pct")))
    trade_count = int(_number(replay.get("trade_count")))
    win_rate = _number(replay.get("win_rate_pct"))
    return round(return_pct - mdd_abs * 0.25 + min(trade_count, 120) * 0.02 + win_rate * 0.03, 2)


def _ai_tournament_contest_entries(raw_returns: list[object] | None = None, label: str = "실전투자대회") -> list[dict[str, object]]:
    entries: list[dict[str, object]] = []
    for index, value in enumerate(raw_returns or [], start=1):
        try:
            return_pct = float(str(value).strip().replace("%", ""))
        except Exception:
            continue
        entries.append({"name": f"{label} 참가자 {index}", "return_pct": round(return_pct, 2)})
    entries.sort(key=lambda row: _number(row.get("return_pct")), reverse=True)
    return entries


def _ai_tournament_trial_consistency(row: dict[str, object]) -> dict[str, object]:
    trials = row.get("challenge_trials") if isinstance(row.get("challenge_trials"), list) else []
    valid = [
        trial for trial in trials
        if isinstance(trial, dict) and "return_pct" in trial and "mdd_pct" in trial
    ]
    returns = [_number(trial.get("return_pct")) for trial in valid]
    mdds = [abs(_number(trial.get("mdd_pct"))) for trial in valid]
    if not returns:
        return {
            "tested": 0,
            "positive_count": 0,
            "positive_rate_pct": 0.0,
            "avg_return_pct": 0.0,
            "min_return_pct": 0.0,
            "max_mdd_pct": 0.0,
            "status": "단일 전술",
            "message": "여러 전술 반복 기록이 없어 기본 리그 결과만 평가합니다.",
        }
    positive_count = sum(1 for value in returns if value > 0)
    avg_return = sum(returns) / len(returns)
    min_return = min(returns)
    max_mdd = max(mdds) if mdds else abs(_number(row.get("max_drawdown_pct")))
    if positive_count == len(returns) and min_return > 0:
        status = "반복 안정"
    elif avg_return > 0 and positive_count >= max(1, math.ceil(len(returns) * 0.5)):
        status = "부분 안정"
    else:
        status = "과최적화 의심"
    return {
        "tested": len(returns),
        "positive_count": positive_count,
        "positive_rate_pct": round((positive_count / len(returns)) * 100.0, 1),
        "avg_return_pct": round(avg_return, 2),
        "min_return_pct": round(min_return, 2),
        "max_mdd_pct": round(max_mdd, 2),
        "status": status,
        "message": f"{len(returns)}개 전술 중 {positive_count}개가 플러스입니다.",
    }


def _ai_tournament_monte_carlo_stress(
    replay: dict[str, object],
    *,
    iterations: int = 300,
    seed: str = "",
) -> dict[str, object]:
    """Closed trades를 흔들어 전략이 운 좋은 매매 순서에 기대는지 점검한다."""
    initial_cash = max(1.0, _number(replay.get("initial_cash")) or 1.0)
    trades: list[dict[str, object]] = []
    sample_source = "missing"
    journal_path_text = str(replay.get("trade_journal_path") or "").strip()
    if journal_path_text:
        try:
            journal_payload = json.loads(Path(journal_path_text).read_text(encoding="utf-8"))
            journal_rows = (
                journal_payload.get("closed_trades")
                if isinstance(journal_payload, dict) and isinstance(journal_payload.get("closed_trades"), list)
                else []
            )
            trades = [row for row in journal_rows if isinstance(row, dict)]
            if trades:
                sample_source = "full_trade_journal"
        except (OSError, json.JSONDecodeError):
            trades = []
    if not trades:
        sample_rows = replay.get("trade_journal_sample") if isinstance(replay.get("trade_journal_sample"), list) else []
        trades = [row for row in sample_rows if isinstance(row, dict)]
        if trades:
            sample_source = "replay_trade_journal_sample"
    if not trades:
        trades = []
        for key in ("trade_journal_top10", "trade_journal_bottom10"):
            rows = replay.get(key) if isinstance(replay.get(key), list) else []
            trades.extend(row for row in rows if isinstance(row, dict))
        if trades:
            sample_source = "extreme_trade_sample"
    impacts: list[float] = []
    for trade in trades:
        if not isinstance(trade, dict):
            continue
        pnl_pct = _number(trade.get("pnl_pct"))
        if pnl_pct == 0:
            continue
        notional = _number(trade.get("notional"))
        exposure = _clamp(notional / initial_cash, 0.02, 0.45) if notional else 0.12
        impacts.append((pnl_pct / 100.0) * exposure)
    actual_trade_sample_count = len(impacts)
    synthetic_sample_used = False
    if len(impacts) < 3:
        total_return = _number(replay.get("total_return_pct"))
        trade_count = max(3, int(_number(replay.get("closed_trade_count") or replay.get("trade_count")) or 3))
        avg_impact = (total_return / 100.0) / trade_count
        if avg_impact:
            impacts = [avg_impact * factor for factor in (1.2, 0.8, -0.65)] * max(1, trade_count // 3)
            synthetic_sample_used = True
            sample_source = "synthetic_aggregate_diagnostic"
    if len(impacts) < 3:
        return {
            "ok": False,
            "status": "표본 부족",
            "message": "청산 매매 표본이 부족해 몬테카를로 스트레스 테스트를 생략했습니다.",
            "trades_used": len(impacts),
            "sample_source": sample_source,
            "official_evidence": False,
            "passed": False,
            "blockers": ["monte_carlo_actual_sample_insufficient"],
        }
    iterations = max(50, min(int(iterations or 300), 1500))
    seed_text = seed or str(replay.get("id") or replay.get("summary") or "")
    seed_int = int(hashlib.sha256(seed_text.encode("utf-8")).hexdigest()[:12], 16)
    rng = random.Random(seed_int)
    finals: list[float] = []
    mdds: list[float] = []
    ruin_count = 0
    positive_count = 0
    n = len(impacts)
    negative_impacts = [impact for impact in impacts if impact < 0]
    for _ in range(iterations):
        equity = 1.0
        peak = 1.0
        max_drawdown = 0.0
        previous_loss = False
        for _step in range(n):
            clustered_loss = bool(previous_loss and negative_impacts and rng.random() < 0.35)
            impact = rng.choice(negative_impacts if clustered_loss else impacts)
            if impact < 0 and rng.random() < 0.10:
                impact *= 1.50
            shaken = impact * rng.uniform(0.70, 1.30) + rng.gauss(0.0, max(0.001, abs(impact) * 0.15))
            equity *= max(0.05, 1.0 + shaken)
            peak = max(peak, equity)
            max_drawdown = min(max_drawdown, (equity / peak - 1.0) * 100.0 if peak else 0.0)
            previous_loss = shaken < 0
        final_return = (equity - 1.0) * 100.0
        finals.append(final_return)
        mdds.append(abs(max_drawdown))
        if final_return > 0:
            positive_count += 1
        if final_return <= -30.0 or abs(max_drawdown) >= 25.0:
            ruin_count += 1
    finals.sort()
    mdds.sort()

    def percentile(values: list[float], pct: float) -> float:
        if not values:
            return 0.0
        index = _clamp((len(values) - 1) * pct, 0, len(values) - 1)
        lower = int(math.floor(index))
        upper = int(math.ceil(index))
        if lower == upper:
            return values[lower]
        ratio = index - lower
        return values[lower] * (1.0 - ratio) + values[upper] * ratio

    positive_rate = (positive_count / iterations) * 100.0
    ruin_rate = (ruin_count / iterations) * 100.0
    p10 = percentile(finals, 0.10)
    median = percentile(finals, 0.50)
    p90 = percentile(finals, 0.90)
    mdd90 = percentile(mdds, 0.90)
    raw_path_gate_passed = positive_rate >= 60.0 and p10 > -8.0 and ruin_rate <= 8.0 and mdd90 <= 20.0
    minimum_official_trades = 20
    reconciliation = (
        replay.get("trade_journal_reconciliation_summary")
        if isinstance(replay.get("trade_journal_reconciliation_summary"), dict)
        else replay.get("return_reconciliation_summary")
        if isinstance(replay.get("return_reconciliation_summary"), dict)
        else {}
    )
    reconciliation_validated = bool(
        int(_number(reconciliation.get("checked_count"))) >= min(actual_trade_sample_count, minimum_official_trades)
        and int(_number(reconciliation.get("official_return_blocker_count"))) == 0
        and int(_number(reconciliation.get("blocker_count"))) == 0
    )
    actual_sample_sufficient = bool(
        not synthetic_sample_used
        and sample_source in {"full_trade_journal", "replay_trade_journal_sample"}
        and actual_trade_sample_count >= minimum_official_trades
    )
    blockers: list[str] = []
    if not actual_sample_sufficient:
        blockers.append("monte_carlo_actual_sample_insufficient")
    if not reconciliation_validated:
        blockers.append("monte_carlo_reconciliation_not_validated")
    if positive_rate < 60.0:
        blockers.append("monte_carlo_low_positive_path_rate")
    if p10 <= -8.0:
        blockers.append("monte_carlo_negative_tail_return")
    if ruin_rate > 8.0:
        blockers.append("monte_carlo_ruin_risk")
    if mdd90 > 20.0:
        blockers.append("monte_carlo_tail_drawdown")
    passed = bool(raw_path_gate_passed and actual_sample_sufficient and reconciliation_validated)
    status = "스트레스 통과" if passed else "스트레스 취약"
    return {
        "ok": True,
        "status": status,
        "passed": passed,
        "raw_path_gate_passed": raw_path_gate_passed,
        "official_evidence": passed,
        "model_version": "loss-cluster-tail-shock-v2",
        "iterations": iterations,
        "trades_used": n,
        "actual_trade_sample_count": actual_trade_sample_count,
        "minimum_official_trades": minimum_official_trades,
        "actual_sample_sufficient": actual_sample_sufficient,
        "synthetic_sample_used": synthetic_sample_used,
        "sample_source": sample_source,
        "reconciliation_validated": reconciliation_validated,
        "blockers": list(dict.fromkeys(blockers)),
        "positive_rate_pct": round(positive_rate, 1),
        "ruin_rate_pct": round(ruin_rate, 1),
        "p10_return_pct": round(p10, 2),
        "median_return_pct": round(median, 2),
        "p90_return_pct": round(p90, 2),
        "p90_mdd_pct": round(mdd90, 2),
        "message": f"{iterations}회 스트레스: 플러스 {positive_rate:.1f}%, 손상 {ruin_rate:.1f}%, P10 {p10:.2f}%",
    }


def _ai_tournament_monte_carlo_failure_reasons(stress: dict[str, object]) -> list[str]:
    if not isinstance(stress, dict) or not stress:
        return ["monte_carlo_evidence_missing"]
    reasons: list[str] = []
    if stress.get("ok") is not True:
        reasons.append("monte_carlo_evidence_missing")
    if stress.get("actual_sample_sufficient") is False:
        reasons.append("monte_carlo_actual_sample_insufficient")
    if stress.get("reconciliation_validated") is False:
        reasons.append("monte_carlo_reconciliation_not_validated")
    if _number(stress.get("positive_rate_pct")) < 60.0:
        reasons.append("monte_carlo_low_positive_path_rate")
    if _number(stress.get("p10_return_pct")) <= -8.0:
        reasons.append("monte_carlo_negative_tail_return")
    if _number(stress.get("ruin_rate_pct")) > 8.0:
        reasons.append("monte_carlo_ruin_risk")
    if _number(stress.get("p90_mdd_pct")) > 20.0:
        reasons.append("monte_carlo_tail_drawdown")
    if stress.get("passed") is False and not reasons:
        reasons.append("monte_carlo_stress_gate_failed")
    return list(dict.fromkeys(reasons))


def _ai_tournament_stress_retraining_config_hash(config: dict[str, object]) -> str:
    material = _ai_staff_strategy_parameters(config)
    return hashlib.sha256(
        json.dumps(
            material,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _ai_tournament_stress_retraining_candidate_material(
    candidate: dict[str, object],
) -> dict[str, object]:
    return {
        "config": _ai_staff_strategy_parameters(candidate),
        "label": str(candidate.get("label") or ""),
        "candidate_origin": str(candidate.get("candidate_origin") or ""),
    }


def _ai_tournament_stress_retraining_plan_material(
    *,
    source_config: dict[str, object],
    reason_codes: list[str],
    candidate_configs: list[dict[str, object]],
) -> dict[str, object]:
    return {
        "schema": "codexstock_monte_carlo_stress_retraining_plan_v1",
        "source_config": _ai_staff_strategy_parameters(source_config),
        "reason_codes": list(dict.fromkeys(str(item) for item in reason_codes if str(item))),
        "candidate_configs": [
            _ai_tournament_stress_retraining_candidate_material(candidate)
            for candidate in candidate_configs
        ],
        "paper_only": True,
        "live_order_allowed": False,
        "automatic_promotion": False,
    }


def _ai_tournament_stress_retraining_plan_valid(plan: dict[str, object]) -> bool:
    if not isinstance(plan, dict):
        return False
    candidates = plan.get("candidate_configs")
    source_config = plan.get("source_config")
    reason_codes = plan.get("reason_codes")
    if (
        plan.get("schema") != "codexstock_monte_carlo_stress_retraining_plan_v1"
        or not isinstance(candidates, list)
        or not isinstance(source_config, dict)
        or not isinstance(reason_codes, list)
        or plan.get("paper_only") is not True
        or plan.get("live_order_allowed") is not False
        or plan.get("automatic_promotion") is not False
        or plan.get("required") is not bool(candidates)
    ):
        return False
    normalized_candidates = [dict(item) for item in candidates if isinstance(item, dict)]
    if len(normalized_candidates) != len(candidates):
        return False
    for candidate in normalized_candidates:
        expected_hash = _ai_tournament_stress_retraining_config_hash(candidate)
        if str(candidate.get("candidate_config_hash") or "") != expected_hash:
            return False
        if str(candidate.get("retraining_candidate_id") or "") != f"MCRC-{expected_hash[:16].upper()}":
            return False
        if candidate.get("candidate_origin") != "monte_carlo_stress_retraining":
            return False
    material = _ai_tournament_stress_retraining_plan_material(
        source_config=source_config,
        reason_codes=[str(item) for item in reason_codes],
        candidate_configs=normalized_candidates,
    )
    expected_plan_hash = hashlib.sha256(
        json.dumps(
            material,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return bool(
        str(plan.get("plan_hash") or "") == expected_plan_hash
        and str(plan.get("plan_id") or "") == f"MCRP-{expected_plan_hash[:16].upper()}"
    )


def _ai_tournament_stress_retraining_plan(
    config: dict[str, object],
    stress: dict[str, object],
) -> dict[str, object]:
    reasons = _ai_tournament_monte_carlo_failure_reasons(stress)
    performance_reasons = [
        reason
        for reason in reasons
        if reason in {
            "monte_carlo_low_positive_path_rate",
            "monte_carlo_negative_tail_return",
            "monte_carlo_ruin_risk",
            "monte_carlo_tail_drawdown",
            "monte_carlo_stress_gate_failed",
        }
    ]
    base = _ai_staff_strategy_parameters(config)
    candidates: list[dict[str, object]] = []
    if performance_reasons:
        allocation = _number(base.get("allocation")) or 25.0
        max_positions = max(1, int(_number(base.get("max_positions")) or 1))
        stop = _number(base.get("stop")) or 8.0
        candidates = [
            {
                **base,
                "label": "stress exposure cut",
                "allocation": round(max(5.0, allocation * 0.65), 2),
                "max_positions": max(1, max_positions - 1),
                "candidate_origin": "monte_carlo_stress_retraining",
            },
            {
                **base,
                "label": "stress tail guard",
                "allocation": round(max(5.0, allocation * 0.78), 2),
                "stop": round(max(0.8, min(stop * 0.8, 4.0)), 2),
                "slow": max(
                    int(_number(base.get("fast")) or 2) + 3,
                    int(_number(base.get("slow")) or 5) + 2,
                ),
                "candidate_origin": "monte_carlo_stress_retraining",
            },
        ]
    for candidate in candidates:
        candidate_config_hash = _ai_tournament_stress_retraining_config_hash(candidate)
        candidate["candidate_config_hash"] = candidate_config_hash
        candidate["retraining_candidate_id"] = f"MCRC-{candidate_config_hash[:16].upper()}"
    material = _ai_tournament_stress_retraining_plan_material(
        source_config=base,
        reason_codes=reasons,
        candidate_configs=candidates,
    )
    plan_hash = hashlib.sha256(
        json.dumps(
            material,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return {
        "schema": "codexstock_monte_carlo_stress_retraining_plan_v1",
        "plan_id": f"MCRP-{plan_hash[:16].upper()}",
        "plan_hash": plan_hash,
        "required": bool(performance_reasons),
        "status": "paper_retest_required" if performance_reasons else "no_performance_retraining_required",
        "source_config": base,
        "reason_codes": reasons,
        "candidate_configs": candidates,
        "paper_only": True,
        "live_order_allowed": False,
        "automatic_promotion": False,
        "execution_contract": {
            "inject_into_next_paper_trial_pool": bool(performance_reasons),
            "same_period_source_control_required": bool(performance_reasons),
            "bounded_trial_budget": True,
            "live_order_allowed": False,
            "automatic_promotion": False,
        },
        "policy": "A failed stress test may create Paper hypotheses only; it cannot promote a strategy or submit an order.",
    }


def _ai_staff_monte_carlo_retraining_trial_configs(
    trial_configs: list[dict[str, object]],
    context: dict[str, object] | None,
    *,
    trial_budget: int,
    season_index: int,
) -> tuple[list[dict[str, object]], list[dict[str, object]]]:
    """Inject verified stress candidates into bounded Paper slots with aligned controls."""
    base_configs = [dict(config) for config in trial_configs if isinstance(config, dict)]
    if not base_configs:
        return [], []
    plan = (
        context.get("stress_retraining_plan")
        if isinstance(context, dict)
        and isinstance(context.get("stress_retraining_plan"), dict)
        else {}
    )
    if not plan.get("required") or not _ai_tournament_stress_retraining_plan_valid(plan):
        return base_configs, [dict(config) for config in base_configs]

    candidates = [
        dict(item)
        for item in plan.get("candidate_configs", [])
        if isinstance(item, dict)
    ]
    if not candidates:
        return base_configs, [dict(config) for config in base_configs]
    budget = max(1, min(int(trial_budget or 1), 12))
    offset = max(0, int(season_index or 0)) % len(candidates)
    rotated_candidates = candidates[offset:] + candidates[:offset]
    source_config = dict(plan.get("source_config") or {})
    pairs: list[tuple[dict[str, object], dict[str, object]]] = []
    for candidate in rotated_candidates:
        prepared = dict(candidate)
        prepared["_monte_carlo_retraining_contract"] = {
            "schema": "codexstock_monte_carlo_retraining_execution_contract_v1",
            "plan_id": plan.get("plan_id"),
            "plan_hash": plan.get("plan_hash"),
            "candidate_id": candidate.get("retraining_candidate_id"),
            "candidate_config_hash": candidate.get("candidate_config_hash"),
            "source_config": source_config,
            "paper_only": True,
            "live_order_allowed": False,
            "automatic_promotion": False,
        }
        control = {
            **source_config,
            "label": "Monte Carlo source control",
            "candidate_origin": "monte_carlo_stress_source_control",
        }
        pairs.append((prepared, control))
    pairs.extend((dict(config), dict(config)) for config in base_configs)

    selected: list[dict[str, object]] = []
    baselines: list[dict[str, object]] = []
    seen: set[str] = set()
    for candidate, control in pairs:
        signature = str(candidate.get("retraining_candidate_id") or "") or json.dumps(
            _ai_staff_strategy_parameters(candidate),
            ensure_ascii=True,
            sort_keys=True,
        )
        if signature in seen:
            continue
        seen.add(signature)
        selected.append(candidate)
        baselines.append(control)
        if len(selected) >= budget:
            break
    return selected, baselines


def _ai_tournament_competition_gate(row: dict[str, object]) -> dict[str, object]:
    return_pct = _number(row.get("total_return_pct"))
    mdd_abs = abs(_number(row.get("max_drawdown_pct")))
    win_rate = _number(row.get("win_rate_pct"))
    trade_count = int(_number(row.get("trade_count")))
    risk_limit = _number(row.get("risk_limit_pct")) or 15.0
    consistency = _ai_tournament_trial_consistency(row)
    stress = row.get("monte_carlo_stress") if isinstance(row.get("monte_carlo_stress"), dict) else {}
    bias_audit = row.get("bias_audit") if isinstance(row.get("bias_audit"), dict) else {}
    checks: list[dict[str, object]] = []

    def add_check(ok: bool, label: str, detail: str, weight: float) -> None:
        checks.append({"ok": bool(ok), "label": label, "detail": detail, "weight": weight})

    add_check(return_pct > 0, "수익률 플러스", f"{return_pct:.2f}%", 22)
    add_check(mdd_abs <= risk_limit, "MDD 한도", f"{mdd_abs:.2f}% / 한도 {risk_limit:.2f}%", 22)
    add_check(trade_count >= 3, "매매 표본", f"{trade_count}회", 14)
    add_check(win_rate >= 35 or trade_count < 3, "승률 방어", f"{win_rate:.1f}%", 12)
    add_check(_number(consistency.get("avg_return_pct")) >= 0, "반복 평균", f"{consistency.get('avg_return_pct')}%", 14)
    add_check(_number(consistency.get("min_return_pct")) > -risk_limit, "최악 전술 방어", f"{consistency.get('min_return_pct')}%", 16)
    add_check(bool(bias_audit.get("passed")), "생존편향·미래정보 차단", str(bias_audit.get("status") or "증거 없음"), 20)
    if stress.get("ok"):
        add_check(
            bool(stress.get("passed")),
            "몬테카를로 스트레스",
            f"{stress.get('status')} / 플러스 {stress.get('positive_rate_pct')}% / P10 {stress.get('p10_return_pct')}%",
            18,
        )

    base = 30.0
    earned = sum(float(item["weight"]) for item in checks if item.get("ok"))
    stress_penalty = 0.0
    if stress.get("ok") and not stress.get("passed"):
        stress_penalty = 12.0 + max(0.0, 60.0 - _number(stress.get("positive_rate_pct"))) * 0.15
    confidence = round(_clamp(base + earned * 0.7 + min(return_pct, 80) * 0.12 - max(0.0, mdd_abs - risk_limit) * 2.0 - stress_penalty, 0, 100), 1)
    failed = [item for item in checks if not item.get("ok")]
    if confidence >= 80 and not failed:
        grade = "S"
        status = "실전 승격 후보"
    elif confidence >= 65 and len(failed) <= 1:
        grade = "A"
        status = "재검증 후 후보"
    elif confidence >= 50:
        grade = "B"
        status = "연구 유지"
    else:
        grade = "C"
        status = "실전 보류"
    return {
        "grade": grade,
        "status": status,
        "confidence_score": confidence,
        "checks": checks,
        "failed_checks": failed,
        "trial_consistency": consistency,
        "monte_carlo_stress": stress,
        "message": f"{status}: 신뢰도 {confidence:.1f}점, 실패 체크 {len(failed)}개",
    }


def _ai_tournament_shadow_windows(start_date: str, end_date: str, max_windows: int = 1) -> list[dict[str, str]]:
    try:
        start = _parse_replay_date(start_date, "2024-01-01").date()
        end = _parse_replay_date(end_date, "2024-03-31").date()
    except Exception:
        return []
    span = max(60, (end - start).days)
    today = datetime.now(_zone("Asia/Seoul", 9)).date()
    windows: list[dict[str, str]] = []
    previous_end = start - timedelta(days=1)
    previous_start = previous_end - timedelta(days=span)
    if previous_start.year >= 2000:
        windows.append({
            "label": "이전 구간 블라인드",
            "start": previous_start.isoformat(),
            "end": previous_end.isoformat(),
        })
    next_start = end + timedelta(days=1)
    next_end = min(next_start + timedelta(days=span), today)
    if next_start < today and (next_end - next_start).days >= 45:
        windows.append({
            "label": "이후 구간 블라인드",
            "start": next_start.isoformat(),
            "end": next_end.isoformat(),
        })
    return windows[: max(0, min(int(max_windows or 1), 2))]


def _ai_tournament_shadow_validation(
    row: dict[str, object],
    *,
    start_date: str,
    end_date: str,
    initial_cash: float,
    allow_simulated_fallback: bool,
    source: str,
) -> dict[str, object]:
    windows = _ai_tournament_shadow_windows(start_date, end_date, max_windows=1)
    if not row or not windows:
        return {
            "ok": False,
            "status": "블라인드 구간 없음",
            "windows": [],
            "message": "인접한 검증 구간이 부족해 블라인드 검증을 생략했습니다.",
        }
    config = row.get("selected_challenge_config") if isinstance(row.get("selected_challenge_config"), dict) else {}
    symbols = _normalize_tournament_symbols(row.get("selected_symbols") if isinstance(row.get("selected_symbols"), list) else [])
    if len(symbols) < 3:
        return {
            "ok": False,
            "status": "검증 종목 부족",
            "windows": [],
            "message": "우승 후보의 선택 종목이 부족해 블라인드 검증을 생략했습니다.",
        }
    results: list[dict[str, object]] = []
    errors: list[dict[str, object]] = []
    for index, window in enumerate(windows, start=1):
        try:
            fast_window, slow_window, window_adjusted = _ai_tournament_windows_for_period(
                window["start"],
                window["end"],
                int(row.get("fast_window") or 5),
                int(row.get("slow_window") or 20),
            )
            replay = run_historical_paper_replay(
                symbols=symbols[:12],
                start_date=window["start"],
                end_date=window["end"],
                fast=fast_window,
                slow=slow_window,
                initial_cash=initial_cash,
                allocation_pct=float(config.get("allocation_pct", 25) or 25),
                max_positions=int(config.get("max_positions", 3) or 3),
                source=f"{source}-shadow-{row.get('contestant_id')}-{index}",
                strategy_mode=str(row.get("strategy_mode") or config.get("strategy_mode") or "ma_cross"),
                stop_loss_pct=float(config.get("stop_loss_pct", 8) or 8),
                take_profit_pct=float(config.get("take_profit_pct", 0) or 0),
                holding_limit_days=int(config.get("holding_limit_days", 0) or 0),
                cycles_per_day=24,
                allow_simulated_fallback=allow_simulated_fallback,
                min_bars=max(8, min(40, slow_window + 4)),
            )
            results.append({
                "label": window["label"],
                "start_date": window["start"],
                "end_date": window["end"],
                "replay_id": replay.get("id"),
                "return_pct": replay.get("total_return_pct"),
                "max_drawdown_pct": replay.get("max_drawdown_pct"),
                "win_rate_pct": replay.get("win_rate_pct"),
                "trade_count": replay.get("trade_count"),
                "fast_window": fast_window,
                "slow_window": slow_window,
                "window_adjusted": window_adjusted,
            })
        except Exception as exc:
            errors.append({"label": window.get("label"), "start_date": window.get("start"), "end_date": window.get("end"), "error": str(exc)})
    returns = [_number(item.get("return_pct")) for item in results]
    mdds = [abs(_number(item.get("max_drawdown_pct"))) for item in results]
    passed = bool(results) and min(returns) > -8.0 and (sum(returns) / len(returns)) >= 0.0 and (max(mdds) if mdds else 0.0) <= max(20.0, _number(row.get("risk_limit_pct")) * 1.5)
    return {
        "ok": bool(results),
        "status": "블라인드 통과" if passed else "블라인드 재훈련 필요",
        "passed": passed,
        "windows": results,
        "errors": errors,
        "avg_return_pct": round(sum(returns) / len(returns), 2) if returns else 0.0,
        "min_return_pct": round(min(returns), 2) if returns else 0.0,
        "max_mdd_pct": round(max(mdds), 2) if mdds else 0.0,
        "message": (
            f"블라인드 {len(results)}구간 평균 {round(sum(returns) / len(returns), 2) if returns else 0.0}%"
            if results
            else "블라인드 검증을 완료하지 못했습니다."
        ),
    }


def _ai_tournament_walk_forward_validation(
    row: dict[str, object],
    *,
    start_date: str,
    end_date: str,
    initial_cash: float,
    base_symbols: list[str],
    symbol_selection_mode: str,
    allow_simulated_fallback: bool,
    replay_cost_profile: dict[str, object] | None,
    source: str,
    replay_data_bundle: dict[str, object] | None = None,
) -> dict[str, object]:
    try:
        start = datetime.fromisoformat(start_date).date()
        end = datetime.fromisoformat(end_date).date()
    except ValueError:
        return {"ok": False, "passed": False, "status": "워크포워드 날짜 오류", "errors": ["invalid_date"]}
    span_days = (end - start).days
    symbols = _normalize_tournament_symbols(base_symbols)
    leakage_free_selection = str(symbol_selection_mode or "") == "common"
    requested_costs = replay_cost_profile if isinstance(replay_cost_profile, dict) else {}
    expected_cost_profile = {
        "commission_bps": max(
            DEFAULT_PAPER_COMMISSION_BPS,
            _number(requested_costs.get("commission_bps")) or DEFAULT_PAPER_COMMISSION_BPS,
        ),
        "slippage_bps": max(
            DEFAULT_PAPER_SLIPPAGE_BPS,
            _number(requested_costs.get("slippage_bps")) or DEFAULT_PAPER_SLIPPAGE_BPS,
        ),
        "kr_sell_tax_bps": max(
            DEFAULT_PAPER_KR_SELL_TAX_BPS,
            _number(requested_costs.get("kr_sell_tax_bps")) or DEFAULT_PAPER_KR_SELL_TAX_BPS,
        ),
        "fx_conversion_spread_bps": max(
            DEFAULT_PAPER_FX_SPREAD_BPS,
            _number(requested_costs.get("fx_conversion_spread_bps"))
            or DEFAULT_PAPER_FX_SPREAD_BPS,
        ),
    }

    def replay_evidence(replay: dict[str, object]) -> dict[str, object]:
        cost_model = replay.get("cost_model") if isinstance(replay.get("cost_model"), dict) else {}
        cost_audit = replay.get("transaction_cost_audit") if isinstance(replay.get("transaction_cost_audit"), dict) else {}
        price_audit = replay.get("price_currency_unit_audit") if isinstance(replay.get("price_currency_unit_audit"), dict) else {}
        timing = replay.get("execution_timing_model") if isinstance(replay.get("execution_timing_model"), dict) else {}
        trade_count = int(_number(replay.get("trade_count")))
        profile_matches = bool(
            abs(_number(cost_model.get("commission_bps_each_side")) - expected_cost_profile["commission_bps"]) <= 0.000001
            and abs(_number(cost_model.get("slippage_bps_each_side")) - expected_cost_profile["slippage_bps"]) <= 0.000001
            and abs(_number(cost_model.get("kr_sell_tax_bps")) - expected_cost_profile["kr_sell_tax_bps"]) <= 0.000001
            and abs(
                _number(cost_model.get("fx_conversion_spread_bps_each_side"))
                - expected_cost_profile["fx_conversion_spread_bps"]
            ) <= 0.000001
            and cost_model.get("us_regulatory_fee_policy_version")
            == PAPER_US_REGULATORY_POLICY_VERSION
        )
        cost_ledger_passed = bool(
            cost_model.get("mandatory") is True
            and cost_model.get("enabled") is True
            and cost_audit.get("schema") == "codexstock_replay_transaction_cost_audit_v1"
            and cost_audit.get("passed") is True
            and int(_number(cost_audit.get("applied_action_count"))) == trade_count
        )
        timing_passed = bool(
            timing.get("lookahead_safe_required") is True
            and timing.get("same_bar_signal_execution_allowed") is False
            and int(_number(timing.get("minimum_signal_lag_bars"))) >= 1
        )
        return {
            "cost_profile_matches": profile_matches,
            "cost_ledger_passed": cost_ledger_passed,
            "price_currency_unit_passed": bool(
                price_audit.get("passed") is True and price_audit.get("base_currency") == "KRW"
            ),
            "lookahead_safe_execution_passed": timing_passed,
            "passed": bool(
                profile_matches
                and cost_ledger_passed
                and price_audit.get("passed") is True
                and price_audit.get("base_currency") == "KRW"
                and timing_passed
            ),
        }
    blockers: list[str] = []
    if span_days < 180:
        blockers.append("period_shorter_than_180_days")
    if len(symbols) < 3:
        blockers.append("fewer_than_3_fixed_symbols")
    if not leakage_free_selection:
        blockers.append("independent_symbol_selection_may_use_future_information")
    if blockers:
        return {
            "ok": False,
            "passed": False,
            "status": "워크포워드 조건 미달",
            "blockers": blockers,
            "train_ratio_pct": 70.0,
            "symbols": symbols,
            "selection_leakage_free": leakage_free_selection,
            "message": "최소 180일·고정 3종목·공통 종목 조건을 충족해야 워크포워드 승격 증거로 인정합니다.",
        }

    split = start + timedelta(days=max(1, int(span_days * 0.70)))
    train_start = start.isoformat()
    train_end = split.isoformat()
    test_start = (split + timedelta(days=1)).isoformat()
    test_end = end.isoformat()
    contestant_id = str(row.get("contestant_id") or "")
    contestant = next(
        (item for item in ai_tournament_contestants() if str(item.get("id") or "") == contestant_id),
        {},
    )
    if not contestant:
        return {
            "ok": False,
            "passed": False,
            "status": "워크포워드 직원 설정 없음",
            "blockers": ["contestant_config_missing"],
        }
    configs = _ai_tournament_challenge_configs(contestant, trial_budget=3)
    training_candidates: list[dict[str, object]] = []
    errors: list[dict[str, object]] = []
    best_config: dict[str, object] | None = None
    best_score = -1e18
    for index, config in enumerate(configs, start=1):
        try:
            fast, slow, adjusted = _ai_tournament_windows_for_period(
                train_start,
                train_end,
                int(config.get("fast", 12) or 12),
                int(config.get("slow", 32) or 32),
            )
            replay = run_historical_paper_replay(
                symbols=symbols,
                start_date=train_start,
                end_date=train_end,
                fast=fast,
                slow=slow,
                initial_cash=initial_cash,
                allocation_pct=float(config.get("allocation", 25) or 25),
                max_positions=int(config.get("max_positions", 3) or 3),
                source=f"{source}-walk-forward-train-{contestant_id}-{index}",
                strategy_mode=str(config.get("strategy") or "ma_cross"),
                stop_loss_pct=float(config.get("stop", 8) or 8),
                take_profit_pct=float(config.get("take", 0) or 0),
                holding_limit_days=int(config.get("hold", 0) or 0),
                cycles_per_day=24,
                allow_simulated_fallback=allow_simulated_fallback,
                min_bars=max(8, min(40, slow + 4)),
                persist_detail=False,
                commission_bps=float(expected_cost_profile["commission_bps"]),
                slippage_bps=float(expected_cost_profile["slippage_bps"]),
                kr_sell_tax_bps=float(expected_cost_profile["kr_sell_tax_bps"]),
                fx_conversion_spread_bps=float(expected_cost_profile["fx_conversion_spread_bps"]),
                replay_data_bundle=replay_data_bundle,
            )
            ranking_score = _ai_tournament_challenge_ranking_score(replay)
            evidence = replay_evidence(replay)
            candidate = {
                "config_index": index,
                "strategy_label": config.get("label"),
                "strategy_mode": config.get("strategy"),
                "fast_window": fast,
                "slow_window": slow,
                "window_adjusted": adjusted,
                "return_pct": replay.get("total_return_pct"),
                "max_drawdown_pct": replay.get("max_drawdown_pct"),
                "trade_count": replay.get("trade_count"),
                "ranking_score": round(ranking_score, 4),
                "cost_model": replay.get("cost_model", {}),
                "evidence": evidence,
            }
            training_candidates.append(candidate)
            if ranking_score > best_score:
                best_score = ranking_score
                best_config = {**config, "fast": fast, "slow": slow, "training_result": candidate}
        except Exception as exc:
            errors.append({"phase": "train", "config_index": index, "error": str(exc)})
    if not best_config:
        return {
            "ok": False,
            "passed": False,
            "status": "워크포워드 학습 실패",
            "errors": errors,
            "training_candidates": training_candidates,
        }
    try:
        test_fast, test_slow, test_adjusted = _ai_tournament_windows_for_period(
            test_start,
            test_end,
            int(best_config.get("fast", 12) or 12),
            int(best_config.get("slow", 32) or 32),
        )
        test_replay = run_historical_paper_replay(
            symbols=symbols,
            start_date=test_start,
            end_date=test_end,
            fast=test_fast,
            slow=test_slow,
            initial_cash=initial_cash,
            allocation_pct=float(best_config.get("allocation", 25) or 25),
            max_positions=int(best_config.get("max_positions", 3) or 3),
            source=f"{source}-walk-forward-oos-{contestant_id}",
            strategy_mode=str(best_config.get("strategy") or "ma_cross"),
            stop_loss_pct=float(best_config.get("stop", 8) or 8),
            take_profit_pct=float(best_config.get("take", 0) or 0),
            holding_limit_days=int(best_config.get("hold", 0) or 0),
            cycles_per_day=24,
            allow_simulated_fallback=allow_simulated_fallback,
            min_bars=max(8, min(40, test_slow + 4)),
            persist_detail=False,
            commission_bps=float(expected_cost_profile["commission_bps"]),
            slippage_bps=float(expected_cost_profile["slippage_bps"]),
            kr_sell_tax_bps=float(expected_cost_profile["kr_sell_tax_bps"]),
            fx_conversion_spread_bps=float(expected_cost_profile["fx_conversion_spread_bps"]),
            replay_data_bundle=replay_data_bundle,
        )
    except Exception as exc:
        errors.append({"phase": "out_of_sample", "error": str(exc)})
        return {
            "ok": False,
            "passed": False,
            "status": "워크포워드 미래구간 실패",
            "errors": errors,
            "training_candidates": training_candidates,
        }
    training_result = best_config.get("training_result") if isinstance(best_config.get("training_result"), dict) else {}
    test_return = _number(test_replay.get("total_return_pct"))
    test_mdd = abs(_number(test_replay.get("max_drawdown_pct")))
    test_trades = int(_number(test_replay.get("trade_count")))
    risk_limit = _number(row.get("risk_limit_pct")) or 15.0
    cost_model = test_replay.get("cost_model") if isinstance(test_replay.get("cost_model"), dict) else {}
    training_evidence = training_result.get("evidence") if isinstance(training_result.get("evidence"), dict) else {}
    out_of_sample_evidence = replay_evidence(test_replay)
    main_replay_evidence = replay_evidence(row)
    checks = {
        "training_return_positive": _number(training_result.get("return_pct")) > 0,
        "out_of_sample_return_positive": test_return > 0,
        "out_of_sample_mdd_within_limit": test_mdd <= max(20.0, risk_limit * 1.5),
        "out_of_sample_trade_sample": test_trades >= 3,
        "training_evidence_passed": training_evidence.get("passed") is True,
        "out_of_sample_cost_ledger_passed": out_of_sample_evidence.get("cost_ledger_passed") is True,
        "out_of_sample_price_currency_unit_passed": out_of_sample_evidence.get("price_currency_unit_passed") is True,
        "out_of_sample_lookahead_safe_execution_passed": out_of_sample_evidence.get("lookahead_safe_execution_passed") is True,
        "same_cost_profile": bool(
            training_evidence.get("cost_profile_matches") is True
            and out_of_sample_evidence.get("cost_profile_matches") is True
            and main_replay_evidence.get("cost_profile_matches") is True
        ),
        "selection_leakage_free": leakage_free_selection,
    }
    measurement_check_ids = {
        "training_evidence_passed",
        "out_of_sample_cost_ledger_passed",
        "out_of_sample_price_currency_unit_passed",
        "out_of_sample_lookahead_safe_execution_passed",
        "same_cost_profile",
        "selection_leakage_free",
    }
    measurement_checks = {key: bool(value) for key, value in checks.items() if key in measurement_check_ids}
    measurement_evidence_validated = bool(measurement_checks) and all(measurement_checks.values())
    failed_check_ids = [key for key, value in checks.items() if not value]
    measurement_blockers = [key for key in failed_check_ids if key in measurement_check_ids]
    performance_blockers = [key for key in failed_check_ids if key not in measurement_check_ids]
    passed = all(checks.values())
    return {
        "ok": True,
        "schema": "codexstock_walk_forward_v1",
        "status": "워크포워드 통과" if passed else "워크포워드 재훈련 필요",
        "passed": passed,
        "strategy_promotion_passed": passed,
        "measurement_evidence_validated": measurement_evidence_validated,
        "measurement_checks": measurement_checks,
        "blockers": failed_check_ids,
        "measurement_blockers": measurement_blockers,
        "performance_blockers": performance_blockers,
        "selection_leakage_free": leakage_free_selection,
        "train_ratio_pct": 70.0,
        "train_period": {"start_date": train_start, "end_date": train_end},
        "out_of_sample_period": {"start_date": test_start, "end_date": test_end},
        "symbols": symbols,
        "selected_strategy": {
            "label": best_config.get("label"),
            "strategy_mode": best_config.get("strategy"),
            "fast_window": test_fast,
            "slow_window": test_slow,
            "window_adjusted": test_adjusted,
        },
        "training_result": training_result,
        "expected_cost_profile": expected_cost_profile,
        "main_replay_evidence": main_replay_evidence,
        "out_of_sample_result": {
            "return_pct": round(test_return, 2),
            "max_drawdown_pct": test_replay.get("max_drawdown_pct"),
            "win_rate_pct": test_replay.get("win_rate_pct"),
            "trade_count": test_trades,
            "total_transaction_cost": test_replay.get("total_transaction_cost"),
            "cost_model": cost_model,
            "transaction_cost_audit": test_replay.get("transaction_cost_audit", {}),
            "price_currency_unit_audit": test_replay.get("price_currency_unit_audit", {}),
            "execution_timing_model": test_replay.get("execution_timing_model", {}),
            "evidence": out_of_sample_evidence,
        },
        "checks": checks,
        "training_candidates": training_candidates,
        "errors": errors,
        "message": f"학습 70%에서 전술 선택 후 미래 30%를 1회 검증: OOS {test_return:+.2f}%, MDD {test_mdd:.2f}%",
    }


def _attach_ai_tournament_walk_forward_validations(
    rows: list[dict[str, object]],
    *,
    bias_audit: dict[str, object],
    start_date: str,
    end_date: str,
    initial_cash: float,
    base_symbols: list[str],
    symbol_selection_mode: str,
    allow_simulated_fallback: bool,
    replay_cost_profile: dict[str, object],
    source: str,
    replay_data_bundle: dict[str, object] | None = None,
) -> None:
    if bias_audit.get("passed") is not True:
        blocked = {
            "ok": False,
            "passed": False,
            "status": "blocked_before_walk_forward",
            "blockers": ["survivorship_or_lookahead_not_validated"],
            "message": "A verified point-in-time universe is required before walk-forward validation.",
        }
        for row in rows:
            row["walk_forward"] = dict(blocked)
        return
    for row in rows:
        row["walk_forward"] = _ai_tournament_walk_forward_validation(
            row,
            start_date=start_date,
            end_date=end_date,
            initial_cash=initial_cash,
            base_symbols=base_symbols,
            symbol_selection_mode=symbol_selection_mode,
            allow_simulated_fallback=allow_simulated_fallback,
            replay_cost_profile=replay_cost_profile,
            source=source,
            replay_data_bundle=replay_data_bundle,
        )


def _point_in_time_universe_claim_classification(
    evidence: dict[str, object],
) -> dict[str, object]:
    """Classify the exact claim scope supported by one universe dataset."""
    grade = str(evidence.get("grade") or "declared_intervals")
    official = evidence.get("official") is True
    historical = evidence.get("historical_query_allowed") is True
    complete_daily = evidence.get("complete_daily_history") is True
    includes_delisted = evidence.get("includes_delisted") is True
    clipped = int(_number(evidence.get("precoverage_listing_dates_clipped")))

    if not official:
        classification = "RESEARCH_ONLY_UNVERIFIED_SOURCE"
        reason = "The dataset is not backed by an official provider declaration."
        claim_scope = "research_only"
        performance_eligible = False
    elif grade == "official_fixed_pre_start_instruments":
        classification = "OFFICIAL_SCOPE_LIMITED_RESEARCH"
        reason = "The fixed pre-start instrument set can test timing, exits, and risk only."
        claim_scope = str(
            evidence.get("claim_scope") or "timing_exit_and_risk_management_only"
        )
        performance_eligible = False
    elif grade == "official_snapshot":
        classification = "OFFICIAL_EXACT_SNAPSHOT_ONLY"
        reason = "One official snapshot cannot reconstruct a historical selection universe."
        claim_scope = "exact_snapshot_only"
        performance_eligible = False
    elif grade == "official_snapshot_chain":
        classification = "OFFICIAL_FORWARD_CAPTURE_CHAIN"
        reason = "Only captured, gap-free forward dates can become certified."
        claim_scope = "captured_forward_dates_only"
        performance_eligible = bool(complete_daily and historical)
    elif grade in {"official_daily_history", "complete_listing_history"}:
        performance_eligible = bool(complete_daily and historical and includes_delisted)
        classification = (
            "OFFICIAL_PERFORMANCE_ELIGIBLE"
            if performance_eligible
            else "OFFICIAL_PARTIAL_RESEARCH_ONLY"
        )
        reason = (
            "The official point-in-time stock universe is complete for the declared range."
            if performance_eligible
            else "The official history is missing daily completeness or delisted securities."
        )
        claim_scope = (
            "point_in_time_stock_selection_and_timing"
            if performance_eligible
            else "requested_symbol_timing_research_only"
        )
    elif grade == "official_listing_interval_history":
        performance_eligible = bool(
            complete_daily and historical and includes_delisted and clipped == 0
        )
        classification = (
            "OFFICIAL_PERFORMANCE_ELIGIBLE"
            if performance_eligible
            else "OFFICIAL_PARTIAL_RESEARCH_ONLY"
        )
        reason = (
            "Official listing and delisting intervals are complete for the declared range."
            if performance_eligible
            else (
                "Official intervals exist, but clipped pre-coverage listing dates or other "
                "completeness gaps prevent a stock-selection performance claim."
            )
        )
        claim_scope = (
            "point_in_time_stock_selection_and_timing"
            if performance_eligible
            else "requested_symbol_timing_research_only"
        )
    else:
        classification = "OFFICIAL_PARTIAL_RESEARCH_ONLY"
        reason = "The official evidence grade does not prove a complete historical universe."
        claim_scope = "research_only"
        performance_eligible = False

    return {
        "classification": classification,
        "reason": reason,
        "claim_scope": claim_scope,
        "official": official,
        "historical_query_allowed": historical,
        "complete_daily_history": complete_daily,
        "includes_delisted": includes_delisted,
        "precoverage_listing_dates_clipped": clipped,
        "official_performance_claim_allowed": performance_eligible,
        "research_only": not performance_eligible,
    }


def _resolve_ai_tournament_universe_dataset(
    *,
    symbols: list[str],
    start_date: str,
    end_date: str,
    requested_dataset_id: str | None = None,
    store: UniverseStore | None = None,
) -> dict[str, object]:
    normalized = _normalize_tournament_symbols(symbols)
    requested_id = str(requested_dataset_id or "").strip()
    universe_store = store or UniverseStore(POINT_IN_TIME_UNIVERSE_ROOT)
    status = universe_store.status()
    datasets = status.get("datasets") if isinstance(status.get("datasets"), list) else []
    candidates: list[dict[str, object]] = []
    grade_priority = {
        "complete_listing_history": 600,
        "official_daily_history": 550,
        "official_listing_interval_history": 500,
        "official_snapshot": 300,
        "official_fixed_pre_start_instruments": 250,
        "declared_intervals": 100,
    }

    dataset_rows = [row for row in datasets if isinstance(row, dict)]
    if requested_id and not any(str(row.get("dataset_id") or "") == requested_id for row in dataset_rows):
        dataset_rows.append({"dataset_id": requested_id})

    for dataset in dataset_rows:
        dataset_id = str(dataset.get("dataset_id") or "").strip()
        if not dataset_id or (requested_id and dataset_id != requested_id):
            continue
        try:
            validation = universe_store.validate_period(dataset_id, normalized, start_date, end_date)
            evidence = validation.get("dataset_evidence") if isinstance(validation.get("dataset_evidence"), dict) else {}
            grade = str(evidence.get("grade") or "declared_intervals")
            official = evidence.get("official") is True
            validation_passed = bool(validation.get("passed"))
            claim_classification = _point_in_time_universe_claim_classification(evidence)
            auto_eligible = bool(
                validation_passed
                and official
                and claim_classification.get("official_performance_claim_allowed") is True
            )
            score = (
                grade_priority.get(grade, 0)
                + (80 if evidence.get("complete_daily_history") is True else 0)
                + (40 if evidence.get("includes_delisted") is True else 0)
                + (20 if evidence.get("historical_query_allowed") is True else 0)
            )
            candidates.append({
                "dataset_id": dataset_id,
                "validation_passed": validation_passed,
                "auto_eligible": auto_eligible,
                "official": official,
                "grade": grade,
                "score": score,
                "coverage_start": evidence.get("coverage_start"),
                "coverage_end": evidence.get("coverage_end"),
                "uncovered_symbols": validation.get("uncovered_symbols", []),
                "content_hash": validation.get("content_hash"),
                "claim_classification": claim_classification,
            })
        except Exception as exc:
            candidates.append({
                "dataset_id": dataset_id,
                "validation_passed": False,
                "auto_eligible": False,
                "error": f"{type(exc).__name__}: {exc}"[:300],
            })

    selected: dict[str, object] = {}
    if requested_id:
        selected = next((row for row in candidates if row.get("dataset_id") == requested_id), {})
    else:
        eligible = [row for row in candidates if row.get("auto_eligible")]
        selected = max(
            eligible,
            key=lambda row: (int(row.get("score") or 0), str(row.get("dataset_id") or "")),
            default={},
        )
    selected_id = str(selected.get("dataset_id") or "")
    return {
        "schema": "codexstock_tournament_universe_resolution_v1",
        "mode": "explicit" if requested_id else "automatic",
        "requested_dataset_id": requested_id or None,
        "selected_dataset_id": selected_id or None,
        "passed": bool(selected and selected.get("validation_passed")),
        "registered_dataset_count": int(status.get("dataset_count") or 0),
        "candidate_count": len(candidates),
        "candidates": candidates,
        "blocker": None if selected_id else "no_official_period_covering_dataset",
        "selection_policy": "Explicit IDs are never replaced; automatic selection requires official evidence and full requested-period coverage.",
    }


def _ai_tournament_bias_audit(
    *,
    symbols: list[str],
    start_date: str,
    end_date: str,
    symbol_selection_mode: str,
    universe_dataset_id: str | None,
    store: UniverseStore | None = None,
) -> dict[str, object]:
    normalized = _normalize_tournament_symbols(symbols)
    selection_mode = str(symbol_selection_mode or "").strip().lower()
    universe_store = store or UniverseStore(POINT_IN_TIME_UNIVERSE_ROOT)
    resolution = _resolve_ai_tournament_universe_dataset(
        symbols=normalized,
        start_date=start_date,
        end_date=end_date,
        requested_dataset_id=universe_dataset_id,
        store=universe_store,
    )
    dataset_id = str(resolution.get("selected_dataset_id") or "").strip()
    blockers: list[str] = []
    if selection_mode != "common":
        blockers.append("dynamic_or_independent_symbol_selection")
    if not dataset_id:
        blockers.append("point_in_time_universe_dataset_missing")
    evidence: dict[str, object] = {}
    if dataset_id:
        try:
            evidence = universe_store.validate_period(dataset_id, normalized, start_date, end_date)
            if not evidence.get("passed"):
                blockers.append("symbol_validity_interval_not_covered")
        except Exception as exc:
            blockers.append("point_in_time_universe_validation_failed")
            evidence = {"passed": False, "error": str(exc), "dataset_id": dataset_id}
    passed = not blockers
    dataset_evidence = evidence.get("dataset_evidence") if isinstance(evidence.get("dataset_evidence"), dict) else {}
    claim_classification = _point_in_time_universe_claim_classification(dataset_evidence)
    fixed_research_universe = dataset_evidence.get("grade") == "official_fixed_pre_start_instruments"
    complete_stock_selection_universe = bool(
        claim_classification.get("official_performance_claim_allowed") is True
    )
    if passed and not fixed_research_universe and not complete_stock_selection_universe:
        blockers.append("official_universe_history_incomplete_for_stock_selection")
        passed = False
    claim_scope = str(claim_classification.get("claim_scope") or "research_only")
    stock_selection_claim_allowed = bool(passed and complete_stock_selection_universe)
    interval_research_validated = bool(
        selection_mode == "common" and evidence.get("passed") is True
    )
    return {
        "ok": True,
        "schema": "codexstock_tournament_bias_audit_v1",
        "status": "생존편향·미래정보 차단 통과" if passed else "연구 전용: 공식 유니버스 증거 부족",
        "passed": passed,
        "symbols": normalized,
        "start_date": start_date,
        "end_date": end_date,
        "symbol_selection_mode": selection_mode,
        "selection_frozen_before_test": selection_mode == "common",
        "universe_dataset_id": dataset_id or None,
        "registered_dataset_count": int(resolution.get("registered_dataset_count") or 0),
        "universe_dataset_resolution": resolution,
        "universe_evidence": evidence,
        "universe_grade": dataset_evidence.get("grade"),
        "claim_scope": claim_scope,
        "claim_classification": claim_classification,
        "fixed_research_universe": fixed_research_universe,
        "stock_selection_claim_allowed": stock_selection_claim_allowed,
        "content_hash": evidence.get("content_hash"),
        "blockers": blockers,
        "promotion_allowed": stock_selection_claim_allowed,
        "research_claim_allowed": interval_research_validated,
        "official_performance_claim_allowed": stock_selection_claim_allowed,
        "research_only": not stock_selection_claim_allowed,
        "message": (
            "등록된 공식 point-in-time 유니버스가 종목선정 성과 주장 범위를 완전히 덮습니다."
            if passed
            else "불완전하거나 부분적인 과거 유니버스 결과는 연구 참고용으로만 사용합니다."
        ),
    }


