def _normalize_ai_tournament_champion_entry(row: dict[str, object]) -> dict[str, object] | None:
    try:
        return_pct = float(str(row.get("return_pct", "")).replace("%", "").strip())
    except Exception:
        return None
    contest_name = _clean_staff_persona_text(row.get("contest_name"), "실전투자대회", 80)
    champion_name = _clean_staff_persona_text(row.get("champion_name"), "챔피언", 40)
    league = _clean_staff_persona_text(row.get("league"), "리그", 60)
    raw_cash = row.get("initial_cash")
    try:
        initial_cash = float(raw_cash) if raw_cash not in {None, ""} else None
    except Exception:
        initial_cash = None
    entry_id = _clean_staff_persona_text(row.get("id"), "", 80)
    if not entry_id:
        slug = re.sub(r"[^0-9a-zA-Z가-힣]+", "-", f"{contest_name}-{league}-{champion_name}-{return_pct}").strip("-")
        entry_id = hashlib.sha256(slug.encode("utf-8")).hexdigest()[:16]
    return {
        "id": entry_id,
        "broker": _clean_staff_persona_text(row.get("broker"), "한국투자증권", 40),
        "contest_name": contest_name,
        "contest_id": _clean_staff_persona_text(row.get("contest_id"), entry_id, 80),
        "league": league,
        "market": _clean_staff_persona_text(row.get("market"), "KR", 12).upper(),
        "champion_name": champion_name,
        "return_pct": round(return_pct, 2),
        "initial_cash": initial_cash,
        "start_date": _clean_staff_persona_text(row.get("start_date"), "", 20),
        "end_date": _clean_staff_persona_text(row.get("end_date"), "", 20),
        "period_label": _clean_staff_persona_text(row.get("period_label"), "", 60),
        "source_label": _clean_staff_persona_text(row.get("source_label"), "사용자 입력", 80),
        "source_url": _clean_staff_persona_text(row.get("source_url"), "", 200),
    }


def load_ai_tournament_champions() -> list[dict[str, object]]:
    entries = [_normalize_ai_tournament_champion_entry(row) for row in _default_ai_tournament_champions()]
    result = [row for row in entries if row]
    if AI_TOURNAMENT_CHAMPIONS_FILE.exists():
        try:
            saved = json.loads(AI_TOURNAMENT_CHAMPIONS_FILE.read_text(encoding="utf-8"))
            rows = saved.get("entries", saved) if isinstance(saved, dict) else saved
            if isinstance(rows, list):
                result.extend(row for row in (_normalize_ai_tournament_champion_entry(item) for item in rows if isinstance(item, dict)) if row)
        except Exception:
            pass
    deduped: dict[str, dict[str, object]] = {}
    for row in result:
        deduped[str(row.get("id"))] = row
    return sorted(deduped.values(), key=lambda row: (str(row.get("start_date") or ""), _number(row.get("return_pct"))), reverse=True)


def save_ai_tournament_champions(payload: dict[str, object]) -> dict[str, object]:
    rows = payload.get("entries", [])
    if not isinstance(rows, list):
        rows = []
    custom_entries = [
        row for row in (_normalize_ai_tournament_champion_entry(item) for item in rows if isinstance(item, dict))
        if row
    ]
    AI_TOURNAMENT_CHAMPIONS_FILE.parent.mkdir(parents=True, exist_ok=True)
    AI_TOURNAMENT_CHAMPIONS_FILE.write_text(json.dumps({"entries": custom_entries}, ensure_ascii=False, indent=2), encoding="utf-8")
    JOURNAL.add("AI_TOURNAMENT_CHAMPIONS_SAVE", "실전투자대회 챔피언 기록 저장", {"count": len(custom_entries)})
    return {"ok": True, "entries": load_ai_tournament_champions(), "custom_count": len(custom_entries), "path": str(AI_TOURNAMENT_CHAMPIONS_FILE)}


def _champion_entries_for_query(query: dict[str, list[str]]) -> list[dict[str, object]]:
    use_champions = str(query.get("champions", ["0"])[0]).lower() in {"1", "true", "yes", "y"}
    if not use_champions:
        return []
    champion_id = str(query.get("champion_id", [""])[0]).strip()
    contest_id = str(query.get("contest_id", [""])[0]).strip()
    market = str(query.get("champion_market", [""])[0]).strip().upper()
    entries = load_ai_tournament_champions()
    if champion_id:
        selected = next((row for row in entries if str(row.get("id")) == champion_id), None)
        if selected:
            group_id = str(selected.get("contest_id") or "")
            entries = [row for row in entries if str(row.get("contest_id") or "") == group_id and (not market or str(row.get("market", "")).upper() == market)]
    elif contest_id:
        entries = [row for row in entries if str(row.get("contest_id") or "") == contest_id and (not market or str(row.get("market", "")).upper() == market)]
    elif market:
        entries = [row for row in entries if str(row.get("market", "")).upper() == market]
    return entries


def _apply_champion_condition_to_query_defaults(query: dict[str, list[str]], champion_entries: list[dict[str, object]]) -> tuple[str | None, str | None, float | None]:
    selected_id = str(query.get("champion_id", [""])[0]).strip()
    selected = next((row for row in champion_entries if str(row.get("id")) == selected_id), None)
    if not selected and champion_entries:
        selected = champion_entries[0]
    if not selected:
        return None, None, None
    start = str(selected.get("start_date") or "").strip() or None
    end = str(selected.get("end_date") or "").strip() or None
    cash = selected.get("initial_cash")
    return start, end, float(cash) if cash not in {None, ""} else None


def _ai_tournament_contest_entries_from_champions(champion_entries: list[dict[str, object]]) -> list[dict[str, object]]:
    entries: list[dict[str, object]] = []
    for row in champion_entries:
        try:
            return_pct = float(row.get("return_pct") or 0)
        except Exception:
            continue
        entries.append(
            {
                "name": f"{row.get('champion_name') or '챔피언'} · {row.get('league') or ''}",
                "return_pct": round(return_pct, 2),
                "champion_id": row.get("id"),
                "contest_name": row.get("contest_name"),
                "league": row.get("league"),
                "market": row.get("market"),
                "initial_cash": row.get("initial_cash"),
                "start_date": row.get("start_date"),
                "end_date": row.get("end_date"),
                "source_url": row.get("source_url"),
            }
        )
    return entries


def _ai_tournament_contest_ranks(rankings: list[dict[str, object]], entries: list[dict[str, object]], label: str = "실전투자대회") -> dict[str, object]:
    if not entries:
        return {"enabled": False, "label": label, "entries": [], "staff_ranks": []}
    staff_ranks: list[dict[str, object]] = []
    for row in rankings:
        return_pct = _number(row.get("total_return_pct"))
        better_count = sum(1 for item in entries if _number(item.get("return_pct")) > return_pct)
        same_or_better_count = sum(1 for item in entries if _number(item.get("return_pct")) >= return_pct)
        rank = better_count + 1
        staff_ranks.append(
            {
                "contestant_id": row.get("contestant_id"),
                "display_name": row.get("display_name") or row.get("name"),
                "return_pct": round(return_pct, 2),
                "estimated_rank": rank,
                "field_size": len(entries) + 1,
                "better_than_count": max(0, len(entries) - same_or_better_count),
                "percentile_top_pct": round((rank / max(1, len(entries) + 1)) * 100.0, 1),
            }
        )
    return {
        "enabled": True,
        "label": label,
        "entries": entries,
        "staff_ranks": staff_ranks,
        "note": "입력한 실전투자대회 수익률표 기준 예상 등수입니다. 실제 공식 순위표를 넣을수록 정확해집니다.",
    }


def run_ai_mini_league(
    *,
    league_name: str = "AI 직원 미니리그",
    start_date: str = "2024-01-01",
    end_date: str = "2024-03-31",
    initial_cash: float = 100_000_000.0,
    symbols: list[str] | None = None,
    benchmark_return_pct: float | None = None,
    contest_return_pcts: list[object] | None = None,
    contest_entries: list[dict[str, object]] | None = None,
    contest_label: str = "실전투자대회",
    symbol_selection_mode: str = "independent",
    season_index: int = 0,
    allow_simulated_fallback: bool = False,
    challenge_mode: bool | None = None,
    challenge_trials: int = 1,
    persist_replay_detail: bool = True,
    replay_cost_profile: dict[str, object] | None = None,
    universe_dataset_id: str | None = None,
    persist_tournament_record: bool = True,
    source: str = "api-ai-mini-league",
) -> dict[str, object]:
    start_date = _parse_replay_date(start_date, "2024-01-01").date().isoformat()
    end_date = _parse_replay_date(end_date, "2024-03-31").date().isoformat()
    initial_cash = max(1_000_000.0, float(initial_cash or 100_000_000.0))
    selected_symbols = _normalize_tournament_symbols(symbols)
    if not selected_symbols:
        selected_symbols = _ai_tournament_default_symbols(limit=8)
    selected_symbols = selected_symbols[:12]
    symbol_selection_mode = str(symbol_selection_mode or "independent").strip().lower()
    if symbol_selection_mode in {"same", "shared", "common", "fixed"}:
        symbol_selection_mode = "common"
    elif symbol_selection_mode not in {"common", "independent", "free"}:
        symbol_selection_mode = "independent"
    if symbol_selection_mode == "free":
        symbol_selection_mode = "independent"
    if challenge_mode is None:
        challenge_mode = bool(contest_entries)
    challenge_trials = max(1, min(int(challenge_trials or (6 if challenge_mode else 1)), 12))
    training_arena = _ai_staff_training_arena(start_date, end_date, season_index)
    requested_cost_profile = replay_cost_profile if isinstance(replay_cost_profile, dict) else {}
    cost_profile = {
        "commission_bps": max(
            DEFAULT_PAPER_COMMISSION_BPS,
            _number(requested_cost_profile.get("commission_bps")) or DEFAULT_PAPER_COMMISSION_BPS,
        ),
        "slippage_bps": max(
            DEFAULT_PAPER_SLIPPAGE_BPS,
            _number(requested_cost_profile.get("slippage_bps")) or DEFAULT_PAPER_SLIPPAGE_BPS,
        ),
        "kr_sell_tax_bps": max(
            DEFAULT_PAPER_KR_SELL_TAX_BPS,
            _number(requested_cost_profile.get("kr_sell_tax_bps")) or DEFAULT_PAPER_KR_SELL_TAX_BPS,
        ),
        "fx_conversion_spread_bps": max(
            DEFAULT_PAPER_FX_SPREAD_BPS,
            _number(requested_cost_profile.get("fx_conversion_spread_bps"))
            or DEFAULT_PAPER_FX_SPREAD_BPS,
        ),
        "mandatory": True,
        "policy_version": PAPER_COST_POLICY_VERSION,
        "us_regulatory_fee_policy_version": PAPER_US_REGULATORY_POLICY_VERSION,
        "us_sec_fee_schedule": [dict(row) for row in PAPER_US_SEC_FEE_SCHEDULE],
        "us_finra_taf_schedule": [dict(row) for row in PAPER_US_FINRA_TAF_SCHEDULE],
    }
    shared_replay_data_bundle: dict[str, object] | None = None
    if symbol_selection_mode == "common" and len(selected_symbols) > 1:
        shared_replay_data_bundle = _build_historical_replay_data_bundle(
            selected_symbols,
            start_date,
            end_date,
            allow_simulated_fallback=allow_simulated_fallback,
            min_bars=40,
        )

    contestants = ai_tournament_contestants()
    personal_bests = _ai_tournament_personal_bests()
    learning_contexts = _ai_staff_verified_learning_contexts(start_date)
    results: list[dict[str, object]] = []
    errors: list[dict[str, object]] = []
    selected_symbols_by_contestant: dict[str, list[str]] = {}
    for contestant in contestants:
        try:
            if symbol_selection_mode == "common":
                contestant_symbols = list(selected_symbols)
                selection_reason = "같은 종목 조건 비교"
            else:
                contestant_symbols, selection_reason = _ai_tournament_symbols_for_contestant(
                    contestant,
                    start_date=start_date,
                    end_date=end_date,
                    base_symbols=selected_symbols,
                    limit=8,
                    season_index=season_index,
                )
            trial_groups = [{"label": selection_reason, "symbols": contestant_symbols}]
            trial_configs = _ai_tournament_challenge_configs(
                contestant,
                trial_budget=1,
                before_date=start_date,
                end_date=end_date,
                season_index=season_index,
            )
            if challenge_mode:
                if symbol_selection_mode != "common":
                    trial_groups = _ai_tournament_challenge_symbol_groups(
                        contestant,
                        start_date=start_date,
                        end_date=end_date,
                        base_symbols=selected_symbols,
                        contestant_symbols=contestant_symbols,
                        season_index=season_index,
                    ) or trial_groups
                trial_configs = _ai_tournament_challenge_configs(
                    contestant,
                    trial_budget=challenge_trials,
                    before_date=start_date,
                    end_date=end_date,
                    season_index=season_index,
                )
            learning_context = learning_contexts.get(str(contestant.get("id") or ""))
            trial_configs, baseline_trial_configs = _ai_staff_monte_carlo_retraining_trial_configs(
                trial_configs,
                learning_context,
                trial_budget=challenge_trials if challenge_mode else 1,
                season_index=season_index,
            )
            trial_configs = [
                _apply_ai_staff_verified_learning(
                    config,
                    learning_context,
                    current_start_date=start_date,
                )
                for config in trial_configs
            ]

            best_pack: dict[str, object] | None = None
            trial_summaries: list[dict[str, object]] = []
            for trial_index in range(challenge_trials if challenge_mode else 1):
                group = trial_groups[trial_index % len(trial_groups)]
                config = trial_configs[trial_index % len(trial_configs)]
                trial_symbols = [str(item) for item in group.get("symbols", [])]
                try:
                    fast_window, slow_window, window_adjusted = _ai_tournament_windows_for_period(
                        start_date,
                        end_date,
                        int(config.get("fast", contestant.get("fast", 12)) or 12),
                        int(config.get("slow", contestant.get("slow", 32)) or 32),
                    )
                    replay = run_historical_paper_replay(
                        symbols=trial_symbols,
                        start_date=start_date,
                        end_date=end_date,
                        fast=fast_window,
                        slow=slow_window,
                        initial_cash=initial_cash,
                        allocation_pct=float(config.get("allocation", contestant.get("allocation_pct", 25)) or 25),
                        max_positions=int(config.get("max_positions", contestant.get("max_positions", 4)) or 4),
                        source=f"{source}-{contestant.get('id')}-trial{trial_index + 1}",
                        strategy_mode=str(config.get("strategy", contestant.get("strategy_mode") or "ma_cross")),
                        stop_loss_pct=float(config.get("stop", contestant.get("stop_loss_pct", 8)) or 8),
                        take_profit_pct=float(config.get("take", contestant.get("take_profit_pct", 0)) or 0),
                        holding_limit_days=int(config.get("hold", contestant.get("holding_limit_days", 0)) or 0),
                        cycles_per_day=24,
                        allow_simulated_fallback=allow_simulated_fallback,
                        min_bars=max(8, min(40, slow_window + 4)),
                        persist_detail=persist_replay_detail,
                        commission_bps=float(cost_profile.get("commission_bps", DEFAULT_PAPER_COMMISSION_BPS)),
                        slippage_bps=float(cost_profile.get("slippage_bps", DEFAULT_PAPER_SLIPPAGE_BPS)),
                        kr_sell_tax_bps=float(cost_profile.get("kr_sell_tax_bps", DEFAULT_PAPER_KR_SELL_TAX_BPS)),
                        fx_conversion_spread_bps=float(
                            cost_profile.get(
                                "fx_conversion_spread_bps",
                                DEFAULT_PAPER_FX_SPREAD_BPS,
                            )
                        ),
                        replay_data_bundle=shared_replay_data_bundle,
                    )
                    score = _ai_tournament_score(replay, float(contestant.get("risk_limit_pct", 15) or 15))
                    ranking_score = _ai_tournament_challenge_ranking_score(replay) if challenge_mode else float(score.get("score", 0) or 0)
                    score["ranking_score"] = ranking_score
                    score["ranking_score_formula"] = (
                        "챔피언 도전 모드: 수익률 - MDD*0.25 + 매매경험 + 승률"
                        if challenge_mode
                        else score.get("score_formula")
                    )
                    trial_row = {
                        "trial": trial_index + 1,
                        "group_label": group.get("label"),
                        "strategy_label": config.get("label"),
                        "strategy_mode": config.get("strategy"),
                        "strategy_candidate_origin": config.get("candidate_origin"),
                        "strategy_generation_id": config.get("strategy_generation_id"),
                        "strategy_horizon": config.get("strategy_horizon"),
                        "training_arena": dict(config.get("training_arena") or training_arena),
                        "agent_strategy_autonomy": bool(config.get("agent_strategy_autonomy")),
                        "autonomous_choice_basis": config.get("autonomous_choice_basis"),
                        "master_strategy_proxy": bool(config.get("master_strategy_proxy")),
                        "stage2_requirements": config.get("stage2_requirements", []),
                        "indicator_recipe": config.get("indicator_recipe", []),
                        "research_indicator_hypothesis": config.get("research_indicator_hypothesis", []),
                        "research_stage_required": bool(config.get("research_stage_required")),
                        "strategy_memory_source_record_id": config.get("strategy_memory_source_record_id"),
                        "symbols": trial_symbols,
                        "fast_window": fast_window,
                        "slow_window": slow_window,
                        "return_pct": replay.get("total_return_pct"),
                        "mdd_pct": replay.get("max_drawdown_pct"),
                        "trade_count": replay.get("trade_count"),
                        "reconciliation_needs_review": (
                            replay.get("trade_journal_reconciliation_summary", {}).get("needs_review", 0)
                            if isinstance(replay.get("trade_journal_reconciliation_summary"), dict)
                            else 0
                        ),
                        "ranking_score": ranking_score,
                        "learning_adaptive": bool(
                            isinstance(config.get("_learning_provenance"), dict)
                            and config.get("_learning_provenance", {}).get("adaptive")
                        ),
                        "monte_carlo_retraining": (
                            config.get("_learning_provenance", {}).get("monte_carlo_retraining", {})
                            if isinstance(config.get("_learning_provenance"), dict)
                            else {}
                        ),
                    }
                    trial_summaries.append(trial_row)
                    if best_pack is None or ranking_score > float(best_pack.get("ranking_score", -1e9)):
                        best_pack = {
                            "ranking_score": ranking_score,
                            "replay": replay,
                            "score": score,
                            "config": config,
                            "baseline_config": baseline_trial_configs[trial_index % len(baseline_trial_configs)],
                            "group": group,
                            "fast_window": fast_window,
                            "slow_window": slow_window,
                            "window_adjusted": window_adjusted,
                            "symbols": trial_symbols,
                        }
                except Exception as trial_exc:
                    trial_summaries.append(
                        {
                            "trial": trial_index + 1,
                            "group_label": group.get("label"),
                            "strategy_label": config.get("label"),
                            "strategy_mode": config.get("strategy"),
                            "symbols": trial_symbols,
                            "error": str(trial_exc),
                        }
                    )
            if not best_pack:
                raise ValueError("챔피언 도전 모드 전술 실험이 모두 실패했습니다.")

            replay = best_pack["replay"]  # type: ignore[assignment]
            score = best_pack["score"]  # type: ignore[assignment]
            best_config = best_pack["config"] if isinstance(best_pack.get("config"), dict) else {}
            best_group = best_pack["group"] if isinstance(best_pack.get("group"), dict) else {}
            contestant_symbols = [str(item) for item in best_pack.get("symbols", contestant_symbols)]  # type: ignore[union-attr]
            selection_reason = str(best_group.get("label") or selection_reason)
            fast_window = int(best_pack.get("fast_window") or contestant.get("fast", 12) or 12)
            slow_window = int(best_pack.get("slow_window") or contestant.get("slow", 32) or 32)
            window_adjusted = bool(best_pack.get("window_adjusted"))
            selected_symbols_by_contestant[str(contestant.get("id") or contestant.get("name"))] = contestant_symbols
            personal_best = personal_bests.get(str(contestant.get("id") or "")) or {}
            current_return = _number(replay.get("total_return_pct"))
            best_before = _number(personal_best.get("return_pct"))
            monte_carlo_stress = _ai_tournament_monte_carlo_stress(
                replay,
                iterations=300,
                seed=f"{source}-{contestant.get('id')}-{start_date}-{end_date}-{season_index}",
            )
            stress_retraining_plan = _ai_tournament_stress_retraining_plan(
                best_config,
                monte_carlo_stress,
            )
            learning_control_baseline_row: dict[str, object] | None = None
            learning_control_error = ""
            learning_provenance = (
                best_config.get("_learning_provenance")
                if isinstance(best_config.get("_learning_provenance"), dict)
                else {}
            )
            if learning_provenance.get("adaptive"):
                baseline_config = (
                    best_pack.get("baseline_config")
                    if isinstance(best_pack.get("baseline_config"), dict)
                    else {}
                )
                try:
                    baseline_fast, baseline_slow, baseline_window_adjusted = _ai_tournament_windows_for_period(
                        start_date,
                        end_date,
                        int(baseline_config.get("fast", contestant.get("fast", 12)) or 12),
                        int(baseline_config.get("slow", contestant.get("slow", 32)) or 32),
                    )
                    baseline_replay = run_historical_paper_replay(
                        symbols=contestant_symbols,
                        start_date=start_date,
                        end_date=end_date,
                        fast=baseline_fast,
                        slow=baseline_slow,
                        initial_cash=initial_cash,
                        allocation_pct=float(baseline_config.get("allocation", contestant.get("allocation_pct", 25)) or 25),
                        max_positions=int(baseline_config.get("max_positions", contestant.get("max_positions", 4)) or 4),
                        source=f"{source}-{contestant.get('id')}-learning-counterfactual",
                        strategy_mode=str(baseline_config.get("strategy", contestant.get("strategy_mode") or "ma_cross")),
                        stop_loss_pct=float(baseline_config.get("stop", contestant.get("stop_loss_pct", 8)) or 8),
                        take_profit_pct=float(baseline_config.get("take", contestant.get("take_profit_pct", 0)) or 0),
                        holding_limit_days=int(baseline_config.get("hold", contestant.get("holding_limit_days", 0)) or 0),
                        cycles_per_day=24,
                        allow_simulated_fallback=allow_simulated_fallback,
                        min_bars=max(8, min(40, baseline_slow + 4)),
                        persist_detail=False,
                        commission_bps=float(cost_profile.get("commission_bps", DEFAULT_PAPER_COMMISSION_BPS)),
                        slippage_bps=float(cost_profile.get("slippage_bps", DEFAULT_PAPER_SLIPPAGE_BPS)),
                        kr_sell_tax_bps=float(cost_profile.get("kr_sell_tax_bps", DEFAULT_PAPER_KR_SELL_TAX_BPS)),
                        fx_conversion_spread_bps=float(
                            cost_profile.get(
                                "fx_conversion_spread_bps",
                                DEFAULT_PAPER_FX_SPREAD_BPS,
                            )
                        ),
                        replay_data_bundle=shared_replay_data_bundle,
                    )
                    learning_control_baseline_row = {
                        "contestant_id": contestant.get("id"),
                        "selected_symbols": contestant_symbols,
                        "strategy_mode": baseline_config.get("strategy") or contestant.get("strategy_mode"),
                        "fast_window": baseline_fast,
                        "slow_window": baseline_slow,
                        "window_adjusted_for_contest_period": baseline_window_adjusted,
                        "actual_start_date": baseline_replay.get("actual_start_date"),
                        "actual_end_date": baseline_replay.get("actual_end_date"),
                        "total_return_pct": baseline_replay.get("total_return_pct"),
                        "max_drawdown_pct": baseline_replay.get("max_drawdown_pct"),
                        "win_rate_pct": baseline_replay.get("win_rate_pct"),
                        "trade_count": baseline_replay.get("trade_count"),
                        "cost_model": baseline_replay.get("cost_model", {}),
                        "transaction_cost_audit": baseline_replay.get("transaction_cost_audit", {}),
                        "price_currency_unit_audit": baseline_replay.get("price_currency_unit_audit", {}),
                        "execution_timing_model": baseline_replay.get("execution_timing_model", {}),
                        "data_coverage": baseline_replay.get("data_coverage", {}),
                        "return_display_basis": baseline_replay.get("return_display_basis"),
                        "return_reconciliation_summary": baseline_replay.get("trade_journal_reconciliation_summary", {}),
                        "selected_challenge_config": {
                            "strategy_mode": baseline_config.get("strategy"),
                            "allocation_pct": baseline_config.get("allocation"),
                            "max_positions": baseline_config.get("max_positions"),
                            "stop_loss_pct": baseline_config.get("stop"),
                            "take_profit_pct": baseline_config.get("take"),
                            "holding_limit_days": baseline_config.get("hold"),
                        },
                    }
                except Exception as control_exc:
                    learning_control_error = f"{type(control_exc).__name__}: {control_exc}"[:300]
            result = {
                "contestant_id": contestant.get("id"),
                "name": contestant.get("name"),
                "persona_name": contestant.get("persona_name"),
                "call_sign": contestant.get("call_sign"),
                "profile": contestant.get("profile"),
                "display_name": f"{contestant.get('persona_name')} · {contestant.get('name')}" if contestant.get("persona_name") else contestant.get("name"),
                "role": contestant.get("role"),
                "strategy_name": best_config.get("label") or contestant.get("strategy_name"),
                "strategy_mode": best_config.get("strategy") or contestant.get("strategy_mode"),
                "strategy_candidate_origin": best_config.get("candidate_origin"),
                "strategy_generation_id": best_config.get("strategy_generation_id"),
                "strategy_horizon": best_config.get("strategy_horizon"),
                "strategy_horizon_mix": best_config.get("strategy_horizon_mix", {}),
                "training_arena": dict(best_config.get("training_arena") or training_arena),
                "agent_strategy_autonomy": bool(best_config.get("agent_strategy_autonomy")),
                "autonomous_choice_basis": best_config.get("autonomous_choice_basis"),
                "role_strategy_restriction": bool(best_config.get("role_strategy_restriction", False)),
                "master_strategy_proxy": bool(best_config.get("master_strategy_proxy")),
                "stage2_requirements": best_config.get("stage2_requirements", []),
                "indicator_recipe": best_config.get("indicator_recipe", []),
                "research_indicator_hypothesis": best_config.get("research_indicator_hypothesis", []),
                "strategy_memory_source_record_id": best_config.get("strategy_memory_source_record_id"),
                "strategy_library_candidate_count": best_config.get("strategy_library_candidate_count"),
                "strategy_library_tested_count": best_config.get("strategy_library_tested_count"),
                "strategy_library_origins": best_config.get("strategy_library_origins", []),
                "risk_limit_pct": contestant.get("risk_limit_pct"),
                "selected_symbols": contestant_symbols,
                "selection_reason": selection_reason,
                "symbol_selection_mode": symbol_selection_mode,
                "fast_window": fast_window,
                "slow_window": slow_window,
                "window_adjusted_for_contest_period": window_adjusted,
                "rank": 0,
                "replay_id": replay.get("id"),
                "actual_start_date": replay.get("actual_start_date"),
                "actual_end_date": replay.get("actual_end_date"),
                "actual_horizon_years": replay.get("actual_horizon_years"),
                "data_coverage": replay.get("data_coverage", {}),
                "replay_data_bundle_evidence": replay.get("replay_data_bundle_evidence", {}),
                "final_equity": replay.get("final_equity"),
                "initial_cash": replay.get("initial_cash"),
                "total_return_pct": replay.get("total_return_pct"),
                "capital_growth_goal": _ai_staff_capital_goal_progress(
                    replay.get("total_return_pct"),
                    replay.get("initial_cash") or initial_cash,
                ),
                "max_drawdown_pct": replay.get("max_drawdown_pct"),
                "win_rate_pct": replay.get("win_rate_pct"),
                "trade_count": replay.get("trade_count"),
                "closed_trade_count": replay.get("closed_trade_count"),
                "average_win_pct": replay.get("average_win_pct"),
                "average_loss_pct": replay.get("average_loss_pct"),
                "cost_model": replay.get("cost_model", {}),
                "transaction_cost_audit": replay.get("transaction_cost_audit", {}),
                "price_currency_unit_audit": replay.get("price_currency_unit_audit", {}),
                "execution_timing_model": replay.get("execution_timing_model", {}),
                "total_transaction_cost": replay.get("total_transaction_cost"),
                "transaction_cost_pct_of_initial_cash": replay.get("transaction_cost_pct_of_initial_cash"),
                "top_trades": replay.get("trade_journal_top10", [])[:3],
                "bottom_trades": replay.get("trade_journal_bottom10", [])[:3],
                "return_reconciliation_summary": replay.get("trade_journal_reconciliation_summary", {}),
                "monte_carlo_stress": monte_carlo_stress,
                "stress_retraining_plan": stress_retraining_plan,
                "score_detail": score,
                "score": score.get("ranking_score", score.get("score")),
                "score_mode": "champion_challenge_return_first" if challenge_mode else "risk_adjusted",
                "personal_best_before": personal_best,
                "personal_best_before_pct": round(best_before, 2),
                "personal_best_gap_pct": round(current_return - best_before, 2),
                "personal_record_broken": bool(current_return > best_before),
                "challenge_mode": bool(challenge_mode),
                "challenge_trial_count": len(trial_summaries),
                "learning_provenance": dict(best_config.get("_learning_provenance") or {}),
                "selected_challenge_config": {
                    "group_label": best_group.get("label"),
                    "strategy_label": best_config.get("label"),
                    "strategy_mode": best_config.get("strategy"),
                    "candidate_origin": best_config.get("candidate_origin"),
                    "strategy_generation_id": best_config.get("strategy_generation_id"),
                    "strategy_horizon": best_config.get("strategy_horizon"),
                    "strategy_horizon_mix": best_config.get("strategy_horizon_mix", {}),
                    "training_arena": dict(best_config.get("training_arena") or training_arena),
                    "agent_strategy_autonomy": bool(best_config.get("agent_strategy_autonomy")),
                    "autonomous_choice_basis": best_config.get("autonomous_choice_basis"),
                    "role_strategy_restriction": bool(best_config.get("role_strategy_restriction", False)),
                    "master_strategy_proxy": bool(best_config.get("master_strategy_proxy")),
                    "stage2_requirements": best_config.get("stage2_requirements", []),
                    "indicator_recipe": best_config.get("indicator_recipe", []),
                    "research_indicator_hypothesis": best_config.get("research_indicator_hypothesis", []),
                    "research_stage_required": bool(best_config.get("research_stage_required")),
                    "strategy_memory_source_record_id": best_config.get("strategy_memory_source_record_id"),
                    "allocation_pct": best_config.get("allocation"),
                    "max_positions": best_config.get("max_positions"),
                    "stop_loss_pct": best_config.get("stop"),
                    "take_profit_pct": best_config.get("take"),
                    "holding_limit_days": best_config.get("hold"),
                },
                "challenge_trials": sorted(
                    trial_summaries,
                    key=lambda row: _number(row.get("ranking_score")),
                    reverse=True,
                )[:6],
                "benchmark_gap_pct": (
                    round(_number(replay.get("total_return_pct")) - float(benchmark_return_pct), 2)
                    if benchmark_return_pct is not None
                    else None
                ),
                "summary": replay.get("summary"),
            }
            if learning_provenance.get("adaptive"):
                source_ids = (
                    learning_provenance.get("verified_source_record_ids")
                    if isinstance(learning_provenance.get("verified_source_record_ids"), list)
                    else []
                )
                if learning_control_baseline_row:
                    result["learning_counterfactual_control"] = _build_ai_staff_learning_counterfactual_control(
                        source_record_id=str(source_ids[0] if source_ids else ""),
                        baseline_row=learning_control_baseline_row,
                        target_row=result,
                    )
                else:
                    result["learning_counterfactual_control"] = {
                        "schema": "codexstock_ai_staff_learning_counterfactual_v1",
                        "status": "control_run_failed",
                        "source_record_id": str(source_ids[0] if source_ids else ""),
                        "contestant_id": contestant.get("id"),
                        "error": learning_control_error or "counterfactual baseline unavailable",
                        "live_order_allowed": False,
                    }
            results.append(result)
        except Exception as exc:
            errors.append({
                "contestant_id": contestant.get("id"),
                "name": contestant.get("name"),
                "persona_name": contestant.get("persona_name"),
                "call_sign": contestant.get("call_sign"),
                "profile": contestant.get("profile"),
                "display_name": contestant.get("display_name"),
                "selected_symbols": selected_symbols_by_contestant.get(str(contestant.get("id") or contestant.get("name")), []),
                "error": str(exc),
            })

    bias_audit = _ai_tournament_bias_audit(
        symbols=selected_symbols,
        start_date=start_date,
        end_date=end_date,
        symbol_selection_mode=symbol_selection_mode,
        universe_dataset_id=universe_dataset_id,
    )
    universe_dataset_id = str(bias_audit.get("universe_dataset_id") or "") or None
    for row in results:
        row["bias_audit"] = bias_audit
        control = row.get("learning_counterfactual_control") if isinstance(row.get("learning_counterfactual_control"), dict) else {}
        baseline_result = control.get("baseline_result") if isinstance(control.get("baseline_result"), dict) else {}
        if baseline_result:
            baseline_result["bias_audit"] = bias_audit
            control["evidence_hash"] = _ai_staff_learning_counterfactual_hash(control, row)
    ranked = sorted(results, key=lambda row: _number(row.get("score")), reverse=True)
    for row in ranked:
        gate = _ai_tournament_competition_gate(row)
        row["competition_gate"] = gate
        row["competition_score"] = round(
            _number(row.get("score"))
            + _number(gate.get("confidence_score")) * 0.16
            - len(gate.get("failed_checks", []) if isinstance(gate.get("failed_checks"), list) else []) * 2.5,
            2,
        )
    ranked = sorted(ranked, key=lambda row: (_number(row.get("competition_score")), _number(row.get("score"))), reverse=True)
    for rank, row in enumerate(ranked, start=1):
        row["rank"] = rank
    champion = ranked[0] if ranked else {}
    shadow_validation: dict[str, object] = {}
    walk_forward: dict[str, object] = {}
    if champion:
        _attach_ai_tournament_walk_forward_validations(
            ranked,
            bias_audit=bias_audit,
            start_date=start_date,
            end_date=end_date,
            initial_cash=initial_cash,
            base_symbols=selected_symbols,
            symbol_selection_mode=symbol_selection_mode,
            allow_simulated_fallback=allow_simulated_fallback,
            replay_cost_profile=cost_profile,
            source=source,
            replay_data_bundle=shared_replay_data_bundle,
        )
        walk_forward = champion.get("walk_forward") if isinstance(champion.get("walk_forward"), dict) else {}
        shadow_validation = _ai_tournament_shadow_validation(
            champion,
            start_date=start_date,
            end_date=end_date,
            initial_cash=initial_cash,
            allow_simulated_fallback=allow_simulated_fallback,
            source=source,
        )
        champion["shadow_validation"] = shadow_validation
        gate = champion.get("competition_gate") if isinstance(champion.get("competition_gate"), dict) else {}
        if gate:
            champion_price_audit = champion.get("price_currency_unit_audit") if isinstance(champion.get("price_currency_unit_audit"), dict) else {}
            gate["walk_forward_status"] = walk_forward.get("status")
            gate["walk_forward_passed"] = bool(walk_forward.get("passed"))
            promotion_blockers = []
            if not walk_forward.get("passed"):
                promotion_blockers.append("walk_forward_not_passed")
            if not bias_audit.get("passed"):
                promotion_blockers.append("survivorship_or_lookahead_not_validated")
            if bias_audit.get("promotion_allowed") is not True:
                promotion_blockers.append("universe_claim_scope_not_valid_for_live_stock_promotion")
            if not champion_price_audit.get("passed"):
                promotion_blockers.append("price_currency_unit_not_validated")
            gate["bias_audit_status"] = bias_audit.get("status")
            gate["bias_audit_passed"] = bool(bias_audit.get("passed"))
            gate["bias_claim_scope"] = bias_audit.get("claim_scope")
            gate["stock_selection_claim_allowed"] = bool(bias_audit.get("stock_selection_claim_allowed"))
            gate["price_currency_unit_status"] = "가격·통화·단위 검증 통과" if champion_price_audit.get("passed") else "가격·통화·단위 검증 필요"
            gate["price_currency_unit_passed"] = bool(champion_price_audit.get("passed"))
            gate["promotion_blocked"] = bool(promotion_blockers)
            gate["promotion_blockers"] = promotion_blockers
            gate["shadow_status"] = shadow_validation.get("status")
            gate["shadow_passed"] = bool(shadow_validation.get("passed"))
            if shadow_validation.get("ok") and not shadow_validation.get("passed") and gate.get("status") == "실전 승격 후보":
                gate["status"] = "블라인드 재검증 필요"
                gate["grade"] = "A"
                gate["message"] = f"{gate.get('message', '')} / 블라인드 검증은 추가 훈련 필요"
            if not walk_forward.get("passed") and gate.get("status") == "실전 승격 후보":
                gate["status"] = "워크포워드 재검증 필요"
                gate["grade"] = "A"
                gate["message"] = f"{gate.get('message', '')} / 미래 30% 검증 미통과"
            if not bias_audit.get("passed") and gate.get("status") == "실전 승격 후보":
                gate["status"] = "생존편향 검증 필요"
                gate["grade"] = "A"
                gate["message"] = f"{gate.get('message', '')} / point-in-time 유니버스 증거 없음"
            if not champion_price_audit.get("passed") and gate.get("status") == "실전 승격 후보":
                gate["status"] = "가격·통화·단위 검증 필요"
                gate["grade"] = "A"
                gate["message"] = f"{gate.get('message', '')} / 수정주가·환율·단위 증거 없음"
    bottom = ranked[-1] if ranked else {}
    lessons: list[str] = []
    if champion:
        lessons.append(
            f"{champion.get('display_name') or champion.get('name')}이 {champion.get('strategy_name')}로 우승했습니다. "
            f"수익률 {champion.get('total_return_pct')}%, MDD {champion.get('max_drawdown_pct')}%, "
            f"신뢰도 {(champion.get('competition_gate') or {}).get('confidence_score', 0)}점."
        )
        stress = champion.get("monte_carlo_stress") if isinstance(champion.get("monte_carlo_stress"), dict) else {}
        if stress:
            lessons.append(
                f"우승자 몬테카를로 스트레스: {stress.get('status')} / "
                f"플러스 {stress.get('positive_rate_pct')}%, P10 {stress.get('p10_return_pct')}%, "
                f"손상 {stress.get('ruin_rate_pct')}%."
            )
        if shadow_validation:
            lessons.append(
                f"우승자 블라인드 검증: {shadow_validation.get('status')} / "
                f"평균 {shadow_validation.get('avg_return_pct')}%, 최악 {shadow_validation.get('min_return_pct')}%, "
                f"최대 MDD {shadow_validation.get('max_mdd_pct')}%."
            )
        if walk_forward:
            oos = walk_forward.get("out_of_sample_result") if isinstance(walk_forward.get("out_of_sample_result"), dict) else {}
            lessons.append(
                f"우승자 워크포워드: {walk_forward.get('status')} / "
                f"미래 30% 수익률 {oos.get('return_pct', '-')}%, MDD {oos.get('max_drawdown_pct', '-')}%."
            )
    if bottom and champion and bottom.get("contestant_id") != champion.get("contestant_id"):
        lessons.append(
            f"{bottom.get('display_name') or bottom.get('name')}은 점수 {bottom.get('score')}로 최하위입니다. "
            "다음 시즌에는 손절·보유기간·후보 필터를 조정해야 합니다."
        )
    if benchmark_return_pct is not None and champion:
        gap = _number(champion.get("benchmark_gap_pct"))
        lessons.append(
            f"공개 실전투자대회 벤치마크 {benchmark_return_pct:.2f}% 대비 챔피언 격차는 {gap:+.2f}%p입니다."
        )
    record_breakers = [row for row in ranked if row.get("personal_record_broken")]
    if record_breakers:
        lessons.append(
            "자기 최고 기록 갱신: "
            + ", ".join(
                f"{row.get('display_name') or row.get('name')} {row.get('total_return_pct')}%"
                for row in record_breakers[:4]
            )
        )
    raw_contest_entries = _ai_tournament_contest_entries(contest_return_pcts, label=contest_label)
    champion_contest_entries = _ai_tournament_contest_entries_from_champions(contest_entries or [])
    contest_entries_for_rank = sorted(raw_contest_entries + champion_contest_entries, key=lambda row: _number(row.get("return_pct")), reverse=True)
    contest_rank = _ai_tournament_contest_ranks(ranked, contest_entries_for_rank, label=contest_label)
    if contest_rank.get("enabled") and champion:
        champion_rank = next((row for row in contest_rank.get("staff_ranks", []) if row.get("contestant_id") == champion.get("contestant_id")), {})
        if champion_rank:
            lessons.append(
                f"{contest_label} 수익률표 기준 챔피언 예상 순위는 {champion_rank.get('estimated_rank')}등/"
                f"{champion_rank.get('field_size')}명입니다."
            )
    next_rules = [
        "리그 우승 전략은 곧바로 실전에 투입하지 않고 다른 기간/다른 종목군으로 재검증합니다.",
        "몬테카를로 스트레스가 취약이면 수익률 1위라도 실전 승격을 보류합니다.",
        "학습 70%에서 고른 전술이 미래 30% 워크포워드를 통과하지 못하면 실전 승격을 차단합니다.",
        "수익률 1위라도 MDD가 리스크 한도를 넘으면 실전 후보 승격을 보류합니다.",
        "하위 AI의 실패 패턴은 다음 미니리그에서 손절·보유일·종목 필터 보정 후보로 등록합니다.",
    ]
    record = {
        "ok": bool(ranked),
        "id": f"AITOUR-{int(time.time() * 1000)}",
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "source": source,
        "league_type": "mini_league",
        "league_name": league_name,
        "challenge_mode": bool(challenge_mode),
        "challenge_trials_per_staff": challenge_trials,
        "challenge_goal": "공개 챔피언 수익률을 이기기 위해 직원별 후보군과 전술을 여러 번 실험한 뒤 최고 전술로 참가합니다." if challenge_mode else "",
        "start_date": start_date,
        "end_date": end_date,
        "initial_cash": round(initial_cash, 2),
        "symbols": selected_symbols,
        "contestant_count": len(contestants),
        "finished_count": len(ranked),
        "error_count": len(errors),
        "benchmark": {
            "label": "공개 실전투자대회 우승 수익률 벤치마크",
            "return_pct": benchmark_return_pct,
            "note": "공개 수익률만 비교 기준으로 사용하며 실제 우승자 매매내역 복제는 아닙니다.",
        } if benchmark_return_pct is not None else None,
        "contest_rank": contest_rank,
        "bias_audit": bias_audit,
        "universe_dataset_id": universe_dataset_id,
        "universe_dataset_resolution": bias_audit.get("universe_dataset_resolution"),
        "walk_forward": walk_forward,
        "shadow_validation": shadow_validation,
        "champion": champion,
        "rankings": ranked,
        "errors": errors,
        "lessons": lessons,
        "next_rules": next_rules,
        "safety": "AI 직원 미니리그는 과거장 Paper/Mock 전용입니다. 실전 주문 모듈을 호출하지 않습니다.",
        "symbol_selection_mode": symbol_selection_mode,
        "common_symbols": selected_symbols,
        "selected_symbols_by_contestant": selected_symbols_by_contestant,
        "training_arena": training_arena,
        "capital_growth_goal": {
            "start_capital_krw": round(initial_cash, 2),
            "target_capital_krw": 10_000_000_000,
            "target_multiple": round(10_000_000_000 / initial_cash, 8),
            "mode": "Paper training objective",
            "live_order_allowed": False,
        },
        "verified_learning_context_staff_count": len(learning_contexts),
        "verified_learning_policy": (
            "Only official, non-overlapping prior Paper evidence may alter a later Paper replay. "
            "Adaptation never authorizes a live order."
        ),
        "strategy_evolution_contract": {
            "schema": "codexstock_ai_staff_strategy_evolution_v1",
            "all_strategies_open_to_all_staff": True,
            "role_specific_strategy_library": False,
            "role_strategy_restriction": False,
            "verified_strategy_memory_reused": True,
            "generated_variants_rotated_between_seasons": True,
            "open_ended_generation": True,
            "fixed_total_strategy_limit": False,
            "tested_per_staff_per_season": challenge_trials,
            "generation_inputs": ["agent", "season", "verified_memory", "journal_diagnosis", "indicator_catalog"],
            "all_staff_indicator_catalog_available": True,
            "dynamic_shared_training_arena": True,
            "independent_agent_strategy_draft": True,
            "fixed_horizon_quota": False,
            "arena_modes": list(AI_STAFF_TRAINING_ARENAS),
            "personality_affects_preference_not_capability": True,
            "all_symbol_lenses_open_to_all_staff": True,
            "symbol_lens_modes": list(AI_STAFF_SYMBOL_SELECTION_LENSES),
            "ultimate_capital_goal_multiple": 1000,
            "master_strategy_proxies": [
                "buffett_quality_proxy",
                "graham_defensive_proxy",
                "lynch_growth_proxy",
                "turtle_55",
                "minervini_proxy",
                "canslim_proxy",
            ],
            "point_in_time_memory_only": True,
            "unverified_result_affects_score": False,
            "unverified_result_affects_live_candidate": False,
            "live_order_allowed": False,
        },
        "replay_cost_profile": cost_profile,
        "career_counted": bool(persist_tournament_record),
        "summary": (
            f"{league_name}: {start_date}~{end_date}, {len(selected_symbols)}종목, "
            f"{len(ranked)}명 완주. 챔피언 {champion.get('name', '-') if champion else '-'}."
        ),
    }
    if persist_tournament_record:
        _append_jsonl(AI_TOURNAMENT_FILE, record)
        sync_ai_staff_career_ledger(records=[record])
        _compact_jsonl(AI_TOURNAMENT_FILE, max_rows=300)
    response_record = _enrich_ai_tournament_record(record)
    JOURNAL.add(
        "AI_TOURNAMENT_MINI_LEAGUE",
        str(record["summary"]),
        {
            "id": record["id"],
            "official_champion": response_record.get("official_champion", {}),
            "reference_champion": response_record.get("reference_champion", {}),
            "record_score_allowed": response_record.get("record_score_allowed") is True,
        },
    )
    return response_record


def _enrich_ai_tournament_staff(row: dict[str, object], persona_lookup: dict[str, dict[str, object]]) -> dict[str, object]:
    result = dict(row)
    contestant_id = str(result.get("contestant_id") or "")
    persona = persona_lookup.get(contestant_id, {})
    persona_name = result.get("persona_name") or persona.get("persona_name")
    result["persona_name"] = persona_name
    result["call_sign"] = result.get("call_sign") or persona.get("call_sign")
    result["profile"] = result.get("profile") or persona.get("profile")
    if not result.get("display_name"):
        result["display_name"] = f"{persona_name} · {result.get('name')}" if persona_name and result.get("name") else result.get("name") or contestant_id
    return result


def _enrich_ai_tournament_record(
    record: dict[str, object],
    *,
    certified_index: dict[str, object] | None = None,
) -> dict[str, object]:
    if not isinstance(record, dict):
        return record
    persona_lookup = {str(row.get("id")): row for row in ai_tournament_contestants()}
    score_index = (
        certified_index
        if isinstance(certified_index, dict)
        else _historical_replay_certified_score_index()
    )
    result = dict(record)
    rankings = result.get("rankings")
    if isinstance(rankings, list):
        enriched_rankings: list[dict[str, object]] = []
        for raw_row in rankings:
            if not isinstance(raw_row, dict):
                continue
            row = _enrich_ai_tournament_staff(raw_row, persona_lookup)
            claim = _ai_tournament_official_claim_state(
                row,
                certified_index=score_index,
            )
            row["reference_rank"] = row.get("rank")
            row["reference_score"] = row.get("score")
            row["reference_total_return_pct"] = row.get("total_return_pct")
            row["score_allowed"] = claim.get("eligible") is True
            row["official_claim"] = claim
            row["official_rank"] = None
            row["official_score"] = None
            row["official_total_return_pct"] = claim.get("official_total_return_pct")
            row["official_replay_id"] = claim.get("certified_replay_id")
            if claim.get("eligible") is True:
                replacement_metrics = {
                    "total_return_pct": claim.get("official_total_return_pct"),
                    "max_drawdown_pct": claim.get("official_max_drawdown_pct"),
                    "win_rate_pct": claim.get("official_win_rate_pct"),
                    "trade_count": claim.get("official_trade_count"),
                    "average_win_pct": claim.get("official_average_win_pct"),
                    "average_loss_pct": claim.get("official_average_loss_pct"),
                }
                official_score = _ai_tournament_score(
                    replacement_metrics,
                    float(row.get("risk_limit_pct") or 15),
                )
                row["official_score"] = official_score.get("score")
                row["official_score_detail"] = official_score
            enriched_rankings.append(row)

        record_score_allowed = bool(enriched_rankings) and all(
            row.get("score_allowed") is True for row in enriched_rankings
        )
        official_rankings: list[dict[str, object]] = []
        if record_score_allowed:
            official_rankings = sorted(
                enriched_rankings,
                key=lambda row: _number(row.get("official_score")),
                reverse=True,
            )
            for rank, row in enumerate(official_rankings, start=1):
                row["official_rank"] = rank
        reference_champion = result.get("champion") if isinstance(result.get("champion"), dict) else {}
        result["reference_champion"] = (
            _enrich_ai_tournament_staff(reference_champion, persona_lookup)
            if reference_champion
            else {}
        )
        result["record_score_allowed"] = record_score_allowed
        result["score_blocked_count"] = sum(
            1 for row in enriched_rankings if row.get("score_allowed") is not True
        )
        result["score_certified_count"] = len(enriched_rankings) - int(result["score_blocked_count"])
        result["official_champion"] = official_rankings[0] if official_rankings else {}
        result["champion"] = official_rankings[0] if official_rankings else {}
        result["rankings"] = enriched_rankings
        result["score_gate"] = {
            "schema": "codexstock_ai_tournament_record_score_gate_v1",
            "score_allowed": record_score_allowed,
            "required_contestant_count": len(enriched_rankings),
            "certified_contestant_count": result["score_certified_count"],
            "blocked_contestant_count": result["score_blocked_count"],
            "certified_milestone": score_index.get("verified_through_count"),
            "policy": "All contestants must have deep-certified replacement evidence before an official rank or champion is issued.",
            "promotion_allowed": False,
            "live_order_allowed": False,
        }
    errors = result.get("errors")
    if isinstance(errors, list):
        result["errors"] = [
            _enrich_ai_tournament_staff(row, persona_lookup) if isinstance(row, dict) else row
            for row in errors
        ]
    return result


def _costed_long_horizon_gate(staff: dict[str, object]) -> dict[str, object]:
    evaluation = staff.get("goal_evaluation") if isinstance(staff.get("goal_evaluation"), dict) else {}
    evidence = staff.get("performance_evidence") if isinstance(staff.get("performance_evidence"), dict) else {}
    evidence_ok = bool(evidence.get("passed"))
    cost_ok = bool(evaluation.get("cost_tax_slippage_validated")) and evidence_ok
    cagr_ok = bool(evaluation.get("cagr_target_met"))
    mdd_ok = bool(evaluation.get("mdd_limit_met"))
    benchmark_ok = bool(evaluation.get("benchmark_excess_target_met"))
    checks = [
        {
            "ok": cost_ok,
            "label": "비용 검증",
            "detail": "수수료·세금·슬리피지 반영" if cost_ok else "비용 검증 필요",
            "weight": 25,
        },
        {
            "ok": cagr_ok,
            "label": "CAGR 목표",
            "detail": f"{_number(staff.get('cagr_pct')):.2f}% / 목표 20.00%",
            "weight": 25,
        },
        {
            "ok": mdd_ok,
            "label": "MDD 한도",
            "detail": f"{abs(_number(staff.get('max_drawdown_pct'))):.2f}% / 한도 25.00%",
            "weight": 25,
        },
        {
            "ok": benchmark_ok,
            "label": "SPY 초과 CAGR",
            "detail": f"{_number(evaluation.get('excess_cagr_pctp')):.2f}%p / 목표 8.00%p",
            "weight": 25,
        },
    ]
    failed = [row for row in checks if not row.get("ok")]
    confidence = round(sum(_number(row.get("weight")) for row in checks if row.get("ok")), 1)
    passed = bool(evaluation.get("production_goal_pass"))
    return {
        "grade": "S" if passed else "C",
        "status": "실전 승격 후보" if passed else "실전 보류",
        "confidence_score": confidence,
        "checks": checks,
        "failed_checks": failed,
        "goal_evaluation": evaluation,
        "performance_evidence": evidence,
        "message": "비용 반영 장기 검증 통과" if passed else f"비용 반영 장기 검증: 실패 체크 {len(failed)}개",
        "basis": "strict_net_costed_actual_horizon_benchmark_evidence_contract",
    }


def _overlay_costed_long_horizon_record(
    record: dict[str, object],
    benchmark: dict[str, object],
) -> dict[str, object]:
    if (
        str(record.get("source") or "") != "ai-staff-2000-2026-benchmark"
        or not benchmark.get("ok")
        or benchmark.get("run_once_key") != "ai-staff-2000-2026-evidence-v4"
        or str(record.get("start_date") or "") != str(benchmark.get("start_date") or "")
        or str(record.get("end_date") or "") != str(benchmark.get("end_date") or "")
    ):
        return record
    original_rankings = record.get("rankings") if isinstance(record.get("rankings"), list) else []
    official_staff = benchmark.get("staff") if isinstance(benchmark.get("staff"), list) else []
    if not original_rankings or not official_staff:
        return record

    official_by_id = {
        str(row.get("contestant_id") or ""): row
        for row in official_staff
        if isinstance(row, dict) and row.get("contestant_id")
    }
    overlaid: list[dict[str, object]] = []
    for original in original_rankings:
        if not isinstance(original, dict):
            continue
        official = official_by_id.get(str(original.get("contestant_id") or ""))
        if not official:
            continue
        row = dict(original)
        for field in (
            "rank",
            "initial_cash",
            "final_equity",
            "total_return_pct",
            "max_drawdown_pct",
            "win_rate_pct",
            "trade_count",
            "score",
            "competition_score",
            "benchmark_gap_pct",
            "competition_gate",
            "monte_carlo_stress",
            "top_trades",
            "bottom_trades",
        ):
            if field in row:
                row[f"gross_{field}"] = row.get(field)
        for field in (
            "rank",
            "strategy_name",
            "strategy_mode",
            "initial_cash",
            "final_equity",
            "total_return_pct",
            "cagr_pct",
            "max_drawdown_pct",
            "trade_count",
            "win_rate_pct",
            "cost_model",
            "transaction_cost_audit",
            "total_transaction_cost",
            "transaction_cost_pct_of_initial_cash",
            "return_claim_status",
            "return_claim_blocked",
            "actual_start_date",
            "actual_end_date",
            "actual_horizon_years",
            "data_coverage",
            "execution_timing_model",
            "performance_evidence",
            "official_total_return_pct",
            "official_cagr_pct",
            "performance_claim_status",
            "performance_confidence_score",
            "goal_evaluation",
            "price_currency_unit_audit",
        ):
            if field in official:
                row[field] = official.get(field)
        evaluation = official.get("goal_evaluation") if isinstance(official.get("goal_evaluation"), dict) else {}
        row["benchmark_cagr_gap_pctp"] = evaluation.get("excess_cagr_pctp")
        row["bias_audit"] = _ai_tournament_bias_audit(
            symbols=[str(symbol) for symbol in benchmark.get("symbols", [])] if isinstance(benchmark.get("symbols"), list) else [],
            start_date=str(benchmark.get("start_date") or record.get("start_date") or ""),
            end_date=str(benchmark.get("end_date") or record.get("end_date") or ""),
            symbol_selection_mode=str(record.get("symbol_selection_mode") or "common"),
            universe_dataset_id=str(record.get("universe_dataset_id") or "") or None,
        )
        row["competition_gate"] = _costed_long_horizon_gate(official)
        row["monte_carlo_stress"] = {}
        row["top_trades"] = []
        row["bottom_trades"] = []
        row["score"] = None
        row["competition_score"] = None
        row["benchmark_gap_pct"] = None
        evidence = official.get("performance_evidence") if isinstance(official.get("performance_evidence"), dict) else {}
        row["return_display_basis"] = (
            "official_net_costed_actual_horizon"
            if evidence.get("passed")
            else "reference_only_unverified"
        )
        row["official_metric_label"] = "비용 반영 총수익률"
        row["superseded_gross_result"] = True
        row["performance_claim_label"] = "official" if evidence.get("passed") else "reference_only"
        row["trade_detail_status"] = "costed_run_detail_not_persisted"
        overlaid.append(row)

    if not overlaid:
        return record
    overlaid.sort(key=lambda row: (int(_number(row.get("rank"))) or 999, -_number(row.get("total_return_pct"))))
    for rank, row in enumerate(overlaid, start=1):
        row["rank"] = rank
    result = dict(record)
    result["gross_champion"] = record.get("champion")
    result["gross_summary"] = record.get("summary")
    result["rankings"] = overlaid
    result["champion"] = overlaid[0]
    result["finished_count"] = len(overlaid)
    result["costed_result_overlay_applied"] = True
    result["gross_record_preserved"] = True
    result["result_basis"] = (
        "official_net_costed_actual_horizon"
        if all(
            isinstance(row.get("performance_evidence"), dict)
            and row.get("performance_evidence", {}).get("passed")
            for row in overlaid
        )
        else "reference_only_unverified"
    )
    result["run_once_key"] = benchmark.get("run_once_key")
    result["costed_benchmark_id"] = benchmark.get("league_record_id")
    result["costed_result_generated_at"] = benchmark.get("generated_at")
    result["benchmark"] = benchmark.get("benchmark")
    result["goal_contract"] = benchmark.get("goal_contract")
    result["limitations"] = benchmark.get("limitations")
    result["display_note"] = "과거 비용 미반영 원장은 감사용으로 보존하고, 화면은 수수료·세금·슬리피지 반영 결과를 표시합니다."
    result["summary"] = (
        f"비용 반영 2000~2026 장기 검증: {len(overlaid)}명 완주. "
        f"1위 {overlaid[0].get('display_name') or overlaid[0].get('name')}, "
        f"총수익률 {overlaid[0].get('total_return_pct')}%, CAGR {overlaid[0].get('cagr_pct')}%."
    )
    return result


def latest_ai_tournaments(limit: int = 10) -> list[dict[str, object]]:
    rows = list(reversed(_read_jsonl(AI_TOURNAMENT_FILE, limit=max(1, min(int(limit or 10), 100)))))
    long_horizon = load_ai_staff_long_horizon_benchmark()
    certified_index = _historical_replay_certified_score_index()
    return [
        _overlay_costed_long_horizon_record(
            _enrich_ai_tournament_record(row, certified_index=certified_index),
            long_horizon,
        )
        for row in rows
    ]


def latest_ai_tournament_challenge(limit: int = 20) -> dict[str, object]:
    for row in latest_ai_tournaments(limit=max(1, min(int(limit or 20), 100))):
        source = str(row.get("source") or "").lower()
        league_name = str(row.get("league_name") or "").lower()
        if bool(row.get("challenge_mode")) or "challenge" in source or "champion" in source or "champion" in league_name:
            return row
    return {}


def _ai_tournament_challenge_summary_from_record(record: dict[str, object]) -> dict[str, object]:
    champion = record.get("champion") if isinstance(record.get("champion"), dict) else {}
    contest_rank = record.get("contest_rank") if isinstance(record.get("contest_rank"), dict) else {}
    entries = contest_rank.get("entries") if isinstance(contest_rank.get("entries"), list) else []
    contest_entry = entries[0] if entries and isinstance(entries[0], dict) else {}
    staff_ranks = contest_rank.get("staff_ranks") if isinstance(contest_rank.get("staff_ranks"), list) else []
    champion_rank = next(
        (
            row for row in staff_ranks
            if isinstance(row, dict) and row.get("contestant_id") == champion.get("contestant_id")
        ),
        {},
    )
    return {
        "id": record.get("id"),
        "generated_at": record.get("generated_at"),
        "contest_name": contest_entry.get("contest_name") or record.get("league_name"),
        "league": contest_entry.get("league"),
        "period": f"{record.get('start_date', '-')}~{record.get('end_date', '-')}",
        "trial_count": record.get("challenge_trials_per_staff") or champion.get("challenge_trial_count"),
        "winner": champion.get("display_name") or champion.get("name"),
        "winner_return_pct": champion.get("total_return_pct"),
        "winner_strategy": champion.get("strategy_name"),
        "estimated_rank": champion_rank.get("estimated_rank"),
        "field_size": champion_rank.get("field_size"),
        "champion_target_return_pct": contest_entry.get("return_pct"),
        "record_broken": champion.get("personal_record_broken"),
    }


def load_ai_tournament_challenge_state() -> dict[str, object]:
    now = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
    loaded_from_file = False
    state: dict[str, object] = {
        "ok": True,
        "enabled": True,
        "mode": "champion_challenge_training",
        "interval_seconds": 5_400,
        "trial_count": 3,
        "run_count": 0,
        "updated_at": now,
        "description": "AI 직원들이 공개 실전투자대회 챔피언 조건으로 주기적으로 붙고, 전술 실험/자기기록/회의 기록을 남깁니다.",
    }
    try:
        if AI_TOURNAMENT_CHALLENGE_STATE_FILE.exists():
            loaded = json.loads(AI_TOURNAMENT_CHALLENGE_STATE_FILE.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                state.update(loaded)
                loaded_from_file = True
    except Exception as exc:
        state["load_error"] = str(exc)
    try:
        interval = max(1_800, int(state.get("interval_seconds", 5_400) or 5_400))
    except Exception:
        interval = 5_400
    try:
        trials = max(1, min(int(state.get("trial_count", 3) or 3), 6))
    except Exception:
        trials = 3
    state["interval_seconds"] = interval
    state["trial_count"] = trials
    last_run_at = state.get("last_run_at")
    if not last_run_at and not loaded_from_file:
        latest_record = latest_ai_tournament_challenge(limit=50)
        latest_at = latest_record.get("generated_at") if isinstance(latest_record, dict) else None
        if latest_at:
            last_run_at = latest_at
            state["last_status"] = "WAITING"
            state["last_run_at"] = latest_at
            state["last_id"] = latest_record.get("id")
            state["last_result"] = _ai_tournament_challenge_summary_from_record(latest_record)
            state["run_count"] = max(1, int(state.get("run_count", 0) or 0))
            state["seeded_from_latest_record"] = True
    if last_run_at:
        age = _iso_age_seconds(last_run_at)
        state["next_due_at"] = _capital_challenge_next_due(last_run_at, interval)
        state["seconds_until_due"] = max(0, interval - int(age or 0))
    else:
        state["next_due_at"] = now
        state["seconds_until_due"] = 0
    return state


def save_ai_tournament_challenge_state(state: dict[str, object]) -> dict[str, object]:
    state = dict(state or {})
    state["ok"] = True
    state["updated_at"] = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
    AI_TOURNAMENT_CHALLENGE_STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
    AI_TOURNAMENT_CHALLENGE_STATE_FILE.write_text(json.dumps(state, ensure_ascii=False, indent=2, sort_keys=True), encoding="utf-8")
    return state


def run_autonomous_ai_tournament_challenge_if_due(
    source: str = "ai-daemon-champion-challenge",
    force: bool = False,
    interval_seconds: int | None = None,
) -> dict[str, object]:
    state = load_ai_tournament_challenge_state()
    focus = build_operating_focus()
    if not force and not focus.get("large_batch_jobs_allowed"):
        return {
            "ok": True,
            "status": "DEFERRED_TO_MARKET_CLOSED_DAY",
            "state": state,
            "schedule": focus.get("large_batch_schedule"),
            "message": "왕중왕전 대형 훈련은 주말·공휴일로 연기했습니다.",
        }
    if interval_seconds is not None:
        state["interval_seconds"] = max(1_800, int(interval_seconds))
    interval = max(1_800, int(state.get("interval_seconds", 5_400) or 5_400))
    if not bool(state.get("enabled", True)):
        state["last_status"] = "DISABLED"
        save_ai_tournament_challenge_state(state)
        return {"ok": True, "status": "DISABLED", "state": state, "message": "챔피언 도전 자동훈련이 꺼져 있습니다."}
    last_run_at = state.get("last_run_at")
    age = _iso_age_seconds(last_run_at)
    if not force and age is not None and age < interval:
        state["last_status"] = "WAITING"
        state["next_due_at"] = _capital_challenge_next_due(last_run_at, interval)
        state["seconds_until_due"] = max(0, interval - int(age or 0))
        save_ai_tournament_challenge_state(state)
        return {
            "ok": True,
            "status": "WAITING",
            "state": state,
            "latest": state.get("last_result", {}),
            "message": f"다음 챔피언 도전 훈련까지 약 {state['seconds_until_due']}초 남았습니다.",
        }
    entries = load_ai_tournament_champions()
    if not entries:
        state["last_status"] = "NO_CHAMPIONS"
        save_ai_tournament_challenge_state(state)
        return {"ok": False, "status": "NO_CHAMPIONS", "state": state, "message": "비교할 챔피언 데이터가 없습니다."}
    run_count = int(state.get("run_count", 0) or 0)
    selected = entries[run_count % len(entries)]
    contest_id = str(selected.get("contest_id") or "")
    market = str(selected.get("market") or "").upper()
    champion_entries = [
        row for row in entries
        if str(row.get("contest_id") or "") == contest_id and (not market or str(row.get("market") or "").upper() == market)
    ] or [selected]
    trials = max(1, min(int(state.get("trial_count", 3) or 3), 6))
    start_date = str(selected.get("start_date") or "2024-01-01")
    end_date = str(selected.get("end_date") or today_kst())
    initial_cash = float(selected.get("initial_cash") or 100_000_000.0)
    try:
        result = run_ai_mini_league(
            league_name=f"AI 챔피언 도전 자동훈련 · {selected.get('contest_name') or '실전투자대회'}",
            start_date=start_date,
            end_date=end_date,
            initial_cash=initial_cash,
            symbols=None,
            contest_entries=champion_entries,
            contest_label="실전투자대회 챔피언",
            symbol_selection_mode="independent",
            season_index=run_count,
            allow_simulated_fallback=False,
            challenge_mode=True,
            challenge_trials=trials,
            source=source,
        )
        champion = result.get("champion") if isinstance(result.get("champion"), dict) else {}
        contest_rank = result.get("contest_rank") if isinstance(result.get("contest_rank"), dict) else {}
        staff_ranks = contest_rank.get("staff_ranks") if isinstance(contest_rank.get("staff_ranks"), list) else []
        champion_rank = next((row for row in staff_ranks if isinstance(row, dict) and row.get("contestant_id") == champion.get("contestant_id")), {})
        summary = {
            "id": result.get("id"),
            "generated_at": result.get("generated_at"),
            "contest_name": selected.get("contest_name"),
            "league": selected.get("league"),
            "period": f"{start_date}~{end_date}",
            "trial_count": trials,
            "winner": champion.get("display_name") or champion.get("name"),
            "winner_return_pct": champion.get("total_return_pct"),
            "winner_strategy": champion.get("strategy_name"),
            "estimated_rank": champion_rank.get("estimated_rank"),
            "field_size": champion_rank.get("field_size"),
            "champion_target_return_pct": selected.get("return_pct"),
            "record_broken": champion.get("personal_record_broken"),
        }
        now = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
        state.update(
            {
                "last_status": "RAN" if result.get("ok") else "FAILED",
                "last_run_at": now,
                "last_id": result.get("id"),
                "last_result": summary,
                "last_champion_id": selected.get("id"),
                "last_champion_name": selected.get("champion_name"),
                "run_count": run_count + 1,
                "next_due_at": _capital_challenge_next_due(now, interval),
                "seconds_until_due": interval,
                "last_error": "",
            }
        )
        save_ai_tournament_challenge_state(state)
        return {"ok": bool(result.get("ok")), "status": "RAN", "state": state, "result": result, "summary": summary}
    except Exception as exc:
        now = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
        state.update(
            {
                "last_status": "ERROR",
                "last_run_at": now,
                "last_error": str(exc),
                "run_count": run_count,
                "next_due_at": _capital_challenge_next_due(now, max(1_800, interval // 2)),
                "seconds_until_due": max(1_800, interval // 2),
            }
        )
        save_ai_tournament_challenge_state(state)
        return {"ok": False, "status": "ERROR", "state": state, "error": str(exc)}


