def _load_ai_staff_learning_counterfactual_scheduler_state() -> dict[str, object]:
    try:
        payload = json.loads(
            AI_STAFF_LEARNING_COUNTERFACTUAL_SCHEDULER_STATE_FILE.read_text(encoding="utf-8")
        )
        return payload if isinstance(payload, dict) else {}
    except (OSError, json.JSONDecodeError):
        return {}


def _save_ai_staff_learning_counterfactual_scheduler_state(
    state: dict[str, object],
) -> dict[str, object]:
    target = AI_STAFF_LEARNING_COUNTERFACTUAL_SCHEDULER_STATE_FILE
    target.parent.mkdir(parents=True, exist_ok=True)
    temp_path = target.with_suffix(target.suffix + ".tmp")
    temp_path.write_text(
        json.dumps(state, ensure_ascii=False, indent=2, sort_keys=True),
        encoding="utf-8",
    )
    temp_path.replace(target)
    return state


def build_ai_staff_learning_counterfactual_runtime_status() -> dict[str, object]:
    state = _load_ai_staff_learning_counterfactual_scheduler_state()
    running = bool(
        AI_STAFF_LEARNING_COUNTERFACTUAL_THREAD is not None
        and AI_STAFF_LEARNING_COUNTERFACTUAL_THREAD.is_alive()
    )
    return {
        "ok": True,
        "schema": "codexstock_ai_staff_learning_counterfactual_runtime_v1",
        "running": running,
        "status": "RUNNING" if running else str(state.get("status") or "IDLE"),
        "state": state,
        "state_path": str(AI_STAFF_LEARNING_COUNTERFACTUAL_SCHEDULER_STATE_FILE),
        "heavy_research_lock_active": HEAVY_RESEARCH_JOB_LOCK.locked(),
        "paper_only": True,
        "live_order_allowed": False,
        "automatic_promotion": False,
    }


def _maybe_preregister_ai_staff_learning_counterfactual(
    schedule: dict[str, object],
    *,
    now: datetime | None = None,
) -> dict[str, object]:
    """Create one immutable forward-test lock while its target period is still future."""
    if schedule.get("ready_to_run"):
        return {
            "ok": True,
            "status": "CURRENT_PERIOD_ALREADY_RUNNABLE",
            "created": False,
            "paper_only": True,
            "live_order_allowed": False,
        }
    start_date = str(schedule.get("next_candidate_start_date") or "")
    end_date = str(schedule.get("minimum_candidate_end_date") or "")
    eligible_date = str(schedule.get("next_eligible_date") or "")
    if not start_date or not end_date or not eligible_date:
        return {
            "ok": True,
            "status": "NO_FUTURE_WINDOW_TO_PREREGISTER",
            "created": False,
            "paper_only": True,
            "live_order_allowed": False,
        }
    return ensure_ai_staff_learning_counterfactual_preregistration(
        target_start_date=start_date,
        target_end_date=end_date,
        first_eligible_run_date=eligible_date,
        symbols=["005930", "000660", "035420"],
        now=now,
    )


def build_ai_staff_learning_counterfactual_preregistration_status(
    schedule: dict[str, object] | None = None,
) -> dict[str, object]:
    """Expose the immutable forward-test lock without leaking full strategy payloads."""
    current = datetime.now(_zone("Asia/Seoul", 9))
    current_schedule = (
        schedule
        if isinstance(schedule, dict)
        else build_ai_staff_learning_counterfactual_scheduler_status(max_triplets=1)
    )
    due_status = _ai_staff_learning_counterfactual_due_preregistration_status()
    due_entries = (
        due_status.get("entries")
        if isinstance(due_status.get("entries"), list)
        else []
    )
    use_current_target = current_schedule.get("preregistered_forward_test") is True
    target_selection_source = (
        "schedule_preregistered_target"
        if use_current_target
        else "scheduler_candidate"
    )
    target_start = str(
        current_schedule.get("target_start_date")
        if use_current_target
        else current_schedule.get("next_candidate_start_date")
        or current_schedule.get("target_start_date")
        or ""
    )
    target_end = str(
        current_schedule.get("learning_preregistration_target_end_date")
        if use_current_target
        else current_schedule.get("minimum_candidate_end_date")
        or current_schedule.get("target_end_date")
        or ""
    )
    first_eligible = str(
        current_schedule.get("learning_preregistration_first_eligible_run_date")
        if use_current_target
        else current_schedule.get("next_eligible_date")
        or ""
    )
    if not use_current_target:
        selected_due = (
            due_status.get("selected_due_contract")
            if isinstance(due_status.get("selected_due_contract"), dict)
            else {}
        )
        active_contract = (
            selected_due
            if selected_due.get("state") == "DUE"
            else next(
                (
                    row
                    for row in due_entries
                    if isinstance(row, dict)
                    and row.get("valid") is True
                    and row.get("state") == "FUTURE_LOCKED"
                ),
                {},
            )
        )
        if active_contract:
            target_start = str(active_contract.get("target_start_date") or "")
            target_end = str(active_contract.get("target_end_date") or "")
            first_eligible = str(
                active_contract.get("first_eligible_run_date") or ""
            )
            target_selection_source = (
                "due_preregistration_ledger"
                if active_contract.get("state") == "DUE"
                else "future_preregistration_ledger"
            )
    lookup = (
        _find_ai_staff_learning_counterfactual_preregistration(
            target_start,
            target_end_date=target_end,
        )
        if target_start and target_end
        else {
            "found": False,
            "valid": False,
            "status": "NO_TARGET_WINDOW",
            "blockers": ["learning_preregistration_target_window_missing"],
            "contract": {},
        }
    )
    contract = (
        lookup.get("contract")
        if isinstance(lookup.get("contract"), dict)
        else {}
    )
    contract_outcome = next(
        (
            row
            for row in due_entries
            if isinstance(row, dict)
            and str(row.get("contract_id") or "")
            == str(contract.get("contract_id") or "")
            and str(row.get("contract_hash") or "")
            == str(contract.get("contract_hash") or "")
            and str(row.get("target_start_date") or "") == target_start
            and str(row.get("target_end_date") or "") == target_end
        ),
        {},
    )
    contract_registered_triplet_count = int(
        _number(
            contract_outcome.get("registered_plan_count")
            if contract_outcome
            else contract.get("registered_plan_count")
        )
    )
    contract_completed_triplet_count = int(
        _number(contract_outcome.get("completed_triplet_count"))
    )
    contract_remaining_triplet_count = int(
        _number(
            contract_outcome.get("remaining_triplet_count")
            if contract_outcome
            else contract_registered_triplet_count
        )
    )
    contract_missing_contestant_ids = (
        contract_outcome.get("missing_contestant_ids")
        if isinstance(contract_outcome.get("missing_contestant_ids"), list)
        else lookup.get("registered_contestant_ids", [])
        if lookup.get("found") and not contract_outcome
        else []
    )
    all_registered_plans_completed = bool(
        contract_outcome.get("state") == "COMPLETED"
        and contract_registered_triplet_count > 0
        and contract_completed_triplet_count == contract_registered_triplet_count
        and contract_remaining_triplet_count == 0
        and not contract_missing_contestant_ids
    )
    contract_result_evidence_ready = bool(
        lookup.get("valid")
        and all_registered_plans_completed
        and contract_outcome.get("ready_for_future_execution") is True
    )
    contract_outcome_state = str(
        contract_outcome.get("state")
        or (
            "OUTCOME_LEDGER_NOT_INDEXED"
            if lookup.get("valid")
            else "NOT_REGISTERED"
        )
    )
    target_is_future = False
    if target_start:
        try:
            target_is_future = current.date() < datetime.fromisoformat(target_start).date()
        except ValueError:
            target_is_future = False
    if lookup.get("found"):
        status = "REGISTERED" if lookup.get("valid") else "INVALID"
        next_action = (
            "review_completed_locked_forward_counterfactual_outcome"
            if contract_result_evidence_ready
            else "wait_for_locked_target_period_to_complete"
            if lookup.get("valid")
            else "quarantine_invalid_preregistration"
        )
    elif target_is_future:
        status = "PENDING_AUTOMATIC_REGISTRATION"
        next_action = "autopilot_scheduler_will_register_before_target_start"
    elif target_start:
        status = "MISSED_REGISTRATION_WINDOW"
        next_action = "skip_period_and_open_next_future_window"
    else:
        status = "NO_TARGET_WINDOW"
        next_action = "wait_for_independent_target_window"
    return {
        "ok": bool(lookup.get("valid") or (not lookup.get("found") and target_is_future)),
        "schema": "codexstock_ai_staff_learning_counterfactual_preregistration_status_v1",
        "generated_at": current.isoformat(timespec="seconds"),
        "status": status,
        "found": bool(lookup.get("found")),
        "valid": bool(lookup.get("valid")),
        "hash_valid": bool(lookup.get("hash_valid")),
        "ready_for_future_execution": bool(
            lookup.get("ready_for_future_execution")
        ),
        "ready_to_register_now": bool(not lookup.get("found") and target_is_future),
        "target_start_date": target_start,
        "target_end_date": target_end,
        "first_eligible_run_date": first_eligible or contract.get("first_eligible_run_date"),
        "target_selection_source": target_selection_source,
        "matured_preregistration_priority_active": bool(
            current_schedule.get("matured_preregistration_priority_active")
        ),
        "due_preregistration_status": current_schedule.get("due_preregistration_status"),
        "due_preregistration_count": int(
            _number(current_schedule.get("due_preregistration_count"))
        ),
        "same_period_auto_judgement_due": bool(
            due_status.get("same_period_auto_judgement_due")
        ),
        "same_period_auto_judgement_status": due_status.get(
            "same_period_auto_judgement_status"
        ),
        "same_period_auto_judgement_target_start_date": due_status.get(
            "same_period_auto_judgement_target_start_date"
        ),
        "same_period_auto_judgement_target_end_date": due_status.get(
            "same_period_auto_judgement_target_end_date"
        ),
        "same_period_auto_judgement_first_eligible_run_date": due_status.get(
            "same_period_auto_judgement_first_eligible_run_date"
        ),
        "same_period_auto_judgement_days_until_due": due_status.get(
            "same_period_auto_judgement_days_until_due"
        ),
        "same_period_auto_judgement_remaining_triplet_count": int(
            _number(due_status.get("same_period_auto_judgement_remaining_triplet_count"))
        ),
        "same_period_auto_judgement_required_action": due_status.get(
            "same_period_auto_judgement_required_action"
        ),
        "same_period_collection_status": due_status.get(
            "same_period_collection_status"
        ),
        "same_period_collection_expected_session_count": int(
            _number(due_status.get("same_period_collection_expected_session_count"))
        ),
        "same_period_collection_observed_session_count": int(
            _number(due_status.get("same_period_collection_observed_session_count"))
        ),
        "same_period_collection_missing_session_count": int(
            _number(due_status.get("same_period_collection_missing_session_count"))
        ),
        "same_period_collection_next_required_date": due_status.get(
            "same_period_collection_next_required_date"
        ),
        "same_period_collection_health": due_status.get(
            "same_period_collection_health"
        ),
        "same_period_collection_monitor": due_status.get(
            "same_period_collection_monitor"
        ),
        "same_period_auto_judgement_runbook": due_status.get(
            "same_period_auto_judgement_runbook"
        ),
        "catch_up_after_restart": bool(
            current_schedule.get("due_preregistration_catch_up_after_restart")
        ),
        "selected_due_preregistration_id": current_schedule.get(
            "selected_due_preregistration_id"
        ),
        "selected_due_preregistration_remaining_triplet_count": int(
            _number(
                current_schedule.get(
                    "selected_due_preregistration_remaining_triplet_count"
                )
            )
        ),
        "contract_id": contract.get("contract_id"),
        "contract_hash": contract.get("contract_hash"),
        "contract_generated_at": contract.get("generated_at"),
        "registered_plan_count": int(_number(contract.get("registered_plan_count"))),
        "blocked_plan_count": int(_number(contract.get("blocked_plan_count"))),
        "registered_contestant_ids": lookup.get("registered_contestant_ids", []),
        "contract_outcome_state": contract_outcome_state,
        "contract_registered_triplet_count": contract_registered_triplet_count,
        "contract_completed_triplet_count": contract_completed_triplet_count,
        "contract_remaining_triplet_count": contract_remaining_triplet_count,
        "contract_missing_contestant_ids": contract_missing_contestant_ids,
        "all_registered_plans_completed": all_registered_plans_completed,
        "contract_result_evidence_ready": contract_result_evidence_ready,
        "contract_result_catch_up_after_restart": bool(
            due_status.get("catch_up_after_restart")
        ),
        "strategy_lock_ready": bool(lookup.get("strategy_lock_ready")),
        "strategy_lock_plan_count": int(
            _number(lookup.get("strategy_lock_plan_count"))
        ),
        "strategy_lock_signature_count": int(
            _number(lookup.get("strategy_lock_signature_count"))
        ),
        "strategy_lock_digest": lookup.get("strategy_lock_digest"),
        "execution_strategy_revalidation_required": True,
        "generated_before_target_start": bool(
            lookup.get("generated_before_target_start")
        ),
        "selection_policy": contract.get("selection_policy"),
        "symbols": contract.get("symbols", []),
        "blockers": lookup.get("blockers", []),
        "next_action": next_action,
        "path": str(AI_STAFF_LEARNING_COUNTERFACTUAL_PREREGISTRATION_FILE),
        "paper_only": True,
        "live_order_allowed": False,
        "automatic_promotion": False,
        "full_strategy_payload_exposed": False,
    }


def _ai_staff_learning_counterfactual_scheduler_worker(config: dict[str, object]) -> None:
    state = _load_ai_staff_learning_counterfactual_scheduler_state()
    state.update(
        {
            "status": "RUNNING",
            "started_at": state.get("started_at")
            or datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
            "updated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
            "paper_only": True,
            "live_order_allowed": False,
            "automatic_promotion": False,
        }
    )
    _save_ai_staff_learning_counterfactual_scheduler_state(state)
    try:
        final_ab_mode = str(config.get("mode") or "") == "forward_ab_90_session_final"
        if final_ab_mode:
            result = run_ai_staff_90_session_forward_ab_final_evaluation(
                heavy_slot_reserved=True
            )
            completed = 1 if result.get("status") == "COMPLETED" else 0
            failed = 0 if completed else 1
            requested = 1
        else:
            result = run_ai_staff_learning_counterfactual_triplet_batch(
                max_triplets=max(1, min(int(_number(config.get("max_triplets")) or 1), 2)),
                symbols=[str(item) for item in config.get("symbols", []) if str(item)]
                if isinstance(config.get("symbols"), list)
                else None,
                start_date=str(config.get("start_date") or ""),
                end_date=str(config.get("end_date") or ""),
                allow_simulated_fallback=False,
                heavy_slot_reserved=True,
            )
            completed = int(_number(result.get("completed_triplet_count")))
            failed = int(_number(result.get("failed_triplet_count")))
            requested = max(1, min(int(_number(config.get("max_triplets")) or 1), 2))
        status = "COMPLETED" if completed >= requested and failed == 0 else (
            "PARTIAL_RETRY_REQUIRED"
            if completed > 0
            else
            "COMPLETED_NO_NEW_EVIDENCE"
            if str(result.get("stopped_reason") or "") == "no_uncompleted_triplet_available"
            else "FAILED"
        )
        state.update(
            {
                "status": status,
                "finished_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
                "updated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
                "completed_triplet_count": completed,
                "failed_triplet_count": failed,
                "requested_triplet_count": requested,
                "stopped_reason": result.get("stopped_reason"),
                "mode": config.get("mode") or "counterfactual_triplet_batch",
                "result_hash": result.get("result_hash"),
                "ledger_summary": result.get("ledger_summary", {}),
                "last_error": "" if status != "FAILED" else str(result.get("stopped_reason") or "triplet_failed"),
            }
        )
    except Exception as exc:
        state.update(
            {
                "status": "FAILED",
                "finished_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
                "updated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
                "last_error": f"{type(exc).__name__}: {exc}"[:500],
            }
        )
    finally:
        _save_ai_staff_learning_counterfactual_scheduler_state(state)
        try:
            HEAVY_RESEARCH_JOB_LOCK.release()
        except RuntimeError:
            pass


def _maybe_schedule_ai_staff_learning_counterfactual(
    source: str,
    *,
    now: datetime | None = None,
) -> dict[str, object]:
    global AI_STAFF_LEARNING_COUNTERFACTUAL_THREAD
    now = now or datetime.now(_zone("Asia/Seoul", 9))
    runtime = build_ai_staff_learning_counterfactual_runtime_status()
    state = runtime.get("state") if isinstance(runtime.get("state"), dict) else {}
    if runtime.get("running"):
        return {
            **runtime,
            "scheduled": False,
            "status": "ALREADY_RUNNING",
        }
    schedule = build_ai_staff_learning_counterfactual_scheduler_status(
        max_triplets=2,
        now=now,
    )
    preregistration = _maybe_preregister_ai_staff_learning_counterfactual(
        schedule,
        now=now,
    )
    forward_ab_90_session = ensure_ai_staff_90_session_forward_ab_contract(now=now)
    if forward_ab_90_session.get("final_ab_evaluation_due") is True:
        with AI_STAFF_LEARNING_COUNTERFACTUAL_START_LOCK:
            if (
                AI_STAFF_LEARNING_COUNTERFACTUAL_THREAD is not None
                and AI_STAFF_LEARNING_COUNTERFACTUAL_THREAD.is_alive()
            ):
                return {
                    **build_ai_staff_learning_counterfactual_runtime_status(),
                    "scheduled": False,
                    "status": "ALREADY_RUNNING",
                }
            if not HEAVY_RESEARCH_JOB_LOCK.acquire(blocking=False):
                return {
                    "ok": True,
                    "status": "HEAVY_RESEARCH_BUSY",
                    "scheduled": False,
                    "forward_ab_90_session": forward_ab_90_session,
                    "paper_only": True,
                    "live_order_allowed": False,
                    "automatic_promotion": False,
                }
            run_id = f"FAB90-EVAL-{int(time.time() * 1000)}"
            queued_state = {
                "schema": "codexstock_ai_staff_learning_counterfactual_scheduler_state_v1",
                "run_id": run_id,
                "mode": "forward_ab_90_session_final",
                "status": "QUEUED",
                "requested_by": source,
                "started_at": now.isoformat(timespec="seconds"),
                "updated_at": now.isoformat(timespec="seconds"),
                "max_triplets": 1,
                "paper_only": True,
                "live_order_allowed": False,
                "automatic_promotion": False,
            }
            _save_ai_staff_learning_counterfactual_scheduler_state(queued_state)
            try:
                AI_STAFF_LEARNING_COUNTERFACTUAL_THREAD = threading.Thread(
                    target=_ai_staff_learning_counterfactual_scheduler_worker,
                    args=(queued_state,),
                    name="ai-staff-forward-ab-final-evaluation",
                    daemon=True,
                )
                AI_STAFF_LEARNING_COUNTERFACTUAL_THREAD.start()
            except Exception:
                HEAVY_RESEARCH_JOB_LOCK.release()
                raise
        return {
            "ok": True,
            "status": "FORWARD_AB_FINAL_EVALUATION_QUEUED",
            "scheduled": True,
            "run_id": run_id,
            "forward_ab_90_session": forward_ab_90_session,
            "paper_only": True,
            "live_order_allowed": False,
            "automatic_promotion": False,
        }
    started_at = str(state.get("started_at") or "")
    try:
        started_day = datetime.fromisoformat(started_at.replace("Z", "+00:00")).astimezone(
            _zone("Asia/Seoul", 9)
        ).date().isoformat()
    except ValueError:
        started_day = ""
    terminal_status = str(state.get("status") or "").upper()
    matured_contract_incomplete = bool(
        schedule.get("matured_preregistration_priority_active")
        and int(_number(schedule.get("selected_due_preregistration_remaining_triplet_count"))) > 0
    )
    if started_day == now.date().isoformat() and terminal_status in {
        "QUEUED",
        "RUNNING",
        "COMPLETED",
        "COMPLETED_NO_NEW_EVIDENCE",
    } and not matured_contract_incomplete:
        return {
            **runtime,
            "scheduled": False,
            "status": "DAILY_COUNTERFACTUAL_ALREADY_ATTEMPTED",
            "schedule": schedule,
            "preregistration": preregistration,
            "forward_ab_90_session": forward_ab_90_session,
            "paper_only": True,
            "live_order_allowed": False,
            "automatic_promotion": False,
        }
    if not schedule.get("ready_to_run"):
        return {
            "ok": True,
            "status": str(schedule.get("status") or "DEFERRED"),
            "scheduled": False,
            "schedule": schedule,
            "preregistration": preregistration,
            "forward_ab_90_session": forward_ab_90_session,
            "paper_only": True,
            "live_order_allowed": False,
            "automatic_promotion": False,
        }
    with AI_STAFF_LEARNING_COUNTERFACTUAL_START_LOCK:
        if (
            AI_STAFF_LEARNING_COUNTERFACTUAL_THREAD is not None
            and AI_STAFF_LEARNING_COUNTERFACTUAL_THREAD.is_alive()
        ):
            return {
                **build_ai_staff_learning_counterfactual_runtime_status(),
                "scheduled": False,
                "status": "ALREADY_RUNNING",
            }
        if not HEAVY_RESEARCH_JOB_LOCK.acquire(blocking=False):
            return {
                "ok": True,
                "status": "HEAVY_RESEARCH_BUSY",
                "scheduled": False,
                "paper_only": True,
                "live_order_allowed": False,
                "automatic_promotion": False,
            }
        run_id = f"LCF-{int(time.time() * 1000)}"
        requested_triplets = max(
            1,
            min(
                2,
                int(_number(schedule.get("queue_triplet_count")) or 1),
            ),
        )
        queued_state = {
            "schema": "codexstock_ai_staff_learning_counterfactual_scheduler_state_v1",
            "run_id": run_id,
            "status": "QUEUED",
            "requested_by": source,
            "started_at": now.isoformat(timespec="seconds"),
            "updated_at": now.isoformat(timespec="seconds"),
            "max_triplets": requested_triplets,
            "start_date": str(schedule.get("target_start_date") or ""),
            "end_date": str(schedule.get("target_end_date") or ""),
            "symbols": [
                str(item)
                for item in schedule.get("target_symbols", [])
                if str(item)
            ] if isinstance(schedule.get("target_symbols"), list) else ["005930", "000660", "035420"],
            "queue_hash": schedule.get("queue_hash"),
            "paper_only": True,
            "live_order_allowed": False,
            "automatic_promotion": False,
        }
        _save_ai_staff_learning_counterfactual_scheduler_state(queued_state)
        try:
            AI_STAFF_LEARNING_COUNTERFACTUAL_THREAD = threading.Thread(
                target=_ai_staff_learning_counterfactual_scheduler_worker,
                args=(queued_state,),
                name="ai-staff-learning-counterfactual",
                daemon=True,
            )
            AI_STAFF_LEARNING_COUNTERFACTUAL_THREAD.start()
        except Exception:
            HEAVY_RESEARCH_JOB_LOCK.release()
            raise
    return {
        "ok": True,
        "status": "QUEUED",
        "scheduled": True,
        "run_id": run_id,
        "schedule": schedule,
        "forward_ab_90_session": forward_ab_90_session,
        "paper_only": True,
        "live_order_allowed": False,
        "automatic_promotion": False,
    }


def _ensure_long_horizon_fixed_etf_universe(
    *,
    coverage_end: str | None = None,
    store: UniverseStore | None = None,
) -> dict[str, object]:
    end_date = _parse_replay_date(coverage_end or today_kst(), today_kst()).date().isoformat()
    universe_store = store or UniverseStore(POINT_IN_TIME_UNIVERSE_ROOT)
    records = [
        {
            **row,
            "market": "US",
            "security_type": "ETF",
            "delisting_date": None,
        }
        for row in LONG_HORIZON_FIXED_ETF_UNIVERSE
    ]
    source_urls = list(dict.fromkeys(str(row["source_url"]) for row in records))
    evidence = {
        "grade": "official_fixed_pre_start_instruments",
        "official": True,
        "coverage_start": min(str(row["listing_date"]) for row in records),
        "coverage_end": end_date,
        "frozen_as_of": max(str(row["listing_date"]) for row in records),
        "frozen_before_test": True,
        "pre_start_listing_required": True,
        "selection_rule_complete": True,
        "selection_rule_version": "broad-index-plus-original-nine-sector-etfs-pre2000.v1",
        "selection_rule": "All three broad US index ETFs and all original nine Select Sector SPDR ETFs listed before 2000-01-03; no later winner may enter.",
        "claim_scope": "timing_exit_and_risk_management_only",
        "stock_selection_claim_allowed": False,
        "live_stock_promotion_allowed": False,
        "instrument_count": len(records),
        "official_source_urls": source_urls,
        "verified_at": "2026-07-15",
    }
    registered = universe_store.register(
        LONG_HORIZON_FIXED_ETF_UNIVERSE_ID,
        records,
        "State Street and Invesco official fund inception/listing records",
        evidence,
    )
    validation = universe_store.validate_period(
        LONG_HORIZON_FIXED_ETF_UNIVERSE_ID,
        [str(row["symbol"]) for row in records],
        "2000-01-03",
        end_date,
    )
    return {
        **registered,
        "symbols": [str(row["symbol"]) for row in records],
        "validation": validation,
        "claim_scope": evidence["claim_scope"],
        "stock_selection_claim_allowed": False,
        "live_order_allowed": False,
    }


def _long_horizon_fixed_etf_universe_status(
    *,
    coverage_end: str | None = None,
    store: UniverseStore | None = None,
) -> dict[str, object]:
    end_date = _parse_replay_date(coverage_end or today_kst(), today_kst()).date().isoformat()
    universe_store = store or UniverseStore(POINT_IN_TIME_UNIVERSE_ROOT)
    try:
        payload = universe_store.get(LONG_HORIZON_FIXED_ETF_UNIVERSE_ID)
        symbols = [str(row.get("symbol") or "") for row in payload.get("records", []) if isinstance(row, dict)]
        validation = universe_store.validate_period(
            LONG_HORIZON_FIXED_ETF_UNIVERSE_ID,
            symbols,
            "2000-01-03",
            end_date,
        )
        evidence = payload.get("evidence") if isinstance(payload.get("evidence"), dict) else {}
        return {
            "ok": bool(validation.get("passed")),
            "dataset_id": LONG_HORIZON_FIXED_ETF_UNIVERSE_ID,
            "record_count": len(symbols),
            "symbols": symbols,
            "content_hash": payload.get("content_hash"),
            "coverage_start": evidence.get("coverage_start"),
            "coverage_end": evidence.get("coverage_end"),
            "validation": validation,
            "claim_scope": evidence.get("claim_scope"),
            "stock_selection_claim_allowed": False,
            "live_order_allowed": False,
        }
    except Exception as exc:
        return {
            "ok": False,
            "dataset_id": LONG_HORIZON_FIXED_ETF_UNIVERSE_ID,
            "error": f"{type(exc).__name__}: {exc}"[:300],
            "stock_selection_claim_allowed": False,
            "live_order_allowed": False,
        }


def _official_usdkrw_at_or_before(date_key: str, lookback_days: int = 14) -> dict[str, object]:
    """Return the latest official ECOS USD/KRW rate without using future data."""
    try:
        boundary = datetime.fromisoformat(str(date_key or "")).date()
    except (TypeError, ValueError):
        return {
            "ok": False,
            "status": "invalid_boundary_date",
            "requested_date": str(date_key or ""),
            "future_value_used": False,
        }
    start = (boundary - timedelta(days=max(7, int(lookback_days)))).strftime("%Y%m%d")
    end = boundary.strftime("%Y%m%d")
    try:
        result = INTEGRATIONS.ecos_series(
            stat_code="731Y001",
            cycle="D",
            start=start,
            end=end,
            item_code1="0000001",
            limit=max(20, int(lookback_days) * 2),
        )
    except Exception as exc:
        return {
            "ok": False,
            "status": "provider_error",
            "requested_date": boundary.isoformat(),
            "source": "BOK ECOS 731Y001/0000001",
            "future_value_used": False,
            "error": f"{type(exc).__name__}: {exc}"[:240],
        }
    eligible = [
        row
        for row in result.get("rows", [])
        if isinstance(row, dict)
        and str(row.get("time") or "") <= end
        and _number(row.get("value")) > 0
    ] if isinstance(result, dict) else []
    selected = eligible[-1] if eligible else {}
    observed_at = str(selected.get("time") or "")
    value = _number(selected.get("value"))
    return {
        "ok": bool(result.get("ok") and observed_at and value > 0),
        "status": "verified" if result.get("ok") and observed_at and value > 0 else "unavailable",
        "requested_date": boundary.isoformat(),
        "observed_at": observed_at,
        "value": value if value > 0 else None,
        "unit": selected.get("unit") or "KRW per USD",
        "source": "BOK ECOS 731Y001/0000001",
        "source_name": selected.get("stat_name", ""),
        "item_name": selected.get("item_name1", ""),
        "future_value_used": False,
        "configured": bool(result.get("configured")) if isinstance(result, dict) else False,
        "message": str(result.get("message") or "") if isinstance(result, dict) else "",
    }


def _long_horizon_spy_benchmark(start_date: str, end_date: str) -> dict[str, object]:
    result = _fetch_yahoo_chart_range("SPY", start_date, end_date, timeout=15.0, min_rows=40)
    rows = [row for row in result.get("rows", []) if isinstance(row, dict)]
    adjusted_rows = [row for row in rows if _number(row.get("adjusted_close")) > 0]
    if len(rows) < 2 or len(adjusted_rows) < 2:
        raise ValueError("SPY adjusted-close history is unavailable")
    first = rows[0]
    last = rows[-1]
    first_adjusted = adjusted_rows[0]
    last_adjusted = adjusted_rows[-1]
    benchmark_first_date = str(first_adjusted.get("date") or "")
    benchmark_last_date = str(last_adjusted.get("date") or "")
    years = max(
        1.0,
        (
            datetime.fromisoformat(benchmark_last_date).date()
            - datetime.fromisoformat(benchmark_first_date).date()
        ).days
        / 365.25,
    )

    def performance(first_value: float, last_value: float) -> tuple[float, float]:
        multiple = last_value / max(first_value, 1e-12)
        return (multiple - 1.0) * 100.0, (multiple ** (1.0 / years) - 1.0) * 100.0

    price_total, price_cagr = performance(_number(first.get("close")), _number(last.get("close")))
    total_return, total_cagr = performance(
        _number(first_adjusted.get("adjusted_close")),
        _number(last_adjusted.get("adjusted_close")),
    )
    krw_total_return: float | None = None
    krw_cagr: float | None = None
    fx_first: float | None = None
    fx_last: float | None = None
    fx_error = ""
    fx_boundary_evidence: dict[str, object] = {}
    fx_sources: list[str] = []
    try:
        fx_result = _fetch_yahoo_chart_range("KRW=X", start_date, end_date, timeout=15.0, min_rows=40)
        fx_rows = [row for row in fx_result.get("rows", []) if isinstance(row, dict)]

        def fx_at(date_key: str) -> float:
            values = [
                _number(row.get("adjusted_close") or row.get("close"))
                for row in fx_rows
                if str(row.get("date") or "") <= date_key and _number(row.get("adjusted_close") or row.get("close")) > 0
            ]
            return values[-1] if values else 0.0

        fx_first = fx_at(str(first_adjusted.get("date") or "")) or None
        fx_last = fx_at(str(last_adjusted.get("date") or "")) or None
        if fx_first or fx_last:
            fx_sources.append("Yahoo chart:KRW=X")
        if not fx_first:
            official_first = _official_usdkrw_at_or_before(benchmark_first_date)
            fx_boundary_evidence["first"] = official_first
            if official_first.get("ok"):
                fx_first = _number(official_first.get("value")) or None
                fx_sources.append(str(official_first.get("source") or "BOK ECOS"))
        if not fx_last:
            official_last = _official_usdkrw_at_or_before(benchmark_last_date)
            fx_boundary_evidence["last"] = official_last
            if official_last.get("ok"):
                fx_last = _number(official_last.get("value")) or None
                fx_sources.append(str(official_last.get("source") or "BOK ECOS"))
        if fx_first and fx_last:
            krw_total_return, krw_cagr = performance(
                _number(first_adjusted.get("adjusted_close")) * fx_first,
                _number(last_adjusted.get("adjusted_close")) * fx_last,
            )
        else:
            fx_error = "USD/KRW does not cover the benchmark boundary dates"
    except Exception as exc:
        fx_error = str(exc)
        if not fx_first:
            official_first = _official_usdkrw_at_or_before(benchmark_first_date)
            fx_boundary_evidence["first"] = official_first
            if official_first.get("ok"):
                fx_first = _number(official_first.get("value")) or None
                fx_sources.append(str(official_first.get("source") or "BOK ECOS"))
        if not fx_last:
            official_last = _official_usdkrw_at_or_before(benchmark_last_date)
            fx_boundary_evidence["last"] = official_last
            if official_last.get("ok"):
                fx_last = _number(official_last.get("value")) or None
                fx_sources.append(str(official_last.get("source") or "BOK ECOS"))
        if fx_first and fx_last:
            krw_total_return, krw_cagr = performance(
                _number(first_adjusted.get("adjusted_close")) * fx_first,
                _number(last_adjusted.get("adjusted_close")) * fx_last,
            )
            fx_error = ""
    fx_sources = list(dict.fromkeys(source for source in fx_sources if source))
    benchmark_cost_profile = {
        "policy_version": PAPER_COST_POLICY_VERSION,
        "commission_bps_each_side": DEFAULT_PAPER_COMMISSION_BPS,
        "slippage_bps_each_side": DEFAULT_PAPER_SLIPPAGE_BPS,
        "us_sell_tax_bps": 0.0,
        "us_regulatory_fee_policy_version": PAPER_US_REGULATORY_POLICY_VERSION,
        "fx_conversion_spread_bps_each_side": DEFAULT_PAPER_FX_SPREAD_BPS,
        "base_currency": "KRW",
        "application": "fractional_buy_and_hold_round_trip",
    }
    commission_rate = DEFAULT_PAPER_COMMISSION_BPS / 10_000.0
    slippage_rate = DEFAULT_PAPER_SLIPPAGE_BPS / 10_000.0
    fx_spread_rate = DEFAULT_PAPER_FX_SPREAD_BPS / 10_000.0
    benchmark_exit_gross_krw = (
        _number(last_adjusted.get("adjusted_close")) * _number(fx_last)
        if fx_last
        else 0.0
    )
    benchmark_regulatory = _paper_us_regulatory_fee_contract(
        benchmark_last_date,
        quantity=1.0,
        gross_krw=benchmark_exit_gross_krw,
        usdkrw_rate=_number(fx_last),
    )
    us_regulatory_exit_rate = (
        (
            _number(benchmark_regulatory.get("sec_fee_krw"))
            + _number(benchmark_regulatory.get("finra_taf_krw"))
        )
        / benchmark_exit_gross_krw
        if benchmark_exit_gross_krw > 0
        else 0.0
    )
    benchmark_cost_profile["exit_sec_fee_bps"] = benchmark_regulatory.get("sec_fee_bps")
    benchmark_cost_profile["exit_finra_taf_per_share_usd"] = benchmark_regulatory.get(
        "finra_taf_per_share_usd"
    )
    benchmark_cost_profile["exit_regulatory_fee_rate"] = round(us_regulatory_exit_rate, 12)
    net_costed_krw_total_return: float | None = None
    net_costed_krw_cagr: float | None = None
    if krw_total_return is not None and krw_cagr is not None:
        gross_multiple = 1.0 + krw_total_return / 100.0
        entry_cost_multiplier = (1.0 + slippage_rate) * (
            1.0 + commission_rate + fx_spread_rate
        )
        exit_proceeds_multiplier = (1.0 - slippage_rate) * (
            1.0 - commission_rate - fx_spread_rate - us_regulatory_exit_rate
        )
        net_multiple = gross_multiple * exit_proceeds_multiplier / entry_cost_multiplier
        net_costed_krw_total_return = (net_multiple - 1.0) * 100.0
        net_costed_krw_cagr = (net_multiple ** (1.0 / years) - 1.0) * 100.0
    input_data_hash = hashlib.sha256(
        json.dumps(
            {
                "adjusted_close": [
                    {
                        "date": str(row.get("date") or ""),
                        "adjusted_close": round(_number(row.get("adjusted_close")), 8),
                    }
                    for row in adjusted_rows
                ],
                "usdkrw_first": fx_first,
                "usdkrw_last": fx_last,
            },
            ensure_ascii=True,
            sort_keys=True,
        ).encode("utf-8")
    ).hexdigest()
    benchmark = {
        "schema": "codexstock_long_horizon_benchmark_v3",
        "symbol": "SPY",
        "source": "Yahoo adjusted close",
        "requested_start_date": start_date,
        "requested_end_date": end_date,
        "first_date": benchmark_first_date,
        "last_date": benchmark_last_date,
        "horizon_years": round(years, 2),
        "row_count": len(rows),
        "adjusted_row_count": len(adjusted_rows),
        "price_total_return_pct": round(price_total, 2),
        "price_cagr_pct": round(price_cagr, 2),
        "dividend_adjusted_total_return_pct": round(total_return, 2),
        "dividend_adjusted_cagr_pct": round(total_cagr, 2),
        "dividends_reinvested": True,
        "return_basis": "adjusted_close_total_return",
        "comparison_currency": "KRW" if krw_cagr is not None else "USD",
        "usdkrw_first": round(fx_first, 6) if fx_first else None,
        "usdkrw_last": round(fx_last, 6) if fx_last else None,
        "usdkrw_source": " + ".join(fx_sources),
        "usdkrw_boundary_evidence": fx_boundary_evidence,
        "usdkrw_future_value_used": False,
        "fx_policy_version": "ecos-boundary-fallback.v1",
        "krw_adjusted_total_return_pct": round(krw_total_return, 4) if krw_total_return is not None else None,
        "krw_adjusted_cagr_pct": round(krw_cagr, 6) if krw_cagr is not None else None,
        "net_costed_krw_total_return_pct": (
            round(net_costed_krw_total_return, 4)
            if net_costed_krw_total_return is not None
            else None
        ),
        "net_costed_krw_cagr_pct": (
            round(net_costed_krw_cagr, 6)
            if net_costed_krw_cagr is not None
            else None
        ),
        "transaction_cost_profile": benchmark_cost_profile,
        "transaction_cost_validated": bool(
            net_costed_krw_total_return is not None and net_costed_krw_cagr is not None
        ),
        "transaction_cost_drag_total_return_pctp": (
            round(krw_total_return - net_costed_krw_total_return, 4)
            if krw_total_return is not None and net_costed_krw_total_return is not None
            else None
        ),
        "transaction_cost_drag_cagr_pctp": (
            round(krw_cagr - net_costed_krw_cagr, 6)
            if krw_cagr is not None and net_costed_krw_cagr is not None
            else None
        ),
        "comparison_return_basis": "net_costed_adjusted_close_total_return",
        "currency_conversion_validated": bool(fx_first and fx_last and krw_cagr is not None),
        "fx_error": fx_error,
        "input_data_hash": input_data_hash,
    }
    benchmark["evidence_hash"] = hashlib.sha256(
        json.dumps(benchmark, ensure_ascii=True, sort_keys=True).encode("utf-8")
    ).hexdigest()
    return benchmark


def _long_horizon_benchmark_cost_policy_current(
    benchmark: dict[str, object],
) -> bool:
    profile = (
        benchmark.get("transaction_cost_profile")
        if isinstance(benchmark.get("transaction_cost_profile"), dict)
        else {}
    )
    return bool(
        benchmark.get("transaction_cost_validated") is True
        and profile.get("policy_version") == PAPER_COST_POLICY_VERSION
        and profile.get("base_currency") == "KRW"
        and abs(
            _number(profile.get("commission_bps_each_side"))
            - DEFAULT_PAPER_COMMISSION_BPS
        )
        <= 0.000001
        and abs(
            _number(profile.get("slippage_bps_each_side"))
            - DEFAULT_PAPER_SLIPPAGE_BPS
        )
        <= 0.000001
        and abs(
            _number(profile.get("fx_conversion_spread_bps_each_side"))
            - DEFAULT_PAPER_FX_SPREAD_BPS
        )
        <= 0.000001
        and profile.get("us_regulatory_fee_policy_version")
        == PAPER_US_REGULATORY_POLICY_VERSION
    )


def _long_horizon_staff_cost_policy_current(staff: dict[str, object]) -> bool:
    model = staff.get("cost_model") if isinstance(staff.get("cost_model"), dict) else {}
    return bool(
        model.get("policy_version") == PAPER_COST_POLICY_VERSION
        and model.get("base_currency") == "KRW"
        and model.get("us_regulatory_fee_policy_version")
        == PAPER_US_REGULATORY_POLICY_VERSION
        and abs(
            _number(model.get("fx_conversion_spread_bps_each_side"))
            - DEFAULT_PAPER_FX_SPREAD_BPS
        )
        <= 0.000001
    )


def _long_horizon_performance_evidence(
    staff: dict[str, object],
    benchmark: dict[str, object],
    *,
    requested_start_date: str,
    requested_end_date: str,
) -> dict[str, object]:
    """Fail closed unless a long-horizon performance claim is reproducible."""
    checks: list[dict[str, object]] = []
    blockers: list[str] = []

    def add_check(check_id: str, passed: bool, weight: float, detail: str, blocker: str) -> None:
        operational_display = {"label": ""}
        operational_state_label = ""
        operational_state_label = str(operational_display.get("label") or operational_state_label or "검증대기")
        checks.append(
            {
                "id": check_id,
                "passed": bool(passed),
                "weight": float(weight),
                "detail": detail,
            }
        )
        if not passed:
            blockers.append(blocker)

    def parse_date(value: object) -> date | None:
        try:
            return datetime.fromisoformat(str(value or "").strip()).date()
        except (TypeError, ValueError):
            return None

    coverage = staff.get("data_coverage") if isinstance(staff.get("data_coverage"), dict) else {}
    actual_start_text = str(coverage.get("actual_start_date") or staff.get("actual_start_date") or "")
    actual_end_text = str(coverage.get("actual_end_date") or staff.get("actual_end_date") or "")
    actual_start = parse_date(actual_start_text)
    actual_end = parse_date(actual_end_text)
    requested_start = parse_date(requested_start_date)
    requested_end = parse_date(requested_end_date)
    actual_days = (actual_end - actual_start).days if actual_start and actual_end else 0
    actual_horizon_years = actual_days / 365.25 if actual_days > 0 else 0.0
    boundary_coverage_passed = bool(
        coverage.get("schema") == "codexstock_replay_data_coverage_v1"
        and coverage.get("portfolio_boundary_coverage_passed") is True
        and actual_start
        and actual_end
        and requested_start
        and requested_end
    )
    add_check(
        "actual_data_boundaries",
        boundary_coverage_passed,
        12,
        f"actual={actual_start_text or '-'}..{actual_end_text or '-'} requested={requested_start_date}..{requested_end_date}",
        "actual_data_boundary_evidence_missing_or_incomplete",
    )
    add_check(
        "minimum_long_horizon",
        actual_horizon_years >= 20.0,
        8,
        f"actual_horizon_years={actual_horizon_years:.4f}",
        "actual_horizon_below_20_years",
    )

    initial_cash = _number(staff.get("initial_cash"))
    final_equity = _number(staff.get("final_equity"))
    recorded_total_return = _number(staff.get("total_return_pct"))
    recorded_cagr = _number(staff.get("cagr_pct"))
    computed_total_return: float | None = None
    computed_cagr: float | None = None
    equity_math_passed = False
    if initial_cash > 0 and final_equity >= 0 and actual_horizon_years > 0:
        ending_multiple = final_equity / initial_cash
        computed_total_return = (ending_multiple - 1.0) * 100.0
        computed_cagr = -100.0 if ending_multiple <= 0 else (ending_multiple ** (1.0 / actual_horizon_years) - 1.0) * 100.0
        equity_math_passed = (
            abs(computed_total_return - recorded_total_return) <= 0.02
            and abs(computed_cagr - recorded_cagr) <= 0.02
        )
    add_check(
        "equity_return_cagr_reconciliation",
        equity_math_passed,
        12,
        (
            f"recorded_total={recorded_total_return:.4f} computed_total={computed_total_return if computed_total_return is not None else '-'} "
            f"recorded_cagr={recorded_cagr:.4f} computed_cagr={computed_cagr if computed_cagr is not None else '-'}"
        ),
        "equity_return_or_cagr_mismatch",
    )

    trade_count = int(_number(staff.get("trade_count")))
    add_check(
        "sample_adequacy",
        trade_count >= 30,
        8,
        f"trade_count={trade_count} minimum=30",
        "trade_sample_below_30_actions",
    )

    cost_audit = staff.get("transaction_cost_audit") if isinstance(staff.get("transaction_cost_audit"), dict) else {}
    cost_model = staff.get("cost_model") if isinstance(staff.get("cost_model"), dict) else {}
    cost_total = _number(staff.get("total_transaction_cost"))
    cost_total_matches = abs(_number(cost_audit.get("recorded_total_transaction_cost")) - cost_total) <= max(
        0.05,
        cost_total * 0.000001,
    )
    cost_passed = bool(
        cost_audit.get("schema") == "codexstock_replay_transaction_cost_audit_v1"
        and cost_audit.get("passed") is True
        and int(_number(cost_audit.get("applied_action_count"))) == trade_count
        and cost_total_matches
        and cost_model.get("base_currency") == "KRW"
    )
    add_check(
        "transaction_cost_ledger",
        cost_passed,
        12,
        f"audited_actions={int(_number(cost_audit.get('applied_action_count')))} trade_count={trade_count} cost={cost_total:.2f}",
        "transaction_cost_ledger_not_reconciled",
    )

    return_status = str(staff.get("return_claim_status") or "").strip().lower()
    return_reconciliation_passed = bool(
        not staff.get("return_claim_blocked") and return_status == "passed"
    )
    add_check(
        "return_reconciliation",
        return_reconciliation_passed,
        8,
        f"status={return_status or '-'} blocked={bool(staff.get('return_claim_blocked'))}",
        "return_reconciliation_not_strictly_passed",
    )

    price_audit = staff.get("price_currency_unit_audit") if isinstance(staff.get("price_currency_unit_audit"), dict) else {}
    price_passed = bool(price_audit.get("passed") is True and price_audit.get("base_currency") == "KRW")
    add_check(
        "price_currency_unit",
        price_passed,
        6,
        f"passed={price_audit.get('passed')} base_currency={price_audit.get('base_currency')}",
        "price_currency_unit_audit_not_passed",
    )

    timing = staff.get("execution_timing_model") if isinstance(staff.get("execution_timing_model"), dict) else {}
    timing_passed = bool(
        timing.get("lookahead_safe_required") is True
        and timing.get("same_bar_signal_execution_allowed") is False
        and int(_number(timing.get("minimum_signal_lag_bars"))) >= 1
    )
    add_check(
        "lookahead_safe_execution",
        timing_passed,
        4,
        f"model={timing.get('version') or '-'} lag={timing.get('minimum_signal_lag_bars')}",
        "lookahead_safe_execution_evidence_missing",
    )

    benchmark_first = parse_date(benchmark.get("first_date"))
    benchmark_last = parse_date(benchmark.get("last_date"))
    benchmark_cagr_present = benchmark.get("net_costed_krw_cagr_pct") not in {None, ""}
    benchmark_currency_passed = bool(
        benchmark.get("schema") == "codexstock_long_horizon_benchmark_v3"
        and benchmark.get("comparison_currency") == "KRW"
        and benchmark.get("currency_conversion_validated") is True
        and benchmark.get("dividends_reinvested") is True
        and benchmark_cagr_present
        and benchmark.get("input_data_hash")
        and benchmark.get("evidence_hash")
    )
    add_check(
        "benchmark_total_return_currency",
        benchmark_currency_passed,
        8,
        f"schema={benchmark.get('schema') or '-'} currency={benchmark.get('comparison_currency') or '-'} dividends={benchmark.get('dividends_reinvested')}",
        "benchmark_total_return_or_currency_evidence_invalid",
    )
    benchmark_cost_profile = (
        benchmark.get("transaction_cost_profile")
        if isinstance(benchmark.get("transaction_cost_profile"), dict)
        else {}
    )
    benchmark_cost_passed = bool(
        benchmark.get("transaction_cost_validated") is True
        and benchmark_cost_profile.get("base_currency") == "KRW"
        and abs(
            _number(benchmark_cost_profile.get("commission_bps_each_side"))
            - _number(cost_model.get("commission_bps_each_side"))
        ) <= 0.000001
        and abs(
            _number(benchmark_cost_profile.get("slippage_bps_each_side"))
            - _number(cost_model.get("slippage_bps_each_side"))
        ) <= 0.000001
        and abs(
            _number(benchmark_cost_profile.get("us_sell_tax_bps"))
            - _number(cost_model.get("us_sell_tax_bps"))
        ) <= 0.000001
        and abs(
            _number(benchmark_cost_profile.get("fx_conversion_spread_bps_each_side"))
            - _number(cost_model.get("fx_conversion_spread_bps_each_side"))
        ) <= 0.000001
        and benchmark_cost_profile.get("us_regulatory_fee_policy_version")
        == cost_model.get("us_regulatory_fee_policy_version")
        == PAPER_US_REGULATORY_POLICY_VERSION
    )
    add_check(
        "benchmark_transaction_cost_contract",
        benchmark_cost_passed,
        4,
        (
            f"benchmark={benchmark_cost_profile.get('commission_bps_each_side')}/"
            f"{benchmark_cost_profile.get('slippage_bps_each_side')}/"
            f"{benchmark_cost_profile.get('us_sell_tax_bps')}/"
            f"{benchmark_cost_profile.get('fx_conversion_spread_bps_each_side')} "
            f"strategy={cost_model.get('commission_bps_each_side')}/"
            f"{cost_model.get('slippage_bps_each_side')}/"
            f"{cost_model.get('us_sell_tax_bps')}/"
            f"{cost_model.get('fx_conversion_spread_bps_each_side')}"
        ),
        "benchmark_transaction_cost_contract_mismatch",
    )
    benchmark_rows = int(_number(benchmark.get("adjusted_row_count")))
    minimum_benchmark_rows = max(40, int(actual_horizon_years * 200)) if actual_horizon_years else 40
    benchmark_period_passed = bool(
        actual_start
        and actual_end
        and benchmark_first
        and benchmark_last
        and benchmark_first == actual_start
        and benchmark_last == actual_end
        and benchmark_rows >= minimum_benchmark_rows
    )
    add_check(
        "benchmark_period_alignment",
        benchmark_period_passed,
        8,
        f"benchmark={benchmark.get('first_date') or '-'}..{benchmark.get('last_date') or '-'} rows={benchmark_rows}/{minimum_benchmark_rows}",
        "benchmark_period_not_aligned_with_strategy",
    )

    bias_audit = staff.get("bias_audit") if isinstance(staff.get("bias_audit"), dict) else {}
    add_check(
        "point_in_time_universe",
        bias_audit.get("passed") is True,
        5,
        f"passed={bias_audit.get('passed')} dataset={bias_audit.get('universe_dataset_id') or '-'}",
        "survivorship_or_point_in_time_universe_not_validated",
    )
    walk_forward = staff.get("walk_forward") if isinstance(staff.get("walk_forward"), dict) else {}
    walk_forward_checks = walk_forward.get("checks") if isinstance(walk_forward.get("checks"), dict) else {}
    measurement_check_ids = {
        "training_evidence_passed",
        "out_of_sample_cost_ledger_passed",
        "out_of_sample_price_currency_unit_passed",
        "out_of_sample_lookahead_safe_execution_passed",
        "same_cost_profile",
        "selection_leakage_free",
    }
    walk_forward_measurement_validated = bool(
        walk_forward.get("measurement_evidence_validated") is True
        or (
            measurement_check_ids.issubset(walk_forward_checks)
            and all(walk_forward_checks.get(check_id) is True for check_id in measurement_check_ids)
        )
        or (not walk_forward_checks and walk_forward.get("passed") is True)
    )
    add_check(
        "walk_forward_measurement_evidence",
        walk_forward_measurement_validated,
        5,
        (
            f"measurement_validated={walk_forward_measurement_validated} "
            f"strategy_passed={walk_forward.get('passed')} status={walk_forward.get('status') or '-'}"
        ),
        "walk_forward_measurement_evidence_not_validated",
    )

    unique_blockers = list(dict.fromkeys(blockers))
    passed = not unique_blockers
    confidence_score = round(sum(_number(row.get("weight")) for row in checks if row.get("passed")), 1)
    benchmark_cagr = (
        _number(benchmark.get("net_costed_krw_cagr_pct"))
        if benchmark_currency_passed and benchmark_cost_passed and benchmark_period_passed
        else None
    )
    excess_cagr = (
        (computed_cagr - benchmark_cagr)
        if computed_cagr is not None and benchmark_cagr is not None
        else None
    )
    return {
        "schema": "codexstock_long_horizon_performance_evidence_v1",
        "passed": passed,
        "status": "official" if passed else "reference_only",
        "confidence_score": confidence_score,
        "checks": checks,
        "blockers": unique_blockers,
        "requested_start_date": requested_start_date,
        "requested_end_date": requested_end_date,
        "actual_start_date": actual_start_text or None,
        "actual_end_date": actual_end_text or None,
        "actual_horizon_years": round(actual_horizon_years, 6),
        "computed_total_return_pct": round(computed_total_return, 4) if computed_total_return is not None else None,
        "computed_cagr_pct": round(computed_cagr, 4) if computed_cagr is not None else None,
        "benchmark_cagr_pct": round(benchmark_cagr, 4) if benchmark_cagr is not None else None,
        "benchmark_gross_cagr_pct": (
            round(_number(benchmark.get("krw_adjusted_cagr_pct")), 4)
            if benchmark_currency_passed and benchmark_period_passed
            else None
        ),
        "excess_cagr_pctp": round(excess_cagr, 4) if excess_cagr is not None else None,
        "claim_scope": bias_audit.get("claim_scope") or "unverified",
        "stock_selection_claim_allowed": bool(bias_audit.get("stock_selection_claim_allowed")),
        "live_stock_promotion_allowed": bool(bias_audit.get("promotion_allowed")),
        "walk_forward_measurement_evidence_validated": walk_forward_measurement_validated,
        "strategy_walk_forward_passed": walk_forward.get("passed") is True,
        "strategy_promotion_allowed": bool(
            walk_forward.get("passed") is True and bias_audit.get("promotion_allowed") is True
        ),
        "official_total_return_pct": round(computed_total_return, 2) if passed and computed_total_return is not None else None,
        "official_cagr_pct": round(computed_cagr, 2) if passed and computed_cagr is not None else None,
        "evidence_hash": hashlib.sha256(
            json.dumps(
                {
                    "staff": staff.get("contestant_id"),
                    "checks": checks,
                    "benchmark": benchmark.get("evidence_hash"),
                    "cost_ledger": cost_audit.get("ledger_hash"),
                },
                ensure_ascii=True,
                sort_keys=True,
            ).encode("utf-8")
        ).hexdigest(),
        "policy": (
            "Historical measurement validity is separate from strategy promotion. Verified losses remain official measurements, "
            "while failed OOS strategy checks remain blocked from scores and live candidates."
        ),
    }


def _long_horizon_common_measurement_window(
    staff_rows: list[dict[str, object]],
    *,
    requested_start_date: str,
    requested_end_date: str,
) -> dict[str, object]:
    """Select one benchmark window only when every staff replay proves it."""

    requested_window = (str(requested_start_date or ""), str(requested_end_date or ""))
    windows: list[tuple[str, str]] = []
    invalid_staff_ids: list[str] = []
    for index, row in enumerate(staff_rows):
        coverage = row.get("data_coverage") if isinstance(row.get("data_coverage"), dict) else {}
        start_date = str(coverage.get("actual_start_date") or row.get("actual_start_date") or "")
        end_date = str(coverage.get("actual_end_date") or row.get("actual_end_date") or "")
        try:
            valid = bool(
                start_date
                and end_date
                and datetime.fromisoformat(start_date).date()
                <= datetime.fromisoformat(end_date).date()
            )
        except (TypeError, ValueError):
            valid = False
        if not valid:
            invalid_staff_ids.append(str(row.get("contestant_id") or f"staff-{index + 1}"))
            continue
        windows.append((start_date, end_date))

    unique_windows = sorted(set(windows))
    all_staff_covered = bool(staff_rows) and len(windows) == len(staff_rows)
    common_window = unique_windows[0] if all_staff_covered and len(unique_windows) == 1 else None
    if common_window:
        status = "common_staff_actual_window"
        selected_window = common_window
    elif not staff_rows:
        status = "requested_window_without_staff_evidence"
        selected_window = requested_window
    else:
        status = "staff_measurement_window_inconsistent_or_incomplete"
        selected_window = requested_window

    return {
        "schema": "codexstock_long_horizon_measurement_window_v1",
        "status": status,
        "start_date": selected_window[0],
        "end_date": selected_window[1],
        "requested_start_date": requested_window[0],
        "requested_end_date": requested_window[1],
        "staff_count": len(staff_rows),
        "covered_staff_count": len(windows),
        "unique_staff_windows": [
            {"start_date": start_date, "end_date": end_date}
            for start_date, end_date in unique_windows
        ],
        "invalid_staff_ids": invalid_staff_ids,
        "benchmark_rebuild_allowed": status in {
            "common_staff_actual_window",
            "requested_window_without_staff_evidence",
        },
        "policy": (
            "The benchmark uses the common proven staff replay boundary. "
            "Divergent or missing staff boundaries remain blocked instead of being coerced."
        ),
    }


def _refresh_ai_staff_long_horizon_benchmark(payload: dict[str, object]) -> dict[str, object]:
    if not payload:
        return {}
    changed = False
    static_identity = {
        "benchmark_type": "fixed_strategy_durability",
        "learning_career_simulation": False,
        "learning_claim_allowed": False,
    }
    for key, value in static_identity.items():
        if payload.get(key) != value:
            payload[key] = value
            changed = True
    adaptive_training_system = {
        "schema": "codexstock_ai_staff_adaptive_training_v1",
        "separate_from_static_benchmark": True,
        "challenge_mode": True,
        "strategy_trials_per_staff_per_season": 6,
        "role_specific_strategy_library": True,
        "verified_past_strategy_memory": True,
        "point_in_time_only": True,
        "live_order_allowed": False,
    }
    if payload.get("adaptive_training_system") != adaptive_training_system:
        payload["adaptive_training_system"] = adaptive_training_system
        changed = True
    expected_run_once_key = LONG_HORIZON_VERIFICATION_CONTRACT_VERSION
    stored_staff = [
        row
        for row in payload.get("staff", [])
        if isinstance(row, dict)
    ] if isinstance(payload.get("staff"), list) else []
    measurement_window = _long_horizon_common_measurement_window(
        stored_staff,
        requested_start_date=str(payload.get("start_date") or "2000-01-03"),
        requested_end_date=str(payload.get("end_date") or min(today_kst(), "2026-12-31")),
    )
    if payload.get("benchmark_measurement_window") != measurement_window:
        payload["benchmark_measurement_window"] = measurement_window
        changed = True
    staff_cost_policy_current = bool(stored_staff) and all(
        _long_horizon_staff_cost_policy_current(row) for row in stored_staff
    )
    rerun_required = bool(
        payload.get("run_once_key") != expected_run_once_key
        or not staff_cost_policy_current
        or (
            bool(stored_staff)
            and measurement_window.get("status") != "common_staff_actual_window"
        )
    )
    if payload.get("verification_contract_version") != expected_run_once_key:
        payload["verification_contract_version"] = expected_run_once_key
        changed = True
    if payload.get("rerun_required") is not rerun_required:
        payload["rerun_required"] = rerun_required
        changed = True
    if rerun_required:
        payload["rerun_reason"] = (
            "stored_result_predates_market_specific_cost_policy_or_current_universe_contract"
        )
    elif payload.pop("rerun_reason", None) is not None:
        changed = True
    if payload.get("schema") != "codexstock_ai_staff_long_horizon_v2":
        payload["schema"] = "codexstock_ai_staff_long_horizon_v2"
        changed = True
    claim_policy_version = "strict-long-horizon-evidence.v2-measurement-promotion-split"
    if payload.get("claim_policy_version") != claim_policy_version:
        league_record_id = str(payload.get("league_record_id") or "")
        league_record = next(
            (
                row
                for row in _read_jsonl(AI_TOURNAMENT_FILE, limit=300)
                if isinstance(row, dict) and str(row.get("id") or "") == league_record_id
            ),
            {},
        )
        ranking_map = {
            str(row.get("contestant_id") or ""): row
            for row in league_record.get("rankings", [])
            if isinstance(row, dict)
        }
        for staff_row in payload.get("staff", []) if isinstance(payload.get("staff"), list) else []:
            if not isinstance(staff_row, dict):
                continue
            ranking = ranking_map.get(str(staff_row.get("contestant_id") or ""))
            if not ranking:
                continue
            state = _ai_tournament_return_reconciliation_state(ranking)
            staff_row["return_claim_status"] = state.get("status")
            staff_row["return_claim_blocked"] = bool(state.get("claim_blocked"))
            staff_row["return_warning_count"] = int(_number(state.get("warning_count")))
            staff_row["return_blocker_count"] = int(_number(state.get("blocker_count")))
            staff_row["official_return_blocker_count"] = int(_number(state.get("official_return_blocker_count")))
        payload["claim_policy_version"] = claim_policy_version
        payload["claim_status_refreshed_at"] = datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds")
        changed = True
    benchmark = payload.get("benchmark") if isinstance(payload.get("benchmark"), dict) else {}
    benchmark_target_start = str(measurement_window.get("start_date") or "")
    benchmark_target_end = str(measurement_window.get("end_date") or "")
    benchmark_period_stale = bool(
        measurement_window.get("benchmark_rebuild_allowed") is True
        and benchmark_target_start
        and benchmark_target_end
        and (
            str(benchmark.get("first_date") or "") != benchmark_target_start
            or str(benchmark.get("last_date") or "") != benchmark_target_end
        )
    )
    needs_fx_retry = bool(
        benchmark.get("schema") != "codexstock_long_horizon_benchmark_v3"
        or benchmark.get("fx_policy_version") != "ecos-boundary-fallback.v1"
        or benchmark.get("net_costed_krw_cagr_pct") in {None, ""}
        or benchmark.get("currency_conversion_validated") is not True
        or benchmark.get("transaction_cost_validated") is not True
        or not _long_horizon_benchmark_cost_policy_current(benchmark)
        or benchmark_period_stale
    )
    if not benchmark.get("dividend_adjusted_cagr_pct") or needs_fx_retry:
        try:
            benchmark = _long_horizon_spy_benchmark(
                benchmark_target_start,
                benchmark_target_end,
            )
            payload["benchmark"] = benchmark
            changed = True
        except Exception as exc:
            payload["benchmark_error"] = str(exc)
    next_run_universe = _long_horizon_fixed_etf_universe_status(
        coverage_end=str(payload.get("end_date") or min(today_kst(), "2026-12-31")),
    )
    if payload.get("next_run_universe_contract") != next_run_universe:
        payload["next_run_universe_contract"] = next_run_universe
        changed = True
    if not any(isinstance(row, dict) for row in payload.get("staff", []) if isinstance(payload.get("staff"), list)):
        payload["staff"] = [
            {
                "contestant_id": str(contestant.get("id") or contestant.get("contestant_id") or ""),
                "name": contestant.get("name") or contestant.get("id") or "",
                "role": contestant.get("role") or "",
                "performance_evidence": {
                    "schema": "codexstock_long_horizon_performance_evidence_v1",
                    "passed": False,
                    "status": "verification_pending",
                    "blockers": ["long_horizon_staff_run_missing"],
                },
            }
            for contestant in ai_tournament_contestants()
            if str(contestant.get("id") or contestant.get("contestant_id") or "")
        ]
        payload["staff_contract_fallback"] = True
        payload["staff_contract_fallback_reason"] = "stored_long_horizon_staff_rows_missing"
        changed = True
    for staff_row in payload.get("staff", []) if isinstance(payload.get("staff"), list) else []:
        if not isinstance(staff_row, dict):
            continue
        if not isinstance(staff_row.get("walk_forward"), dict) or not staff_row.get("walk_forward"):
            staff_row["walk_forward"] = {
                "ok": False,
                "passed": False,
                "status": "재검증 필요",
                "blockers": ["legacy_per_staff_walk_forward_missing"],
                "message": "This stored row predates independent per-staff walk-forward evidence.",
            }
            changed = True
        previous_evidence = staff_row.get("performance_evidence")
        performance_evidence = _long_horizon_performance_evidence(
            staff_row,
            benchmark,
            requested_start_date=str(payload.get("start_date") or "2000-01-03"),
            requested_end_date=str(payload.get("end_date") or min(today_kst(), "2026-12-31")),
        )
        staff_row["performance_evidence"] = performance_evidence
        if previous_evidence != performance_evidence:
            changed = True
        computed_cagr_value = performance_evidence.get("computed_cagr_pct")
        cagr = _number(computed_cagr_value if computed_cagr_value is not None else staff_row.get("cagr_pct"))
        mdd = abs(_number(staff_row.get("max_drawdown_pct")))
        excess_cagr_value = performance_evidence.get("excess_cagr_pctp")
        excess_cagr = _number(excess_cagr_value) if excess_cagr_value is not None else None
        benchmark_cagr_value = performance_evidence.get("benchmark_cagr_pct")
        benchmark_cagr = _number(benchmark_cagr_value) if benchmark_cagr_value is not None else None
        reasons: list[str] = [
            str(reason)
            for reason in performance_evidence.get("blockers", [])
            if str(reason)
        ]
        if cagr < 20.0:
            reasons.append("cagr_below_20pct")
        if mdd > 25.0:
            reasons.append("mdd_above_25pct")
        if excess_cagr is None or excess_cagr < 8.0:
            reasons.append("spy_total_return_excess_below_8pctp")
        check_map = {
            str(row.get("id") or ""): bool(row.get("passed"))
            for row in performance_evidence.get("checks", [])
            if isinstance(row, dict)
        }
        cost_validated = check_map.get("transaction_cost_ledger", False)
        price_validated = check_map.get("price_currency_unit", False)
        bias_validated = check_map.get("point_in_time_universe", False)
        walk_forward_validated = check_map.get("walk_forward_measurement_evidence", False)
        return_reconciliation_validated = check_map.get("return_reconciliation", False)
        timing_validated = check_map.get("lookahead_safe_execution", False)
        benchmark_validated = bool(
            check_map.get("benchmark_total_return_currency", False)
            and check_map.get("benchmark_period_alignment", False)
        )
        production_goal_pass = bool(
            performance_evidence.get("passed")
            and cagr >= 20.0
            and mdd <= 25.0
            and excess_cagr is not None
            and excess_cagr >= 8.0
        )
        staff_row["official_total_return_pct"] = performance_evidence.get("official_total_return_pct")
        staff_row["official_cagr_pct"] = performance_evidence.get("official_cagr_pct")
        staff_row["performance_claim_status"] = performance_evidence.get("status")
        staff_row["performance_confidence_score"] = performance_evidence.get("confidence_score")
        staff_row["return_display_basis"] = (
            "official_net_costed_actual_horizon"
            if performance_evidence.get("passed")
            else "reference_only_unverified"
        )
        staff_row["goal_evaluation"] = {
            "cagr_target_pct": 20.0,
            "research_stretch_target_pct": 25.0,
            "research_extreme_target_pct": 30.0,
            "mdd_limit_pct": 25.0,
            "spy_total_return_cagr_pct": round(benchmark_cagr, 2) if benchmark_cagr is not None else None,
            "spy_net_costed_krw_cagr_pct": round(benchmark_cagr, 2) if benchmark_cagr is not None else None,
            "benchmark_currency": "KRW" if benchmark_validated else None,
            "excess_cagr_pctp": round(excess_cagr, 2) if excess_cagr is not None else None,
            "cagr_target_met": bool(computed_cagr_value is not None and cagr >= 20.0),
            "mdd_limit_met": mdd <= 25.0,
            "benchmark_excess_target_met": bool(excess_cagr is not None and excess_cagr >= 8.0),
            "cost_tax_slippage_validated": cost_validated,
            "return_reconciliation_validated": return_reconciliation_validated,
            "price_currency_unit_validated": price_validated,
            "lookahead_safe_execution_validated": timing_validated,
            "survivorship_lookahead_validated": bias_validated,
            "walk_forward_validated": walk_forward_validated,
            "benchmark_period_currency_validated": benchmark_validated,
            "performance_evidence_validated": bool(performance_evidence.get("passed")),
            "performance_confidence_score": performance_evidence.get("confidence_score"),
            "production_goal_pass": production_goal_pass,
            "blocked_reasons": list(dict.fromkeys(reasons)),
        }
    payload["goal_contract"] = {
        "production_cagr_target_pct": 20.0,
        "research_stretch_range_pct": [25.0, 30.0],
        "max_drawdown_limit_pct": 25.0,
        "minimum_spy_total_return_excess_pctp": 8.0,
        "requires_cost_tax_slippage": True,
        "requires_actual_data_boundaries": True,
        "requires_exact_krw_benchmark_period": True,
        "requires_strict_return_reconciliation": True,
        "requires_minimum_trade_actions": 30,
        "claim_scope": "timing_exit_and_risk_management_only",
        "stock_selection_performance_claim_allowed": False,
        "live_stock_promotion_allowed": False,
        "performance_evidence_schema": "codexstock_long_horizon_performance_evidence_v1",
        "policy": "No staff strategy is promoted on CAGR alone; every gate must pass exact-period KRW benchmark, full cost ledger, point-in-time universe, and out-of-sample validation.",
    }
    if changed:
        _save_ai_staff_long_horizon_benchmark(payload)
    return payload


def load_ai_staff_long_horizon_benchmark() -> dict[str, object]:
    try:
        payload = json.loads(AI_STAFF_LONG_HORIZON_FILE.read_text(encoding="utf-8"))
        return _refresh_ai_staff_long_horizon_benchmark(payload) if isinstance(payload, dict) else {}
    except Exception:
        start_date = "2000-01-03"
        end_date = min(today_kst(), "2026-12-31")
        try:
            benchmark = _long_horizon_spy_benchmark(start_date, end_date)
        except Exception as exc:
            benchmark = {
                "schema": "codexstock_long_horizon_benchmark_v3",
                "status": "benchmark_unavailable",
                "currency_conversion_validated": False,
                "transaction_cost_validated": False,
                "net_costed_krw_cagr_pct": None,
                "input_data_hash": "",
                "usdkrw_future_value_used": False,
                "error": str(exc),
            }
        staff = []
        for contestant in ai_tournament_contestants():
            contestant_id = str(contestant.get("id") or contestant.get("contestant_id") or "")
            if not contestant_id:
                continue
            staff.append(
                {
                    "contestant_id": contestant_id,
                    "name": contestant.get("name") or contestant_id,
                    "role": contestant.get("role") or "",
                    "performance_evidence": {
                        "schema": "codexstock_long_horizon_performance_evidence_v1",
                        "passed": False,
                        "status": "verification_pending",
                        "blockers": ["long_horizon_staff_run_missing"],
                    },
                }
            )
        payload = {
            "schema": "codexstock_ai_staff_long_horizon_v2",
            "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
            "start_date": start_date,
            "end_date": end_date,
            "benchmark": benchmark,
            "staff": staff,
            "fallback_contract": True,
            "fallback_reason": "long_horizon_file_missing_or_invalid",
            "live_order_allowed": False,
        }
        return _refresh_ai_staff_long_horizon_benchmark(payload)


def run_ai_staff_long_horizon_benchmark(force: bool = False) -> dict[str, object]:
    cached = load_ai_staff_long_horizon_benchmark()
    expected_ids = {str(row.get("id") or "") for row in ai_tournament_contestants()}
    cached_ids = {
        str(row.get("contestant_id") or "")
        for row in cached.get("staff", [])
        if isinstance(row, dict)
    }
    if (
        cached.get("ok")
        and cached.get("run_once_key") == LONG_HORIZON_VERIFICATION_CONTRACT_VERSION
        and expected_ids
        and expected_ids.issubset(cached_ids)
        and not force
    ):
        return {**cached, "cached": True, "path": str(AI_STAFF_LONG_HORIZON_FILE)}
    start_date = "2000-01-03"
    end_date = min(today_kst(), "2026-12-31")
    universe_contract = _ensure_long_horizon_fixed_etf_universe(coverage_end=end_date)
    symbols = [str(value) for value in universe_contract.get("symbols", [])]
    league = run_ai_mini_league(
        league_name="AI staff 2000-2026 long-horizon benchmark",
        start_date=start_date,
        end_date=end_date,
        initial_cash=100_000_000.0,
        symbols=symbols,
        symbol_selection_mode="common",
        allow_simulated_fallback=False,
        challenge_mode=False,
        challenge_trials=1,
        persist_replay_detail=False,
        replay_cost_profile={
            "commission_bps": DEFAULT_PAPER_COMMISSION_BPS,
            "slippage_bps": DEFAULT_PAPER_SLIPPAGE_BPS,
            "kr_sell_tax_bps": DEFAULT_PAPER_KR_SELL_TAX_BPS,
            "fx_conversion_spread_bps": DEFAULT_PAPER_FX_SPREAD_BPS,
        },
        universe_dataset_id=LONG_HORIZON_FIXED_ETF_UNIVERSE_ID,
        persist_tournament_record=False,
        source="ai-staff-2000-2026-benchmark",
    )
    start = datetime.fromisoformat(start_date).date()
    end = datetime.fromisoformat(end_date).date()
    horizon_years = max(1.0, (end - start).days / 365.25)
    staff_rows: list[dict[str, object]] = []
    for row in league.get("rankings", []) if isinstance(league.get("rankings"), list) else []:
        if not isinstance(row, dict):
            continue
        data_coverage = row.get("data_coverage") if isinstance(row.get("data_coverage"), dict) else {}
        actual_start_date = str(data_coverage.get("actual_start_date") or row.get("actual_start_date") or "")
        actual_end_date = str(data_coverage.get("actual_end_date") or row.get("actual_end_date") or "")
        try:
            actual_horizon_years = max(
                0.0,
                (
                    datetime.fromisoformat(actual_end_date).date()
                    - datetime.fromisoformat(actual_start_date).date()
                ).days
                / 365.25,
            )
        except (TypeError, ValueError):
            actual_horizon_years = 0.0
        total_return_pct = _number(row.get("total_return_pct"))
        ending_multiple = max(0.0, 1.0 + total_return_pct / 100.0)
        cagr_pct = (
            -100.0
            if ending_multiple <= 0
            else (ending_multiple ** (1.0 / actual_horizon_years) - 1.0) * 100.0
            if actual_horizon_years > 0
            else 0.0
        )
        reconciliation = _ai_tournament_return_reconciliation_state(row)
        staff_rows.append(
            {
                "contestant_id": row.get("contestant_id"),
                "display_name": row.get("display_name") or row.get("name"),
                "rank": row.get("rank"),
                "strategy_name": row.get("strategy_name"),
                "strategy_mode": row.get("strategy_mode"),
                "start_date": start_date,
                "end_date": end_date,
                "horizon_years": round(actual_horizon_years, 6),
                "requested_horizon_years": round(horizon_years, 6),
                "actual_start_date": actual_start_date or None,
                "actual_end_date": actual_end_date or None,
                "actual_horizon_years": round(actual_horizon_years, 6),
                "data_coverage": data_coverage,
                "initial_cash": row.get("initial_cash"),
                "final_equity": row.get("final_equity"),
                "total_return_pct": round(total_return_pct, 2),
                "cagr_pct": round(cagr_pct, 2),
                "max_drawdown_pct": row.get("max_drawdown_pct"),
                "trade_count": row.get("trade_count"),
                "win_rate_pct": row.get("win_rate_pct"),
                "cost_model": row.get("cost_model", {}),
                "transaction_cost_audit": row.get("transaction_cost_audit", {}),
                "price_currency_unit_audit": row.get("price_currency_unit_audit", {}),
                "execution_timing_model": row.get("execution_timing_model", {}),
                "bias_audit": row.get("bias_audit", {}),
                "walk_forward": row.get("walk_forward", {}),
                "total_transaction_cost": row.get("total_transaction_cost"),
                "transaction_cost_pct_of_initial_cash": row.get("transaction_cost_pct_of_initial_cash"),
                "return_claim_status": reconciliation.get("status"),
                "return_claim_blocked": bool(reconciliation.get("claim_blocked")),
            }
        )
    payload = {
        "ok": bool(league.get("ok")) and expected_ids.issubset({str(row.get("contestant_id") or "") for row in staff_rows}),
        "schema": "codexstock_ai_staff_long_horizon_v2",
        "benchmark_type": "fixed_strategy_durability",
        "learning_career_simulation": False,
        "learning_claim_allowed": False,
        "run_once_key": LONG_HORIZON_VERIFICATION_CONTRACT_VERSION,
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "league_record_id": league.get("id"),
        "start_date": start_date,
        "end_date": end_date,
        "horizon_years": round(horizon_years, 2),
        "symbols": symbols,
        "universe_contract": universe_contract,
        "staff_count": len(staff_rows),
        "staff": staff_rows,
        "errors": league.get("errors", []),
        "safety": "Historical real-data replay only. Detailed replay logs are not persisted and no live order path is called.",
        "adaptive_training_system": {
            "schema": "codexstock_ai_staff_adaptive_training_v1",
            "separate_from_static_benchmark": True,
            "challenge_mode": True,
            "strategy_trials_per_staff_per_season": 6,
            "role_specific_strategy_library": True,
            "verified_past_strategy_memory": True,
            "point_in_time_only": True,
            "live_order_allowed": False,
        },
        "limitations": [
            "This is a fixed-strategy durability benchmark and must never be described as 26 years of staff learning.",
            "Results are a historical simulation, not a promise of future returns.",
            "The fixed pre-2000 ETF universe validates timing, exits, and risk management only; it does not validate individual-stock selection skill.",
            "CAGR is derived from simulated final equity over actual market-data boundary dates, never requested labels.",
            "All unverified values are reference-only and cannot affect staff scores or live candidates.",
        ],
    }
    _save_ai_staff_long_horizon_benchmark(payload)
    payload = _refresh_ai_staff_long_horizon_benchmark(payload)
    return {**payload, "cached": False, "path": str(AI_STAFF_LONG_HORIZON_FILE)}


def _build_ai_tournament_activity_standings() -> dict[str, object]:
    """Return the append-only staff history without waiting for deep replay rehashing."""
    events = _read_jsonl(AI_STAFF_CAREER_LEDGER_FILE)
    persona_lookup = {str(row.get("id") or ""): row for row in ai_tournament_contestants()}
    staff: dict[str, dict[str, object]] = {}
    for event in events:
        rankings = event.get("rankings") if isinstance(event.get("rankings"), list) else []
        generated_at = str(event.get("generated_at") or "")
        for row in rankings:
            if not isinstance(row, dict):
                continue
            contestant_id = str(row.get("contestant_id") or row.get("display_name") or "unknown")
            persona = persona_lookup.get(contestant_id, {})
            entry = staff.setdefault(
                contestant_id,
                {
                    "contestant_id": contestant_id,
                    "name": persona.get("name") or contestant_id,
                    "persona_name": persona.get("persona_name"),
                    "call_sign": persona.get("call_sign"),
                    "profile": persona.get("profile"),
                    "role": persona.get("role") or "-",
                    "display_name": row.get("display_name") or persona.get("display_name") or contestant_id,
                    "strategy_names": [],
                    "activity_seasons": 0,
                    "activity_wins": 0,
                    "activity_podiums": 0,
                    "activity_total_trades": 0,
                    "trusted_run_count": 0,
                    "trusted_win_count": 0,
                    "quarantined_run_count": 0,
                    "quarantined_win_count": 0,
                    "_activity_returns": [],
                    "_activity_mdds": [],
                    "_trusted_returns": [],
                    "_quarantined_returns": [],
                    "first_run_at": generated_at,
                    "latest_run_at": generated_at,
                },
            )
            rank = int(_number(row.get("rank")))
            return_pct = _number(row.get("return_pct"))
            mdd_pct = abs(_number(row.get("max_drawdown_pct")))
            trade_count = int(_number(row.get("trade_count")))
            strategy_name = str(row.get("strategy_name") or "").strip()
            if strategy_name and strategy_name not in entry["strategy_names"]:
                entry["strategy_names"].append(strategy_name)
            entry["activity_seasons"] = int(entry.get("activity_seasons") or 0) + 1
            entry["activity_wins"] = int(entry.get("activity_wins") or 0) + (1 if rank == 1 else 0)
            entry["activity_podiums"] = int(entry.get("activity_podiums") or 0) + (1 if 1 <= rank <= 3 else 0)
            entry["activity_total_trades"] = int(entry.get("activity_total_trades") or 0) + trade_count
            entry["_activity_returns"].append(return_pct)
            entry["_activity_mdds"].append(mdd_pct)
            eligible = row.get("official_claim_eligible") is True
            if eligible:
                official_rank = int(_number(row.get("official_rank")))
                official_return = _number(row.get("official_return_pct"))
                entry["trusted_run_count"] = int(entry.get("trusted_run_count") or 0) + 1
                entry["trusted_win_count"] = int(entry.get("trusted_win_count") or 0) + (1 if official_rank == 1 else 0)
                entry["_trusted_returns"].append(official_return)
            else:
                entry["quarantined_run_count"] = int(entry.get("quarantined_run_count") or 0) + 1
                entry["quarantined_win_count"] = int(entry.get("quarantined_win_count") or 0) + (1 if rank == 1 else 0)
                entry["_quarantined_returns"].append(return_pct)
            entry["latest_reference_rank"] = rank or None
            entry["latest_reference_return_pct"] = return_pct
            entry["latest_return_pct"] = _number(row.get("official_return_pct")) if eligible else None
            entry["latest_return_claim_status"] = "trusted" if eligible else "verification_pending"
            entry["latest_at"] = generated_at
            if generated_at:
                entry["latest_run_at"] = generated_at

    long_horizon = load_ai_staff_long_horizon_benchmark()
    long_horizon_map = {
        str(row.get("contestant_id") or ""): row
        for row in long_horizon.get("staff", [])
        if isinstance(row, dict)
    }
    standings: list[dict[str, object]] = []
    for entry in staff.values():
        activity_returns = [float(value) for value in entry.pop("_activity_returns", [])]
        activity_mdds = [float(value) for value in entry.pop("_activity_mdds", [])]
        trusted_returns = [float(value) for value in entry.pop("_trusted_returns", [])]
        quarantined_returns = [float(value) for value in entry.pop("_quarantined_returns", [])]
        activity_seasons = int(entry.get("activity_seasons") or 0)
        trusted_runs = int(entry.get("trusted_run_count") or 0)
        quarantined_runs = int(entry.get("quarantined_run_count") or 0)
        activity_avg = round(sum(activity_returns) / len(activity_returns), 2) if activity_returns else None
        avg_mdd = round(sum(activity_mdds) / len(activity_mdds), 2) if activity_mdds else None
        entry.update(
            {
                # These aliases keep old clients useful while the explicit activity_* fields
                # prevent training history from being mistaken for official performance.
                "seasons": activity_seasons,
                "wins": int(entry.get("activity_wins") or 0),
                "podiums": int(entry.get("activity_podiums") or 0),
                "total_trades": int(entry.get("activity_total_trades") or 0),
                "avg_return_pct": activity_avg,
                "activity_avg_return_pct": activity_avg,
                "best_return_pct": max(activity_returns) if activity_returns else None,
                "activity_best_return_pct": max(activity_returns) if activity_returns else None,
                "avg_drawdown_pct": avg_mdd,
                "activity_avg_drawdown_pct": avg_mdd,
                "trusted_avg_return_pct": round(sum(trusted_returns) / len(trusted_returns), 2) if trusted_returns else None,
                "trusted_best_return_pct": max(trusted_returns) if trusted_returns else None,
                "quarantined_avg_return_pct": round(sum(quarantined_returns) / len(quarantined_returns), 2) if quarantined_returns else None,
                "quarantined_best_return_pct": max(quarantined_returns) if quarantined_returns else None,
                "return_claim_status": "trusted" if trusted_runs and not quarantined_runs else ("mixed" if trusted_runs else "review_required"),
                "return_claim_note": "훈련 활동 전적을 즉시 표시하고 공식 수익률 대사는 백그라운드에서 갱신합니다.",
                "risk_efficiency": round((activity_avg or 0.0) / max(avg_mdd or 0.0, 1.0), 3),
                "career_ledger_backed": True,
                "long_horizon_2000_2026": long_horizon_map.get(str(entry.get("contestant_id") or "")),
            }
        )
        standings.append(entry)
    standings.sort(
        key=lambda row: (
            int(row.get("trusted_win_count") or 0),
            int(row.get("activity_wins") or 0),
            _number(row.get("activity_avg_return_pct")),
        ),
        reverse=True,
    )
    for index, row in enumerate(standings, start=1):
        row["standing_rank"] = index
        row["realism_standing_rank"] = index
    return_claim_summary = {
        "trusted_staff_count": sum(1 for row in standings if row.get("return_claim_status") == "trusted"),
        "mixed_staff_count": sum(1 for row in standings if row.get("return_claim_status") == "mixed"),
        "review_required_staff_count": sum(1 for row in standings if row.get("return_claim_status") == "review_required"),
        "trusted_run_count": sum(int(row.get("trusted_run_count") or 0) for row in standings),
        "quarantined_run_count": sum(int(row.get("quarantined_run_count") or 0) for row in standings),
    }
    return {
        "ok": True,
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "run_count": len(events),
        "recent_display_run_count": len(events),
        "finished_run_count": len(events),
        "failed_run_count": 0,
        "latest_champion": {},
        "latest_reference_champion": {},
        "score_gate": {
            "status": "snapshot_only",
            "promotion_allowed": False,
            "live_order_allowed": False,
        },
        "return_claim_summary": return_claim_summary,
        "long_horizon_2000_2026": long_horizon,
        "standings": standings,
        "summary_mode": "career_activity_snapshot",
        "refreshing": False,
        "official_deep_refresh_required": True,
        "note": "직원 훈련 전적은 저장된 누적 원장에서 즉시 표시합니다. 무거운 공식 심층 대사는 별도 검증 작업에서만 실행합니다.",
    }


def _build_ai_tournament_standings(limit: int = 100) -> dict[str, object]:
    records = latest_ai_tournaments(limit=max(1, min(int(limit or 100), 300)))
    score_index = _historical_replay_certified_score_index()
    persona_lookup = {str(row.get("id")): row for row in ai_tournament_contestants()}
    stats: dict[str, dict[str, object]] = {}
    finished_runs = 0
    failed_runs = 0
    latest_champion: dict[str, object] = {}
    latest_reference_champion: dict[str, object] = {}
    for record in records:
        rankings = record.get("rankings") if isinstance(record, dict) else []
        if not isinstance(rankings, list) or not rankings:
            failed_runs += 1
            continue
        finished_runs += 1
        reference_champion = record.get("reference_champion") if isinstance(record.get("reference_champion"), dict) else {}
        if not reference_champion and rankings:
            reference_champion = min(
                (row for row in rankings if isinstance(row, dict)),
                key=lambda row: int(_number(row.get("reference_rank"))) or 999,
                default={},
            )
        if not latest_reference_champion and reference_champion:
            latest_reference_champion = {
                "display_name": reference_champion.get("display_name") or reference_champion.get("name"),
                "return_pct": reference_champion.get("reference_total_return_pct", reference_champion.get("total_return_pct")),
                "generated_at": record.get("generated_at"),
                "league_name": record.get("league_name"),
                "reference_only": True,
            }
        champion = record.get("official_champion") if isinstance(record.get("official_champion"), dict) else {}
        if not latest_champion and isinstance(champion, dict):
            if not champion:
                champion = {}
            champion_persona = persona_lookup.get(str(champion.get("contestant_id") or ""))
            champion_claim = champion.get("official_claim") if isinstance(champion.get("official_claim"), dict) else {}
            if champion and champion_claim.get("eligible") is True:
                latest_champion = {
                    "name": champion.get("name"),
                    "persona_name": champion.get("persona_name") or (champion_persona or {}).get("persona_name"),
                    "call_sign": champion.get("call_sign") or (champion_persona or {}).get("call_sign"),
                    "display_name": champion.get("display_name") or (
                        f"{(champion_persona or {}).get('persona_name')} · {champion.get('name')}"
                        if (champion_persona or {}).get("persona_name")
                        else champion.get("name")
                    ),
                    "role": champion.get("role"),
                    "return_pct": champion_claim.get("official_total_return_pct"),
                    "return_claim_status": champion_claim.get("status"),
                    "return_claim_blocked": False,
                    "return_reconciliation": champion_claim.get("reconciliation", {}),
                    "certified_replay_id": champion_claim.get("certified_replay_id"),
                    "certified_milestone": champion_claim.get("certified_milestone"),
                    "generated_at": record.get("generated_at"),
                    "league_name": record.get("league_name"),
                }
        for row in rankings:
            if not isinstance(row, dict):
                continue
            contestant_id = str(row.get("contestant_id") or row.get("name") or "unknown")
            persona = persona_lookup.get(contestant_id, {})
            persona_name = row.get("persona_name") or persona.get("persona_name")
            display_name = row.get("display_name") or (f"{persona_name} · {row.get('name') or contestant_id}" if persona_name else row.get("name") or contestant_id)
            entry = stats.setdefault(contestant_id, {
                "contestant_id": contestant_id,
                "name": row.get("name") or contestant_id,
                "persona_name": persona_name,
                "call_sign": row.get("call_sign") or persona.get("call_sign"),
                "profile": row.get("profile") or persona.get("profile"),
                "display_name": display_name,
                "role": row.get("role") or "-",
                "strategy_names": [],
                "seasons": 0,
                "wins": 0,
                "podiums": 0,
                "total_trades": 0,
                "activity_seasons": 0,
                "activity_wins": 0,
                "activity_podiums": 0,
                "activity_total_trades": 0,
                "_returns": [],
                "_activity_returns": [],
                "_trusted_returns": [],
                "_quarantined_returns": [],
                "_mdds": [],
                "_activity_mdds": [],
                "_scores": [],
                "_reference_scores": [],
                "_reconciliation_status_counts": {},
                "best_return_pct": None,
                "activity_best_return_pct": None,
                "trusted_best_return_pct": None,
                "quarantined_best_return_pct": None,
                "worst_drawdown_pct": None,
                "latest_rank": None,
                "latest_return_pct": None,
                "latest_return_claim_status": None,
                "latest_score": None,
                "latest_at": None,
                "trusted_run_count": 0,
                "quarantined_run_count": 0,
                "trusted_win_count": 0,
                "quarantined_win_count": 0,
            })
            strategy_name = str(row.get("strategy_name") or row.get("strategy_mode") or "").strip()
            if strategy_name and strategy_name not in entry["strategy_names"]:
                entry["strategy_names"].append(strategy_name)
            activity_rank = int(_number(row.get("reference_rank", row.get("rank"))) or 0)
            official_rank = int(_number(row.get("official_rank")) or 0)
            return_pct = _number(row.get("total_return_pct"))
            reconciliation_state = _ai_tournament_return_reconciliation_state(row)
            official_claim = row.get("official_claim") if isinstance(row.get("official_claim"), dict) else {}
            if not official_claim:
                official_claim = _ai_tournament_official_claim_state(row)
            reconciliation_status = str(reconciliation_state.get("status") or "unknown")
            claim_blocked = not bool(official_claim.get("eligible"))
            official_return_pct = _number(official_claim.get("official_total_return_pct"))
            activity_mdd_pct = abs(_number(row.get("max_drawdown_pct")))
            official_mdd_pct = abs(_number(official_claim.get("official_max_drawdown_pct")))
            reference_score = _number(row.get("reference_score", row.get("score")))
            official_score = _number(row.get("official_score"))
            entry["activity_seasons"] = int(entry["activity_seasons"]) + 1
            entry["activity_wins"] = int(entry["activity_wins"]) + (1 if activity_rank == 1 else 0)
            entry["activity_podiums"] = int(entry["activity_podiums"]) + (1 if 1 <= activity_rank <= 3 else 0)
            entry["activity_total_trades"] = int(entry["activity_total_trades"]) + int(_number(row.get("trade_count")))
            entry["_activity_returns"].append(return_pct)
            entry["_activity_mdds"].append(activity_mdd_pct)
            entry["_reference_scores"].append(reference_score)
            status_counts = entry["_reconciliation_status_counts"] if isinstance(entry.get("_reconciliation_status_counts"), dict) else {}
            status_counts[reconciliation_status] = int(status_counts.get(reconciliation_status, 0) or 0) + 1
            entry["_reconciliation_status_counts"] = status_counts
            if claim_blocked:
                entry["_quarantined_returns"].append(return_pct)
                entry["quarantined_run_count"] = int(entry.get("quarantined_run_count") or 0) + 1
                entry["quarantined_win_count"] = int(entry.get("quarantined_win_count") or 0) + (1 if activity_rank == 1 else 0)
            else:
                entry["seasons"] = int(entry["seasons"]) + 1
                entry["wins"] = int(entry["wins"]) + (1 if official_rank == 1 else 0)
                entry["podiums"] = int(entry["podiums"]) + (1 if 1 <= official_rank <= 3 else 0)
                entry["total_trades"] = int(entry["total_trades"]) + int(_number(official_claim.get("official_trade_count")))
                entry["_returns"].append(official_return_pct)
                entry["_trusted_returns"].append(official_return_pct)
                entry["trusted_run_count"] = int(entry.get("trusted_run_count") or 0) + 1
                entry["trusted_win_count"] = int(entry.get("trusted_win_count") or 0) + (1 if official_rank == 1 else 0)
                entry["_mdds"].append(official_mdd_pct)
            if not claim_blocked:
                entry["_scores"].append(official_score)
            best_return = entry.get("best_return_pct")
            trusted_best_return = entry.get("trusted_best_return_pct")
            quarantined_best_return = entry.get("quarantined_best_return_pct")
            worst_mdd = entry.get("worst_drawdown_pct")
            activity_best_return = entry.get("activity_best_return_pct")
            entry["activity_best_return_pct"] = return_pct if activity_best_return is None else max(_number(activity_best_return), return_pct)
            if claim_blocked:
                entry["quarantined_best_return_pct"] = return_pct if quarantined_best_return is None else max(_number(quarantined_best_return), return_pct)
            else:
                entry["best_return_pct"] = official_return_pct if best_return is None else max(_number(best_return), official_return_pct)
                entry["trusted_best_return_pct"] = official_return_pct if trusted_best_return is None else max(_number(trusted_best_return), official_return_pct)
                entry["worst_drawdown_pct"] = official_mdd_pct if worst_mdd is None else max(_number(worst_mdd), official_mdd_pct)
            if entry.get("latest_rank") is None:
                entry["latest_rank"] = official_rank or None
                entry["latest_reference_rank"] = activity_rank
                entry["latest_return_pct"] = official_return_pct if not claim_blocked else None
                entry["latest_reference_return_pct"] = return_pct
                entry["latest_return_claim_status"] = reconciliation_status
                entry["latest_official_claim_status"] = official_claim.get("status")
                entry["latest_official_claim_reasons"] = official_claim.get("reasons", [])
                entry["latest_score"] = official_score if not claim_blocked else None
                entry["latest_reference_score"] = reference_score
                entry["latest_at"] = record.get("generated_at")

    standings: list[dict[str, object]] = []
    for entry in stats.values():
        seasons = int(entry.get("seasons") or 0)
        activity_seasons = int(entry.get("activity_seasons") or 0)
        returns = [float(value) for value in entry.pop("_returns", [])]
        activity_returns = [float(value) for value in entry.pop("_activity_returns", [])]
        trusted_returns = [float(value) for value in entry.pop("_trusted_returns", [])]
        quarantined_returns = [float(value) for value in entry.pop("_quarantined_returns", [])]
        mdds = [float(value) for value in entry.pop("_mdds", [])]
        activity_mdds = [float(value) for value in entry.pop("_activity_mdds", [])]
        scores = [float(value) for value in entry.pop("_scores", [])]
        reference_scores = [float(value) for value in entry.pop("_reference_scores", [])]
        reconciliation_counts = entry.pop("_reconciliation_status_counts", {})
        if not isinstance(reconciliation_counts, dict):
            reconciliation_counts = {}
        avg_return = round(sum(returns) / len(returns), 2) if returns else 0.0
        trusted_avg_return = round(sum(trusted_returns) / len(trusted_returns), 2) if trusted_returns else None
        quarantined_avg_return = round(sum(quarantined_returns) / len(quarantined_returns), 2) if quarantined_returns else None
        avg_mdd = round(sum(mdds) / len(mdds), 2) if mdds else 0.0
        avg_score = round(sum(scores) / len(scores), 2) if scores else 0.0
        reference_avg_score = round(sum(reference_scores) / len(reference_scores), 2) if reference_scores else 0.0
        wins = int(entry.get("wins") or 0)
        podiums = int(entry.get("podiums") or 0)
        trusted_runs = int(entry.get("trusted_run_count") or 0)
        quarantined_runs = int(entry.get("quarantined_run_count") or 0)
        return_claim_status = "trusted" if trusted_runs and not quarantined_runs else ("mixed" if trusted_runs and quarantined_runs else "review_required")
        entry.update({
            "avg_return_pct": avg_return,
            "activity_avg_return_pct": round(sum(activity_returns) / len(activity_returns), 2) if activity_returns else None,
            "trusted_avg_return_pct": trusted_avg_return,
            "quarantined_avg_return_pct": quarantined_avg_return,
            "return_claim_status": return_claim_status,
            "return_reconciliation_status_counts": reconciliation_counts,
            "return_claim_note": (
                "Only trusted_* return fields should be used for official performance claims."
                if return_claim_status != "trusted"
                else "All sampled return claims passed reconciliation."
            ),
            "avg_drawdown_pct": avg_mdd,
            "activity_avg_drawdown_pct": round(sum(activity_mdds) / len(activity_mdds), 2) if activity_mdds else None,
            "avg_score": avg_score,
            "reference_avg_score": reference_avg_score,
            "win_rate_pct": round((wins / seasons) * 100, 1) if seasons else None,
            "activity_win_rate_pct": round((int(entry.get("activity_wins") or 0) / activity_seasons) * 100, 1) if activity_seasons else None,
            "trusted_win_rate_pct": round((int(entry.get("trusted_win_count") or 0) / max(trusted_runs, 1)) * 100, 1) if trusted_runs else None,
            "quarantined_win_rate_pct": round((int(entry.get("quarantined_win_count") or 0) / max(quarantined_runs, 1)) * 100, 1) if quarantined_runs else None,
            "podium_rate_pct": round((podiums / seasons) * 100, 1) if seasons else None,
            "risk_efficiency": round(avg_return / max(avg_mdd, 1.0), 3),
            "trusted_risk_efficiency": round((trusted_avg_return or 0.0) / max(avg_mdd, 1.0), 3) if trusted_avg_return is not None else None,
            "title": (
                "왕중왕"
                if wins >= 3 else
                "현 챔피언 후보"
                if wins >= 1 else
                "도전자"
            ),
        })
        standings.append(entry)
    career = ai_staff_career_summary()
    career_map = {
        str(row.get("contestant_id") or ""): row
        for row in career.get("staff", [])
        if isinstance(row, dict)
    }
    long_horizon = load_ai_staff_long_horizon_benchmark()
    long_horizon_map = {
        str(row.get("contestant_id") or ""): row
        for row in long_horizon.get("staff", [])
        if isinstance(row, dict)
    }
    for entry in standings:
        contestant_id = str(entry.get("contestant_id") or "")
        career_row = career_map.get(contestant_id)
        if career_row:
            for key in (
                "seasons",
                "wins",
                "podiums",
                "total_trades",
                "best_return_pct",
                "avg_return_pct",
                "win_rate_pct",
                "trusted_run_count",
                "trusted_win_count",
                "quarantined_run_count",
                "quarantined_win_count",
                "trusted_avg_return_pct",
                "trusted_best_return_pct",
                "trusted_win_rate_pct",
                "quarantined_avg_return_pct",
                "quarantined_best_return_pct",
                "official_claim_reason_counts",
                "first_run_at",
                "latest_run_at",
                "career_rank",
            ):
                entry[key] = career_row.get(key)
            wins = int(entry.get("wins") or 0)
            entry["title"] = "dynasty" if wins >= 3 else "champion_candidate" if wins >= 1 else "challenger"
            entry["career_ledger_backed"] = True
        entry["long_horizon_2000_2026"] = long_horizon_map.get(contestant_id)
    standings.sort(
        key=lambda row: (
            int(row.get("trusted_win_count") or 0),
            _number((row.get("long_horizon_2000_2026") or {}).get("cagr_pct") if isinstance(row.get("long_horizon_2000_2026"), dict) else None),
            _number(row.get("trusted_avg_return_pct")),
            -_number(row.get("avg_drawdown_pct")),
        ),
        reverse=True,
    )
    for index, row in enumerate(standings, start=1):
        row["standing_rank"] = index
    return_claim_summary = {
        "trusted_staff_count": sum(1 for row in standings if row.get("return_claim_status") == "trusted"),
        "mixed_staff_count": sum(1 for row in standings if row.get("return_claim_status") == "mixed"),
        "review_required_staff_count": sum(1 for row in standings if row.get("return_claim_status") == "review_required"),
        "trusted_run_count": sum(int(row.get("trusted_run_count") or 0) for row in standings),
        "quarantined_run_count": sum(int(row.get("quarantined_run_count") or 0) for row in standings),
        "policy": "Official standings require deep-certified replay replacements and full-record ranking coverage; raw wins and returns remain clearly labeled activity history only.",
    }
    target_count = int(_number(score_index.get("target_count")))
    verified_count = int(_number(score_index.get("verified_through_count")))
    score_gate = {
        "schema": "codexstock_ai_tournament_standings_score_gate_v1",
        "status": score_index.get("status"),
        "deep_verified_replay_count": verified_count,
        "target_replay_count": target_count,
        "progress_pct": round((verified_count / target_count) * 100, 2) if target_count else 0.0,
        "certified_replacement_count": int(_number(score_index.get("certified_replacement_count"))),
        "official_record_count": sum(1 for row in records if row.get("record_score_allowed") is True),
        "reference_only_record_count": sum(1 for row in records if row.get("record_score_allowed") is not True),
        "official_staff_count": return_claim_summary["trusted_staff_count"],
        "reference_only_staff_count": (
            return_claim_summary["mixed_staff_count"]
            + return_claim_summary["review_required_staff_count"]
        ),
        "blockers": score_index.get("blockers", []),
        "promotion_allowed": False,
        "live_order_allowed": False,
        "policy": (
            "Only deep-audited replacement replays with reconciled entry, exit, reason, return, "
            "cost, price-unit, and point-in-time bias evidence may enter official standings."
        ),
    }
    return {
        "ok": True,
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "run_count": int(career.get("event_count") or len(records)),
        "recent_display_run_count": len(records),
        "finished_run_count": finished_runs,
        "failed_run_count": failed_runs,
        "latest_champion": latest_champion,
        "latest_reference_champion": latest_reference_champion,
        "score_gate": score_gate,
        "return_claim_summary": return_claim_summary,
        "career_ledger": career,
        "long_horizon_2000_2026": long_horizon,
        "standings": standings,
        "note": "AI 직원 왕중왕전 전적표는 과거장 Paper 리그 기록만 집계합니다. 실전 주문 기록이 아닙니다.",
    }


def _ai_tournament_standings_source_signature(limit: int) -> tuple[object, ...]:
    return (
        max(1, min(int(limit or 100), 300)),
        _historical_replay_status_file_signature(AI_TOURNAMENT_FILE),
        _historical_replay_status_file_signature(AI_STAFF_CAREER_LEDGER_FILE),
        _historical_replay_status_file_signature(AI_STAFF_LONG_HORIZON_FILE),
        _historical_replay_status_file_signature(
            HISTORICAL_REPLAY_REGENERATION_CAMPAIGN_FILE
        ),
        _historical_replay_status_file_signature(
            HISTORICAL_REPLAY_EVIDENCE_MILESTONE_FILE
        ),
    )


def ai_tournament_standings(limit: int = 100) -> dict[str, object]:
    """Build standings once per evidence snapshot and collapse concurrent reads."""
    global AI_TOURNAMENT_STANDINGS_LAST_GOOD
    checked_limit = max(1, min(int(limit or 100), 300))
    signature = _ai_tournament_standings_source_signature(checked_limit)
    with AI_TOURNAMENT_STANDINGS_CACHE_LOCK:
        cached = AI_TOURNAMENT_STANDINGS_CACHE.get(signature)
        if isinstance(cached, dict):
            return {
                **cached,
                "cache_hit": True,
                "cache_source": "memory_evidence_signature",
            }
    with AI_TOURNAMENT_STANDINGS_BUILD_LOCK:
        signature = _ai_tournament_standings_source_signature(checked_limit)
        with AI_TOURNAMENT_STANDINGS_CACHE_LOCK:
            cached = AI_TOURNAMENT_STANDINGS_CACHE.get(signature)
            if isinstance(cached, dict):
                return {
                    **cached,
                    "cache_hit": True,
                    "cache_source": "memory_evidence_signature",
                }
        payload = _build_ai_tournament_standings(checked_limit)
    with AI_TOURNAMENT_STANDINGS_CACHE_LOCK:
        if len(AI_TOURNAMENT_STANDINGS_CACHE) >= 16:
            AI_TOURNAMENT_STANDINGS_CACHE.pop(
                next(iter(AI_TOURNAMENT_STANDINGS_CACHE)),
                None,
            )
        AI_TOURNAMENT_STANDINGS_CACHE[signature] = dict(payload)
        AI_TOURNAMENT_STANDINGS_LAST_GOOD = dict(payload)
    return {
        **payload,
        "cache_hit": False,
        "cache_source": "computed_evidence_signature",
    }


def _refresh_ai_tournament_standings(checked_limit: int) -> None:
    global AI_TOURNAMENT_STANDINGS_LAST_GOOD
    error = ""
    try:
        payload = ai_tournament_standings(checked_limit)
        if payload.get("ok") is True:
            with AI_TOURNAMENT_STANDINGS_CACHE_LOCK:
                AI_TOURNAMENT_STANDINGS_LAST_GOOD = {
                    key: value
                    for key, value in payload.items()
                    if key not in {"cache_hit", "cache_source"}
                }
    except Exception as exc:  # noqa: BLE001 - background refresh must preserve the UI
        error = f"{type(exc).__name__}: {exc}"
    finally:
        with AI_TOURNAMENT_STANDINGS_REFRESH_STATE_LOCK:
            AI_TOURNAMENT_STANDINGS_REFRESH_STATE.update(
                {
                    "running": False,
                    "finished_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
                    "last_error": error,
                }
            )


def _start_ai_tournament_standings_refresh(checked_limit: int) -> bool:
    with AI_TOURNAMENT_STANDINGS_REFRESH_STATE_LOCK:
        if AI_TOURNAMENT_STANDINGS_REFRESH_STATE.get("running") is True:
            return False
        AI_TOURNAMENT_STANDINGS_REFRESH_STATE.update(
            {
                "running": True,
                "started_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
                "finished_at": "",
                "last_error": "",
            }
        )
    threading.Thread(
        target=_refresh_ai_tournament_standings,
        args=(checked_limit,),
        name="ai-tournament-standings-refresh",
        daemon=True,
    ).start()
    return True


def ai_tournament_standings_responsive(limit: int = 100) -> dict[str, object]:
    """Never start a deep-evidence rebuild from an interactive dashboard read."""
    checked_limit = max(1, min(int(limit or 100), 300))
    signature = _ai_tournament_standings_source_signature(checked_limit)
    with AI_TOURNAMENT_STANDINGS_CACHE_LOCK:
        cached = AI_TOURNAMENT_STANDINGS_CACHE.get(signature)
        last_good = dict(AI_TOURNAMENT_STANDINGS_LAST_GOOD or {})
    if isinstance(cached, dict):
        return {
            **cached,
            "cache_hit": True,
            "cache_source": "memory_evidence_signature",
            "refreshing": False,
        }
    if last_good:
        return {
            **last_good,
            "cache_hit": True,
            "cache_source": "last_deep_snapshot",
            "refreshing": False,
            "official_deep_refresh_required": True,
        }
    fallback = _build_ai_tournament_activity_standings()
    return {
        **fallback,
        "cache_hit": False,
        "cache_source": "career_ledger_fast_fallback",
    }


def _daily_replay_drill_symbols(raw_rows: list[dict[str, object]], limit: int = 8) -> list[str]:
    """당일 장 복기용으로 거래대금/상승률/관심종목을 섞어 훈련 종목을 고른다."""
    selected: list[str] = []

    def push(symbol: object) -> None:
        normalized = str(symbol or "").strip().upper()
        if normalized.isdigit():
            normalized = normalized.zfill(6)
        if normalized and normalized not in selected:
            selected.append(normalized)

    liquid = [
        row for row in raw_rows
        if re.match(r"^\d{6}$", str(row.get("symbol", "")))
        if _number(row.get("close")) >= 1000
        and _number(row.get("amount")) >= 5_000_000_000
        and _number(row.get("marcap")) >= 50_000_000_000
    ]
    for row in sorted(liquid, key=lambda item: _number(item.get("amount")), reverse=True)[:4]:
        push(row.get("symbol"))
    for row in sorted(liquid, key=lambda item: (_number(item.get("change_pct")), _number(item.get("amount"))), reverse=True)[:6]:
        push(row.get("symbol"))
    for symbol in load_user_watchlist().get("symbols", [])[:6]:
        push(symbol)
    fallback = ["083450", "005930", "000660", "005380", "042700", "058470", "NVDA", "AAPL"]
    for symbol in fallback:
        push(symbol)
    return selected[: max(3, min(int(limit or 8), 12))]


def _daily_replay_drill_configs(repeats: int) -> list[dict[str, object]]:
    base = [
        {"strategy": "intraday_theme_leader", "label": "주도테마 단타 3/12", "fast": 3, "slow": 12, "stop": 1.5, "take": 3.0, "hold": 1, "allocation": 35, "max_positions": 2},
        {"strategy": "intraday_momentum_breakout", "label": "단타 고점 돌파 3/10", "fast": 3, "slow": 10, "stop": 2.0, "take": 3.5, "hold": 3, "allocation": 35, "max_positions": 2},
        {"strategy": "short_swing", "label": "단기 스윙 5/20", "fast": 5, "slow": 20, "stop": 3.0, "take": 5.0, "hold": 3, "allocation": 30, "max_positions": 2},
        {"strategy": "breakout", "label": "신고가 돌파 8/24", "fast": 8, "slow": 24, "stop": 4.0, "take": 8.0, "hold": 5, "allocation": 25, "max_positions": 3},
        {"strategy": "protected_ma", "label": "보호형 추세 8/30", "fast": 8, "slow": 30, "stop": 4.5, "take": 8.0, "hold": 7, "allocation": 25, "max_positions": 3},
        {"strategy": "ma_cross", "label": "기본 추세 12/32", "fast": 12, "slow": 32, "stop": 5.0, "take": 0.0, "hold": 0, "allocation": 25, "max_positions": 3},
        {"strategy": "intraday_pullback_reclaim", "label": "단타 눌림목 회복 4/12", "fast": 4, "slow": 12, "stop": 1.8, "take": 3.0, "hold": 4, "allocation": 35, "max_positions": 2},
        {"strategy": "breakout", "label": "거래대금 돌파 5/20", "fast": 5, "slow": 20, "stop": 3.0, "take": 6.0, "hold": 3, "allocation": 35, "max_positions": 2},
        {"strategy": "protected_ma", "label": "방어 추세 10/40", "fast": 10, "slow": 40, "stop": 3.5, "take": 6.0, "hold": 10, "allocation": 20, "max_positions": 3},
        {"strategy": "intraday_mean_reversion", "label": "단타 과매도 반전 3/15", "fast": 3, "slow": 15, "stop": 2.2, "take": 3.2, "hold": 4, "allocation": 30, "max_positions": 2},
    ]
    configs = []
    for index in range(max(1, min(int(repeats or 10), 100))):
        template = dict(base[index % len(base)])
        variant = index // len(base)
        # A 50-run drill must vary the experiment, not just repeat ten labels.
        # Shift timing and risk parameters while keeping each strategy's shape.
        template["fast"] = max(2, int(template.get("fast", 5)) + variant)
        template["slow"] = max(template["fast"] + 4, int(template.get("slow", 20)) + variant * 4)
        template["stop"] = round(max(0.8, float(template.get("stop", 2.0)) + variant * 0.35), 2)
        if float(template.get("take", 0.0) or 0.0) > 0:
            template["take"] = round(float(template["take"]) + variant * 0.75, 2)
        if int(template.get("hold", 0) or 0) > 0:
            template["hold"] = int(template["hold"]) + variant
        template["variant"] = variant + 1
        template["label"] = f"{template.get('label', template.get('strategy', 'strategy'))} / 변형 {variant + 1}"
        template["iteration"] = index + 1
        configs.append(template)
    return configs


def run_post_market_daily_replay_drill(
    target_date: str | None = None,
    repeats: int = 10,
    symbols: list[str] | None = None,
    initial_cash: float = 150_000.0,
    lookback_days: int = 160,
    source: str = "post-market-daily-drill",
    remember: bool = True,
) -> dict[str, object]:
    """장마감 후 당일 주도주를 대상으로 10회 반복 복기 훈련을 수행한다."""
    repeats = max(1, min(int(repeats or 10), 100))
    initial_cash = max(50_000.0, float(initial_cash or 150_000.0))
    lookback_days = max(80, min(int(lookback_days or 160), 365))
    requested_date = target_date or today_kst()
    try:
        requested_dt = datetime.fromisoformat(str(requested_date)).date()
    except ValueError:
        requested_dt = datetime.now(_zone("Asia/Seoul", 9)).date()
    start_date = (requested_dt - timedelta(days=lookback_days)).isoformat()
    end_date = requested_dt.isoformat()
    work_date = end_date
    raw_rows: list[dict[str, object]] = []
    market_note = ""
    try:
        work_date, raw_rows = fetch_kr_market_rows()
        if work_date <= end_date:
            end_date = work_date
    except Exception as exc:
        market_note = f"KRX 당일 데이터 조회 실패: {exc}"
    today_movers: list[dict[str, object]] = []
    today_mover_note = ""
    try:
        mover_radar = build_kis_fluctuation_radar(direction="up", market="all", limit=12)
        mover_rows = mover_radar.get("items") if isinstance(mover_radar, dict) else []
        if isinstance(mover_rows, list):
            for row in mover_rows:
                if not isinstance(row, dict):
                    continue
                symbol = _normalize_symbol_for_watchlist(row.get("symbol"))
                if not symbol:
                    continue
                live_candidate_eligible = bool(row.get("live_candidate_eligible"))
                today_movers.append(
                    {
                        "symbol": symbol,
                        "name": str(row.get("name") or symbol),
                        "change_pct": round(_number(row.get("change_pct")), 2),
                        "amount_eok": round(_number(row.get("amount_eok")), 1),
                        "data_quality": str(row.get("data_quality") or "unknown"),
                        "turnover_source": str(row.get("turnover_source") or "unknown"),
                        "live_candidate_eligible": live_candidate_eligible,
                        "analysis_only": not live_candidate_eligible,
                        "selection_reason": "today_gainer_radar",
                    }
                )
        if not bool(mover_radar.get("ok")):
            today_mover_note = str(mover_radar.get("message") or "당일 상승 레이더 검증대기")
    except Exception as exc:
        today_mover_note = f"당일 상승 레이더 조회 실패: {exc}"
    requested_work_date = requested_dt.isoformat()
    krx_date_matches_request = work_date == requested_work_date
    krx_rows_by_symbol = {
        _normalize_symbol_for_watchlist(row.get("symbol")): row
        for row in raw_rows
        if isinstance(row, dict) and _normalize_symbol_for_watchlist(row.get("symbol"))
    }
    for mover in today_movers:
        symbol = str(mover.get("symbol") or "")
        krx_row = krx_rows_by_symbol.get(symbol, {})
        krx_amount = _number(krx_row.get("amount")) if isinstance(krx_row, dict) else 0.0
        crosscheck = {
            "requested_date": requested_work_date,
            "reference_date": work_date,
            "date_match": krx_date_matches_request,
            "symbol_match": bool(krx_row),
            "amount_positive": krx_amount > 0,
            "amount_eok": round(krx_amount / 100_000_000, 1) if krx_amount > 0 else 0.0,
            "source": str(krx_row.get("source") or "") if isinstance(krx_row, dict) else "",
        }
        mover["turnover_crosscheck"] = crosscheck
        if _number(mover.get("amount_eok")) > 0:
            mover["replay_turnover_verified"] = True
            mover["replay_analysis_eligible"] = True
            mover["turnover_verification_source"] = "kis_intraday"
            mover["krx_crosscheck_status"] = (
                "matched" if crosscheck["date_match"] and crosscheck["symbol_match"] and crosscheck["amount_positive"]
                else "unavailable_or_not_matched"
            )
        elif krx_date_matches_request and krx_amount > 0:
            # Daily KRX turnover is valid for replay analysis only. It must not
            # upgrade an incomplete intraday KIS row into a live candidate.
            mover["amount_eok"] = crosscheck["amount_eok"]
            mover["data_quality"] = "complete_for_replay"
            mover["turnover_source"] = "krx_daily_crosscheck"
            mover["replay_turnover_verified"] = True
            mover["replay_analysis_eligible"] = True
            mover["turnover_verification_source"] = "krx_daily_crosscheck"
            mover["krx_crosscheck_status"] = "matched"
            mover["live_candidate_eligible"] = False
            mover["analysis_only"] = True
        else:
            mover["replay_turnover_verified"] = False
            mover["replay_analysis_eligible"] = False
            mover["turnover_verification_source"] = "none"
            mover["krx_crosscheck_status"] = "unavailable_or_not_matched"
    selected_symbols: list[str] = []
    for symbol in symbols or []:
        normalized = str(symbol or "").strip().upper()
        if normalized:
            selected_symbols.append(normalized.zfill(6) if normalized.isdigit() else normalized)
    if not selected_symbols:
        base_symbols = _daily_replay_drill_symbols(raw_rows, limit=12)
        for symbol in [row.get("symbol") for row in today_movers[:6]] + base_symbols:
            normalized = str(symbol or "").strip().upper()
            if normalized and normalized not in selected_symbols:
                selected_symbols.append(normalized)
    selected_symbols = selected_symbols[:12]
    shared_replay_data_bundle: dict[str, object] | None = None
    shared_bundle_error = ""
    shared_bundle_started = time.monotonic()
    try:
        shared_replay_data_bundle = _build_historical_replay_data_bundle(
            selected_symbols,
            start_date,
            end_date,
            allow_simulated_fallback=False,
            min_bars=40,
        )
    except Exception as exc:
        shared_bundle_error = str(exc)[:500]
    shared_bundle_build_seconds = round(time.monotonic() - shared_bundle_started, 3)
    configs = _daily_replay_drill_configs(repeats)
    runs: list[dict[str, object]] = []
    memories: list[dict[str, object]] = []
    errors: list[dict[str, object]] = []
    for config in configs:
        iteration = int(config.get("iteration", len(runs) + 1) or len(runs) + 1)
        symbol_offset = (iteration - 1) % max(1, len(selected_symbols))
        rotated = selected_symbols[symbol_offset:] + selected_symbols[:symbol_offset]
        train_symbols = rotated[: min(5, len(rotated))]
        try:
            replay = run_historical_paper_replay(
                symbols=train_symbols,
                start_date=start_date,
                end_date=end_date,
                fast=int(config.get("fast", 5) or 5),
                slow=int(config.get("slow", 20) or 20),
                initial_cash=initial_cash,
                allocation_pct=float(config.get("allocation", 30) or 30),
                max_positions=int(config.get("max_positions", 2) or 2),
                source=f"{source}-{iteration:02d}",
                strategy_mode=str(config.get("strategy", "intraday_theme_leader")),
                stop_loss_pct=float(config.get("stop", 2.0) or 2.0),
                take_profit_pct=float(config.get("take", 0.0) or 0.0),
                holding_limit_days=int(config.get("hold", 0) or 0),
                cycles_per_day=10,
                allow_simulated_fallback=False,
                replay_data_bundle=shared_replay_data_bundle,
            )
            bundle_evidence = (
                replay.get("replay_data_bundle_evidence")
                if isinstance(replay.get("replay_data_bundle_evidence"), dict)
                else {}
            )
            compact = {
                "iteration": iteration,
                "label": config.get("label"),
                "replay_id": replay.get("id"),
                "symbols": replay.get("symbols", []),
                "strategy_mode": replay.get("strategy_mode"),
                "strategy_label": replay.get("strategy_label"),
                "return_pct": replay.get("total_return_pct"),
                "max_drawdown_pct": replay.get("max_drawdown_pct"),
                "trade_count": replay.get("trade_count"),
                "win_rate_pct": replay.get("win_rate_pct"),
                "final_equity": replay.get("final_equity"),
                "cost_model": replay.get("cost_model", {}),
                "price_currency_unit_audit": replay.get("price_currency_unit_audit", {}),
                "total_transaction_cost": replay.get("total_transaction_cost"),
                "transaction_cost_pct_of_initial_cash": replay.get("transaction_cost_pct_of_initial_cash"),
                "latest_period_returns": replay.get("latest_period_returns"),
                "replay_data_bundle_evidence": {
                    "used": bool(bundle_evidence.get("used")),
                    "passed": bool(bundle_evidence.get("passed")),
                    "bundle_content_hash": str(bundle_evidence.get("bundle_content_hash") or ""),
                    "slice_content_hash": str(bundle_evidence.get("slice_content_hash") or ""),
                    "source_fetch_reused": bool(bundle_evidence.get("source_fetch_reused")),
                    "future_rows_excluded_before_strategy": bool(
                        bundle_evidence.get("future_rows_excluded_before_strategy")
                    ),
                    "no_rows_outside_requested_period": bool(
                        bundle_evidence.get("no_rows_outside_requested_period")
                    ),
                },
                "top_trades": replay.get("trade_journal_top10", [])[:3],
                "bottom_trades": replay.get("trade_journal_bottom10", [])[:3],
                "summary": replay.get("summary"),
            }
            runs.append(compact)
            if remember:
                try:
                    memory = MEMORY.append_historical_replay_memory(replay, source=f"{source}-memory-{iteration:02d}")
                    memories.append({
                        "iteration": iteration,
                        "ok": bool(memory.get("ok")),
                        "memory_id": (memory.get("memory") or {}).get("id") if isinstance(memory.get("memory"), dict) else None,
                        "note_path": memory.get("path"),
                    })
                except Exception as exc:
                    memories.append({"iteration": iteration, "ok": False, "error": str(exc)})
        except Exception as exc:
            errors.append({"iteration": iteration, "label": config.get("label"), "symbols": train_symbols, "error": str(exc)})
    if runs:
        best = max(runs, key=lambda row: _number(row.get("return_pct")))
        worst = min(runs, key=lambda row: _number(row.get("return_pct")))
        avg_return = round(sum(_number(row.get("return_pct")) for row in runs) / len(runs), 2)
        total_trades = sum(int(_number(row.get("trade_count"))) for row in runs)
    else:
        best = {}
        worst = {}
        avg_return = 0.0
        total_trades = 0
    run_bundle_evidence = [
        row.get("replay_data_bundle_evidence")
        for row in runs
        if isinstance(row.get("replay_data_bundle_evidence"), dict)
    ]
    run_bundle_hashes = sorted(
        {
            str(row.get("bundle_content_hash") or "")
            for row in run_bundle_evidence
            if str(row.get("bundle_content_hash") or "")
        }
    )
    shared_bundle_hash = str(
        (shared_replay_data_bundle.get("content_hash") or "")
        if isinstance(shared_replay_data_bundle, dict)
        else ""
    )
    source_fetch_reused_for_all_runs = bool(runs) and all(
        bool(row.get("used")) and bool(row.get("passed")) and bool(row.get("source_fetch_reused"))
        for row in run_bundle_evidence
    ) and len(run_bundle_evidence) == len(runs)
    shared_bundle_hash_consistent = bool(shared_bundle_hash) and run_bundle_hashes == [shared_bundle_hash]
    drill = {
        "ok": bool(runs),
        "id": f"DDRILL-{int(time.time() * 1000)}",
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "target_date": end_date,
        "requested_date": requested_date,
        "source": source,
        "mode": "post_market_daily_variant_drill",
        "scope_label": "오늘 날짜 기준 데이터 변형 테스트 (실제 오늘 수익률 아님)",
        "repeats_requested": repeats,
        "completed_repeats": len(runs),
        "failed_repeats": len(errors),
        "initial_cash": round(initial_cash, 2),
        "lookback_days": lookback_days,
        "start_date": start_date,
        "end_date": end_date,
        "symbols": selected_symbols,
        "market_note": market_note,
        "today_movers": today_movers,
        "today_mover_count": len(today_movers),
        "analysis_only_mover_count": sum(bool(row.get("analysis_only")) for row in today_movers),
        "replay_turnover_verified_mover_count": sum(bool(row.get("replay_turnover_verified")) for row in today_movers),
        "krx_crosschecked_mover_count": sum(row.get("turnover_source") == "krx_daily_crosscheck" for row in today_movers),
        "today_mover_note": today_mover_note,
        "symbol_selection_contract": {
            "explicit_symbols_override": bool(symbols),
            "priority": [
                "explicit_symbols",
                "today_gainer_radar_top6",
                "krx_turnover_and_change",
                "user_watchlist",
                "fallback",
            ],
            "analysis_only_does_not_enable_live_order": True,
            "krx_turnover_crosscheck_only_enables_replay_analysis": True,
            "krx_turnover_crosscheck_does_not_enable_live_candidate": True,
            "replay_selection_has_live_order_side_effect": False,
        },
        "shared_replay_data_bundle": {
            "created": isinstance(shared_replay_data_bundle, dict),
            "used_for_all_completed_runs": source_fetch_reused_for_all_runs,
            "bundle_hash_consistent": shared_bundle_hash_consistent,
            "content_hash": shared_bundle_hash,
            "run_bundle_hashes": run_bundle_hashes,
            "symbol_count": len(selected_symbols),
            "build_seconds": shared_bundle_build_seconds,
            "fallback_to_per_run_fetch": shared_replay_data_bundle is None,
            "fallback_reason": shared_bundle_error,
            "immutable_execution_scope": True,
            "live_order_allowed": False,
        },
        "runs": runs,
        "errors": errors,
        "memory_records": memories,
        "best": best,
        "worst": worst,
        "average_return_pct": avg_return,
        "total_trade_count": total_trades,
        "lesson": (
            f"{end_date} 장마감 복기 드릴 {len(runs)}/{repeats}회 완료. "
            f"평균 {avg_return:+.2f}%, 최고 {best.get('label', '-')} {best.get('return_pct', 0)}%, "
            f"최저 {worst.get('label', '-')} {worst.get('return_pct', 0)}%. "
            "오늘의 주도주/거래대금 후보를 다음 장 후보 필터와 매매일지 복기에 반영합니다."
            if runs
            else "장마감 복기 드릴을 완료하지 못했습니다."
        ),
        "safety": "장마감 반복 훈련은 과거/당일 데이터 복기용입니다. 실제 주문을 전송하지 않습니다.",
    }
    _append_jsonl(DAILY_REPLAY_DRILL_FILE, drill)
    JOURNAL.add("DAILY_REPLAY_DRILL", str(drill["lesson"]), {"id": drill["id"], "completed": len(runs), "errors": len(errors)})
    return drill


def format_daily_replay_drill_reply(drill: dict[str, object]) -> str:
    best = drill.get("best", {}) if isinstance(drill.get("best"), dict) else {}
    worst = drill.get("worst", {}) if isinstance(drill.get("worst"), dict) else {}
    repeats_label = int(_number(drill.get("repeats_requested")) or 10)
    lines = [
        f"장마감 당일장 {repeats_label}회 복기훈련 결과입니다.",
        f"- 기준일: {drill.get('target_date', '-')}",
        f"- 완료: {drill.get('completed_repeats', 0)}/{drill.get('repeats_requested', 0)}회",
        f"- 평균 수익률: {_number(drill.get('average_return_pct')):+.2f}%",
        f"- 총 매매: {int(_number(drill.get('total_trade_count')))}회",
        f"- 최고: {best.get('label', '-')} / {best.get('return_pct', 0)}%",
        f"- 최저: {worst.get('label', '-')} / {worst.get('return_pct', 0)}%",
        f"- 종목: {', '.join(str(item) for item in drill.get('symbols', [])[:8])}",
        "",
        str(drill.get("lesson") or ""),
        "실제 주문은 실행하지 않았고, 장기기억/복기 기록으로만 저장했습니다.",
    ]
    errors = drill.get("errors", []) if isinstance(drill.get("errors"), list) else []
    if errors:
        lines.append(f"일부 실패: {len(errors)}회. 데이터 부족/조회 실패 구간은 다음 훈련에서 제외합니다.")
    return "\n".join(lines)


def _missed_buy_trade_identity(row: dict[str, object]) -> dict[str, str]:
    """주문/후보/체결 로그의 위치가 제각각이라도 종목과 방향만 안전하게 뽑는다."""
    containers: list[dict[str, object]] = []
    if isinstance(row, dict):
        containers.append(row)
        for key in ("ticket", "plan", "approval"):
            nested = row.get(key)
            if isinstance(nested, dict):
                containers.append(nested)
                if key == "approval" and isinstance(nested.get("ticket"), dict):
                    containers.append(nested["ticket"])
        plan = row.get("plan") if isinstance(row.get("plan"), dict) else {}
        selection = plan.get("selection") if isinstance(plan.get("selection"), dict) else {}
        if isinstance(selection, dict):
            containers.append(selection)
    symbol = ""
    side = ""
    name = ""
    for item in containers:
        if not symbol:
            symbol = str(item.get("symbol") or item.get("pdno") or item.get("code") or "").upper().strip()
        if not side:
            side = str(item.get("side") or item.get("buy_sell") or item.get("ord_dvsn_name") or "").upper().strip()
        if not name:
            name = _useful_symbol_name(item.get("name") or item.get("symbol_name") or item.get("prdt_name"), symbol)
    if side in {"매수", "BUY_ORDER"}:
        side = "BUY"
    if side in {"매도", "SELL_ORDER"}:
        side = "SELL"
    return {"symbol": _normalize_symbol_for_watchlist(symbol), "side": side, "name": name}


def _missed_buy_review_name(row: dict[str, object]) -> str:
    symbol = _normalize_symbol_for_watchlist(row.get("symbol"))
    return _quick_trade_symbol_name(symbol, row.get("name"))


def _missed_buy_score(row: dict[str, object]) -> float:
    change = max(0.0, _number(row.get("change_pct")))
    amount_eok = _number(row.get("amount")) / 100_000_000
    marcap_eok = _number(row.get("marcap")) / 100_000_000
    return round(change * 4.0 + min(amount_eok, 3_000) / 25.0 + min(marcap_eok, 80_000) / 8_000.0, 2)


def _missed_buy_review_reason(
    symbol: str,
    *,
    buy_candidate_symbols: set[str],
    paper_buy_symbols: set[str],
    today_reason: dict[str, object],
) -> tuple[str, str, str]:
    diagnostics = today_reason.get("direction_diagnostics") if isinstance(today_reason.get("direction_diagnostics"), dict) else {}
    latest_side = str(diagnostics.get("latest_side") or "").upper()
    buy_candidate_count = int(_number(diagnostics.get("buy_candidate_count")))
    approval_issue = today_reason.get("approval_issue") if isinstance(today_reason.get("approval_issue"), dict) else {}
    approval_message = str(approval_issue.get("message") or "").strip()

    if symbol in buy_candidate_symbols:
        return (
            "후보는 만들었지만 실제 매수까지 가지 못함",
            approval_message or "승인, dry-submit, 최종전송 중 하나가 끝까지 이어지지 않았습니다.",
            "후보 생성 뒤 3분 안에 승인·dry-submit·최종전송 상태를 한 줄로 표시하고 만료 전에 다시 생성합니다.",
        )
    if symbol in paper_buy_symbols:
        return (
            "모의매매에서는 잡았지만 실전 후보로 승격하지 못함",
            "훈련 로그와 실전 후보 게이트가 분리되어 강한 종목이 실전 준비 목록에 올라오지 않았습니다.",
            "모의매매 상위 수익 종목을 장중 실전 후보 큐에도 자동 등록하는 연결고리를 추가합니다.",
        )
    if latest_side == "SELL":
        return (
            "매도/보유관리 루틴에 치우쳐 신규 매수 탐지가 약했음",
            "최근 실전 후보 방향이 매도였고, 강한 신규 매수 종목을 별도 큐로 승격하지 못했습니다.",
            "매도 후보와 별도로 상승률·거래대금 상위 신규 매수 후보를 매 사이클 강제 스캔합니다.",
        )
    if buy_candidate_count <= 0:
        return (
            "신규 매수 후보가 생성되지 않음",
            "오늘 실전 매수 후보 수가 0건이라 강한 종목을 주문 후보까지 끌어올리지 못했습니다.",
            "장중 5분마다 거래대금 상위+상승률 상위 교집합을 후보 점수표에 강제 반영합니다.",
        )
    return (
        "점수는 강했지만 후보 우선순위에서 밀림",
        "거래대금과 상승률은 좋았지만 기존 관심종목/보유종목 중심 판단이 더 우선되었습니다.",
        "당일 주도주 점수에 가중치를 주고, 관심종목 밖 강한 종목도 1차 후보에 올립니다.",
    )


def _compact_missed_buy_review_history(max_rows: int = 600, path: Path | None = None) -> dict[str, object]:
    target = path or MISSED_BUY_REVIEW_FILE
    safe_rows = max(50, min(int(max_rows or 600), 5000))
    if not target.exists():
        return {"ok": True, "status": "not_found", "compacted": False, "path": str(target)}
    with _jsonl_io_lock(target):
        tail_rows: deque[dict[str, object]] = deque(maxlen=safe_rows)
        prior_summarized_rows = 0
        valid_rows = data_rows = invalid_lines = blank_lines = summary_row_count = 0
        with target.open("r", encoding="utf-8", errors="ignore") as source:
            for line in source:
                clean = line.strip().lstrip("\ufeff")
                if not clean:
                    blank_lines += 1
                    continue
                try:
                    row = json.loads(clean)
                except json.JSONDecodeError:
                    invalid_lines += 1
                    continue
                if not isinstance(row, dict):
                    invalid_lines += 1
                    continue
                valid_rows += 1
                if str(row.get("type") or "") == "jsonl_compaction_summary":
                    summary_row_count += 1
                    prior_summarized_rows += max(0, int(_number(row.get("summarized_rows"))))
                    continue
                data_rows += 1
                tail_rows.append(row)
        if data_rows <= safe_rows and invalid_lines == 0 and blank_lines == 0 and summary_row_count <= 1:
            return {
                "ok": True,
                "status": "within_limit",
                "compacted": False,
                "data_rows": data_rows,
                "summarized_rows": prior_summarized_rows,
                "kept_rows": len(tail_rows),
                "path": str(target),
            }
        newly_summarized_rows = max(0, data_rows - len(tail_rows))
        summarized_rows = prior_summarized_rows + newly_summarized_rows
        summary_row = {
            "type": "jsonl_compaction_summary",
            "source_file": target.name,
            "summarized_rows": summarized_rows,
            "prior_summarized_rows": prior_summarized_rows,
            "newly_summarized_rows": newly_summarized_rows,
            "invalid_lines_removed": invalid_lines,
            "blank_lines_removed": blank_lines,
            "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
            "retention_policy": f"latest_{safe_rows}_detailed_reviews",
        }
        temp_path = target.with_name(f"{target.name}.tmp")
        with temp_path.open("w", encoding="utf-8", newline="\n") as handle:
            if summarized_rows:
                handle.write(json.dumps(summary_row, ensure_ascii=False, sort_keys=True) + "\n")
            for row in tail_rows:
                handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n")
            handle.flush()
            os.fsync(handle.fileno())
        temp_path.replace(target)
        retained_rows = ([summary_row] if summarized_rows else []) + list(tail_rows)
        index_synchronized = _synchronize_runtime_event_index_after_rewrite(target, retained_rows)
        return {
            "ok": invalid_lines == 0,
            "status": "compacted",
            "compacted": True,
            "valid_rows_before": valid_rows,
            "data_rows_before": data_rows,
            "kept_rows": len(tail_rows),
            "prior_summarized_rows": prior_summarized_rows,
            "newly_summarized_rows": newly_summarized_rows,
            "summarized_rows": summarized_rows,
            "invalid_lines_removed": invalid_lines,
            "blank_lines_removed": blank_lines,
            "runtime_event_index_synchronized": index_synchronized,
            "path": str(target),
        }


def _intraday_detection_evidence(symbol: str, target_date: str) -> dict[str, object]:
    """Explain whether the intraday radar never saw, saw late, or rejected a symbol."""
    normalized = _normalize_symbol_for_watchlist(symbol)
    sightings: list[dict[str, object]] = []
    for record in _read_jsonl(INTRADAY_MINUTE_RADAR_FILE, limit=500):
        generated_at = str(record.get("generated_at") or "")
        if not generated_at.startswith(str(target_date)):
            continue
        for item in record.get("items", []) if isinstance(record.get("items"), list) else []:
            if not isinstance(item, dict) or _normalize_symbol_for_watchlist(item.get("symbol")) != normalized:
                continue
            sightings.append(
                {
                    "generated_at": generated_at,
                    "score": round(_number(item.get("score")), 1),
                    "state": str(item.get("state") or ""),
                    "action": str(item.get("action") or ""),
                    "sources": item.get("marketwide_sources") or item.get("sources") or [],
                }
            )
    sightings.sort(key=lambda row: str(row.get("generated_at") or ""))
    if not sightings:
        return {
            "seen": False,
            "root_cause": "탐색 누락",
            "explanation": "장중 레이더 기록에 한 번도 올라오지 않아 점수·진입 검증 단계까지 가지 못했습니다.",
            "next_fix": "거래대금·거래량·상승률·수급 순위의 합집합을 장중 후보 풀에 강제 포함합니다.",
        }
    first = sightings[0]
    first_time = str(first.get("generated_at") or "")
    try:
        first_clock = datetime.fromisoformat(first_time).time()
    except ValueError:
        first_clock = dt_time(0, 0)
    max_score = max(_number(row.get("score")) for row in sightings)
    if first_clock >= dt_time(14, 30):
        root_cause = "탐색 지연"
        explanation = f"레이더 최초 포착이 {first_time[11:19]}로 늦어 유효 진입 검증 시간이 부족했습니다."
        next_fix = "시장 순위 합집합을 장초반부터 주기적으로 갱신하고 최초 포착 시각을 감시합니다."
    elif max_score < 58:
        root_cause = "검증 탈락"
        explanation = f"장중에는 포착했지만 최고 점수 {max_score:.1f}로 분봉·체결강도·호가 검증을 통과하지 못했습니다."
        next_fix = "탈락 사유를 수급·분봉·호가별로 분리 저장하고 장후 실제 상승 결과와 임계값을 재검증합니다."
    else:
        root_cause = "후보 이후 중단"
        explanation = f"장중 포착 및 최고 점수 {max_score:.1f}까지 갔지만 주문 후보 전환 또는 승인 단계가 이어지지 않았습니다."
        next_fix = "후보 생성부터 주문 게이트까지 단계별 상태와 중단 사유를 한 원장으로 대사합니다."
    return {
        "seen": True,
        "first_seen_at": first_time,
        "last_seen_at": sightings[-1].get("generated_at"),
        "sighting_count": len(sightings),
        "max_score": round(max_score, 1),
        "root_cause": root_cause,
        "explanation": explanation,
        "next_fix": next_fix,
    }


def build_missed_buy_review(
    target_date: str | None = None,
    limit: int = 10,
    source: str = "manual",
) -> dict[str, object]:
    """오늘 강했지만 실제 매수하지 못한 종목과 그 이유를 복기 로그로 남긴다."""
    target_date = target_date or today_kst()
    limit = max(3, min(int(limit or 10), 20))
    generated_at = datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds")
    market_note = ""
    work_date = target_date
    rows: list[dict[str, object]] = []
    try:
        work_date, rows = fetch_kr_market_rows()
    except Exception as exc:
        market_note = f"KRX 당일 데이터 조회 실패: {exc}"
        latest_reflection = latest_market_reflection_journal()
        for key in ("gainers", "top_amount", "missed_or_watch"):
            for row in latest_reflection.get(key, []) if isinstance(latest_reflection, dict) and isinstance(latest_reflection.get(key), list) else []:
                if isinstance(row, dict):
                    rows.append(row)
        work_date = str(latest_reflection.get("work_date") or target_date) if isinstance(latest_reflection, dict) else target_date

    live_rows = [row for row in _read_jsonl(LIVE_ORDER_SUBMIT_FILE, limit=1000) if _quick_trade_matches_date(row, target_date)]
    ticket_rows = [row for row in OPS.tickets(limit=1500) if _quick_trade_matches_date(row, target_date)]
    today_summary = build_today_trade_quick_summary(target_date)
    today_reason = today_summary.get("why_no_real_trade") if isinstance(today_summary.get("why_no_real_trade"), dict) else {}

    bought_symbols: set[str] = set()
    buy_candidate_symbols: set[str] = set()
    paper_buy_symbols: set[str] = set()
    for row in live_rows:
        ident = _missed_buy_trade_identity(row)
        if ident["side"] == "BUY" and str(row.get("status", "")).upper() == "LIVE_SUBMITTED":
            bought_symbols.add(ident["symbol"])
    try:
        broker = build_today_broker_executions_summary(target_date)
        for row in broker.get("executions", []) if isinstance(broker.get("executions"), list) else []:
            ident = _missed_buy_trade_identity(row)
            if ident["side"] == "BUY" and ident["symbol"]:
                bought_symbols.add(ident["symbol"])
    except Exception as exc:
        broker = {"ok": False, "message": f"실계좌 체결 조회 제외: {exc}", "executions": []}
    for row in ticket_rows:
        ident = _missed_buy_trade_identity(row)
        if ident["side"] != "BUY" or not ident["symbol"]:
            continue
        mode = str(row.get("mode") or "").lower()
        status = str(row.get("status") or "").upper()
        if mode == "live_candidate":
            buy_candidate_symbols.add(ident["symbol"])
        if mode == "paper" and status == "PAPER_FILLED":
            paper_buy_symbols.add(ident["symbol"])

    reviewed: list[dict[str, object]] = []
    seen: set[str] = set()
    filtered_rows: list[dict[str, object]] = []
    for row in rows:
        symbol = _normalize_symbol_for_watchlist(row.get("symbol"))
        if not re.fullmatch(r"\d{6}", symbol or ""):
            continue
        dept = str(row.get("dept") or "").upper()
        if "ETF" in dept or "ETN" in dept or "SPAC" in dept:
            continue
        close = _number(row.get("close"))
        amount = _number(row.get("amount"))
        marcap = _number(row.get("marcap"))
        change = _number(row.get("change_pct"))
        if close < 2_000 or amount < 10_000_000_000 or marcap < 200_000_000_000 or change < 2.0:
            continue
        filtered_rows.append(row)
    if len(filtered_rows) < limit:
        for row in rows:
            symbol = _normalize_symbol_for_watchlist(row.get("symbol"))
            if not re.fullmatch(r"\d{6}", symbol or ""):
                continue
            close = _number(row.get("close"))
            amount = _number(row.get("amount"))
            marcap = _number(row.get("marcap"))
            change = _number(row.get("change_pct"))
            if close >= 2_000 and amount >= 20_000_000_000 and marcap >= 100_000_000_000 and change > 0:
                filtered_rows.append(row)

    ranked_rows = sorted(filtered_rows, key=_missed_buy_score, reverse=True)
    for row in ranked_rows:
        symbol = _normalize_symbol_for_watchlist(row.get("symbol"))
        if not symbol or symbol in seen or symbol in bought_symbols:
            continue
        seen.add(symbol)
        reason, detail, fix = _missed_buy_review_reason(
            symbol,
            buy_candidate_symbols=buy_candidate_symbols,
            paper_buy_symbols=paper_buy_symbols,
            today_reason=today_reason,
        )
        amount_eok = round(_number(row.get("amount")) / 100_000_000, 1)
        marcap_eok = round(_number(row.get("marcap")) / 100_000_000, 1)
        name = _missed_buy_review_name(row)
        detection = _intraday_detection_evidence(symbol, target_date)
        reviewed.append(
            {
                "rank": len(reviewed) + 1,
                "symbol": symbol,
                "name": name,
                "market": row.get("market") or "KR",
                "close": round(_number(row.get("close")), 2),
                "price_evidence": {
                    "currency": "KRW",
                    "quote_unit": "KRW_per_share",
                    "source": "KRX_daily_market_rows",
                    "source_work_date": work_date,
                    "adjustment": "source_reported_close",
                },
                "change_pct": round(_number(row.get("change_pct")), 2),
                "amount": round(_number(row.get("amount")), 0),
                "amount_eok": amount_eok,
                "marcap_eok": marcap_eok,
                "score": _missed_buy_score(row),
                "not_bought_reason": reason,
                "detail": detail,
                "next_fix": fix,
                "detection_audit": detection,
                "root_cause": detection.get("root_cause"),
                "root_cause_detail": detection.get("explanation"),
                "detection_next_fix": detection.get("next_fix"),
                "status": "live_candidate_only" if symbol in buy_candidate_symbols else "paper_only" if symbol in paper_buy_symbols else "missed",
                "review_line": f"{name} {round(_number(row.get('change_pct')), 2):+.2f}% / 거래대금 {amount_eok:,.1f}억 / {detection.get('root_cause')} / {reason}",
            }
        )
        if len(reviewed) >= limit:
            break

    if reviewed:
        top = reviewed[0]
        lesson = (
            f"{work_date} 기준 강한 종목 중 실제 매수하지 못한 후보 {len(reviewed)}개를 찾았습니다. "
            f"최상위는 {top.get('name')}({top.get('change_pct')}%, 거래대금 {top.get('amount_eok')}억)이고, "
            f"핵심 원인은 '{top.get('not_bought_reason')}'입니다."
        )
    else:
        lesson = f"{work_date} 기준 필터를 통과한 '강했지만 실제 매수하지 않은' 종목을 찾지 못했습니다."
    review = {
        "ok": True,
        "id": f"MBR-{int(time.time() * 1000)}",
        "generated_at": generated_at,
        "target_date": target_date,
        "work_date": work_date,
        "source": source,
        "market_note": market_note,
        "data_contract": {
            "price_currency": "KRW",
            "price_quote_unit": "KRW_per_share",
            "amount_unit": "KRW",
            "marcap_unit": "KRW",
            "primary_source": "KRX_daily_market_rows",
            "source_work_date": work_date,
        },
        "counts": {
            "reviewed": len(reviewed),
            "live_buy_submitted": len(bought_symbols),
            "live_buy_candidates": len(buy_candidate_symbols),
            "paper_buy_filled": len(paper_buy_symbols),
            "strong_rows": len(ranked_rows),
        },
        "bought_symbols": sorted(bought_symbols),
        "buy_candidate_symbols": sorted(buy_candidate_symbols),
        "paper_buy_symbols": sorted(paper_buy_symbols),
        "reviewed": reviewed,
        "top_missed": reviewed[0] if reviewed else {},
        "today_trade_diagnostics": today_reason.get("diagnostics", []) if isinstance(today_reason, dict) else [],
        "today_trade_reason": {
            "status": today_reason.get("status") if isinstance(today_reason, dict) else "",
            "title": today_reason.get("title") if isinstance(today_reason, dict) else "",
            "reason": today_reason.get("reason") if isinstance(today_reason, dict) else "",
            "next": today_reason.get("next") if isinstance(today_reason, dict) else "",
        },
        "broker_executions": {
            "ok": broker.get("ok") if isinstance(broker, dict) else False,
            "count": broker.get("count") if isinstance(broker, dict) else 0,
            "message": broker.get("message") if isinstance(broker, dict) else "",
        },
        "lesson": lesson,
        "next_action": "장중 후보 생성 루틴에 '거래대금 상위 + 상승률 상위 + 시총/가격 필터' 전용 매수 큐를 추가하고, 장마감 10회 복기훈련에 오늘 놓친 종목을 우선 투입합니다.",
        "safety": "읽기전용 복기입니다. 실제 주문은 실행하지 않았습니다.",
    }
    _append_jsonl(MISSED_BUY_REVIEW_FILE, review)
    review["storage_retention"] = _compact_missed_buy_review_history()
    JOURNAL.add(
        "MISSED_BUY_REVIEW",
        str(review["lesson"]),
        {"id": review["id"], "reviewed": len(reviewed), "source": source},
    )
    return review


def format_missed_buy_review_reply(review: dict[str, object]) -> str:
    counts = review.get("counts", {}) if isinstance(review.get("counts"), dict) else {}
    rows = review.get("reviewed", []) if isinstance(review.get("reviewed"), list) else []
    lines = [
        f"오늘 놓친 매수 후보 복기입니다. ({review.get('work_date') or review.get('target_date') or today_kst()})",
        f"- 복기 후보: {counts.get('reviewed', 0)}개",
        f"- 실제 매수 체결/전송: {counts.get('live_buy_submitted', 0)}개",
        f"- 실전 매수 후보: {counts.get('live_buy_candidates', 0)}개",
        f"- 모의 매수 체결: {counts.get('paper_buy_filled', 0)}개",
        "",
        str(review.get("lesson") or ""),
    ]
    if rows:
        lines.append("")
        lines.append("상위 놓친 후보:")
        for row in rows[:5]:
            if isinstance(row, dict):
                lines.append(
                    f"- {row.get('name', row.get('symbol', '-'))}: {_number(row.get('change_pct')):+,.2f}% / "
                    f"거래대금 {_number(row.get('amount_eok')):,.1f}억 / {row.get('root_cause', '원인 미분류')} / "
                    f"{row.get('not_bought_reason', '-')}"
                )
                lines.append(f"  포착 대사: {row.get('root_cause_detail', '-')}")
                lines.append(f"  다음 보완: {row.get('next_fix', '-')}")
    diagnostics = review.get("today_trade_diagnostics", []) if isinstance(review.get("today_trade_diagnostics"), list) else []
    if diagnostics:
        lines.append("")
        lines.append("오늘 시스템 진단:")
        for item in diagnostics[:3]:
            if isinstance(item, dict):
                lines.append(f"- {item.get('title', '진단')}: {item.get('detail', '-')}")
    lines.extend(["", str(review.get("next_action") or ""), "실제 주문은 실행하지 않았습니다."])
    return "\n".join(lines)


def is_missed_buy_review_query(text: str, lowered: str) -> bool:
    compact = re.sub(r"\s+", "", str(text or "").lower())
    korean = (
        "놓친종목",
        "놓친매수",
        "놓친후보",
        "매수안한이유",
        "왜안샀",
        "왜안사",
        "안산이유",
        "못산종목",
        "못샀",
        "오늘놓친",
    )
    english = ("missed buy", "missed trade", "missed candidate", "why no buy")
    return any(word in compact for word in korean) or any(word in lowered for word in english)


def latest_missed_buy_review() -> dict[str, object]:
    rows = _read_jsonl(MISSED_BUY_REVIEW_FILE, limit=1)
    return rows[-1] if rows else {}


def fresh_missed_buy_review(limit: int = 10, max_age_seconds: int = 1800) -> dict[str, object]:
    latest = latest_missed_buy_review()
    if (
        latest
        and latest.get("work_date") == today_kst()
        and _iso_age_seconds(latest.get("generated_at")) is not None
        and float(_iso_age_seconds(latest.get("generated_at")) or 0) <= max_age_seconds
    ):
        return latest
    return build_missed_buy_review(limit=limit, source="live-pilot-feedback")


def latest_post_market_auto_review() -> dict[str, object]:
    rows = _read_jsonl(POST_MARKET_AUTO_REVIEW_FILE, limit=1)
    return rows[-1] if rows else {}


def _latest_daily_drill_for_date(target_date: str) -> dict[str, object]:
    rows = _read_jsonl(DAILY_REPLAY_DRILL_FILE, limit=120)
    for row in reversed(rows):
        if str(row.get("target_date") or row.get("date") or "") == str(target_date):
            return row
    return {}


def _daily_replay_drill_ledger_audit(
    drill: dict[str, object] | None,
    min_repeats: int = 10,
) -> dict[str, object]:
    drill = drill if isinstance(drill, dict) else {}
    required = max(1, int(min_repeats or 10))
    runs = [row for row in drill.get("runs", []) if isinstance(row, dict)] if isinstance(drill.get("runs"), list) else []
    memories = (
        [row for row in drill.get("memory_records", []) if isinstance(row, dict)]
        if isinstance(drill.get("memory_records"), list)
        else []
    )
    run_iterations = [int(_number(row.get("iteration"))) for row in runs if int(_number(row.get("iteration"))) > 0]
    memory_iterations = [
        int(_number(row.get("iteration")))
        for row in memories
        if row.get("ok") and int(_number(row.get("iteration"))) > 0 and (row.get("memory_id") or row.get("note_path"))
    ]
    replay_ids = [str(row.get("replay_id") or "").strip() for row in runs if str(row.get("replay_id") or "").strip()]
    required_iterations = set(range(1, required + 1))
    completed = int(_number(drill.get("completed_repeats")))
    requested = int(_number(drill.get("repeats_requested")))
    checks = [
        {
            "id": "counter_reconciliation",
            "label": "완료 수와 실제 회차 원장 수 일치",
            "ok": completed == len(runs) and completed >= required and requested >= required,
        },
        {
            "id": "unique_iterations",
            "label": f"서로 다른 {required}개 복기 회차",
            "ok": required_iterations.issubset(set(run_iterations)) and len(set(run_iterations)) == len(run_iterations),
        },
        {
            "id": "unique_replays",
            "label": f"회차별 리플레이 증거 {required}개",
            "ok": len(replay_ids) == len(runs) and len(set(replay_ids)) == len(replay_ids) and len(replay_ids) >= required,
        },
        {
            "id": "memory_per_iteration",
            "label": f"회차별 장기기억 저장 {required}개",
            "ok": required_iterations.issubset(set(memory_iterations)),
        },
    ]
    return {
        "ready": bool(drill) and all(bool(check["ok"]) for check in checks),
        "required_repeats": required,
        "completed_repeats": completed,
        "run_count": len(runs),
        "unique_iteration_count": len(set(run_iterations)),
        "unique_replay_count": len(set(replay_ids)),
        "memory_link_count": len(set(memory_iterations)),
        "checks": checks,
        "blockers": [str(check["label"]) for check in checks if not check["ok"]],
    }


def _post_market_target_date() -> str:
    try:
        return str(fetch_krx_work_date())
    except Exception:
        return today_kst()


def _post_market_auto_review_due(target_date: str, min_repeats: int = 10, force: bool = False) -> dict[str, object]:
    clock = build_market_session_clock()
    kr_session = next((item for item in clock.get("sessions", []) if isinstance(item, dict) and item.get("id") == "KR"), {})
    now_kst = datetime.now(_zone("Asia/Seoul", 9))
    phase = str(kr_session.get("phase") or "closed")
    is_prior_workday = str(target_date) < today_kst()
    is_after_close = is_prior_workday or (
        phase in {"afterhours", "closed"} and (now_kst.time() >= dt_time(15, 35) or now_kst.weekday() >= 5)
    )
    latest_auto = latest_post_market_auto_review()
    latest_drill = _latest_daily_drill_for_date(target_date)
    drills = _read_jsonl(DAILY_REPLAY_DRILL_FILE, limit=1000)
    auto_drill_id = str(latest_auto.get("daily_replay_drill_id") or "")
    auto_drill = next((row for row in reversed(drills) if str(row.get("id") or "") == auto_drill_id), {})
    auto_drill_audit = _daily_replay_drill_ledger_audit(auto_drill, min_repeats=min_repeats)
    stored_hash = str(latest_auto.get("daily_replay_drill_hash") or "")
    hash_candidates = {_evidence_signature(auto_drill)} if auto_drill else set()
    if auto_drill:
        hash_candidates.add(_evidence_signature({**auto_drill, "reused": True}))
    auto_drill_hash_ok = bool(stored_hash and stored_hash in hash_candidates)
    auto_done = (
        str(latest_auto.get("target_date") or "") == str(target_date)
        and bool(auto_drill_audit.get("ready"))
        and auto_drill_hash_ok
        and str(latest_auto.get("status") or "") in {"RAN", "ALREADY_COMPLETE"}
    )
    latest_drill_audit = _daily_replay_drill_ledger_audit(latest_drill, min_repeats=min_repeats)
    drill_done = bool(latest_drill_audit.get("ready"))
    if force:
        due = True
        reason = "forced"
    elif not is_after_close:
        due = False
        reason = f"not_post_market:{phase}"
    elif auto_done:
        due = False
        reason = "already_recorded"
    else:
        due = True
        reason = "missing_auto_review" if not latest_auto or str(latest_auto.get("target_date") or "") != str(target_date) else "incomplete_repeats"
    return {
        "due": due,
        "reason": reason,
        "target_date": target_date,
        "min_repeats": min_repeats,
        "phase": phase,
        "catch_up_prior_workday": is_prior_workday,
        "clock": clock,
        "latest_auto_review": latest_auto,
        "latest_daily_drill": latest_drill,
        "daily_drill_done": drill_done,
        "daily_drill_audit": latest_drill_audit,
        "auto_drill_audit": auto_drill_audit,
        "auto_drill_hash_ok": auto_drill_hash_ok,
    }


def _post_market_theme_for_symbol(symbol: str, reflection: dict[str, object]) -> str:
    normalized = str(symbol or "").upper().strip()
    for theme in reflection.get("themes_today", []) if isinstance(reflection.get("themes_today"), list) else []:
        if not isinstance(theme, dict):
            continue
        for leader in theme.get("leaders", []) if isinstance(theme.get("leaders"), list) else []:
            if isinstance(leader, dict) and str(leader.get("symbol") or "").upper().strip() == normalized:
                return str(theme.get("name") or "주도테마")
    return ""


def _build_post_market_material_reviews(reflection: dict[str, object], limit: int = 10) -> list[dict[str, object]]:
    strong_rows: list[dict[str, object]] = []
    seen: set[str] = set()
    for group in ("gainers", "top_amount", "should_have_entered", "missed_or_watch"):
        for row in reflection.get(group, []) if isinstance(reflection.get(group), list) else []:
            if not isinstance(row, dict):
                continue
            symbol = str(row.get("symbol") or "").upper().strip()
            if not symbol or symbol in seen:
                continue
            seen.add(symbol)
            strong_rows.append(row)
            if len(strong_rows) >= limit:
                break
        if len(strong_rows) >= limit:
            break
    news_rows: list[dict[str, object]] = []
    try:
        news_rows = build_news_radar(strong_rows[:limit])
    except Exception:
        news_rows = []
    news_map = {str(row.get("symbol") or "").upper().strip(): row for row in news_rows if isinstance(row, dict)}
    reviews: list[dict[str, object]] = []
    for row in strong_rows[:limit]:
        symbol = str(row.get("symbol") or "").upper().strip()
        name = str(row.get("name") or symbol)
        amount_eok = round(_number(row.get("amount")) / 100_000_000, 1)
        change_pct = round(_number(row.get("change_pct")), 2)
        theme = _post_market_theme_for_symbol(symbol, reflection)
        news = news_map.get(symbol, {})
        headlines = news.get("items") if isinstance(news.get("items"), list) else []
        headline = ""
        if headlines and isinstance(headlines[0], dict):
            headline = str(headlines[0].get("title") or "")
        material_candidates: list[str] = []
        if theme:
            material_candidates.append(f"{theme} 주도테마")
        if amount_eok >= 1000:
            material_candidates.append("거래대금 1000억 이상 수급 집중")
        elif amount_eok >= 300:
            material_candidates.append("거래대금 300억 이상 단기 관심")
        if headline:
            material_candidates.append(f"뉴스/재료 후보: {headline[:120]}")
        if not material_candidates:
            material_candidates.append("재료 추가 확인 필요: 공시, 뉴스, 테마 동반 여부를 다음 장전 점검")
        reviews.append(
            {
                "symbol": symbol,
                "name": name,
                "change_pct": change_pct,
                "amount_eok": amount_eok,
                "theme": theme or "미확인",
                "news_stance": news.get("stance") if isinstance(news, dict) else "",
                "headline": headline,
                "material_candidates": material_candidates,
                "review": f"{name}은(는) {change_pct:+.2f}%, 거래대금 {amount_eok:,.1f}억. 강세 재료 후보: {', '.join(material_candidates[:3])}",
            }
        )
    return reviews


def run_post_market_auto_review_if_due(
    *,
    target_date: str | None = None,
    repeats: int = 10,
    raw_rows: list[dict[str, object]] | None = None,
    kr_market: dict[str, object] | None = None,
    themes: list[dict[str, object]] | None = None,
    candidates: list[dict[str, object]] | None = None,
    ops_action: dict[str, object] | None = None,
    replay_training: dict[str, object] | None = None,
    source: str = "post-market-auto-review",
    force: bool = False,
) -> dict[str, object]:
    target_date = target_date or _post_market_target_date()
    repeats = max(10, min(int(repeats or 10), 30))
    due = _post_market_auto_review_due(target_date, min_repeats=10, force=force)
    if not due.get("due"):
        return {
            "ok": True,
            "status": "SKIPPED",
            "target_date": target_date,
            "reason": due.get("reason"),
            "completed_repeats": int(_number((due.get("latest_daily_drill") or {}).get("completed_repeats"))),
            "safety": "장마감 자동복기 상태 확인만 수행했습니다. 실제 주문은 실행하지 않습니다.",
        }

    generated_at = datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds")
    reflection = build_market_reflection_journal(
        raw_rows=raw_rows,
        kr_market=kr_market,
        themes=themes,
        candidates=candidates,
        ops_action=ops_action,
        replay_training=replay_training,
        source=f"{source}-market-reflection",
        force=True,
    )
    missed = build_missed_buy_review(target_date=target_date, limit=10, source=f"{source}-missed-buy")
    latest_drill = _latest_daily_drill_for_date(target_date)
    latest_drill_audit = _daily_replay_drill_ledger_audit(latest_drill, min_repeats=10)
    if latest_drill_audit.get("ready") and not force:
        drill = dict(latest_drill)
        drill["reused"] = True
    else:
        drill = run_post_market_daily_replay_drill(
            target_date=target_date,
            repeats=repeats,
            initial_cash=150_000.0,
            lookback_days=160,
            source=f"{source}-10x",
            remember=True,
        )
    drill_ledger_audit = _daily_replay_drill_ledger_audit(drill, min_repeats=10)
    source_drill = {key: value for key, value in drill.items() if key != "reused"}
    material_reviews = _build_post_market_material_reviews(reflection, limit=10)
    supply_audit = reflection.get("supply_audit") if isinstance(reflection.get("supply_audit"), dict) else {}
    bought_symbols = missed.get("bought_symbols", []) if isinstance(missed.get("bought_symbols"), list) else []
    paper_symbols = missed.get("paper_buy_symbols", []) if isinstance(missed.get("paper_buy_symbols"), list) else []
    candidate_symbols = missed.get("buy_candidate_symbols", []) if isinstance(missed.get("buy_candidate_symbols"), list) else []
    top_missed = missed.get("top_missed") if isinstance(missed.get("top_missed"), dict) else {}
    best = drill.get("best") if isinstance(drill.get("best"), dict) else {}
    worst = drill.get("worst") if isinstance(drill.get("worst"), dict) else {}
    strong = material_reviews[:5]
    good_points = [
        f"장마감 10회 복기 {int(_number(drill.get('completed_repeats')))}/{int(_number(drill.get('repeats_requested')) or repeats)}회 완료",
        f"시장복기 기록 완료: {reflection.get('summary', '-')}",
        f"강했던 종목/재료 후보 {len(material_reviews)}개를 분리 기록",
    ]
    if bought_symbols or paper_symbols or candidate_symbols:
        good_points.append(f"선택/검토한 후보: 실제 {len(bought_symbols)}개, paper {len(paper_symbols)}개, 실전후보 {len(candidate_symbols)}개")
    improvements = [
        f"최저 복기전략: {worst.get('label', '-')} {worst.get('return_pct', 0)}%",
        f"놓친 상위 후보: {top_missed.get('name', '-') or '-'} / 이유: {top_missed.get('not_bought_reason', '-')}",
    ]
    next_rules = [
        "다음 장에는 거래대금 상위 + 상승률 상위 + 주도테마 대장주 조건을 먼저 확인",
        "거래량·하락률·외국인·기관·개인 순매수 상위까지 같은 시각 스냅샷으로 대조",
        "고른 종목은 선택 당시 점수, 테마, 뉴스/공시, 수급 근거를 매매일지에 함께 남김",
        "놓친 종목은 왜 못 샀는지, 다음에는 어떤 조건이면 살지 후보 필터로 되돌림",
    ]
    for row in missed.get("reviewed", [])[:3] if isinstance(missed.get("reviewed"), list) else []:
        if isinstance(row, dict) and row.get("next_fix"):
            next_rules.append(str(row.get("next_fix")))
    try:
        learning = build_ai_learning_insights(force=True, persist=True)
    except Exception as exc:
        learning = {"ok": False, "error": str(exc)}
    try:
        meeting = record_ai_staff_meeting(
            {
                "market_reflection": reflection,
                "replay_training": drill,
                "missed_buy_review": missed,
                "material_reviews": material_reviews,
                "candidates": candidates or [],
                "market_clock": build_market_session_clock(),
                "ops_status": OPS.status(marks={}),
            },
            source=f"{source}-staff-meeting",
            force=True,
        )
    except Exception as exc:
        meeting = {"ok": False, "error": str(exc)}
    record = {
        "ok": bool(drill_ledger_audit.get("ready")),
        "id": f"PMAUTO-{int(time.time() * 1000)}",
        "generated_at": generated_at,
        "target_date": target_date,
        "source": source,
        "status": "RAN" if drill_ledger_audit.get("ready") else "INCOMPLETE",
        "mode": "post_market_auto_10x_review",
        "completed_repeats": int(_number(drill.get("completed_repeats"))),
        "repeats_requested": int(_number(drill.get("repeats_requested")) or repeats),
        "average_return_pct": drill.get("average_return_pct"),
        "total_trade_count": drill.get("total_trade_count"),
        "daily_replay_drill_id": drill.get("id"),
        "daily_replay_drill_hash": _evidence_signature(source_drill),
        "daily_replay_drill_audit": drill_ledger_audit,
        "best_strategy": {"label": best.get("label"), "return_pct": best.get("return_pct")},
        "worst_strategy": {"label": worst.get("label"), "return_pct": worst.get("return_pct")},
        "market_reflection_id": reflection.get("id"),
        "market_summary": reflection.get("summary"),
        "supply_audit": supply_audit,
        "missed_buy_review_id": missed.get("id"),
        "top_missed": top_missed,
        "selected_review": {
            "bought_symbols": bought_symbols,
            "paper_buy_symbols": paper_symbols,
            "live_candidate_symbols": candidate_symbols,
            "why_selected": "실전/모의 후보는 점수, 위험게이트, 가격/현금 한도, 승인/리허설 상태를 통과한 경우에만 기록됩니다.",
        },
        "strong_material_reviews": strong,
        "material_review_count": len(material_reviews),
        "good_points": good_points,
        "improvements": improvements,
        "next_rules": next_rules[:8],
        "learning": {
            "ok": bool(learning.get("ok")),
            "learning_score": learning.get("learning_score"),
            "insight_count": len(learning.get("insight_cards", [])) if isinstance(learning.get("insight_cards"), list) else 0,
        },
        "staff_meeting": {
            "ok": bool(meeting.get("ok", meeting.get("recorded", False))),
            "id": meeting.get("id"),
            "decision": meeting.get("decision") if isinstance(meeting.get("decision"), dict) else {},
        },
        "lesson": (
            f"{target_date} 장마감 자동복기: 10회 드릴 {int(_number(drill.get('completed_repeats')))}회, "
            f"평균 {_number(drill.get('average_return_pct')):+.2f}%, 놓친 후보 {len(missed.get('reviewed', []) if isinstance(missed.get('reviewed'), list) else [])}개, "
            f"강세 재료 후보 {len(material_reviews)}개를 기록했습니다."
        ),
        "safety": "장마감 자동복기는 연구/복기/기억 루틴입니다. 실제 주문은 실행하지 않습니다.",
    }
    _append_jsonl(POST_MARKET_AUTO_REVIEW_FILE, record)
    _compact_jsonl(POST_MARKET_AUTO_REVIEW_FILE, max_rows=260)
    JOURNAL.add("POST_MARKET_AUTO_REVIEW", str(record["lesson"]), {"id": record["id"], "target_date": target_date})
    return record


def missed_buy_feedback_live_rows(max_notional: float | None = None, quantity: float = 1) -> list[dict[str, object]]:
    """놓친 매수 복기를 다음 실전 후보 풀에 섞기 위한 읽기전용 변환."""
    try:
        review = fresh_missed_buy_review(limit=10)
    except Exception:
        return []
    reviewed = review.get("reviewed", []) if isinstance(review.get("reviewed"), list) else []
    try:
        policy = OPS.autotrade_policy()
    except Exception:
        policy = {}
    try:
        account = INTEGRATIONS.kis_account()
        summary = account.get("summary", {}) if isinstance(account.get("summary"), dict) else {}
    except Exception:
        summary = {}
    available_cash = _number(summary.get("available_cash") or summary.get("cash"))
    sizing_mode = str(policy.get("live_pilot_sizing_mode", "single_share") or "single_share").lower()
    max_cash_pct = max(0.0, min(_number(policy.get("live_pilot_max_cash_pct", 100.0)) or 100.0, 100.0))
    cash_cap = available_cash * max_cash_pct / 100.0 if available_cash and sizing_mode == "cash_pct" else available_cash
    policy_cap = _number(policy.get("live_pilot_max_notional")) or _number(policy.get("max_order_amount"))
    caps = [value for value in (max_notional, policy_cap, cash_cap) if _number(value) > 0]
    notional_cap = min(_number(value) for value in caps) if caps else 0.0
    qty = max(1.0, _number(quantity) or 1.0)
    rows: list[dict[str, object]] = []
    for item in reviewed:
        if not isinstance(item, dict):
            continue
        symbol = _normalize_symbol_for_watchlist(item.get("symbol"))
        if not re.fullmatch(r"\d{6}", symbol or ""):
            continue
        price = _number(item.get("close"))
        notional = price * qty
        if price <= 0 or (notional_cap and notional > notional_cap):
            continue
        score = _number(item.get("score"))
        change = _number(item.get("change_pct"))
        amount_eok = _number(item.get("amount_eok"))
        live_score = _clamp(62.0 + min(score, 180.0) * 0.16 + min(change, 15.0) * 1.5 + min(amount_eok, 2_000.0) / 90.0, 0, 100)
        rows.append(
            {
                "symbol": symbol,
                "name": item.get("name") or symbol,
                "score": round(score, 2),
                "live_score": round(live_score, 2),
                "trade_mode": "복기반영 단기/스윙 후보",
                "strategy_mode": "missed_buy_feedback",
                "estimated_price": price,
                "estimated_notional": round(notional, 2),
                "notional_ok": True,
                "validation_status": "놓친 매수 복기 반영",
                "news_stance": "추가 확인",
                "financial_stance": "추가 확인",
                "theme_name": "당일 강세/거래대금",
                "theme_rank": item.get("rank"),
                "reasons": [
                    f"오늘 놓친 매수 복기 상위 {item.get('rank', '-')}: {item.get('review_line', '')}",
                    str(item.get("detail") or ""),
                    str(item.get("next_fix") or ""),
                ],
                "risk_flags": ["복기 기반 후보: 실전 전송 전 뉴스·재무·호가 재확인 필요"],
                "source": "missed_buy_feedback",
            }
        )
    rows.sort(key=lambda row: _number(row.get("live_score")), reverse=True)
    return rows


def _capital_phase_key(scenario: dict[str, object]) -> str:
    return str(scenario.get("phase", "")).strip().upper()


