def _capital_challenge_scenario_catalog(start_year: int = 2000) -> list[dict[str, object]]:
    catalog: list[dict[str, object]] = []
    for scenario in _capital_challenge_scenarios(start_year=start_year):
        catalog.append(
            {
                "phase": scenario.get("phase"),
                "label": scenario.get("label"),
                "purpose": scenario.get("purpose"),
                "regime": scenario.get("regime", ""),
                "start": scenario.get("start"),
                "end": scenario.get("end"),
                "period": f"{scenario.get('start')}~{scenario.get('end')}",
                "strategy": scenario.get("strategy"),
                "symbols": scenario.get("symbols", []),
                "cycles_per_day": scenario.get("cycles_per_day"),
                "status": "PLANNED",
                "lesson": "아직 이 구간은 새 전체 실행 또는 구간별 재훈련 전입니다.",
            }
        )
    return catalog


def run_capital_growth_challenge(
    initial_cash: float = 10_000_000.0,
    target_cash: float = 10_000_000_000.0,
    source: str = "manual-capital-challenge",
    start_year: int = 2000,
    phase_id: str | None = None,
    progress_callback: Callable[[dict[str, object]], None] | None = None,
) -> dict[str, object]:
    initial_cash = max(1_000_000.0, float(initial_cash or 10_000_000.0))
    target_cash = max(initial_cash, float(target_cash or 10_000_000_000.0))
    start_year = max(2000, min(int(start_year or 2000), int(today_kst()[:4])))
    selected_phase = str(phase_id or "").strip().upper()
    selected_phase = {
        "10Y-1": "TREND-2016",
        "10Y-2": "WEAK-2018",
        "1": "GROWTH-2020",
        "2": "WEAK-2022",
        "3": "LEADER-2024",
    }.get(selected_phase, selected_phase)
    scenarios = _capital_challenge_scenarios(start_year=start_year)
    if selected_phase:
        scenarios = [scenario for scenario in scenarios if _capital_phase_key(scenario) == selected_phase]
        if not scenarios:
            raise ValueError(f"선택한 훈련 구간을 찾지 못했습니다: {selected_phase}")
    current_cash = initial_cash
    phases: list[dict[str, object]] = []
    replay_ids: list[str] = []
    worst_mdd = 0.0
    total_trades = 0
    total_training_hours = 0
    lessons: list[str] = []
    phase_count = len(scenarios)
    if progress_callback:
        progress_callback(
            {
                "progress_pct": 0.0,
                "phase_index": 0,
                "phase_count": phase_count,
                "current_phase": "",
                "current_label": "훈련 준비 중",
                "compressed_training_hours": 0,
                "trade_count": 0,
            }
        )
    for phase_index, scenario in enumerate(scenarios, start=1):
        if progress_callback:
            progress_callback(
                {
                    "progress_pct": round(((phase_index - 1) / max(phase_count, 1)) * 100.0 + (8.0 / max(phase_count, 1)), 2),
                    "phase_index": phase_index,
                    "phase_count": phase_count,
                    "current_phase": scenario["phase"],
                    "current_label": f"{scenario['label']} 데이터 수집/훈련 중",
                    "compressed_training_hours": total_training_hours,
                    "trade_count": total_trades,
                }
            )
        try:
            replay = run_historical_paper_replay(
                symbols=[str(item) for item in scenario["symbols"]],
                start_date=str(scenario["start"]),
                end_date=str(scenario["end"]),
                fast=int(scenario["fast"]),
                slow=int(scenario["slow"]),
                initial_cash=current_cash,
                allocation_pct=float(scenario["allocation"]),
                max_positions=int(scenario["max_positions"]),
                source=f"{source}-phase-{scenario['phase']}",
                strategy_mode=str(scenario["strategy"]),
                stop_loss_pct=float(scenario["stop_loss"]),
                take_profit_pct=float(scenario["take_profit"]),
                holding_limit_days=int(scenario["holding_limit"]),
                cycles_per_day=int(scenario["cycles_per_day"]),
                allow_simulated_fallback=bool(scenario.get("allow_simulated_fallback", False)),
            )
            final_equity = float(replay.get("final_equity", current_cash) or current_cash)
            phase_return = float(replay.get("total_return_pct", 0) or 0)
            phase_mdd = float(replay.get("max_drawdown_pct", 0) or 0)
            worst_mdd = min(worst_mdd, phase_mdd)
            phase_trades = int(replay.get("trade_count", 0) or 0)
            phase_hours = int(replay.get("compressed_training_hours", 0) or 0)
            total_trades += phase_trades
            total_training_hours += phase_hours
            replay_ids.append(str(replay.get("id", "")))
            if phase_return > 20 and phase_mdd > -12:
                lesson = "성장 구간으로 인정. 같은 조건을 더 많은 주도섹터에 확장 검증합니다."
            elif phase_return > 0:
                lesson = "살아남기는 했지만 100억 프로젝트 속도는 부족합니다. 회전율/후보 품질을 개선해야 합니다."
            else:
                lesson = "목표 달성 경로를 깎는 구간입니다. 진입 필터와 현금 대기 규칙을 강화해야 합니다."
            phase_record = {
                "status": "DONE",
                "phase": scenario["phase"],
                "label": scenario["label"],
                "purpose": scenario["purpose"],
                "regime": scenario.get("regime", ""),
                "period": f"{replay.get('start_date')}~{replay.get('end_date')}",
                "symbols": replay.get("symbols", []),
                "strategy": replay.get("strategy_label"),
                "start_cash": round(current_cash, 2),
                "final_equity": round(final_equity, 2),
                "return_pct": round(phase_return, 2),
                "max_drawdown_pct": round(phase_mdd, 2),
                "trade_count": phase_trades,
                "win_rate_pct": replay.get("win_rate_pct"),
                "compressed_training_hours": phase_hours,
                "training_run_label": f"{phase_hours:,}시간 압축훈련",
                "replay_id": replay.get("id"),
                "trade_journal_count": replay.get("trade_journal_count"),
                "trade_action_count": replay.get("trade_action_count"),
                "trade_journal_path": replay.get("trade_journal_path"),
                "trade_journal_markdown_path": replay.get("trade_journal_markdown_path"),
                "trade_journal_top10": replay.get("trade_journal_top10", []),
                "trade_journal_bottom10": replay.get("trade_journal_bottom10", []),
                "trade_journal_sample": replay.get("trade_journal_sample", []),
                "lesson": lesson,
                "top_trades": replay.get("trade_journal_top10", [])[:10] or replay.get("trades", [])[-12:],
                "data_mode": replay.get("data_mode"),
                "data_sources": replay.get("sources", []),
            }
            current_cash = max(1_000_000.0, final_equity)
        except Exception as exc:
            phase_return = 0.0
            phase_mdd = 0.0
            lesson = f"실데이터 훈련 실패: {exc}"
            phase_record = {
                "status": "ERROR",
                "phase": scenario["phase"],
                "label": scenario["label"],
                "purpose": scenario["purpose"],
                "regime": scenario.get("regime", ""),
                "period": f"{scenario.get('start')}~{scenario.get('end')}",
                "symbols": scenario.get("symbols", []),
                "strategy": str(scenario.get("strategy", "-")),
                "start_cash": round(current_cash, 2),
                "final_equity": round(current_cash, 2),
                "return_pct": 0.0,
                "max_drawdown_pct": 0.0,
                "trade_count": 0,
                "win_rate_pct": 0,
                "compressed_training_hours": 0,
                "training_run_label": "실데이터 부족으로 미완료",
                "replay_id": "",
                "lesson": lesson,
                "top_trades": [],
                "error": str(exc),
            }
        phases.append(phase_record)
        lessons.append(f"{scenario['label']}: {phase_return:+.2f}%, MDD {phase_mdd:.2f}%. {lesson}")
        if progress_callback:
            progress_callback(
                {
                    "progress_pct": round((phase_index / max(phase_count, 1)) * 100.0, 2),
                    "phase_index": phase_index,
                    "phase_count": phase_count,
                    "current_phase": scenario["phase"],
                    "current_label": scenario["label"],
                    "compressed_training_hours": total_training_hours,
                    "trade_count": total_trades,
                    "latest_phase": phase_record,
                }
            )
    achieved_multiple = current_cash / initial_cash if initial_cash else 0.0
    target_multiple = target_cash / initial_cash if initial_cash else 0.0
    remaining_multiple = target_cash / current_cash if current_cash else 0.0
    progress_pct = current_cash / target_cash * 100.0 if target_cash else 0.0
    success = current_cash >= target_cash
    if success:
        verdict = "과거 차트 경로에서 목표를 달성했습니다. 과최적화 여부를 워크포워드/종목 확장으로 재검증해야 합니다."
    elif achieved_multiple >= target_multiple * 0.1:
        verdict = "목표에는 못 미쳤지만 성장 경로가 일부 보입니다. 섹터 회전/리스크 축소/후보 확장이 필요합니다."
    else:
        verdict = "현재 규칙만으로는 1천만원을 100억원으로 키우기 어렵습니다. 무리한 레버리지보다 전략 연구와 후보 확장이 먼저입니다."
    next_tasks = [
        "목표 달성 실패 구간의 진입 종목을 매매일지와 대조해 '들어가면 안 됐던 자리' 규칙으로 추가",
        "3개월 주도섹터와 당일 거래대금 상위가 겹치는 종목만 별도 챌린지로 재훈련",
        "100억 목표용 공격형 전략과 실전용 보수형 전략을 분리하고, 실전은 1주 파일럿/손실한도 안에서만 운용",
        "미국 AI/반도체 대형주, 국내 주도섹터, 약세장 현금대기 규칙을 각각 워크포워드 검증",
    ]
    start_date_text = str(phases[0].get("period", "").split("~")[0]) if phases else ""
    end_date_text = str(phases[-1].get("period", "").split("~")[-1]) if phases else ""
    try:
        horizon_years = round((datetime.fromisoformat(end_date_text).date() - datetime.fromisoformat(start_date_text).date()).days / 365.25, 1)
    except Exception:
        horizon_years = 1.0 if selected_phase else 10.0
    record = {
        "ok": True,
        "id": f"CAPCHAL-{int(time.time() * 1000)}",
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "source": source,
        "phase_only": bool(selected_phase),
        "selected_phase": selected_phase,
        "start_year": start_year,
        "phase_count": phase_count,
        "training_iteration": len(_read_jsonl(CAPITAL_CHALLENGE_FILE, limit=10000)) + 1,
        "horizon_years": horizon_years,
        "start_date": start_date_text,
        "end_date": end_date_text,
        "project_name": "1천만원으로 과거 차트 100억 달성 프로젝트",
        "initial_cash": round(initial_cash, 2),
        "target_cash": round(target_cash, 2),
        "final_equity": round(current_cash, 2),
        "target_multiple": round(target_multiple, 2),
        "achieved_multiple": round(achieved_multiple, 4),
        "remaining_multiple": round(remaining_multiple, 2),
        "progress_pct": round(progress_pct, 4),
        "success": success,
        "verdict": verdict,
        "worst_max_drawdown_pct": round(worst_mdd, 2),
        "total_trade_count": total_trades,
        "compressed_training_hours": total_training_hours,
        "phases": phases,
        "replay_ids": [item for item in replay_ids if item],
        "lessons": lessons,
        "next_tasks": next_tasks,
        "safety": "과거 차트 훈련 프로젝트입니다. 실전에서 100억 달성을 보장하지 않으며, 레버리지/몰빵을 권하지 않습니다.",
    }
    memory = MEMORY.append_capital_challenge_memory(record)
    record["memory"] = {
        "ok": bool(memory.get("ok")),
        "note_path": memory.get("path"),
        "latest_path": memory.get("latest_path"),
        "graph_path": memory.get("graph_path"),
    }
    if selected_phase:
        _append_jsonl(CAPITAL_PHASE_TRAINING_FILE, record)
        _compact_jsonl(CAPITAL_PHASE_TRAINING_FILE, max_rows=800)
        JOURNAL.add("CAPITAL_PHASE_TRAINING", f"{phases[0].get('label', selected_phase) if phases else selected_phase}: {record['achieved_multiple']}배", {"id": record["id"], "phase": selected_phase, "note_path": record["memory"].get("note_path")})
    else:
        _append_jsonl(CAPITAL_CHALLENGE_FILE, record)
        _compact_jsonl(CAPITAL_CHALLENGE_FILE, max_rows=400)
        JOURNAL.add("CAPITAL_GROWTH_CHALLENGE", f"{record['project_name']}: {record['achieved_multiple']}배 / 목표 {record['target_multiple']}배", {"id": record["id"], "note_path": record["memory"].get("note_path")})
    return record


def latest_capital_growth_challenge() -> dict[str, object]:
    rows = _read_jsonl(CAPITAL_CHALLENGE_FILE, limit=1)
    return rows[-1] if rows else {}


def _capital_challenge_brief(record: dict[str, object] | None = None) -> dict[str, object]:
    record = record or latest_capital_growth_challenge()
    if not isinstance(record, dict) or not record:
        return {}
    return {
        "id": record.get("id"),
        "generated_at": record.get("generated_at"),
        "training_iteration": record.get("training_iteration"),
        "start_year": record.get("start_year"),
        "phase_count": record.get("phase_count"),
        "initial_cash": record.get("initial_cash"),
        "target_cash": record.get("target_cash"),
        "final_equity": record.get("final_equity"),
        "achieved_multiple": record.get("achieved_multiple"),
        "remaining_multiple": record.get("remaining_multiple"),
        "progress_pct": record.get("progress_pct"),
        "worst_max_drawdown_pct": record.get("worst_max_drawdown_pct"),
        "total_trade_count": record.get("total_trade_count"),
        "compressed_training_hours": record.get("compressed_training_hours"),
        "success": record.get("success"),
        "verdict": record.get("verdict"),
        "note_path": ((record.get("memory") or {}).get("note_path") if isinstance(record.get("memory"), dict) else None),
    }


def capital_challenge_job_status() -> dict[str, object]:
    with CAPITAL_CHALLENGE_JOB_LOCK:
        job = dict(CAPITAL_CHALLENGE_JOB)
    latest = latest_capital_growth_challenge()
    job["ok"] = True
    job["latest"] = _capital_challenge_brief(latest)
    job["scenarios"] = _capital_challenge_scenario_catalog(start_year=2000)
    job["state"] = load_capital_challenge_state()
    return job


def _capital_challenge_job_worker(
    initial_cash: float,
    target_cash: float,
    source: str = "api-capital-challenge-job",
    start_year: int = 2000,
    phase_id: str | None = None,
) -> None:
    try:
        def update_progress(progress: dict[str, object]) -> None:
            with CAPITAL_CHALLENGE_JOB_LOCK:
                CAPITAL_CHALLENGE_JOB.update(
                    {
                        "progress_pct": progress.get("progress_pct", 0.0),
                        "phase_index": progress.get("phase_index", 0),
                        "phase_count": progress.get("phase_count", 0),
                        "current_phase": progress.get("current_phase", ""),
                        "current_label": progress.get("current_label", ""),
                        "compressed_training_hours": progress.get("compressed_training_hours", 0),
                        "trade_count": progress.get("trade_count", 0),
                        "latest_phase": progress.get("latest_phase", {}),
                        "message": f"{progress.get('current_label', '훈련')} 진행 중 · {progress.get('progress_pct', 0)}%",
                    }
                )

        record = run_capital_growth_challenge(
            initial_cash=initial_cash,
            target_cash=target_cash,
            source=source,
            start_year=start_year,
            phase_id=phase_id,
            progress_callback=update_progress,
        )
        state = load_capital_challenge_state() if record.get("phase_only") else _remember_capital_challenge_run(record)
        message = "선택 구간 훈련이 완료됐습니다." if record.get("phase_only") else "100억 프로젝트 새 실행이 완료되어 최신 결과에 반영됐습니다."
        with CAPITAL_CHALLENGE_JOB_LOCK:
            CAPITAL_CHALLENGE_JOB.update(
                {
                    "running": False,
                    "status": "DONE",
                    "finished_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
                    "message": message,
                    "progress_pct": 100.0,
                    "result": record,
                    "state": state,
                    "error": "",
                }
            )
    except Exception as exc:
        with CAPITAL_CHALLENGE_JOB_LOCK:
            CAPITAL_CHALLENGE_JOB.update(
                {
                    "running": False,
                    "status": "ERROR",
                    "finished_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
                    "message": f"100억 프로젝트 실행 실패: {exc}",
                    "result": None,
                    "error": str(exc),
                }
            )


def start_capital_challenge_job(
    initial_cash: float = 10_000_000.0,
    target_cash: float = 10_000_000_000.0,
    start_year: int = 2000,
    phase_id: str | None = None,
) -> dict[str, object]:
    selected_phase = str(phase_id or "").strip().upper()
    with CAPITAL_CHALLENGE_JOB_LOCK:
        if CAPITAL_CHALLENGE_JOB.get("running"):
            job = dict(CAPITAL_CHALLENGE_JOB)
            job["ok"] = True
            job["accepted"] = False
            job["message"] = "이미 100억 프로젝트가 실행 중입니다. 완료될 때까지 진행 상태를 표시합니다."
            return job
        started_at = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
        CAPITAL_CHALLENGE_JOB.update(
            {
                "running": True,
                "status": "RUNNING",
                "started_at": started_at,
                "finished_at": "",
                "message": "선택 구간을 백그라운드에서 훈련 중입니다." if selected_phase else "100억 프로젝트를 백그라운드에서 실행 중입니다. 화면은 자동으로 완료 여부를 확인합니다.",
                "progress_pct": 0.0,
                "phase_index": 0,
                "phase_count": 0,
                "current_phase": selected_phase,
                "current_label": "훈련 준비 중",
                "compressed_training_hours": 0,
                "trade_count": 0,
                "latest_phase": {},
                "mode": "phase" if selected_phase else "full",
                "phase_id": selected_phase,
                "start_year": start_year,
                "initial_cash": initial_cash,
                "target_cash": target_cash,
                "result": None,
                "error": "",
            }
        )
        job = dict(CAPITAL_CHALLENGE_JOB)
    thread = threading.Thread(
        target=_capital_challenge_job_worker,
        args=(float(initial_cash), float(target_cash), "api-capital-challenge-phase-job" if selected_phase else "api-capital-challenge-job", int(start_year), selected_phase or None),
        daemon=True,
        name="capital-challenge-phase-job" if selected_phase else "capital-challenge-job",
    )
    thread.start()
    job["ok"] = True
    job["accepted"] = True
    return job


def latest_ohlcv_walk_forward_challenge() -> dict[str, object]:
    if not OHLCV_WALK_FORWARD_RESULT_FILE.exists():
        return {"ok": False, "status": "NO_RESULT", "message": "OHLCV 워크포워드 연구 결과가 아직 없습니다."}
    try:
        payload = json.loads(OHLCV_WALK_FORWARD_RESULT_FILE.read_text(encoding="utf-8"))
        results = payload.get("results", []) if isinstance(payload, dict) else []
        if not isinstance(results, list) or not results:
            return {"ok": False, "status": "EMPTY", "message": "OHLCV 워크포워드 결과 파일에 전략 결과가 없습니다."}
        best = results[0] if isinstance(results[0], dict) else {}
        report_dir = OBSIDIAN_VAULT / "CapitalChallenge"
        reports = sorted(report_dir.glob("walk-forward-ohlcv-*.md"), key=lambda item: item.stat().st_mtime, reverse=True) if report_dir.exists() else []
        compact_top = [
            {
                "name": row.get("name"),
                "final_equity": row.get("final_equity"),
                "multiple": row.get("multiple"),
                "target_progress_pct": row.get("target_progress_pct"),
                "max_drawdown_pct": row.get("max_drawdown_pct"),
                "trade_count": row.get("trade_count"),
                "win_rate_pct": row.get("win_rate_pct"),
                "performance_evidence_status": row.get("performance_evidence_status", "blocked"),
                "official_return_claim_allowed": bool(
                    isinstance(row.get("trade_evidence_audit"), dict)
                    and row["trade_evidence_audit"].get("official_return_claim_allowed") is True
                ),
                "trade_evidence_audit": row.get("trade_evidence_audit", {}),
                "trade_ledger": row.get("trade_ledger", {}),
            }
            for row in results[:5]
            if isinstance(row, dict)
        ]
        best_name = str(best.get("name") or "-")
        best_multiple = _number(best.get("multiple"))
        best_mdd = _number(best.get("max_drawdown_pct"))
        trade_evidence = payload.get("trade_evidence") if isinstance(payload.get("trade_evidence"), dict) else {}
        best_verified = bool(
            isinstance(best.get("trade_evidence_audit"), dict)
            and best["trade_evidence_audit"].get("official_return_claim_allowed") is True
            and isinstance(best.get("trade_ledger"), dict)
            and best["trade_ledger"].get("persisted_and_readback_verified") is True
            and trade_evidence.get("all_results_verified") is True
        )
        return {
            "ok": best_verified,
            "status": "READY" if best_verified else "VERIFICATION_BLOCKED",
            "generated_at": payload.get("generated_at"),
            "start": payload.get("start"),
            "end": payload.get("end"),
            "data_symbols": payload.get("data_symbols"),
            "tested": payload.get("tested"),
            "elapsed_seconds": payload.get("elapsed_seconds"),
            "best": compact_top[0] if compact_top else {},
            "top": compact_top,
            "trade_evidence": trade_evidence,
            "official_return_claim_allowed": best_verified,
            "verification_blockers": [] if best_verified else [
                "full_trade_ledger_not_verified",
                "entry_exit_reason_return_reconciliation_not_proven",
            ],
            "verification_message": (
                "Full trade ledger, timing, entry/exit reason, and return reconciliation passed."
                if best_verified
                else "Result is visible but blocked until the full trade ledger is regenerated and verified."
            ),
            "report_path": str(reports[0]) if reports else "",
            "message": f"OHLCV 워크포워드 최고 전략은 {best_name}, {best_multiple:.4f}배, MDD {best_mdd:.2f}%입니다.",
        }
    except Exception as exc:
        return {"ok": False, "status": "ERROR", "message": str(exc)}


def _write_hundred_billion_lab_state(payload: dict[str, object]) -> None:
    HUNDRED_BILLION_LAB_STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
    payload["updated_at"] = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
    HUNDRED_BILLION_LAB_STATE_FILE.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")


def _read_hundred_billion_lab_state() -> dict[str, object]:
    if not HUNDRED_BILLION_LAB_STATE_FILE.exists():
        return {}
    try:
        payload = json.loads(HUNDRED_BILLION_LAB_STATE_FILE.read_text(encoding="utf-8"))
        return payload if isinstance(payload, dict) else {}
    except Exception:
        return {}


def _compact_hundred_billion_lab_result() -> dict[str, object]:
    if not HUNDRED_BILLION_LAB_RESULT_FILE.exists():
        return {"ok": False, "status": "NO_RESULT", "message": "100억 전략 실험실 결과가 아직 없습니다."}
    try:
        payload = json.loads(HUNDRED_BILLION_LAB_RESULT_FILE.read_text(encoding="utf-8"))
        if not isinstance(payload, dict):
            return {"ok": False, "status": "INVALID", "message": "결과 파일 형식이 올바르지 않습니다."}
        results = payload.get("results", [])
        if not isinstance(results, list):
            results = []
        compact_top = [
            {
                "name": row.get("name"),
                "family": row.get("family"),
                "final_equity": row.get("final_equity"),
                "multiple": row.get("multiple"),
                "target_progress_pct": row.get("target_progress_pct"),
                "max_drawdown_pct": row.get("max_drawdown_pct"),
                "trade_count": row.get("trade_count"),
                "win_rate_pct": row.get("win_rate_pct"),
                "performance_evidence_status": row.get("performance_evidence_status", "blocked"),
                "official_return_claim_allowed": bool(
                    isinstance(row.get("trade_evidence_audit"), dict)
                    and row["trade_evidence_audit"].get("official_return_claim_allowed") is True
                ),
                "trade_evidence_audit": row.get("trade_evidence_audit", {}),
                "trade_ledger": row.get("trade_ledger", {}),
            }
            for row in results[:8]
            if isinstance(row, dict)
        ]
        best = compact_top[0] if compact_top else {}
        trade_evidence = payload.get("trade_evidence") if isinstance(payload.get("trade_evidence"), dict) else {}
        best_verified = bool(
            best.get("official_return_claim_allowed") is True
            and isinstance(best.get("trade_ledger"), dict)
            and best["trade_ledger"].get("persisted_and_readback_verified") is True
            and trade_evidence.get("all_results_verified") is True
        )
        report_dir = OBSIDIAN_VAULT / "CapitalChallenge"
        reports = sorted(report_dir.glob("hundred-billion-strategy-lab-*.md"), key=lambda item: item.stat().st_mtime, reverse=True) if report_dir.exists() else []
        return {
            "ok": bool(compact_top) and best_verified,
            "status": (
                "PARTIAL"
                if str(payload.get("status") or "").upper() == "PARTIAL"
                else "READY" if compact_top and best_verified else "VERIFICATION_BLOCKED" if compact_top else "EMPTY"
            ),
            "mode": payload.get("mode"),
            "generated_at": payload.get("generated_at"),
            "start": payload.get("start"),
            "end": payload.get("end"),
            "data_symbols": payload.get("data_symbols"),
            "tested": payload.get("tested", len(results)),
            "planned": payload.get("planned"),
            "elapsed_seconds": payload.get("elapsed_seconds"),
            "best": best,
            "top": compact_top,
            "trade_evidence": trade_evidence,
            "official_return_claim_allowed": bool(compact_top) and best_verified,
            "verification_blockers": [] if best_verified else [
                "full_trade_ledger_not_verified",
                "entry_exit_reason_return_reconciliation_not_proven",
            ],
            "verification_message": (
                "Full trade ledger, timing, entry/exit reason, and return reconciliation passed."
                if best_verified
                else "Result is visible but blocked until the full trade ledger is regenerated and verified."
            ),
            "report_path": str(reports[0]) if reports else "",
            "message": (
                f"최고 전략 {best.get('name', '-')} / {float(best.get('multiple', 0) or 0):.4f}배 / "
                f"최종 {float(best.get('final_equity', 0) or 0):,.0f}원"
                if best
                else "아직 완료된 전략 결과가 없습니다."
            ),
        }
    except Exception as exc:
        return {"ok": False, "status": "ERROR", "message": str(exc)}


def hundred_billion_lab_status() -> dict[str, object]:
    global HUNDRED_BILLION_LAB_PROCESS
    state = _read_hundred_billion_lab_state()
    result = _compact_hundred_billion_lab_result()
    running = False
    return_code = None
    with HUNDRED_BILLION_LAB_LOCK:
        if HUNDRED_BILLION_LAB_PROCESS is not None:
            return_code = HUNDRED_BILLION_LAB_PROCESS.poll()
            running = return_code is None
            if not running:
                state = {
                    **state,
                    "running": False,
                    "status": "DONE" if return_code == 0 else "EXITED",
                    "return_code": return_code,
                }
                _write_hundred_billion_lab_state(state)
                HUNDRED_BILLION_LAB_PROCESS = None
    tested = int(result.get("tested", 0) or 0)
    planned = int(result.get("planned", 0) or 0)
    progress_pct = (tested / planned * 100.0) if planned else (100.0 if result.get("status") in {"READY", "VERIFICATION_BLOCKED"} and tested else 0.0)
    result_status = str(result.get("status") or "IDLE")
    if running:
        status = "RUNNING"
    elif result_status in {"VERIFICATION_BLOCKED", "ERROR", "EMPTY", "NO_RESULT"}:
        status = result_status
    else:
        status = str(state.get("status") or result_status)
    return {
        "ok": True,
        "running": running,
        "status": status,
        "mode": state.get("mode") or result.get("mode") or "quick",
        "started_at": state.get("started_at"),
        "updated_at": state.get("updated_at"),
        "return_code": return_code if return_code is not None else state.get("return_code"),
        "progress_pct": round(max(0.0, min(100.0, progress_pct)), 2),
        "result_verification_status": result_status,
        "official_return_claim_allowed": bool(result.get("official_return_claim_allowed")),
        "result": result,
        "logs": {
            "stdout": str(HUNDRED_BILLION_LAB_OUT_LOG),
            "stderr": str(HUNDRED_BILLION_LAB_ERR_LOG),
        },
        "message": "전략 실험실이 백그라운드에서 연구 중입니다." if running else result.get("message", "전략 실험실 대기 중입니다."),
    }


def start_hundred_billion_lab(mode: str = "focus") -> dict[str, object]:
    global HUNDRED_BILLION_LAB_PROCESS
    mode = str(mode or "focus").lower().strip()
    allowed = {"quick", "focus", "ultra", "deep"}
    if mode not in allowed:
        return {"ok": False, "error": f"mode는 {', '.join(sorted(allowed))} 중 하나여야 합니다."}
    already_running = False
    with HUNDRED_BILLION_LAB_LOCK:
        if HUNDRED_BILLION_LAB_PROCESS is not None and HUNDRED_BILLION_LAB_PROCESS.poll() is None:
            already_running = True
        else:
            if HUNDRED_BILLION_LAB_PROCESS is not None and HUNDRED_BILLION_LAB_PROCESS.poll() is not None:
                HUNDRED_BILLION_LAB_PROCESS = None
            script = APP_ROOT / "hundred_billion_strategy_lab.py"
            args = [sys.executable, str(script)]
            if mode != "quick":
                args.append(f"--{mode}")
            HUNDRED_BILLION_LAB_OUT_LOG.parent.mkdir(parents=True, exist_ok=True)
            stdout_handle = HUNDRED_BILLION_LAB_OUT_LOG.open("a", encoding="utf-8")
            stderr_handle = HUNDRED_BILLION_LAB_ERR_LOG.open("a", encoding="utf-8")
            creationflags = subprocess.CREATE_NO_WINDOW if hasattr(subprocess, "CREATE_NO_WINDOW") else 0
            try:
                HUNDRED_BILLION_LAB_PROCESS = subprocess.Popen(
                    args,
                    cwd=str(REPO_ROOT),
                    stdout=stdout_handle,
                    stderr=stderr_handle,
                    creationflags=creationflags,
                )
            finally:
                stdout_handle.close()
                stderr_handle.close()
            started_at = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
            _write_hundred_billion_lab_state(
                {
                    "ok": True,
                    "running": True,
                    "status": "RUNNING",
                    "mode": mode,
                    "pid": HUNDRED_BILLION_LAB_PROCESS.pid,
                    "started_at": started_at,
                    "command": " ".join(args),
                }
            )
    status = hundred_billion_lab_status()
    status["already_running" if already_running else "started"] = True
    return status


def stop_hundred_billion_lab() -> dict[str, object]:
    global HUNDRED_BILLION_LAB_PROCESS
    already_stopped = False
    with HUNDRED_BILLION_LAB_LOCK:
        if HUNDRED_BILLION_LAB_PROCESS is None or HUNDRED_BILLION_LAB_PROCESS.poll() is not None:
            state = {**_read_hundred_billion_lab_state(), "running": False, "status": "STOPPED"}
            _write_hundred_billion_lab_state(state)
            already_stopped = True
        else:
            pid = HUNDRED_BILLION_LAB_PROCESS.pid
            HUNDRED_BILLION_LAB_PROCESS.terminate()
            try:
                HUNDRED_BILLION_LAB_PROCESS.wait(timeout=5)
            except subprocess.TimeoutExpired:
                HUNDRED_BILLION_LAB_PROCESS.kill()
                HUNDRED_BILLION_LAB_PROCESS.wait(timeout=5)
            HUNDRED_BILLION_LAB_PROCESS = None
            _write_hundred_billion_lab_state(
                {
                    "ok": True,
                    "running": False,
                    "status": "STOPPED",
                    "pid": pid,
                    "stopped_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
                }
            )
    status = hundred_billion_lab_status()
    status["already_stopped" if already_stopped else "stopped"] = True
    return status


def _capital_challenge_next_due(last_run_at: object, interval_seconds: int) -> str:
    try:
        parsed = datetime.fromisoformat(str(last_run_at).replace("Z", "+00:00"))
    except Exception:
        parsed = datetime.now(ZoneInfo("Asia/Seoul"))
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=ZoneInfo("Asia/Seoul"))
    return (parsed.astimezone(ZoneInfo("Asia/Seoul")) + timedelta(seconds=max(60, int(interval_seconds)))).isoformat(timespec="seconds")


def load_capital_challenge_state() -> dict[str, object]:
    now = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
    state: dict[str, object] = {
        "ok": True,
        "enabled": True,
        "mode": "research_only",
        "interval_seconds": 21_600,
        "run_count": 0,
        "updated_at": now,
        "description": "AI가 매 연구 사이클마다 상태를 확인하고, 무거운 100억 프로젝트 백테스트는 정해진 주기마다 재도전합니다.",
    }
    try:
        if CAPITAL_CHALLENGE_STATE_FILE.exists():
            loaded = json.loads(CAPITAL_CHALLENGE_STATE_FILE.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                state.update(loaded)
    except Exception as exc:
        state["load_error"] = str(exc)
    latest = latest_capital_growth_challenge()
    if latest:
        if not state.get("last_run_at"):
            state["last_run_at"] = latest.get("generated_at")
        if not state.get("last_id"):
            state["last_id"] = latest.get("id")
        if not state.get("last_result"):
            state["last_result"] = _capital_challenge_brief(latest)
        if int(state.get("run_count", 0) or 0) <= 0:
            state["run_count"] = max(1, len(_read_jsonl(CAPITAL_CHALLENGE_FILE, limit=400)))
    try:
        interval = max(3_600, int(state.get("interval_seconds", 21_600) or 21_600))
    except Exception:
        interval = 21_600
    state["interval_seconds"] = interval
    if state.get("last_run_at"):
        state["next_due_at"] = _capital_challenge_next_due(state.get("last_run_at"), interval)
        age = _iso_age_seconds(state.get("last_run_at"))
        state["seconds_until_due"] = max(0, interval - int(age or 0))
    else:
        state["next_due_at"] = now
        state["seconds_until_due"] = 0
    return state


def save_capital_challenge_state(state: dict[str, object]) -> dict[str, object]:
    state = dict(state or {})
    state["ok"] = True
    state["updated_at"] = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
    CAPITAL_CHALLENGE_STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
    CAPITAL_CHALLENGE_STATE_FILE.write_text(json.dumps(state, ensure_ascii=False, indent=2, sort_keys=True), encoding="utf-8")
    return state


def _remember_capital_challenge_run(record: dict[str, object], state: dict[str, object] | None = None) -> dict[str, object]:
    state = dict(state or load_capital_challenge_state())
    interval = max(3_600, int(state.get("interval_seconds", 21_600) or 21_600))
    state.update(
        {
            "enabled": bool(state.get("enabled", True)),
            "last_run_at": record.get("generated_at"),
            "last_id": record.get("id"),
            "last_result": _capital_challenge_brief(record),
            "next_due_at": _capital_challenge_next_due(record.get("generated_at"), interval),
            "seconds_until_due": interval,
            "last_status": "RAN",
            "last_source": record.get("source"),
            "run_count": int(state.get("run_count", 0) or 0) + 1,
        }
    )
    return save_capital_challenge_state(state)


def run_autonomous_capital_challenge_if_due(
    source: str = "ai-daemon-capital-challenge",
    force: bool = False,
    interval_seconds: int | None = None,
) -> dict[str, object]:
    state = load_capital_challenge_state()
    focus = build_operating_focus()
    if not force and not focus.get("large_batch_jobs_allowed"):
        return {
            "ok": True,
            "status": "DEFERRED_TO_MARKET_CLOSED_DAY",
            "state": state,
            "schedule": focus.get("large_batch_schedule"),
            "message": "100억 프로젝트 대형 훈련은 주말·공휴일로 연기했습니다.",
        }
    if interval_seconds is not None:
        state["interval_seconds"] = max(3_600, int(interval_seconds))
    interval = max(3_600, int(state.get("interval_seconds", 21_600) or 21_600))
    latest = latest_capital_growth_challenge()
    brief = _capital_challenge_brief(latest)
    if not bool(state.get("enabled", True)):
        state["last_status"] = "DISABLED"
        save_capital_challenge_state(state)
        return {"ok": True, "status": "DISABLED", "state": state, "latest": brief, "message": "100억 프로젝트 자동 도전이 꺼져 있습니다."}
    last_run_at = state.get("last_run_at") or (latest.get("generated_at") if latest else None)
    age = _iso_age_seconds(last_run_at)
    if not force and age is not None and age < interval:
        state["last_run_at"] = last_run_at
        state["last_id"] = state.get("last_id") or (latest.get("id") if latest else None)
        state["last_result"] = state.get("last_result") or brief
        state["last_status"] = "WAITING"
        state["next_due_at"] = _capital_challenge_next_due(last_run_at, interval)
        state["seconds_until_due"] = max(0, interval - int(age or 0))
        save_capital_challenge_state(state)
        return {
            "ok": True,
            "status": "WAITING",
            "state": state,
            "latest": brief,
            "message": f"다음 100억 프로젝트 재도전까지 약 {state['seconds_until_due']}초 남았습니다.",
        }
    try:
        record = run_capital_growth_challenge(
            initial_cash=float(state.get("initial_cash", 10_000_000) or 10_000_000),
            target_cash=float(state.get("target_cash", 10_000_000_000) or 10_000_000_000),
            source=source,
        )
        state = _remember_capital_challenge_run(record, state)
        return {
            "ok": True,
            "status": "RAN",
            "state": state,
            "challenge": _capital_challenge_brief(record),
            "latest": _capital_challenge_brief(record),
            "message": "AI가 100억 프로젝트에 재도전하고 결과를 장기기억에 기록했습니다.",
        }
    except Exception as exc:
        state["last_status"] = "ERROR"
        state["last_error"] = str(exc)
        save_capital_challenge_state(state)
        return {"ok": False, "status": "ERROR", "state": state, "latest": brief, "error": str(exc)}


def _market_series(symbol: str, days: int = 460) -> dict[str, object]:
    try:
        return _fetch_yahoo_chart(symbol, days=days)
    except Exception as exc:
        if symbol in {"^VIX", "^TNX"}:
            fallback = 18.0 if symbol == "^VIX" else 4.5
            rows = [
                {
                    "date": (datetime.now(timezone.utc).date() - timedelta(days=days - index)).isoformat(),
                    "close": fallback,
                }
                for index in range(days)
            ]
        else:
            prices = MARKET.history(symbol.replace("^", ""), min(days, 460))
            rows = [
                {
                    "date": (datetime.now(timezone.utc).date() - timedelta(days=len(prices) - index)).isoformat(),
                    "close": float(price),
                }
                for index, price in enumerate(prices)
            ]
        return {"source": f"fallback:{exc}", "rows": rows}


def _asset_gear(symbol: str, label: str, days: int = 460) -> dict[str, object]:
    series = _market_series(symbol, days=days)
    rows = [row for row in series.get("rows", []) if isinstance(row, dict)]
    closes = [float(row.get("close", 0) or 0) for row in rows if float(row.get("close", 0) or 0) > 0]
    if not closes:
        closes = MARKET.history(symbol.replace("^", ""), 220)
    price = closes[-1]
    sma200 = _series_sma(closes, 200)
    sma30w = _series_sma(closes, 150)
    return_4w = _series_pct_change(closes, 20)
    return_13w = _series_pct_change(closes, 65)
    return_1d = _series_pct_change(closes, 1)
    rsi14 = _series_rsi(closes, 14)
    dist_200 = ((price / sma200) - 1.0) * 100 if sma200 else 0.0
    dist_30w = ((price / sma30w) - 1.0) * 100 if sma30w else 0.0
    if price > sma200 * 1.02 and price > sma30w:
        gear = 3
        state = "상승 추세"
        score = 25
    elif price < sma200 * 0.98 or price < sma30w * 0.98:
        gear = 1
        state = "하락/방어"
        score = -25
    else:
        gear = 2
        state = "중립/횡보"
        score = 5
    return {
        "symbol": symbol,
        "label": label,
        "gear": gear,
        "state": state,
        "score": score,
        "price": round(price, 2),
        "sma200": round(sma200, 2),
        "sma30w": round(sma30w, 2),
        "distance_200d_pct": round(dist_200, 2),
        "distance_30w_pct": round(dist_30w, 2),
        "return_1d_pct": round(return_1d, 2),
        "return_4w_pct": round(return_4w, 2),
        "return_13w_pct": round(return_13w, 2),
        "rsi14": round(rsi14, 2),
        "source": str(series.get("source", "-")),
        "latest_date": rows[-1].get("date") if rows else today_kst(),
    }


def build_market_regime(force: bool = False) -> dict[str, object]:
    if not force:
        cached = _agent_cache_load(MARKET_REGIME_CACHE_FILE, ttl_seconds=60 * 30)
        if cached and isinstance(cached.get("payload"), dict):
            payload = dict(cached["payload"])
            cached_assets = payload.get("assets", []) if isinstance(payload.get("assets"), list) else []
            if cached_assets and all(isinstance(item, dict) and "return_1d_pct" in item for item in cached_assets):
                payload["cached"] = True
                return payload

    assets = [
        _asset_gear("SPY", "S&P500"),
        _asset_gear("QQQ", "Nasdaq100"),
        _asset_gear("SOXX", "반도체"),
    ]
    rsp = _asset_gear("RSP", "동일가중 S&P500")
    spy = assets[0]
    vix = _asset_gear("^VIX", "VIX 공포지수", days=90)
    tnx = _asset_gear("^TNX", "미국 10년물", days=120)
    breadth = float(rsp.get("return_4w_pct", 0) or 0) - float(spy.get("return_4w_pct", 0) or 0)
    vix_value = float(vix.get("price", 18) or 18)
    gear3_count = sum(1 for item in assets if int(item.get("gear", 0) or 0) == 3)
    gear1_count = sum(1 for item in assets if int(item.get("gear", 0) or 0) == 1)
    trend_component = sum(float(item.get("score", 0) or 0) for item in assets) / max(1, len(assets))
    breadth_component = 8 if breadth >= 1.5 else -10 if breadth <= -1.5 else 2 if breadth > 0 else -2
    if vix_value < 12:
        vix_component = -6
        vix_state = "도취 경계"
    elif vix_value <= 20:
        vix_component = 8
        vix_state = "정상 변동성"
    elif vix_value <= 30:
        vix_component = -10
        vix_state = "주의 변동성"
    else:
        vix_component = -18
        vix_state = "공포 구간"
    regime_score = round(_clamp(55 + trend_component + breadth_component + vix_component, 0, 100), 1)
    if regime_score >= 76 and gear3_count >= 2:
        stance = "공격 가능"
        mode = "attack"
        cash_range = "10~20%"
        allocation_multiplier = 1.0
        candidate_multiplier = 1.03
        new_buy_blocked = False
        leverage_allowed = True
    elif regime_score >= 61:
        stance = "정찰/분할 매수"
        mode = "scout"
        cash_range = "20~35%"
        allocation_multiplier = 0.75
        candidate_multiplier = 0.96
        new_buy_blocked = False
        leverage_allowed = False
    elif regime_score >= 46:
        stance = "관망/선별"
        mode = "watch"
        cash_range = "35~55%"
        allocation_multiplier = 0.5
        candidate_multiplier = 0.88
        new_buy_blocked = False
        leverage_allowed = False
    elif regime_score >= 31:
        stance = "방어/현금 확대"
        mode = "defense"
        cash_range = "55~75%"
        allocation_multiplier = 0.25
        candidate_multiplier = 0.72
        new_buy_blocked = gear1_count >= 2
        leverage_allowed = False
    else:
        stance = "리스크 오프"
        mode = "risk_off"
        cash_range = "75~90%"
        allocation_multiplier = 0.1
        candidate_multiplier = 0.55
        new_buy_blocked = True
        leverage_allowed = False

    reasons = []
    for item in assets:
        reasons.append(f"{item['label']} Gear {item['gear']}({item['state']})")
    reasons.append(f"브레드스 RSP-SPY 4주 {breadth:.2f}%")
    reasons.append(f"VIX {vix_value:.2f}: {vix_state}")
    if gear1_count:
        reasons.append("하락 Gear 자산이 있어 신규 진입 규모를 축소합니다.")
    if vix_value > 30:
        reasons.append("공포 구간은 분할 접근만 허용하고 레버리지는 금지합니다.")

    payload = {
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "cached": False,
        "engine": "EZLONG-inspired market regime",
        "score": regime_score,
        "stance": stance,
        "mode": mode,
        "headline": f"시장 국면 {stance} · 점수 {regime_score}/100 · 현금 {cash_range}",
        "assets": assets,
        "breadth": {
            "rsp_4w_pct": rsp.get("return_4w_pct", 0),
            "spy_4w_pct": spy.get("return_4w_pct", 0),
            "rsp_minus_spy_4w_pct": round(breadth, 2),
            "state": "참여폭 양호" if breadth >= 1.5 else "빅테크 쏠림 주의" if breadth <= -1.5 else "중립",
        },
        "volatility": {
            "vix": vix_value,
            "state": vix_state,
            "gear": vix.get("gear"),
            "source": vix.get("source", "-"),
        },
        "rates": {
            "tnx": tnx.get("price", 0),
            "state": "금리 부담 점검" if float(tnx.get("price", 0) or 0) >= 4.5 else "금리 중립",
            "source": tnx.get("source", "-"),
        },
        "automation": {
            "cash_range": cash_range,
            "allocation_multiplier": allocation_multiplier,
            "candidate_score_multiplier": candidate_multiplier,
            "new_buy_blocked": new_buy_blocked,
            "leverage_allowed": leverage_allowed,
            "tranches": [30, 30, 40] if not new_buy_blocked else [0, 0, 0],
            "max_leverage_position_pct": 10 if leverage_allowed else 0,
        },
        "rules": [
            "Gear 3: 200일선과 30주선 위, 상승 추세. 분할 진입 가능.",
            "Gear 2: 방향 불명확. 정찰대와 검증 위주.",
            "Gear 1: 하락/방어. 신규 매수 축소, 현금 확보.",
            "3-3-4 분할 집행: 1차 30%, 확인 후 2차 30%, 추세 확정 후 3차 40%.",
        ],
        "reasons": reasons,
        "source_note": "Yahoo chart 우선, 실패 시 로컬 시뮬레이션 폴백. 참고용 위험 필터이며 수익을 보장하지 않습니다.",
    }
    _agent_cache_save(MARKET_REGIME_CACHE_FILE, payload)
    return payload


def build_screener_targets(limit: int = 16) -> list[dict[str, object]]:
    preferred = ["083450", "005930", "000660", "042700", "403870", "095340", "240810", "058470", "NVDA", "TSM", "AVGO", "AMD", "MSFT", "AAPL"]
    rows_by_symbol = {row["symbol"]: row for row in _lookup_symbols(preferred)}
    try:
        work_date, kr_rows = fetch_kr_market_rows()
        intraday_theme_map = _intraday_theme_map_from_rows(kr_rows)
        for row in kr_rows:
            symbol = str(row.get("symbol", "")).upper()
            if symbol in rows_by_symbol:
                rows_by_symbol[symbol].update(
                    {
                        "name": row.get("name", rows_by_symbol[symbol].get("name", symbol)),
                        "market": f"KR-{row.get('market', 'KR')}",
                        "change_pct": row.get("change_pct", rows_by_symbol[symbol].get("change_pct", 0)),
                        "amount": row.get("amount", rows_by_symbol[symbol].get("amount", 0)),
                        "volume": row.get("volume", rows_by_symbol[symbol].get("volume", 0)),
                        "close": row.get("close", rows_by_symbol[symbol].get("close", 0)),
                        "marcap": row.get("marcap", rows_by_symbol[symbol].get("marcap", 0)),
                        "intraday_theme": intraday_theme_map.get(symbol, {}),
                        "source": f"KRX-{work_date}",
                    }
                )
        liquid = [row for row in kr_rows if float(row.get("amount", 0)) >= 5_000_000_000]
        ranked_kr = sorted(liquid, key=lambda row: (float(row.get("change_pct", 0)) * 2, float(row.get("amount", 0)) / 100_000_000), reverse=True)
        for row in ranked_kr[:24]:
            symbol = str(row.get("symbol", "")).upper()
            if symbol and symbol not in rows_by_symbol:
                rows_by_symbol[symbol] = {
                    "symbol": symbol,
                    "name": row.get("name", symbol),
                    "market": f"KR-{row.get('market', 'KR')}",
                    "change_pct": row.get("change_pct", 0),
                    "amount": row.get("amount", 0),
                    "volume": row.get("volume", 0),
                    "close": row.get("close", 0),
                    "marcap": row.get("marcap", 0),
                    "intraday_theme": intraday_theme_map.get(symbol, {}),
                    "source": f"KRX-{work_date}",
                }
    except Exception:
        pass
    memory = MEMORY.summary()
    for item in memory.get("top_candidates", [])[:8]:
        if isinstance(item, dict):
            symbol = str(item.get("symbol", "")).upper()
            if symbol and symbol not in rows_by_symbol:
                rows_by_symbol[symbol] = {"symbol": symbol, "name": item.get("name", symbol), "market": item.get("market", "-"), "source": "장기기억"}
    rows = []
    for symbol in preferred:
        if symbol in rows_by_symbol:
            rows.append(rows_by_symbol.pop(symbol))
    rows.extend(rows_by_symbol.values())
    return rows[:limit]


def _company_quality_profile(row: dict[str, object]) -> dict[str, object]:
    """실전 후보와 추천 카드가 같은 '좋은 회사' 기준을 쓰게 만드는 내부 품질 점검."""
    symbol = str(row.get("symbol", "")).upper().strip()
    is_kr = bool(symbol.isdigit() and len(symbol) == 6)
    market_signal = row.get("market_signal") if isinstance(row.get("market_signal"), dict) else {}
    signal = market_signal.get("signal") if isinstance(market_signal.get("signal"), dict) else {}
    reasons = [str(item) for item in row.get("reasons", [])] if isinstance(row.get("reasons"), list) else []
    risks = [str(item) for item in row.get("risk_flags", [])] if isinstance(row.get("risk_flags"), list) else []
    sector_signal = row.get("sector_news_signal") if isinstance(row.get("sector_news_signal"), dict) else {}
    sector_matches = sector_signal.get("matched") if isinstance(sector_signal.get("matched"), list) else []
    text = " ".join(
        [
            str(row.get("name", "")),
            str(row.get("market", "")),
            str(row.get("financial_stance", "")),
            str(row.get("news_stance", "")),
            str(row.get("market_signal_label", "")),
            str(sector_signal.get("label", "")),
            str(sector_signal.get("summary", "")),
            " ".join(reasons),
            " ".join(risks),
            " ".join(str(item) for item in sector_matches),
        ]
    )
    risk_text = " ".join(risks)
    price = _number(row.get("price") or row.get("estimated_price") or signal.get("price") or market_signal.get("price"))
    amount = _number(row.get("amount") or row.get("trade_value") or signal.get("amount") or market_signal.get("amount"))
    financial_score = _number(row.get("financial_score"))
    score = _number(row.get("score"))
    sector_delta = _number(row.get("sector_news_score_delta"))
    mdd = abs(_number(row.get("mdd_pct")))
    change_pct = abs(_number(row.get("change_pct")))

    quality_score = 18.0
    quality_reasons: list[str] = []
    blockers: list[str] = []
    warnings: list[str] = []
    moat_universe = {
        "005930": "글로벌 메모리·스마트폰·파운드리 핵심 대형주",
        "000660": "HBM/메모리 글로벌 핵심 공급사",
        "083450": "반도체 후공정·액침냉각 기술 보유 후보",
        "042700": "반도체 장비 핵심 공급망 후보",
        "095340": "반도체 테스트 소켓 기술 후보",
        "240810": "반도체 소재/부품 공급망 후보",
        "058470": "반도체/전자부품 공급망 후보",
        "NVDA": "AI 가속기 글로벌 시장지위 핵심주",
        "TSM": "글로벌 파운드리 시장지위 핵심주",
        "AVGO": "AI 네트워크/반도체 인프라 핵심 공급사",
        "AMD": "AI/CPU/GPU 경쟁력 보유 대형주",
        "MSFT": "클라우드/AI 플랫폼 대형주",
        "AAPL": "글로벌 소비자 플랫폼 대형주",
    }

    severe_keywords = ("거래정지", "상장폐지", "관리종목", "투자주의", "가격조회 실패", "조회 실패", "시세 미확인", "실전 차단")
    if any(keyword in risk_text for keyword in severe_keywords):
        blockers.append("시세/거래 리스크 확인 전까지 제외")
    if is_kr and price and price < 5_000:
        blockers.append("동전주·저가 투기주 기준 제외")
    if is_kr and amount and amount < 1_000_000_000:
        warnings.append("거래대금 부족")
        quality_score -= 8
    if financial_score <= 0 and is_kr:
        blockers.append("재무제표 점수 미확인")
    elif financial_score >= 85:
        quality_score += 30
        quality_reasons.append("재무제표 매우 우수")
    elif financial_score >= 70:
        quality_score += 23
        quality_reasons.append("재무제표 우수")
    elif financial_score >= 55:
        quality_score += 12
        quality_reasons.append("재무제표 보통 이상")
    elif financial_score > 0:
        blockers.append("재무점수 55 미만")

    moat_keywords = (
        "시장점유율", "점유율", "1위", "과점", "독점", "고객사", "거래처", "공급계약", "공급",
        "수주", "파트너", "기술력", "특허", "장비", "소재", "후공정", "액침냉각", "HBM",
        "AI", "반도체", "클라우드", "데이터센터",
    )
    moat_hits = [word for word in moat_keywords if word.upper() in text.upper()]
    if moat_hits:
        quality_score += min(24, 5 * len(moat_hits))
        quality_reasons.append("점유율·기술력·거래처 단서 확인")
    elif symbol in moat_universe:
        quality_score += 20
        quality_reasons.append(moat_universe[symbol])
    else:
        warnings.append("점유율/기술력/거래처 단서 추가 확인 필요")
    if symbol in moat_universe and moat_universe[symbol] not in quality_reasons:
        quality_score += 12
        quality_reasons.append(moat_universe[symbol])
    if not is_kr and symbol in moat_universe and financial_score <= 0:
        quality_score += 18
        warnings.append("해외 재무제표 정밀 연결 필요")

    if amount >= 20_000_000_000:
        quality_score += 10
        quality_reasons.append("거래대금 충분")
    elif amount >= 5_000_000_000:
        quality_score += 5
    if sector_delta >= 4:
        quality_score += 10
        quality_reasons.append("섹터 뉴스 우호")
    elif sector_delta > 0:
        quality_score += 5
    if score >= 78:
        quality_score += 8
    if mdd >= 45:
        quality_score -= 10
        warnings.append("과거 낙폭 큼")
    if change_pct >= 25:
        blockers.append("단기 급등 투기 후보 제외")
    elif change_pct >= 15:
        quality_score -= 8
        warnings.append("단기 급등 부담")

    quality_score = round(_clamp(quality_score, 0, 100), 1)
    if quality_score >= 82:
        grade = "A"
    elif quality_score >= 68:
        grade = "B"
    elif quality_score >= 55:
        grade = "C"
    else:
        grade = "D"
    is_quality_candidate = bool(not blockers and quality_score >= 55)
    return {
        "score": quality_score,
        "grade": grade,
        "is_quality_candidate": is_quality_candidate,
        "reasons": quality_reasons[:4],
        "warnings": warnings[:4],
        "blockers": blockers[:4],
        "rule": "동전주/잡주 제외 + 재무점수 + 점유율/기술력/거래처 단서 + 거래대금 + 섹터 우호",
    }


def _trade_horizon_profile(row: dict[str, object], quality: dict[str, object] | None = None, kr_session: dict[str, object] | None = None) -> dict[str, object]:
    quality = quality or {}
    kr_session = kr_session or {}
    intraday_theme = row.get("intraday_theme") if isinstance(row.get("intraday_theme"), dict) else {}
    amount = _number(row.get("amount"))
    volume = _number(row.get("volume"))
    marcap = _number(row.get("marcap") or row.get("market_cap"))
    change_pct = _number(row.get("change_pct"))
    financial_score = _number(row.get("financial_score"))
    sector_delta = _number(row.get("sector_news_score_delta"))
    quality_score = _number(quality.get("score") or row.get("quality_score"))
    return_pct = _number(row.get("return_pct"))
    mdd = abs(_number(row.get("mdd_pct")))
    score = _number(row.get("score"))
    market = str(row.get("market", "")).upper()
    symbol = str(row.get("symbol", "")).upper().strip()
    is_kr = bool(symbol.isdigit() and len(symbol) == 6)
    risk_flags = [str(item) for item in row.get("risk_flags", [])] if isinstance(row.get("risk_flags"), list) else []
    blockers = [str(item) for item in quality.get("blockers", [])] if isinstance(quality.get("blockers"), list) else []
    risk_text = " ".join(risk_flags + blockers)
    regular_open = bool(kr_session.get("is_regular_open"))
    phase_label = str(kr_session.get("phase_label", "-"))
    now_time = datetime.now(_zone("Asia/Seoul", 9)).time()
    in_theme_entry_window = dt_time(9, 30) <= now_time <= dt_time(14, 20)
    early_open_wait = regular_open and now_time < dt_time(9, 30)
    late_entry_block = regular_open and now_time > dt_time(14, 20)
    theme_confirmed = bool(intraday_theme.get("confirmed"))
    theme_rank = int(_number(intraday_theme.get("leader_rank")) or 0)
    daytrade_study = build_daytrader_strategy_study(force=False, persist=False)
    study_weights = daytrade_study.get("rule_weights", {}) if isinstance(daytrade_study.get("rule_weights"), dict) else {}
    study_score = _number(daytrade_study.get("study_score"))
    strict_amount_krw = _number(study_weights.get("strict_amount_krw")) or 100_000_000_000.0
    watch_amount_krw = _number(study_weights.get("small_account_watch_amount_krw")) or 30_000_000_000.0
    study_rules = [
        str(rule.get("name"))
        for rule in (daytrade_study.get("distilled_rules", []) if isinstance(daytrade_study.get("distilled_rules"), list) else [])
        if isinstance(rule, dict) and rule.get("name")
    ][:4]

    day_score = 0.0
    day_reasons: list[str] = []
    day_risks: list[str] = []
    if is_kr and regular_open:
        day_score += 12
        day_reasons.append("정규장 중 단타 판단 가능")
    elif is_kr:
        day_risks.append(f"현재 {phase_label}: 단타 신규 진입 보류")
    else:
        day_risks.append("해외 종목은 현재 국내 단타 엔진 대상 아님")
    if early_open_wait:
        day_score -= 14
        day_risks.append("9:30 전 주도테마 확인 대기")
    elif late_entry_block:
        day_score -= 18
        day_risks.append("14:20 이후 신규 단타 진입 금지")
    elif in_theme_entry_window:
        day_score += 8
        day_reasons.append("단타 진입 가능 시간대")
    if theme_confirmed:
        day_score += 18
        theme_name = str(intraday_theme.get("name") or "주도테마")
        day_reasons.append(f"주도테마 확인: {theme_name}")
        if 1 <= theme_rank <= 2:
            day_score += 8
            day_reasons.append("테마 대장주 후보")
    else:
        day_score -= 18
        day_risks.append("주도테마/대장주 조건 미확인")
    if amount >= 200_000_000_000:
        day_score += 32
        day_reasons.append("초대형 거래대금")
    elif amount >= 100_000_000_000:
        day_score += 25
        day_reasons.append("거래대금 1000억 이상")
    elif amount >= 50_000_000_000:
        day_score += 16
        day_reasons.append("거래대금 500억 이상")
    elif amount >= 20_000_000_000:
        day_score += 8
        day_reasons.append("거래대금 동반")
    elif amount >= 5_000_000_000:
        day_score += 8
        day_reasons.append("최소 유동성 확인")
    else:
        day_risks.append("거래대금 부족")
    if amount >= watch_amount_krw:
        day_score += 4
        day_reasons.append(f"단타 공부 기준 거래대금 {watch_amount_krw / 100_000_000:,.0f}억 통과")
    elif amount > 0 and amount < watch_amount_krw and "단타" in str(row.get("trade_mode", "")):
        day_risks.append(f"학습 기준 거래대금 미달: {watch_amount_krw / 100_000_000:,.0f}억")
    if amount >= strict_amount_krw:
        day_score += 2
    if study_score >= 70 and theme_confirmed and 1 <= theme_rank <= 2:
        day_score += 5
        day_reasons.append("단타 공부 엔진: 주도테마 대장주 가산")
    if volume >= 5_000_000:
        day_score += 12
        day_reasons.append("거래량 급증 후보")
    elif volume >= 1_000_000:
        day_score += 7
    if 1.0 <= change_pct <= 8.0:
        day_score += 18
        day_reasons.append("당일 상대강도 양호")
    elif 8.0 < change_pct <= 15.0:
        day_score += 6
        day_risks.append("단기 과열 가능성")
    elif change_pct >= 15.0:
        day_score -= 18
        day_risks.append("급등 과열 단타 금지")
    elif change_pct <= -2.5:
        day_score -= 10
        day_risks.append("당일 약세")
    if "시세 미확인" in risk_text or "거래정지" in risk_text or "관리종목" in risk_text:
        day_score -= 30
        day_risks.append("단타 시세/거래 리스크")
    if 300_000_000_000 <= marcap <= 10_000_000_000_000:
        day_score += 10
        day_reasons.append("단타 적정 시총 범위")
    elif marcap > 10_000_000_000_000:
        day_score += 4
        day_risks.append("10조 이상 대형주는 변동성 제한")
    elif marcap >= 300_000_000_000:
        day_score += 6
    elif marcap > 0:
        day_score -= 8
        day_risks.append("시총 3000억 미만 단타 제외 후보")

    swing_score = 0.0
    swing_reasons: list[str] = []
    swing_risks: list[str] = []
    if quality.get("is_quality_candidate"):
        swing_score += min(quality_score, 100) * 0.38
        swing_reasons.append(f"품질 {quality.get('grade', '-')}")
    else:
        swing_score -= 15
        swing_risks.append("품질 기준 미통과")
    swing_score += min(financial_score, 100) * 0.22
    if financial_score >= 70:
        swing_reasons.append("재무 우수")
    swing_score += _clamp(sector_delta, -8, 10) * 2.2
    if sector_delta > 0:
        swing_reasons.append("섹터 우호")
    swing_score += _clamp(return_pct, -50, 180) / 180 * 18
    if return_pct > 30:
        swing_reasons.append("장기 백테스트 우위")
    if mdd >= 45:
        swing_score -= 12
        swing_risks.append("과거 낙폭 큼")
    elif mdd <= 30:
        swing_score += 6
    if score >= 70:
        swing_score += 8
    if "뉴스 주의" in risk_text:
        swing_score -= 8
        swing_risks.append("뉴스 리스크")

    day_score = round(_clamp(day_score, 0, 100), 1)
    swing_score = round(_clamp(swing_score, 0, 100), 1)
    daytrade_entry_allowed = bool(day_score >= 72 and day_score >= swing_score + 8 and theme_confirmed and in_theme_entry_window)
    if daytrade_entry_allowed:
        mode = "단타"
        strategy_mode = "intraday_flow"
        hold_rule = "당일 수급 우선. -1%대 흔들림은 소프트 손절로 재확인하고, 하드 손절/장마감/수급훼손 때만 청산."
        soft_stop_pct = 1.2
        stop_loss_pct = 1.8
        take_profit_pct = 2.2
    elif swing_score >= 58:
        mode = "스윙"
        strategy_mode = "quality_swing"
        hold_rule = "3~20거래일 품질/섹터/추세 유지 여부를 보며 분할 청산 판단."
        soft_stop_pct = 0.0
        stop_loss_pct = 2.0
        take_profit_pct = 5.0 if quality_score >= 70 else 3.0
    elif day_score >= 55:
        mode = "단타 관찰"
        strategy_mode = "intraday_watch"
        hold_rule = "수급은 있으나 확률 우위가 부족합니다. 작은 손절 구간은 재확인하고, 하드 손절 때만 청산."
        soft_stop_pct = 1.0
        stop_loss_pct = 1.5
        take_profit_pct = 1.8
    else:
        mode = "관망"
        strategy_mode = "research_only"
        hold_rule = "단타/스윙 모두 우위 부족. 연구와 모의훈련만 수행."
        soft_stop_pct = 0.0
        stop_loss_pct = 2.0
        take_profit_pct = 3.0
    return {
        "mode": mode,
        "strategy_mode": strategy_mode,
        "daytrade_score": day_score,
        "swing_score": swing_score,
        "hold_rule": hold_rule,
        "soft_stop_pct": soft_stop_pct,
        "stop_loss_pct": stop_loss_pct,
        "take_profit_pct": take_profit_pct,
        "daytrade_reasons": day_reasons[:4],
        "daytrade_risks": day_risks[:4],
        "swing_reasons": swing_reasons[:4],
        "swing_risks": swing_risks[:4],
        "daytrade_criteria": {
            "entry_allowed": daytrade_entry_allowed,
            "theme_confirmed": theme_confirmed,
            "theme": intraday_theme,
            "entry_window": in_theme_entry_window,
            "early_open_wait": early_open_wait,
            "late_entry_block": late_entry_block,
            "study_score": study_score,
            "study_rules": study_rules,
            "study_amount_filter_krw": watch_amount_krw,
            "study_note_path": daytrade_study.get("note_path"),
            "source_model": "불개미/홍인기 공개 원칙 지속 학습 기반: 주도테마, 거래대금, 대장주, 시간대, 손절/비중",
        },
        "inputs": {
            "amount": amount,
            "volume": volume,
            "marcap": marcap,
            "change_pct": change_pct,
            "quality_score": quality_score,
            "financial_score": financial_score,
            "sector_delta": sector_delta,
            "regular_open": regular_open,
            "market": market,
        },
    }


def build_ai_screener(
    symbols: list[str] | None = None,
    force: bool = False,
    *,
    allow_stale_health_cache: bool = False,
) -> dict[str, object]:
    if not force and not symbols:
        cached = _agent_cache_load(AGENT_SCREENER_CACHE_FILE, ttl_seconds=60 * 10)
        health_probe_cache = False
        if cached is None and allow_stale_health_cache and AGENT_SCREENER_CACHE_FILE.exists():
            try:
                raw_cache = json.loads(AGENT_SCREENER_CACHE_FILE.read_text(encoding="utf-8"))
                if isinstance(raw_cache, dict) and isinstance(raw_cache.get("payload"), dict):
                    cached = raw_cache
                    health_probe_cache = True
            except Exception:
                cached = None
        if cached and isinstance(cached.get("payload"), dict):
            payload = dict(cached["payload"])
            cached_candidates = payload.get("candidates") if isinstance(payload.get("candidates"), list) else []
            score_cache_current = bool(cached_candidates and _candidate_score_cache_is_current(cached_candidates))
            learning_cache_current = bool(cached_candidates and _candidate_learning_cache_is_current(cached_candidates))
            learning_trace_refreshed = False
            if not health_probe_cache and score_cache_current and not learning_cache_current:
                learning_insight = build_ai_learning_insights(force=False, persist=False)
                refreshed_candidates = [
                    _refresh_candidate_learning_trace(row, learning_insight)
                    for row in cached_candidates
                    if isinstance(row, dict)
                ]
                refreshed_candidates.sort(key=_candidate_sort_key)
                for rank, row in enumerate(refreshed_candidates, start=1):
                    row["rank"] = rank
                    row["ranking_vector"] = {
                        "display_score": _candidate_ranking_vector(row)[0],
                        "raw_score": _candidate_ranking_vector(row)[1],
                        "quality_score": _candidate_ranking_vector(row)[2],
                        "financial_score": _candidate_ranking_vector(row)[3],
                        "profit_factor": _candidate_ranking_vector(row)[4],
                        "mdd_pct": _candidate_ranking_vector(row)[5],
                        "symbol_final_tiebreak": str(row.get("symbol") or "").upper(),
                    }
                if _candidate_learning_cache_is_current(refreshed_candidates):
                    cached_candidates = refreshed_candidates
                    payload["candidates"] = refreshed_candidates
                    payload["top"] = refreshed_candidates[0] if refreshed_candidates else None
                    learning_payload = payload.get("learning") if isinstance(payload.get("learning"), dict) else {}
                    learning_payload.update({
                        "score": learning_insight.get("learning_score"),
                        "generated_at": learning_insight.get("generated_at"),
                        "policy_version": LEARNING_MEMORY_POLICY_VERSION,
                        "evidence_fingerprint": learning_insight.get("learning_evidence_fingerprint"),
                        "score_applied_candidate_count": sum(
                            1 for row in refreshed_candidates if row.get("learning_bias_applied_to_score")
                        ),
                        "candidate_count": len(refreshed_candidates),
                    })
                    payload["learning"] = learning_payload
                    payload["learning_trace_refreshed_at"] = datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds")
                    learning_cache_current = True
                    learning_trace_refreshed = True
            cache_policy_current = bool(
                not health_probe_cache
                and score_cache_current
                and learning_cache_current
            )
            if cache_policy_current:
                # Candidate generation is expensive, but these policy views are cheap.
                # Reuse only candidates whose score ledger matches the current policy.
                payload["candidate_lanes"] = _candidate_lane_summary(cached_candidates)
                payload["score_saturation_audit"] = _candidate_score_saturation_audit(cached_candidates)
                payload["sector_promotion_board"] = _candidate_sector_promotion_board(
                    cached_candidates, max_per_sector=2, limit=10
                )
                payload["sector_concentration_audit"] = _candidate_sector_concentration_audit(cached_candidates)
                payload["sector_concentration_audit"]["promotion_board"] = payload["sector_promotion_board"]
                if learning_trace_refreshed:
                    _agent_cache_save(
                        AGENT_SCREENER_CACHE_FILE,
                        payload,
                        saved_at=float(cached.get("saved_at", 0) or time.time()),
                    )
            if cache_policy_current or health_probe_cache:
                payload["cached"] = True
                payload["health_probe_cache"] = health_probe_cache
                payload["cache_policy_current"] = cache_policy_current
                payload["cache_refresh_required"] = not cache_policy_current
                payload["learning_trace_refreshed"] = learning_trace_refreshed
                payload["cache_age_seconds"] = round(
                    max(0.0, time.time() - float(cached.get("saved_at", 0) or 0)),
                    2,
                )
                return payload
    targets = _lookup_symbols(symbols) if symbols else build_screener_targets()
    target_symbols = [str(row.get("symbol", "")).upper() for row in targets if row.get("symbol")]
    radar = build_agent_radar(symbols=target_symbols[:8], force=force)
    news_map = {str(row.get("symbol", "")).upper(): row for row in radar.get("news", []) if isinstance(row, dict)}
    financial_map = {str(row.get("symbol", "")).upper(): row for row in radar.get("financials", []) if isinstance(row, dict)}
    toss_public = radar.get("toss_public") if isinstance(radar.get("toss_public"), dict) else {}
    toss_map = {
        str(row.get("symbol", "")).upper(): row
        for row in toss_public.get("items", [])
        if isinstance(row, dict) and row.get("symbol")
    }
    market_regime = build_market_regime(force=force)
    regime_auto = market_regime.get("automation", {}) if isinstance(market_regime.get("automation"), dict) else {}
    base_regime_multiplier = float(regime_auto.get("candidate_score_multiplier", 1.0) or 1.0)
    new_buy_blocked = bool(regime_auto.get("new_buy_blocked"))
    sector_report = build_sector_news_report(force=force)
    sector_map = {
        str(sector.get("id", "")): sector
        for sector in sector_report.get("sectors", [])
        if isinstance(sector, dict) and sector.get("id")
    }
    learning_insight = build_ai_learning_insights(force=force, persist=False)
    try:
        market_clock = build_market_session_clock()
        kr_session = next((item for item in market_clock.get("sessions", []) if isinstance(item, dict) and item.get("id") == "KR"), {})
    except Exception:
        kr_session = {}
    candidates = []
    for row in targets:
        symbol = str(row.get("symbol", "")).upper()
        if not symbol:
            continue
        benchmark = "069500" if symbol.isdigit() else "SPY"
        reasons = []
        risk_flags = []
        try:
            backtest = BACKTESTER.run_ma_cross_range(symbol, "2020-01-01", today_kst(), 12, 32)
        except Exception as exc:
            backtest = {"total_return_pct": 0, "max_drawdown_pct": 0, "trade_quality": {}, "error": str(exc)}
            risk_flags.append(f"백테스트 오류: {exc}")
        risk_gate = OPS.evaluate_backtest_risk_gate(backtest)
        quality = backtest.get("trade_quality", {}) if isinstance(backtest, dict) else {}
        total_return = float(backtest.get("total_return_pct", 0) or 0)
        mdd = float(backtest.get("max_drawdown_pct", 0) or 0)
        win_rate = float(quality.get("win_rate_pct", 0) or 0)
        profit_factor = float(quality.get("profit_factor", 0) or 0)
        news = news_map.get(symbol, {})
        financial = financial_map.get(symbol, {})
        toss_signal_row = toss_map.get(symbol, {})
        toss_signal = toss_signal_row.get("signal") if isinstance(toss_signal_row.get("signal"), dict) else {}
        news_score = float(news.get("score", 0) or 0)
        financial_score = float(financial.get("score", 0) or 0)
        toss_component = _clamp(float(toss_signal.get("score_delta", 0) or 0), -8, 8)
        sector_signal = build_sector_news_signal(row, sector_map)
        sector_component = _clamp(float(sector_signal.get("score_delta", 0) or 0), -8, 10)
        change_pct = float(row.get("change_pct", 0) or 0)
        amount = float(row.get("amount", 0) or 0)
        backtest_component = _clamp(total_return, -50, 250) / 250 * 24
        mdd_component = 12 - _clamp(abs(mdd), 0, 55) / 55 * 12
        quality_component = _clamp(win_rate, 0, 80) / 80 * 8 + _clamp(profit_factor, 0, 3) / 3 * 6
        financial_component = _clamp(financial_score, 0, 100) / 100 * 20
        news_component = _clamp(news_score, -6, 8) * 1.5
        market_component = 0
        if amount >= 20_000_000_000:
            market_component += 6
            reasons.append("거래대금 동반")
        elif amount >= 5_000_000_000:
            market_component += 3
        if change_pct > 3:
            market_component += 4
            reasons.append("당일 상대강도")
        elif change_pct < -3:
            market_component -= 4
            risk_flags.append("당일 약세")
        theme_bonus = 0
        haystack = f"{row.get('name', '')} {symbol}".upper()
        if any(word in haystack for word in ["GST", "반도체", "NVDA", "TSM", "AVGO", "AMD", "HPSP", "ISC", "한미"]):
            theme_bonus = 5
            reasons.append("AI/반도체 핵심 테마")
        if financial_score >= 75:
            reasons.append(str(financial.get("stance", "재무 우수")))
        elif financial_score and financial_score < 50:
            risk_flags.append(str(financial.get("stance", "재무 점검")))
        if news_score > 0:
            reasons.append(str(news.get("stance", "뉴스 긍정")))
        elif news_score < 0:
            risk_flags.append(str(news.get("stance", "뉴스 주의")))
        if toss_signal_row.get("ok"):
            toss_label = str(toss_signal.get("label", "공개 시세"))
            if toss_component > 0:
                reasons.append(f"토스 공개 시세 {toss_label}")
            elif toss_component < 0:
                risk_flags.append(f"토스 공개 시세 {toss_label}")
        elif symbol.isdigit():
            risk_flags.append("토스 공개 시세 미확인")
        if sector_signal.get("matched"):
            sector_label = str(sector_signal.get("label", "섹터뉴스"))
            if sector_component > 0:
                reasons.append(f"섹터뉴스 {sector_label}")
            elif sector_component < 0:
                risk_flags.append(f"섹터뉴스 {sector_label}")
        if total_return > 50:
            reasons.append("장기 백테스트 우위")
        if mdd < -35:
            risk_flags.append("낙폭 큼")
        market_name = str(row.get("market", "-")).upper()
        regime_multiplier = base_regime_multiplier if not symbol.isdigit() else 1 + ((base_regime_multiplier - 1) * 0.65)
        score_component_values = {
            "base": 12,
            "backtest": round(backtest_component, 2),
            "mdd": round(mdd_component, 2),
            "quality": round(quality_component, 2),
            "financial": round(financial_component, 2),
            "news": round(news_component, 2),
            "market": round(market_component, 2),
            "theme": round(theme_bonus, 2),
            "toss_public": round(toss_component, 2),
            "sector_news": round(sector_component, 2),
        }
        score_dedup_audit = _deduplicate_candidate_score_components(score_component_values)
        pre_dedup_score = _number(score_dedup_audit.get("original_component_total")) * regime_multiplier
        score = _number(score_dedup_audit.get("effective_component_total")) * regime_multiplier
        reasons.append(f"시장 국면: {market_regime.get('stance', '-')}")
        new_buy_penalty = 0
        if new_buy_blocked:
            new_buy_penalty = 12 if "US" in market_name or not symbol.isdigit() else 8
            score -= new_buy_penalty
            pre_dedup_score -= new_buy_penalty
            risk_flags.append("시장 국면이 방어/리스크오프라 신규 매수를 축소합니다.")
        raw_score = round(score, 2)
        pre_dedup_raw_score = round(pre_dedup_score, 2)
        duplicate_bonus_removed = round(max(0.0, pre_dedup_raw_score - raw_score), 2)
        score_dedup_audit.update({
            "regime_multiplier": round(regime_multiplier, 3),
            "pre_dedup_raw_score": pre_dedup_raw_score,
            "post_dedup_raw_score": raw_score,
            "removed_points_after_regime": duplicate_bonus_removed,
        })
        display_score = _desaturate_candidate_score(raw_score)
        if display_score >= 78 and not any("뉴스 주의" in flag or "백테스트 오류" in flag for flag in risk_flags):
            action = "집중 연구"
        elif display_score >= 62:
            action = "관심 편입"
        elif display_score >= 48:
            action = "관찰"
        else:
            action = "보류"
        candidate = {
            "symbol": symbol,
            "name": row.get("name", symbol),
            "market": row.get("market", "-"),
            "score": display_score,
            "raw_score": raw_score,
            "pre_dedup_raw_score": pre_dedup_raw_score,
            "duplicate_bonus_removed": duplicate_bonus_removed,
            "score_dedup_audit": score_dedup_audit,
            "score_adjustment": {
                "method": "anti_saturation_curve",
                "raw_score": raw_score,
                "display_score": display_score,
                "compressed": bool(raw_score > display_score),
                "compression_delta": round(raw_score - display_score, 2),
            },
            "score_components": {
                **score_component_values,
                "regime_multiplier": round(regime_multiplier, 3),
                "new_buy_block_penalty": new_buy_penalty,
            },
            "action": action,
            "reasons": reasons[:5] or ["데이터 누적 관찰"],
            "risk_flags": risk_flags[:5],
            "financial_score": financial_score,
            "financial_stance": financial.get("stance", "-"),
            "news_score": news_score,
            "news_stance": news.get("stance", "-"),
            "market_signal": toss_signal_row,
            "market_signal_label": toss_signal.get("label", "-"),
            "market_signal_score_delta": toss_component,
            "sector_news_signal": sector_signal,
            "sector_news_score_delta": sector_component,
            "return_pct": total_return,
            "mdd_pct": mdd,
            "win_rate_pct": win_rate,
            "profit_factor": profit_factor,
            "change_pct": change_pct,
            "amount": amount,
            "volume": row.get("volume", 0),
            "marcap": row.get("marcap", 0),
            "intraday_theme": row.get("intraday_theme", {}),
            "benchmark": benchmark,
            "risk_gate_status": risk_gate.get("status"),
            "risk_gate_message": risk_gate.get("message"),
            "risk_gate_failed": [item.get("name") for item in risk_gate.get("failed", [])],
            "market_regime_stance": market_regime.get("stance"),
            "market_regime_score": market_regime.get("score"),
            "market_regime_multiplier": round(regime_multiplier, 3),
            "market_regime_blocked": new_buy_blocked,
        }
        company_quality = _company_quality_profile(candidate)
        candidate["company_quality"] = company_quality
        candidate["quality_score"] = company_quality.get("score", 0)
        candidate["quality_grade"] = company_quality.get("grade", "D")
        for reason in company_quality.get("reasons", []):
            if reason not in candidate["reasons"]:
                candidate["reasons"].append(reason)
        for blocker in company_quality.get("blockers", []):
            if blocker not in candidate["risk_flags"]:
                candidate["risk_flags"].append(blocker)
        candidate["reasons"] = candidate["reasons"][:6]
        candidate["risk_flags"] = candidate["risk_flags"][:6]
        if not company_quality.get("is_quality_candidate"):
            penalty = 12 if company_quality.get("blockers") else 5
            candidate["raw_score"] = round(_number(candidate.get("raw_score")) - penalty, 2)
            candidate["pre_dedup_raw_score"] = round(_number(candidate.get("pre_dedup_raw_score")) - penalty, 2)
            candidate["score"] = _desaturate_candidate_score(candidate["raw_score"])
            adjustment = candidate.get("score_adjustment") if isinstance(candidate.get("score_adjustment"), dict) else {}
            adjustment.update({
                "raw_score": candidate["raw_score"],
                "display_score": candidate["score"],
                "compressed": bool(_number(candidate.get("raw_score")) > _number(candidate.get("score"))),
                "compression_delta": round(_number(candidate.get("raw_score")) - _number(candidate.get("score")), 2),
                "quality_penalty": penalty,
            })
            candidate["score_adjustment"] = adjustment
            if candidate["score"] < 48:
                candidate["action"] = "보류"
            elif candidate["score"] < 62:
                candidate["action"] = "관찰"
        trade_horizon = _trade_horizon_profile(candidate, company_quality, kr_session)
        candidate["trade_horizon"] = trade_horizon
        candidate["trade_mode"] = trade_horizon.get("mode", "관망")
        candidate["strategy_mode"] = trade_horizon.get("strategy_mode", "research_only")
        if trade_horizon.get("mode") == "관망" and candidate["action"] != "보류":
            candidate["action"] = "관찰"
        horizon_bonus = 0
        if trade_horizon.get("mode") == "단타":
            horizon_bonus = 4
        elif trade_horizon.get("mode") == "스윙":
            horizon_bonus = 2
        if horizon_bonus:
            candidate["pre_dedup_raw_score"] = round(_number(candidate.get("pre_dedup_raw_score")) + horizon_bonus, 2)
            candidate["duplicate_bonus_removed"] = round(_number(candidate.get("duplicate_bonus_removed")) + horizon_bonus, 2)
            dedup_audit = candidate.get("score_dedup_audit") if isinstance(candidate.get("score_dedup_audit"), dict) else {}
            removed_sources = dedup_audit.get("removed_sources") if isinstance(dedup_audit.get("removed_sources"), list) else []
            if "derived_horizon_bonus" not in removed_sources:
                removed_sources.append("derived_horizon_bonus")
            dedup_audit["removed_sources"] = removed_sources
            candidate["score_dedup_audit"] = dedup_audit
        raw_score_before_learning = round(_number(candidate.get("raw_score")), 2)
        learning_bias = _learning_bias_for_candidate(candidate, learning_insight)
        candidate["learning_bias"] = learning_bias
        candidate["learning_bias_applied_to_score"] = bool(learning_bias.get("eligible_for_score"))
        if learning_bias.get("score_delta"):
            candidate["raw_score"] = round(_number(candidate.get("raw_score")) + float(learning_bias.get("score_delta", 0) or 0), 2)
            candidate["pre_dedup_raw_score"] = round(_number(candidate.get("pre_dedup_raw_score")) + float(learning_bias.get("score_delta", 0) or 0), 2)
            candidate["score"] = _desaturate_candidate_score(candidate["raw_score"])
            for reason in learning_bias.get("reasons", []) if isinstance(learning_bias.get("reasons"), list) else []:
                if reason not in candidate["reasons"]:
                    candidate["reasons"].append(reason)
        expected_raw_score_after_learning = round(
            raw_score_before_learning + _number(learning_bias.get("score_delta")),
            2,
        )
        candidate["raw_score_before_learning"] = raw_score_before_learning
        candidate["learning_score_reconciliation"] = {
            "policy_version": LEARNING_MEMORY_POLICY_VERSION,
            "evidence_fingerprint": learning_bias.get("evidence_fingerprint"),
            "raw_score_before_learning": raw_score_before_learning,
            "score_delta": round(_number(learning_bias.get("score_delta")), 2),
            "expected_raw_score_after_learning": expected_raw_score_after_learning,
            "raw_score_after_learning": round(_number(candidate.get("raw_score")), 2),
            "passed": abs(_number(candidate.get("raw_score")) - expected_raw_score_after_learning) <= 0.011,
        }
        learning_duplicate = _number(learning_bias.get("duplicate_bonus_removed"))
        if learning_duplicate > 0:
            candidate["pre_dedup_raw_score"] = round(_number(candidate.get("pre_dedup_raw_score")) + learning_duplicate, 2)
            candidate["duplicate_bonus_removed"] = round(_number(candidate.get("duplicate_bonus_removed")) + learning_duplicate, 2)
            dedup_audit = candidate.get("score_dedup_audit") if isinstance(candidate.get("score_dedup_audit"), dict) else {}
            removed_sources = dedup_audit.get("removed_sources") if isinstance(dedup_audit.get("removed_sources"), list) else []
            if "learning_financial_quality_repeat" not in removed_sources:
                removed_sources.append("learning_financial_quality_repeat")
            dedup_audit["removed_sources"] = removed_sources
            candidate["score_dedup_audit"] = dedup_audit
        dedup_audit = candidate.get("score_dedup_audit") if isinstance(candidate.get("score_dedup_audit"), dict) else {}
        dedup_audit.update({
            "pre_dedup_raw_score": candidate.get("pre_dedup_raw_score"),
            "post_dedup_raw_score": candidate.get("raw_score"),
            "removed_points_after_regime": candidate.get("duplicate_bonus_removed", 0),
        })
        candidate["score_dedup_audit"] = dedup_audit
        adjustment = candidate.get("score_adjustment") if isinstance(candidate.get("score_adjustment"), dict) else {}
        adjustment.update({
            "raw_score": candidate["raw_score"],
            "display_score": candidate["score"],
            "compressed": bool(_number(candidate.get("raw_score")) > _number(candidate.get("score"))),
            "compression_delta": round(_number(candidate.get("raw_score")) - _number(candidate.get("score")), 2),
        })
        if trade_horizon.get("mode") in {"단타", "스윙"}:
            adjustment["horizon_bonus_excluded_as_duplicate"] = horizon_bonus
        if learning_bias.get("score_delta"):
            adjustment["learning_delta"] = round(float(learning_bias.get("score_delta", 0) or 0), 2)
        adjustment["duplicate_bonus_removed"] = candidate.get("duplicate_bonus_removed", 0)
        candidate["score_adjustment"] = adjustment
        candidate["action"] = _candidate_action_from_final_score(candidate)
        candidate["score_contract"] = _candidate_score_contract(candidate)
        candidate["reasons"] = candidate["reasons"][:7]
        candidates.append(candidate)
    candidates.sort(key=_candidate_sort_key)
    for rank, candidate in enumerate(candidates, start=1):
        candidate["rank"] = rank
        candidate["ranking_vector"] = {
            "display_score": _candidate_ranking_vector(candidate)[0],
            "raw_score": _candidate_ranking_vector(candidate)[1],
            "quality_score": _candidate_ranking_vector(candidate)[2],
            "financial_score": _candidate_ranking_vector(candidate)[3],
            "profit_factor": _candidate_ranking_vector(candidate)[4],
            "mdd_pct": _candidate_ranking_vector(candidate)[5],
            "symbol_final_tiebreak": str(candidate.get("symbol") or "").upper(),
        }
    candidate_lanes = _candidate_lane_summary(candidates)
    sector_promotion_board = _candidate_sector_promotion_board(candidates, max_per_sector=2, limit=10)
    sector_concentration_audit = _candidate_sector_concentration_audit(candidates)
    sector_concentration_audit["promotion_board"] = sector_promotion_board
    saturation_audit = _candidate_score_saturation_audit(candidates)
    learning_bias_rows = [
        row.get("learning_bias")
        for row in candidates
        if isinstance(row.get("learning_bias"), dict)
    ]
    learning_freshness = learning_bias_rows[0] if learning_bias_rows else {}
    next_actions = []
    for item in candidates[:5]:
        next_actions.append(f"{item['symbol']} {item['action']}: {', '.join(item['reasons'][:2])}")
    payload = {
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "cached": False,
        "target_count": len(targets),
        "radar_cached": radar.get("cached", False),
        "top": candidates[0] if candidates else None,
        "candidates": candidates,
        "next_actions": next_actions,
        "candidate_lanes": candidate_lanes,
        "sector_promotion_board": sector_promotion_board,
        "sector_concentration_audit": sector_concentration_audit,
        "score_saturation_audit": saturation_audit,
        "market_regime": {
            "score": market_regime.get("score"),
            "stance": market_regime.get("stance"),
            "mode": market_regime.get("mode"),
            "headline": market_regime.get("headline"),
            "automation": market_regime.get("automation", {}),
        },
        "sector_news": {
            "generated_at": sector_report.get("generated_at"),
            "cached": sector_report.get("cached", False),
            "source": sector_report.get("source"),
            "tasks": sector_report.get("tasks", []),
        },
        "learning": {
            "score": learning_insight.get("learning_score"),
            "generated_at": learning_insight.get("generated_at"),
            "freshness_status": learning_freshness.get("freshness_status", "no_candidates"),
            "age_seconds": learning_freshness.get("age_seconds"),
            "freshness_factor": learning_freshness.get("freshness_factor", 0),
            "score_applied_candidate_count": sum(1 for row in candidates if row.get("learning_bias_applied_to_score")),
            "candidate_count": len(candidates),
            "cards": learning_insight.get("insight_cards", [])[:5] if isinstance(learning_insight.get("insight_cards"), list) else [],
        },
        "method": "재무 독립근거 + 백테스트 실행 1개당 최대 30점 + 뉴스/테마 가족 최대 14점 + 가격/거래량 가족 최대 9점 + 검증된 학습보정 + 기본체력 12점. 동일 원천 파생값은 감쇠하고 표시 점수는 88점 이상부터 98.7점 아래로 압축합니다.",
        "safety": "후보 발굴은 투자 판단 보조입니다. 실전 주문은 잠금입니다.",
    }
    if not symbols:
        _agent_cache_save(AGENT_SCREENER_CACHE_FILE, payload)
    return payload


def _opportunity_upside(row: dict[str, object]) -> dict[str, object]:
    score = _number(row.get("score"))
    financial_score = _number(row.get("financial_score"))
    sector_delta = _number(row.get("sector_news_score_delta"))
    momentum_delta = _number(row.get("market_signal_score_delta"))
    mdd = abs(_number(row.get("mdd_pct")))
    if score >= 84:
        base_low, base_high, label = 18, 38, "강한 후보"
    elif score >= 74:
        base_low, base_high, label = 12, 28, "우호 후보"
    elif score >= 62:
        base_low, base_high, label = 7, 18, "관심 후보"
    elif score >= 50:
        base_low, base_high, label = 3, 12, "관찰 후보"
    else:
        base_low, base_high, label = -8, 8, "검증 대기"
    if financial_score >= 80:
        base_low += 2
        base_high += 4
    if sector_delta >= 4:
        base_low += 2
        base_high += 5
    if momentum_delta < -3:
        base_low -= 3
        base_high -= 4
    if mdd >= 40:
        base_low -= 4
        base_high -= 6
    low = round(_clamp(base_low, -25, 45), 1)
    high = round(_clamp(max(base_high, low + 4), -15, 65), 1)
    confidence = "높음" if score >= 78 and financial_score >= 70 else "중간" if score >= 62 else "낮음"
    return {
        "label": label,
        "range_pct": [low, high],
        "text": f"{low:+.1f}%~{high:+.1f}% 가설",
        "confidence": confidence,
        "basis": "AI 점수, 섹터뉴스, 재무점수, 공개시세 모멘텀, 백테스트 낙폭을 조합한 연구용 범위입니다.",
    }


def _investor_style_fit(row: dict[str, object]) -> dict[str, object]:
    financial_score = _number(row.get("financial_score"))
    news_score = _number(row.get("news_score"))
    sector_delta = _number(row.get("sector_news_score_delta"))
    market_delta = _number(row.get("market_signal_score_delta"))
    return_pct = _number(row.get("return_pct"))
    mdd = abs(_number(row.get("mdd_pct")))
    score = _number(row.get("score"))
    styles: list[dict[str, object]] = []
    if financial_score >= 75 and mdd <= 35:
        styles.append({"name": "워런 버핏식 품질/재무", "fit": min(95, 55 + financial_score * 0.35 - mdd * 0.25), "why": "재무점수와 낙폭 안정성을 우선 봅니다."})
    if sector_delta > 0 or news_score > 0:
        styles.append({"name": "피터 린치식 성장 스토리", "fit": min(94, 58 + max(sector_delta, 0) * 4 + max(news_score, 0) * 2), "why": "이해 가능한 섹터 변화와 뉴스 촉매를 봅니다."})
    if market_delta > 0 or return_pct > 50:
        styles.append({"name": "윌리엄 오닐식 추세/상대강도", "fit": min(96, 55 + max(market_delta, 0) * 4 + _clamp(return_pct, 0, 160) * 0.12), "why": "상대강도, 추세, 가격 모멘텀을 중시합니다."})
    if score >= 70 and mdd <= 45:
        styles.append({"name": "마크 미너비니식 추세 후보", "fit": min(92, 50 + score * 0.35 - mdd * 0.18), "why": "강한 후보 점수와 리스크 관리 가능성을 같이 봅니다."})
    if not styles:
        styles.append({"name": "하워드 막스식 리스크 우선 관찰", "fit": 58, "why": "확실한 우위보다 리스크와 사이클 확인이 먼저입니다."})
    styles = sorted(styles, key=lambda item: float(item.get("fit", 0)), reverse=True)
    top = styles[0]
    return {
        "primary": top["name"],
        "fit_score": round(float(top.get("fit", 0)), 1),
        "why": top["why"],
        "alternatives": styles[1:3],
    }


