def _news_link_cards(items: object, limit: int = 3) -> list[dict[str, object]]:
    links = []
    for item in items if isinstance(items, list) else []:
        if not isinstance(item, dict):
            continue
        title = str(item.get("title", "")).strip()
        if not title:
            continue
        links.append(
            {
                "title": title[:140],
                "link": item.get("link", ""),
                "source": item.get("source", ""),
                "published": item.get("published", ""),
            }
        )
        if len(links) >= limit:
            break
    return links


def _enrich_cached_opportunity_links(payload: dict[str, object]) -> dict[str, object]:
    try:
        sector_report = build_sector_news_report(force=False)
    except Exception:
        return payload
    sector_map = {
        str(sector.get("id", "")): sector
        for sector in sector_report.get("sectors", [])
        if isinstance(sector, dict) and sector.get("id")
    }
    for sector in payload.get("sectors", []) if isinstance(payload.get("sectors"), list) else []:
        if not isinstance(sector, dict):
            continue
        sector_id = str(sector.get("id", ""))
        sector_links = sector.get("news_links") if isinstance(sector.get("news_links"), list) else []
        if not sector_links:
            sector_links = _news_link_cards((sector_map.get(sector_id, {}) or {}).get("items"), limit=3)
            sector["news_links"] = sector_links
        for card in sector.get("cards", []) if isinstance(sector.get("cards"), list) else []:
            if isinstance(card, dict) and not card.get("sector_news_links"):
                card["sector_news_links"] = sector_links
    payload["top_cards"] = [card for sector in payload.get("sectors", []) if isinstance(sector, dict) for card in sector.get("cards", [])[:2]][:12]
    return payload


def _start_opportunity_cards_refresh() -> bool:
    if not OPPORTUNITY_REFRESH_LOCK.acquire(blocking=False):
        return False

    def worker() -> None:
        try:
            build_opportunity_cards(force=True, allow_cached=False)
        except Exception as exc:
            JOURNAL.add("OPPORTUNITY_CARDS_REFRESH_ERROR", str(exc), {})
        finally:
            OPPORTUNITY_REFRESH_LOCK.release()

    threading.Thread(target=worker, name="opportunity-cards-refresh", daemon=True).start()
    return True


def build_opportunity_cards(force: bool = False, allow_cached: bool = True) -> dict[str, object]:
    if allow_cached:
        cached = _agent_cache_load(OPPORTUNITY_CARDS_CACHE_FILE, ttl_seconds=60 * 30)
        if cached and isinstance(cached.get("payload"), dict):
            payload = dict(cached["payload"])
            payload = _enrich_cached_opportunity_links(payload)
            payload["cached"] = True
            if force:
                payload["refreshing"] = _start_opportunity_cards_refresh()
                payload["refresh_message"] = "기존 카드를 즉시 보여주고, 백그라운드에서 새 추천 카드를 계산합니다."
            return payload
    sector_report = build_sector_news_report(force=force)
    sector_map = {
        str(sector.get("id", "")): sector
        for sector in sector_report.get("sectors", [])
        if isinstance(sector, dict) and sector.get("id")
    }
    symbols: list[str] = []
    for rule in SECTOR_THEME_RULES.values():
        for symbol in rule.get("symbols", set()):
            normalized = str(symbol).upper()
            if normalized and normalized not in symbols:
                symbols.append(normalized)
    watchlist = [str(item).upper() for item in load_user_watchlist().get("symbols", [])]
    for symbol in watchlist:
        if symbol and symbol not in symbols:
            symbols.append(symbol)
    screener = build_ai_screener(symbols=symbols, force=force)
    candidates = [
        item for item in screener.get("candidates", [])
        if isinstance(item, dict) and item.get("symbol")
    ]
    by_symbol = {str(item.get("symbol", "")).upper(): item for item in candidates}
    radar = build_agent_radar(symbols=symbols[:8], force=force)
    news_map = {
        str(row.get("symbol", "")).upper(): row
        for row in radar.get("news", [])
        if isinstance(row, dict) and row.get("symbol")
    }
    sectors = []
    for sector in DEFAULT_SECTOR_NEWS:
        sector_id = str(sector.get("id", ""))
        rule = SECTOR_THEME_RULES.get(sector_id, {})
        sector_news = sector_map.get(sector_id, {})
        sector_links = _news_link_cards(sector_news.get("items"), limit=3)
        sector_symbols = [str(item).upper() for item in sorted(rule.get("symbols", set()))]
        rows = []
        for symbol in sector_symbols:
            row = by_symbol.get(symbol)
            if not row:
                lookup = (_lookup_symbols([symbol]) or [{"symbol": symbol, "name": symbol, "market": "KR" if symbol.isdigit() else "US"}])[0]
                sector_signal = build_sector_news_signal(lookup, sector_map)
                row = {
                    "symbol": symbol,
                    "name": lookup.get("name", symbol),
                    "market": lookup.get("market", "-"),
                    "score": 0,
                    "action": "데이터 대기",
                    "reasons": ["유니버스에는 있으나 스크리너 데이터 누적 대기"],
                    "risk_flags": ["정밀 백테스트/재무 확인 필요"],
                    "financial_score": 0,
                    "financial_stance": "-",
                    "news_score": 0,
                    "news_stance": "-",
                    "sector_news_signal": sector_signal,
                    "sector_news_score_delta": sector_signal.get("score_delta", 0),
                    "market_signal_label": "-",
                    "market_signal_score_delta": 0,
                    "return_pct": 0,
                    "mdd_pct": 0,
                    "risk_gate_status": "WAIT",
                }
            quote = {}
            try:
                quote = live_quote(symbol)
            except Exception:
                quote = {"source": "unavailable", "price": 0}
            quality_row = dict(row)
            quality_row["price"] = quote.get("price", row.get("price", 0))
            quality_row["change_pct"] = quote.get("change_pct", row.get("change_pct", 0))
            company_quality = row.get("company_quality") if isinstance(row.get("company_quality"), dict) else _company_quality_profile(quality_row)
            upside = _opportunity_upside(row)
            style = _investor_style_fit(row)
            symbol_news = news_map.get(symbol, {})
            news_links = _news_link_cards(symbol_news.get("items"), limit=3)
            rows.append(
                {
                    "symbol": symbol,
                    "name": row.get("name", symbol),
                    "market": row.get("market", "-"),
                    "price": quote.get("price", 0),
                    "price_source": quote.get("source", "-"),
                    "change_pct": quote.get("change_pct", row.get("change_pct", 0)),
                    "score": row.get("score", 0),
                    "action": row.get("action", "-"),
                    "company_quality": company_quality,
                    "quality_score": company_quality.get("score", 0),
                    "quality_grade": company_quality.get("grade", "D"),
                    "quality_passed": bool(company_quality.get("is_quality_candidate")),
                    "trade_horizon": row.get("trade_horizon", {}),
                    "trade_mode": row.get("trade_mode", "-"),
                    "strategy_mode": row.get("strategy_mode", "-"),
                    "upside": upside,
                    "investor_style": style,
                    "why": list(row.get("reasons", []))[:5],
                    "risks": list(row.get("risk_flags", []))[:4],
                    "financial": {"score": row.get("financial_score", 0), "stance": row.get("financial_stance", "-")},
                    "news": {"score": row.get("news_score", 0), "stance": row.get("news_stance", "-")},
                    "news_links": news_links,
                    "sector_news_links": sector_links,
                    "sector_signal": row.get("sector_news_signal", {}),
                    "market_signal": {
                        "label": row.get("market_signal_label", "-"),
                        "delta": row.get("market_signal_score_delta", 0),
                    },
                    "backtest": {
                        "return_pct": row.get("return_pct", 0),
                        "mdd_pct": row.get("mdd_pct", 0),
                        "win_rate_pct": row.get("win_rate_pct", 0),
                        "profit_factor": row.get("profit_factor", 0),
                        "risk_gate": row.get("risk_gate_status", "-"),
                    },
                    "next_study": [
                        "최근 분기 실적과 마진 변화 확인",
                        "시장점유율·핵심 거래처·기술력 근거 확인",
                        "섹터 뉴스 원문과 공시 이벤트 확인",
                        "차트에서 지지/저항과 손절 기준 재검토",
                    ],
                }
            )
        rows = sorted(
            rows,
            key=lambda item: (
                1 if item.get("quality_passed") else 0,
                float(item.get("quality_score", 0) or 0),
                float(item.get("score", 0) or 0),
            ),
            reverse=True,
        )
        avg_score = round(sum(float(item.get("score", 0) or 0) for item in rows[:5]) / max(1, min(5, len(rows))), 2)
        sector_score = _number(sector_news.get("score"))
        sectors.append(
            {
                "id": sector_id,
                "name": sector.get("name", sector_id),
                "stance": sector_news.get("stance", "중립"),
                "sector_news_score": sector_score,
                "summary": sector_news.get("summary", sector.get("query", "")),
                "news_links": sector_links,
                "learning_notes": _sector_learning_notes(sector_id),
                "avg_candidate_score": avg_score,
                "top_symbols": [item.get("symbol") for item in rows[:5]],
                "cards": rows,
            }
        )
    sectors = sorted(
        sectors,
        key=lambda item: (float(item.get("sector_news_score", 0) or 0), float(item.get("avg_candidate_score", 0) or 0)),
        reverse=True,
    )
    payload = {
        "ok": True,
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "cached": bool(screener.get("cached")) or bool(sector_report.get("cached")),
        "sectors": sectors,
        "top_cards": [card for sector in sectors for card in sector.get("cards", [])[:2]][:12],
        "method": "섹터뉴스 + AI 후보점수 + 재무/뉴스/DART + 공개시세 + 백테스트 위험게이트를 카드형으로 재구성",
        "safety": "상승여력은 확정 전망이 아니라 연구용 가설 범위입니다. 매수/매도 지시가 아니며 실전 주문은 BLOCKED입니다.",
    }
    _agent_cache_save(OPPORTUNITY_CARDS_CACHE_FILE, payload)
    return payload


