def scheduled_report_runs(limit: int = 30) -> list[dict[str, object]]:
    return list(reversed(_read_jsonl(SCHEDULED_REPORT_FILE, limit=limit)))


def _parse_report_time(value: object) -> dt_time | None:
    try:
        hour, minute = str(value or "").split(":", 1)
        return dt_time(max(0, min(23, int(hour))), max(0, min(59, int(minute))))
    except Exception:
        return None


def _scheduled_report_due(now: datetime, slot: dict[str, object]) -> bool:
    if bool(slot.get("weekdays_only", True)) and now.weekday() >= 5:
        return False
    target_time = _parse_report_time(slot.get("time"))
    if not target_time:
        return False
    target = now.replace(hour=target_time.hour, minute=target_time.minute, second=0, microsecond=0)
    grace_minutes = max(5, min(180, int(slot.get("grace_minutes", 45) or 45)))
    return target <= now <= target + timedelta(minutes=grace_minutes)


def _scheduled_report_recorded(report_date: str, slot_id: str) -> bool:
    for row in _read_jsonl(SCHEDULED_REPORT_FILE, limit=300):
        if str(row.get("report_date")) == report_date and str(row.get("slot_id")) == slot_id and row.get("queued"):
            return True
    return False


def _next_scheduled_report_slot(now: datetime, slot_id: str, slot: dict[str, object]) -> dict[str, object]:
    target_time = _parse_report_time(slot.get("time"))
    if not target_time:
        return {
            "id": slot_id,
            "label": slot.get("label", slot_id),
            "time": slot.get("time", "-"),
            "enabled": False,
            "status": "시간 오류",
            "next_at": "",
            "minutes_to_next": None,
        }
    weekdays_only = bool(slot.get("weekdays_only", True))
    grace_minutes = max(5, min(180, int(slot.get("grace_minutes", 45) or 45)))
    for offset in range(0, 10):
        day = (now + timedelta(days=offset)).date()
        if weekdays_only and day.weekday() >= 5:
            continue
        target = datetime.combine(day, target_time, tzinfo=now.tzinfo)
        if target <= now <= target + timedelta(minutes=grace_minutes):
            if _scheduled_report_recorded(day.isoformat(), slot_id):
                continue
            return {
                "id": slot_id,
                "label": slot.get("label", slot_id),
                "time": slot.get("time", "-"),
                "enabled": True,
                "status": "보고 가능 시간",
                "next_at": target.isoformat(timespec="seconds"),
                "minutes_to_next": 0,
                "grace_minutes": grace_minutes,
            }
        if target > now:
            minutes = int(math.ceil((target - now).total_seconds() / 60))
            return {
                "id": slot_id,
                "label": slot.get("label", slot_id),
                "time": slot.get("time", "-"),
                "enabled": True,
                "status": "대기",
                "next_at": target.isoformat(timespec="seconds"),
                "minutes_to_next": max(0, minutes),
                "grace_minutes": grace_minutes,
            }
    return {
        "id": slot_id,
        "label": slot.get("label", slot_id),
        "time": slot.get("time", "-"),
        "enabled": True,
        "status": "계산 대기",
        "next_at": "",
        "minutes_to_next": None,
        "grace_minutes": grace_minutes,
    }


