def build_telegram_report_schedule(policy: dict[str, object] | None = None) -> dict[str, object]:
    policy = policy or OPS.telegram_policy()
    windows = policy.get("scheduled_report_windows", {}) if isinstance(policy.get("scheduled_report_windows"), dict) else {}
    now = datetime.now(_zone("Asia/Seoul", 9))
    slots: list[dict[str, object]] = []
    for slot_id, slot in windows.items():
        if not isinstance(slot, dict):
            continue
        if not bool(slot.get("enabled", True)):
            slots.append(
                {
                    "id": str(slot_id),
                    "label": slot.get("label", slot_id),
                    "time": slot.get("time", "-"),
                    "enabled": False,
                    "status": "꺼짐",
                    "next_at": "",
                    "minutes_to_next": None,
                }
            )
            continue
        slots.append(_next_scheduled_report_slot(now, str(slot_id), slot))
    enabled_slots = [
        slot for slot in slots
        if slot.get("enabled") and slot.get("minutes_to_next") is not None
    ]
    enabled_slots.sort(key=lambda slot: int(slot.get("minutes_to_next", 999999) or 999999))
    daemon_auto_report = bool(policy.get("daemon_auto_report_enabled", False))
    scheduled_enabled = bool(policy.get("scheduled_reports_enabled", True))
    next_slot = enabled_slots[0] if scheduled_enabled and enabled_slots else {}
    try:
        pending_rows = OPS.pending_telegram_outbox(limit=100)
    except Exception:
        pending_rows = []
    try:
        dispatch_rows = OPS.telegram_dispatches(limit=20)
    except Exception:
        dispatch_rows = []
    try:
        policy_stats = OPS.telegram_policy_stats(limit=200)
    except Exception:
        policy_stats = {}
    pending_by_type: dict[str, int] = {}
    recent_pending_count = 0
    for row in pending_rows:
        if not isinstance(row, dict):
            continue
        message_type = str(row.get("message_type", "manual"))
        pending_by_type[message_type] = pending_by_type.get(message_type, 0) + 1
        age_seconds = _iso_age_seconds(row.get("created_at"))
        if age_seconds is not None and age_seconds <= 30 * 60:
            recent_pending_count += 1
    dispatcher_state = TELEGRAM_DISPATCHER.status()
    telegram_status = INTEGRATIONS.status().get("telegram", {})
    last_dispatch = dispatch_rows[-1] if dispatch_rows and isinstance(dispatch_rows[-1], dict) else {}
    dispatch_state = {
        "pending_total": len(pending_rows),
        "pending_recent": recent_pending_count,
        "pending_by_type": pending_by_type,
        "auto_dispatch": bool(policy.get("auto_dispatch", False)),
        "dispatcher_running": bool(dispatcher_state.get("running")) and bool(dispatcher_state.get("thread_alive")),
        "telegram_ready": bool(telegram_status.get("enabled")) and bool(telegram_status.get("configured")),
        "last_dispatch_status": last_dispatch.get("status", "-"),
        "last_dispatch_at": last_dispatch.get("created_at", ""),
        "policy_skips_recent": policy_stats.get("recent_skips", 0),
        "dedupe_enabled": bool(policy.get("dedupe_enabled", True)),
        "rate_limit_enabled": bool(policy.get("rate_limit_enabled", True)),
        "message": (
            "최근 보고만 천천히 발송합니다."
            if bool(policy.get("auto_dispatch", False))
            else "자동발송은 꺼져 있고, 큐에 쌓인 보고는 수동/스케줄러가 처리합니다."
        ),
    }
    today_report_date = now.date().isoformat()
    recent_runs = scheduled_report_runs(limit=50)
    today_runs: list[dict[str, object]] = []
    today_run_by_slot: dict[str, dict[str, object]] = {}
    for row in recent_runs:
        if not isinstance(row, dict) or str(row.get("report_date", "")) != today_report_date:
            continue
        run_row = {
            "slot_id": row.get("slot_id", ""),
            "label": row.get("label") or row.get("slot_id", "-"),
            "created_at": row.get("created_at", ""),
            "queued": bool(row.get("queued")),
            "telegram_status": row.get("telegram_status", "-"),
            "reason": row.get("reason", ""),
        }
        today_runs.append(run_row)
        today_run_by_slot[str(row.get("slot_id", ""))] = run_row
    last_run = today_runs[0] if today_runs else {}
    today_slots: list[dict[str, object]] = []
    for slot_id, slot in windows.items():
        if not isinstance(slot, dict):
            continue
        label = slot.get("label", slot_id)
        if not bool(slot.get("enabled", True)):
            today_slots.append({"id": str(slot_id), "label": label, "time": slot.get("time", "-"), "status": "꺼짐", "queued": False})
            continue
        target_time = _parse_report_time(slot.get("time"))
        if not target_time:
            today_slots.append({"id": str(slot_id), "label": label, "time": slot.get("time", "-"), "status": "시간 오류", "queued": False})
            continue
        if bool(slot.get("weekdays_only", True)) and now.weekday() >= 5:
            today_slots.append({"id": str(slot_id), "label": label, "time": slot.get("time", "-"), "status": "주말 제외", "queued": False})
            continue
        target = now.replace(hour=target_time.hour, minute=target_time.minute, second=0, microsecond=0)
        grace_minutes = max(5, min(180, int(slot.get("grace_minutes", 45) or 45)))
        run = today_run_by_slot.get(str(slot_id), {})
        if run:
            status = "완료" if run.get("queued") else "스킵"
            minutes_to_target = 0
        elif now < target:
            status = "예정"
            minutes_to_target = int(math.ceil((target - now).total_seconds() / 60))
        elif target <= now <= target + timedelta(minutes=grace_minutes):
            status = "보고 가능"
            minutes_to_target = 0
        else:
            status = "지나감"
            minutes_to_target = 0
        today_slots.append(
            {
                "id": str(slot_id),
                "label": label,
                "time": slot.get("time", "-"),
                "status": status,
                "queued": bool(run.get("queued")),
                "created_at": run.get("created_at", ""),
                "next_at": target.isoformat(timespec="seconds"),
                "minutes_to_target": minutes_to_target,
            }
        )
    today_slot_summary = {
        "total": len(today_slots),
        "done": len([slot for slot in today_slots if slot.get("status") == "완료"]),
        "pending": len([slot for slot in today_slots if slot.get("status") in {"예정", "보고 가능"}]),
        "missed": len([slot for slot in today_slots if slot.get("status") == "지나감"]),
    }
    next_slot_id = str(next_slot.get("id", "")) if isinstance(next_slot, dict) else ""
    next_preview = _scheduled_report_preview(next_slot_id) if next_slot_id else {}
    payload = {
        "ok": True,
        "generated_at": now.isoformat(timespec="seconds"),
        "enabled": scheduled_enabled,
        "mode": "시간표 보고" if scheduled_enabled else "자동보고 OFF",
        "quiet_learning": not daemon_auto_report,
        "daemon_auto_report": daemon_auto_report,
        "trade_reason_reports_enabled": bool(policy.get("trade_reason_reports_enabled", True)),
        "next_slot": next_slot,
        "slots": slots,
        "dispatch_state": dispatch_state,
        "today_run_count": len(today_runs),
        "today_runs": today_runs[:8],
        "last_run": last_run,
        "today_slots": today_slots,
        "today_slot_summary": today_slot_summary,
        "next_preview": next_preview,
        "allowed_reports": [
            "장전 준비 보고",
            "장중 중간 점검",
            "장마감 보고",
            "장 복기 후 보고",
            "저녁 9시 연구 요약",
            "실전 매매 사유 보고",
            "사용자 명령 답변",
        ],
        "silent_items": [
            "연구 데몬 반복 학습",
            "모의훈련/백테스트 세부 로그",
            "AI 직원 내부 회의",
            "건강점검/리허설 변화",
        ],
        "detail": "자동 보고는 시간표와 매매 사유 중심으로 제한하고, 나머지 연구는 장기기억에 조용히 저장합니다.",
    }


def _brief_candidate_lines(candidates: list[dict[str, object]], limit: int = 3) -> list[str]:
    lines = []
    for item in candidates[:limit]:
        if not isinstance(item, dict):
            continue
        lines.append(
            f"- {item.get('name') or item.get('symbol', '-')}({item.get('symbol', '-')}) "
            f"점수 {item.get('score', '-')} / 게이트 {item.get('risk_gate_status', '-')}"
        )
    return lines or ["- 후보 데이터 대기"]


def _brief_plain_title(value: object, limit: int = 72) -> str:
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    text = re.sub(r"\(([A-Z0-9.]{1,12}|\d{6})\)", "", text).strip()
    return text[:limit].rstrip()


def _pre_market_news_lines(sector_report: dict[str, object], limit: int = 5) -> list[str]:
    rows = []
    sectors = [item for item in sector_report.get("sectors", []) if isinstance(item, dict)]
    sectors.sort(key=lambda item: abs(float(item.get("score", 0) or 0)), reverse=True)
    for sector in sectors:
        items = [item for item in sector.get("items", []) if isinstance(item, dict)]
        title = _brief_plain_title(items[0].get("title") if items else sector.get("summary"), limit=70)
        score = float(sector.get("score", 0) or 0)
        rows.append(
            f"- {sector.get('name', '-')} / {sector.get('stance', '-')} "
            f"({score:+g}) : {title or '뉴스 제목 대기'}"
        )
        if len(rows) >= limit:
            break
    return rows or ["- 뉴스 수집 대기: 섹터 뉴스 레이더가 다음 사이클에서 다시 확인합니다."]


def _pre_market_overnight_lines(overnight_report: dict[str, object], limit: int = 5) -> list[str]:
    rows = []
    issues = [item for item in overnight_report.get("issues", []) if isinstance(item, dict)]
    issues.sort(key=lambda item: abs(float(item.get("score", 0) or 0)), reverse=True)
    for issue in issues[:limit]:
        items = [item for item in issue.get("items", []) if isinstance(item, dict)]
        title = _brief_plain_title(items[0].get("title") if items else issue.get("summary"), limit=76)
        source = str(items[0].get("source", "")).strip() if items else ""
        source_text = f" / {source}" if source else ""
        rows.append(
            f"- {issue.get('name', '-')} / {issue.get('stance', '-')} "
            f"({float(issue.get('score', 0) or 0):+g}) : {title or '이슈 제목 대기'}{source_text}"
        )
    return rows or ["- 지난밤 이슈 수집 대기: 장전 브리핑이 다음 사이클에서 다시 확인합니다."]


def _pre_market_sector_lines(sector_report: dict[str, object], limit: int = 3) -> list[str]:
    sectors = [item for item in sector_report.get("sectors", []) if isinstance(item, dict)]
    sectors.sort(key=lambda item: float(item.get("score", 0) or 0), reverse=True)
    lines = []
    for sector in sectors[:limit]:
        lines.append(
            f"- {sector.get('name', '-')} : {sector.get('stance', '-')} "
            f"/ 긍정 {sector.get('positive_count', 0)}·위험 {sector.get('risk_count', 0)}"
        )
    return lines or ["- 섹터 강도 데이터 대기"]


def _pre_market_candidate_lines(candidates: list[dict[str, object]], limit: int = 5) -> list[str]:
    lines = []
    for item in candidates[:limit]:
        if not isinstance(item, dict):
            continue
        name = item.get("name") or item.get("symbol", "-")
        reasons = item.get("reasons") if isinstance(item.get("reasons"), list) else []
        risks = item.get("risk_flags") if isinstance(item.get("risk_flags"), list) else []
        reason = ", ".join(str(row) for row in reasons[:2]) or "점수 상위"
        risk = f" / 주의 {', '.join(str(row) for row in risks[:1])}" if risks else ""
        lines.append(
            f"- {name}: 점수 {float(item.get('score', 0) or 0):.1f} "
            f"/ {item.get('action', '관찰')} / {reason}{risk}"
        )
    return lines or ["- 후보 데이터 대기"]


def _market_news_context_rows(report: dict[str, object], limit: int = 8) -> list[dict[str, object]]:
    """Group similar headlines by outlet while keeping every claim unverified."""
    candidates: list[dict[str, object]] = []
    for issue in report.get("issues", []) if isinstance(report.get("issues"), list) else []:
        if not isinstance(issue, dict):
            continue
        for item in issue.get("items", []) if isinstance(issue.get("items"), list) else []:
            if not isinstance(item, dict):
                continue
            title = " ".join(str(item.get("title") or "").split())
            if not title:
                continue
            claim_title = re.sub(r"\s+-\s+[^-]{1,50}$", "", title).strip()
            terms = set(re.findall(r"[0-9A-Za-z가-힣]{2,}", claim_title.lower()))
            if not terms:
                continue
            candidates.append(
                {
                    "headline": title,
                    "name": title,
                    "theme": issue.get("name", "시장 속보"),
                    "observed_at": item.get("published", ""),
                    "source": item.get("source", report.get("source", "Google News RSS")),
                    "source_url": item.get("link", ""),
                    "publisher_url": item.get("source_home_url", ""),
                    "source_record": {
                        "source": item.get("source", report.get("source", "Google News RSS")),
                        "source_url": item.get("link", ""),
                        "publisher_url": item.get("source_home_url", ""),
                        "headline": title,
                        "observed_at": item.get("published", ""),
                    },
                    "_terms": terms,
                    "_claim_key": re.sub(r"[^0-9a-z가-힣]+", "", claim_title.lower())[:240],
                }
            )

    clusters: list[dict[str, object]] = []
    for candidate in candidates:
        terms = candidate["_terms"]
        claim_key = candidate["_claim_key"]
        matched: dict[str, object] | None = None
        for cluster in clusters:
            cluster_terms = cluster["_terms"]
            overlap = len(terms & cluster_terms)
            similar = bool(claim_key == cluster["_claim_key"] or (overlap >= 3 and overlap / min(len(terms), len(cluster_terms)) >= 0.6))
            if similar:
                matched = cluster
                break
        if matched is None:
            matched = {
                **candidate,
                "_sources": set(),
                "_links": set(),
                "_publisher_urls": set(),
                "_source_records": [],
            }
            clusters.append(matched)
        source = str(candidate.get("source") or "출처 미상")
        matched["_sources"].add(source)
        if candidate.get("source_url"):
            matched["_links"].add(str(candidate["source_url"]))
        if candidate.get("publisher_url"):
            matched["_publisher_urls"].add(str(candidate["publisher_url"]))
        source_record = candidate.get("source_record")
        if isinstance(source_record, dict):
            record_key = (
                str(source_record.get("source_url") or ""),
                str(source_record.get("publisher_url") or ""),
                str(source_record.get("source") or ""),
            )
            existing_keys = {
                (
                    str(record.get("source_url") or ""),
                    str(record.get("publisher_url") or ""),
                    str(record.get("source") or ""),
                )
                for record in matched["_source_records"]
                if isinstance(record, dict)
            }
            if record_key not in existing_keys:
                matched["_source_records"].append(dict(source_record))

    rows: list[dict[str, object]] = []
    for cluster in clusters:
        sources = sorted(cluster.pop("_sources"))
        links = sorted(cluster.pop("_links"))
        publisher_urls = sorted(cluster.pop("_publisher_urls"))
        source_records = sorted(
            [record for record in cluster.pop("_source_records") if isinstance(record, dict)],
            key=lambda record: (
                str(record.get("observed_at") or ""),
                str(record.get("source") or ""),
                str(record.get("source_url") or ""),
            ),
        )
        cluster.pop("source_record", None)
        cluster.pop("_terms", None)
        cluster.pop("_claim_key", None)
        corroborated = len(sources) >= 2
        rows.append(
            {
                **cluster,
                "source_url": links[0] if links else cluster.get("source_url", ""),
                "source_urls": links,
                "publisher_urls": publisher_urls,
                "source_records": source_records,
                "corroborating_sources": sources,
                "corroborating_source_count": len(sources),
                "corroborated": corroborated,
                "verification_state": "MULTI_SOURCE_CORROBORATED" if corroborated else "SINGLE_SOURCE_PENDING",
                "basis": "공개 기사 제목·게시시각 및 언론사 중복 출현",
                "evidence_origin": "internal_news_rss",
                # Repetition across outlets is corroboration, not proof of the underlying claim.
                "verified": False,
            }
        )
    rows.sort(key=lambda row: (bool(row.get("corroborated")), int(row.get("corroborating_source_count", 0))), reverse=True)
    return rows[: max(1, int(limit or 8))]


