def _news_url_host(value: object) -> str:
    try:
        return (urlparse(str(value or "")).hostname or "").lower().removeprefix("www.")
    except ValueError:
        return ""


NEWS_MULTIPART_PUBLIC_SUFFIXES = {
    "ac.kr", "co.kr", "go.kr", "ne.kr", "or.kr", "pe.kr", "re.kr",
    "com.au", "com.br", "com.cn", "com.hk", "com.sg", "com.tw",
    "co.jp", "co.nz", "co.uk", "org.uk",
}


def _news_independent_domain(value: object) -> str:
    """Collapse mobile/www subdomains so one publisher cannot count as two sources."""
    host = _news_url_host(value)
    if not host:
        return ""
    if host == "localhost" or re.fullmatch(r"\d{1,3}(?:\.\d{1,3}){3}", host):
        return host
    labels = [label for label in host.split(".") if label]
    if len(labels) <= 2:
        return host
    suffix2 = ".".join(labels[-2:])
    return ".".join(labels[-3:]) if suffix2 in NEWS_MULTIPART_PUBLIC_SUFFIXES else suffix2


def _is_news_aggregator_url(value: object) -> bool:
    host = _news_url_host(value)
    return not host or any(host == suffix or host.endswith(f".{suffix}") for suffix in NEWS_AGGREGATOR_HOST_SUFFIXES)


def _external_market_context_news_rows(limit: int = 8) -> tuple[list[dict[str, object]], dict[str, object]]:
    """Accept only fresh, integrity-checked external news URLs as VERIFY_ONLY evidence."""
    status: dict[str, object] = {
        "schema": "codexstock_external_market_context_news_bridge_v1",
        "enabled": True,
        "source_usable": False,
        "report_signature": "",
        "report_generated_at": "",
        "context_count": 0,
        "accepted_row_count": 0,
        "accepted_original_url_count": 0,
        "independent_domain_count": 0,
        "body_verified_count": 0,
        "stale_source_item_count": 0,
        "blockers": [],
        "score_allowed": False,
        "live_order_allowed": False,
    }
    try:
        inbox = external_signal_inbox_status(include_report=True)
    except Exception as exc:
        status["blockers"] = [f"external_signal_inbox_error:{type(exc).__name__}"]
        return [], status
    status["source_usable"] = bool(inbox.get("current_source_usable"))
    status["report_signature"] = str(inbox.get("report_signature") or "")
    report = inbox.get("report") if isinstance(inbox.get("report"), dict) else {}
    status["report_generated_at"] = str(report.get("generated_at") or "")
    if not status["source_usable"]:
        status["blockers"] = ["external_signal_source_not_current_or_integrity_verified"]
        return [], status
    contexts = report.get("market_context") if isinstance(report.get("market_context"), list) else []
    status["context_count"] = len(contexts)
    now = datetime.now(_zone("Asia/Seoul", 9))
    rows: list[dict[str, object]] = []
    all_domains: set[str] = set()
    accepted_url_count = 0
    body_verified_count = 0
    stale_item_count = 0
    for context in contexts:
        if not isinstance(context, dict):
            continue
        source_records: list[dict[str, object]] = []
        seen_domains: set[str] = set()
        for source in context.get("sources", []) if isinstance(context.get("sources"), list) else []:
            if not isinstance(source, dict) or str(source.get("type") or "").lower() != "naver_news":
                continue
            original_evidence = (
                source.get("original_evidence")
                if isinstance(source.get("original_evidence"), dict)
                else {}
            )
            original_url = str(original_evidence.get("canonical_url") or source.get("url") or "").strip()
            domain = _news_independent_domain(original_url)
            if not original_url.startswith(("http://", "https://")) or not domain or _is_news_aggregator_url(original_url):
                continue
            published_at = str(source.get("published_at") or context.get("detected_at") or "")
            published_dt, _ = _parse_market_context_observed_at(published_at, default_tz=now.tzinfo)
            age_seconds = (now - published_dt).total_seconds() if published_dt else None
            if age_seconds is None or age_seconds < -300 or age_seconds > 72 * 60 * 60:
                stale_item_count += 1
                continue
            if domain in seen_domains:
                continue
            seen_domains.add(domain)
            body_verified = bool(
                original_evidence.get("body_included")
                and str(original_evidence.get("body_hash") or "").startswith("sha256:")
                and int(_number(original_evidence.get("body_char_count"))) > 0
            )
            if body_verified:
                body_verified_count += 1
            source_records.append(
                {
                    "source": str(source.get("name") or domain),
                    "source_url": original_url,
                    "publisher_url": f"https://{domain}",
                    "headline": str(source.get("title") or context.get("headline") or ""),
                    "observed_at": published_at,
                    "external_original_fetch_status": str(original_evidence.get("fetch_status") or "UNKNOWN"),
                    "external_original_body_verified": body_verified,
                }
            )
            if len(source_records) >= 8:
                break
        if not source_records:
            continue
        domains = sorted({_news_independent_domain(row.get("source_url")) for row in source_records})
        source_urls = [str(row.get("source_url") or "") for row in source_records]
        publisher_urls = [str(row.get("publisher_url") or "") for row in source_records]
        observed_at = str(context.get("detected_at") or source_records[0].get("observed_at") or "")
        all_domains.update(domains)
        accepted_url_count += len(source_urls)
        rows.append(
            {
                "headline": str(context.get("headline") or source_records[0].get("headline") or "외부 시장 이슈"),
                "name": str(context.get("headline") or source_records[0].get("headline") or "외부 시장 이슈"),
                "theme": str(context.get("category") or "외부 시장 이슈"),
                "observed_at": observed_at,
                "source": "External Info Scout",
                "source_url": source_urls[0],
                "source_urls": source_urls,
                "publisher_urls": publisher_urls,
                "source_records": source_records,
                "corroborating_sources": sorted({str(row.get("source") or "") for row in source_records}),
                "corroborating_source_count": len(domains),
                "corroborated": len(domains) >= 2,
                "verification_state": "EXTERNAL_MULTI_SOURCE_PENDING_CODEXSTOCK_RESOLUTION",
                "basis": "무결성·신선도 통과 외부 보고서의 독립 언론사 원문 URL",
                "evidence_origin": "external_signal_market_context",
                "external_context_id": str(context.get("context_id") or ""),
                "external_report_signature": status["report_signature"],
                "external_engine_decision": "VERIFY_ONLY",
                "verified": False,
                "score_allowed": False,
                "live_order_allowed": False,
            }
        )
        if len(rows) >= max(1, min(int(_number(limit) or 8), 20)):
            break
    status.update(
        {
            "accepted_row_count": len(rows),
            "accepted_original_url_count": accepted_url_count,
            "independent_domain_count": len(all_domains),
            "body_verified_count": body_verified_count,
            "stale_source_item_count": stale_item_count,
            "blockers": [] if rows else ["no_fresh_independent_news_original_urls"],
        }
    )
    return rows, status


def _news_claim_terms(value: object) -> set[str]:
    claim = re.sub(r"\s+-\s+[^-]{1,50}$", "", str(value or "")).lower()
    stop_terms = {
        "증시", "시장", "오늘", "관련", "대한", "통해", "위해", "가운데", "전망", "분석",
        "코스피", "코스닥", "주식", "기자", "단독", "종합", "마켓", "프리뷰",
    }
    return {
        term
        for term in re.findall(r"[0-9a-z가-힣]{2,}", claim)
        if term not in stop_terms and len(term) >= 2
    }


def _resolve_original_via_bing_news(
    publisher_url: str,
    headline: object,
    *,
    timeout: float,
) -> tuple[str, str]:
    """Use Bing only as a locator; the returned article must match title and publisher domain."""
    publisher_domain = _news_independent_domain(publisher_url)
    headline_text = re.sub(r"\s+-\s+[^-]{1,50}$", "", " ".join(str(headline or "").split())).strip()
    headline_terms = _news_claim_terms(headline_text)
    if not publisher_domain or len(headline_terms) < 2:
        return "", ""
    query = quote_plus(f'"{headline_text[:180]}" site:{publisher_domain}')
    search_url = f"https://www.bing.com/news/search?q={query}&format=rss&setlang=ko-kr"
    try:
        request = Request(
            search_url,
            headers={
                "User-Agent": "Mozilla/5.0 (compatible; CodexStockNewsEvidence/1.0)",
                "Accept": "application/rss+xml,application/xml,text/xml",
            },
        )
        with urlopen(request, timeout=max(1.0, float(timeout))) as response:
            root = ET.fromstring(response.read(512 * 1024))
    except Exception as exc:
        return "", str(exc)[:240]
    for item in root.findall("./channel/item")[:8]:
        result_title = html.unescape(item.findtext("title") or "").strip()
        result_terms = _news_claim_terms(result_title)
        overlap = len(headline_terms & result_terms)
        coverage = overlap / max(1, len(headline_terms))
        if overlap < 2 or coverage < 0.5:
            continue
        result_link = html.unescape(item.findtext("link") or "").strip()
        parsed_link = urlparse(result_link)
        embedded_urls = parse_qs(parsed_link.query).get("url", [])
        candidate = str(embedded_urls[0] if embedded_urls else result_link).strip()
        if not candidate.startswith(("http://", "https://")):
            continue
        if _news_independent_domain(candidate) != publisher_domain:
            continue
        return candidate, ""
    return "", ""


def _resolve_publisher_home_article(
    publisher_url: str,
    headline: object,
    *,
    timeout: float,
) -> tuple[str, str]:
    if not publisher_url.startswith(("http://", "https://")):
        return "", ""
    publisher_host = _news_url_host(publisher_url)
    headline_terms = _news_claim_terms(headline)
    if not publisher_host or len(headline_terms) < 2:
        return "", ""
    try:
        request = Request(
            publisher_url,
            headers={
                "User-Agent": "Mozilla/5.0 (compatible; CodexStockNewsEvidence/1.0)",
                "Accept": "text/html,application/xhtml+xml",
            },
        )
        with urlopen(request, timeout=max(1.0, float(timeout))) as response:
            page_url = str(response.geturl() or publisher_url)
            body = response.read(768 * 1024).decode("utf-8", errors="ignore")
    except Exception as exc:
        return "", str(exc)[:240]
    best_url = ""
    best_score = 0.0
    for raw_href, raw_anchor in re.findall(
        r'<a\b[^>]*href=["\']([^"\']+)["\'][^>]*>(.*?)</a>',
        body,
        flags=re.IGNORECASE | re.DOTALL,
    ):
        anchor_text = html.unescape(re.sub(r"<[^>]+>", " ", raw_anchor))
        anchor_terms = _news_claim_terms(anchor_text)
        overlap = len(headline_terms & anchor_terms)
        if overlap < 2:
            continue
        candidate = html.unescape(urljoin(page_url, raw_href.strip()))
        candidate_host = _news_url_host(candidate)
        same_publisher = bool(
            candidate_host == publisher_host
            or candidate_host.endswith(f".{publisher_host}")
            or publisher_host.endswith(f".{candidate_host}")
        )
        if not same_publisher or _is_news_aggregator_url(candidate):
            continue
        coverage = overlap / max(1, len(headline_terms))
        precision = overlap / max(1, len(anchor_terms))
        score = 0.7 * coverage + 0.3 * precision
        if overlap >= 3 and coverage >= 0.4 and score > best_score:
            best_url = candidate
            best_score = score
    return best_url, ""


def _resolve_news_original_url(
    link: object,
    publisher_url: object = "",
    headline: object = "",
    *,
    timeout: float = 4.0,
) -> dict[str, object]:
    raw_link = str(link or "").strip()
    publisher = str(publisher_url or "").strip()
    if raw_link and not _is_news_aggregator_url(raw_link):
        return {
            "status": "DIRECT_ORIGINAL_URL",
            "aggregator_url": "",
            "original_url": raw_link,
            "publisher_url": publisher,
            "original_host": _news_url_host(raw_link),
            "error": "",
        }
    if not raw_link:
        return {
            "status": "PUBLISHER_ATTRIBUTED" if publisher else "NO_SOURCE_URL",
            "aggregator_url": "",
            "original_url": "",
            "publisher_url": publisher,
            "original_host": "",
            "error": "",
        }
    body = ""
    final_url = raw_link
    error = ""
    try:
        request = Request(
            raw_link,
            headers={
                "User-Agent": "Mozilla/5.0 (compatible; CodexStockNewsEvidence/1.0)",
                "Accept": "text/html,application/xhtml+xml",
            },
        )
        with urlopen(request, timeout=max(1.0, float(timeout))) as response:
            final_url = str(response.geturl() or raw_link)
            body = response.read(256 * 1024).decode("utf-8", errors="ignore")
    except Exception as exc:
        error = str(exc)[:240]
    candidates = [final_url]
    if body:
        patterns = (
            r'<link[^>]+rel=["\']canonical["\'][^>]+href=["\']([^"\']+)',
            r'<meta[^>]+(?:property|name)=["\']og:url["\'][^>]+content=["\']([^"\']+)',
            r'data-n-au=["\']([^"\']+)',
            r'[?&]url=(https?%3A%2F%2F[^&"\']+)',
        )
        for pattern in patterns:
            candidates.extend(re.findall(pattern, body, flags=re.IGNORECASE))
    for candidate in candidates:
        decoded = html.unescape(unquote(str(candidate or "").strip()))
        if decoded.startswith(("http://", "https://")) and not _is_news_aggregator_url(decoded):
            return {
                "status": "RESOLVED_ORIGINAL_URL",
                "aggregator_url": raw_link,
                "original_url": decoded,
                "publisher_url": publisher,
                "original_host": _news_url_host(decoded),
                "error": "",
            }
    bing_original_url, bing_error = _resolve_original_via_bing_news(
        publisher,
        headline,
        timeout=timeout,
    )
    if bing_original_url:
        return {
            "status": "BING_NEWS_EXACT_TITLE_ORIGINAL_URL",
            "aggregator_url": raw_link,
            "original_url": bing_original_url,
            "publisher_url": publisher,
            "original_host": _news_url_host(bing_original_url),
            "error": "",
        }
    home_original_url, home_error = _resolve_publisher_home_article(
        publisher,
        headline,
        timeout=timeout,
    )
    if home_original_url:
        return {
            "status": "PUBLISHER_HOME_MATCHED_ORIGINAL_URL",
            "aggregator_url": raw_link,
            "original_url": home_original_url,
            "publisher_url": publisher,
            "original_host": _news_url_host(home_original_url),
            "error": "",
        }
    return {
        "status": "PUBLISHER_ATTRIBUTED" if publisher else "AGGREGATOR_ONLY",
        "aggregator_url": raw_link,
        "original_url": "",
        "publisher_url": publisher,
        "original_host": "",
        "error": error or bing_error or home_error,
    }


def _news_material_tags(value: object) -> set[str]:
    normalized = re.sub(r"\s+", "", str(value or "").lower())
    return {
        tag
        for tag, keywords in NEWS_MATERIAL_TAG_RULES.items()
        if any(keyword.lower() in normalized for keyword in keywords)
    }


def _news_event_features(row: dict[str, object]) -> set[str]:
    normalized = re.sub(r"\s+", "", str(row.get("headline") or row.get("name") or "").lower())
    features = {
        feature
        for feature, keywords in NEWS_EVENT_FEATURE_RULES.items()
        if any(keyword.lower() in normalized for keyword in keywords)
    }
    features.update(f"material:{tag}" for tag in _news_material_tags(normalized))
    for corp in row.get("matched_corporations", []) if isinstance(row.get("matched_corporations"), list) else []:
        if isinstance(corp, dict) and str(corp.get("stock_code") or ""):
            features.add(f"corp:{str(corp.get('stock_code')).zfill(6)}")
    normalized_theme = re.sub(
        r"[^0-9a-z가-힣]+",
        "_",
        str(row.get("theme") or "").casefold(),
    ).strip("_")
    if len(normalized_theme) >= 2:
        features.add(f"theme:{normalized_theme}")
    return features


def _match_news_dart_corporations(
    headline: object,
    corp_map: dict[str, dict[str, str]],
    *,
    limit: int = 3,
) -> list[dict[str, str]]:
    normalized_headline = re.sub(r"\s+", "", str(headline or "").lower())
    explicit_symbols = set(re.findall(r"(?<!\d)(\d{6})(?!\d)", normalized_headline))
    matches: list[tuple[int, dict[str, str]]] = []
    for symbol, raw_corp in corp_map.items():
        if not isinstance(raw_corp, dict):
            continue
        corp = {str(key): str(value or "") for key, value in raw_corp.items()}
        corp_name = re.sub(r"(?:주식회사|\(주\)|㈜)|\s+", "", corp.get("name", "").lower())
        symbol_match = symbol in explicit_symbols
        name_match = len(corp_name) >= 4 and corp_name in normalized_headline
        if not symbol_match and not name_match:
            continue
        normalized = {
            "stock_code": str(corp.get("stock_code") or symbol).zfill(6),
            "corp_code": corp.get("corp_code", ""),
            "name": corp.get("name", ""),
        }
        if normalized["corp_code"]:
            matches.append((1000 if symbol_match else len(corp_name), normalized))
    matches.sort(key=lambda item: item[0], reverse=True)
    unique: list[dict[str, str]] = []
    seen: set[str] = set()
    for _, corp in matches:
        if corp["corp_code"] in seen:
            continue
        seen.add(corp["corp_code"])
        unique.append(corp)
        if len(unique) >= max(1, limit):
            break
    return unique


def _dart_disclosure_source_url(item: dict[str, object]) -> str:
    receipt_number = str(item.get("rcept_no") or "").strip()
    return f"https://dart.fss.or.kr/dsaf001/main.do?rcpNo={receipt_number}" if receipt_number else ""


def _dart_disclosure_matches_news(
    headline: object,
    published_at: object,
    disclosure: dict[str, object],
    *,
    now: datetime,
) -> tuple[bool, list[str], int | None]:
    headline_tags = _news_material_tags(headline)
    disclosure_tags = _news_material_tags(disclosure.get("report_nm"))
    matched_tags = sorted(headline_tags & disclosure_tags)
    published, _ = _parse_market_context_observed_at(published_at, default_tz=now.tzinfo)
    disclosed, _ = _parse_market_context_observed_at(disclosure.get("rcept_dt"), default_tz=now.tzinfo)
    # A disclosure published after the article cannot be used as contemporaneous evidence.
    day_distance = (published.date() - disclosed.date()).days if published and disclosed else None
    matched = bool(matched_tags) and day_distance is not None and 0 <= day_distance <= 7
    return matched, matched_tags, day_distance


def _dedupe_paths(paths: list[Path]) -> list[Path]:
    seen: set[str] = set()
    result: list[Path] = []
    for path in paths:
        key = str(path)
        if key in seen:
            continue
        seen.add(key)
        result.append(path)
    return result


def _external_search_codexstock_outbox_path() -> Path:
    configured = str(os.getenv("CODEXSTOCK_EXTERNAL_SIGNAL_OUTBOX", "") or "").strip()
    return Path(configured) if configured else Path(r"C:\external-search-mcp\codexstock_outbox")


def _market_news_collection_request_files() -> list[Path]:
    bridge = _external_search_codexstock_outbox_path() / MARKET_NEWS_EVIDENCE_COLLECTION_BRIDGE_REQUEST_NAME
    return _dedupe_paths([MARKET_NEWS_EVIDENCE_COLLECTION_REQUEST_FILE, bridge])


def _market_news_collection_response_candidate_files() -> list[Path]:
    bridge = _external_search_codexstock_outbox_path() / MARKET_NEWS_EVIDENCE_COLLECTION_BRIDGE_RESPONSE_NAME
    return _dedupe_paths([MARKET_NEWS_EVIDENCE_COLLECTION_RESPONSE_FILE, bridge])


def _write_json_atomic(path: Path, payload: dict[str, object]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    temporary.replace(path)


def _market_news_collection_response_source_file() -> Path | None:
    for path in _market_news_collection_response_candidate_files():
        if path.exists():
            return path
    return None


def _market_news_collection_response_file_status() -> dict[str, object]:
    active = _market_news_collection_response_source_file()
    candidates: list[dict[str, object]] = []
    for path in _market_news_collection_response_candidate_files():
        exists = path.exists()
        stat = None
        if exists:
            try:
                stat = path.stat()
            except OSError:
                stat = None
        candidates.append(
            {
                "path": str(path),
                "exists": exists,
                "size_bytes": int(stat.st_size) if stat else 0,
                "modified_at": (
                    datetime.fromtimestamp(stat.st_mtime, _zone("Asia/Seoul", 9)).isoformat(
                        timespec="seconds"
                    )
                    if stat
                    else ""
                ),
            }
        )
    return {
        "response_file": active.name if active else MARKET_NEWS_EVIDENCE_COLLECTION_RESPONSE_FILE.name,
        "response_write_file": str(MARKET_NEWS_EVIDENCE_COLLECTION_RESPONSE_FILE),
        "response_read_files": [
            str(path) for path in _market_news_collection_response_candidate_files()
        ],
        "response_file_candidates": candidates,
        "active_response_file": str(active) if active else "",
        "file_exists": active is not None,
    }


def _market_news_evidence_collection_request(
    *,
    evidence_gap: dict[str, object],
    article_rows: list[dict[str, object]],
    generated_at: datetime,
    report_fingerprint: str,
) -> dict[str, object]:
    requested_events: list[dict[str, object]] = []
    if evidence_gap.get("independent_multi_source_requirement_satisfied") is not True:
        for row in article_rows:
            if not isinstance(row, dict):
                continue
            domain_count = int(_number(row.get("independent_original_domain_count")))
            if domain_count >= 2:
                continue
            headline = str(row.get("headline") or row.get("name") or "").strip()
            if not headline:
                continue
            event_features = row.get("event_feature_keys")
            requested_events.append(
                {
                    "headline": headline[:220],
                    "theme": str(row.get("theme") or ""),
                    "observed_at": str(row.get("observed_at") or ""),
                    "known_original_domains": row.get("independent_original_domains", []),
                    "known_original_urls": row.get("original_source_urls", []),
                    "known_aggregator_urls": row.get("source_urls", []),
                    "event_feature_keys": event_features if isinstance(event_features, list) else [],
                    "required_new_independent_original_domain_count": max(0, 2 - domain_count),
                    "acceptance_contract": {
                        "must_resolve_to_original_article_url": True,
                        "must_be_independent_from_known_original_domains": True,
                        "must_match_same_event_or_claim": True,
                        "aggregator_or_homepage_only_not_accepted": True,
                        "minimum_independent_original_domain_count": 2,
                        "external_engine_decision": "VERIFY_ONLY",
                        "score_allowed": False,
                        "live_order_allowed": False,
                    },
                }
            )
            if len(requested_events) >= 5:
                break
    request_basis = {
        "report_fingerprint": report_fingerprint,
        "requested_events": requested_events,
        "missing_domains": evidence_gap.get("missing_independent_original_domain_count"),
    }
    return {
        "schema": "codexstock_market_news_evidence_collection_request_v1",
        "request_id": hashlib.sha256(
            json.dumps(request_basis, ensure_ascii=True, sort_keys=True).encode("utf-8")
        ).hexdigest()[:24],
        "generated_at": generated_at.isoformat(timespec="seconds"),
        "status": "PENDING_EXTERNAL_NEWS_ORIGINAL_COLLECTION" if requested_events else "NO_NEWS_EVIDENCE_GAPS",
        "action": "COLLECT_INFORMATION_ONLY",
        "source_report_fingerprint": report_fingerprint,
        "requested_event_count": len(requested_events),
        "requested_events": requested_events,
        "delivery": {
            "pull_endpoint": "/api/market/news-evidence-collection-request",
            "persisted_file": MARKET_NEWS_EVIDENCE_COLLECTION_REQUEST_FILE.name,
            "request_write_files": [
                str(path) for path in _market_news_collection_request_files()
            ],
            "response_status_endpoint": "/api/market/news-evidence-collection-response-status",
            "response_write_file": str(MARKET_NEWS_EVIDENCE_COLLECTION_RESPONSE_FILE),
            "response_write_files": [
                str(path) for path in _market_news_collection_response_candidate_files()
            ],
            "response_schema": "codexstock_market_news_evidence_collection_response_v1",
            "response_contract": {
                "write_encoding": "utf-8",
                "atomic_write_recommended": True,
                "required_top_level_fields": [
                    "schema",
                    "request_id",
                    "generated_at",
                    "action",
                    "source_report_fingerprint",
                    "score_allowed",
                    "live_order_allowed",
                    "safety",
                    "resolved_events",
                ],
                "required_event_fields": [
                    "request_headline",
                    "headline",
                    "event_feature_keys",
                    "sources",
                ],
                "required_source_fields": [
                    "source",
                    "source_url",
                    "publisher_url",
                    "headline",
                    "observed_at",
                ],
                "source_url_policy": "original_article_url_only_no_google_naver_homepage_or_aggregator",
                "decision_policy": "VERIFY_ONLY",
                "score_allowed": False,
                "live_order_allowed": False,
            },
            "response_template": {
                "schema": "codexstock_market_news_evidence_collection_response_v1",
                "request_id": "",
                "generated_at": "",
                "action": "VERIFY_ONLY",
                "source_report_fingerprint": report_fingerprint,
                "score_allowed": False,
                "live_order_allowed": False,
                "safety": {
                    "score_allowed": False,
                    "live_order_allowed": False,
                    "requires_codexstock_validation": True,
                },
                "resolved_events": [
                    {
                        "request_headline": requested_events[0]["headline"] if requested_events else "",
                        "headline": requested_events[0]["headline"] if requested_events else "",
                        "event_feature_keys": requested_events[0]["event_feature_keys"] if requested_events else [],
                        "sources": [
                            {
                                "source": "publisher-name",
                                "source_url": "https://publisher.example/article/original",
                                "publisher_url": "https://publisher.example",
                                "headline": requested_events[0]["headline"] if requested_events else "",
                                "observed_at": generated_at.isoformat(timespec="seconds"),
                            }
                        ],
                    }
                ] if requested_events else [],
            },
        },
        "safety": {
            "decision_scope": "information_only",
            "external_engine_decision": "VERIFY_ONLY",
            "requires_codexstock_validation": True,
            "score_allowed": False,
            "promotion_allowed": False,
            "live_order_allowed": False,
        },
    }


def _save_market_news_evidence_collection_request(payload: dict[str, object]) -> dict[str, object]:
    saved: list[str] = []
    errors: list[str] = []
    for path in _market_news_collection_request_files():
        try:
            _write_json_atomic(path, payload)
            saved.append(str(path))
        except OSError as exc:
            errors.append(f"{path}:{type(exc).__name__}")
    return {
        "schema": "codexstock_market_news_evidence_collection_request_save_v1",
        "saved_count": len(saved),
        "saved_files": saved,
        "error_count": len(errors),
        "errors": errors,
        "bridge_outbox": str(_external_search_codexstock_outbox_path()),
    }


def _market_news_response_event_matches(row: dict[str, object], event: dict[str, object]) -> bool:
    row_headline = " ".join(str(row.get("headline") or row.get("name") or "").split()).casefold()
    event_headline = " ".join(
        str(event.get("request_headline") or event.get("headline") or "").split()
    ).casefold()
    if row_headline and event_headline and row_headline == event_headline:
        return True
    row_features = set(row.get("event_feature_keys") or _news_event_features(row))
    event_features = {
        str(item)
        for item in event.get("event_feature_keys", [])
        if str(item or "").strip()
    } if isinstance(event.get("event_feature_keys"), list) else set()
    if len(row_features & event_features) >= 2:
        return True
    row_terms = _news_claim_terms(row_headline)
    event_terms = _news_claim_terms(event_headline)
    if not row_terms or not event_terms:
        return False
    overlap = len(row_terms & event_terms)
    return overlap >= 3 and overlap / max(1, min(len(row_terms), len(event_terms))) >= 0.6


def _apply_market_news_evidence_collection_response(
    rows: list[dict[str, object]],
    *,
    report_fingerprint: str,
    now: datetime,
) -> dict[str, object]:
    """Merge external scout findings only as untrusted source records for CodexStock validation."""
    status: dict[str, object] = {
        "schema": "codexstock_market_news_evidence_collection_response_status_v1",
        "enabled": True,
        **_market_news_collection_response_file_status(),
        "expected_response_schema": "codexstock_market_news_evidence_collection_response_v1",
        "source_usable": False,
        "accepted_source_record_count": 0,
        "rejected_source_record_count": 0,
        "matched_event_count": 0,
        "response_generated_at": "",
        "response_request_id": "",
        "source_report_fingerprint": "",
        "source_report_fingerprint_matches_current": False,
        "current_event_revalidation_required": False,
        "accepted_via_current_event_revalidation": False,
        "blockers": [],
        "score_allowed": False,
        "live_order_allowed": False,
        "response_contract": {
            "action": "VERIFY_ONLY",
            "source_url_policy": "original_article_url_only_no_google_naver_homepage_or_aggregator",
            "required_top_level_fields": [
                "schema",
                "request_id",
                "generated_at",
                "action",
                "source_report_fingerprint",
                "score_allowed",
                "live_order_allowed",
                "safety",
                "resolved_events",
            ],
            "required_source_fields": [
                "source",
                "source_url",
                "publisher_url",
                "headline",
                "observed_at",
            ],
        },
    }
    response_file = _market_news_collection_response_source_file()
    if response_file is None:
        status["blockers"] = ["response_file_missing"]
        return status
    try:
        response = json.loads(response_file.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        status["blockers"] = [f"response_file_unreadable:{type(exc).__name__}"]
        return status
    if not isinstance(response, dict):
        status["blockers"] = ["response_payload_not_object"]
        return status
    status["response_generated_at"] = str(response.get("generated_at") or "")
    status["response_request_id"] = str(response.get("request_id") or "")
    status["source_report_fingerprint"] = str(response.get("source_report_fingerprint") or "")
    safety = response.get("safety") if isinstance(response.get("safety"), dict) else {}
    blockers: list[str] = []
    if str(response.get("schema") or "") != "codexstock_market_news_evidence_collection_response_v1":
        blockers.append("schema_mismatch")
    if str(response.get("action") or response.get("external_engine_decision") or "").upper() != "VERIFY_ONLY":
        blockers.append("external_decision_not_verify_only")
    if response.get("score_allowed") is True or safety.get("score_allowed") is True:
        blockers.append("external_score_allowed_not_false")
    if response.get("live_order_allowed") is True or safety.get("live_order_allowed") is True:
        blockers.append("external_live_order_allowed_not_false")
    declared_fingerprint = str(response.get("source_report_fingerprint") or "")
    fingerprint_matches_current = bool(
        declared_fingerprint and declared_fingerprint == report_fingerprint
    )
    status["source_report_fingerprint_matches_current"] = fingerprint_matches_current
    status["current_event_revalidation_required"] = bool(
        declared_fingerprint and not fingerprint_matches_current
    )
    if not declared_fingerprint:
        blockers.append("source_report_fingerprint_missing")
    generated_at, _ = _parse_market_context_observed_at(response.get("generated_at"), default_tz=now.tzinfo)
    if generated_at and abs((now - generated_at).total_seconds()) > 48 * 60 * 60:
        blockers.append("response_stale_over_48h")
    events = response.get("resolved_events") if isinstance(response.get("resolved_events"), list) else []
    if not events:
        blockers.append("resolved_events_missing")
    if blockers:
        status["blockers"] = sorted(blockers)
        return status

    accepted = 0
    rejected = 0
    matched_events = 0
    for event in events[:10]:
        if not isinstance(event, dict):
            rejected += 1
            continue
        target_row: dict[str, object] | None = None
        for row in rows:
            if _market_news_response_event_matches(row, event):
                target_row = row
                break
        if target_row is None:
            rejected += 1
            continue
        sources = event.get("sources") if isinstance(event.get("sources"), list) else []
        existing_records = target_row.get("source_records")
        source_records = existing_records if isinstance(existing_records, list) else []
        existing_urls = {
            str(record.get("source_url") or "")
            for record in source_records
            if isinstance(record, dict)
        }
        event_accepted = 0
        for source in sources[:8]:
            if not isinstance(source, dict):
                rejected += 1
                continue
            source_url = str(source.get("source_url") or source.get("original_url") or "").strip()
            publisher_url = str(source.get("publisher_url") or source.get("publisher_home_url") or "").strip()
            if not source_url.startswith(("http://", "https://")):
                rejected += 1
                continue
            if _is_news_aggregator_url(source_url):
                rejected += 1
                continue
            if source_url in existing_urls:
                continue
            source_records.append(
                {
                    "source": str(source.get("source") or source.get("publisher") or "external-news-scout")[:120],
                    "source_url": source_url,
                    "publisher_url": publisher_url,
                    "headline": str(source.get("headline") or event.get("headline") or target_row.get("headline") or "")[:500],
                    "observed_at": str(source.get("observed_at") or response.get("generated_at") or ""),
                    "evidence_origin": "external_news_collection_response",
                    "requires_codexstock_validation": True,
                    "score_allowed": False,
                    "live_order_allowed": False,
                }
            )
            existing_urls.add(source_url)
            event_accepted += 1
        if event_accepted:
            matched_events += 1
            accepted += event_accepted
            target_row["source_records"] = source_records
            target_row["source_urls"] = sorted({
                *[str(url) for url in target_row.get("source_urls", []) if str(url or "").strip()],
                *[str(record.get("source_url") or "") for record in source_records if isinstance(record, dict)],
            })
            target_row["publisher_urls"] = sorted({
                *[str(url) for url in target_row.get("publisher_urls", []) if str(url or "").strip()],
                *[str(record.get("publisher_url") or "") for record in source_records if isinstance(record, dict) and str(record.get("publisher_url") or "").strip()],
            })
            target_row["corroborating_sources"] = sorted({
                *[str(item) for item in target_row.get("corroborating_sources", []) if str(item or "").strip()],
                *[str(record.get("source") or "") for record in source_records if isinstance(record, dict) and str(record.get("source") or "").strip()],
            })
            target_row["corroborating_source_count"] = len(target_row["corroborating_sources"])
            target_row["external_collection_response_applied"] = True
        else:
            rejected += 1
    status.update(
        {
            "source_usable": accepted > 0,
            "accepted_source_record_count": accepted,
            "rejected_source_record_count": rejected,
            "matched_event_count": matched_events,
            "accepted_via_current_event_revalidation": bool(
                accepted and not fingerprint_matches_current
            ),
            "blockers": [] if accepted else ["no_accepted_original_sources"],
        }
    )
    return status


