def _build_intraday_candidate_brief(
    radar: dict[str, object],
    account: dict[str, object],
    policy: dict[str, object],
    *,
    generated_at: str | None = None,
) -> dict[str, object]:
    """Compress the live radar into an affordable, user-facing candidate brief."""
    summary = account.get("summary") if isinstance(account.get("summary"), dict) else {}
    available_cash = _number(summary.get("available_cash") or summary.get("cash"))
    equity = _number(
        summary.get("net_liquidation_value")
        or summary.get("total_value")
        or summary.get("broker_total_value")
        or (available_cash + _number(summary.get("stock_value")))
    )
    position_pct = max(
        0.0,
        min(
            _number(
                policy.get(
                    "delegated_live_max_position_cash_pct",
                    policy.get("live_pilot_max_cash_pct", 15.0),
                )
            )
            or 15.0,
            100.0,
        ),
    )
    position_cap = min(available_cash, equity * position_pct / 100.0) if equity > 0 else 0.0
    rows = radar.get("items") if isinstance(radar.get("items"), list) else []
    ranked: list[dict[str, object]] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        price = _number(row.get("price"))
        score = _number(row.get("score"))
        strength = _number(row.get("avg_strength"))
        minute = _number(row.get("minute_momentum_pct"))
        action = str(row.get("action") or "대기")
        affordable = bool(price > 0 and position_cap >= price and available_cash >= price)
        evidence_ready = bool(
            action in {"단타 관찰", "후보 유지"}
            and score >= 65.0
            and strength >= 105.0
            and minute > 0.0
        )
        if evidence_ready and affordable:
            lane = "실행검토"
            note = "한도 내 1주 가능 · 주문 직전 안전검사 필요"
        elif evidence_ready:
            lane = "한도초과"
            note = f"1주 {price:,.0f}원 > 종목한도 {position_cap:,.0f}원"
        elif action == "회피/대기" or minute < 0 or strength < 95:
            lane = "제외"
            note = str(row.get("reason") or "분봉 또는 체결강도 약세")
        else:
            lane = "조건부"
            note = str(row.get("reason") or "추가 확인 필요")
        ranked.append(
            {
                "symbol": str(row.get("symbol") or ""),
                "name": str(row.get("name") or row.get("symbol") or "-"),
                "price": round(price, 2),
                "change_pct": round(_number(row.get("change_pct")), 2),
                "score": round(score, 1),
                "avg_strength": round(strength, 1),
                "minute_momentum_pct": round(minute, 3),
                "action": action,
                "lane": lane,
                "affordable": affordable,
                "note": note,
            }
        )
    lane_order = {"실행검토": 4, "한도초과": 3, "조건부": 2, "제외": 1}
    ranked.sort(
        key=lambda row: (
            lane_order.get(str(row.get("lane")), 0),
            _number(row.get("score")),
            _number(row.get("avg_strength")),
        ),
        reverse=True,
    )
    shortlist = [
        row for row in ranked
        if row.get("affordable") and row.get("lane") != "제외"
    ][:4]
    rejected = [
        row for row in ranked
        if not row.get("affordable") or row.get("lane") == "제외"
    ][:6]
    signature_rows = [
        f"{row.get('symbol')}:{row.get('lane')}:{row.get('action')}"
        for row in [*shortlist, *rejected]
    ]
    signature = hashlib.sha256("|".join(signature_rows).encode("utf-8")).hexdigest()[:16]
    stamp = generated_at or datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds")
    lines = [
        "[코덱스스톡 장중 후보 보고]",
        f"기준 {stamp[11:19] if len(stamp) >= 19 else stamp} · 종목당 한도 {position_cap:,.0f}원",
    ]
    if shortlist:
        for index, row in enumerate(shortlist, start=1):
            lines.append(
                f"{index}. {row['name']} {row['change_pct']:+.2f}% · {row['score']:.1f}점 · "
                f"체결 {row['avg_strength']:.1f} · {row['lane']}"
            )
            lines.append(f"   {row['note']}")
    else:
        lines.append("현재 조건을 충족한 실제 매매 후보 없음")
    if rejected:
        lines.append("제외: " + ", ".join(f"{row['name']}({row['note']})" for row in rejected))
    lines.append("후보가 바뀌면 즉시 다시 보고합니다.")
    return {
        "ok": bool(radar.get("ok")),
        "schema": "codexstock_intraday_candidate_brief_v1",
        "generated_at": stamp,
        "available_cash": round(available_cash, 2),
        "equity": round(equity, 2),
        "position_limit_pct": round(position_pct, 2),
        "position_limit_krw": round(position_cap, 2),
        "shortlist": shortlist,
        "rejected": rejected,
        "signature": signature,
        "text": "\n".join(lines),
        "live_order_allowed": False,
    }


