    def update_staff_activity(
        self,
        role: str,
        task: str,
        detail: str = "",
        *,
        state: str = "상시근무",
        tone: str = "active",
        target: str = "",
        progress_pct: int | float | None = None,
        evidence: str = "",
        next_action: str = "",
    ) -> None:
        now = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
        current = dict(self.staff_activity.get(role, {})) if isinstance(self.staff_activity.get(role), dict) else {}
        current.update(
            {
                "state": state,
                "tone": tone,
                "task": task,
                "detail": detail or current.get("detail", ""),
                "target": target or current.get("target", "-"),
                "updated_at": now,
                "continuous": self.running,
            }
        )
        if progress_pct is not None:
            current["progress_pct"] = progress_pct
        if evidence:
            current["evidence"] = evidence
        if next_action:
            current["next_action"] = next_action
        self.staff_activity[role] = current
        self.record_staff_activity(role, current)

    def record_staff_activity(self, role: str, activity: dict[str, object], force: bool = False) -> None:
        signature = "|".join(
            str(activity.get(key, ""))
            for key in ("state", "task", "target", "evidence", "next_action", "continuous")
        )
        if not force and self.staff_activity_signatures.get(role) == signature:
            return
        self.staff_activity_signatures[role] = signature
        role_meta = next((item for item in AI_STAFF_ROLES if item.get("id") == role), {})
        role_name_overrides = {"risk": "리스크 관리자", "telegram": "텔레그램 비서"}
        record = {
            "created_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
            "role": role,
            "name": activity.get("name") or role_meta.get("name") or role_name_overrides.get(role) or role,
            "state": activity.get("state", "-"),
            "tone": activity.get("tone", "-"),
            "task": activity.get("task", "-"),
            "detail": activity.get("detail", ""),
            "target": activity.get("target", "-"),
            "progress_pct": activity.get("progress_pct", 0),
            "evidence": activity.get("evidence", ""),
            "next_action": activity.get("next_action", ""),
            "continuous": bool(activity.get("continuous", self.running)),
            "running": bool(self.running),
        }
        try:
            _append_jsonl(AI_STAFF_ACTIVITY_FILE, record)
            self.staff_activity_write_count += 1
            if self.staff_activity_write_count % 50 == 0:
                _compact_jsonl(AI_STAFF_ACTIVITY_FILE, max_rows=1200)
        except Exception:
            pass

    def activate_staff_roster(self, force_log: bool = False) -> None:
        self.staff_activity = self.default_staff_activity(running=self.running)
        for role, activity in self.staff_activity.items():
            self.record_staff_activity(role, activity, force=force_log)

    def set_activity(
        self,
        label: str,
        detail: str = "",
        phase: str = "working",
        symbol: str = "",
        symbol_name: str = "",
        progress_pct: int | float | None = None,
    ) -> None:
        now = datetime.now().isoformat(timespec="seconds")
        previous = self.current_activity if isinstance(self.current_activity, dict) else {}
        self.current_activity = {
            "phase": phase,
            "label": label,
            "detail": detail,
            "symbol": symbol,
            "symbol_name": symbol_name or symbol,
            "started_at": previous.get("started_at") if previous.get("phase") == phase and previous.get("label") == label else now,
            "updated_at": now,
            "progress_pct": progress_pct,
        }

