    expected_unit_quote_unit = str(unit_policy.get("quote_unit") or "share").strip().lower()
    split_adjustment_required = bool(unit_policy.get("split_adjustment_required", True))

    def _canonical_quote_unit(value: object) -> str:
        normalized = re.sub(r"[\s\-]+", "_", str(value or "").strip().lower())
        if normalized in {"share", "shares", "stock_share", "equity_share", "per_share", "price_per_share", "주", "주식"}:
            return "share"
        return normalized

