def build_sector_investment_committee(
    force: bool = False,
    symbols: list[str] | None = None,
    *,
    allow_stale_health_cache: bool = False,
) -> dict[str, object]:
    screener = build_ai_screener(
        symbols=symbols,
        force=force,
        allow_stale_health_cache=allow_stale_health_cache,
    )
    candidates = [
        item for item in screener.get("candidates", [])
        if isinstance(item, dict)
    ]
    try:
        market_clock = build_market_session_clock()
    except Exception:
        market_clock = {}
    committee = _investment_committee_from_candidates(
        candidates,
        market_clock=market_clock,
        decision_label="sector-first research committee",
    )
    return {
        "ok": bool(committee.get("ok")),
        "status": committee.get("status", "insufficient_evidence"),
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "source": "sector-committee-api",
        "screener_cached": bool(screener.get("cached")),
        "health_probe_cache": bool(screener.get("health_probe_cache")),
        "candidate_count": len(candidates),
        "top_candidates": [
            {
                "symbol": row.get("symbol"),
                "name": row.get("name"),
                "score": row.get("score"),
                "sector": (row.get("candidate_sector") or {}).get("label") if isinstance(row.get("candidate_sector"), dict) else "",
                "lane": row.get("candidate_lane"),
            }
            for row in candidates[:8]
        ],
        "investment_committee": committee,
        "safety": "Read-only research/Paper committee. No live order is submitted.",
    }


TOURNAMENT_RECONCILIATION_HEALTH_CACHE_LOCK = threading.Lock()
TOURNAMENT_RECONCILIATION_HEALTH_CACHES: dict[
    tuple[int, int, int], StaleWhileRefreshStatusCache
] = {}


def _cached_tournament_reconciliation_health_audit(
    *,
    limit: int = 300,
    queue_limit: int = 20,
    batch_limit: int = 12,
    ttl_seconds: int = 300,
) -> dict[str, object]:
    """Share a durable stale-while-refresh audit across Stage 2 health probes."""
    key = (int(limit), int(queue_limit), int(batch_limit))
    with TOURNAMENT_RECONCILIATION_HEALTH_CACHE_LOCK:
        cache = TOURNAMENT_RECONCILIATION_HEALTH_CACHES.get(key)
        if cache is None:
            cache = StaleWhileRefreshStatusCache(
                builder=lambda: ai_tournament_reconciliation_audit(
                    limit=key[0],
                    queue_limit=key[1],
                    batch_limit=key[2],
                ),
                cache_path=_runtime_file(
                    f"tournament_reconciliation_health_{key[0]}_{key[1]}_{key[2]}.json"
                ),
                schema_version="tournament-reconciliation-health-cache.v1",
                ttl_seconds=max(30, int(ttl_seconds)),
                durable_validator=lambda payload: isinstance(payload.get("stage2_handoff"), dict),
            )
            TOURNAMENT_RECONCILIATION_HEALTH_CACHES[key] = cache
    return cache.get()


def _tournament_reconciliation_health_probe() -> dict[str, object]:
    replay_status = responsive_historical_replay_regeneration_status()
    progress = replay_status.get("progress") if isinstance(replay_status.get("progress"), dict) else {}
    target_count = int(_number(progress.get("total_candidate_count")))
    verified_count = int(_number(progress.get("verified_count")))
    remaining_count = int(_number(progress.get("remaining_candidate_count")))
    certificate = _cached_verified_historical_replay_completion_certificate()
    if (
        target_count > 0
        and verified_count == target_count
        and remaining_count == 0
        and certificate.get("ok") is True
        and certificate.get("completion_verified") is True
        and int(_number(certificate.get("resolved_count"))) == target_count
    ):
        return {
            "ok": True,
            "status": "ready_certified_replacement_scope",
            "severity": "ok",
            "status_reason": "signed_757_replacement_scope_verified",
            "summary": {
                "status": "ready_certified_replacement_scope",
                "target_count": target_count,
                "verified_count": verified_count,
                "remaining_count": 0,
                "legacy_claims_quarantined": True,
                "legacy_official_return_claim_allowed": False,
            },
            "regeneration_progress": progress,
            "certificate_id": certificate.get("certificate_id", ""),
            "certificate_sha256": certificate.get("certificate_sha256", ""),
            "source_last_success_at": certificate.get("issued_at", ""),
            "official_performance_scope": "certified_757_replacement_replays_only",
            "legacy_claims_quarantined": True,
            "legacy_official_return_claim_allowed": False,
            "deep_legacy_audit_endpoint": "/api/ai-tournament/reconciliation-audit",
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
            "safety": "Only signed replacement replays are healthy; legacy return claims remain quarantined.",
        }
    payload = dict(ai_tournament_reconciliation_audit(limit=300))
    audit_candidate_count = int(_number(payload.get("regeneration_candidate_count")))
    campaign_target_count, campaign_source_ids = _historical_replay_campaign_manifest_scope()
    campaign_scope_ready = bool(campaign_target_count and campaign_source_ids)
    progress_target_count = campaign_target_count if campaign_scope_ready else audit_candidate_count
    candidate_count_delta = campaign_target_count - audit_candidate_count if campaign_scope_ready else 0
    payload["regeneration_progress"] = _historical_replay_regeneration_ledger_progress(
        progress_target_count,
        source_replay_ids=campaign_source_ids or None,
    )
    payload["regeneration_audit_candidate_count"] = audit_candidate_count
    payload["regeneration_campaign_target_count"] = campaign_target_count
    payload["regeneration_campaign_scope_count"] = len(campaign_source_ids)
    payload["regeneration_candidate_count_delta"] = candidate_count_delta
    payload["regeneration_progress_denominator_source"] = (
        "frozen_campaign_manifest"
        if campaign_scope_ready
        else "current_audit_candidate_count"
    )
    summary = dict(payload.get("summary")) if isinstance(payload.get("summary"), dict) else {}
    summary.update(
        {
            "regeneration_audit_candidate_count": audit_candidate_count,
            "regeneration_campaign_target_count": campaign_target_count,
            "regeneration_campaign_scope_count": len(campaign_source_ids),
            "regeneration_candidate_count_delta": candidate_count_delta,
            "regeneration_progress_denominator_source": payload[
                "regeneration_progress_denominator_source"
            ],
        }
    )
    payload["summary"] = summary
    safely_quarantined_legacy = (
        str(summary.get("status") or "").lower() == "review_required"
        and int(_number(summary.get("missing_summary_rows"))) == 0
        and int(_number(summary.get("blocker_rows"))) == 0
        and int(_number(summary.get("official_return_blocker_trade_count"))) == 0
        and int(_number(summary.get("warning_rows"))) > 0
        and not bool(summary.get("official_return_claim_allowed"))
    )
    if not safely_quarantined_legacy:
        return payload
    health_payload = dict(payload)
    health_summary = dict(summary)
    health_summary["audit_status"] = summary.get("status")
    health_summary["status"] = "ready_with_historical_quarantine"
    health_payload["summary"] = health_summary
    health_payload["audit_status"] = payload.get("status") or summary.get("audit_status")
    health_payload["status"] = "ready_with_historical_quarantine"
    health_payload["severity"] = "warning"
    health_payload["status_reason"] = "legacy_trailing_evidence_quarantined"
    health_payload["official_performance_scope"] = "verified_current_engine_only"
    return health_payload


def _tournament_completion_certificate_health_probe() -> dict[str, object]:
    """Distinguish expected replay progress from a broken final certificate."""
    replay_status = responsive_historical_replay_regeneration_status()
    progress = (
        dict(replay_status.get("progress") or {})
        if isinstance(replay_status.get("progress"), dict)
        else {}
    )
    total_count = int(_number(progress.get("total_candidate_count")))
    remaining_count = int(_number(progress.get("remaining_candidate_count")))
    verified_count = int(_number(progress.get("verified_count")))
    certificate = _cached_verified_historical_replay_completion_certificate()
    certificate_status = str(certificate.get("status") or "certificate_missing")
    base = {
        "summary": {
            "target_count": total_count,
            "verified_count": verified_count,
            "remaining_count": remaining_count,
            "certificate_status": certificate_status,
        },
        "regeneration_progress": progress,
        "certificate_status": certificate_status,
        "certificate_path": certificate.get("path", ""),
        "paper_only": True,
        "score_allowed": False,
        "automatic_promotion": False,
        "live_order_allowed": False,
        "safety": "Read-only completion-certificate probe. No live order is submitted.",
    }
    if remaining_count > 0 or total_count <= 0:
        return {
            **base,
            "ok": True,
            "status": "verification_pending",
            "severity": "warning",
            "status_reason": "historical_replay_regeneration_in_progress",
            "summary": {
                **base["summary"],
                "status": "verification_pending",
            },
            "action": (
                "Let the serial Paper replay worker finish, then require a verified completion "
                "certificate before accepting the 757-replay result."
            ),
        }
    if bool(certificate.get("ok")) and certificate_status == "certificate_verified":
        issued_at = str(certificate.get("issued_at") or "")
        return {
            **base,
            "ok": True,
            "status": "certificate_verified",
            "severity": "ok",
            "status_reason": "historical_replay_completion_certificate_verified",
            "summary": {
                **base["summary"],
                "status": "certificate_verified",
            },
            "certificate_id": certificate.get("certificate_id", ""),
            "certificate_sha256": certificate.get("certificate_sha256", ""),
            "issued_at": issued_at,
            "source_last_success_at": issued_at,
            "score_allowed": True,
        }
    return {
        **base,
        "ok": False,
        "status": certificate_status,
        "severity": "error",
        "status_reason": f"historical_replay_{certificate_status}",
        "summary": {
            **base["summary"],
            "status": certificate_status,
        },
        "action": (
            "Rerun the final deep evidence audit and issue a fresh signed certificate; "
            "keep scores, promotion, and live orders blocked until verification passes."
        ),
    }


def _tournament_data_gap_health_probe() -> dict[str, object]:
    payload = dict(historical_replay_data_gap_queue(record=False))
    payload["severity"] = "warning" if int(_number(payload.get("request_count"))) else "ok"
    payload["status_reason"] = (
        "historical_ohlcv_backfill_required"
        if int(_number(payload.get("request_count")))
        else "no_unresolved_data_gap"
    )
    return payload


TOURNAMENT_DATA_GAP_STORAGE_CACHE: dict[str, object] = {
    "saved_at": 0.0,
    "scope": "",
    "payload": {},
}


def _tournament_data_gap_storage_health_probe() -> dict[str, object]:
    def signature(path: Path) -> str:
        try:
            stat = path.stat()
            return f"{path.resolve()}:{stat.st_mtime_ns}:{stat.st_size}"
        except OSError:
            return f"{path.resolve()}:missing"

    scope = "|".join(
        (
            signature(HISTORICAL_REPLAY_DATA_GAP_RESULT_DIR),
            signature(HISTORICAL_REPLAY_DATA_GAP_INDEX_FILE),
        )
    )
    cached = load_probe_cache(
        TOURNAMENT_DATA_GAP_STORAGE_CACHE,
        HISTORICAL_REPLAY_DATA_GAP_STORAGE_CACHE_FILE,
        schema_version="historical-data-gap-storage-audit-cache.v1",
        scope=scope,
        ttl_seconds=24 * 60 * 60,
    )
    if cached is not None:
        return cached
    payload = _audit_replay_data_backfill_storage(
        result_dir=HISTORICAL_REPLAY_DATA_GAP_RESULT_DIR,
        index_path=HISTORICAL_REPLAY_DATA_GAP_INDEX_FILE,
    )
    save_probe_cache(
        TOURNAMENT_DATA_GAP_STORAGE_CACHE,
        HISTORICAL_REPLAY_DATA_GAP_STORAGE_CACHE_FILE,
        payload,
        schema_version="historical-data-gap-storage-audit-cache.v1",
        scope=scope,
    )
    return payload


def _tournament_champion_health_probe() -> dict[str, object]:
    replay_status = responsive_historical_replay_regeneration_status()
    progress = replay_status.get("progress") if isinstance(replay_status.get("progress"), dict) else {}
    target_count = int(_number(progress.get("total_candidate_count")))
    verified_count = int(_number(progress.get("verified_count")))
    remaining_count = int(_number(progress.get("remaining_candidate_count")))
    certificate = _cached_verified_historical_replay_completion_certificate()
    if (
        target_count > 0
        and verified_count == target_count
        and remaining_count == 0
        and certificate.get("ok") is True
        and certificate.get("completion_verified") is True
    ):
        return {
            "ok": True,
            "status": "ready_without_unverified_champion_claim",
            "severity": "ok",
            "status_reason": "official_champion_claims_safely_excluded",
            "summary": {
                "status": "ready_without_unverified_champion_claim",
                "target_count": target_count,
                "verified_count": verified_count,
                "official_champion_claim_allowed": False,
                "legacy_claims_quarantined": True,
            },
            "certificate_id": certificate.get("certificate_id", ""),
            "source_last_success_at": certificate.get("issued_at", ""),
            "official_performance_scope": "certified_757_replacement_replays_only",
            "official_champion_claim_allowed": False,
            "legacy_claims_quarantined": True,
            "deep_legacy_audit_endpoint": "/api/ai-tournament/champion-audit",
            "paper_only": True,
            "automatic_promotion": False,
            "live_order_allowed": False,
            "safety": "Health is verified without publishing an unproven champion or legend claim.",
        }
    payload = ai_tournament_champion_audit(limit=300, legend_threshold_pct=500.0)
    summary = payload.get("summary") if isinstance(payload.get("summary"), dict) else {}
    safely_quarantined_claims = (
        str(summary.get("reconciliation_status") or "").lower() == "review_required"
        and int(_number(summary.get("official_win_rows"))) == 0
        and int(_number(summary.get("trusted_official_win_rows"))) == 0
        and int(_number(summary.get("legend_count"))) == 0
    )
    if not safely_quarantined_claims:
        return payload
    health_payload = dict(payload)
    health_payload["audit_status"] = payload.get("status")
    health_payload["status"] = "ready_with_historical_quarantine"
    health_payload["severity"] = "warning"
    health_payload["status_reason"] = "unverified_historical_champion_claims_quarantined"
    health_payload["official_performance_scope"] = "verified_current_engine_only"
    return health_payload


