def _feature_surface_coverage_contract(surface_contracts: dict[str, object]) -> dict[str, object]:
    summary = surface_contracts.get("summary") if isinstance(surface_contracts.get("summary"), dict) else {}
    button_total = int(_number(summary.get("ui_button_count")))
    button_covered = int(_number(summary.get("ui_button_bound_count")))
    api_total = int(_number(summary.get("ui_api_call_count")))
    api_covered = max(0, api_total - int(_number(summary.get("ui_api_missing_count"))))
    mcp_total = int(_number(summary.get("mcp_tool_count")))
    mcp_covered = int(_number(summary.get("mcp_tool_handled_count")))
    total = button_total + api_total + mcp_total
    covered = button_covered + api_covered + mcp_covered
    ok = bool(surface_contracts.get("ok")) and total > 0 and covered == total
    return {
        "ok": ok,
        "schema": "codexstock_feature_surface_coverage_v1",
        "coverage_kind": "structural_wiring",
        "runtime_execution_verified": False,
        "runtime_evidence_required_separately": True,
        "coverage_pct": round(covered / total * 100.0, 2) if total else 0.0,
        "covered_count": covered,
        "total_count": total,
        "ui_buttons": {
            "covered_count": button_covered,
            "total_count": button_total,
            "missing_count": max(0, button_total - button_covered),
        },
        "ui_api_calls": {
            "covered_count": api_covered,
            "total_count": api_total,
            "missing_count": max(0, api_total - api_covered),
        },
        "mcp_tools": {
            "covered_count": mcp_covered,
            "total_count": mcp_total,
            "missing_count": max(0, mcp_total - mcp_covered),
        },
        "missing": list(surface_contracts.get("missing") or []),
        "audit_only": True,
        "live_order_allowed": False,
    }


def _feature_runtime_execution_evidence(
    checks: list[dict[str, object]],
    surface_coverage: dict[str, object],
    *,
    recent_window_seconds: int = 24 * 60 * 60,
) -> dict[str, object]:
    """Summarize bounded runtime probes without overstating static coverage."""
    safe_window = max(60, int(recent_window_seconds))
    recent_ids: list[str] = []
    stale_ids: list[str] = []
    never_verified_ids: list[str] = []
    current_issue_ids: list[str] = []
    monitored_endpoints: set[str] = set()
    monitored_mcp_tools: set[str] = set()

    for index, row in enumerate(checks):
        check_id = str(row.get("id") or f"check_{index + 1}")
        endpoint = str(row.get("endpoint") or "").strip()
        mcp_tool = str(row.get("mcp_tool") or "").strip()
        if endpoint:
            monitored_endpoints.add(endpoint)
        if mcp_tool:
            monitored_mcp_tools.add(mcp_tool)

        last_success_at = str(row.get("last_success_at") or "").strip()
        if not last_success_at:
            never_verified_ids.append(check_id)
        else:
            age_seconds = (
                int(max(0, _number(row.get("last_success_age_seconds"))))
                if "last_success_age_seconds" in row
                else _iso_age_seconds(last_success_at)
            )
            if age_seconds is not None and age_seconds <= safe_window:
                recent_ids.append(check_id)
            else:
                stale_ids.append(check_id)

        if str(row.get("operational_state") or "verification_pending") != "normal":
            current_issue_ids.append(check_id)

    monitored_count = len(checks)
    recent_count = len(recent_ids)
    structural_total = int(_number(surface_coverage.get("total_count")))
    status = (
        "verification_pending"
        if never_verified_ids
        else "stale"
        if stale_ids
        else "attention"
        if current_issue_ids
        else "recently_verified"
    )
    return {
        "ok": not never_verified_ids and not stale_ids,
        "schema": "codexstock_bounded_runtime_execution_evidence_v1",
        "status": status,
        "scope": "bounded_health_probes_only",
        "recent_window_seconds": safe_window,
        "monitored_check_count": monitored_count,
        "recent_success_count": recent_count,
        "stale_success_count": len(stale_ids),
        "never_verified_count": len(never_verified_ids),
        "current_issue_count": len(current_issue_ids),
        "recent_success_pct": round(recent_count / monitored_count * 100.0, 2) if monitored_count else 0.0,
        "monitored_endpoint_count": len(monitored_endpoints),
        "monitored_mcp_tool_count": len(monitored_mcp_tools),
        "structural_surface_total_count": structural_total,
        "recent_success_ids": recent_ids,
        "stale_success_ids": stale_ids,
        "never_verified_ids": never_verified_ids,
        "current_issue_ids": current_issue_ids,
        "all_structural_features_runtime_verified": False,
        "claim_boundary": (
            "Static wiring coverage proves that buttons, API routes, and MCP handlers are connected. "
            "This runtime evidence covers only the bounded health probes and does not claim that every "
            "structural feature was recently executed."
        ),
        "audit_only": True,
        "live_order_allowed": False,
    }


