def _start_feature_health_refresh(probe: bool, source: str) -> bool:
    global FEATURE_HEALTH_BOARD_CACHE, FEATURE_HEALTH_REFRESHING, FEATURE_HEALTH_REFRESH_PROBE
    with FEATURE_HEALTH_REFRESH_LOCK:
        if FEATURE_HEALTH_REFRESHING:
            return False
        FEATURE_HEALTH_REFRESHING = True
        FEATURE_HEALTH_REFRESH_PROBE = bool(probe)
        FEATURE_HEALTH_REFRESH_COMPLETE.clear()

    def refresh() -> None:
        global FEATURE_HEALTH_BOARD_CACHE, FEATURE_HEALTH_REFRESHING, FEATURE_HEALTH_REFRESH_PROBE
        try:
            with FEATURE_HEALTH_BUILD_LOCK:
                payload = _build_feature_health_board_uncached(
                    probe=probe,
                    record=True,
                    source=f"{source}-background-refresh",
                )
                FEATURE_HEALTH_BOARD_CACHE = (time.time(), dict(payload))
        finally:
            with FEATURE_HEALTH_REFRESH_LOCK:
                FEATURE_HEALTH_REFRESHING = False
                FEATURE_HEALTH_REFRESH_PROBE = False
                FEATURE_HEALTH_REFRESH_COMPLETE.set()

    threading.Thread(target=refresh, name="feature-health-refresh", daemon=True).start()
    return True


def build_feature_health_board(probe: bool = False, record: bool = False, source: str = "feature-health") -> dict[str, object]:
    global FEATURE_HEALTH_BOARD_CACHE
    if record:
        with FEATURE_HEALTH_REFRESH_LOCK:
            refresh_in_progress = FEATURE_HEALTH_REFRESHING
            refresh_has_required_probe = FEATURE_HEALTH_REFRESH_PROBE or not probe
        if refresh_in_progress:
            refresh_finished = FEATURE_HEALTH_REFRESH_COMPLETE.wait(
                timeout=FEATURE_HEALTH_FORCE_WAIT_SECONDS
            )
            if refresh_finished and refresh_has_required_probe and FEATURE_HEALTH_BOARD_CACHE:
                _, cached_payload = FEATURE_HEALTH_BOARD_CACHE
                if not probe or bool(cached_payload.get("probe")):
                    payload = _ensure_feature_health_lifecycle_payload(dict(cached_payload))
                    payload["coalesced_refresh"] = True
                    payload["cached"] = False
                    payload["refreshing"] = False
                    payload["requested_source"] = source
                    return payload
            if not refresh_finished:
                if FEATURE_HEALTH_BOARD_CACHE:
                    _, cached_payload = FEATURE_HEALTH_BOARD_CACHE
                    payload = _ensure_feature_health_lifecycle_payload(dict(cached_payload))
                else:
                    payload = _feature_health_placeholder(source)
                payload["ok"] = False
                payload["status"] = "degraded"
                payload["force_refresh_timeout"] = True
                payload["force_refresh_wait_seconds"] = FEATURE_HEALTH_FORCE_WAIT_SECONDS
                payload["refreshing"] = True
                payload["requested_source"] = source
                payload["safety"] = (
                    "Read-only force refresh exceeded its time budget; stale results remain visible "
                    "and unverified results remain blocked from scores and orders."
                )
                return payload
        with FEATURE_HEALTH_BUILD_LOCK:
            payload = _build_feature_health_board_uncached(probe=probe, record=True, source=source)
            FEATURE_HEALTH_BOARD_CACHE = (time.time(), dict(payload))
        return payload

    now = time.time()
    cached_at = 0.0
    cached_payload: dict[str, object] | None = None
    if FEATURE_HEALTH_BOARD_CACHE:
        cached_at, cached_payload = FEATURE_HEALTH_BOARD_CACHE
    elif FEATURE_HEALTH_FILE.exists():
        rows = _read_jsonl(FEATURE_HEALTH_FILE, limit=1)
        if rows:
            cached_payload = dict(rows[-1])
            try:
                cached_at = FEATURE_HEALTH_FILE.stat().st_mtime
            except OSError:
                cached_at = now
            FEATURE_HEALTH_BOARD_CACHE = (cached_at, dict(cached_payload))

    cache_age = max(0.0, now - cached_at) if cached_payload is not None else 0.0
    needs_refresh = cached_payload is None or probe or cache_age > FEATURE_HEALTH_CACHE_TTL_SECONDS
    refresh_started = _start_feature_health_refresh(probe=probe, source=source) if needs_refresh else False
    if cached_payload is None:
        payload = _feature_health_placeholder(source)
        payload["refresh_started"] = refresh_started
        return payload

    payload = _ensure_feature_health_lifecycle_payload(dict(cached_payload))
    payload["cached"] = True
    payload["cache_age_seconds"] = round(cache_age, 2)
    payload["cache_ttl_seconds"] = FEATURE_HEALTH_CACHE_TTL_SECONDS
    payload["stale"] = cache_age > FEATURE_HEALTH_CACHE_TTL_SECONDS
    payload["refreshing"] = FEATURE_HEALTH_REFRESHING
    payload["refresh_started"] = refresh_started
    payload["requested_source"] = source
    return payload


def _fast_sqlite_storage_snapshot(max_age_seconds: int = 86400) -> dict[str, object]:
    """Read the last bounded SQLite audit without opening any database."""
    try:
        envelope = json.loads(SQLITE_STORAGE_AUDIT_CACHE_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError, TypeError, ValueError):
        return {}
    if not isinstance(envelope, dict) or envelope.get("schema_version") != "sqlite-storage-audit-cache.v1":
        return {}
    payload = envelope.get("payload") if isinstance(envelope.get("payload"), dict) else {}
    if not payload:
        return {}
    saved_at = float(_number(envelope.get("saved_at_epoch")))
    age_seconds = max(0.0, time.time() - saved_at) if saved_at else float("inf")
    return {
        **dict(payload),
        "cache_scope": envelope.get("scope"),
        "cached": True,
        "cache_age_seconds": round(age_seconds, 2) if math.isfinite(age_seconds) else None,
        "stale": age_seconds > max(1, int(max_age_seconds)),
        "health_probe_mode": "instant_cached_read_only",
    }


def build_system_feature_health_instant() -> dict[str, object]:
    """Return a bounded sidecar diagnostic without running deep overlays.

    The full feature board remains authoritative and refreshes in the
    background. This endpoint only reads its latest immutable snapshot plus
    the persisted SQLite audit, so liveness monitoring cannot compete with
    replay reconciliation or other research workloads.
    """
    global FEATURE_HEALTH_BOARD_CACHE
    now = time.time()
    cached_at = 0.0
    board: dict[str, object] = {}
    cached = FEATURE_HEALTH_BOARD_CACHE
    if isinstance(cached, tuple) and len(cached) == 2 and isinstance(cached[1], dict):
        cached_at = float(cached[0])
        board = dict(cached[1])
    elif FEATURE_HEALTH_FILE.exists():
        rows = _read_jsonl(FEATURE_HEALTH_FILE, limit=1)
        if rows and isinstance(rows[-1], dict):
            board = dict(rows[-1])
            try:
                cached_at = FEATURE_HEALTH_FILE.stat().st_mtime
            except OSError:
                cached_at = now
            FEATURE_HEALTH_BOARD_CACHE = (cached_at, dict(board))

    if not board:
        board = _feature_health_placeholder("system-feature-health-instant")
    cache_age = max(0.0, now - cached_at) if cached_at else 0.0
    stale = not cached_at or cache_age > FEATURE_HEALTH_CACHE_TTL_SECONDS
    refresh_started = (
        _start_feature_health_refresh(probe=False, source="system-feature-health-instant")
        if stale
        else False
    )
    checks = [
        dict(row)
        for row in board.get("checks", [])
        if isinstance(row, dict)
    ]
    sqlite_snapshot = _fast_sqlite_storage_snapshot()
    for row in checks:
        if str(row.get("id") or "") != "sqlite_storage" or not sqlite_snapshot:
            continue
        if sqlite_snapshot.get("stale"):
            sqlite_state = "delayed"
        elif sqlite_snapshot.get("ok"):
            sqlite_state = "normal"
        else:
            sqlite_state = "verification_pending"
        display = _feature_operational_state_display(sqlite_state)
        row.update(
            {
                "status": "alive" if sqlite_state == "normal" else "degraded",
                "operational_state": sqlite_state,
                "operational_state_label": display.get("label"),
                "operational_severity": display.get("severity"),
                "detail": (
                    f"cached_sqlite_ok={bool(sqlite_snapshot.get('ok'))}, "
                    f"problem_sqlite_count={int(_number(sqlite_snapshot.get('problem_sqlite_count')))}, "
                    f"max_query_ms={float(_number(sqlite_snapshot.get('max_query_ms'))):.2f}"
                ),
            }
        )

    operational_counts = _feature_health_operational_counts_from_rows(checks)
    total = len(checks)
    broken_count = operational_counts["broken"]
    warning_count = operational_counts["delayed"] + operational_counts["verification_pending"]
    return {
        "ok": broken_count == 0,
        "schema": "codexstock.system-feature-health-instant.v1",
        "generated_at": board.get("generated_at"),
        "served_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "source": "system-feature-health-instant",
        "cached": True,
        "stale": stale,
        "cache_age_seconds": round(cache_age, 2),
        "refreshing": bool(FEATURE_HEALTH_REFRESHING),
        "refresh_started": refresh_started,
        "total": total,
        "normal_count": operational_counts["normal"],
        "delayed_count": operational_counts["delayed"],
        "verification_pending_count": operational_counts["verification_pending"],
        "operational_broken_count": broken_count,
        "operational_counts": operational_counts,
        "health_line_plain": _feature_health_operational_line(total, operational_counts),
        "surface_runtime_smoke": board.get("surface_runtime_smoke", {}),
        "checks": checks,
        "diagnostic_mode": "cached_snapshot_no_deep_overlay",
        "deep_refresh_deferred": True,
        "audit_only": True,
        "live_order_allowed": False,
        "safety": "Read-only instant sidecar diagnostic. No live order or deep research job is executed.",
    }


def build_system_feature_health(force: bool = False, compact: bool = False, record: bool = False) -> dict[str, object]:
    # Explicit refreshes must return the new probe result rather than the
    # previous cache entry while a background refresh is still running.
    board = build_feature_health_board(
        probe=force,
        record=bool(record or force),
        source="system-feature-health",
    )
    summary = board.get("summary") if isinstance(board.get("summary"), dict) else {}
    counts = summary.get("counts") if isinstance(summary.get("counts"), dict) else {}

    def ui_status(status: object) -> str:
        raw = str(status or "").lower()
        if raw == "alive":
            return "ok"
        if raw == "broken":
            return "fail"
        if raw in {"degraded", "unknown"}:
            return "watch"
        return "wait"

    checks: list[dict[str, object]] = []
    live_progress_overlay_at = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
    for item in board.get("checks", []) if isinstance(board.get("checks"), list) else []:
        if not isinstance(item, dict):
            continue
        metadata = dict(item.get("metadata")) if isinstance(item.get("metadata"), dict) else {}
        detail = str(item.get("detail") or "")
        if str(item.get("id") or "") == "sqlite_storage":
            latest_sqlite = _fast_sqlite_storage_snapshot()
            if not latest_sqlite:
                latest_sqlite = {}
            sqlite_summary = (
                latest_sqlite.get("summary")
                if isinstance(latest_sqlite.get("summary"), dict)
                else {}
            )
            if latest_sqlite:
                if latest_sqlite.get("stale"):
                    sqlite_state = "delayed"
                elif latest_sqlite.get("ok"):
                    sqlite_state = "normal"
                else:
                    sqlite_state = "verification_pending"
                sqlite_display = _feature_operational_state_display(sqlite_state)
                item["operational_state"] = sqlite_state
                item["operational_state_label"] = sqlite_display.get("label")
                item["operational_state_description"] = sqlite_display.get("description")
                item["operational_severity"] = sqlite_display.get("severity")
                item["status_badge"] = sqlite_display.get("badge")
                item["status"] = "alive" if sqlite_state == "normal" else "degraded"
                metadata["live_progress_overlay"] = True
                metadata["live_progress_overlay_at"] = live_progress_overlay_at
                metadata["sqlite_storage_summary"] = sqlite_summary
                metadata["sqlite_overlay_mode"] = "persisted_bounded_snapshot"
                detail = (
                    f"ok={bool(latest_sqlite.get('ok'))}, "
                    f"status={latest_sqlite.get('status') or sqlite_summary.get('status') or 'unknown'}, "
                    f"cached={bool(latest_sqlite.get('cached'))}, "
                    f"sqlite_file_count={int(_number(latest_sqlite.get('sqlite_file_count') or sqlite_summary.get('sqlite_file_count')))}, "
                    f"total_sqlite_mb={float(_number(latest_sqlite.get('total_sqlite_mb') or sqlite_summary.get('total_sqlite_mb'))):.2f}, "
                    f"problem_sqlite_count={int(_number(latest_sqlite.get('problem_sqlite_count') or sqlite_summary.get('problem_sqlite_count')))}, "
                    f"max_query_ms={float(_number(latest_sqlite.get('max_query_ms') or sqlite_summary.get('max_query_ms'))):.2f}"
                )
        if str(item.get("id") or "") == "tournament_reconciliation_audit":
            cached_progress = (
                metadata.get("regeneration_progress")
                if isinstance(metadata.get("regeneration_progress"), dict)
                else {}
            )
            total_candidates = int(_number(cached_progress.get("total_candidate_count")))
            campaign_total, campaign_ids = _historical_replay_campaign_manifest_scope()
            if campaign_total > 0:
                total_candidates = campaign_total
            if total_candidates > 0:
                replay_status = responsive_historical_replay_regeneration_status()
                responsive_progress = (
                    replay_status.get("progress")
                    if isinstance(replay_status.get("progress"), dict)
                    else {}
                )
                current_progress = (
                    dict(responsive_progress)
                    if int(_number(responsive_progress.get("total_candidate_count"))) == total_candidates
                    else dict(cached_progress)
                )
                metadata["regeneration_progress"] = current_progress
                replay_worker = (
                    dict(replay_status.get("worker"))
                    if isinstance(replay_status.get("worker"), dict)
                    else {}
                )
                replay_estimate = (
                    dict(replay_status.get("completion_estimate"))
                    if isinstance(replay_status.get("completion_estimate"), dict)
                    else {}
                )
                metadata["regeneration_worker"] = replay_worker
                metadata["regeneration_estimate"] = replay_estimate
                metadata["live_progress_overlay"] = True
                metadata["live_progress_overlay_at"] = live_progress_overlay_at
                metadata["replay_overlay_mode"] = "responsive_signed_snapshot"
                current_label = str(current_progress.get("label") or "-")
                if re.search(r"replay_recovery=[^,]+", detail):
                    detail = re.sub(r"replay_recovery=[^,]+", f"replay_recovery={current_label}", detail, count=1)
                else:
                    detail = f"{detail}, replay_recovery={current_label}".strip(", ")
                detail += (
                    ", replay_breakdown="
                    f"verified:{int(_number(current_progress.get('verified_count')))},"
                    f"quarantined:{int(_number(current_progress.get('quarantined_count')))},"
                    f"retryable_failed:{int(_number(current_progress.get('retryable_failure_count')))},"
                    f"blocked:{int(_number(current_progress.get('blocked_failure_count')))},"
                    f"unattempted:{int(_number(current_progress.get('unattempted_count')))},"
                    f"accounting_ok:{bool((current_progress.get('accounting') or {}).get('invariant_ok'))}"
                )
                detail += f", replay_worker={replay_worker.get('health_state', 'UNKNOWN')}"
                detail += (
                    ", replay_eta_hours="
                    f"{replay_estimate.get('estimated_hours_remaining')},"
                    "replay_duty_pct="
                    f"{replay_estimate.get('estimated_worker_duty_cycle_pct')},"
                    "replay_throughput_per_hour="
                    f"{replay_estimate.get('estimated_throughput_per_hour')}"
                )
        if str(item.get("id") or "") == "mcp_manifest":
            client_exposure = (
                metadata.get("client_exposure")
                if isinstance(metadata.get("client_exposure"), dict)
                else {}
            )
            exposure_reconciliation = (
                metadata.get("exposure_reconciliation")
                if isinstance(metadata.get("exposure_reconciliation"), dict)
                else {}
            )
            if exposure_reconciliation:
                detail += (
                    ", mcp_full="
                    f"{exposure_reconciliation.get('full_surface_status')},"
                    "mcp_core="
                    f"{exposure_reconciliation.get('core_surface_status')},"
                    "mcp_core_coverage="
                    f"{exposure_reconciliation.get('core_client_tool_count')}/"
                    f"{exposure_reconciliation.get('core_server_tool_count')},"
                    "mcp_next="
                    f"{exposure_reconciliation.get('next_action')}"
                )
            metadata["mcp_client_exposure_summary"] = {
                "full_status": client_exposure.get("status"),
                "full_server_tool_count": client_exposure.get("server_tool_count"),
                "full_client_tool_count": (
                    exposure_reconciliation.get("full_client_tool_count")
                    if exposure_reconciliation.get("full_client_tool_count") is not None
                    else client_exposure.get("client_cached_tool_count")
                ),
                "full_missing_tool_count": client_exposure.get("missing_on_client_count"),
                "core_status": client_exposure.get("core_exposure_status"),
                "core_server_tool_count": client_exposure.get("core_server_tool_count"),
                "core_client_tool_count": client_exposure.get("core_client_exposed_tool_count"),
                "core_missing_tool_count": client_exposure.get("core_missing_on_client_count"),
                "next_action": exposure_reconciliation.get("next_action"),
            }
        severity = str(metadata.get("severity") or "").lower()
        is_warning = severity == "warning"
        domain_attention = bool(metadata.get("domain_attention"))
        operational_state = str(item.get("operational_state") or "verification_pending")
        status = {
            "normal": "ok",
            "delayed": "watch",
            "verification_pending": "watch",
            "broken": "fail",
        }.get(operational_state, ui_status(item.get("status")))
        operational_state_label = str(item.get("operational_state_label") or "검증대기")
        operational_display = _feature_operational_state_display(operational_state)
        operational_state_label = str(operational_display.get("label") or operational_state_label or "검증대기")
        checks.append(
            {
                "id": item.get("id"),
                "label": item.get("label"),
                "category": item.get("category"),
                "status": status,
                "state_label": operational_state_label,
                "underlying_state": str(item.get("status") or status).upper(),
                "operational_state": operational_state,
                "operational_state_label": operational_state_label,
                "operational_state_description": item.get(
                    "operational_state_description",
                    operational_display.get("description", ""),
                ),
                "operational_severity": item.get(
                    "operational_severity",
                    operational_display.get("severity", "pending"),
                ),
                "status_badge": item.get("status_badge", operational_display.get("badge", operational_state_label)),
                "severity": severity,
                "is_warning": is_warning,
                "domain_attention": domain_attention,
                "domain_status": metadata.get("domain_status", ""),
                "domain_attention_label": metadata.get("domain_attention_label", ""),
                "domain_attention_reason": metadata.get("domain_attention_reason", ""),
                "status_reason": metadata.get("status_reason", ""),
                "official_performance_scope": metadata.get("official_performance_scope", ""),
                "regeneration_progress": metadata.get("regeneration_progress", {}),
                "regeneration_worker": metadata.get("regeneration_worker", {}),
                "regeneration_estimate": metadata.get("regeneration_estimate", {}),
                "mcp_client_exposure_summary": metadata.get("mcp_client_exposure_summary", {}),
                "mcp_exposure_reconciliation": metadata.get("exposure_reconciliation", {}),
                "endpoint": item.get("endpoint"),
                "mcp_tool": item.get("mcp_tool"),
                "latency_ms": item.get("latency_ms"),
                "latency_threshold_ms": item.get("latency_threshold_ms"),
                "latency_state": item.get("latency_state", "normal"),
                "last_checked_at": item.get("last_checked_at", ""),
                "last_success_at": item.get("last_success_at", ""),
                "last_success_age_seconds": item.get("last_success_age_seconds"),
                "success_evidence_status": item.get("success_evidence_status", "never_verified"),
                "success_evidence_label": item.get("success_evidence_label", "성공 기록 없음"),
                "last_failure_at": item.get("last_failure_at", ""),
                "last_issue_at": item.get("last_issue_at", ""),
                "last_transition_at": item.get("last_transition_at", ""),
                "detail": detail,
                "next_action": item.get("action") or detail,
                "button_id": metadata.get("button_id", ""),
                "live_progress_overlay": bool(metadata.get("live_progress_overlay")),
                "live_progress_overlay_at": metadata.get("live_progress_overlay_at", ""),
            }
        )
    fail_rows = [row for row in checks if row.get("status") == "fail"]
    watch_rows = [row for row in checks if row.get("status") == "watch"]
    warning_rows = [row for row in checks if row.get("is_warning")]
    domain_attention_rows = [row for row in checks if row.get("domain_attention")]
    total = int(board.get("checked_count") or len(checks))
    liveness_counts = (
        board.get("liveness_counts")
        if isinstance(board.get("liveness_counts"), dict)
        else summary.get("liveness_counts")
        if isinstance(summary.get("liveness_counts"), dict)
        else counts
    )
    alive_count = int(_number(board.get("alive_count") or liveness_counts.get("alive")))
    warning_count = int(summary.get("warning_count", board.get("warning_count", 0)) or 0)
    visible_warning_count = int(summary.get("visible_warning_count", board.get("visible_warning_count", len(watch_rows) + len(warning_rows))) or 0)
    error_count = int(summary.get("error_count", board.get("error_count", len(fail_rows))) or 0)
    attention_count = max(len(watch_rows), int(board.get("attention_count") or 0))
    broken_count = len(fail_rows)
    derived_operational_counts = {
        state: sum(1 for row in checks if row.get("operational_state") == state)
        for state in ("normal", "delayed", "verification_pending", "broken")
    }
    # Live overlays can resolve a stale cached check before the full board refresh
    # finishes, so the visible totals must always be derived from visible rows.
    operational_counts = derived_operational_counts
    normal_count = int(_number(operational_counts.get("normal")))
    delayed_count = int(_number(operational_counts.get("delayed")))
    verification_pending_count = int(_number(operational_counts.get("verification_pending")))
    operational_broken_count = int(_number(operational_counts.get("broken")))
    operational_warning_count = delayed_count + verification_pending_count
    operational_attention_count = operational_warning_count + operational_broken_count
    operational_line = _feature_health_operational_line(total, {
        "normal": normal_count,
        "delayed": delayed_count,
        "verification_pending": verification_pending_count,
        "broken": operational_broken_count,
    })
    attention_count = operational_attention_count
    warning_count = operational_warning_count
    visible_warning_count = operational_warning_count
    broken_count = operational_broken_count
    error_count = operational_broken_count
    score = round(max(0.0, min(100.0, 100.0 - broken_count * 18.0 - attention_count * 7.0 - warning_count * 2.0)), 1)
    overall = "fail" if broken_count else "watch" if operational_warning_count else "ok"
    visible_checks = checks[:12] if compact else checks
    return {
        "ok": broken_count == 0,
        "generated_at": board.get("generated_at"),
        "source": "system-feature-health",
        "cached": bool(board.get("cached")),
        "stale": bool(board.get("stale")),
        "refreshing": bool(board.get("refreshing")),
        "refresh_started": bool(board.get("refresh_started")),
        "cache_age_seconds": board.get("cache_age_seconds"),
        "overall": overall,
        "score": score,
        "total": total,
        "alive_count": alive_count,
        "attention_count": attention_count,
        "warning_count": warning_count,
        "domain_attention_count": len(domain_attention_rows),
        "visible_warning_count": visible_warning_count,
        "error_count": error_count,
        "broken_count": broken_count,
        "normal_count": normal_count,
        "delayed_count": delayed_count,
        "verification_pending_count": verification_pending_count,
        "operational_broken_count": operational_broken_count,
        "operational_counts": {
            "normal": normal_count,
            "delayed": delayed_count,
            "verification_pending": verification_pending_count,
            "broken": operational_broken_count,
        },
        "surface_coverage": board.get("surface_coverage", {}),
        "surface_runtime_smoke": board.get("surface_runtime_smoke", {}),
        "runtime_execution_evidence": board.get("runtime_execution_evidence", {}),
        "external_engine_health": board.get("external_engine_health", {}),
        "checks": visible_checks,
        "failing_buttons": fail_rows[:8],
        "attention_buttons": watch_rows[:8],
        "warning_buttons": warning_rows[:8],
        "domain_attention_buttons": domain_attention_rows[:8],
        "warning_actions": board.get("warning_actions", []),
        "warning_ids": board.get("warning_ids", []),
        "error_ids": board.get("error_ids", []),
        "health_line_plain": operational_line,
        "operational_summary": operational_line,
        "liveness_summary": (
            f"응답 생존 {alive_count}/{total} · 응답 저하 "
            f"{int(_number(board.get('liveness_degraded_count')))} · 응답 실패 "
            f"{int(_number(board.get('liveness_broken_count')))}"
        ),
        "recommended_actions": board.get("recommended_actions", []),
        "agent_feature_health": board if not compact else {
            "summary": summary,
            "surface_coverage": board.get("surface_coverage", {}),
            "surface_runtime_smoke": board.get("surface_runtime_smoke", {}),
            "runtime_execution_evidence": board.get("runtime_execution_evidence", {}),
            "external_engine_health": board.get("external_engine_health", {}),
            "recommended_actions": board.get("recommended_actions", []),
            "warning_actions": board.get("warning_actions", []),
            "warning_ids": board.get("warning_ids", []),
            "error_ids": board.get("error_ids", []),
            "health_line_plain": operational_line,
            "operational_summary": operational_line,
        },
        "audit_only": True,
        "live_order_allowed": False,
        "safety": board.get("safety") or "Read-only feature health board. No live order is submitted.",
    }


def build_ai_health_report(queue_telegram: bool = False, source: str = "health-report") -> dict[str, object]:
    health = build_autopilot_health()
    summary = health.get("summary", {}) if isinstance(health.get("summary"), dict) else {}
    checks = [item for item in health.get("checks", []) if isinstance(item, dict)]
    memory = MEMORY.summary()
    market_clock = build_market_session_clock()
    telegram_poller = TELEGRAM_POLLER.status()
    telegram_dispatcher = TELEGRAM_DISPATCHER.status()
    generated_at = datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds")
    top_candidates = [
        item for item in list(memory.get("top_candidates", []))[:5]
        if isinstance(item, dict)
    ]
    problem_checks = [item for item in checks if str(item.get("status")) in {"warning", "critical", "idle"}]
    if not problem_checks:
        problem_checks = checks[:3]
    telegram_lines = [
        "[코덱스스톡 AI 건강보고]",
        f"생성: {generated_at}",
        f"종합상태: {summary.get('overall', '-')}",
        f"실전주문: {summary.get('real_execution', 'BLOCKED')}",
        f"시세: {summary.get('quote_symbol', '-')} {float(summary.get('quote_price', 0) or 0):,.0f} / {summary.get('quote_source', '-')}",
        f"텔레그램: 명령 {'ON' if summary.get('telegram_poller_running') else 'OFF'} / 자동보고 {'ON' if summary.get('telegram_dispatcher_running') else 'OFF'}",
        f"보고대기: 최근 {summary.get('recent_reports', 0)}건 / 전체 {summary.get('pending_reports', 0)}건",
        f"장기기억: 사이클 {memory.get('cycle_count', 0)}개 / 리허설 {memory.get('paper_rehearsal_memory_count', 0)}개",
        "",
        "핵심 점검:",
    ]
    for item in problem_checks[:6]:
        telegram_lines.append(f"- {item.get('label', '-')}: {item.get('status', '-')} / {item.get('detail', '-')}")
    if top_candidates:
        telegram_lines += ["", "상위 기억 후보:"]
        for item in top_candidates[:3]:
            telegram_lines.append(f"- {item.get('symbol', '-')} {item.get('name', '')}: 점수 {item.get('score', '-')}")
    telegram_lines += ["", "주문 전송 없음. 이 보고서는 감시/복기용입니다."]
    telegram_text = "\n".join(telegram_lines)

    lines = [
        "# 코덱스스톡 AI 건강보고",
        "",
        f"- 생성: {generated_at}",
        f"- 종합상태: {summary.get('overall', '-')}",
        f"- 실전주문: {summary.get('real_execution', 'BLOCKED')}",
        f"- 주 시장: {market_clock.get('primary_market', '-')}",
        f"- 시세: {summary.get('quote_symbol', '-')} {float(summary.get('quote_price', 0) or 0):,.0f} / {summary.get('quote_source', '-')}",
        f"- 텔레그램 명령감시: {'ON' if summary.get('telegram_poller_running') else 'OFF'}",
        f"- 텔레그램 자동보고: {'ON' if summary.get('telegram_dispatcher_running') else 'OFF'}",
        f"- 보고대기: 최근 {summary.get('recent_reports', 0)}건 / 전체 {summary.get('pending_reports', 0)}건",
        f"- 장기기억: 연구 사이클 {memory.get('cycle_count', 0)}개 / 리허설 기억 {memory.get('paper_rehearsal_memory_count', 0)}개",
        "",
        "## 점검 항목",
    ]
    for item in checks:
        lines.append(f"- {item.get('label', '-')}: {item.get('status', '-')} / {item.get('detail', '-')}")
        if item.get("action"):
            lines.append(f"  - 권장 조치: {item.get('action')}")
    lines += ["", "## 텔레그램"]
    lines.append(f"- 명령감시: running={telegram_poller.get('running')} thread={telegram_poller.get('thread_alive')} ready={telegram_poller.get('ready')}")
    lines.append(f"- 자동보고: running={telegram_dispatcher.get('running')} thread={telegram_dispatcher.get('thread_alive')} recent={telegram_dispatcher.get('eligible_recent')} pending={telegram_dispatcher.get('pending_total')}")
    lines += ["", "## 상위 기억 후보"]
    if top_candidates:
        for item in top_candidates:
            lines.append(f"- {item.get('symbol', '-')} {item.get('name', '')}: 점수 {item.get('score', '-')} / 게이트 {item.get('risk_gate_status', '-')}")
    else:
        lines.append("- 아직 장기기억 후보가 없습니다.")
    lines += ["", "실전 주문은 계속 BLOCKED입니다. 이 보고서는 자동 감시와 복기용입니다."]

    note_dir = OBSIDIAN_VAULT / "Health"
    note_dir.mkdir(parents=True, exist_ok=True)
    safe_stamp = datetime.now(_zone("Asia/Seoul", 9)).strftime("%Y%m%d-%H%M%S")
    note_path = note_dir / f"health-{safe_stamp}.md"
    note_text = "\n".join(lines).rstrip() + "\n"
    note_path.write_text(note_text, encoding="utf-8")
    latest_path = note_dir / "latest.md"
    latest_path.write_text(note_text, encoding="utf-8")

    record = None
    if queue_telegram:
        record = OPS.queue_telegram(
            telegram_text,
            message_type="health_report",
            source=source,
            metadata={"overall": summary.get("overall"), "note_path": str(note_path)},
        )
    JOURNAL.add(
        "AI_HEALTH_REPORT",
        f"AI 건강보고 생성: {summary.get('overall', '-')}",
        {"note_path": str(note_path), "telegram_record": record.get("id") if isinstance(record, dict) else None},
    )
    return {
        "ok": True,
        "generated_at": generated_at,
        "health": health,
        "summary": summary,
        "telegram_text": telegram_text,
        "telegram_record": record,
        "note_path": str(note_path),
        "latest_path": str(latest_path),
        "queued": bool(record and record.get("queued", True)),
        "message": "AI 건강보고를 Obsidian에 기록했습니다." + (" 텔레그램 outbox에도 등록했습니다." if queue_telegram else ""),
    }


def ai_health_snapshots(limit: int = 20) -> list[dict[str, object]]:
    return list(reversed(_read_jsonl(HEALTH_SNAPSHOT_FILE, limit=limit)))


def _health_signature(health: dict[str, object]) -> dict[str, object]:
    summary = health.get("summary", {}) if isinstance(health.get("summary"), dict) else {}
    checks = [item for item in health.get("checks", []) if isinstance(item, dict)]
    problem_checks = [
        {
            "id": str(item.get("id", "")),
            "status": str(item.get("status", "")),
        }
        for item in checks
        if str(item.get("status", "")) in {"warning", "critical", "idle"}
    ]
    watch_checks = [
        "scheduler",
        "last_error",
        "telegram_queue",
        "telegram_command_poller",
        "telegram_auto_dispatcher",
        "live_quote",
        "long_memory",
        "real_lock",
    ]
    status_map = {
        str(item.get("id", "")): str(item.get("status", ""))
        for item in checks
        if str(item.get("id", "")) in watch_checks
    }
    payload = {
        "overall": str(summary.get("overall", "")),
        "quote_source": str(summary.get("quote_source", "")),
        "telegram_poller": bool(summary.get("telegram_poller_running")),
        "telegram_dispatcher": bool(summary.get("telegram_dispatcher_running")),
        "problem_checks": sorted(problem_checks, key=lambda item: item["id"]),
        "status_map": status_map,
    }
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    return {"hash": hashlib.sha1(raw.encode("utf-8")).hexdigest()[:16], "payload": payload}


def record_ai_health_snapshot(source: str = "health-monitor", queue_on_change: bool = False) -> dict[str, object]:
    health = build_autopilot_health()
    summary = health.get("summary", {}) if isinstance(health.get("summary"), dict) else {}
    checks = [item for item in health.get("checks", []) if isinstance(item, dict)]
    signature = _health_signature(health)
    previous = ai_health_snapshots(limit=1)
    previous_row = previous[0] if previous else None
    changed = bool(previous_row and previous_row.get("signature") != signature["hash"])
    changed_from = previous_row.get("overall") if isinstance(previous_row, dict) else None
    record = {
        "id": f"AHS-{int(time.time() * 1000)}",
        "created_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "source": source,
        "overall": summary.get("overall", "-"),
        "signature": signature["hash"],
        "signature_payload": signature["payload"],
        "changed": changed,
        "changed_from": changed_from,
        "quote_symbol": summary.get("quote_symbol"),
        "quote_price": summary.get("quote_price"),
        "quote_source": summary.get("quote_source"),
        "telegram_poller_running": summary.get("telegram_poller_running"),
        "telegram_dispatcher_running": summary.get("telegram_dispatcher_running"),
        "recent_reports": summary.get("recent_reports"),
        "pending_reports": summary.get("pending_reports"),
        "memory_cycles": summary.get("memory_cycles"),
        "problem_checks": [
            {
                "id": item.get("id"),
                "label": item.get("label"),
                "status": item.get("status"),
                "detail": item.get("detail"),
            }
            for item in checks
            if str(item.get("status", "")) in {"warning", "critical", "idle"}
        ],
    }
    report: dict[str, object] | None = None
    health_auto_report_enabled = bool(OPS.telegram_policy().get("health_auto_report_enabled", False))
    if queue_on_change and health_auto_report_enabled and changed:
        report = build_ai_health_report(queue_telegram=True, source=f"{source}-change")
        record["health_report_id"] = (report.get("telegram_record") or {}).get("id") if isinstance(report.get("telegram_record"), dict) else None
        record["health_report_note"] = report.get("note_path")
        record["health_report_queued"] = bool(report.get("queued", True))
    elif changed:
        record["health_report_id"] = None
        record["health_report_queued"] = False
        record["health_report_reason"] = "health_auto_report_disabled"
    _append_jsonl(HEALTH_SNAPSHOT_FILE, record)
    JOURNAL.add(
        "AI_HEALTH_SNAPSHOT",
        f"AI 건강 스냅샷: {record['overall']} / changed={changed}",
        {"id": record["id"], "signature": record["signature"], "report": record.get("health_report_id")},
    )
    return {
        "ok": True,
        "recorded": True,
        "changed": changed,
        "previous": previous_row,
        "record": record,
        "report": report,
        "path": str(HEALTH_SNAPSHOT_FILE),
        "message": "건강상태 변화가 감지되어 보고를 큐에 넣었습니다." if changed and report else "건강상태 변화 없음. 스냅샷만 기록했습니다." if previous_row else "건강상태 기준선을 기록했습니다.",
    }


def _latest_for_symbol(rows: list[dict[str, object]], symbol: str, mode: str | None = None) -> dict[str, object] | None:
    normalized = symbol.upper()
    for row in reversed(rows):
        ticket = row.get("ticket") if isinstance(row.get("ticket"), dict) else row
        if str(ticket.get("symbol", "")).upper() != normalized:
            continue
        if mode and str(ticket.get("mode", "")) != mode:
            continue
        return row
    return None


def _pipeline_stage(stage_id: str, label: str, state: str, detail: str) -> dict[str, object]:
    return {"id": stage_id, "label": label, "state": state, "detail": detail}


def build_ai_pipeline() -> dict[str, object]:
    memory = MEMORY.summary()
    screener = build_ai_screener(force=False)
    screener_rows = {
        str(item.get("symbol", "")).upper(): item
        for item in screener.get("candidates", [])
        if isinstance(item, dict) and item.get("symbol")
    }
    tickets = OPS.tickets()
    approvals = OPS.approvals()
    dry_submits = OPS.live_dry_submits()
    candidates: list[dict[str, object]] = []
    seen: set[str] = set()
    for source_item in list(memory.get("top_candidates", [])) + list(screener.get("candidates", [])):
        if not isinstance(source_item, dict):
            continue
        symbol = str(source_item.get("symbol", "")).upper()
        if not symbol or symbol in seen:
            continue
        seen.add(symbol)
        candidates.append(source_item)
        if len(candidates) >= 10:
            break

    rows = []
    for item in candidates:
        symbol = str(item.get("symbol", "")).upper()
        enriched = dict(item)
        enriched.update({key: value for key, value in screener_rows.get(symbol, {}).items() if value not in (None, "")})
        score_fields = _candidate_score_view_fields(enriched)
        enriched.update(score_fields)
        score = float(score_fields.get("score", 0) or 0)
        gate = str(enriched.get("risk_gate_status") or enriched.get("gate") or "-")
        paper_ticket = _latest_for_symbol(tickets, symbol, mode="paper")
        live_ticket = _latest_for_symbol(tickets, symbol, mode="live_candidate")
        approval = _latest_for_symbol(approvals, symbol)
        dry_submit = _latest_for_symbol(dry_submits, symbol)
        market_signal = enriched.get("market_signal") if isinstance(enriched.get("market_signal"), dict) else {}
        signal = market_signal.get("signal") if isinstance(market_signal.get("signal"), dict) else {}
        signal_label = str(signal.get("label") or enriched.get("market_signal_label") or "-")
        intelligence_done = bool(enriched.get("financial_stance") or enriched.get("news_stance") or enriched.get("reasons") or market_signal)
        gate_state = "done" if gate == "PASSED" else "review" if gate == "REVIEW" else "blocked" if gate == "BLOCKED" else "active"
        paper_state = "done" if paper_ticket else "active" if gate == "PASSED" else "wait"
        approval_state = "wait"
        approval_detail = "실전 후보 생성 전"
        if dry_submit:
            approval_state = "done"
            approval_detail = str(dry_submit.get("status", "dry-run 완료"))
        elif approval:
            approval_status = str(approval.get("status", "-"))
            approval_state = "active" if approval_status == "pending" else "review" if approval_status == "approved" else "blocked"
            approval_detail = f"승인 {approval_status}"
        elif live_ticket:
            approval_state = "active"
            approval_detail = str(live_ticket.get("status", "실전 후보"))

        stages = [
            _pipeline_stage("discover", "후보 발굴", "done", f"점수 {round(score, 2)}"),
            _pipeline_stage("public_quote", "공개시세", "done" if market_signal.get("ok") else "wait", signal_label),
            _pipeline_stage("intelligence", "뉴스/재무", "done" if intelligence_done else "active", enriched.get("financial_stance") or enriched.get("news_stance") or "레이더 확인 필요"),
            _pipeline_stage("backtest_gate", "백테스트 게이트", gate_state, gate),
            _pipeline_stage("paper", "Paper 리허설", paper_state, str((paper_ticket or {}).get("status", "리허설 대기"))),
            _pipeline_stage("approval", "승인/Dry-run", approval_state, approval_detail),
            _pipeline_stage("review", "복기/기억", "done" if paper_ticket or dry_submit else "wait", "장기기억 후보 카드 유지"),
        ]
        done_score = sum(1.0 if stage["state"] == "done" else 0.5 if stage["state"] in {"active", "review"} else 0.0 for stage in stages)
        progress = round(done_score / len(stages) * 100, 1)
        if gate != "PASSED":
            next_action = "전략 조건을 다시 백테스트하고 위험 게이트 실패 원인을 복기"
            lane = "검토"
        elif not paper_ticket:
            next_action = "상위 후보를 paper 리허설 장부에 올려 실제 주문 없이 추적"
            lane = "리허설 대기"
        elif not live_ticket:
            next_action = "paper 손익과 뉴스/공시 변화를 관찰하고 필요하면 실전 후보로 승격"
            lane = "관찰"
        elif approval and approval.get("status") == "pending":
            next_action = "승인 토큰을 검토하되 실제 주문은 계속 잠금"
            lane = "승인 대기"
        elif approval and approval.get("status") == "approved" and not dry_submit:
            next_action = "dry-submit으로 중복/한도/승인 상태만 검증"
            lane = "Dry-run 대기"
        else:
            next_action = "dry-run 결과를 복기하고 다음 사이클 점수 변화와 비교"
            lane = "복기"
        rows.append(
            {
                "symbol": symbol,
                "name": enriched.get("name", symbol),
                "market": enriched.get("market", "KR" if symbol.isdigit() else "US"),
                **score_fields,
                "gate": gate,
                "progress": progress,
                "lane": lane,
                "next_action": next_action,
                "return_pct": enriched.get("return_pct"),
                "robustness_score": enriched.get("robustness_score"),
                "market_signal_label": signal_label,
                "market_signal_score_delta": enriched.get("market_signal_score_delta"),
                "paper_ticket_id": (paper_ticket or {}).get("id"),
                "approval_token": (approval or {}).get("token") or (live_ticket or {}).get("approval_token"),
                "dry_submit_status": (dry_submit or {}).get("status"),
                "stages": stages,
            }
        )
    rows.sort(key=lambda row: (float(row.get("progress", 0)), float(row.get("score", 0))), reverse=True)
    return {
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "market_clock": build_market_session_clock(),
        "summary": {
            "count": len(rows),
            "paper_ready": len([row for row in rows if row.get("lane") == "리허설 대기"]),
            "observing": len([row for row in rows if row.get("lane") == "관찰"]),
            "dry_run_ready": len([row for row in rows if "Dry-run" in str(row.get("lane"))]),
            "blocked": len([row for row in rows if row.get("lane") == "검토"]),
            "real_execution": "BLOCKED",
        },
        "lanes": ["검토", "리허설 대기", "관찰", "승인 대기", "Dry-run 대기", "복기"],
        "candidates": rows,
        "safety": "파이프라인은 연구/리허설/검증 상태판입니다. 실제 주문은 여전히 BLOCKED입니다.",
    }


def _alert(priority: str, category: str, title: str, message: str, action: str, symbol: str = "", data: dict[str, object] | None = None) -> dict[str, object]:
    priority_rank = {"critical": 0, "warning": 1, "opportunity": 2, "info": 3}
    return {
        "id": f"{priority}-{category}-{symbol or title}".lower().replace(" ", "-")[:80],
        "priority": priority,
        "rank": priority_rank.get(priority, 9),
        "category": category,
        "title": title,
        "message": message,
        "action": action,
        "symbol": symbol,
        "data": data or {},
    }


def build_ai_alert_center() -> dict[str, object]:
    clock = build_market_session_clock()
    pipeline = build_ai_pipeline()
    rehearsal_digest = _promotion_rehearsal_digest(limit=20)
    rehearsal_trend = _promotion_rehearsal_snapshot_trend(limit=20)
    ops_status = OPS.status(marks={})
    paper = ops_status.get("paper", {}) if isinstance(ops_status.get("paper"), dict) else {}
    approvals = ops_status.get("approvals", {}) if isinstance(ops_status.get("approvals"), dict) else {}
    outbox = ops_status.get("telegram_outbox", {}) if isinstance(ops_status.get("telegram_outbox"), dict) else {}
    duplicate = ops_status.get("duplicate_guard", {}) if isinstance(ops_status.get("duplicate_guard"), dict) else {}
    alerts: list[dict[str, object]] = []
    rehearsal_severity = rehearsal_digest.get("by_severity", {}) if isinstance(rehearsal_digest.get("by_severity"), dict) else {}
    rehearsal_warning_count = int(rehearsal_severity.get("warning", 0) or 0) + int(rehearsal_severity.get("danger", 0) or 0)
    rehearsal_count = int(rehearsal_digest.get("count", 0) or 0)
    rehearsal_avg_pct = _number(rehearsal_digest.get("avg_pnl_pct"))

    primary_market = str(clock.get("primary_market", "-"))
    primary_focus = str(clock.get("primary_focus", "-"))
    alerts.append(
        _alert(
            "info",
            "market",
            f"현재 주시 시장: {primary_market}",
            primary_focus,
            "시장 시계 기준으로 AI 작업 우선순위를 유지합니다.",
            data={"market_clock": clock},
        )
    )
    for session in clock.get("sessions", []):
        if not isinstance(session, dict):
            continue
        minutes = int(session.get("minutes_to_next", 9999) or 9999)
        phase = str(session.get("phase", "closed"))
        if phase == "regular":
            alerts.append(
                _alert(
                    "opportunity",
                    "market",
                    f"{session.get('name')} 정규장 감시 중",
                    str(session.get("ai_focus", "")),
                    "거래대금/상대강도 후보를 파이프라인과 비교합니다.",
                    data={"session": session},
                )
            )
        elif minutes <= 60:
            alerts.append(
                _alert(
                    "warning",
                    "market",
                    f"{session.get('name')} 다음 이벤트 임박",
                    f"{session.get('next_event')}까지 {minutes}분 남았습니다.",
                    "장전/장마감 루틴을 준비합니다.",
                    data={"session": session},
                )
            )

    pending = int(approvals.get("pending", 0) or 0)
    if pending:
        alerts.append(
            _alert(
                "warning",
                "approval",
                f"승인 대기 {pending}건",
                "실전 후보 승인 토큰이 대기 중입니다. 실제 주문은 여전히 BLOCKED입니다.",
                "후보의 뉴스/재무/백테스트 근거를 확인한 뒤 승인 또는 거절하세요.",
            )
        )
    queued = int(outbox.get("queued", 0) or 0)
    if queued:
        alerts.append(
            _alert(
                "info",
                "telegram",
                f"텔레그램 outbox {queued}건",
                "보고 대기 메시지가 쌓여 있습니다.",
                "운영보고 큐 또는 텔레그램 전송 설정을 확인하세요.",
            )
        )
    fingerprints = int(duplicate.get("fingerprints", 0) or 0)
    if fingerprints:
        alerts.append(
            _alert(
                "info",
                "risk",
                f"중복 주문 가드 {fingerprints}개 기록",
                "dry-run 중복 fingerprint가 관리되고 있습니다.",
                "같은 종목/수량/가격 반복 후보가 차단되는지 확인합니다.",
            )
        )

    if rehearsal_count:
        winners = rehearsal_digest.get("winners") if isinstance(rehearsal_digest.get("winners"), list) else []
        risks = rehearsal_digest.get("risks") if isinstance(rehearsal_digest.get("risks"), list) else []
        top = winners[0] if winners and isinstance(winners[0], dict) else {}
        weak = risks[0] if risks and isinstance(risks[0], dict) else {}
        top_mark = top.get("mark") if isinstance(top.get("mark"), dict) else {}
        weak_mark = weak.get("mark") if isinstance(weak.get("mark"), dict) else {}
        if rehearsal_warning_count:
            alerts.append(
                _alert(
                    "warning",
                    "paper-rehearsal",
                    f"Paper 리허설 경고 {rehearsal_warning_count}건",
                    f"평균 손익률 {rehearsal_avg_pct:+.2f}%, 약세 후보 {weak.get('symbol', '-')} {_number(weak_mark.get('pnl_pct')):+.2f}%입니다.",
                    "리허설 타임라인에서 위험 후보를 우선 복기하고 종합 요약 보고를 큐에 넣습니다.",
                    symbol=str(weak.get("symbol", "")),
                    data={"digest": rehearsal_digest},
                )
            )
        elif rehearsal_avg_pct >= 2:
            alerts.append(
                _alert(
                    "opportunity",
                    "paper-rehearsal",
                    "Paper 리허설 성과 확인",
                    f"리허설 {rehearsal_count}건 평균 {rehearsal_avg_pct:+.2f}%, 상위 후보 {top.get('symbol', '-')} {_number(top_mark.get('pnl_pct')):+.2f}%입니다.",
                    "성과 원인을 복기하고 같은 전략 조건의 워크포워드 검증을 유지합니다.",
                    symbol=str(top.get("symbol", "")),
                    data={"digest": rehearsal_digest},
                )
            )
        else:
            alerts.append(
                _alert(
                    "info",
                    "paper-rehearsal",
                    f"Paper 리허설 {rehearsal_count}건 관찰 중",
                    f"평균 손익률 {rehearsal_avg_pct:+.2f}%, 실전 주문은 BLOCKED입니다.",
                    "다음 자동 점검까지 paper 복기 상태를 유지합니다.",
                    data={"digest": rehearsal_digest},
                )
            )
        trend_state = str(rehearsal_trend.get("state", "empty"))
        if trend_state in {"worse", "better", "stable", "baseline"}:
            priority = "warning" if trend_state == "worse" else "opportunity" if trend_state == "better" else "info"
            alerts.append(
                _alert(
                    priority,
                    "paper-rehearsal-trend",
                    f"리허설 변화: {rehearsal_trend.get('label', '-')}",
                    str(rehearsal_trend.get("message", "")),
                    "스냅샷 변화와 후보별 손익 변화량을 복기합니다.",
                    data={"trend": rehearsal_trend},
                )
            )
    else:
        alerts.append(
            _alert(
                "info",
                "paper-rehearsal",
                "Paper 리허설 이력 대기",
                "아직 전략 승급 후보가 paper 리허설로 넘어간 기록이 없습니다.",
                "PAPER_READY 후보를 리허설 티켓으로 올려 추적을 시작합니다.",
            )
        )

    for row in pipeline.get("candidates", [])[:10]:
        if not isinstance(row, dict):
            continue
        symbol = str(row.get("symbol", ""))
        lane = str(row.get("lane", ""))
        score = row.get("score", "-")
        progress = row.get("progress", "-")
        if lane == "리허설 대기":
            alerts.append(
                _alert(
                    "opportunity",
                    "pipeline",
                    f"{symbol} paper 리허설 후보",
                    f"점수 {score}, 진행률 {progress}%, 백테스트 게이트 통과 후 paper 대기입니다.",
                    "실제 주문 없이 paper 티켓으로 올려 추적합니다.",
                    symbol=symbol,
                    data=row,
                )
            )
        elif lane == "승인 대기":
            alerts.append(
                _alert(
                    "warning",
                    "pipeline",
                    f"{symbol} 승인 대기",
                    "실전 후보 승인 토큰이 생성되어 있습니다.",
                    "승인 근거와 리스크를 확인하세요. 실제 주문은 BLOCKED입니다.",
                    symbol=symbol,
                    data=row,
                )
            )
        elif lane == "Dry-run 대기":
            alerts.append(
                _alert(
                    "warning",
                    "pipeline",
                    f"{symbol} dry-run 대기",
                    "승인은 되었지만 dry-submit 검증이 아직 남았습니다.",
                    "중복/한도/승인 상태만 검증하고 브로커 주문은 보내지 않습니다.",
                    symbol=symbol,
                    data=row,
                )
            )
        elif lane == "검토":
            alerts.append(
                _alert(
                    "info",
                    "pipeline",
                    f"{symbol} 게이트 재검토",
                    "위험 게이트 또는 데이터 조건을 다시 봐야 합니다.",
                    "전략 조건과 기간을 바꿔 재백테스트합니다.",
                    symbol=symbol,
                    data=row,
                )
            )

    for position in paper.get("positions", []) if isinstance(paper.get("positions"), list) else []:
        if not isinstance(position, dict):
            continue
        pnl = float(position.get("unrealized_pct", 0) or 0)
        symbol = str(position.get("symbol", ""))
        if pnl <= -3:
            alerts.append(
                _alert("warning", "paper", f"{symbol} paper 손실 점검", f"미실현 손익 {pnl}%입니다.", "뉴스/공시 변화와 손절 기준을 복기합니다.", symbol=symbol, data=position)
            )
        elif pnl >= 3:
            alerts.append(
                _alert("opportunity", "paper", f"{symbol} paper 성과 확인", f"미실현 손익 {pnl}%입니다.", "성과 원인을 복기하고 전략 조건 재현성을 확인합니다.", symbol=symbol, data=position)
            )

    alerts.append(
        _alert(
            "info",
            "safety",
            "실전 주문 잠금 유지",
            "현재 시스템은 후보, paper, 승인, dry-run까지만 허용합니다.",
            "충분한 paper 기록과 명시적 사용자 정책 전까지 broker live submit은 열지 않습니다.",
        )
    )
    alerts.sort(key=lambda item: (int(item.get("rank", 9)), str(item.get("title", ""))))
    top_alerts = alerts[:16]
    summary = {
        "total": len(top_alerts),
        "critical": len([item for item in top_alerts if item.get("priority") == "critical"]),
        "warning": len([item for item in top_alerts if item.get("priority") == "warning"]),
        "opportunity": len([item for item in top_alerts if item.get("priority") == "opportunity"]),
        "info": len([item for item in top_alerts if item.get("priority") == "info"]),
        "paper_rehearsal_count": rehearsal_count,
        "paper_rehearsal_warning": rehearsal_warning_count,
        "paper_rehearsal_avg_pnl_pct": rehearsal_avg_pct,
        "paper_rehearsal_trend": rehearsal_trend.get("label"),
        "real_execution": "BLOCKED",
    }
    telegram_lines = ["[AI 알림 센터 요약]", f"생성: {datetime.now().isoformat(timespec='seconds')}", f"실전 주문: {summary['real_execution']}", ""]
    for item in top_alerts[:8]:
        telegram_lines.append(f"- {item.get('priority')} / {item.get('title')}: {item.get('message')}")
    return {
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "summary": summary,
        "alerts": top_alerts,
        "recommended_commands": ["운영상태", "후보 발굴", "연구 한번", "dry-submit"],
        "telegram_text": "\n".join(telegram_lines),
        "safety": "알림은 의사결정 보조입니다. 실제 주문은 여전히 BLOCKED입니다.",
    }


def build_telegram_dispatch_center() -> dict[str, object]:
    status = INTEGRATIONS.status().get("telegram", {})
    pending = OPS.pending_telegram_outbox(limit=50)
    all_dispatches = OPS.telegram_dispatches()
    dispatches = list(reversed(all_dispatches[-20:]))
    policy = OPS.telegram_policy()
    policy_stats = OPS.telegram_policy_stats(limit=200)
    by_type: dict[str, int] = {}
    for row in pending:
        message_type = str(row.get("message_type", "manual"))
        by_type[message_type] = by_type.get(message_type, 0) + 1
    soft_limits = policy.get("pending_soft_limit_by_type", {})
    soft_overflows = []
    if isinstance(soft_limits, dict):
        for message_type, count in by_type.items():
            limit = int(soft_limits.get(message_type, 0) or 0)
            if limit > 0 and count > limit:
                soft_overflows.append({"message_type": message_type, "count": count, "limit": limit})
    return {
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "telegram_status": status,
        "summary": {
            "pending": len(pending),
            "dispatch_count": len(all_dispatches),
            "sent": len([row for row in all_dispatches if row.get("sent")]),
            "dry_run": len([row for row in all_dispatches if row.get("status") == "dry_run"]),
            "failed": len([row for row in all_dispatches if row.get("status") in {"failed", "failed_terminal"}]),
            "failed_terminal": len([row for row in all_dispatches if row.get("status") == "failed_terminal"]),
            "single_delivery_claims": len([row for row in all_dispatches if row.get("status") == "claimed_once"]),
            "integrity_fallbacks": len(
                [
                    row
                    for row in all_dispatches
                    if isinstance(row.get("result"), dict)
                    and bool(row["result"].get("used_integrity_fallback"))
                ]
            ),
            "by_type": by_type,
            "policy_skips": policy_stats.get("recent_skips", 0),
            "soft_overflows": soft_overflows,
        },
        "pending": pending[:12],
        "dispatch_recent": dispatches,
        "policy": {
            "enabled": bool(policy.get("enabled", True)),
            "dedupe_enabled": bool(policy.get("dedupe_enabled", True)),
            "dedupe_window_minutes": policy.get("dedupe_window_minutes", 20),
            "rate_limit_enabled": bool(policy.get("rate_limit_enabled", True)),
            "min_interval_minutes_by_type": policy.get("min_interval_minutes_by_type", {}),
            "pending_soft_limit_by_type": policy.get("pending_soft_limit_by_type", {}),
            "manual_dispatch_limit": policy.get("manual_dispatch_limit", 3),
            "auto_dispatch": bool(policy.get("auto_dispatch", False)),
            "safety": policy.get("safety", ""),
        },
        "policy_stats": policy_stats,
        "dispatcher": TELEGRAM_DISPATCHER.status(),
        "delivery_guarantee": {
            "queue_dedupe": "atomic_in_process",
            "dispatcher": "single_flight",
            "incident_delivery": "at_most_once_attempt",
            "encoding": "utf8_json_with_integrity_fallback",
        },
        "safety": "보고 발송 센터는 텔레그램 메시지만 처리합니다. 주식 주문과 무관하며 실전 주문은 BLOCKED입니다.",
    }


def _dispatch_telegram_outbox_legacy(limit: int = 3, source: str = "telegram-dispatcher", max_age_minutes: int | None = None) -> dict[str, object]:
    pending = OPS.pending_telegram_outbox(limit=max(1, min(limit, 10)))
    skipped_stale = 0
    if max_age_minutes is not None:
        all_pending = OPS.pending_telegram_outbox(limit=100)
        recent = []
        for row in all_pending:
            age = _iso_age_seconds(row.get("created_at"))
            if age is not None and age <= max_age_minutes * 60:
                recent.append(row)
            else:
                skipped_stale += 1
        pending = recent[: max(1, min(limit, 10))]
    dispatches = []
    for row in pending:
        result = INTEGRATIONS.telegram_send(str(row.get("text", "")))
        dispatches.append(OPS.record_telegram_dispatch(row, result, source=source))
    return {
        "ok": True,
        "processed": len(dispatches),
        "skipped_stale": skipped_stale,
        "message": f"{len(dispatches)}건 처리" + (f", 오래된 보고 {skipped_stale}건은 자동발송 제외" if skipped_stale else ""),
        "dispatches": dispatches,
        "center": build_telegram_dispatch_center(),
    }


def dispatch_telegram_outbox(limit: int = 3, source: str = "telegram-dispatcher", max_age_minutes: int | None = None) -> dict[str, object]:
    """Dispatch Telegram reports with one sender and at-most-once incident claims."""
    if not TELEGRAM_OUTBOX_DISPATCH_LOCK.acquire(blocking=False):
        return {
            "ok": True,
            "processed": 0,
            "skipped_stale": 0,
            "coalesced": True,
            "message": "다른 텔레그램 발송기가 이미 처리 중이어서 이번 호출을 합쳤습니다.",
            "dispatches": [],
        }
    try:
        safe_limit = max(1, min(int(limit or 1), 10))
        pending = OPS.pending_telegram_outbox(limit=safe_limit)
        skipped_stale = 0
        if max_age_minutes is not None:
            recent = []
            for row in OPS.pending_telegram_outbox(limit=100):
                age = _iso_age_seconds(row.get("created_at"))
                if age is not None and age <= max_age_minutes * 60:
                    recent.append(row)
                else:
                    skipped_stale += 1
            pending = recent[:safe_limit]
        dispatches = []
        for row in pending:
            metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
            claim = OPS.claim_single_delivery_telegram(row, source=source)
            if metadata.get("single_delivery") is True and claim is None:
                continue
            result = INTEGRATIONS.telegram_send(str(row.get("text", "")))
            dispatches.append(OPS.record_telegram_dispatch(row, result, source=source))
        return {
            "ok": True,
            "processed": len(dispatches),
            "skipped_stale": skipped_stale,
            "coalesced": False,
            "message": f"텔레그램 보고 {len(dispatches)}건 처리" + (f", 오래된 보고 {skipped_stale}건 자동 발송 제외" if skipped_stale else ""),
            "dispatches": dispatches,
            "center": build_telegram_dispatch_center(),
        }
    finally:
        TELEGRAM_OUTBOX_DISPATCH_LOCK.release()


def recent_ai_staff_activity(limit: int = 40) -> list[dict[str, object]]:
    safe_limit = max(1, min(int(limit or 40), 200))
    rows = _read_jsonl(AI_STAFF_ACTIVITY_FILE, limit=safe_limit)
    return list(reversed(rows))


def build_ai_worklog() -> dict[str, object]:
    memory_data = MEMORY.load()
    memory_summary = MEMORY.summary()
    market_clock = build_market_session_clock()
    pipeline = build_ai_pipeline()
    cycles = [item for item in list(memory_data.get("cycles", [])) if isinstance(item, dict)]
    recent_cycles = list(reversed(cycles[-10:]))
    staff_meetings = recent_ai_staff_meetings(limit=10)
    staff_activity_rows = recent_ai_staff_activity(limit=36)
    ops_status = OPS.status(marks={})
    paper = ops_status.get("paper", {}) if isinstance(ops_status.get("paper"), dict) else {}
    approvals = ops_status.get("approvals", {}) if isinstance(ops_status.get("approvals"), dict) else {}
    outbox = ops_status.get("telegram_outbox", {}) if isinstance(ops_status.get("telegram_outbox"), dict) else {}
    duplicate = ops_status.get("duplicate_guard", {}) if isinstance(ops_status.get("duplicate_guard"), dict) else {}
    daemon_status = AI_DAEMON.status()
    worker_board = daemon_status.get("worker_board", {}) if isinstance(daemon_status.get("worker_board"), dict) else {}
    workers = worker_board.get("workers", []) if isinstance(worker_board.get("workers"), list) else []
    active_worker_count = len([row for row in workers if isinstance(row, dict) and bool(row.get("continuous"))])
    latest_cycle = recent_cycles[0] if recent_cycles else {}
    latest_candidates = latest_cycle.get("candidates", []) if isinstance(latest_cycle.get("candidates"), list) else []
    latest_top = latest_candidates[0] if latest_candidates and isinstance(latest_candidates[0], dict) else {}
    lessons = [str(item) for item in list(memory_summary.get("lessons", [])) if item][-6:]
    latest_paper_memory = memory_summary.get("latest_paper_rehearsal_memory") if isinstance(memory_summary.get("latest_paper_rehearsal_memory"), dict) else {}
    paper_memory_count = int(memory_summary.get("paper_rehearsal_memory_count", 0) or 0)
    journal_events = JOURNAL.recent(24)
    timeline: list[dict[str, object]] = []

    for activity in staff_activity_rows[:12]:
        if not isinstance(activity, dict):
            continue
        timeline.append(
            {
                "kind": "staff_activity",
                "created_at": activity.get("created_at") or datetime.now().isoformat(timespec="seconds"),
                "title": f"{activity.get('name') or activity.get('role') or 'AI 직원'} 근무",
                "headline": f"{activity.get('state', '-')} / {activity.get('task', '-')}",
                "symbol": "",
                "score": activity.get("progress_pct", ""),
                "gate": "상시" if activity.get("continuous") else "대기",
                "ops_status": "RUNNING" if activity.get("running") else "WAITING",
                "memo": f"{activity.get('detail', '')} 다음: {activity.get('next_action', '-')}",
            }
        )

    for meeting in staff_meetings[:6]:
        decision = meeting.get("decision", {}) if isinstance(meeting.get("decision"), dict) else {}
        top = meeting.get("top_candidate", {}) if isinstance(meeting.get("top_candidate"), dict) else {}
        next_actions = meeting.get("next_actions", []) if isinstance(meeting.get("next_actions"), list) else []
        timeline.append(
            {
                "kind": "staff_meeting",
                "created_at": meeting.get("created_at") or datetime.now().isoformat(timespec="seconds"),
                "title": f"AI 직원 회의 {meeting.get('id', '-')}",
                "headline": f"{decision.get('label', '-')} / {top.get('name') or top.get('symbol', '-')}",
                "symbol": top.get("symbol", ""),
                "score": top.get("score", ""),
                "gate": top.get("gate", ""),
                "ops_status": meeting.get("real_execution", "BLOCKED"),
                "memo": " / ".join(str(item) for item in next_actions[:2]) or "연구원과 운용원이 다음 행동을 합의했습니다.",
            }
        )

    for cycle in recent_cycles[:6]:
        candidates = cycle.get("candidates", []) if isinstance(cycle.get("candidates"), list) else []
        top = candidates[0] if candidates and isinstance(candidates[0], dict) else {}
        ops_action = cycle.get("ops_action", {}) if isinstance(cycle.get("ops_action"), dict) else {}
        timeline.append(
            {
                "kind": "cycle",
                "created_at": cycle.get("stamp") or datetime.now().isoformat(timespec="seconds"),
                "title": f"연구 사이클 {cycle.get('cycle_id', '-')}",
                "headline": cycle.get("headline", "-"),
                "symbol": top.get("symbol", "-"),
                "score": top.get("score", "-"),
                "gate": top.get("risk_gate_status", "-"),
                "ops_status": ops_action.get("status", "-"),
                "memo": cycle.get("lesson", "-"),
            }
        )

    for event in journal_events[:10]:
        if not isinstance(event, dict):
            continue
        timeline.append(
            {
                "kind": "journal",
                "created_at": _format_event_time(event.get("time")),
                "title": event.get("type", "JOURNAL"),
                "headline": event.get("message", "-"),
                "symbol": "",
                "score": "",
                "gate": "",
                "ops_status": "",
                "memo": "시스템 이벤트/사용자 명령 기록",
            }
        )

    timeline.sort(key=lambda item: str(item.get("created_at", "")), reverse=True)
    top_candidates = []
    for item in list(memory_summary.get("top_candidates", []))[:8]:
        if not isinstance(item, dict):
            continue
        top_candidates.append(
            {
                "symbol": item.get("symbol", "-"),
                "name": item.get("name", ""),
                "score": item.get("score", "-"),
                "gate": item.get("risk_gate_status", "-"),
                "return_pct": item.get("return_pct", "-"),
                "robustness_score": item.get("robustness_score", "-"),
                "memo": item.get("memo", ""),
            }
        )

    shift_cards = [
        {"label": "상시근무", "value": f"{active_worker_count}명", "detail": f"작업판 {len(workers)}명"},
        {"label": "AI 회의록", "value": f"{len(staff_meetings)}건", "detail": (staff_meetings[0].get("decision", {}) or {}).get("label", "-") if staff_meetings and isinstance(staff_meetings[0].get("decision"), dict) else "-"},
        {"label": "Paper 기억", "value": f"{paper_memory_count}개", "detail": f"최신 {latest_paper_memory.get('id', '-') or '-'}"},
        {"label": "근무 상태", "value": "연구 중" if daemon_status.get("running") else "대기", "detail": f"주기 {daemon_status.get('interval_seconds', 0)}초"},
        {"label": "현재 주시", "value": str(market_clock.get("primary_market", "-")), "detail": str(market_clock.get("primary_focus", "-"))[:36]},
        {"label": "누적 사이클", "value": f"{memory_summary.get('cycle_count', 0)}회", "detail": f"Vault {memory_summary.get('vault', '-')}"},
        {"label": "Paper 티켓", "value": f"{paper.get('ticket_count', 0)}건", "detail": f"평가금 {paper.get('equity', '-')}"},
        {"label": "승인/중복", "value": f"{approvals.get('pending', 0)} 대기", "detail": f"중복가드 {duplicate.get('fingerprints', 0)}개"},
        {"label": "텔레그램 큐", "value": f"{outbox.get('queued', 0)}건", "detail": "보고 outbox"},
        {"label": "실전 주문", "value": "BLOCKED", "detail": "dry-run까지만 허용"},
    ]

    return {
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "brief": {
            "headline": "AI 트레이더 교대보고",
            "summary": f"최근 최고 후보는 {latest_top.get('symbol', '-')}이며, 실전 주문은 잠금 상태로 연구/검증/보고만 수행 중입니다.",
            "latest_cycle_id": latest_cycle.get("cycle_id", "-"),
            "latest_cycle_at": latest_cycle.get("stamp", "-"),
            "latest_top": latest_top,
            "latest_lesson": latest_cycle.get("lesson", lessons[-1] if lessons else "-"),
            "next_action": latest_cycle.get("next_action", "상위 후보를 계속 재무/뉴스/백테스트로 검증"),
        },
        "shift_cards": shift_cards,
        "timeline": timeline[:18],
        "lessons": lessons,
        "staff_meetings": staff_meetings,
        "staff_activity": staff_activity_rows,
        "top_candidates": top_candidates,
        "ops_snapshot": {
            "paper_ticket_count": paper.get("ticket_count", 0),
            "paper_equity": paper.get("equity", 0),
            "pending_approvals": approvals.get("pending", 0),
            "telegram_queued": outbox.get("queued", 0),
            "real_execution": "BLOCKED",
        },
        "market_clock": market_clock,
        "pipeline_summary": pipeline.get("summary", {}),
        "data_sources": ["장기기억 JSON", "Obsidian Vault", "Native Journal", "OPS paper/approval/audit", "텔레그램 outbox"],
    }


def _mobile_number(value: object, default: float = 0.0) -> float:
    try:
        return float(value or 0)
    except (TypeError, ValueError):
        return default


def _mobile_compact_candidate(
    row: dict[str, object],
    pipeline_row: dict[str, object] | None = None,
) -> dict[str, object]:
    pipeline = pipeline_row or {}
    market_signal = row.get("market_signal") if isinstance(row.get("market_signal"), dict) else {}
    trade_horizon = row.get("trade_horizon") if isinstance(row.get("trade_horizon"), dict) else {}
    sector = row.get("candidate_sector") if isinstance(row.get("candidate_sector"), dict) else {}
    failed = row.get("risk_gate_failed") if isinstance(row.get("risk_gate_failed"), list) else []
    return {
        "symbol": str(row.get("symbol") or pipeline.get("symbol") or ""),
        "name": str(row.get("name") or pipeline.get("name") or ""),
        "market": str(row.get("market") or pipeline.get("market") or ""),
        "rank": int(_mobile_number(row.get("rank"), 0)),
        "score": round(_mobile_number(row.get("score") or row.get("display_score")), 2),
        "action": str(row.get("action") or pipeline.get("lane") or "관찰"),
        "lane": str(row.get("candidate_lane") or pipeline.get("lane") or ""),
        "trade_mode": str(row.get("trade_mode") or trade_horizon.get("mode") or ""),
        "sector": str(sector.get("label") or ""),
        "price": _mobile_number(market_signal.get("price")),
        "change_pct": round(_mobile_number(row.get("change_pct") or market_signal.get("change_pct")), 2),
        "amount": _mobile_number(row.get("amount")),
        "risk_gate_status": str(row.get("risk_gate_status") or pipeline.get("gate") or ""),
        "risk_gate_failed": [str(item) for item in failed[:5]],
        "reasons": [str(item) for item in (row.get("reasons") or [])[:5]],
        "risk_flags": [str(item) for item in (row.get("risk_flags") or [])[:5]],
        "next_action": str(pipeline.get("next_action") or ""),
        "progress": round(_mobile_number(pipeline.get("progress")), 1),
        "stop_loss_pct": _mobile_number(trade_horizon.get("stop_loss_pct")),
        "take_profit_pct": _mobile_number(trade_horizon.get("take_profit_pct")),
    }


def _mobile_compact_trade(row: object) -> dict[str, object]:
    source = row if isinstance(row, dict) else {}
    return {
        "id": str(source.get("id") or source.get("signal_id") or ""),
        "time": str(source.get("executed_at") or source.get("submitted_at") or source.get("created_at") or source.get("time") or ""),
        "symbol": str(source.get("symbol") or ""),
        "name": str(source.get("name") or ""),
        "side": str(source.get("side") or ""),
        "quantity": _mobile_number(source.get("quantity") or source.get("filled_quantity")),
        "price": _mobile_number(source.get("price") or source.get("avg_price")),
        "status": str(source.get("status") or ""),
        "reason": str(source.get("reason") or source.get("memo") or source.get("message") or ""),
    }


MOBILE_CONSOLE_CACHE: dict[str, tuple[float, dict[str, object]]] = {}
MOBILE_CONSOLE_CACHE_LOCK = threading.Lock()
MOBILE_CONSOLE_BUILD_LOCKS: dict[str, threading.Lock] = {}


def _mobile_console_cached_payload(
    cache_key: str,
    builder: Callable[[], dict[str, object]],
    *,
    ttl_seconds: int,
) -> dict[str, object]:
    """Keep the phone responsive without changing order-time data contracts."""
    ttl = max(1, int(ttl_seconds))

    def cached_payload(
        saved: tuple[float, dict[str, object]],
        now: float,
        *,
        stale: bool,
        refreshing: bool,
    ) -> dict[str, object]:
        return {
            **saved[1],
            "mobile_cache": {
                "hit": True,
                "age_seconds": round(max(0.0, now - saved[0]), 2),
                "ttl_seconds": ttl,
                "stale": stale,
                "refreshing": refreshing,
            },
        }

    now = time.monotonic()
    with MOBILE_CONSOLE_CACHE_LOCK:
        saved = MOBILE_CONSOLE_CACHE.get(cache_key)
        build_lock = MOBILE_CONSOLE_BUILD_LOCKS.setdefault(cache_key, threading.Lock())
    if saved and now - saved[0] < ttl:
        return cached_payload(saved, now, stale=False, refreshing=False)

    if saved:
        refresh_started = build_lock.acquire(blocking=False)
        if refresh_started:
            def refresh() -> None:
                try:
                    payload = builder()
                    if not isinstance(payload, dict):
                        raise TypeError("mobile console builder must return a dictionary")
                    with MOBILE_CONSOLE_CACHE_LOCK:
                        MOBILE_CONSOLE_CACHE[cache_key] = (time.monotonic(), dict(payload))
                except Exception as exc:
                    print(f"Mobile console cache refresh failed closed ({cache_key}): {exc}")
                finally:
                    build_lock.release()

            threading.Thread(
                target=refresh,
                name=f"mobile-cache-{cache_key[:20]}",
                daemon=True,
            ).start()
        return cached_payload(saved, now, stale=True, refreshing=refresh_started)

    with build_lock:
        now = time.monotonic()
        with MOBILE_CONSOLE_CACHE_LOCK:
            saved = MOBILE_CONSOLE_CACHE.get(cache_key)
        if saved:
            return cached_payload(
                saved,
                now,
                stale=now - saved[0] >= ttl,
                refreshing=False,
            )
        payload = builder()
        if not isinstance(payload, dict):
            raise TypeError("mobile console builder must return a dictionary")
        saved_at = time.monotonic()
        stored = dict(payload)
        with MOBILE_CONSOLE_CACHE_LOCK:
            MOBILE_CONSOLE_CACHE[cache_key] = (saved_at, stored)
        return {
            **stored,
            "mobile_cache": {
                "hit": False,
                "age_seconds": 0.0,
                "ttl_seconds": ttl,
                "stale": False,
                "refreshing": False,
            },
        }


def prewarm_mobile_console() -> None:
    """Prepare the two slowest read-only phone cards after server startup."""
    for cache_key, builder, ttl in (
        ("summary", build_mobile_console_summary, 12),
        ("activity", build_mobile_console_activity, 30),
    ):
        try:
            _mobile_console_cached_payload(cache_key, builder, ttl_seconds=ttl)
        except Exception as exc:
            print(f"Mobile console prewarm failed closed ({cache_key}): {exc}")


def build_mobile_console_summary() -> dict[str, object]:
    started_at = time.perf_counter()
    focus = build_operating_focus_status()
    ops = build_autotrade_status_quick()
    sidecar = build_execution_sidecar_status_quick()
    developer = build_internal_developer_launcher_status()
    staff = build_ai_worker_status_quick(ttl_seconds=60)
    market_clock = build_market_session_clock()
    flags = ops.get("flags") if isinstance(ops.get("flags"), dict) else {}
    capital = ops.get("capital_policy") if isinstance(ops.get("capital_policy"), dict) else {}
    execution_contract = capital.get("execution_mode_contract") if isinstance(capital.get("execution_mode_contract"), dict) else {}
    pipeline = sidecar.get("candidate_pipeline") if isinstance(sidecar.get("candidate_pipeline"), dict) else {}
    workers = staff.get("workers") if isinstance(staff.get("workers"), list) else []
    compact_workers = []
    for row in workers[:10]:
        if not isinstance(row, dict):
            continue
        compact_workers.append(
            {
                "id": str(row.get("id") or row.get("role") or ""),
                "name": str(row.get("name") or row.get("label") or row.get("role") or "AI 직원"),
                "status": str(row.get("status") or row.get("state") or ""),
                "task": str(row.get("current_task") or row.get("task") or row.get("detail") or ""),
                "updated_at": str(row.get("updated_at") or row.get("last_seen_at") or ""),
            }
        )
    developer_status = str(developer.get("status") or "UNKNOWN").upper()
    system_ok = developer_status not in {"OFFLINE", "STALE", "INCIDENT"}
    pipeline_ok = bool(pipeline.get("trading_pipeline_healthy", pipeline.get("ok", False)))
    return {
        "ok": True,
        "schema": "codexstock_mobile_summary_v1",
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "overall": {
            "ok": system_ok and pipeline_ok and bool(sidecar.get("ok")),
            "label": "정상 운영" if system_ok and pipeline_ok and sidecar.get("ok") else "확인 필요",
            "system_healthy": system_ok,
            "trading_pipeline_healthy": pipeline_ok,
            "execution_healthy": bool(sidecar.get("ok")),
        },
        "focus": {
            "mode": focus.get("mode"),
            "label": focus.get("label"),
            "trading_focus_pct": focus.get("trading_focus_pct"),
            "research_focus_pct": focus.get("research_focus_pct"),
            "market_phase": focus.get("market_phase"),
            "current_task": focus.get("current_task"),
            "reason": focus.get("reason"),
            "updated_at": focus.get("updated_at"),
        },
        "market_clock": {
            "phase": market_clock.get("phase") or market_clock.get("market_phase"),
            "label": market_clock.get("label") or market_clock.get("session_label"),
            "is_open": bool(market_clock.get("is_open") or market_clock.get("market_open")),
            "now": market_clock.get("now") or market_clock.get("current_time"),
        },
        "operations": {
            "mode": ops.get("mode"),
            "flags": {
                key: bool(flags.get(key))
                for key in (
                    "delegated_live_autonomy_enabled",
                    "delegated_live_authorized_today",
                    "live_candidate_enabled",
                    "live_pilot_enabled",
                    "live_execution_enabled",
                    "require_approval",
                    "emergency_halt",
                    "day_halted",
                    "buy_blocked",
                    "scheduler_running",
                    "research_daemon_running",
                )
            },
            "auto_submit_max_cash_pct": capital.get("auto_submit_max_cash_pct"),
            "max_position_cash_pct": capital.get("max_position_cash_pct"),
            "target_symbol_count": capital.get("target_symbol_count"),
            "today_counts": ops.get("today_counts") if isinstance(ops.get("today_counts"), dict) else {},
            "blockers": [str(item) for item in (ops.get("blockers") or [])[:8]],
            "control_mode": execution_contract.get("control_mode"),
            "contract_state": execution_contract.get("state"),
        },
        "executor": {
            "ok": bool(sidecar.get("ok")),
            "mode": sidecar.get("mode"),
            "updated_at": sidecar.get("updated_at"),
            "processed_total": sidecar.get("processed_total"),
            "inbox_pending": sidecar.get("inbox_pending"),
            "real_order_supported": bool(sidecar.get("real_order_supported")),
            "pipeline_state": pipeline.get("state"),
            "no_trade_classification": pipeline.get("no_trade_classification"),
            "stage_counts": pipeline.get("stage_counts") if isinstance(pipeline.get("stage_counts"), dict) else {},
            "incidents": [str(item) for item in (pipeline.get("incidents") or [])[:5]],
        },
        "developer": {
            "status": developer.get("status"),
            "tone": developer.get("tone"),
            "label": developer.get("label"),
            "message": developer.get("message"),
            "counts": developer.get("counts") if isinstance(developer.get("counts"), dict) else {},
            "workflow": developer.get("workflow") if isinstance(developer.get("workflow"), dict) else {},
        },
        "staff": {
            "running": bool(staff.get("running")),
            "headline": staff.get("headline"),
            "status_counts": staff.get("status_counts") if isinstance(staff.get("status_counts"), dict) else {},
            "workers": compact_workers,
        },
        "elapsed_ms": round((time.perf_counter() - started_at) * 1000, 1),
        "safety": "휴대폰용 상태 요약입니다. 계좌번호·API 키·토큰을 포함하지 않으며 주문을 실행하지 않습니다.",
    }


def build_mobile_console_candidates(limit: int = 8) -> dict[str, object]:
    bounded = max(1, min(int(limit), 12))
    screener = build_ai_screener(force=False)
    pipeline = build_ai_pipeline()
    screener_rows = screener.get("candidates") if isinstance(screener.get("candidates"), list) else []
    pipeline_rows = pipeline.get("candidates") if isinstance(pipeline.get("candidates"), list) else []
    pipeline_by_symbol = {
        str(row.get("symbol") or ""): row
        for row in pipeline_rows
        if isinstance(row, dict) and row.get("symbol")
    }
    candidates = [
        _mobile_compact_candidate(row, pipeline_by_symbol.get(str(row.get("symbol") or "")))
        for row in screener_rows[:bounded]
        if isinstance(row, dict)
    ]
    return {
        "ok": True,
        "schema": "codexstock_mobile_candidates_v1",
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "count": len(candidates),
        "top": candidates[0] if candidates else {},
        "candidates": candidates,
        "pipeline_summary": pipeline.get("summary") if isinstance(pipeline.get("summary"), dict) else {},
        "market_regime": screener.get("market_regime") if isinstance(screener.get("market_regime"), dict) else {},
        "safety": "후보는 연구·관찰 정보이며 휴대폰 호출만으로 주문하지 않습니다.",
    }


def build_mobile_console_activity() -> dict[str, object]:
    today = build_today_trade_quick_summary()
    alerts = build_ai_alert_center()
    developer = build_internal_developer_launcher_status()
    counts = today.get("counts") if isinstance(today.get("counts"), dict) else {}
    trade_groups = {}
    for key in ("live_submitted", "live_blocked", "live_candidates", "dry_ready", "paper_filled"):
        rows = today.get(key) if isinstance(today.get(key), list) else []
        trade_groups[key] = [_mobile_compact_trade(row) for row in rows[:12]]
    alert_rows = alerts.get("alerts") if isinstance(alerts.get("alerts"), list) else []
    compact_alerts = []
    for row in alert_rows[:12]:
        if not isinstance(row, dict):
            continue
        compact_alerts.append(
            {
                "level": str(row.get("level") or row.get("severity") or "info"),
                "title": str(row.get("title") or row.get("label") or "알림"),
                "message": str(row.get("message") or row.get("detail") or row.get("reason") or ""),
                "next_action": str(row.get("next_action") or row.get("action") or ""),
                "created_at": str(row.get("created_at") or row.get("generated_at") or ""),
            }
        )
    return {
        "ok": True,
        "schema": "codexstock_mobile_activity_v1",
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "today": {
            "date": today.get("date"),
            "headline": today.get("headline"),
            "counts": counts,
            "why_no_real_trade": today.get("why_no_real_trade") if isinstance(today.get("why_no_real_trade"), dict) else {},
            "trades": trade_groups,
        },
        "alerts": compact_alerts,
        "developer": {
            "status": developer.get("status"),
            "label": developer.get("label"),
            "message": developer.get("message"),
            "history": (developer.get("history") or [])[:8] if isinstance(developer.get("history"), list) else [],
        },
        "safety": "읽기 전용 활동 원장입니다. 민감 인증정보를 반환하지 않습니다.",
    }


def build_mobile_console_portfolio() -> dict[str, object]:
    performance = build_live_trade_performance(limit=12)
