def _mobile_request_authorized(handler: SimpleHTTPRequestHandler) -> tuple[bool, dict[str, object]]:
    token = bearer_token_from_headers(handler.headers)
    result = MOBILE_ACCESS.authenticate(token)
    if result.get("ok"):
        return True, result
    json_response(
        handler,
        {
            "ok": False,
            "error": result.get("error") or "mobile_unauthorized",
            "message": "휴대폰 연결 토큰이 없거나 만료됐습니다. PC에서 새 페어링 코드를 만드세요.",
        },
        status=401,
    )
    return False, result


def json_response(handler: SimpleHTTPRequestHandler, payload: object, status: int = 200) -> None:
    body = json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8")
    try:
        handler.send_response(status)
        handler.send_header("Content-Type", "application/json; charset=utf-8")
        handler.send_header("Content-Length", str(len(body)))
        handler.end_headers()
        handler.wfile.write(body)
    except (BrokenPipeError, ConnectionAbortedError, ConnectionResetError):
        # Browser refreshes and cancelled fetches can close the socket after work is done.
        return


def _market_cache_quote_invalid_for_official_mark(symbol: str, price: float, market: str) -> list[str]:
    issues: list[str] = []
    if market != "KR":
        return issues
    if price <= 0:
        issues.append("market_cache_price_missing")
        return issues
    if abs(price - round(price)) > 0.001:
        issues.append(f"market_cache_fractional_krw_price:{price}")
    if price < 500:
        issues.append(f"market_cache_too_low_for_kr_equity:{price}")
    floor = CORE_KR_PRICE_FLOOR.get(_normalize_symbol_for_watchlist(symbol))
    if floor and price < floor:
        issues.append(f"market_cache_below_core_floor:{price}<{floor:g}")
    return issues


def _store_verified_official_quote(payload: dict[str, object]) -> None:
    symbol = _normalize_symbol_for_watchlist(payload.get("symbol"))
    source = str(payload.get("source") or "").strip().lower()
    if source not in {"kis", "kis_readonly", "kis_readonly_account"}:
        return
    guard = quote_unit_guard(
        symbol,
        payload.get("price"),
        payload.get("market"),
        payload.get("currency"),
        source,
        unit_scale=payload.get("unit_scale"),
        require_unit_contract=True,
    )
    relationship_issues = _quote_price_relationship_issues(payload)
    if (
        guard.get("status") != "ok"
        or guard.get("market") != "KR"
        or payload.get("price_contract_ok") is not True
        or relationship_issues
    ):
        return
    verified_at = datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds")
    row = {
        "symbol": symbol,
        "name": str(payload.get("name") or resolve_symbol_display_name(symbol)),
        "market": "KR",
        "currency": "KRW",
        "price": _number(payload.get("price")),
        "unit_scale": 1,
        "previous_close": _number(payload.get("previous_close")),
        "open": _number(payload.get("open")),
        "high": _number(payload.get("high")),
        "low": _number(payload.get("low")),
        "change_pct": _number(payload.get("change_pct")),
        "upper_limit_price": _number(payload.get("upper_limit_price")),
        "lower_limit_price": _number(payload.get("lower_limit_price")),
        "price_contract_ok": True,
        "original_source": source,
        "verified_at_epoch": time.time(),
        "verified_at": verified_at,
    }
    try:
        with VERIFIED_QUOTE_CACHE_LOCK:
            cache: dict[str, object] = {"schema": "codexstock_verified_quotes_v2", "quotes": {}}
            if VERIFIED_QUOTE_CACHE_FILE.exists():
                try:
                    loaded = json.loads(VERIFIED_QUOTE_CACHE_FILE.read_text(encoding="utf-8"))
                    if isinstance(loaded, dict) and loaded.get("schema") == "codexstock_verified_quotes_v2":
                        cache.update(loaded)
                except (OSError, json.JSONDecodeError):
                    # A torn legacy write must not permanently block future
                    # official quote refreshes. The next clean KIS quote
                    # rebuilds the derived cache from a known schema.
                    cache = {"schema": "codexstock_verified_quotes_v2", "quotes": {}}
            quotes = cache.get("quotes") if isinstance(cache.get("quotes"), dict) else {}
            quotes[symbol] = row
            cache["quotes"] = quotes
            cache["updated_at"] = verified_at
            VERIFIED_QUOTE_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
            temp_path = VERIFIED_QUOTE_CACHE_FILE.with_name(
                f"{VERIFIED_QUOTE_CACHE_FILE.name}.{os.getpid()}.{threading.get_ident()}.tmp"
            )
            temp_path.write_text(json.dumps(cache, ensure_ascii=False, indent=2), encoding="utf-8")
            os.replace(temp_path, VERIFIED_QUOTE_CACHE_FILE)
    except Exception:
        return


def _load_verified_official_quote(symbol: str, max_age_hours: float = 72.0) -> dict[str, object] | None:
    normalized = _normalize_symbol_for_watchlist(symbol)
    try:
        with VERIFIED_QUOTE_CACHE_LOCK:
            cache = json.loads(VERIFIED_QUOTE_CACHE_FILE.read_text(encoding="utf-8"))
        if not isinstance(cache, dict) or cache.get("schema") != "codexstock_verified_quotes_v2":
            return None
        quotes = cache.get("quotes") if isinstance(cache, dict) and isinstance(cache.get("quotes"), dict) else {}
        row = quotes.get(normalized) if isinstance(quotes.get(normalized), dict) else None
        if not row:
            return None
        verified_at_epoch = _number(row.get("verified_at_epoch"))
        age_seconds = max(0.0, time.time() - verified_at_epoch) if verified_at_epoch > 0 else float("inf")
        if age_seconds > max(1.0, max_age_hours) * 3600:
            return None
        guard = quote_unit_guard(
            normalized,
            row.get("price"),
            row.get("market"),
            row.get("currency"),
            "kis_verified_cache",
            unit_scale=row.get("unit_scale"),
            require_unit_contract=True,
        )
        if guard.get("status") != "ok":
            return None
        if row.get("price_contract_ok") is not True or _quote_price_relationship_issues(row):
            return None
        return {
            "symbol": normalized,
            "name": str(row.get("name") or resolve_symbol_display_name(normalized)),
            "market": "KR",
            "currency": "KRW",
            "unit_scale": 1,
            "price": _number(row.get("price")),
            "previous_close": _number(row.get("previous_close")),
            "open": _number(row.get("open")),
            "high": _number(row.get("high")),
            "low": _number(row.get("low")),
            "change_pct": _number(row.get("change_pct")),
            "upper_limit_price": _number(row.get("upper_limit_price")),
            "lower_limit_price": _number(row.get("lower_limit_price")),
            "price_contract_ok": True,
            "source": "KIS_VERIFIED_CACHE",
            "original_source": str(row.get("original_source") or "kis_readonly"),
            "updated_at": str(row.get("verified_at") or ""),
            "verified_quote_age_seconds": round(age_seconds, 1),
        }
    except Exception:
        return None


def ops_quote(symbol: str, *, prefer_live: bool = True) -> dict[str, object]:
    normalized = symbol.upper().strip()
    price = 0.0
    source = "내장 시세"
    name = resolve_symbol_display_name(normalized)
    updated_at = datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds")
    expected = expected_quote_market_currency(normalized)
    market = expected["market"]
    currency = expected["currency"]
    unit_scale: object = None
    quote_meta: dict[str, object] = {}
    if prefer_live and re.fullmatch(r"\d{6}", normalized):
        try:
            kis = INTEGRATIONS.kis_quote(symbol=normalized)
            if kis.get("ok"):
                price = _number(kis.get("price"))
                source = str(kis.get("source") or "KIS")
                name = resolve_symbol_display_name(normalized, kis.get("name"), name)
                updated_at = str(kis.get("updated_at") or kis.get("timestamp") or updated_at)
                market = "KR"
                currency = str(kis.get("currency") or "").strip().upper()
                unit_scale = kis.get("unit_scale")
                _store_verified_official_quote(
                    {
                        "symbol": normalized,
                        "name": name,
                        "market": market,
                        "currency": currency,
                        "price": price,
                        "unit_scale": unit_scale,
                        "previous_close": kis.get("previous_close"),
                        "open": kis.get("open"),
                        "high": kis.get("high"),
                        "low": kis.get("low"),
                        "change_pct": kis.get("change_pct"),
                        "upper_limit_price": kis.get("upper_limit_price"),
                        "lower_limit_price": kis.get("lower_limit_price"),
                        "price_contract_ok": kis.get("price_contract_ok"),
                        "source": source,
                    }
                )
                quote_meta["verified_quote_age_seconds"] = 0.0
                quote_meta["original_source"] = source
                quote_meta["previous_close"] = _number(kis.get("previous_close"))
                quote_meta["open"] = _number(kis.get("open"))
                quote_meta["high"] = _number(kis.get("high"))
                quote_meta["low"] = _number(kis.get("low"))
                quote_meta["change_pct"] = _number(kis.get("change_pct"))
                quote_meta["upper_limit_price"] = _number(kis.get("upper_limit_price"))
                quote_meta["lower_limit_price"] = _number(kis.get("lower_limit_price"))
                quote_meta["vi_cls_code"] = str(kis.get("vi_cls_code") or "").strip()
                quote_meta["temporary_halt_yn"] = str(kis.get("temporary_halt_yn") or "").strip().upper()
                quote_meta["market_warning_code"] = str(kis.get("market_warning_code") or "").strip()
                quote_meta["short_overheat_yn"] = str(kis.get("short_overheat_yn") or "").strip().upper()
                quote_meta["risk_fields_observed"] = bool(kis.get("risk_fields_observed"))
        except Exception as exc:
            OPS.audit("KIS_QUOTE_FALLBACK", f"{normalized} KIS 시세 실패, 내장 시세 사용", {"error": str(exc)})
    if price <= 0 and market == "KR":
        verified_quote = _load_verified_official_quote(normalized)
        if verified_quote:
            price = _number(verified_quote.get("price"))
            source = str(verified_quote.get("source") or "KIS_VERIFIED_CACHE")
            name = resolve_symbol_display_name(normalized, verified_quote.get("name"), name)
            updated_at = str(verified_quote.get("updated_at") or updated_at)
            quote_meta["verified_quote_age_seconds"] = verified_quote.get("verified_quote_age_seconds")
            quote_meta["original_source"] = verified_quote.get("original_source")
            unit_scale = verified_quote.get("unit_scale")
            for field in (
                "previous_close",
                "open",
                "high",
                "low",
                "change_pct",
                "upper_limit_price",
                "lower_limit_price",
                "price_contract_ok",
            ):
                quote_meta[field] = verified_quote.get(field)
    if price <= 0:
        quote = MARKET.quote(normalized)
        raw_market_price = float(quote.get("price", 0) or 0)
        market_cache_issues = _market_cache_quote_invalid_for_official_mark(normalized, raw_market_price, market)
        price = 0.0 if market_cache_issues else raw_market_price
        source = str(quote.get("source") or "MARKET_CACHE")
        if market_cache_issues:
            source = "MARKET_CACHE_BLOCKED"
            quote_meta["raw_market_cache_price"] = round(raw_market_price, 4)
            quote_meta["market_cache_issues"] = market_cache_issues
            quote_meta["message"] = "MARKET_CACHE simulated KR quote blocked from official marks"
        name = resolve_symbol_display_name(normalized, quote.get("name"), name)
        updated_at = datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds")
        unit_scale = quote.get("unit_scale")
    payload = {
        "symbol": normalized,
        "name": name,
        "market": market,
        "currency": currency,
        "unit_scale": unit_scale,
        "price": round(price, 4),
        "source": source,
        "updated_at": updated_at,
    }
    payload.update(quote_meta)
    return attach_quote_unit_guard(
        payload,
        normalized,
    )


def build_ops_marks(symbols: list[str] | None = None, *, prefer_live: bool = False) -> dict[str, float]:
    if symbols is None:
        paper = OPS.paper_summary(marks={})
        symbols = [
            str(row.get("symbol", "")).upper()
            for row in paper.get("positions", [])
            if isinstance(row, dict) and row.get("symbol")
        ]
    unique_symbols = sorted({str(item).upper().strip() for item in symbols if str(item).strip()})
    marks, snapshot = build_common_quote_marks(
        symbols=unique_symbols,
        prefer_live=prefer_live,
        source="ops-marks",
    )
    snapshot_hash = snapshot.get("snapshot_hash")
    blocked_rows = snapshot.get("blocked") if isinstance(snapshot.get("blocked"), list) else []
    for row in blocked_rows:
        symbol = str(row.get("symbol", "")).strip().upper() if isinstance(row, dict) else ""
        if not symbol:
            continue
        OPS.audit(
            "QUOTE_UNIT_MARK_BLOCKED",
            f"{symbol} mark skipped by common quote snapshot",
            {"symbol": symbol, "snapshot_hash": snapshot_hash, "quote": row},
        )
    return marks


def _readiness_check(label: str, ok: bool, detail: str, weight: int = 10, warning: bool = False) -> dict[str, object]:
    return {
        "label": label,
        "ok": bool(ok),
        "status": "ok" if ok else "warning" if warning else "blocked",
        "detail": detail,
        "weight": weight,
        "earned": weight if ok else max(0, weight // 2) if warning else 0,
    }


EXECUTION_CONTROL_MODE_MANUAL = "manual_approval"
EXECUTION_CONTROL_MODE_DELEGATED = "delegated_auto"
EXECUTION_SIDECAR_MODES = {"shadow", "paper", "live"}


def build_execution_mode_contract(
    policy: dict[str, object],
    *,
    sidecar_mode: object = "",
    supervisor_mode: object = "",
    sidecar_real_order_supported: object | None = None,
    sidecar_ok: object | None = None,
    supervisor_state: object = "",
    live_executor_enabled: bool | None = None,
    require_runtime_evidence: bool = False,
) -> dict[str, object]:
    """Return one fail-closed execution-mode contract for every runtime surface."""
    policy_contract = _build_execution_policy_contract(
        policy,
        trading_date=today_kst(),
    )
    requested_mode = str(policy_contract["control_mode"])
    require_approval = bool(policy_contract["require_approval"])
    delegated_enabled = bool(policy_contract["delegated_enabled"])
    policy_conflicts = list(policy_contract["policy_conflicts"])
    policy_consistent = bool(policy_contract["policy_consistent"])
    delegated = bool(policy_contract["delegated"])
    authorization = dict(policy_contract["authorization"])
    authorization_required = bool(policy_contract["authorization_required"])
    authorization_valid = bool(policy_contract["authorization_valid"])
    live_switches_enabled = bool(policy_contract["live_switches_enabled"])
    safety_halt = bool(policy_contract["safety_halt"])
    desired_sidecar_mode = str(policy_contract["desired_sidecar_mode"])
    configured_live_capability = (
        os.environ.get("CODEXSTOCK_ENABLE_EXTERNAL_LIVE_EXECUTOR") == "1"
        if live_executor_enabled is None
        else bool(live_executor_enabled)
    )
    if sidecar_real_order_supported is True:
        configured_live_capability = True
    supervisor_launch_mode = (
        desired_sidecar_mode
        if desired_sidecar_mode != "live" or configured_live_capability
        else "shadow"
    )

    normalized_sidecar_mode = str(sidecar_mode or "").strip().lower()
    normalized_supervisor_mode = str(supervisor_mode or "").strip().lower()
    normalized_supervisor_state = str(supervisor_state or "").strip().upper()
    runtime_conflicts: list[str] = []
    if require_runtime_evidence and not normalized_sidecar_mode:
        runtime_conflicts.append("sidecar_mode_unverified")
    if require_runtime_evidence and not normalized_supervisor_mode:
        runtime_conflicts.append("supervisor_mode_unverified")
    if normalized_sidecar_mode:
        if normalized_sidecar_mode not in EXECUTION_SIDECAR_MODES:
            runtime_conflicts.append("invalid_sidecar_mode")
        elif normalized_sidecar_mode != desired_sidecar_mode:
            runtime_conflicts.append("sidecar_mode_mismatch")
    if normalized_supervisor_mode:
        if normalized_supervisor_mode not in EXECUTION_SIDECAR_MODES:
            runtime_conflicts.append("invalid_supervisor_mode")
        elif normalized_supervisor_mode != desired_sidecar_mode:
            runtime_conflicts.append("supervisor_mode_mismatch")
    if (
        normalized_sidecar_mode
        and normalized_supervisor_mode
        and normalized_sidecar_mode != normalized_supervisor_mode
    ):
        runtime_conflicts.append("sidecar_supervisor_mode_mismatch")
    if desired_sidecar_mode == "live" and not configured_live_capability:
        runtime_conflicts.append("live_executor_capability_disabled")
    if require_runtime_evidence and sidecar_ok is not True:
        runtime_conflicts.append("sidecar_not_healthy")
    if require_runtime_evidence and normalized_supervisor_state != "MONITORING":
        runtime_conflicts.append("supervisor_not_monitoring")
    if (
        require_runtime_evidence
        and desired_sidecar_mode == "live"
        and sidecar_real_order_supported is not True
    ):
        runtime_conflicts.append("sidecar_live_capability_unverified")
    runtime_conflicts = list(dict.fromkeys(runtime_conflicts))

    mode_consistent = bool(policy_consistent and not runtime_conflicts)
    if not policy_consistent:
        state = "POLICY_CONFLICT"
    elif runtime_conflicts:
        state = "RUNTIME_MODE_CONFLICT"
    elif safety_halt:
        state = "SAFETY_HALTED"
    elif delegated and not authorization_valid:
        state = "DELEGATION_AUTHORIZATION_REQUIRED"
    elif delegated and live_switches_enabled:
        state = "DELEGATED_AUTO_READY"
    elif delegated:
        state = "DELEGATED_AUTO_STANDBY"
    elif live_switches_enabled:
        state = "MANUAL_APPROVAL_READY"
    else:
        state = "MANUAL_APPROVAL_STANDBY"

    contract_material = {
        "control_mode": requested_mode,
        "require_approval": require_approval,
        "delegated_enabled": delegated_enabled,
        "authorization_status": authorization.get("status"),
        "live_switches_enabled": live_switches_enabled,
        "safety_halt": safety_halt,
        "desired_sidecar_mode": desired_sidecar_mode,
    }
    contract_id = hashlib.sha256(
        json.dumps(
            contract_material,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()[:20]
    delegated_runtime_ready = bool(
        delegated
        and authorization_valid
        and live_switches_enabled
        and not safety_halt
        and desired_sidecar_mode == "live"
        and configured_live_capability
        and not runtime_conflicts
    )
    live_path_ready = bool(
        policy_consistent
        and live_switches_enabled
        and not safety_halt
        and (delegated_runtime_ready if delegated else require_approval)
    )
    return {
        "schema": "codexstock_execution_mode_contract_v1",
        "contract_id": contract_id,
        "control_mode": requested_mode,
        "state": state,
        "policy_consistent": policy_consistent,
        "mode_consistent": mode_consistent,
        "delegated": delegated,
        "requires_user_approval": not delegated,
        "approval_token_required": not delegated,
        "authorization_required": authorization_required,
        "authorization_valid": authorization_valid,
        "authorization": authorization,
        "live_switches_enabled": live_switches_enabled,
        "safety_halt": safety_halt,
        "desired_sidecar_mode": desired_sidecar_mode,
        "supervisor_launch_mode": supervisor_launch_mode,
        "sidecar_mode": normalized_sidecar_mode or "unknown",
        "supervisor_mode": normalized_supervisor_mode or "unknown",
        "supervisor_state": normalized_supervisor_state or "unknown",
        "runtime_evidence_required": require_runtime_evidence,
        "live_executor_capability_enabled": configured_live_capability,
        "live_path_ready": live_path_ready,
        "policy_conflicts": policy_conflicts,
        "runtime_conflicts": runtime_conflicts,
        "safety": (
            "정책 또는 런타임 모드가 하나라도 어긋나면 실전 자동집행 준비 상태가 되지 않습니다."
        ),
    }


def build_runtime_execution_mode_contract(
    policy: dict[str, object] | None = None,
) -> dict[str, object]:
    """Reconcile the saved policy with the modes reported by both sidecar processes."""
    current_policy = policy if isinstance(policy, dict) else OPS.autotrade_policy()
    sidecar_root = OPS.data_dir / "execution_sidecar"
    try:
        sidecar_status = json.loads(
            (sidecar_root / "status.json").read_text(encoding="utf-8")
        )
    except (OSError, json.JSONDecodeError):
        sidecar_status = {}
    try:
        supervisor_status = json.loads(
            (sidecar_root / "supervisor.json").read_text(encoding="utf-8")
        )
    except (OSError, json.JSONDecodeError):
        supervisor_status = {}
    contract = build_execution_mode_contract(
        current_policy,
        sidecar_mode=sidecar_status.get("mode"),
        supervisor_mode=(
            supervisor_status.get("expected_mode")
            or supervisor_status.get("mode")
        ),
        sidecar_real_order_supported=sidecar_status.get("real_order_supported"),
        sidecar_ok=sidecar_status.get("ok"),
        supervisor_state=supervisor_status.get("state"),
        require_runtime_evidence=True,
    )
    contract["sidecar_status_updated_at"] = str(
        sidecar_status.get("updated_at") or ""
    )
    contract["supervisor_checked_at"] = str(
        supervisor_status.get("checked_at") or ""
    )
    return contract


def _approval_gate_contract(policy: dict[str, object]) -> tuple[bool, str]:
    contract = build_execution_mode_contract(policy)
    if not contract.get("policy_consistent"):
        conflicts = ", ".join(str(item) for item in contract.get("policy_conflicts", []))
        return False, f"실행 모드 정책 충돌: {conflicts or 'unknown'}"
    if contract.get("delegated"):
        return True, "완전자동 모드: 개별 승인 대신 서명 신호와 외부 실행기 안전 게이트를 사용합니다."
    return bool(contract.get("requires_user_approval")), "반자동 모드: 실전 후보는 승인 토큰을 거쳐야 합니다."


def _delegated_execution_mode(policy: dict[str, object]) -> bool:
    return bool(build_execution_mode_contract(policy).get("delegated"))


def build_autotrade_readiness(ops_status: dict[str, object] | None = None) -> dict[str, object]:
    ops_status = ops_status or OPS.status(marks={})
    integration_status = INTEGRATIONS.status()
    kis = integration_status.get("kis", {}) if isinstance(integration_status.get("kis"), dict) else {}
    dart = integration_status.get("dart", {}) if isinstance(integration_status.get("dart"), dict) else {}
    ecos = integration_status.get("ecos", {}) if isinstance(integration_status.get("ecos"), dict) else {}
    fred = integration_status.get("fred", {}) if isinstance(integration_status.get("fred"), dict) else {}
    telegram = integration_status.get("telegram", {}) if isinstance(integration_status.get("telegram"), dict) else {}
    policy = ops_status.get("autotrade_policy") if isinstance(ops_status.get("autotrade_policy"), dict) else OPS.autotrade_policy()
    paper = ops_status.get("paper", {}) if isinstance(ops_status.get("paper"), dict) else {}
    approvals = ops_status.get("approvals", {}) if isinstance(ops_status.get("approvals"), dict) else {}
    duplicate = ops_status.get("duplicate_guard", {}) if isinstance(ops_status.get("duplicate_guard"), dict) else {}
    scheduler = AUTOPILOT_SCHEDULER.status()
    daemon = AI_DAEMON.status()
    ticket_count = int(paper.get("ticket_count", 0) or 0)
    try:
        min_paper = max(0, int(float(policy.get("min_paper_rehearsals_before_live", 20))))
    except (TypeError, ValueError):
        min_paper = 20
    live_execution = bool(policy.get("live_execution_enabled"))
    delegated_authorization = build_delegated_live_authorization(policy)
    delegated_authorization_ok = (
        not bool(policy.get("delegated_live_autonomy_enabled"))
        or bool(delegated_authorization.get("valid_today"))
    )
    approval_gate_ok, approval_gate_detail = _approval_gate_contract(policy)
    kis_order_mode = bool(kis.get("configured")) and str(kis.get("mode")) == "real" and not bool(kis.get("use_mock")) and bool(kis.get("live_trading")) and not bool(kis.get("readonly", True))
    checks = [
        _readiness_check("KIS 실전 읽기연결", bool(kis.get("configured")) and str(kis.get("mode")) == "real", f"mode={kis.get('mode', '-')}, readonly={kis.get('readonly', '-')}", 12),
        _readiness_check(
            "KIS 실전 주문 모드",
            kis_order_mode if live_execution else bool(kis.get("readonly", True)),
            f"live_execution={live_execution}, live_trading={kis.get('live_trading', '-')}, readonly={kis.get('readonly', '-')}, mock={kis.get('use_mock', '-')}",
            12,
            warning=not live_execution,
        ),
        _readiness_check("DART 재무/공시", bool(dart.get("configured")), "기업 공시/재무제표 분석 연결", 8),
        _readiness_check("ECOS 국내 거시", bool(ecos.get("configured")), "금리/환율/물가 연결", 6, warning=True),
        _readiness_check("FRED 미국 거시", bool(fred.get("configured")), "미국 금리/고용/물가 연결", 6, warning=True),
        _readiness_check("승인/실행 게이트", approval_gate_ok, approval_gate_detail, 10),
        _readiness_check(
            "당일 실전 위임",
            delegated_authorization_ok,
            str(delegated_authorization.get("message", "")),
            10,
        ),
        _readiness_check("긴급정지 해제", not bool(policy.get("emergency_halt")), str(policy.get("memo", "")), 10),
        _readiness_check("중복 주문 가드", bool(duplicate.get("ready")), f"fingerprint {duplicate.get('fingerprints', 0)}개", 8),
        _readiness_check("Paper 리허설 누적", ticket_count >= min_paper, f"{ticket_count}/{min_paper}건", 10, warning=ticket_count > 0),
        _readiness_check("오토파일럿 스케줄러", bool(scheduler.get("running")) and bool(scheduler.get("thread_alive")), "24시간 자동 점검 루프", 8, warning=True),
        _readiness_check("AI 연구 데몬", bool(daemon.get("running")), "후보 발굴/복기/장기기억 루프", 6, warning=True),
        _readiness_check("텔레그램 보고", bool(telegram.get("configured")) or bool(telegram.get("dry_run")), "사용자 보고 채널", 4, warning=True),
    ]
    total = sum(int(item["weight"]) for item in checks)
    earned = sum(int(item["earned"]) for item in checks)
    score = round((earned / total) * 100, 1) if total else 0.0
    blocked = [item for item in checks if item.get("status") == "blocked"]
    warnings = [item for item in checks if item.get("status") == "warning"]
    live_ready = score >= float(policy.get("min_readiness_score_for_live", 90) or 90) and not blocked and ticket_count >= min_paper and kis_order_mode and live_execution and delegated_authorization_ok
    mode = "실전주문 준비완료" if live_ready else "실전 파일럿 준비 중" if live_execution else "자동연구/Paper 운용" if not bool(policy.get("emergency_halt")) else "긴급정지"
    return {
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "score": score,
        "mode": mode,
        "live_ready": live_ready,
        "live_execution_enabled": bool(policy.get("live_execution_enabled")),
        "delegated_authorization": delegated_authorization,
        "paper_autopilot_enabled": bool(policy.get("paper_autopilot_enabled")),
        "emergency_halt": bool(policy.get("emergency_halt")),
        "blocked_count": len(blocked),
        "warning_count": len(warnings),
        "checks": checks,
        "next_actions": [
            "오토파일럿/AI 연구 데몬을 켜서 paper 리허설 누적" if not scheduler.get("running") or not daemon.get("running") else "",
            f"paper 리허설 {max(0, min_paper - ticket_count)}건 추가 누적" if ticket_count < min_paper else "",
            "승인 대기 후보를 검토하고 dry-submit으로 전송 직전 조건 확인" if int(approvals.get("pending", 0) or 0) else "",
            "긴급정지를 해제해야 자동 후보 생성 가능" if policy.get("emergency_halt") else "",
            str(delegated_authorization.get("message", "")) if not delegated_authorization_ok else "",
        ],
        "safety": "준비도는 자동매매 운영 상태 점검입니다. 실제 브로커 전송은 별도 정책과 승인 게이트를 통과해야 합니다.",
    }


def build_portfolio_target_preview(
    symbols: list[str] | None = None,
    limit: int = 6,
    budget: float | None = None,
    source: str = "portfolio-target-planner",
) -> dict[str, object]:
    policy = OPS.autotrade_policy()
    base_paper = OPS.paper_summary(marks={})
    base_symbols = [
        str(row.get("symbol", "")).upper()
        for row in base_paper.get("positions", [])
        if isinstance(row, dict) and row.get("symbol")
    ]
    base_symbols += [str(item).upper() for item in load_user_watchlist().get("symbols", [])]
    quote_marks, quote_snapshot = build_common_quote_marks(symbols=base_symbols, source="portfolio-target-status")
    ops_status = OPS.status(marks=quote_marks)
    paper = ops_status.get("paper", {}) if isinstance(ops_status.get("paper"), dict) else {}
    market_regime = build_market_regime()
    regime_auto = market_regime.get("automation", {}) if isinstance(market_regime.get("automation"), dict) else {}
    allocation_multiplier = float(regime_auto.get("allocation_multiplier", 1.0) or 1.0)
    new_buy_blocked = bool(regime_auto.get("new_buy_blocked"))
    pipeline = build_ai_pipeline()
    candidates = [item for item in pipeline.get("candidates", []) if isinstance(item, dict)]
    if symbols:
        wanted = {item.upper().strip() for item in symbols if item.strip()}
        candidates = [item for item in candidates if str(item.get("symbol", "")).upper() in wanted]
        missing = wanted - {str(item.get("symbol", "")).upper() for item in candidates}
        for symbol in sorted(missing):
            candidates.append({"symbol": symbol, "name": symbol, "score": 50, "gate": "MANUAL", "lane": "수동"})
    candidates = candidates[: max(1, min(int(limit or 6), 12))]
    candidate_symbols = [str(item.get("symbol", "")).upper().strip() for item in candidates if str(item.get("symbol", "")).strip()]
    target_marks, target_quote_snapshot = build_common_quote_marks(symbols=candidate_symbols, prefer_live=True, source="portfolio-target-candidates")
    target_quote_rows = {
        str(row.get("symbol", "")).upper(): row
        for row in target_quote_snapshot.get("rows", [])
        if isinstance(row, dict) and row.get("symbol")
    }
    cash = float(paper.get("cash", 0) or 0)
    max_order_amount = float(policy.get("max_order_amount", 2_000_000) or 2_000_000)
    max_position_pct = float(policy.get("max_position_pct", 10.0) or 10.0)
    allocation_base = float(budget or min(cash if cash > 0 else OPS.paper_start_cash, max_order_amount * max(1, len(candidates))))
    allocation_base = round(allocation_base * allocation_multiplier, 2)
    score_sum = sum(max(1.0, float(item.get("score", 0) or 0)) for item in candidates) or 1.0
    rows = []
    for item in candidates:
        symbol = str(item.get("symbol", "")).upper().strip()
        if not symbol:
            continue
        score = max(1.0, float(item.get("score", 0) or 0))
        gate = str(item.get("gate") or item.get("risk_gate_status") or "-")
        quote = target_quote_rows.get(symbol, {})
        price = float(target_marks.get(symbol, 0) or 0)
        raw_target = allocation_base * (score / score_sum)
        capped_target = min(raw_target, max_order_amount, OPS.paper_start_cash * max_position_pct / 100.0)
        quantity = int(capped_target // price) if price > 0 else 0
        notional = round(quantity * price, 2)
        ticket = {
            "symbol": symbol,
            "side": "BUY",
            "quantity": quantity,
            "price": price,
            "mode": "paper",
            "source": source,
        }
        checks = OPS.risk_checks(ticket) if quantity > 0 and price > 0 else [
            {"name": "target_quantity", "ok": False, "detail": "가격 또는 목표금액 때문에 매수 가능 수량이 0입니다."}
        ]
        if quote and not bool(quote.get("official_mark_eligible")):
            checks.append(
                {
                    "name": "quote_unit_official_mark",
                    "ok": False,
                    "detail": f"common quote snapshot excluded this mark: {quote.get('unit_status')} / {quote.get('issues', []) or quote.get('warnings', [])}",
                }
            )
        duplicate = OPS.has_today_ticket(symbol, side="BUY", mode="paper", source=source)
        if duplicate:
            checks.append({"name": "same_source_daily_duplicate", "ok": False, "detail": "오늘 같은 출처의 paper 타깃 티켓이 이미 있습니다."})
        if gate not in {"PASSED", "MANUAL"}:
            checks.append({"name": "backtest_gate_passed", "ok": False, "detail": f"게이트 {gate} 상태입니다."})
        if new_buy_blocked:
            checks.append({"name": "market_regime_allows_buy", "ok": False, "detail": f"시장 국면 {market_regime.get('stance', '-')} 상태라 신규 BUY를 차단합니다."})
        ready = bool(quantity > 0 and price > 0 and all(bool(check.get("ok")) for check in checks))
        rows.append(
            {
                "symbol": symbol,
                "name": item.get("name", symbol),
                "market": item.get("market", "KR" if symbol.isdigit() else "US"),
                "score": round(score, 2),
                "gate": gate,
                "lane": item.get("lane", "-"),
                "price": price,
                "quote_snapshot_hash": target_quote_snapshot.get("snapshot_hash"),
                "quote_unit_status": quote.get("unit_status", "missing"),
                "quote_source": quote.get("source", ""),
                "quantity": quantity,
                "target_value": round(capped_target, 2),
                "notional": notional,
                "target_pct_of_paper": round((notional / OPS.paper_start_cash) * 100, 3) if OPS.paper_start_cash else 0,
                "market_regime_stance": market_regime.get("stance"),
                "market_regime_score": market_regime.get("score"),
                "allocation_multiplier": allocation_multiplier,
                "ready": ready,
                "checks": checks,
                "blockers": [check for check in checks if not bool(check.get("ok"))],
                "source": source,
            }
        )
    ready_count = len([row for row in rows if row.get("ready")])
    return {
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "summary": {
            "candidate_count": len(rows),
            "ready_count": ready_count,
            "blocked_count": len(rows) - ready_count,
            "allocation_base": round(allocation_base, 2),
            "market_regime_stance": market_regime.get("stance"),
            "market_regime_score": market_regime.get("score"),
            "allocation_multiplier": allocation_multiplier,
            "new_buy_blocked_by_regime": new_buy_blocked,
            "max_order_amount": max_order_amount,
            "max_position_pct": max_position_pct,
            "emergency_halt": bool(policy.get("emergency_halt")),
            "paper_autopilot_enabled": bool(policy.get("paper_autopilot_enabled")),
        },
        "targets": rows,
        "quote_snapshot": {
            "schema": quote_snapshot.get("schema"),
            "snapshot_hash": quote_snapshot.get("snapshot_hash"),
            "summary": quote_snapshot.get("summary"),
            "blocked": quote_snapshot.get("blocked", [])[:5] if isinstance(quote_snapshot.get("blocked"), list) else [],
        },
        "target_quote_snapshot": {
            "schema": target_quote_snapshot.get("schema"),
            "snapshot_hash": target_quote_snapshot.get("snapshot_hash"),
            "summary": target_quote_snapshot.get("summary"),
            "blocked": target_quote_snapshot.get("blocked", [])[:5] if isinstance(target_quote_snapshot.get("blocked"), list) else [],
        },
        "market_regime": market_regime,
        "policy": policy,
        "safety": "목표 포트폴리오는 paper 리허설 주문 후보만 계산합니다. 브로커 실주문은 전송하지 않습니다.",
    }


def apply_portfolio_targets_to_paper(limit: int = 5, source: str = "portfolio-target-planner") -> dict[str, object]:
    preview = build_portfolio_target_preview(limit=limit, source=source)
    policy = preview.get("policy") if isinstance(preview.get("policy"), dict) else {}
    if policy.get("emergency_halt"):
        return {"ok": False, "applied": [], "preview": preview, "message": "긴급정지 상태라 paper 타깃 적용을 중단했습니다."}
    if not policy.get("paper_autopilot_enabled", True):
        return {"ok": False, "applied": [], "preview": preview, "message": "paper 자동운영이 꺼져 있습니다."}
    applied = []
    for row in preview.get("targets", []):
        if not isinstance(row, dict) or not row.get("ready"):
            continue
        try:
            ticket = OPS.create_order(
                symbol=str(row.get("symbol", "")),
                side="BUY",
                quantity=float(row.get("quantity", 0) or 0),
                price=float(row.get("price", 0) or 0),
                mode="paper",
                source=source,
                memo=f"AI 목표 포트폴리오 paper 적용: score={row.get('score')}, gate={row.get('gate')}",
            )
            applied.append(ticket)
            if ticket.get("status") == "PAPER_FILLED":
                try:
                    queue_simple_trade_telegram(
                        ticket,
                        report_mode="paper",
                        reason=f"목표 포트폴리오 후보 점수 {row.get('score', '-')}·위험 게이트 {row.get('gate', '-')}",
                        source=source,
                    )
                except Exception as exc:
                    JOURNAL.add("PAPER_TELEGRAM_QUEUE_ERROR", str(exc), {"ticket_id": ticket.get("id")})
        except Exception as exc:
            applied.append({"symbol": row.get("symbol"), "status": "APPLY_FAILED", "error": str(exc)})
    OPS.audit("PORTFOLIO_TARGETS_APPLIED", f"AI 목표 포트폴리오 paper 적용 {len(applied)}건", {"applied": applied, "preview_summary": preview.get("summary")})
    return {
        "ok": True,
        "applied_count": len([item for item in applied if isinstance(item, dict) and item.get("status") == "PAPER_FILLED"]),
        "applied": applied,
        "preview": preview,
        "ops_status": build_ops_status(),
        "message": "목표 포트폴리오를 paper 리허설 장부에 적용했습니다.",
    }


