    for item in execution_gate.get("checks", []) if isinstance(execution_gate.get("checks"), list) else []:
        if isinstance(item, dict):
            mark = "통과" if item.get("ok") else "차단" if item.get("severity") == "block" else "주의"
            lines.append(f"- [{mark}] {item.get('label', '-')}: {item.get('state', '-')} / {item.get('detail', '-')}")
    data_freshness = execution_gate.get("data_freshness", {}) if isinstance(execution_gate.get("data_freshness"), dict) else {}
    if data_freshness:
        lines += [
            "",
            "### 데이터 신선도",
            f"- 점검 시각: {data_freshness.get('generated_at', '-')}",
            f"- 계좌 기준: {data_freshness.get('account_source', '-')} / {data_freshness.get('account_updated_at', '-')}",
            f"- 가격 기준: {data_freshness.get('quote_source', '-')} / {data_freshness.get('price_basis', '-')} / {data_freshness.get('quote_updated_at', '-')}",
            f"- 장 상태: {data_freshness.get('market_phase', '-')} / 정규장 {data_freshness.get('regular_open', False)}",
            f"- 주의: {data_freshness.get('warning', '-')}",
        ]
        for check in data_freshness.get("checks", []) if isinstance(data_freshness.get("checks"), list) else []:
            if isinstance(check, dict):
                lines.append(f"- {check.get('label', '-')}: {check.get('status', '-')} / {check.get('detail', '-')}")
    next_trigger_plan = execution_gate.get("next_trigger_plan", []) if isinstance(execution_gate.get("next_trigger_plan"), list) else []
    if next_trigger_plan:
        lines += ["", "### 다음 실행 루틴"]
        for item in next_trigger_plan:
            lines.append(f"- {item}")
    prepared_ticket = execution_gate.get("prepared_ticket", {}) if isinstance(execution_gate.get("prepared_ticket"), dict) else {}
    if prepared_ticket:
        lines += [
            "",
            "### 준비 티켓",
            f"- 상태: {prepared_ticket.get('status', '-')} / {prepared_ticket.get('guard', '-')}",
            f"- 티켓: {prepared_ticket.get('ticket_id', '-')} / 멱등키 {prepared_ticket.get('idempotency_key', '-')}",
            f"- 발급/만료: {prepared_ticket.get('issued_at', '-')} / {prepared_ticket.get('expires_at', '-')}",
            f"- 대상: {prepared_ticket.get('name', '-')} {prepared_ticket.get('side', '-')} {prepared_ticket.get('quantity', 0)}주",
            f"- 예상가/금액: {_format_krw(prepared_ticket.get('estimated_price'))} / {_format_krw(prepared_ticket.get('estimated_notional'))}",
            f"- 근거: {prepared_ticket.get('decision', '-')} / {prepared_ticket.get('reason', '-')}",
            f"- 리스크선: {prepared_ticket.get('risk_line', '-')}",
        ]
        duplicate_guard = prepared_ticket.get("duplicate_guard", {}) if isinstance(prepared_ticket.get("duplicate_guard"), dict) else {}
        if duplicate_guard:
            lines.append(
                f"- 중복 가드: {duplicate_guard.get('status', '-')} / 오늘 동일 제출 {duplicate_guard.get('today_submitted_count', 0)}건 / "
                f"{duplicate_guard.get('detail', '-')}"
            )
        impact = prepared_ticket.get("impact_preview", {}) if isinstance(prepared_ticket.get("impact_preview"), dict) else {}
        if impact:
            cost = impact.get("cost_preview", {}) if isinstance(impact.get("cost_preview"), dict) else {}
            lines += [
                f"- 예상 계좌 영향: 현금 {_format_krw(impact.get('cash_before'))} -> {_format_krw(impact.get('cash_after'))} / "
                f"주식평가 {_format_krw(impact.get('stock_value_before'))} -> {_format_krw(impact.get('stock_value_after'))} / "
                f"추정손익 {_format_krw(impact.get('estimated_pnl'))} ({_safe_pct(impact.get('estimated_pnl_pct'))})",
                f"- 추정 비용: 수수료 {_format_krw(cost.get('broker_fee'))} / 거래세 {_format_krw(cost.get('transaction_tax'))} / 합계 {_format_krw(cost.get('total_cost'))}",
                f"- 영향 메모: {impact.get('note', '-')}",
            ]
    next_report = report_schedule.get("next_slot", {}) if isinstance(report_schedule.get("next_slot"), dict) else {}
    dispatch_state = report_schedule.get("dispatch_state", {}) if isinstance(report_schedule.get("dispatch_state"), dict) else {}
    last_report_run = report_schedule.get("last_run", {}) if isinstance(report_schedule.get("last_run"), dict) else {}
    today_slot_summary = report_schedule.get("today_slot_summary", {}) if isinstance(report_schedule.get("today_slot_summary"), dict) else {}
    next_preview = report_schedule.get("next_preview", {}) if isinstance(report_schedule.get("next_preview"), dict) else {}
