def attach_backtest_risk_gate(result: dict[str, object]) -> dict[str, object]:
    if "backtest_return_reconciliation" not in result:
        result["backtest_return_reconciliation"] = build_backtest_return_reconciliation(result)
    result["risk_gate"] = OPS.evaluate_backtest_risk_gate(result)
    return result


def build_ops_paper_portfolio_payload() -> dict[str, object]:
    base_paper = OPS.paper_summary(marks={})
    quote_symbols = [
        str(row.get("symbol", "")).upper()
        for row in base_paper.get("positions", [])
        if isinstance(row, dict) and row.get("symbol")
    ]
    quote_marks, quote_snapshot = build_common_quote_marks(symbols=quote_symbols, source="paper-portfolio")
    paper = OPS.paper_summary(marks=quote_marks)
    position_unit_audit = build_position_unit_audit(
        paper=paper,
        include_live=False,
        prefer_live_quotes=False,
        source="paper-portfolio-position-unit-audit",
    )
    policy = OPS.autotrade_policy()
    max_orders = int(policy.get("max_daily_orders", OPS.max_daily_orders) or OPS.max_daily_orders)
    max_position_pct = float(policy.get("max_position_pct", 10.0) or 10.0)
    positions = []
    for row in paper.get("positions", []) if isinstance(paper.get("positions"), list) else []:
        if not isinstance(row, dict):
            continue
        positions.append(
            {
                "symbol": row.get("symbol"),
                "quantity": row.get("quantity", 0),
                "price": row.get("mark", row.get("avg_cost", 0)),
                "avg_price": row.get("avg_cost", 0),
                "value": row.get("value", 0),
                "profit_loss": row.get("unrealized_pnl", 0),
                "profit_loss_rate": row.get("unrealized_pct", 0),
            }
        )
    return {
        "ok": True,
        "source": "ops_paper_ledger",
        "cash": paper.get("cash", 0),
        "market_value": paper.get("market_value", 0),
        "equity": paper.get("equity", 0),
        "quote_snapshot": {
            "schema": quote_snapshot.get("schema"),
            "snapshot_hash": quote_snapshot.get("snapshot_hash"),
            "summary": quote_snapshot.get("summary"),
            "blocked": quote_snapshot.get("blocked", [])[:8] if isinstance(quote_snapshot.get("blocked"), list) else [],
        },
        "position_unit_audit": {
            "schema": position_unit_audit.get("schema"),
            "summary": position_unit_audit.get("summary"),
            "blocked": position_unit_audit.get("blocked", [])[:8] if isinstance(position_unit_audit.get("blocked"), list) else [],
        },
        "positions": positions,
        "orders": paper.get("recent_tickets", []),
        "risk": {
            "max_orders": max_orders,
            "used_orders": paper.get("ticket_count", 0),
            "max_position_pct": max_position_pct,
        },
        "paper": paper,
    }


