def _external_signal_report_freshness(
    generated_at: object,
    *,
    now: datetime | None = None,
) -> dict[str, object]:
    """Use the reporting cadence, not only the resident poller, to detect stale data."""
    current = now or datetime.now(_zone("Asia/Seoul", 9))
    if current.tzinfo is None:
        current = current.replace(tzinfo=_zone("Asia/Seoul", 9))
    text = str(generated_at or "").strip()
    generated: datetime | None = None
    if text:
        try:
            generated = datetime.fromisoformat(text.replace("Z", "+00:00"))
            if generated.tzinfo is None:
                generated = generated.replace(tzinfo=current.tzinfo)
            generated = generated.astimezone(current.tzinfo)
        except (TypeError, ValueError):
            generated = None

    minute = current.hour * 60 + current.minute
    weekday = current.weekday() < 5
    if weekday and 7 * 60 <= minute <= 16 * 60 + 30:
        session = "kr_premarket_or_regular"
        default_limit = 180
        env_name = "CODEXSTOCK_EXTERNAL_SIGNAL_INTRADAY_STALE_MINUTES"
    elif weekday and 16 * 60 + 30 < minute <= 23 * 60 + 30:
        session = "kr_after_market"
        default_limit = 360
        env_name = "CODEXSTOCK_EXTERNAL_SIGNAL_AFTERMARKET_STALE_MINUTES"
    else:
        session = "overnight_or_closed"
        default_limit = 720
        env_name = "CODEXSTOCK_EXTERNAL_SIGNAL_CLOSED_STALE_MINUTES"
    try:
        max_age_minutes = max(30, int(os.getenv(env_name, str(default_limit)) or default_limit))
    except (TypeError, ValueError):
        max_age_minutes = default_limit

    if generated is None:
        age_minutes: float | None = None
        fresh = False
        reason = "report_generated_at_missing_or_invalid"
    else:
        age_minutes = max(0.0, (current - generated).total_seconds() / 60.0)
        fresh = age_minutes <= float(max_age_minutes)
        reason = "within_session_freshness_budget" if fresh else "report_older_than_session_budget"
    return {
        "schema": "codexstock_external_signal_freshness_v1",
        "fresh": fresh,
        "status": "fresh" if fresh else "stale",
        "reason": reason,
        "session": session,
        "generated_at": text,
        "checked_at": current.isoformat(timespec="seconds"),
        "age_minutes": round(age_minutes, 2) if age_minutes is not None else None,
        "max_age_minutes": max_age_minutes,
        "candidate_pool_allowed": fresh,
        "score_allowed": False,
        "live_order_allowed": False,
    }


