def _external_signal_text(value: object, max_length: int = 500) -> str:
    return str(value or "").strip()[:max_length]


def _external_signal_forbidden_paths(value: object, path: str = "report") -> list[str]:
    found: list[str] = []
    if isinstance(value, dict):
        for raw_key, child in value.items():
            key = re.sub(r"[^a-z0-9_]+", "_", str(raw_key).lower()).strip("_")
            child_path = f"{path}.{raw_key}"
            if key in EXTERNAL_SIGNAL_FORBIDDEN_KEYS:
                found.append(child_path)
            found.extend(_external_signal_forbidden_paths(child, child_path))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            found.extend(_external_signal_forbidden_paths(child, f"{path}[{index}]"))
    return found[:20]


def _external_signal_string_list(value: object, *, limit: int, item_length: int = 160) -> list[str]:
    if not isinstance(value, list):
        return []
    result: list[str] = []
    for item in value[:limit]:
        text = _external_signal_text(item, item_length)
        if text:
            result.append(text)
    return result


def _normalize_external_signal_sources(
    value: object,
    *,
    fallback_fetched_at: object = "",
    freshness_minutes: int = 0,
) -> tuple[list[dict[str, object]], dict[str, object]]:
    """Keep attached evidence while counting only distinct public publisher domains."""
    raw_sources = value if isinstance(value, list) else []
    sources: list[dict[str, object]] = []
    seen_sources: set[tuple[str, ...]] = set()
    valid_urls: set[str] = set()
    independent_domains: set[str] = set()
    invalid_url_count = 0
    original_body_evidence_count = 0
    original_url_evidence_count = 0
    lineage_complete_source_count = 0
    verified_relevance_source_count = 0
    duplicate_groups: set[str] = set()

    def normalized_timestamp(value: object) -> str:
        parsed, _ = _parse_market_context_observed_at(
            value,
            default_tz=_zone("Asia/Seoul", 9),
        )
        return parsed.isoformat(timespec="seconds") if parsed is not None else ""

    for raw_source in raw_sources[:EXTERNAL_SIGNAL_MAX_SOURCES_PER_SIGNAL]:
        if not isinstance(raw_source, dict):
            continue
        raw_url = _external_signal_text(raw_source.get("url"), 2048)
        url = ""
        independent_domain = ""
        if raw_url:
            try:
                parsed = urlparse(raw_url)
                if (
                    parsed.scheme.lower() in {"http", "https"}
                    and parsed.hostname
                    and not parsed.username
                    and not parsed.password
                ):
                    url = parsed._replace(
                        scheme=parsed.scheme.lower(),
                        netloc=parsed.netloc.lower(),
                        fragment="",
                    ).geturl()
                    independent_domain = _news_independent_domain(url)
                    if independent_domain == "localhost" or re.fullmatch(
                        r"\d{1,3}(?:\.\d{1,3}){3}", independent_domain
                    ):
                        independent_domain = ""
                else:
                    invalid_url_count += 1
            except ValueError:
                invalid_url_count += 1

        raw_original = raw_source.get("original_evidence")
        raw_original = raw_original if isinstance(raw_original, dict) else {}
        try:
            body_char_count = max(0, min(int(raw_original.get("body_char_count", 0) or 0), 10_000_000))
        except (TypeError, ValueError):
            body_char_count = 0
        body_hash = _external_signal_text(raw_original.get("body_hash"), 80).lower()
        raw_item_id = _external_signal_text(raw_original.get("raw_item_id"), 80).lower()
        fetch_status = _external_signal_text(raw_original.get("fetch_status"), 50).upper()
        canonical_url = _external_signal_text(raw_original.get("canonical_url"), 2048)
        canonical_domain = _news_independent_domain(canonical_url) if canonical_url else ""
        canonical_url_matches = bool(
            url
            and canonical_url.startswith(("http://", "https://"))
            and canonical_domain
            and canonical_domain == independent_domain
        )
        body_evidence_attested = bool(
            canonical_url_matches
            and body_char_count > 0
            and re.fullmatch(r"[0-9a-f]{24,64}", body_hash)
            and re.fullmatch(r"[0-9a-f]{24,64}", raw_item_id)
            and fetch_status == "FULL_TEXT_FETCHED"
            and raw_original.get("body_included") is False
        )
        published_at = normalized_timestamp(raw_source.get("published_at"))
        fetched_at = normalized_timestamp(
            raw_source.get("fetched_at")
            or raw_original.get("fetched_at")
            or fallback_fetched_at
        )
        market_timestamp = normalized_timestamp(
            raw_source.get("market_timestamp") or published_at
        )
        expiry_at = normalized_timestamp(raw_source.get("expiry_at"))
        if not expiry_at and published_at and freshness_minutes > 0:
            published_dt, _ = _parse_market_context_observed_at(
                published_at,
                default_tz=_zone("Asia/Seoul", 9),
            )
            if published_dt is not None:
                expiry_at = (
                    published_dt + timedelta(minutes=max(1, freshness_minutes))
                ).isoformat(timespec="seconds")
        raw_relevance = raw_source.get("relevance_score")
        try:
            relevance_score = float(raw_relevance)
            relevance_score_verified = math.isfinite(relevance_score) and 0.0 <= relevance_score <= 1.0
        except (TypeError, ValueError):
            relevance_score = 0.0
            relevance_score_verified = False
        if not relevance_score_verified:
            relevance_score = 0.0
        primary_or_secondary = _external_signal_text(
            raw_source.get("primary_or_secondary"), 30
        ).upper()
        if primary_or_secondary not in {"PRIMARY", "SECONDARY"}:
            source_type = _external_signal_text(raw_source.get("type"), 80).casefold()
            primary_or_secondary = (
                "PRIMARY"
                if source_type in {"official", "disclosure", "regulatory", "filing"}
                else "SECONDARY"
            )
        content_hash = f"sha256:{body_hash}" if body_evidence_attested else ""
        duplicate_seed = body_hash or canonical_url or url
        duplicate_group = (
            "sha256:"
            + hashlib.sha256(duplicate_seed.encode("utf-8")).hexdigest()
            if duplicate_seed
            else ""
        )
        lineage_missing_fields = [
            field
            for field, present in (
                ("source_url", bool(url)),
                ("publisher", bool(_external_signal_text(raw_source.get("name"), 200))),
                ("published_at", bool(published_at)),
                ("fetched_at", bool(fetched_at)),
                ("market_timestamp", bool(market_timestamp)),
                ("content_hash", bool(content_hash)),
                ("duplicate_group", bool(duplicate_group)),
                ("primary_or_secondary", bool(primary_or_secondary)),
                ("relevance_score", relevance_score_verified),
                ("expiry_at", bool(expiry_at)),
            )
            if not present
        ]
        lineage_complete = not lineage_missing_fields
        source = {
            "type": _external_signal_text(raw_source.get("type"), 80),
            "name": _external_signal_text(raw_source.get("name"), 200),
            "publisher": _external_signal_text(raw_source.get("name"), 200),
            "title": _external_signal_text(raw_source.get("title"), 500),
            "url": url,
            "source_url": url,
            "published_at": published_at,
            "fetched_at": fetched_at,
            "market_timestamp": market_timestamp,
            "content_hash": content_hash,
            "duplicate_group": duplicate_group,
            "primary_or_secondary": primary_or_secondary,
            "relevance_score": round(relevance_score, 6),
            "relevance_score_verified": relevance_score_verified,
            "expiry_at": expiry_at,
            "lineage_complete": lineage_complete,
            "lineage_missing_fields": lineage_missing_fields,
            "evidence": _external_signal_text(raw_source.get("evidence"), 1200),
            "independent_domain": independent_domain,
            "original_evidence": {
                "canonical_url": canonical_url if canonical_url_matches else "",
                "raw_item_id": raw_item_id if re.fullmatch(r"[0-9a-f]{24,64}", raw_item_id) else "",
                "body_char_count": body_char_count,
                "body_hash": body_hash if re.fullmatch(r"[0-9a-f]{24,64}", body_hash) else "",
                "fetch_status": fetch_status,
                "body_included": False,
                "canonical_url_matches_source": canonical_url_matches,
                "body_evidence_attested": body_evidence_attested,
            },
        }
        if url:
            identity = ("url", url)
        else:
            identity = (
                "metadata",
                str(source["type"]).casefold(),
                str(source["name"]).casefold(),
                str(source["title"]).casefold(),
                str(source["published_at"]).casefold(),
                str(source["evidence"]).casefold(),
            )
        if identity in seen_sources:
            continue
        seen_sources.add(identity)
        sources.append(source)
        if canonical_url_matches:
            original_url_evidence_count += 1
        if body_evidence_attested:
            original_body_evidence_count += 1
        if relevance_score_verified:
            verified_relevance_source_count += 1
        if duplicate_group:
            duplicate_groups.add(duplicate_group)
        if lineage_complete:
            lineage_complete_source_count += 1
        if url:
            valid_urls.add(url)
        if independent_domain:
            independent_domains.add(independent_domain)

    effective_count = len(independent_domains)
    evidence = {
        "source_count": effective_count,
        "source_count_basis": "independent_structurally_valid_url_domains",
        "attached_source_count": len(sources),
        "valid_source_url_count": len(valid_urls),
        "invalid_source_url_count": invalid_url_count,
        "independent_source_domain_count": effective_count,
        "independent_source_domains": sorted(independent_domains),
        "multi_source_evidence": effective_count >= 2,
        "original_url_evidence_count": original_url_evidence_count,
        "original_body_evidence_count": original_body_evidence_count,
        "original_body_evidence": original_body_evidence_count > 0,
        "original_evidence_basis": "manifest_bound_body_hash_length_and_matching_canonical_domain",
        "lineage_complete_source_count": lineage_complete_source_count,
        "lineage_incomplete_source_count": max(0, len(sources) - lineage_complete_source_count),
        "source_lineage_complete": bool(sources) and lineage_complete_source_count == len(sources),
        "verified_relevance_source_count": verified_relevance_source_count,
        "duplicate_group_count": len(duplicate_groups),
        "lineage_contract_fields": [
            "source_url",
            "publisher",
            "published_at",
            "fetched_at",
            "market_timestamp",
            "content_hash",
            "duplicate_group",
            "primary_or_secondary",
            "relevance_score",
            "expiry_at",
        ],
    }
    return sources, evidence


def _external_signal_context_coverage(context_rows: object) -> dict[str, object]:
    rows = context_rows if isinstance(context_rows, list) else []
    present = sorted(
        {
            str(row.get("category") or "").strip()
            for row in rows
            if isinstance(row, dict) and str(row.get("category") or "").strip() in EXTERNAL_SIGNAL_EXPECTED_CONTEXT_CATEGORIES
        }
    )
    expected = list(EXTERNAL_SIGNAL_EXPECTED_CONTEXT_CATEGORIES)
    missing = [category for category in expected if category not in present]
    ratio = len(present) / len(expected) if expected else 1.0
    return {
        "status": "COMPLETE" if not missing else "INCOMPLETE",
        "coverage_pct": round(ratio * 100, 1),
        "expected_categories": expected,
        "present_categories": present,
        "missing_categories": missing,
        "present_labels": [EXTERNAL_SIGNAL_EXPECTED_CONTEXT_CATEGORIES[item] for item in present],
        "missing_labels": [EXTERNAL_SIGNAL_EXPECTED_CONTEXT_CATEGORIES[item] for item in missing],
        "context_count": len(rows),
    }


def _normalize_external_signal_report(report: object) -> tuple[dict[str, object] | None, list[str]]:
    if not isinstance(report, dict):
        return None, ["report_must_be_object"]
    errors: list[str] = []
    forbidden_paths = _external_signal_forbidden_paths(report)
    if forbidden_paths:
        errors.append("forbidden_secret_fields:" + ",".join(forbidden_paths))
    if _external_signal_text(report.get("schema"), 100) != EXTERNAL_SIGNAL_SCHEMA:
        errors.append("unsupported_schema")
    report_window = report.get("collection_window") if isinstance(report.get("collection_window"), dict) else {}
    fallback_fetched_at = (
        report_window.get("ended_at")
        or report.get("generated_at")
        or ""
    )

    safety = report.get("safety") if isinstance(report.get("safety"), dict) else {}
    if safety.get("decision_scope") != "information_only":
        errors.append("decision_scope_must_be_information_only")
    if safety.get("external_engine_decision") != "VERIFY_ONLY":
        errors.append("external_engine_decision_must_be_VERIFY_ONLY")
    if safety.get("live_order_allowed") is not False:
        errors.append("live_order_allowed_must_be_false")
    if safety.get("requires_codexstock_validation") is not True:
        errors.append("requires_codexstock_validation_must_be_true")

    raw_signals = report.get("signals")
    if not isinstance(raw_signals, list):
        errors.append("signals_must_be_array")
        raw_signals = []
    if len(raw_signals) > EXTERNAL_SIGNAL_MAX_SIGNALS:
        errors.append("too_many_signals")

    signal_ids: set[str] = set()
    signals: list[dict[str, object]] = []
    for index, raw_signal in enumerate(raw_signals[:EXTERNAL_SIGNAL_MAX_SIGNALS]):
        if not isinstance(raw_signal, dict):
            errors.append(f"signal_{index}_must_be_object")
            continue
        signal_id = _external_signal_text(raw_signal.get("signal_id"), 180)
        if not signal_id:
            errors.append(f"signal_{index}_id_required")
            continue
        if signal_id in signal_ids:
            errors.append(f"duplicate_signal_id:{signal_id}")
            continue
        signal_ids.add(signal_id)
        missing_fields = sorted(EXTERNAL_SIGNAL_REQUIRED_FIELDS - set(raw_signal))
        if missing_fields:
            errors.append(f"signal_missing_fields:{signal_id}:{','.join(missing_fields)}")
        if raw_signal.get("live_order_allowed") is not False:
            errors.append(f"signal_live_order_allowed_must_be_false:{signal_id}")
        if raw_signal.get("external_engine_decision") != "VERIFY_ONLY":
            errors.append(f"signal_decision_must_be_VERIFY_ONLY:{signal_id}")

        raw_sources = raw_signal.get("sources")
        if not isinstance(raw_sources, list):
            raw_sources = []
            errors.append(f"signal_sources_must_be_array:{signal_id}")
        if len(raw_sources) > EXTERNAL_SIGNAL_MAX_SOURCES_PER_SIGNAL:
            errors.append(f"too_many_sources:{signal_id}")
        try:
            confidence = max(0.0, min(1.0, float(raw_signal.get("confidence", 0) or 0)))
        except (TypeError, ValueError):
            confidence = 0.0
            errors.append(f"invalid_confidence:{signal_id}")
        try:
            freshness_minutes = max(0, int(raw_signal.get("freshness_minutes", 0) or 0))
        except (TypeError, ValueError):
            freshness_minutes = 0
            errors.append(f"invalid_freshness_minutes:{signal_id}")
        sources, source_evidence = _normalize_external_signal_sources(
            raw_sources,
            fallback_fetched_at=fallback_fetched_at,
            freshness_minutes=freshness_minutes,
        )
        try:
            reported_source_count = max(0, int(raw_signal.get("source_count", len(sources))))
        except (TypeError, ValueError):
            reported_source_count = len(sources)
            errors.append(f"invalid_source_count:{signal_id}")
        signals.append(
            {
                "signal_id": signal_id,
                "detected_at": _external_signal_text(raw_signal.get("detected_at"), 80),
                "symbol": _external_signal_text(raw_signal.get("symbol"), 30).upper(),
                "name": _external_signal_text(raw_signal.get("name"), 200),
                "market": _external_signal_text(raw_signal.get("market"), 30).upper(),
                "theme": _external_signal_text(raw_signal.get("theme"), 200),
                "sentiment": _external_signal_text(raw_signal.get("sentiment"), 40),
                "urgency": _external_signal_text(raw_signal.get("urgency"), 40),
                "confidence": round(confidence, 6),
                "freshness_minutes": freshness_minutes,
                "evidence_summary": _external_signal_text(raw_signal.get("evidence_summary"), 1600),
                "keywords": _external_signal_string_list(raw_signal.get("keywords"), limit=30),
                "risk_flags": _external_signal_string_list(raw_signal.get("risk_flags"), limit=30, item_length=300),
                "requested_codexstock_checks": _external_signal_string_list(
                    raw_signal.get("requested_codexstock_checks"), limit=30
                ),
                **source_evidence,
                "reported_source_count": reported_source_count,
                "source_count_capped": reported_source_count > int(source_evidence["source_count"]),
                "sources": sources,
                "external_engine_decision": "VERIFY_ONLY",
                "live_order_allowed": False,
                "codexstock_validation_status": "PENDING_VERIFY_ONLY",
                "promotion_allowed": False,
            }
        )

    raw_triggers = report.get("urgent_triggers")
    if not isinstance(raw_triggers, list):
        raw_triggers = []
        errors.append("urgent_triggers_must_be_array")
    urgent_triggers: list[dict[str, object]] = []
    for raw_trigger in raw_triggers[:500]:
        if not isinstance(raw_trigger, dict):
            continue
        urgent_triggers.append(
            {
                "trigger_id": _external_signal_text(raw_trigger.get("trigger_id"), 180),
                "type": _external_signal_text(raw_trigger.get("type"), 100),
                "severity": _external_signal_text(raw_trigger.get("severity"), 50),
                "detected_at": _external_signal_text(raw_trigger.get("detected_at"), 80),
                "theme": _external_signal_text(raw_trigger.get("theme"), 200),
                "symbols": _external_signal_string_list(raw_trigger.get("symbols"), limit=50, item_length=30),
                "reason": _external_signal_text(raw_trigger.get("reason"), 600),
            }
        )

    raw_market_context = report.get("market_context", [])
    if not isinstance(raw_market_context, list):
        errors.append("market_context_must_be_array")
        raw_market_context = []
    if len(raw_market_context) > EXTERNAL_SIGNAL_MAX_MARKET_CONTEXT:
        errors.append("too_many_market_context_items")
    market_context: list[dict[str, object]] = []
    context_ids: set[str] = set()
    for index, raw_context in enumerate(raw_market_context[:EXTERNAL_SIGNAL_MAX_MARKET_CONTEXT]):
        if not isinstance(raw_context, dict):
            errors.append(f"market_context_{index}_must_be_object")
            continue
        context_id = _external_signal_text(raw_context.get("context_id"), 180)
        category = _external_signal_text(raw_context.get("category"), 80)
        if not context_id:
            errors.append(f"market_context_{index}_id_required")
            continue
        if context_id in context_ids:
            errors.append(f"duplicate_market_context_id:{context_id}")
            continue
        context_ids.add(context_id)
        missing_fields = sorted(EXTERNAL_SIGNAL_REQUIRED_CONTEXT_FIELDS - set(raw_context))
        if missing_fields:
            errors.append(f"market_context_missing_fields:{context_id}:{','.join(missing_fields)}")
        if category not in EXTERNAL_SIGNAL_EXPECTED_CONTEXT_CATEGORIES:
            errors.append(f"unsupported_market_context_category:{context_id}:{category}")
        if raw_context.get("live_order_allowed") is not False:
            errors.append(f"market_context_live_order_allowed_must_be_false:{context_id}")
        if raw_context.get("external_engine_decision") != "VERIFY_ONLY":
            errors.append(f"market_context_decision_must_be_VERIFY_ONLY:{context_id}")
        raw_sources = raw_context.get("sources")
        if not isinstance(raw_sources, list):
            raw_sources = []
            errors.append(f"market_context_sources_must_be_array:{context_id}")
        if not raw_sources:
            errors.append(f"market_context_source_required:{context_id}")
        if len(raw_sources) > EXTERNAL_SIGNAL_MAX_SOURCES_PER_SIGNAL:
            errors.append(f"too_many_market_context_sources:{context_id}")
        sources, source_evidence = _normalize_external_signal_sources(
            raw_sources,
            fallback_fetched_at=fallback_fetched_at,
            freshness_minutes=24 * 60,
        )
        try:
            confidence = max(0.0, min(1.0, float(raw_context.get("confidence", 0) or 0)))
        except (TypeError, ValueError):
            confidence = 0.0
            errors.append(f"invalid_market_context_confidence:{context_id}")
        try:
            reported_source_count = max(0, int(raw_context.get("source_count", len(sources))))
        except (TypeError, ValueError):
            reported_source_count = len(sources)
            errors.append(f"invalid_market_context_source_count:{context_id}")
        market_context.append(
            {
                "context_id": context_id,
                "category": category,
                "headline": _external_signal_text(raw_context.get("headline"), 500),
                "summary": _external_signal_text(raw_context.get("summary"), 1600),
                "event_name": _external_signal_text(raw_context.get("event_name"), 300),
                "event_at": _external_signal_text(raw_context.get("event_at"), 80),
                "observed_at": _external_signal_text(raw_context.get("observed_at"), 80),
                "timezone": _external_signal_text(raw_context.get("timezone"), 80),
                "official_url": _external_signal_text(raw_context.get("official_url"), 2048),
                "calendar_provider": _external_signal_text(raw_context.get("calendar_provider"), 160),
                "severity": _external_signal_text(raw_context.get("severity"), 50).lower() or "watch",
                "detected_at": _external_signal_text(raw_context.get("detected_at"), 80),
                "markets": _external_signal_string_list(raw_context.get("markets"), limit=20, item_length=30),
                "symbols": _external_signal_string_list(raw_context.get("symbols"), limit=50, item_length=30),
                "impact_channels": _external_signal_string_list(raw_context.get("impact_channels"), limit=20),
                "risk_flags": _external_signal_string_list(raw_context.get("risk_flags"), limit=30, item_length=300),
                "confidence": round(confidence, 6),
                **source_evidence,
                "reported_source_count": reported_source_count,
                "source_count_capped": reported_source_count > int(source_evidence["source_count"]),
                "sources": sources,
                "external_engine_decision": "VERIFY_ONLY",
                "live_order_allowed": False,
                "codexstock_validation_status": "PENDING_VERIFY_ONLY",
            }
        )

    if errors:
        return None, errors[:50]
    engine = report.get("engine") if isinstance(report.get("engine"), dict) else {}
    window = report.get("collection_window") if isinstance(report.get("collection_window"), dict) else {}
    normalized = {
        "schema": EXTERNAL_SIGNAL_SCHEMA,
        "generated_at": _external_signal_text(report.get("generated_at"), 80),
        "report_type": _external_signal_text(report.get("report_type"), 50),
        "report_slot": _external_signal_text(report.get("report_slot"), 50),
        "engine": {
            "name": _external_signal_text(engine.get("name"), 120),
            "version": _external_signal_text(engine.get("version"), 80),
        },
        "collection_window": {
            "started_at": _external_signal_text(window.get("started_at"), 80),
            "ended_at": _external_signal_text(window.get("ended_at"), 80),
        },
        "safety": {
            "decision_scope": "information_only",
            "external_engine_decision": "VERIFY_ONLY",
            "live_order_allowed": False,
            "requires_codexstock_validation": True,
            "promotion_allowed": False,
        },
        "summary": {
            "signal_count": len(signals),
            "urgent_count": len(urgent_triggers),
            "market_context_count": len(market_context),
            "pending_validation_count": len(signals),
            "reported_source_count_total": sum(
                int(row.get("reported_source_count", 0) or 0) for row in [*signals, *market_context]
            ),
            "effective_source_count_total": sum(
                int(row.get("source_count", 0) or 0) for row in [*signals, *market_context]
            ),
            "source_count_inflation_blocked_count": sum(
                1 for row in [*signals, *market_context] if row.get("source_count_capped")
            ),
        },
        "signals": signals,
        "urgent_triggers": urgent_triggers,
        "market_context": market_context,
        "context_coverage": _external_signal_context_coverage(market_context),
    }
    return normalized, []


def _external_signal_signature(report: dict[str, object]) -> str:
    canonical = json.dumps(report, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest()


def _external_signal_alert_semantic_signature(report: dict[str, object], limit: int = 4) -> str:
    """Hash the user-visible event meaning, excluding scan time and changing counters."""
    canonical_items: list[dict[str, str]] = []
    for item in _external_signal_alert_items(report, limit=limit):
        canonical_items.append(
            {
                "kind": str(item.get("kind") or "").strip().lower(),
                "alert_level": str(item.get("alert_level") or "").strip().lower(),
                "symbol": str(item.get("symbol") or "").strip().upper(),
                "name": " ".join(str(item.get("name") or "").split()).strip().lower(),
                "theme": " ".join(str(item.get("theme") or "").split()).strip().lower(),
                "reason": " ".join(str(item.get("reason") or "").split()).strip().lower()[:150],
            }
        )
    if not canonical_items:
        return ""
    canonical_items.sort(key=lambda row: json.dumps(row, ensure_ascii=False, sort_keys=True))
    canonical = json.dumps(
        canonical_items,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest()


def _external_signal_alert_delivery_id(report: dict[str, object], limit: int = 4) -> str:
    semantic_signature = _external_signal_alert_semantic_signature(report, limit=limit)
    if not semantic_signature:
        return ""
    generated_day = str(report.get("generated_at") or "").strip()[:10]
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", generated_day):
        generated_day = datetime.now(ZoneInfo("Asia/Seoul")).date().isoformat()
    return f"external-signal-alert:{generated_day}:{semantic_signature}"


def _external_signal_semantic_text(value: object, limit: int = 1600) -> str:
    return " ".join(str(value or "").split()).strip().casefold()[:limit]


def _external_signal_source_semantic_tokens(value: object) -> list[str]:
    tokens: set[str] = set()
    for source in value if isinstance(value, list) else []:
        if not isinstance(source, dict):
            continue
        original = source.get("original_evidence")
        original = original if isinstance(original, dict) else {}
        identity = {
            "url": _external_signal_semantic_text(
                source.get("source_url") or source.get("url") or original.get("canonical_url"),
                2048,
            ),
            "published_at": _external_signal_semantic_text(source.get("published_at"), 80),
            "content_hash": _external_signal_semantic_text(
                source.get("content_hash") or original.get("body_hash"),
                100,
            ),
            "raw_item_id": _external_signal_semantic_text(original.get("raw_item_id"), 100),
            "title": _external_signal_semantic_text(source.get("title"), 500),
        }
        if any(identity.values()):
            tokens.add(json.dumps(identity, ensure_ascii=False, sort_keys=True, separators=(",", ":")))
    return sorted(tokens)


def _external_signal_verification_semantic_key(signal: dict[str, object]) -> str:
    payload = {
        "symbol": _external_signal_semantic_text(signal.get("symbol"), 30).upper(),
        "name": _external_signal_semantic_text(signal.get("name"), 200),
        "market": _external_signal_semantic_text(signal.get("market"), 30).upper(),
        "theme": _external_signal_semantic_text(signal.get("theme"), 200),
        "sentiment": _external_signal_semantic_text(signal.get("sentiment"), 40),
        "urgency": _external_signal_semantic_text(signal.get("urgency"), 40),
        "evidence_summary": _external_signal_semantic_text(signal.get("evidence_summary"), 1600),
        "keywords": sorted(_external_signal_semantic_text(item, 160) for item in signal.get("keywords", [])),
        "risk_flags": sorted(_external_signal_semantic_text(item, 300) for item in signal.get("risk_flags", [])),
        "requested_checks": sorted(
            _external_signal_semantic_text(item, 160)
            for item in signal.get("requested_codexstock_checks", [])
        ),
        "sources": _external_signal_source_semantic_tokens(signal.get("sources")),
    }
    canonical = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest()


def _external_context_verification_semantic_key(context: dict[str, object]) -> str:
    payload = {
        "category": _external_signal_semantic_text(context.get("category"), 80),
        "headline": _external_signal_semantic_text(context.get("headline"), 500),
        "summary": _external_signal_semantic_text(context.get("summary"), 1600),
        "event_name": _external_signal_semantic_text(context.get("event_name"), 300),
        "event_at": _external_signal_semantic_text(context.get("event_at"), 80),
        "official_url": _external_signal_semantic_text(context.get("official_url"), 2048),
        "severity": _external_signal_semantic_text(context.get("severity"), 50),
        "markets": sorted(_external_signal_semantic_text(item, 30) for item in context.get("markets", [])),
        "symbols": sorted(_external_signal_semantic_text(item, 30).upper() for item in context.get("symbols", [])),
        "impact_channels": sorted(
            _external_signal_semantic_text(item, 160) for item in context.get("impact_channels", [])
        ),
        "risk_flags": sorted(_external_signal_semantic_text(item, 300) for item in context.get("risk_flags", [])),
        "sources": _external_signal_source_semantic_tokens(context.get("sources")),
    }
    canonical = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest()


def _external_signal_report_semantic_signature(report: dict[str, object]) -> str:
    signal_keys = sorted(
        _external_signal_verification_semantic_key(row)
        for row in report.get("signals", [])
        if isinstance(row, dict)
    )
    context_keys = sorted(
        _external_context_verification_semantic_key(row)
        for row in report.get("market_context", [])
        if isinstance(row, dict)
    )
    payload = {
        "signals": signal_keys,
        "market_context": context_keys,
        "alert_signature": _external_signal_alert_semantic_signature(report),
    }
    canonical = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest()


def _external_signal_alert_items(report: dict[str, object], limit: int = 4) -> list[dict[str, object]]:
    """Choose a small, diverse set of urgent external signals for user notification."""
    safe_limit = max(1, min(int(limit or 4), 6))
    triggers = [row for row in report.get("urgent_triggers", []) if isinstance(row, dict)]
    trigger_by_key: dict[str, dict[str, object]] = {}
    for trigger in triggers:
        theme = str(trigger.get("theme") or "").strip()
        symbols = [str(item).strip().upper() for item in trigger.get("symbols", []) if str(item).strip()]
        keys = [theme.lower(), *(symbol.lower() for symbol in symbols)]
        for key in keys:
            if key and key not in trigger_by_key:
                trigger_by_key[key] = trigger

    candidates: list[dict[str, object]] = []
    for context in report.get("market_context", []):
        if not isinstance(context, dict):
            continue
        severity = str(context.get("severity") or "watch").strip().lower()
        category = str(context.get("category") or "").strip()
        if severity not in {"urgent", "critical", "high"}:
            continue
        confidence = max(0.0, min(1.0, _number(context.get("confidence"))))
        source_count = max(0, int(_number(context.get("source_count"))))
        candidates.append(
            {
                "kind": "market_context",
                "alert_level": severity,
                "symbol": "",
                "name": str(context.get("headline") or "시장 중요 정보").strip(),
                "theme": EXTERNAL_SIGNAL_EXPECTED_CONTEXT_CATEGORIES.get(category, category or "시장 이슈"),
                "confidence": confidence,
                "source_count": source_count,
                "reason": str(context.get("summary") or "외부 시장 정보 감지").strip(),
                "risk_flags": [str(item).strip() for item in context.get("risk_flags", []) if str(item).strip()][:2],
                "score": 3.0 + (1.0 if severity == "critical" else 0.5) + confidence + min(source_count, 100) / 200,
            }
        )
    for signal in report.get("signals", []):
        if not isinstance(signal, dict):
            continue
        urgency = str(signal.get("urgency") or "").strip().lower()
        theme = str(signal.get("theme") or "").strip()
        symbol = str(signal.get("symbol") or "").strip().upper()
        matching_trigger = trigger_by_key.get(symbol.lower()) or trigger_by_key.get(theme.lower()) or {}
        trigger_severity = str(matching_trigger.get("severity") or "").strip().lower()
        if urgency not in {"urgent", "critical", "high"} and trigger_severity not in {"urgent", "critical", "high"}:
            continue
        confidence = max(0.0, min(1.0, _number(signal.get("confidence"))))
        source_count = max(0, int(_number(signal.get("source_count"))))
        severity_bonus = 2.0 if urgency == "critical" or trigger_severity == "critical" else 1.0
        alert_level = (
            "critical"
            if "critical" in {urgency, trigger_severity}
            else "urgent"
            if "urgent" in {urgency, trigger_severity}
            else "high"
        )
        score = severity_bonus + confidence + min(source_count, 100) / 200
        candidates.append(
            {
                "kind": "signal",
                "alert_level": alert_level,
                "symbol": symbol,
                "name": str(signal.get("name") or symbol or "시장 이슈").strip(),
                "theme": theme or "기타",
                "confidence": confidence,
                "source_count": source_count,
                "reason": str(matching_trigger.get("reason") or signal.get("evidence_summary") or "반복 언급 증가").strip(),
                "risk_flags": [str(item).strip() for item in signal.get("risk_flags", []) if str(item).strip()][:2],
                "score": score,
            }
        )

    covered_themes = {str(row.get("theme") or "").lower() for row in candidates}
    for trigger in triggers:
        severity = str(trigger.get("severity") or "").strip().lower()
        trigger_type = str(trigger.get("type") or "").strip().lower()
        theme = str(trigger.get("theme") or "").strip() or "시장 이슈"
        if theme.lower() in covered_themes:
            continue
        if severity not in {"urgent", "critical", "high"} and trigger_type not in {"datalab_spike", "multi_source_spike"}:
            continue
        symbols = [str(item).strip().upper() for item in trigger.get("symbols", []) if str(item).strip()]
        candidates.append(
            {
                "kind": "trigger",
                "alert_level": severity or "watch",
                "symbol": symbols[0] if symbols else "",
                "name": ", ".join(symbols[:3]) if symbols else "시장 전체",
                "theme": theme,
                "confidence": 0.0,
                "source_count": 0,
                "reason": str(trigger.get("reason") or "외부 관심도 급증").strip(),
                "risk_flags": [],
                "score": 1.5 if severity in {"critical", "high", "urgent"} else 0.8,
            }
        )

    candidates.sort(key=lambda row: (-float(row.get("score", 0) or 0), str(row.get("theme") or "")))
    selected: list[dict[str, object]] = []
    seen: set[str] = set()
    for row in candidates:
        key = f"{row.get('symbol')}|{str(row.get('theme') or '').lower()}"
        if key in seen:
            continue
        seen.add(key)
        selected.append(row)
        if len(selected) >= safe_limit:
            break
    return selected


def build_external_signal_telegram_text(report: dict[str, object], limit: int = 4) -> str:
    items = _external_signal_alert_items(report, limit=limit)
    if not items:
        return ""
    generated_at = str(report.get("generated_at") or "").strip()
    lines = ["[외부정보·검증중]", "외부 탐색 엔진이 중요한 반복 언급을 감지했습니다."]
    for row in items:
        name = str(row.get("name") or "시장 전체")
        symbol = str(row.get("symbol") or "")
        subject = f"{name}({symbol})" if symbol and symbol not in name else name
        theme = str(row.get("theme") or "시장 이슈")
        source_count = int(row.get("source_count", 0) or 0)
        confidence = float(row.get("confidence", 0) or 0)
        detail = []
        if source_count:
            detail.append(f"출처 {source_count}곳")
        if confidence:
            detail.append(f"신뢰 {confidence * 100:.0f}%")
        suffix = f" ({', '.join(detail)})" if detail else ""
        lines.append(f"- {theme}: {subject}{suffix}")
        reason = " ".join(str(row.get("reason") or "").split())[:150]
        if reason:
            lines.append(f"  감지 이유: {reason}")
    if generated_at:
        lines.append(f"수집 시각: {generated_at}")
    coverage = (
        report.get("context_coverage")
        if isinstance(report.get("context_coverage"), dict)
        else _external_signal_context_coverage(report.get("market_context", []))
    )
    missing_labels = [str(item) for item in coverage.get("missing_labels", []) if str(item)]
    if missing_labels:
        lines.append("이번 보고서에서 빠진 영역: " + ", ".join(missing_labels))
    lines.extend(
        [
            "상태: 원출처·시세·재료 지속성을 코덱스스톡이 교차검증 중입니다.",
            "주의: 이 알림만으로 실제 주문하지 않습니다.",
        ]
    )
    return "\n".join(lines)


def _queue_external_signal_telegram_alert(
    report: dict[str, object],
    *,
    report_signature: str,
    source: str,
) -> dict[str, object]:
    """Keep scout reports inside CodexStock; only the secretary reports to users."""
    text = build_external_signal_telegram_text(report)
    if not text:
        return {"status": "not_urgent", "queued": False}
    semantic_signature = _external_signal_alert_semantic_signature(report)
    delivery_id = _external_signal_alert_delivery_id(report)
    return {
        "status": "internal_only",
        "queued": False,
        "route": "external-scout->codexstock-verification",
        "report_signature": report_signature,
        "external_source": source,
        "generated_at": report.get("generated_at", ""),
        "semantic_signature": semantic_signature,
        "single_delivery_id": delivery_id,
        "live_order_allowed": False,
        "verification_required": True,
        "reason": "외부 탐색 원문은 코덱스스톡 내부 검증용이며 사용자에게 직접 발송하지 않습니다.",
    }


def _external_signal_manifest_binding(
    manifest: dict[str, object],
    report: dict[str, object],
    *,
    report_path: Path,
    source_fingerprint: str,
) -> dict[str, object]:
    """Cross-check the bridge manifest against the exact report bytes read by CodexStock."""
    contract = manifest.get("codexstock_receiver_contract")
    contract = contract if isinstance(contract, dict) else {}
    expected_path = os.path.normcase(os.path.abspath(str(report_path)))
    declared_paths = {
        "latest_json": str(manifest.get("latest_json") or "").strip(),
        "contract_read_file": str(contract.get("read_file") or "").strip(),
    }
    checks = {
        "latest_json_path_matched": bool(
            declared_paths["latest_json"]
            and os.path.normcase(os.path.abspath(declared_paths["latest_json"])) == expected_path
        ),
        "contract_read_path_matched": bool(
            declared_paths["contract_read_file"]
            and os.path.normcase(os.path.abspath(declared_paths["contract_read_file"])) == expected_path
        ),
        "report_schema_matched": str(manifest.get("report_schema") or "") == str(report.get("schema") or ""),
        "generated_at_matched": str(manifest.get("latest_report_generated_at") or "")
        == str(report.get("generated_at") or ""),
        "report_type_matched": str(manifest.get("latest_report_type") or "")
        == str(report.get("report_type") or ""),
        "report_slot_matched": str(manifest.get("latest_report_slot") or "")
        == str(report.get("report_slot") or ""),
        "signal_count_matched": int(_number(manifest.get("signal_count")))
        == len(report.get("signals", [])) if isinstance(report.get("signals"), list) else False,
        "urgent_count_matched": int(_number(manifest.get("urgent_count")))
        == len(report.get("urgent_triggers", [])) if isinstance(report.get("urgent_triggers"), list) else False,
    }
    declared_hash = str(
        manifest.get("report_sha256")
        or manifest.get("latest_json_sha256")
        or contract.get("report_sha256")
        or ""
    ).strip().lower()
    hash_declared = bool(declared_hash)
    hash_matched = bool(
        not hash_declared
        or (
            re.fullmatch(r"[0-9a-f]{64}", declared_hash)
            and hmac.compare_digest(declared_hash, source_fingerprint.lower())
        )
    )
    checks["declared_sha256_matched"] = hash_matched
    blockers = sorted(name for name, passed in checks.items() if not passed)
    return {
        "schema": "codexstock_external_signal_manifest_binding_v1",
        "passed": not blockers,
        "checks": checks,
        "blockers": blockers,
        "source_fingerprint": source_fingerprint,
        "hash_declared": hash_declared,
        "hash_binding_mode": "manifest_sha256" if hash_declared else "receiver_computed_legacy_manifest",
        "report_path": str(report_path),
    }


def _ensure_external_signal_stage2_snapshot(
    report: dict[str, object], report_signature: str
) -> dict[str, object]:
    with EXTERNAL_SIGNAL_STAGE2_LOCK:
        try:
            cached = json.loads(EXTERNAL_SIGNAL_STAGE2_SNAPSHOT_FILE.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            cached = {}
        if cached.get("report_signature") == report_signature and cached.get("ready"):
            return {**cached, "cached": True}

        symbols: list[str] = []
        for signal in report.get("signals", []) if isinstance(report.get("signals"), list) else []:
            if not isinstance(signal, dict):
                continue
            symbol = _external_signal_text(signal.get("symbol"), 30).upper()
            if symbol and symbol not in symbols:
                symbols.append(symbol)
        selected_symbols = symbols[:5]
        if not selected_symbols:
            state = {
                "schema": "codexstock_external_signal_stage2_snapshot_v1",
                "ready": False,
                "status": "NO_SIGNAL_SYMBOLS",
                "report_signature": report_signature,
                "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
                "symbols": [],
                "live_order_allowed": False,
                "promotion_allowed": False,
            }
        else:
            snapshot_result = EXTERNAL_KNOWLEDGE.build_common_snapshot_from_ohlcv_cache(
                symbols=selected_symbols,
                max_symbols=len(selected_symbols),
                max_rows_per_symbol=120,
                action="run_external_backtest",
                package_id=f"external-signal-{report_signature[:12]}",
                record=True,
                source="external-signal-stage2-snapshot",
            )
            snapshot = (
                snapshot_result.get("recorded_dataset_snapshot")
                if isinstance(snapshot_result.get("recorded_dataset_snapshot"), dict)
                else snapshot_result.get("dataset_snapshot_preview")
                if isinstance(snapshot_result.get("dataset_snapshot_preview"), dict)
                else {}
            )
            state = {
                "schema": "codexstock_external_signal_stage2_snapshot_v1",
                "ready": bool(snapshot_result.get("ok") and snapshot.get("dataset_hash")),
                "status": str(snapshot_result.get("status") or "NOT_READY").upper(),
                "report_signature": report_signature,
                "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
                "symbols": selected_symbols,
                "snapshot_id": snapshot.get("snapshot_id", ""),
                "dataset_hash": snapshot.get("dataset_hash", ""),
                "row_count": snapshot.get("row_count", 0),
                "symbol_count": snapshot.get("symbol_count", 0),
                "dataset_integrity": snapshot.get("dataset_integrity", {}),
                "missing_symbols": snapshot_result.get("missing_symbols", []),
                "stage2_required_blockers": snapshot_result.get("stage2_required_blockers", []),
                "live_order_allowed": False,
                "promotion_allowed": False,
                "safety": "CodexStock common data snapshot only; no external runtime or live order was executed.",
            }
        EXTERNAL_SIGNAL_STAGE2_SNAPSHOT_FILE.parent.mkdir(parents=True, exist_ok=True)
        temp_path = EXTERNAL_SIGNAL_STAGE2_SNAPSHOT_FILE.with_suffix(".tmp")
        temp_path.write_text(json.dumps(state, ensure_ascii=False, indent=2, sort_keys=True), encoding="utf-8")
        temp_path.replace(EXTERNAL_SIGNAL_STAGE2_SNAPSHOT_FILE)
        return {**state, "cached": False}


def _build_external_signal_news_verification(
    report: dict[str, object],
) -> dict[str, dict[str, object]]:
    """Bind original-body provenance and contemporaneous DART evidence to each signal."""
    signals = [
        row for row in report.get("signals", [])
        if isinstance(row, dict)
    ] if isinstance(report.get("signals"), list) else []
    try:
        corp_map = load_dart_corp_code_map(force=False)
    except Exception:
        corp_map = {}

    signal_corporations: dict[str, list[dict[str, str]]] = {}
    required_corporations: dict[str, dict[str, str]] = {}
    for signal in signals:
        signal_id = _external_signal_text(signal.get("signal_id"), 180)
        symbol = _external_signal_text(signal.get("symbol"), 30).zfill(6)
        sources = signal.get("sources") if isinstance(signal.get("sources"), list) else []
        claim_text = " ".join(
            [
                _external_signal_text(signal.get("name"), 200),
                _external_signal_text(signal.get("theme"), 200),
                _external_signal_text(signal.get("evidence_summary"), 1600),
                *[
                    _external_signal_text(source.get("title"), 500)
                    for source in sources
                    if isinstance(source, dict)
                ],
            ]
        )
        corporations: list[dict[str, str]] = []
        exact = corp_map.get(symbol) if isinstance(corp_map, dict) else None
        if isinstance(exact, dict) and exact.get("corp_code"):
            corporations.append({
                "stock_code": str(exact.get("stock_code") or symbol).zfill(6),
                "corp_code": str(exact.get("corp_code") or ""),
                "name": str(exact.get("name") or signal.get("name") or ""),
            })
        if not corporations and corp_map:
            corporations = _match_news_dart_corporations(claim_text, corp_map, limit=2)
        signal_corporations[signal_id] = corporations
        if _news_material_tags(claim_text):
            for corp in corporations:
                if corp.get("corp_code"):
                    required_corporations[corp["corp_code"]] = corp

    disclosure_responses: dict[str, dict[str, object]] = {}
    if required_corporations:
        with ThreadPoolExecutor(max_workers=min(3, len(required_corporations))) as executor:
            futures = {
                executor.submit(
                    INTEGRATIONS.dart_disclosures,
                    corp_code=corp_code,
                    days=14,
                    page_count=20,
                ): corp_code
                for corp_code in list(required_corporations)[:6]
            }
            for future in as_completed(futures):
                corp_code = futures[future]
                try:
                    response = future.result()
                    disclosure_responses[corp_code] = response if isinstance(response, dict) else {}
                except Exception as exc:
                    disclosure_responses[corp_code] = {"items": [], "error": _external_signal_text(exc, 240)}

    now = datetime.now(_zone("Asia/Seoul", 9))
    results: dict[str, dict[str, object]] = {}
    for signal in signals:
        signal_id = _external_signal_text(signal.get("signal_id"), 180)
        sources = [
            source for source in signal.get("sources", [])
            if isinstance(source, dict)
        ] if isinstance(signal.get("sources"), list) else []
        claim_text = " ".join(
            [
                _external_signal_text(signal.get("name"), 200),
                _external_signal_text(signal.get("theme"), 200),
                _external_signal_text(signal.get("evidence_summary"), 1600),
                *[_external_signal_text(source.get("title"), 500) for source in sources],
            ]
        )
        material_tags = sorted(_news_material_tags(claim_text))
        disclosure_required = bool(material_tags)
        original_body_count = sum(
            1
            for source in sources
            if isinstance(source.get("original_evidence"), dict)
            and source["original_evidence"].get("body_evidence_attested") is True
        )
        independent_domains = sorted({
            str(source.get("independent_domain") or "")
            for source in sources
            if str(source.get("independent_domain") or "")
        })
        lineage_complete_count = sum(
            1 for source in sources if source.get("lineage_complete") is True
        )
        verified_relevance_count = sum(
            1 for source in sources if source.get("relevance_score_verified") is True
        )
        disclosure_matches: list[dict[str, object]] = []
        seen_receipts: set[str] = set()
        for corp in signal_corporations.get(signal_id, []):
            response = disclosure_responses.get(corp.get("corp_code", ""), {})
            items = response.get("items") if isinstance(response.get("items"), list) else []
            for disclosure in items:
                if not isinstance(disclosure, dict):
                    continue
                for source in sources:
                    matched, matched_tags, day_distance = _dart_disclosure_matches_news(
                        source.get("title"),
                        source.get("published_at"),
                        disclosure,
                        now=now,
                    )
                    if not matched:
                        continue
                    receipt_number = str(disclosure.get("rcept_no") or "")
                    if receipt_number in seen_receipts:
                        continue
                    seen_receipts.add(receipt_number)
                    disclosure_matches.append({
                        "corp_code": corp.get("corp_code", ""),
                        "stock_code": corp.get("stock_code", ""),
                        "corp_name": corp.get("name", ""),
                        "report_name": _external_signal_text(disclosure.get("report_nm"), 300),
                        "receipt_date": _external_signal_text(disclosure.get("rcept_dt"), 20),
                        "receipt_number": receipt_number,
                        "source_url": _dart_disclosure_source_url(disclosure),
                        "matched_material_tags": matched_tags,
                        "date_distance_days": day_distance,
                        "official_source": "DART",
                    })
        checks = {
            "original_body_evidence_passed": original_body_count > 0,
            "multi_source_evidence_passed": len(independent_domains) >= 2,
            "official_disclosure_gate_passed": not disclosure_required or bool(disclosure_matches),
            "source_lineage_bundle_passed": bool(sources)
            and lineage_complete_count == len(sources)
            and verified_relevance_count == len(sources),
        }
        blockers = sorted(name for name, passed in checks.items() if not passed)
        results[signal_id] = {
            "schema": "codexstock_external_news_evidence_v1",
            "signal_id": signal_id,
            "checked_at": now.isoformat(timespec="seconds"),
            "status": "EVIDENCE_READY_FOR_STAGE2" if not blockers else "EVIDENCE_BLOCKED",
            "checks": checks,
            "blockers": blockers,
            "original_body_evidence_count": original_body_count,
            "independent_source_domain_count": len(independent_domains),
            "independent_source_domains": independent_domains,
            "source_lineage_complete_count": lineage_complete_count,
            "source_lineage_incomplete_count": max(0, len(sources) - lineage_complete_count),
            "verified_relevance_source_count": verified_relevance_count,
            "source_lineage_contract_fields": [
                "source_url",
                "publisher",
                "published_at",
                "fetched_at",
                "market_timestamp",
                "content_hash",
                "duplicate_group",
                "primary_or_secondary",
                "relevance_score",
                "expiry_at",
            ],
            "material_tags": material_tags,
            "official_disclosure_required": disclosure_required,
            "official_disclosure_match_count": len(disclosure_matches),
            "official_disclosure_matches": disclosure_matches[:6],
            "matched_corporations": signal_corporations.get(signal_id, []),
            "score_allowed": False,
            "promotion_allowed": False,
            "live_order_allowed": False,
        }
    return results


def _enqueue_external_signal_verification_requests(
    report: dict[str, object], *, received_at: str, source: str, report_signature: str,
    stage2_snapshot: dict[str, object] | None = None,
    news_verification: dict[str, dict[str, object]] | None = None,
) -> int:
    existing = _read_jsonl(EXTERNAL_SIGNAL_VERIFICATION_QUEUE_FILE)
    seen_keys = {str(row.get("dedupe_key", "")) for row in existing if row.get("dedupe_key")}
    seen_semantic_keys = {
        str(row.get("semantic_key", "")) for row in existing if row.get("semantic_key")
    }
    generated_at = _external_signal_text(report.get("generated_at"), 80)
    enqueued = 0
    for signal in report.get("signals", []) if isinstance(report.get("signals"), list) else []:
        if not isinstance(signal, dict):
            continue
        signal_id = _external_signal_text(signal.get("signal_id"), 180)
        dedupe_key = f"{generated_at}:{signal_id}"
        semantic_key = _external_signal_verification_semantic_key(signal)
        if (
            not generated_at
            or not signal_id
            or dedupe_key in seen_keys
            or semantic_key in seen_semantic_keys
        ):
            continue
        request = {
            "schema": "codexstock_external_signal_verification_request_v1",
            "dedupe_key": dedupe_key,
            "semantic_key": semantic_key,
            "received_at": received_at,
            "received_from": source,
            "report_signature": report_signature,
            "action": "VERIFY_ONLY",
            "status": "PENDING_CODEXSTOCK_CHECKS",
            "signal_id": signal_id,
            "symbol": signal.get("symbol", ""),
            "name": signal.get("name", ""),
            "market": signal.get("market", ""),
            "theme": signal.get("theme", ""),
            "confidence": signal.get("confidence", 0),
            "urgency": signal.get("urgency", ""),
            "requested_checks": signal.get("requested_codexstock_checks", []),
            "risk_flags": signal.get("risk_flags", []),
            "source_count": signal.get("source_count", 0),
            "source_evidence": {
                "original_body_evidence_count": signal.get("original_body_evidence_count", 0),
                "original_url_evidence_count": signal.get("original_url_evidence_count", 0),
                "independent_source_domain_count": signal.get("independent_source_domain_count", 0),
                "independent_source_domains": signal.get("independent_source_domains", []),
                "multi_source_evidence": signal.get("multi_source_evidence", False),
                "lineage_complete_source_count": signal.get("lineage_complete_source_count", 0),
                "lineage_incomplete_source_count": signal.get("lineage_incomplete_source_count", 0),
                "source_lineage_complete": signal.get("source_lineage_complete", False),
                "verified_relevance_source_count": signal.get("verified_relevance_source_count", 0),
                "duplicate_group_count": signal.get("duplicate_group_count", 0),
                "lineage_contract_fields": signal.get("lineage_contract_fields", []),
            },
            "news_verification": (news_verification or {}).get(signal_id, {}),
            "stage2_snapshot_status": (stage2_snapshot or {}).get("status", "NOT_READY"),
            "stage2_snapshot_id": (stage2_snapshot or {}).get("snapshot_id", ""),
            "stage2_dataset_hash": (stage2_snapshot or {}).get("dataset_hash", ""),
            "stage2_snapshot_ready": bool((stage2_snapshot or {}).get("ready")),
            "live_order_allowed": False,
            "promotion_allowed": False,
        }
        _append_jsonl(EXTERNAL_SIGNAL_VERIFICATION_QUEUE_FILE, request)
        seen_keys.add(dedupe_key)
        seen_semantic_keys.add(semantic_key)
        enqueued += 1
    if enqueued:
        _compact_jsonl(EXTERNAL_SIGNAL_VERIFICATION_QUEUE_FILE, max_rows=4000)
    return enqueued


def _external_context_requested_checks(category: str) -> list[str]:
    return {
        "macro_economy": ["official_macro_source_check", "ecos_fred_cross_check", "published_at_check"],
        "economic_calendar": ["official_event_calendar_check", "event_time_timezone_check", "market_impact_check"],
        "capital_flows": ["official_flow_statistics_check", "kis_supply_cross_check", "currency_unit_check"],
        "fx_rates": ["fx_quote_snapshot_check", "ecos_fred_cross_check", "currency_unit_check"],
        "global_markets": ["global_quote_snapshot_check", "market_session_check", "currency_unit_check"],
        "market_news": ["original_source_check", "multi_source_duplicate_check", "published_at_check"],
    }.get(category, ["original_source_check", "published_at_check"])


def _enqueue_external_context_verification_requests(
    report: dict[str, object], *, received_at: str, source: str, report_signature: str
) -> int:
    existing = _read_jsonl(EXTERNAL_CONTEXT_VERIFICATION_QUEUE_FILE)
    seen_keys = {str(row.get("dedupe_key", "")) for row in existing if row.get("dedupe_key")}
    seen_semantic_keys = {
        str(row.get("semantic_key", "")) for row in existing if row.get("semantic_key")
    }
    generated_at = _external_signal_text(report.get("generated_at"), 80)
    enqueued = 0
    for context in report.get("market_context", []) if isinstance(report.get("market_context"), list) else []:
        if not isinstance(context, dict):
            continue
        context_id = _external_signal_text(context.get("context_id"), 180)
        dedupe_key = f"{generated_at}:{context_id}"
        semantic_key = _external_context_verification_semantic_key(context)
        if (
            not generated_at
            or not context_id
            or dedupe_key in seen_keys
            or semantic_key in seen_semantic_keys
        ):
            continue
        category = str(context.get("category") or "").strip()
        request = {
            "schema": "codexstock_external_context_verification_request_v1",
            "dedupe_key": dedupe_key,
            "semantic_key": semantic_key,
            "received_at": received_at,
            "received_from": source,
            "report_signature": report_signature,
            "action": "VERIFY_ONLY",
            "status": "PENDING_CONTEXT_CROSS_CHECKS",
            "context_id": context_id,
            "category": category,
            "headline": context.get("headline", ""),
            "severity": context.get("severity", "watch"),
            "confidence": context.get("confidence", 0),
            "source_count": context.get("source_count", 0),
            "requested_checks": _external_context_requested_checks(category),
            "impact_channels": context.get("impact_channels", []),
            "risk_flags": context.get("risk_flags", []),
            "score_allowed": False,
            "live_order_allowed": False,
            "promotion_allowed": False,
        }
        _append_jsonl(EXTERNAL_CONTEXT_VERIFICATION_QUEUE_FILE, request)
        seen_keys.add(dedupe_key)
        seen_semantic_keys.add(semantic_key)
        enqueued += 1
    if enqueued:
        _compact_jsonl(EXTERNAL_CONTEXT_VERIFICATION_QUEUE_FILE, max_rows=4000)
    return enqueued


def _external_signal_snapshot_validation_result(
    request: dict[str, object],
    *,
    report_signature: str,
    stage2_snapshot: dict[str, object],
    verified_at: str | None = None,
) -> dict[str, object]:
    """Bind one external signal to CodexStock's immutable common snapshot."""
    snapshot_integrity = (
        stage2_snapshot.get("dataset_integrity")
        if isinstance(stage2_snapshot.get("dataset_integrity"), dict)
        else {}
    )
    snapshot_symbols = {
        _external_signal_text(symbol, 30).upper()
        for symbol in stage2_snapshot.get("symbols", [])
        if _external_signal_text(symbol, 30)
    } if isinstance(stage2_snapshot.get("symbols"), list) else set()
    request_hash = str(request.get("stage2_dataset_hash") or "").strip().lower()
    snapshot_hash = str(stage2_snapshot.get("dataset_hash") or "").strip().lower()
    request_snapshot_id = str(request.get("stage2_snapshot_id") or "").strip()
    snapshot_id = str(stage2_snapshot.get("snapshot_id") or "").strip()
    symbol = _external_signal_text(request.get("symbol"), 30).upper()
    checks = {
        "report_signature_matched": bool(
            report_signature
            and str(request.get("report_signature") or "") == report_signature
            and str(stage2_snapshot.get("report_signature") or "") == report_signature
        ),
        "snapshot_ready": bool(stage2_snapshot.get("ready")),
        "snapshot_identity_matched": bool(snapshot_id and request_snapshot_id == snapshot_id),
        "dataset_hash_matched": bool(
            re.fullmatch(r"[0-9a-f]{64}", snapshot_hash)
            and request_hash == snapshot_hash
        ),
        "dataset_integrity_passed": bool(
            snapshot_integrity.get("ok")
            and int(_number(snapshot_integrity.get("fatal_issue_count"))) == 0
        ),
        "symbol_in_snapshot": bool(symbol and symbol in snapshot_symbols),
        "no_live_order_passed": request.get("live_order_allowed") is False,
    }
    blockers = sorted(name for name, passed in checks.items() if not passed)
    snapshot_passed = not blockers
    return {
        "schema": "codexstock_external_signal_snapshot_validation_v1",
        "dedupe_key": str(request.get("dedupe_key") or ""),
        "signal_id": str(request.get("signal_id") or ""),
        "symbol": symbol,
        "report_signature": report_signature,
        "verified_at": verified_at or datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        "status": "SNAPSHOT_VERIFIED_PENDING_STAGE2_RESULT" if snapshot_passed else "SNAPSHOT_BLOCKED",
        "stage2_snapshot_id": snapshot_id,
        "stage2_dataset_hash": snapshot_hash,
        "snapshot_validation": {
            "passed": snapshot_passed,
            "checks": checks,
            "blockers": blockers,
            "snapshot_symbol_count": len(snapshot_symbols),
            "dataset_row_count": snapshot_integrity.get("row_count", stage2_snapshot.get("row_count", 0)),
            "currencies": snapshot_integrity.get("currencies", {}),
            "markets": snapshot_integrity.get("markets", {}),
        },
        "validation_grade": "SNAPSHOT_ONLY" if snapshot_passed else "BLOCKED",
        "stage2_result_gate_passed": False,
        "score_allowed": False,
        "promotion_allowed": False,
        "live_order_allowed": False,
    }


def _reconcile_external_signal_snapshot_queue(
    *, report_signature: str, stage2_snapshot: dict[str, object]
) -> dict[str, int]:
    requests = _read_jsonl(EXTERNAL_SIGNAL_VERIFICATION_QUEUE_FILE)
    existing_results = _read_jsonl(EXTERNAL_SIGNAL_VERIFICATION_RESULT_FILE)
    seen = {
        (
            str(row.get("dedupe_key") or ""),
            str(row.get("stage2_dataset_hash") or ""),
        )
        for row in existing_results
    }
    verified = 0
    blocked = 0
    skipped = 0
    for request in requests:
        if str(request.get("report_signature") or "") != report_signature:
            continue
        key = (
            str(request.get("dedupe_key") or ""),
            str(stage2_snapshot.get("dataset_hash") or ""),
        )
        if not key[0] or key in seen:
            skipped += 1
            continue
        result = _external_signal_snapshot_validation_result(
            request,
            report_signature=report_signature,
            stage2_snapshot=stage2_snapshot,
        )
        _append_jsonl(EXTERNAL_SIGNAL_VERIFICATION_RESULT_FILE, result)
        seen.add(key)
        if result["status"] == "SNAPSHOT_VERIFIED_PENDING_STAGE2_RESULT":
            verified += 1
        else:
            blocked += 1
    if verified or blocked:
        _compact_jsonl(EXTERNAL_SIGNAL_VERIFICATION_RESULT_FILE, max_rows=4000)
    return {"verified": verified, "blocked": blocked, "skipped": skipped}


def receive_external_signal_report(report: object, source: str = "external-info-scout") -> tuple[dict[str, object], int]:
    normalized, errors = _normalize_external_signal_report(report)
    received_at = datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds")
    source_name = _external_signal_text(source, 120) or "external-info-scout"
    if normalized is None:
        receipt = {
            "schema": "codexstock_external_signal_receipt_v1",
            "status": "REJECTED",
            "received_at": received_at,
            "source": source_name,
            "errors": errors,
            "live_order_allowed": False,
        }
        with EXTERNAL_SIGNAL_INBOX_LOCK:
            _append_jsonl(EXTERNAL_SIGNAL_RECEIPT_FILE, receipt)
            _compact_jsonl(EXTERNAL_SIGNAL_RECEIPT_FILE, max_rows=2000)
        return receipt, 400

    signature = _external_signal_signature(normalized)
    try:
        existing_envelope = json.loads(EXTERNAL_SIGNAL_LATEST_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        existing_envelope = {}
    existing_report = (
        existing_envelope.get("report")
        if isinstance(existing_envelope.get("report"), dict)
        else {}
    )
    report_semantic_signature = _external_signal_report_semantic_signature(normalized)
    existing_report_semantic_signature = _external_signal_report_semantic_signature(existing_report)
    semantic_report_duplicate = bool(
        report_semantic_signature
        and report_semantic_signature == existing_report_semantic_signature
    )
    if existing_envelope.get("report_signature") == signature and isinstance(
        existing_envelope.get("news_verification"), dict
    ):
        news_verification = existing_envelope["news_verification"]
    else:
        try:
            news_verification = _build_external_signal_news_verification(normalized)
        except Exception as exc:
            news_verification = {
                _external_signal_text(signal.get("signal_id"), 180): {
                    "schema": "codexstock_external_news_evidence_v1",
                    "signal_id": _external_signal_text(signal.get("signal_id"), 180),
                    "status": "EVIDENCE_ERROR",
                    "checks": {
                        "original_body_evidence_passed": False,
                        "multi_source_evidence_passed": False,
                        "official_disclosure_gate_passed": False,
                        "source_lineage_bundle_passed": False,
                    },
                    "blockers": ["news_evidence_build_error"],
                    "error": _external_signal_text(exc, 500),
                    "score_allowed": False,
                    "promotion_allowed": False,
                    "live_order_allowed": False,
                }
                for signal in normalized.get("signals", [])
                if isinstance(signal, dict)
            }
    try:
        stage2_snapshot = _ensure_external_signal_stage2_snapshot(normalized, signature)
    except Exception as exc:
        stage2_snapshot = {
            "ready": False,
            "status": "SNAPSHOT_ERROR",
            "error": _external_signal_text(exc, 500),
            "live_order_allowed": False,
            "promotion_allowed": False,
        }
    with EXTERNAL_SIGNAL_INBOX_LOCK:
        try:
            latest = json.loads(EXTERNAL_SIGNAL_LATEST_FILE.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            latest = {}
        if latest.get("report_signature") == signature:
            status = "DUPLICATE_IGNORED"
        else:
            status = "ACCEPTED_PENDING_VALIDATION"
            envelope = {
                "schema": "codexstock_external_signal_inbox_v1",
                "status": status,
                "received_at": received_at,
                "source": source_name,
                "report_signature": signature,
                "report_semantic_signature": report_semantic_signature,
                "live_order_allowed": False,
                "promotion_allowed": False,
                "report": normalized,
                "news_verification": news_verification,
            }
            EXTERNAL_SIGNAL_LATEST_FILE.parent.mkdir(parents=True, exist_ok=True)
            temp_path = EXTERNAL_SIGNAL_LATEST_FILE.with_suffix(".tmp")
            temp_path.write_text(json.dumps(envelope, ensure_ascii=False, indent=2, sort_keys=True), encoding="utf-8")
            temp_path.replace(EXTERNAL_SIGNAL_LATEST_FILE)
        current_alert_delivery_id = _external_signal_alert_delivery_id(normalized)
        previous_report = latest.get("report") if isinstance(latest.get("report"), dict) else {}
        previous_alert_delivery_id = _external_signal_alert_delivery_id(previous_report)
        semantic_alert_duplicate = bool(
            current_alert_delivery_id
            and current_alert_delivery_id == previous_alert_delivery_id
        )
        enqueued_count = (
            0
            if semantic_report_duplicate
            else _enqueue_external_signal_verification_requests(
                normalized,
                received_at=received_at,
                source=source_name,
                report_signature=signature,
                stage2_snapshot=stage2_snapshot,
                news_verification=news_verification,
            )
        )
        enqueued_context_count = (
            0
            if semantic_report_duplicate
            else _enqueue_external_context_verification_requests(
                normalized,
                received_at=received_at,
                source=source_name,
                report_signature=signature,
            )
        )
        snapshot_reconciliation = _reconcile_external_signal_snapshot_queue(
            report_signature=signature,
            stage2_snapshot=stage2_snapshot,
        )
        telegram_alert = (
            _queue_external_signal_telegram_alert(
                normalized,
                report_signature=signature,
                source=source_name,
            )
            if status == "ACCEPTED_PENDING_VALIDATION" and not semantic_alert_duplicate
            else {
                "status": "semantic_duplicate",
                "queued": False,
                "single_delivery_id": current_alert_delivery_id,
            }
            if semantic_alert_duplicate
            else {"status": "duplicate_report", "queued": False}
        )
        receipt = {
            "schema": "codexstock_external_signal_receipt_v1",
            "status": status,
            "received_at": received_at,
            "source": source_name,
            "report_signature": signature,
            "report_semantic_signature": report_semantic_signature,
            "semantic_report_duplicate": semantic_report_duplicate,
            "signal_count": len(normalized.get("signals", [])),
            "urgent_count": len(normalized.get("urgent_triggers", [])),
            "enqueued_verification_count": enqueued_count,
            "enqueued_context_verification_count": enqueued_context_count,
            "snapshot_verified_count": snapshot_reconciliation["verified"],
            "snapshot_blocked_count": snapshot_reconciliation["blocked"],
            "snapshot_reconciliation_skipped_count": snapshot_reconciliation["skipped"],
            "stage2_snapshot_ready": bool(stage2_snapshot.get("ready")),
            "stage2_snapshot_id": stage2_snapshot.get("snapshot_id", ""),
            "stage2_dataset_hash": stage2_snapshot.get("dataset_hash", ""),
            "stage2_snapshot_cached": bool(stage2_snapshot.get("cached")),
            "news_evidence_ready_count": sum(
                1 for row in news_verification.values()
                if isinstance(row, dict) and row.get("status") == "EVIDENCE_READY_FOR_STAGE2"
            ),
            "news_evidence_blocked_count": sum(
                1 for row in news_verification.values()
                if isinstance(row, dict) and row.get("status") != "EVIDENCE_READY_FOR_STAGE2"
            ),
            "official_disclosure_match_count": sum(
                int(row.get("official_disclosure_match_count", 0) or 0)
                for row in news_verification.values() if isinstance(row, dict)
            ),
            "telegram_alert_status": telegram_alert.get("status", "unknown"),
            "telegram_alert_queued": bool(telegram_alert.get("status") == "queued" or telegram_alert.get("queued")),
            "telegram_alert_id": telegram_alert.get("id", ""),
            "telegram_alert_semantic_duplicate": semantic_alert_duplicate,
            "telegram_alert_delivery_id": current_alert_delivery_id,
            "live_order_allowed": False,
            "promotion_allowed": False,
        }
        _append_jsonl(EXTERNAL_SIGNAL_RECEIPT_FILE, receipt)
        _compact_jsonl(EXTERNAL_SIGNAL_RECEIPT_FILE, max_rows=2000)
    return receipt, 200


def _external_signal_expected_key() -> str:
    return str(
        os.getenv("CODEXSTOCK_CONTROL_PLANE_API_KEY", "")
        or os.getenv("CONTROL_PLANE_API_KEY", "")
        or ""
    ).strip()


def _external_signal_promotion_audit(request: dict[str, object]) -> dict[str, object]:
    """Recompute promotion eligibility from evidence instead of trusting a stored flag."""
    blockers: list[str] = []
    status = str(request.get("status") or "").strip().upper()
    if status not in {"STAGE2_PASSED", "VERIFIED_STAGE2", "ACCEPTED_FOR_STAGE2_PROMOTION"}:
        blockers.append("stage2_status_not_passed")
    if not bool(request.get("stage2_result_gate_passed")):
        blockers.append("stage2_result_gate_not_passed")
    contract_hash = str(request.get("contract_hash") or "").strip().lower()
    contract_hash_echo = str(request.get("contract_hash_echo") or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{64}", contract_hash):
        blockers.append("contract_hash_invalid")
    elif contract_hash_echo != contract_hash:
        blockers.append("contract_hash_echo_mismatch")
    schema_version = str(request.get("contract_schema_version_echo") or "").strip()
    if schema_version != "stage2-handoff-contract.v1.40":
        blockers.append("contract_schema_version_not_current")
    snapshot_id = str(request.get("stage2_snapshot_id") or "").strip()
    snapshot_id_echo = str(request.get("required_snapshot_id_echo") or "").strip()
    dataset_hash = str(request.get("stage2_dataset_hash") or "").strip().lower()
    dataset_hash_echo = str(request.get("dataset_hash_echo") or "").strip().lower()
    if not snapshot_id or snapshot_id_echo != snapshot_id:
        blockers.append("snapshot_identity_mismatch")
    if not re.fullmatch(r"[0-9a-f]{64}", dataset_hash) or dataset_hash_echo != dataset_hash:
        blockers.append("dataset_hash_evidence_mismatch")
    validation_grade = str(request.get("validation_grade") or "").strip().upper()
    if validation_grade not in {"A", "B"}:
        blockers.append("validation_grade_below_promotion")
    evidence = request.get("validation_evidence") if isinstance(request.get("validation_evidence"), dict) else {}
    required_evidence = {
        "return_reconciliation_passed",
        "exit_reason_alignment_passed",
        "cost_profile_passed",
        "unit_currency_passed",
        "no_live_order_passed",
    }
    missing_evidence = sorted(key for key in required_evidence if evidence.get(key) is not True)
    if missing_evidence:
        blockers.append("validation_evidence_incomplete")
    news_verification = (
        request.get("news_verification")
        if isinstance(request.get("news_verification"), dict)
        else {}
    )
    news_checks = (
        news_verification.get("checks")
        if isinstance(news_verification.get("checks"), dict)
        else {}
    )
    if news_checks.get("original_body_evidence_passed") is not True:
        blockers.append("original_body_evidence_not_passed")
    if news_checks.get("multi_source_evidence_passed") is not True:
        blockers.append("multi_source_evidence_not_passed")
    if news_checks.get("official_disclosure_gate_passed") is not True:
        blockers.append("official_disclosure_gate_not_passed")
    if news_checks.get("source_lineage_bundle_passed") is not True:
        blockers.append("source_lineage_bundle_not_passed")
    eligible = not blockers
    return {
        "eligible": eligible,
        "stored_promotion_flag": bool(request.get("promotion_allowed")),
        "validation_grade": validation_grade or "UNVERIFIED",
        "blockers": blockers,
        "missing_evidence": missing_evidence,
        "news_evidence_status": str(news_verification.get("status") or "MISSING"),
        "news_evidence_checks": news_checks,
        "official_disclosure_required": bool(news_verification.get("official_disclosure_required")),
        "official_disclosure_match_count": int(news_verification.get("official_disclosure_match_count", 0) or 0),
        "contract_hash_prefix": contract_hash[:12] if contract_hash else "",
        "dataset_hash_prefix": dataset_hash[:12] if dataset_hash else "",
        "rule": "Promotion requires a current Stage 2 contract, matching snapshot/dataset hashes, grade A/B, complete reconciliation, and complete external-source lineage evidence.",
    }


EXTERNAL_SIGNAL_STAGE2_CONTRACT_SCHEMA = "stage2-handoff-contract.v1.40"
EXTERNAL_SIGNAL_STAGE2_RESULT_SCHEMA = "codexstock_external_signal_stage2_result_v1"


def _external_signal_stage2_contract(
    request: dict[str, object],
    *,
    report_generated_at: object,
    snapshot_symbols: list[str],
) -> dict[str, object]:
    budget = EXTERNAL_KNOWLEDGE.external_execution_budget()
    signal_id = str(request.get("signal_id") or "").strip()
    replay_token = re.sub(r"[^A-Za-z0-9._:-]+", "-", signal_id).strip("-_.:") or "signal"
    replay_id = f"external-signal-{replay_token}"[:120]
    timeout_seconds = min(
        int(_number(budget.get("hard_timeout_seconds")) or 600),
        max(60, int(_number(budget.get("default_timeout_seconds")) or 180)),
    )
    max_artifact_bytes = int(max(1, _number(budget.get("max_artifact_mb")) or 25) * 1024 * 1024)
    news_verification = (
        request.get("news_verification")
        if isinstance(request.get("news_verification"), dict)
        else {}
    )
    news_evidence_hash = hashlib.sha256(
        json.dumps(news_verification, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    contract_body: dict[str, object] = {
        "contract_schema_version": EXTERNAL_SIGNAL_STAGE2_CONTRACT_SCHEMA,
        "contract_scope": "external_signal_candidate_validation",
        "report_signature": str(request.get("report_signature") or ""),
        "report_generated_at": str(report_generated_at or ""),
        "dedupe_key": str(request.get("dedupe_key") or ""),
        "signal_id": signal_id,
        "symbol": str(request.get("symbol") or "").strip().upper(),
        "replay_id": replay_id,
        "stage2_action": "run_external_replay",
        "preferred_engines": ["nautilustrader", "research-forge", "vectorbt"],
        "external_runtime_mode": "spawn_on_demand_only",
        "required_snapshot_id": str(request.get("stage2_snapshot_id") or ""),
        "required_dataset_hash": str(request.get("stage2_dataset_hash") or "").lower(),
        "snapshot_symbols": snapshot_symbols,
        "news_evidence_hash": news_evidence_hash,
        "timeout_seconds": timeout_seconds,
        "max_concurrent_external_jobs": int(
            max(1, _number(budget.get("max_concurrent_external_jobs")) or 1)
        ),
        "max_temp_artifact_bytes": max_artifact_bytes,
        "required_outputs": [
            "contract_hash_echo",
            "snapshot_id_echo",
            "dataset_hash_echo",
            "external_engine_name",
            "external_run_id",
            "external_runtime_mode_echo",
            "external_runtime_budget_evidence",
            "external_runtime_cleanup_evidence",
            "entry_exit_return_reason_evidence",
            "return_reconciliation_evidence",
            "exit_reason_alignment_evidence",
            "fee_tax_slippage_evidence",
            "unit_currency_audit_evidence",
            "no_live_order_evidence",
        ],
        "candidate_pool_only": True,
        "score_allowed": False,
        "live_order_allowed": False,
    }
    contract_hash = hashlib.sha256(
        json.dumps(contract_body, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    return {
        **contract_body,
        "stage2_job_id": f"EXTSIG-{contract_hash[:20].upper()}",
        "idempotency_key": f"external-signal:{contract_hash}",
        "contract_hash": contract_hash,
        "contract_hash_prefix": contract_hash[:12],
    }


def build_external_signal_stage2_queue(
    *,
    limit: int = 20,
    now: datetime | None = None,
) -> dict[str, object]:
    safe_limit = max(1, min(int(_number(limit) or 20), 200))
    try:
        latest = json.loads(EXTERNAL_SIGNAL_LATEST_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        latest = {}
    try:
        snapshot = json.loads(EXTERNAL_SIGNAL_STAGE2_SNAPSHOT_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        snapshot = {}
    report = latest.get("report") if isinstance(latest.get("report"), dict) else {}
    report_signature = str(latest.get("report_signature") or "")
    freshness = _external_signal_report_freshness(report.get("generated_at"), now=now)
    snapshot_symbols = [
        str(symbol or "").strip().upper()
        for symbol in (snapshot.get("symbols") if isinstance(snapshot.get("symbols"), list) else [])
        if str(symbol or "").strip()
    ]

    latest_validation_by_key: dict[str, dict[str, object]] = {}
    for row in _read_jsonl(EXTERNAL_SIGNAL_VERIFICATION_RESULT_FILE):
        dedupe_key = str(row.get("dedupe_key") or "")
        if dedupe_key:
            latest_validation_by_key[dedupe_key] = row
    accepted_by_contract: dict[str, dict[str, object]] = {}
    latest_attempt_by_job: dict[str, dict[str, object]] = {}
    for row in _read_jsonl(EXTERNAL_SIGNAL_STAGE2_RESULT_FILE):
        job_id = str(row.get("stage2_job_id") or "")
        contract_hash = str(row.get("contract_hash") or "")
        if job_id:
            latest_attempt_by_job[job_id] = row
        if contract_hash and row.get("accepted_for_candidate_pool") is True:
            accepted_by_contract[contract_hash] = row

    jobs: list[dict[str, object]] = []
    for raw_request in _read_jsonl(EXTERNAL_SIGNAL_VERIFICATION_QUEUE_FILE):
        if str(raw_request.get("report_signature") or "") != report_signature:
            continue
        dedupe_key = str(raw_request.get("dedupe_key") or "")
        request = {**raw_request, **latest_validation_by_key.get(dedupe_key, {})}
        contract = _external_signal_stage2_contract(
            request,
            report_generated_at=report.get("generated_at"),
            snapshot_symbols=snapshot_symbols,
        )
        blockers: list[str] = []
        symbol = str(request.get("symbol") or "").strip().upper()
        if not bool(freshness.get("fresh")):
            blockers.append("external_signal_report_stale")
        if not (symbol.isdigit() and len(symbol) == 6):
            blockers.append("invalid_domestic_symbol")
        if str(request.get("status") or "").upper() != "SNAPSHOT_VERIFIED_PENDING_STAGE2_RESULT":
            blockers.append("snapshot_validation_not_ready")
        if not re.fullmatch(r"[0-9a-f]{64}", str(request.get("stage2_dataset_hash") or "").lower()):
            blockers.append("stage2_dataset_hash_invalid")
        if not str(request.get("stage2_snapshot_id") or ""):
            blockers.append("stage2_snapshot_id_missing")
        if request.get("live_order_allowed") is not False:
            blockers.append("live_order_boundary_not_proven")
        news_verification = (
            request.get("news_verification")
            if isinstance(request.get("news_verification"), dict)
            else {}
        )
        news_checks = (
            news_verification.get("checks")
            if isinstance(news_verification.get("checks"), dict)
            else {}
        )
        for field in (
            "original_body_evidence_passed",
            "multi_source_evidence_passed",
            "official_disclosure_gate_passed",
        ):
            if news_checks.get(field) is not True:
                blockers.append(f"news_{field}_missing")
        accepted_result = accepted_by_contract.get(str(contract.get("contract_hash") or ""), {})
        if accepted_result:
            state = "completed"
        elif blockers:
            state = "blocked"
        else:
            state = "ready_to_queue"
        jobs.append(
            {
                **contract,
                "state": state,
                "blockers": sorted(set(blockers)),
                "blocker_count": len(set(blockers)),
                "name": request.get("name", ""),
                "theme": request.get("theme", ""),
                "confidence": request.get("confidence", 0),
                "news_verification": news_verification,
                "accepted_result": accepted_result,
                "latest_attempt": latest_attempt_by_job.get(str(contract.get("stage2_job_id") or ""), {}),
                "candidate_pool_allowed": bool(accepted_result and freshness.get("fresh")),
                "score_allowed": False,
                "live_order_allowed": False,
            }
        )
    jobs.sort(
        key=lambda row: (
            {"ready_to_queue": 0, "blocked": 1, "completed": 2}.get(str(row.get("state")), 3),
            -_number(row.get("confidence")),
            str(row.get("symbol") or ""),
        )
    )
    ready_jobs = [row for row in jobs if row.get("state") == "ready_to_queue"]
    blocked_jobs = [row for row in jobs if row.get("state") == "blocked"]
    completed_jobs = [row for row in jobs if row.get("state") == "completed"]
    blocker_counts: dict[str, int] = {}
    for row in blocked_jobs:
        for blocker in row.get("blockers", []) if isinstance(row.get("blockers"), list) else []:
            blocker_counts[str(blocker)] = blocker_counts.get(str(blocker), 0) + 1
    if ready_jobs:
        status = "ready"
    elif blocked_jobs:
        status = "blocked"
    elif jobs and completed_jobs:
        status = "idle_all_completed"
    else:
        status = "idle_no_signal_jobs"
    return {
        "ok": status in {"ready", "idle_all_completed", "idle_no_signal_jobs"},
        "schema": "codexstock_external_signal_stage2_queue_v1",
        "status": status,
        "generated_at": datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
        "report_signature": report_signature,
        "report_freshness": freshness,
        "job_count": len(jobs),
        "ready_count": len(ready_jobs),
        "blocked_count": len(blocked_jobs),
        "completed_count": len(completed_jobs),
        "blocker_counts": blocker_counts,
        "next_ready_job": ready_jobs[0] if ready_jobs else {},
        "jobs": jobs[:safe_limit],
        "execution_policy": "explicit_on_demand_only",
        "max_concurrent_external_jobs": 1,
        "candidate_pool_rule": "Only a fresh report with exact Stage 2 contract evidence may enter the internal watch candidate pool.",
        "score_allowed": False,
        "live_order_allowed": False,
    }


def receive_external_signal_stage2_result(
    payload: object,
    *,
    source: str = "external-stage2-engine",
    now: datetime | None = None,
) -> tuple[dict[str, object], int]:
    if not isinstance(payload, dict):
        return {"ok": False, "error": "payload_must_be_object", "live_order_allowed": False}, 400
    queue = build_external_signal_stage2_queue(limit=200, now=now)
    stage2_job_id = str(payload.get("stage2_job_id") or "").strip()
    matched_job = next(
        (
            row
            for row in queue.get("jobs", [])
            if isinstance(row, dict) and str(row.get("stage2_job_id") or "") == stage2_job_id
        ),
        {},
    )
    if matched_job.get("state") == "completed" and isinstance(matched_job.get("accepted_result"), dict):
        return {
            **matched_job["accepted_result"],
            "ok": True,
            "duplicate_ignored": True,
            "live_order_allowed": False,
        }, 200

    blockers: list[str] = []
    if not matched_job:
        blockers.append("stage2_job_not_found")
    elif matched_job.get("state") != "ready_to_queue":
        blockers.extend(
            matched_job.get("blockers", [])
            if isinstance(matched_job.get("blockers"), list)
            else ["stage2_job_not_ready"]
        )
    expected_contract_hash = str(matched_job.get("contract_hash") or "")
    contract_hash_echo = str(payload.get("contract_hash_echo") or "").strip().lower()
    if not expected_contract_hash or contract_hash_echo != expected_contract_hash:
        blockers.append("contract_hash_echo_mismatch")
    expected_snapshot_id = str(matched_job.get("required_snapshot_id") or "")
    expected_dataset_hash = str(matched_job.get("required_dataset_hash") or "").lower()
    if str(payload.get("snapshot_id_echo") or "") != expected_snapshot_id:
        blockers.append("snapshot_id_echo_mismatch")
    if str(payload.get("dataset_hash_echo") or "").lower() != expected_dataset_hash:
        blockers.append("dataset_hash_echo_mismatch")

    engine_name = str(payload.get("external_engine_name") or "").strip()
    normalized_engine = re.sub(r"[^a-z0-9]+", "", engine_name.lower())
    allowed_engine_tokens = {
        re.sub(r"[^a-z0-9]+", "", str(item).lower())
        for item in matched_job.get("preferred_engines", [])
        if str(item or "").strip()
    } if isinstance(matched_job.get("preferred_engines"), list) else set()
    if normalized_engine not in allowed_engine_tokens:
        blockers.append("external_engine_not_allowed_by_contract")
    external_run_id = str(payload.get("external_run_id") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9._:-]{8,128}", external_run_id):
        blockers.append("external_run_id_invalid")
    if any(token in external_run_id.lower() for token in ("test", "sample", "dummy", "placeholder", "example")):
        blockers.append("external_run_id_placeholder")
    runtime_mode = str(payload.get("external_runtime_mode_echo") or "").strip().lower()
    if runtime_mode != str(matched_job.get("external_runtime_mode") or "").lower():
        blockers.append("external_runtime_mode_mismatch")
    if any(token in runtime_mode for token in ("always_on", "daemon", "resident", "in_process")):
        blockers.append("external_runtime_mode_unsafe")

    engine_result = payload.get("engine_result") if isinstance(payload.get("engine_result"), dict) else {}
    if engine_result.get("ok") is not True:
        blockers.append("external_engine_result_not_ok")
    if engine_result.get("live_order_allowed") is not False:
        blockers.append("external_engine_live_order_boundary_failed")
    if str(engine_result.get("decision") or "").upper() != "VERIFY_ONLY":
        blockers.append("external_engine_decision_not_verify_only")
    if str(engine_result.get("snapshot_id") or "") != expected_snapshot_id:
        blockers.append("engine_result_snapshot_mismatch")
    if str(engine_result.get("dataset_hash") or "").lower() != expected_dataset_hash:
        blockers.append("engine_result_dataset_hash_mismatch")
    engine_result_hash = str(engine_result.get("result_hash") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{64}", engine_result_hash):
        blockers.append("engine_result_hash_invalid")

    symbol = str(matched_job.get("symbol") or "").upper()
    evidence_by_symbol = (
        engine_result.get("stage2_evidence_by_symbol")
        if isinstance(engine_result.get("stage2_evidence_by_symbol"), dict)
        else {}
    )
    stage2_evidence = (
        evidence_by_symbol.get(symbol)
        if isinstance(evidence_by_symbol.get(symbol), dict)
        else engine_result.get("stage2_evidence")
        if isinstance(engine_result.get("stage2_evidence"), dict)
        else {}
    )
    required_evidence = {
        "entry_exit_return_reason_evidence": "entry_exit_return_reason_passed",
        "return_reconciliation_evidence": "return_reconciliation_passed",
        "exit_reason_alignment_evidence": "exit_reason_alignment_passed",
        "fee_tax_slippage_evidence": "cost_profile_passed",
        "unit_currency_audit_evidence": "unit_currency_passed",
        "no_live_order_evidence": "no_live_order_passed",
    }
    validation_evidence: dict[str, bool] = {}
    for evidence_name, result_name in required_evidence.items():
        evidence_row = stage2_evidence.get(evidence_name) if isinstance(stage2_evidence.get(evidence_name), dict) else {}
        passed = evidence_row.get("passed") is True
        validation_evidence[result_name] = passed
        if not passed:
            blockers.append(f"{evidence_name}_not_passed")
    fill_ledger_hash = str(stage2_evidence.get("fill_ledger_hash") or "").lower()
    if not re.fullmatch(r"[0-9a-f]{64}", fill_ledger_hash):
        blockers.append("fill_ledger_hash_invalid")

    runtime_budget = (
        payload.get("external_runtime_budget_evidence")
        if isinstance(payload.get("external_runtime_budget_evidence"), dict)
        else {}
    )
    runtime_required_fields = {
        "actual_runtime_seconds",
        "timeout_seconds",
        "max_concurrent_external_jobs",
    }
    runtime_missing_fields = sorted(
        field
        for field in runtime_required_fields
        if field not in runtime_budget or runtime_budget.get(field) in (None, "")
    )
    if runtime_missing_fields:
        blockers.append("external_runtime_budget_evidence_incomplete")
    actual_runtime_seconds = _number(runtime_budget.get("actual_runtime_seconds"))
    if abs(_number(runtime_budget.get("timeout_seconds")) - _number(matched_job.get("timeout_seconds"))) > 0.000001:
        blockers.append("external_runtime_timeout_echo_mismatch")
    if int(_number(runtime_budget.get("max_concurrent_external_jobs"))) != int(
        _number(matched_job.get("max_concurrent_external_jobs"))
    ):
        blockers.append("external_runtime_concurrency_evidence_mismatch")
    if actual_runtime_seconds < 0 or actual_runtime_seconds > _number(matched_job.get("timeout_seconds")):
        blockers.append("external_runtime_timeout_evidence_failed")
    cleanup = (
        payload.get("external_runtime_cleanup_evidence")
        if isinstance(payload.get("external_runtime_cleanup_evidence"), dict)
        else {}
    )
    cleanup_required_fields = {
        "cleanup_completed",
        "resident_process_count",
        "temp_artifact_bytes",
        "max_temp_artifact_bytes",
    }
    cleanup_missing_fields = sorted(
        field
        for field in cleanup_required_fields
        if field not in cleanup or cleanup.get(field) in (None, "")
    )
    if cleanup_missing_fields:
        blockers.append("external_runtime_cleanup_evidence_incomplete")
    if cleanup.get("cleanup_completed") is not True:
        blockers.append("external_runtime_cleanup_not_completed")
    if int(_number(cleanup.get("resident_process_count"))) != 0:
        blockers.append("external_runtime_resident_process_remaining")
    temp_artifact_bytes = int(_number(cleanup.get("temp_artifact_bytes")))
    if int(_number(cleanup.get("max_temp_artifact_bytes"))) != int(
        _number(matched_job.get("max_temp_artifact_bytes"))
    ):
        blockers.append("external_runtime_temp_artifact_budget_echo_mismatch")
    if temp_artifact_bytes < 0 or temp_artifact_bytes > int(_number(matched_job.get("max_temp_artifact_bytes"))):
        blockers.append("external_runtime_temp_artifact_budget_failed")

    validation_grade = str(payload.get("validation_grade") or "").strip().upper()
    if validation_grade not in {"A", "B"}:
        blockers.append("validation_grade_below_candidate_pool")
    accepted = not blockers
    checked_at = (now or datetime.now(_zone("Asia/Seoul", 9))).isoformat(timespec="seconds")
    engine_payload_hash = hashlib.sha256(
        json.dumps(engine_result, ensure_ascii=False, sort_keys=True, default=str, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    attempt = {
        "schema": EXTERNAL_SIGNAL_STAGE2_RESULT_SCHEMA,
        "ok": True,
        "accepted_for_candidate_pool": accepted,
        "status": "STAGE2_PASSED" if accepted else "STAGE2_REJECTED",
        "checked_at": checked_at,
        "source": _external_signal_text(source, 120),
        "stage2_job_id": stage2_job_id,
        "dedupe_key": str(matched_job.get("dedupe_key") or ""),
        "signal_id": str(matched_job.get("signal_id") or ""),
        "symbol": symbol,
        "contract_hash": expected_contract_hash,
        "contract_hash_echo": contract_hash_echo,
        "external_engine_name": engine_name,
        "external_run_id": external_run_id,
        "engine_result_hash": engine_result_hash,
        "engine_payload_hash": engine_payload_hash,
        "validation_grade": validation_grade or "UNVERIFIED",
        "fill_ledger_hash": fill_ledger_hash,
        "validation_evidence": validation_evidence,
        "blockers": sorted(set(blockers)),
        "candidate_pool_allowed": accepted,
        "score_allowed": False,
        "promotion_allowed": False,
        "live_order_allowed": False,
    }
    with EXTERNAL_SIGNAL_STAGE2_RESULT_LOCK:
        _append_jsonl(EXTERNAL_SIGNAL_STAGE2_RESULT_FILE, attempt)
        _compact_jsonl(EXTERNAL_SIGNAL_STAGE2_RESULT_FILE, max_rows=4000)
        if accepted:
            verification_record = {
                "schema": "codexstock_external_signal_stage2_validation_v1",
                "dedupe_key": attempt["dedupe_key"],
                "signal_id": attempt["signal_id"],
                "symbol": symbol,
                "report_signature": str(matched_job.get("report_signature") or ""),
                "verified_at": checked_at,
                "status": "STAGE2_PASSED",
                "stage2_result_gate_passed": True,
                "stage2_job_id": stage2_job_id,
                "contract_hash": expected_contract_hash,
                "contract_hash_echo": contract_hash_echo,
                "contract_schema_version_echo": EXTERNAL_SIGNAL_STAGE2_CONTRACT_SCHEMA,
                "stage2_snapshot_id": expected_snapshot_id,
                "required_snapshot_id_echo": expected_snapshot_id,
                "stage2_dataset_hash": expected_dataset_hash,
                "dataset_hash_echo": expected_dataset_hash,
                "validation_grade": validation_grade,
                "validation_evidence": validation_evidence,
                "news_verification": matched_job.get("news_verification", {}),
                "external_engine_name": engine_name,
                "external_run_id": external_run_id,
                "engine_result_hash": engine_result_hash,
                "fill_ledger_hash": fill_ledger_hash,
                "candidate_pool_allowed": True,
                "score_allowed": False,
                "promotion_allowed": False,
                "live_order_allowed": False,
            }
            _append_jsonl(EXTERNAL_SIGNAL_VERIFICATION_RESULT_FILE, verification_record)
            _compact_jsonl(EXTERNAL_SIGNAL_VERIFICATION_RESULT_FILE, max_rows=4000)
    return attempt, 200 if accepted else 409


def _external_signal_stage2_job_state_load() -> dict[str, object]:
    try:
        payload = json.loads(EXTERNAL_SIGNAL_STAGE2_JOB_STATE_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def _external_signal_stage2_job_state_save(payload: dict[str, object]) -> None:
    EXTERNAL_SIGNAL_STAGE2_JOB_STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
    temporary = EXTERNAL_SIGNAL_STAGE2_JOB_STATE_FILE.with_name(
        f".{EXTERNAL_SIGNAL_STAGE2_JOB_STATE_FILE.name}.{os.getpid()}.tmp"
    )
    temporary.write_text(
        json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2, default=str),
        encoding="utf-8",
    )
    os.replace(temporary, EXTERNAL_SIGNAL_STAGE2_JOB_STATE_FILE)


def _external_signal_stage2_job_update(**updates: object) -> dict[str, object]:
    with EXTERNAL_SIGNAL_STAGE2_JOB_LOCK:
        state = _external_signal_stage2_job_state_load()
        state.update(updates)
        state["schema"] = "codexstock_external_signal_stage2_job_state_v1"
        state["updated_at"] = datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds")
        state["live_order_allowed"] = False
        _external_signal_stage2_job_state_save(state)
        return state


def external_signal_stage2_job_status() -> dict[str, object]:
    with EXTERNAL_SIGNAL_STAGE2_JOB_LOCK:
        state = _external_signal_stage2_job_state_load()
    thread_alive = bool(
        EXTERNAL_SIGNAL_STAGE2_JOB_THREAD is not None
        and EXTERNAL_SIGNAL_STAGE2_JOB_THREAD.is_alive()
    )
    status = str(state.get("status") or "idle")
    if status in {"queued", "running"} and not thread_alive:
        status = "interrupted"
    deadline_text = str(state.get("deadline_at") or "")
    eta_seconds = 0
    if status in {"queued", "running"} and deadline_text:
        try:
            deadline = datetime.fromisoformat(deadline_text.replace("Z", "+00:00"))
            now = datetime.now(deadline.tzinfo or _zone("Asia/Seoul", 9))
            eta_seconds = max(0, int((deadline - now).total_seconds()))
        except (TypeError, ValueError):
            eta_seconds = 0
    return {
        **state,
        "ok": status not in {"failed", "interrupted"},
        "status": status,
        "thread_alive": thread_alive,
        "eta_seconds": eta_seconds,
        "execution_policy": "explicit_on_demand_background_singleflight",
        "max_concurrent_external_jobs": 1,
        "live_order_allowed": False,
    }


def _run_external_signal_stage2_job_sync(stage2_job_id: str) -> dict[str, object]:
    queue = build_external_signal_stage2_queue(limit=200)
    job = next(
        (
            row
            for row in queue.get("jobs", [])
            if isinstance(row, dict) and str(row.get("stage2_job_id") or "") == stage2_job_id
        ),
        {},
    )
    if not job or job.get("state") != "ready_to_queue":
        return {
            "ok": False,
            "status": "job_not_ready",
            "stage2_job_id": stage2_job_id,
            "blockers": job.get("blockers", ["stage2_job_not_found"]) if isinstance(job, dict) else ["stage2_job_not_found"],
            "live_order_allowed": False,
        }
    snapshot_symbols = [
        str(symbol or "").strip().upper()
        for symbol in (job.get("snapshot_symbols") if isinstance(job.get("snapshot_symbols"), list) else [])
        if str(symbol or "").strip()
    ]
    if not snapshot_symbols:
        return {
            "ok": False,
            "status": "snapshot_symbols_missing",
            "stage2_job_id": stage2_job_id,
            "live_order_allowed": False,
        }
    _external_signal_stage2_job_update(status="running", phase="snapshot_rebuild", progress_pct=15)
    snapshot_result = EXTERNAL_KNOWLEDGE.build_common_snapshot_from_ohlcv_cache(
        symbols=snapshot_symbols,
        max_symbols=len(snapshot_symbols),
        max_rows_per_symbol=120,
        action="run_external_backtest",
        package_id=f"external-signal-{str(job.get('report_signature') or '')[:12]}",
        record=False,
        include_rows_for_runtime=True,
        source="external-signal-stage2-on-demand",
    )
    runtime_payload = snapshot_result.pop("runtime_dataset_payload", None)
    snapshot_meta = snapshot_result.get("dataset_snapshot_preview")
    if not snapshot_result.get("ok") or not isinstance(runtime_payload, dict) or not isinstance(snapshot_meta, dict):
        return {
            "ok": False,
            "status": "snapshot_rebuild_failed",
            "stage2_job_id": stage2_job_id,
            "snapshot": snapshot_result,
            "live_order_allowed": False,
        }
    if (
        str(snapshot_meta.get("snapshot_id") or "") != str(job.get("required_snapshot_id") or "")
        or str(snapshot_meta.get("dataset_hash") or "").lower()
        != str(job.get("required_dataset_hash") or "").lower()
    ):
        return {
            "ok": False,
            "status": "snapshot_contract_changed",
            "stage2_job_id": stage2_job_id,
            "expected_snapshot_id": job.get("required_snapshot_id", ""),
            "actual_snapshot_id": snapshot_meta.get("snapshot_id", ""),
            "expected_dataset_hash": job.get("required_dataset_hash", ""),
            "actual_dataset_hash": snapshot_meta.get("dataset_hash", ""),
            "live_order_allowed": False,
        }

    _external_signal_stage2_job_update(status="running", phase="engine_preflight", progress_pct=30)
    started = time.perf_counter()
    timeout_seconds = int(_number(job.get("timeout_seconds")) or 180)
    engine_name = ""
    engine_source = ""
    engine_result: dict[str, object] = {}
    symbol = str(job.get("symbol") or "").upper()
    symbol_evidence: dict[str, object] = {}
    engine_attempts: list[dict[str, object]] = []
    engine_chain = (
        (
            "nautilustrader",
            "codexstock-on-demand-nautilus",
            lambda budget: NAUTILUS_RUNTIME.run_replay(
                runtime_payload,
                snapshot_meta,
                fast_window=10,
                slow_window=60,
                timeout_seconds=budget,
            ),
        ),
        (
            "vectorbt",
            "codexstock-on-demand-vectorbt-fallback",
            lambda budget: VECTORBT_RUNTIME.run_backtest(
                runtime_payload,
                snapshot_meta,
                fast_windows=[5, 10],
                slow_windows=[20, 40],
                timeout_seconds=budget,
            ),
        ),
    )
    for attempt_index, (candidate_engine, candidate_source, runner) in enumerate(engine_chain, start=1):
        elapsed_seconds = max(0.0, time.perf_counter() - started)
        remaining_seconds = max(0, int(timeout_seconds - elapsed_seconds))
        if remaining_seconds < 20:
            engine_attempts.append(
                {
                    "engine_name": candidate_engine,
                    "ok": False,
                    "status": "skipped_global_timeout_budget",
                    "live_order_allowed": False,
                }
            )
            break
        attempt_budget = min(60, remaining_seconds) if attempt_index == 1 else remaining_seconds
        _external_signal_stage2_job_update(
            status="running",
            phase=f"{candidate_engine}_stage2_replay",
            progress_pct=35 if attempt_index == 1 else 60,
            engine_name=candidate_engine,
        )
        candidate_result = runner(attempt_budget)
        evidence_by_symbol = (
            candidate_result.get("stage2_evidence_by_symbol")
            if isinstance(candidate_result.get("stage2_evidence_by_symbol"), dict)
            else {}
        )
        candidate_evidence = (
            evidence_by_symbol.get(symbol)
            if isinstance(evidence_by_symbol.get(symbol), dict)
            else {}
        )
        candidate_grade = str(candidate_evidence.get("validation_grade") or "BLOCKED").upper()
        engine_attempts.append(
            {
                "engine_name": candidate_engine,
                "ok": candidate_result.get("ok") is True,
                "validation_grade": candidate_grade,
                "error": _external_signal_text(candidate_result.get("error") or candidate_result.get("stderr"), 300),
                "runtime_elapsed_ms": candidate_result.get("runtime_elapsed_ms", 0),
                "result_hash": candidate_result.get("result_hash", ""),
                "live_order_allowed": False,
            }
        )
        engine_name = candidate_engine
        engine_source = candidate_source
        engine_result = candidate_result
        symbol_evidence = candidate_evidence
        if candidate_result.get("ok") is True and candidate_grade in {"A", "B"}:
            break
    actual_runtime_seconds = max(0.0, time.perf_counter() - started)
    _external_signal_stage2_job_update(status="running", phase="result_gate", progress_pct=85)
    now = datetime.now(_zone("Asia/Seoul", 9))
    run_token = f"run:{str(job.get('contract_hash_prefix') or '')}:{str(job.get('replay_id') or '')}:{int(now.timestamp())}"
    result_payload = {
        "stage2_job_id": stage2_job_id,
        "contract_hash_echo": job.get("contract_hash", ""),
        "snapshot_id_echo": job.get("required_snapshot_id", ""),
        "dataset_hash_echo": job.get("required_dataset_hash", ""),
        "external_engine_name": engine_name,
        "external_run_id": run_token[:128],
        "external_runtime_mode_echo": "spawn_on_demand_only",
        "external_runtime_budget_evidence": {
            "actual_runtime_seconds": round(actual_runtime_seconds, 6),
            "timeout_seconds": timeout_seconds,
            "max_concurrent_external_jobs": 1,
        },
        "external_runtime_cleanup_evidence": {
            "cleanup_completed": True,
            "resident_process_count": 0,
            "temp_artifact_bytes": 0,
            "max_temp_artifact_bytes": int(_number(job.get("max_temp_artifact_bytes"))),
        },
        "validation_grade": symbol_evidence.get("validation_grade", "BLOCKED"),
        "engine_result": engine_result,
        "source": engine_source,
    }
    result, status_code = receive_external_signal_stage2_result(
        result_payload,
        source=engine_source,
    )
    return {
        "ok": status_code == 200 and result.get("accepted_for_candidate_pool") is True,
        "status": "completed" if status_code == 200 else "result_gate_blocked",
        "http_status": status_code,
        "stage2_job_id": stage2_job_id,
        "engine_name": engine_name,
        "engine_attempts": engine_attempts,
        "engine_result_hash": engine_result.get("result_hash", ""),
        "validation_grade": symbol_evidence.get("validation_grade", "BLOCKED"),
        "result_gate": result,
        "live_order_allowed": False,
    }


def _external_signal_stage2_job_worker(stage2_job_id: str) -> None:
    try:
        result = _run_external_signal_stage2_job_sync(stage2_job_id)
        final_status = "completed" if result.get("ok") else "failed"
        _external_signal_stage2_job_update(
            status=final_status,
            phase="done",
            progress_pct=100,
            completed_at=datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
            result=result,
            error="" if result.get("ok") else str(result.get("status") or "stage2_job_failed"),
        )
    except Exception as exc:
        _external_signal_stage2_job_update(
            status="failed",
            phase="exception",
            progress_pct=100,
            completed_at=datetime.now(_zone("Asia/Seoul", 9)).isoformat(timespec="seconds"),
            error=_external_signal_text(exc, 500),
        )
    finally:
        EXTERNAL_SIGNAL_STAGE2_EXECUTION_LOCK.release()


def start_external_signal_stage2_job(stage2_job_id: str = "") -> tuple[dict[str, object], int]:
    global EXTERNAL_SIGNAL_STAGE2_JOB_THREAD
    queue = build_external_signal_stage2_queue(limit=200)
    requested_job_id = str(stage2_job_id or "").strip()
    job = next(
        (
            row
            for row in queue.get("jobs", [])
            if isinstance(row, dict)
            and (
                str(row.get("stage2_job_id") or "") == requested_job_id
                if requested_job_id
                else row.get("state") == "ready_to_queue"
            )
        ),
        {},
    )
    if not job or job.get("state") != "ready_to_queue":
        return {
            "ok": False,
            "status": "no_ready_stage2_job",
            "requested_stage2_job_id": requested_job_id,
            "queue_status": queue.get("status", ""),
            "blocker_counts": queue.get("blocker_counts", {}),
            "live_order_allowed": False,
        }, 409
    if not EXTERNAL_SIGNAL_STAGE2_EXECUTION_LOCK.acquire(blocking=False):
        return {
            "ok": False,
            "status": "external_engine_busy",
            "current_job": external_signal_stage2_job_status(),
            "live_order_allowed": False,
        }, 409
    started_at = datetime.now(_zone("Asia/Seoul", 9))
    timeout_seconds = int(_number(job.get("timeout_seconds")) or 180)
    try:
        _external_signal_stage2_job_update(
            status="queued",
            phase="queued",
            progress_pct=5,
            stage2_job_id=job.get("stage2_job_id", ""),
            symbol=job.get("symbol", ""),
            engine_name="auto_stage2_chain",
            started_at=started_at.isoformat(timespec="seconds"),
            deadline_at=(started_at + timedelta(seconds=timeout_seconds)).isoformat(timespec="seconds"),
            timeout_seconds=timeout_seconds,
            error="",
            result={},
        )
        EXTERNAL_SIGNAL_STAGE2_JOB_THREAD = threading.Thread(
            target=_external_signal_stage2_job_worker,
            args=(str(job.get("stage2_job_id") or ""),),
            name="external-signal-stage2-on-demand",
            daemon=True,
        )
        EXTERNAL_SIGNAL_STAGE2_JOB_THREAD.start()
    except Exception:
        EXTERNAL_SIGNAL_STAGE2_EXECUTION_LOCK.release()
        raise
    return {
        "ok": True,
        "status": "queued",
        "stage2_job_id": job.get("stage2_job_id", ""),
        "symbol": job.get("symbol", ""),
        "engine_name": "nautilustrader",
        "progress_pct": 5,
        "eta_seconds": timeout_seconds,
        "live_order_allowed": False,
    }, 202


def external_signal_inbox_status(include_report: bool = False) -> dict[str, object]:
    try:
        latest = json.loads(EXTERNAL_SIGNAL_LATEST_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        latest = {}
    try:
        stage2_snapshot = json.loads(EXTERNAL_SIGNAL_STAGE2_SNAPSHOT_FILE.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        stage2_snapshot = {}
    receipts = _read_jsonl(EXTERNAL_SIGNAL_RECEIPT_FILE, limit=20)
    raw_verification_requests = _read_jsonl(EXTERNAL_SIGNAL_VERIFICATION_QUEUE_FILE)
    context_verification_requests = _read_jsonl(EXTERNAL_CONTEXT_VERIFICATION_QUEUE_FILE)
    validation_results = _read_jsonl(EXTERNAL_SIGNAL_VERIFICATION_RESULT_FILE)
    latest_validation_by_key: dict[str, dict[str, object]] = {}
    for validation in validation_results:
        dedupe_key = str(validation.get("dedupe_key") or "")
        if dedupe_key:
            latest_validation_by_key[dedupe_key] = validation
    all_verification_requests = [
        {**request, **latest_validation_by_key.get(str(request.get("dedupe_key") or ""), {})}
        for request in raw_verification_requests
    ]
    verification_requests = all_verification_requests[-20:]
    report = latest.get("report") if isinstance(latest.get("report"), dict) else {}
    report_signature = str(latest.get("report_signature", "") or "")
    status_counts: dict[str, int] = {}
    for request in all_verification_requests:
        status = str(request.get("status", "UNKNOWN") or "UNKNOWN").upper()
        status_counts[status] = status_counts.get(status, 0) + 1
    pending_requests = [
        request
        for request in all_verification_requests
        if "PENDING" in str(request.get("status", "") or "").upper()
    ]
    current_report_pending = [
        request for request in pending_requests if str(request.get("report_signature", "") or "") == report_signature
    ]
    stage2_passed = [
        request
        for request in all_verification_requests
        if str(request.get("status", "") or "").upper() in {"STAGE2_PASSED", "VERIFIED_STAGE2", "ACCEPTED_FOR_STAGE2_PROMOTION"}
    ]
    snapshot_verified = [
        request
        for request in all_verification_requests
        if str(request.get("status", "") or "").upper() == "SNAPSHOT_VERIFIED_PENDING_STAGE2_RESULT"
    ]
    snapshot_blocked = [
        request
        for request in all_verification_requests
        if str(request.get("status", "") or "").upper() == "SNAPSHOT_BLOCKED"
    ]
    audited_requests = [
        {**request, "promotion_audit": _external_signal_promotion_audit(request)}
        for request in all_verification_requests
    ]
    promotion_eligible = [
        request for request in audited_requests if bool((request.get("promotion_audit") or {}).get("eligible"))
    ]
    unsafe_stored_promotion_flags = [
        request
        for request in audited_requests
        if bool(request.get("promotion_allowed")) and not bool((request.get("promotion_audit") or {}).get("eligible"))
    ]
    context_coverage = (
        report.get("context_coverage")
        if isinstance(report.get("context_coverage"), dict)
        else _external_signal_context_coverage(report.get("market_context", []))
    )
    report_freshness = _external_signal_report_freshness(report.get("generated_at"))
    stage2_handoff = build_external_signal_stage2_queue(limit=20)
    promotion_eligible_symbols = sorted(
        {
            str(request.get("symbol") or "").strip().upper()
            for request in promotion_eligible
            if str(request.get("symbol") or "").strip()
        }
    )
    result: dict[str, object] = {
        "schema": "codexstock_external_signal_inbox_status_v1",
        "ready": True,
        "has_report": bool(report),
        "status": latest.get("status", "EMPTY"),
        "received_at": latest.get("received_at", ""),
        "source": latest.get("source", ""),
        "report_signature": report_signature,
        "report_freshness": report_freshness,
        "summary": report.get("summary", {}),
        "context_coverage": context_coverage,
        "stage2_snapshot": stage2_snapshot,
        "safety": {
            "decision_scope": "information_only",
            "external_engine_decision": "VERIFY_ONLY",
            "live_order_allowed": False,
            "promotion_allowed": False,
            "requires_codexstock_validation": True,
        },
        "receiver": {
            "path": "/api/external-signal/report",
            "max_bytes": EXTERNAL_SIGNAL_MAX_BYTES,
            "auth_mode": "loopback_and_key" if _external_signal_expected_key() else "loopback_only",
        },
        "recent_receipts": list(reversed(receipts)),
        "verification_queue": {
            "recent_count": len(verification_requests),
            "total_count": len(all_verification_requests),
            "pending_count": len(pending_requests),
            "current_report_pending_count": len(current_report_pending),
            "historical_pending_count": max(0, len(pending_requests) - len(current_report_pending)),
            "stage2_passed_count": len(stage2_passed),
            "snapshot_verified_count": len(snapshot_verified),
            "snapshot_blocked_count": len(snapshot_blocked),
            "snapshot_validation_result_count": len(validation_results),
            "promotion_eligible_count": len(promotion_eligible),
            "promotion_eligible_symbols": promotion_eligible_symbols,
            "unsafe_stored_promotion_flag_count": len(unsafe_stored_promotion_flags),
            "status_counts": status_counts,
            "state": "WAITING_STAGE2_RESULTS" if pending_requests else "NO_PENDING_VERIFICATION",
            "snapshot_ready_is_not_validation_passed": True,
            "recent_requests": list(reversed(audited_requests[-20:])),
            "action": "VERIFY_ONLY",
            "live_order_allowed": False,
            "promotion_allowed": bool(promotion_eligible),
        },
        "stage2_handoff": stage2_handoff,
        "context_verification_queue": {
            "total_count": len(context_verification_requests),
            "pending_count": len(
                [
                    row
                    for row in context_verification_requests
                    if str(row.get("status") or "").startswith("PENDING_")
                ]
            ),
            "current_report_pending_count": len(
                [
                    row
                    for row in context_verification_requests
                    if str(row.get("report_signature") or "") == report_signature
                    and str(row.get("status") or "").startswith("PENDING_")
                ]
            ),
            "recent_requests": list(reversed(context_verification_requests[-20:])),
            "score_allowed": False,
            "live_order_allowed": False,
        },
    }
    poller = globals().get("EXTERNAL_SIGNAL_FILE_POLLER")
    if poller is not None:
        result["file_poller"] = poller.status()
        source_integrity = _external_signal_source_integrity(poller)
        result["source_integrity"] = source_integrity
        source_usable = bool(source_integrity.get("usable") and report_freshness.get("fresh"))
        result["source_integrity_usable"] = bool(source_integrity.get("usable"))
        result["current_source_usable"] = source_usable
        result["verification_queue"]["current_source_usable"] = source_usable
        result["verification_queue"]["report_fresh"] = bool(report_freshness.get("fresh"))
        result["verification_queue"]["unverified_score_influence_count"] = 0
        result["verification_queue"]["unverified_order_influence_count"] = 0
    else:
        result["current_source_usable"] = False
    if include_report and report:
        result["report"] = report
    return result


def _external_signal_request_authorized(handler: SimpleHTTPRequestHandler) -> tuple[bool, str]:
    client_host = str(handler.client_address[0] if handler.client_address else "")
    if client_host not in {"127.0.0.1", "::1"}:
        return False, "loopback_only"
    expected = _external_signal_expected_key()
    if not expected:
        return True, "loopback_only"
    supplied = str(handler.headers.get("X-Control-Plane-Key", "") or "").strip()
    if not supplied:
        authorization = str(handler.headers.get("Authorization", "") or "").strip()
        if authorization.lower().startswith("bearer "):
            supplied = authorization[7:].strip()
    if not supplied or not hmac.compare_digest(supplied, expected):
        return False, "invalid_control_plane_key"
    return True, "loopback_and_key"


class ExternalSignalFilePoller(ExternalSignalFilePollerCore):
    """App-wired compatibility facade for the isolated file poller."""

    def __init__(self) -> None:
        super().__init__(
            state_path=EXTERNAL_SIGNAL_POLLER_STATE_FILE,
            outbox_path_provider=self._configured_outbox_path,
            manifest_binder=_external_signal_manifest_binding,
            report_receiver=receive_external_signal_report,
            text_formatter=_external_signal_text,
            max_bytes=EXTERNAL_SIGNAL_MAX_BYTES,
            stale_minutes=EXTERNAL_SIGNAL_SOURCE_STALE_MINUTES,
        )

    @staticmethod
    def _configured_outbox_path() -> Path:
        configured = str(os.getenv("CODEXSTOCK_EXTERNAL_SIGNAL_OUTBOX", "") or "").strip()
        return Path(configured) if configured else Path(r"C:\\external-search-mcp\\codexstock_outbox")


def _external_signal_source_integrity(poller: ExternalSignalFilePoller) -> dict[str, object]:
    return audit_external_signal_source_integrity(
        poller,
        manifest_binder=_external_signal_manifest_binding,
        report_normalizer=_normalize_external_signal_report,
        text_formatter=_external_signal_text,
        max_bytes=EXTERNAL_SIGNAL_MAX_BYTES,
        stale_minutes=EXTERNAL_SIGNAL_SOURCE_STALE_MINUTES,
    )


EXTERNAL_SIGNAL_FILE_POLLER = ExternalSignalFilePoller()


RESEARCH_FORGE_STORAGE_STATUS_CACHE: dict[str, object] = {
    "saved_at": 0.0,
    "scope": "",
    "payload": {},
}


def _research_forge_storage_status(ttl_seconds: int = 900) -> dict[str, object]:
    scope = str((USER_DATA_ROOT / "research_forge").resolve())
    cached = load_probe_cache(
        RESEARCH_FORGE_STORAGE_STATUS_CACHE,
        RESEARCH_FORGE_STORAGE_STATUS_CACHE_FILE,
        schema_version="research-forge-storage-status-cache.v1",
        scope=scope,
        ttl_seconds=ttl_seconds,
    )
    if cached is not None:
        return cached
    storage_root = USER_DATA_ROOT / "research_forge" / "analytical_storage"
    archive_root = USER_DATA_ROOT / "research_forge" / "microstructure_archive"
    storage_error = ""
    archive_error = ""
    try:
        storage = RESEARCH_FORGE.storage().summary()
    except Exception as exc:
        parquet_files = list((storage_root / "parquet").rglob("*.parquet")) if (storage_root / "parquet").exists() else []
        storage = {
            "ok": False,
            "status": "duckdb_summary_unavailable",
            "fallback_file_inventory": True,
            "row_count": len(parquet_files),
            "symbol_count": 0,
            "parquet_files": len(parquet_files),
            "database_bytes": (storage_root / "research_forge.duckdb").stat().st_size
            if (storage_root / "research_forge.duckdb").is_file()
            else 0,
        }
        storage_error = f"{type(exc).__name__}: {exc}"
    try:
        archive = RESEARCH_FORGE.microstructure_archive().status()
    except Exception as exc:
        chunks = list(archive_root.rglob("*.parquet")) if archive_root.exists() else []
        archive = {
            "ok": False,
            "status": "archive_summary_unavailable",
            "fallback_file_inventory": True,
            "chunk_count": len(chunks),
            "row_count": len(chunks),
        }
        archive_error = f"{type(exc).__name__}: {exc}"
    payload = {
        "storage": storage,
        "archive": archive,
        "storage_error": storage_error,
        "archive_error": archive_error,
        "cached": False,
    }
    save_probe_cache(
        RESEARCH_FORGE_STORAGE_STATUS_CACHE,
        RESEARCH_FORGE_STORAGE_STATUS_CACHE_FILE,
        payload,
        schema_version="research-forge-storage-status-cache.v1",
        scope=scope,
    )
    return payload


def _build_research_forge_status_uncached(include_readiness: bool = False) -> dict[str, object]:
    """Lightweight CodexStock-facing health contract for the Research Forge sub-engine."""
    try:
        status = RESEARCH_FORGE.status()
        doctor_error = ""
        jobs_error = ""
        try:
            doctor = RESEARCH_FORGE.doctor()
        except Exception as exc:
            doctor = {
                "ok": True,
                "status": "storage_doctor_fallback",
                "fallback_file_inventory": True,
                "warning": "Analytical storage doctor is unavailable, but the engine process is connected.",
            }
            doctor_error = f"{type(exc).__name__}: {exc}"
        try:
            jobs = RESEARCH_FORGE.jobs().status(limit=10)
        except Exception as exc:
            jobs = {"status_counts": {}, "items": [], "fallback": True}
            jobs_error = f"{type(exc).__name__}: {exc}"
        storage_status = _research_forge_storage_status()
        storage = storage_status.get("storage") if isinstance(storage_status.get("storage"), dict) else {}
        archive = storage_status.get("archive") if isinstance(storage_status.get("archive"), dict) else {}
        counts = jobs.get("status_counts") if isinstance(jobs.get("status_counts"), dict) else {}
        active_jobs = int(counts.get("QUEUED", 0) or 0) + int(counts.get("RUNNING", 0) or 0)
        analytical_row_count = int(storage.get("row_count", 0) or 0)
        storage_fallback = bool(storage.get("fallback_file_inventory"))
        payload: dict[str, object] = {
            "ok": bool(status.get("ok") and doctor.get("ok") and analytical_row_count > 0),
            "schema": "codexstock_research_forge_status_v1",
            "engine": status.get("engine"),
            "version": status.get("version"),
            "connected": True,
            "mode": "research-only",
            "live_order_allowed": False,
            "max_concurrent_heavy_jobs": 1,
            "active_job_count": active_jobs,
            "experiment_count": int(status.get("experiment_count", 0) or 0),
            "analytical_row_count": analytical_row_count,
            "archive_chunk_count": int(archive.get("chunk_count", 0) or 0),
            "archive_row_count": int(archive.get("row_count", 0) or 0),
            "storage_summary_mode": "file_inventory_fallback" if storage_fallback else "duckdb",
            "storage_degraded": storage_fallback,
            "storage_error": storage_status.get("storage_error", ""),
            "archive_error": storage_status.get("archive_error", ""),
            "doctor_error": doctor_error,
            "jobs_error": jobs_error,
            "storage_cache": {
                "cached": bool(storage_status.get("cached")),
                "source": storage_status.get("cache_source", "computed"),
                "age_seconds": storage_status.get("cache_age_seconds", 0),
                "ttl_seconds": 900,
            },
            "doctor": doctor,
            "jobs": jobs,
            "data_root": str(USER_DATA_ROOT / "research_forge"),
            "migration": RESEARCH_FORGE_MIGRATION,
            "safety": "연구·검증 결과만 코덱스스톡에 전달하며 실전 주문 권한은 없습니다.",
            "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        }
        if include_readiness:
            integration_status = INTEGRATIONS.status()
            kis = integration_status.get("kis") if isinstance(integration_status.get("kis"), dict) else {}
            import importlib.util
            payload["readiness"] = RESEARCH_FORGE.readiness({
                "kis_configured": bool(kis.get("configured")),
                "websocket_available": importlib.util.find_spec("websocket") is not None,
            })
        return payload
    except Exception as exc:
        return {
            "ok": False,
            "schema": "codexstock_research_forge_status_v1",
            "connected": False,
            "live_order_allowed": False,
            "error": {"type": type(exc).__name__, "message": str(exc)},
            "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
        }


RESEARCH_FORGE_STATUS_CACHE = StaleWhileRefreshStatusCache(
    builder=lambda: _build_research_forge_status_uncached(include_readiness=False),
    cache_path=RESEARCH_FORGE_STATUS_CACHE_FILE,
    schema_version="research-forge-status-cache.v1",
    ttl_seconds=15,
)


def build_research_forge_status(include_readiness: bool = False) -> dict[str, object]:
    if include_readiness or _INSTANCE_LOCK_BYPASS_ALLOWED:
        return _build_research_forge_status_uncached(include_readiness=include_readiness)
    payload = RESEARCH_FORGE_STATUS_CACHE.get()
    error = payload.get("error") if isinstance(payload.get("error"), dict) else {}
    error_message = str(error.get("message") or "")
    if not payload.get("ok") and "DuckDB storage extra is required" in error_message:
        fresh = _build_research_forge_status_uncached(include_readiness=False)
        fresh["cache_bypassed_reason"] = "duckdb_storage_fallback_refresh"
        return fresh
    return payload


def build_research_forge_integration_audit() -> dict[str, object]:
    """Verify that Research Forge is consumed by CodexStock, not merely installed."""
    status = build_research_forge_status(include_readiness=False)
    doctor = status.get("doctor") if isinstance(status.get("doctor"), dict) else {}
    doctor_checks = {
        str(row.get("id") or ""): row.get("ok") is True
        for row in doctor.get("checks", [])
        if isinstance(row, dict) and str(row.get("id") or "")
    }
    manifest = RESEARCH_FORGE.manifest()
    manifest_tools = {str(value) for value in manifest.get("tools", []) if str(value)}
    gateway_tools = {str(value) for value in RESEARCH_TOOL_NAMES if str(value)}
    mcp_tools: set[str] = set()
    mcp_import_error = ""
    try:
        from codexstock_mcp_server import TOOLS as mcp_tool_rows

        mcp_tools = {
            str(row.get("name") or "")
            for row in mcp_tool_rows
            if isinstance(row, dict) and str(row.get("name") or "")
        }
    except Exception as exc:
        mcp_import_error = f"{type(exc).__name__}: {exc}"[:500]

    indicator_catalog = build_ai_staff_indicator_catalog()
    promotion = _research_forge_candidate_discovery_audit()
    corporate_actions = RESEARCH_FORGE.corporate_actions().status()
    universe = RESEARCH_FORGE.universe().status()
    stability = EngineStabilityLedger(EXTERNAL_ENGINE_STABILITY_LEDGER_FILE).audit(
        window_days=30,
        max_gap_seconds=900,
    )
    expected_root = (USER_DATA_ROOT / "research_forge").resolve()
    actual_root = RESEARCH_FORGE.registry.root.parent.resolve()
    critical_tools = {
        "research_corporate_action_reconcile",
        "research_realtime_resume",
        "research_instrument_contracts",
        "research_instrument_validate",
        "research_shard_batch_create",
        "research_shard_status",
        "research_stability_record",
        "research_stability_audit",
    }
    capability_contracts = [
        {
            "id": "corporate_action_history",
            "recognized": doctor_checks.get("corporate_action_registry") is True
            and "research_corporate_action_reconcile" in gateway_tools,
            "consumed_by": ["full_spec_readiness", "adjusted_price_provenance"],
            "evidence_status": "verified" if int(corporate_actions.get("complete_dataset_count") or 0) > 0 else "collecting_evidence",
        },
        {
            "id": "point_in_time_universe",
            "recognized": doctor_checks.get("universe_store") is True
            and "research_universe_validate" in gateway_tools,
            "consumed_by": ["experiment_validation", "paper_candidate_gate"],
            "evidence_status": "available" if int(universe.get("dataset_count") or 0) > 0 else "collecting_evidence",
        },
        {
            "id": "instrument_contracts",
            "recognized": doctor_checks.get("instrument_contracts") is True
            and {"research_instrument_contracts", "research_instrument_validate"}.issubset(gateway_tools),
            "consumed_by": ["experiment_creation", "backtest_preflight", "paper_nomination_gate"],
            "evidence_status": "enforced",
        },
        {
            "id": "realtime_resume",
            "recognized": "research_realtime_resume" in gateway_tools,
            "consumed_by": ["realtime_collection", "full_session_readiness"],
            "evidence_status": "available",
        },
        {
            "id": "distributed_research",
            "recognized": doctor_checks.get("distributed_shard_store") is True
            and {"research_shard_batch_create", "research_shard_status"}.issubset(gateway_tools),
            "consumed_by": ["bounded_heavy_research"],
            "evidence_status": "available",
        },
        {
            "id": "long_term_stability",
            "recognized": doctor_checks.get("engine_stability_ledger") is True
            and {"research_stability_record", "research_stability_audit"}.issubset(gateway_tools),
            "consumed_by": ["external_engine_dashboard", "feature_health"],
            "evidence_status": str(stability.get("status") or "collecting_evidence"),
        },
        {
            "id": "ai_staff_indicators",
            "recognized": indicator_catalog.get("all_staff_can_read") is True
            and int(indicator_catalog.get("research_forge_supported_count") or 0) > 0,
            "consumed_by": ["all_ai_staff", "strategy_research"],
            "evidence_status": "available",
        },
        {
            "id": "paper_candidate_handoff",
            "recognized": promotion.get("contract_ready") is True
            and promotion.get("scheduler_hook") == "run_due_promotion_paper_rehearsal"
            and promotion.get("paper_only") is True
            and promotion.get("live_order_allowed") is False,
            "consumed_by": ["post_market_scheduler", "paper_rehearsal", "forward_observation"],
            "evidence_status": "ready" if int(promotion.get("scheduler_eligible_candidate_count") or 0) > 0 else "waiting_for_verified_candidate",
        },
    ]
    checks = [
        {
            "id": "engine_connected",
            "ok": status.get("ok") is True and status.get("connected") is True,
            "detail": str(status.get("version") or ""),
        },
        {
            "id": "single_runtime_root",
            "ok": actual_root == expected_root,
            "detail": str(actual_root),
        },
        {
            "id": "gateway_manifest_sync",
            "ok": gateway_tools == manifest_tools and critical_tools.issubset(gateway_tools),
            "detail": f"gateway={len(gateway_tools)} manifest={len(manifest_tools)}",
        },
        {
            "id": "mcp_surface_sync",
            "ok": not mcp_import_error and gateway_tools.issubset(mcp_tools),
            "detail": mcp_import_error or f"research_tools={len(gateway_tools)} exposed={len(gateway_tools & mcp_tools)}",
        },
        {
            "id": "capability_consumers_registered",
            "ok": all(row.get("recognized") is True and row.get("consumed_by") for row in capability_contracts),
            "detail": f"recognized={sum(row.get('recognized') is True for row in capability_contracts)}/{len(capability_contracts)}",
        },
        {
            "id": "research_only_boundary",
            "ok": status.get("live_order_allowed") is False
            and promotion.get("live_order_allowed") is False,
            "detail": "Research Forge cannot submit live orders.",
        },
    ]
    blockers = [str(row["id"]) for row in checks if row.get("ok") is not True]
    pending_evidence = [
        str(row["id"])
        for row in capability_contracts
        if str(row.get("evidence_status") or "") in {"collecting_evidence", "waiting_for_verified_candidate"}
    ]
    return {
        "ok": not blockers,
        "schema": "codexstock_research_forge_integration_audit_v1",
        "status": "integrated" if not blockers else "partial",
        "recognized_capability_count": sum(row.get("recognized") is True for row in capability_contracts),
        "capability_count": len(capability_contracts),
        "gateway_tool_count": len(gateway_tools),
        "manifest_tool_count": len(manifest_tools),
        "mcp_exposed_research_tool_count": len(gateway_tools & mcp_tools),
        "indicator_count_available_to_staff": int(indicator_catalog.get("research_forge_supported_count") or 0),
        "runtime_root": str(actual_root),
        "checks": checks,
        "capabilities": capability_contracts,
        "blockers": blockers,
        "evidence_pending": pending_evidence,
        "evidence_pending_is_not_integration_failure": True,
        "paper_only": True,
        "live_order_allowed": False,
        "generated_at": datetime.now(ZoneInfo("Asia/Seoul")).isoformat(timespec="seconds"),
    }


